-- 和合本全文数据（文件序号见文件名 bible_cuv_data_NN.sql）。先运行 bible_cuv_schema.sql 建表，再按序号依次运行各数据文件。可重复运行（冲突自动跳过）。
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 1, 1, '起初，神创造天地。'),
('CUV', '创世纪', 1, 1, 2, '地是空虚混沌，渊面黑暗；神的灵运行在水面上。'),
('CUV', '创世纪', 1, 1, 3, '神说：要有光，就有了光。'),
('CUV', '创世纪', 1, 1, 4, '神看光是好的，就把光暗分开了。'),
('CUV', '创世纪', 1, 1, 5, '神称光为昼，称暗为夜。有晚上，有早晨，这是头一日。'),
('CUV', '创世纪', 1, 1, 6, '神说：诸水之间要有空气，将水分为上下。'),
('CUV', '创世纪', 1, 1, 7, '神就造出空气，将空气以下的水、空气以上的水分开了。事就这样成了。'),
('CUV', '创世纪', 1, 1, 8, '神称空气为天。有晚上，有早晨，是第二日。'),
('CUV', '创世纪', 1, 1, 9, '神说：天下的水要聚在一处，使旱地露出来。事就这样成了。'),
('CUV', '创世纪', 1, 1, 10, '神称旱地为地，称水的聚处为海。神看著是好的。'),
('CUV', '创世纪', 1, 1, 11, '神说：地要发生青草和结种子的菜蔬，并结果子的树木，各从其类，果子都包著核。事就这样成了。'),
('CUV', '创世纪', 1, 1, 12, '于是地发生了青草和结种子的菜蔬，各从其类；并结果子的树木，各从其类；果子都包著核。神看著是好的。'),
('CUV', '创世纪', 1, 1, 13, '有晚上，有早晨，是第三日。'),
('CUV', '创世纪', 1, 1, 14, '神说：天上要有光体，可以分昼夜，作记号，定节令、日子、年岁，'),
('CUV', '创世纪', 1, 1, 15, '并要发光在天空，普照在地上。事就这样成了。'),
('CUV', '创世纪', 1, 1, 16, '于是神造了两个大光，大的管昼，小的管夜，又造众星，'),
('CUV', '创世纪', 1, 1, 17, '就把这些光摆列在天空，普照在地上，'),
('CUV', '创世纪', 1, 1, 18, '管理昼夜，分别明暗。神看著是好的。'),
('CUV', '创世纪', 1, 1, 19, '有晚上，有早晨，是第四日。'),
('CUV', '创世纪', 1, 1, 20, '神说：水要多多滋生有生命的物；要有雀鸟飞在地面以上，天空之中。'),
('CUV', '创世纪', 1, 1, 21, '神就造出大鱼和水中所滋生各样有生命的动物，各从其类；又造出各样飞鸟，各从其类。神看著是好的。'),
('CUV', '创世纪', 1, 1, 22, '神就赐福给这一切，说：滋生繁多，充满海中的水；雀鸟也要多生在地上。'),
('CUV', '创世纪', 1, 1, 23, '有晚上，有早晨，是第五日。'),
('CUV', '创世纪', 1, 1, 24, '神说：地要生出活物来，各从其类；牲畜、昆虫、地上的野兽，各从其类。事就这样成了。'),
('CUV', '创世纪', 1, 1, 25, '于是神造出野兽，各从其类；牲畜，各从其类；地上一切昆虫，各从其类。神看著是好的。'),
('CUV', '创世纪', 1, 1, 26, '神说：我们要照著我们的形像、按著我们的样式造人，使他们管理海里的鱼、空中的鸟、地上的牲畜，和全地，并地上所爬的一切昆虫。'),
('CUV', '创世纪', 1, 1, 27, '神就照著自己的形像造人，乃是照著他的形像造男造女。'),
('CUV', '创世纪', 1, 1, 28, '神就赐福给他们，又对他们说：要生养众多，遍满地面，治理这地，也要管理海里的鱼、空中的鸟，和地上各样行动的活物。'),
('CUV', '创世纪', 1, 1, 29, '神说：看哪，我将遍地上一切结种子的菜蔬和一切树上所结有核的果子全赐给你们作食物。'),
('CUV', '创世纪', 1, 1, 30, '至于地上的走兽和空中的飞鸟，并各样爬在地上有生命的物，我将青草赐给他们作食物。事就这样成了。'),
('CUV', '创世纪', 1, 1, 31, '神看著一切所造的都甚好。有晚上，有早晨，是第六日。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 2, 1, '天地万物都造齐了。'),
('CUV', '创世纪', 1, 2, 2, '到第七日，神造物的工已经完毕，就在第七日歇了他一切的工，安息了。'),
('CUV', '创世纪', 1, 2, 3, '神赐福给第七日，定为圣日；因为在这日，神歇了他一切创造的工，就安息了。'),
('CUV', '创世纪', 1, 2, 4, '创造天地的来历，在耶和华神造天地的日子，乃是这样，'),
('CUV', '创世纪', 1, 2, 5, '野地还没有草木，田间的菜蔬还没有长起来；因为耶和华神还没有降雨在地上，也没有人耕地，'),
('CUV', '创世纪', 1, 2, 6, '但有雾气从地上腾，滋润遍地。'),
('CUV', '创世纪', 1, 2, 7, '耶和华神用地上的尘土造人，将生气吹在他鼻孔里，他就成了有灵的活人，名叫亚当。'),
('CUV', '创世纪', 1, 2, 8, '耶和华神在东方的伊甸立了一个园子，把所造的人安置在那里。'),
('CUV', '创世纪', 1, 2, 9, '耶和华神使各样的树从地里长出来，可以悦人的眼目，其上的果子好作食物。园子当中又有生命树和分别善恶的树。'),
('CUV', '创世纪', 1, 2, 10, '有河从伊甸流出来，滋润那园子，从那里分为四道：'),
('CUV', '创世纪', 1, 2, 11, '第一道名叫比逊，就是环绕哈腓拉全地的。在那里有金子，'),
('CUV', '创世纪', 1, 2, 12, '并且那地的金子是好的；在那里又有珍珠和红玛瑙。'),
('CUV', '创世纪', 1, 2, 13, '第二道河名叫基训，就是环绕古实全地的。'),
('CUV', '创世纪', 1, 2, 14, '第三道河名叫底格里斯，流在亚述的东边。第四道河就是伯拉河。'),
('CUV', '创世纪', 1, 2, 15, '耶和华神将那人安置在伊甸园，使他修理，看守。'),
('CUV', '创世纪', 1, 2, 16, '耶和华神吩咐他说：园中各样树上的果子，你可以随意吃，'),
('CUV', '创世纪', 1, 2, 17, '只是分别善恶树上的果子，你不可吃，因为你吃的日子必定死！'),
('CUV', '创世纪', 1, 2, 18, '耶和华神说：那人独居不好，我要为他造一个配偶帮助他。'),
('CUV', '创世纪', 1, 2, 19, '耶和华神用土所造成的野地各样走兽和空中各样飞鸟都带到那人面前，看他叫甚么。那人怎样叫各样的活物，那就是他的名字。'),
('CUV', '创世纪', 1, 2, 20, '那人便给一切牲畜和空中飞鸟、野地走兽都起了名；只是那人没有遇见配偶帮助他。'),
('CUV', '创世纪', 1, 2, 21, '耶和华神使他沉睡，他就睡了；于是取下他的一条肋骨，又把肉合起来。'),
('CUV', '创世纪', 1, 2, 22, '耶和华神就用那人身上所取的肋骨造成一个女人，领他到那人跟前。'),
('CUV', '创世纪', 1, 2, 23, '那人说：这是我骨中的骨，肉中的肉，可以称他为女人，因为他是从男人身上取出来的。'),
('CUV', '创世纪', 1, 2, 24, '因此，人要离开父母，与妻子连合，二人成为一体。'),
('CUV', '创世纪', 1, 2, 25, '当时夫妻二人赤身露体，并不羞耻。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 3, 1, '耶和华神所造的，惟有蛇比田野一切的活物更狡猾。蛇对女人说：神岂是真说不许你们吃园中所有树上的果子么？'),
('CUV', '创世纪', 1, 3, 2, '女人对蛇说：园中树上的果子，我们可以吃，'),
('CUV', '创世纪', 1, 3, 3, '惟有园当中那棵树上的果子，神曾说：你们不可吃，也不可摸，免得你们死。'),
('CUV', '创世纪', 1, 3, 4, '蛇对女人说：你们不一定死；'),
('CUV', '创世纪', 1, 3, 5, '因为神知道，你们吃的日子眼睛就明亮了，你们便如神能知道善恶。'),
('CUV', '创世纪', 1, 3, 6, '于是女人见那棵树的果子好作食物，也悦人的眼目，且是可喜爱的，能使人有智慧，就摘下果子来吃了，又给他丈夫，他丈夫也吃了。'),
('CUV', '创世纪', 1, 3, 7, '他们二人的眼睛就明亮了，才知道自己是赤身露体，便拿无花果树的叶子为自己编作裙子。'),
('CUV', '创世纪', 1, 3, 8, '天起了凉风，耶和华神在园中行走。那人和他妻子听见神的声音，就藏在园里的树木中，躲避耶和华神的面。'),
('CUV', '创世纪', 1, 3, 9, '耶和华神呼唤那人，对他说：你在那里？'),
('CUV', '创世纪', 1, 3, 10, '他说：我在园中听见你的声音，我就害怕；因为我赤身露体，我便藏了。'),
('CUV', '创世纪', 1, 3, 11, '耶和华说：谁告诉你赤身露体呢？莫非你吃了我吩咐你不可吃的那树上的果子吗？'),
('CUV', '创世纪', 1, 3, 12, '那人说：你所赐给我与我同居的女人，他把那树上的果子给我，我就吃了。'),
('CUV', '创世纪', 1, 3, 13, '耶和华神对女人说：你作的是甚么事呢？女人说：那蛇引诱我，我就吃了。'),
('CUV', '创世纪', 1, 3, 14, '耶和华神对蛇说：你既作了这事，就必受咒诅，比一切的牲畜野兽更甚。你必用肚子行走，终身吃土。'),
('CUV', '创世纪', 1, 3, 15, '我又要叫你和女人彼此为仇；你的后裔和女人的后裔也彼此为仇。女人的后裔要伤你的头；你要伤他的脚跟。'),
('CUV', '创世纪', 1, 3, 16, '又对女人说：我必多多加增你怀胎的苦楚；你生产儿女必多受苦楚。你必恋慕你丈夫；你丈夫必管辖你。'),
('CUV', '创世纪', 1, 3, 17, '又对亚当说：你既听从妻子的话，吃了我所吩咐你不可吃的那树上的果子，地必为你的缘故受咒诅；你必终身劳苦才能从地里得吃的。'),
('CUV', '创世纪', 1, 3, 18, '地必给你长出荆棘和蒺藜来；你也要吃田间的菜蔬。'),
('CUV', '创世纪', 1, 3, 19, '你必汗流满面才得糊口，直到你归了土，因为你是从土而出的。你本是尘土，仍要归于尘土。'),
('CUV', '创世纪', 1, 3, 20, '亚当给他妻子起名叫夏娃，因为他是众生之母。'),
('CUV', '创世纪', 1, 3, 21, '耶和华神为亚当和他妻子用皮子作衣服给他们穿。'),
('CUV', '创世纪', 1, 3, 22, '耶和华神说：那人已经与我们相似，能知道善恶；现在恐怕他伸手又摘生命树的果子吃，就永远活著。'),
('CUV', '创世纪', 1, 3, 23, '耶和华神便打发他出伊甸园去，耕种他所自出之土。'),
('CUV', '创世纪', 1, 3, 24, '于是把他赶出去了；又在伊甸园的东边安设基路伯和四面转动发火燄的剑，要把守生命树的道路。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 4, 1, '有一日，那人和他妻子夏娃同房，夏娃就怀孕，生了该隐(就是得的意思)，便说：耶和华使我得了一个男子。'),
('CUV', '创世纪', 1, 4, 2, '又生了该隐的兄弟亚伯。亚伯是牧羊的；该隐是种地的。'),
('CUV', '创世纪', 1, 4, 3, '有一日，该隐拿地里的出产为供物献给耶和华'),
('CUV', '创世纪', 1, 4, 4, '亚伯也将他羊群中头生的和羊的脂油献上。耶和华看中了亚伯和他的供物，'),
('CUV', '创世纪', 1, 4, 5, '只是看不中该隐和他的供物。该隐就大大的发怒，变了脸色。'),
('CUV', '创世纪', 1, 4, 6, '耶和华对该隐说：你为甚么发怒呢？你为甚么变了脸色呢？'),
('CUV', '创世纪', 1, 4, 7, '你若行得好，岂不蒙悦纳？你若行得不好，罪就伏在门前。他必恋慕你，你却要制伏他。'),
('CUV', '创世纪', 1, 4, 8, '该隐与他兄弟亚伯说话；二人正在田间。该隐起来打他兄弟亚伯，把他杀了。'),
('CUV', '创世纪', 1, 4, 9, '耶和华对该隐说：你兄弟亚伯在那里？他说：我不知道！我岂是看守我兄弟的么？'),
('CUV', '创世纪', 1, 4, 10, '耶和华说：你作了甚么事呢？你兄弟的血有声音从地里向我哀告。'),
('CUV', '创世纪', 1, 4, 11, '地开了口，从你手里接受你兄弟的血。现在你必从这地受咒诅。'),
('CUV', '创世纪', 1, 4, 12, '你种地，地不再给你效力；你必流离飘荡在地上。'),
('CUV', '创世纪', 1, 4, 13, '该隐对耶和华说：我的刑罚太重，过于我所能当的。'),
('CUV', '创世纪', 1, 4, 14, '你如今赶逐我离开这地，以致不见你面；我必流离飘荡在地上，凡遇见我的必杀我。'),
('CUV', '创世纪', 1, 4, 15, '耶和华对他说：凡杀该隐的，必遭报七倍。耶和华就给该隐立一个记号，免得人遇见他就杀他。'),
('CUV', '创世纪', 1, 4, 16, '于是该隐离开耶和华的面，去住在伊甸东边挪得之地。'),
('CUV', '创世纪', 1, 4, 17, '该隐与妻子同房，他妻子就怀孕，生了以诺。该隐建造了一座城，就按著他儿子的名将那城叫作以诺。'),
('CUV', '创世纪', 1, 4, 18, '以诺生以拿；以拿生米户雅利；米户雅利生玛土撒利；玛土撒利生拉麦。'),
('CUV', '创世纪', 1, 4, 19, '拉麦娶了两个妻：一个名叫亚大，一个名叫洗拉。'),
('CUV', '创世纪', 1, 4, 20, '亚大生雅八；雅八就是住帐棚、牧养牲畜之人的祖师。'),
('CUV', '创世纪', 1, 4, 21, '雅八的兄弟名叫犹八；他是一切弹琴吹箫之人的祖师。'),
('CUV', '创世纪', 1, 4, 22, '洗拉又生了土八该隐；他是打造各样铜铁利器的(或作：是铜匠铁匠的祖师)。土八该隐的妹子是拿玛。'),
('CUV', '创世纪', 1, 4, 23, '拉麦对他两个妻子说：亚大、洗拉，听我的声音；拉麦的妻子，细听我的话语：壮年人伤我，我把他杀了；少年人损我，我把他害了(或作我杀壮士却伤自己，我害幼童却损本身。)'),
('CUV', '创世纪', 1, 4, 24, '若杀该隐，遭报七倍，杀拉麦，必遭报七十七倍。'),
('CUV', '创世纪', 1, 4, 25, '亚当又与妻子同房，他就生了一个儿子，起名叫塞特，意思说：神另给我立了一个儿子代替亚伯，因为该隐杀了他。'),
('CUV', '创世纪', 1, 4, 26, '塞特也生了一个儿子，起名叫以挪士。那时候，人才求告耶和华的名。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 5, 1, '亚当的后代记在下面。〈当神造人的日子，是照著自己的样式造的，'),
('CUV', '创世纪', 1, 5, 2, '并且造男造女。在他们被造的日子，神赐福给他们，称他们为人。〉'),
('CUV', '创世纪', 1, 5, 3, '亚当活到一百三十岁，生了一个儿子，形像样式和自己相似，就给他起名叫塞特。'),
('CUV', '创世纪', 1, 5, 4, '亚当生塞特之后，又在世八百年，并且生儿养女。'),
('CUV', '创世纪', 1, 5, 5, '亚当共活了九百三十岁就死了。'),
('CUV', '创世纪', 1, 5, 6, '塞特活到一百零五岁，生了以挪士。'),
('CUV', '创世纪', 1, 5, 7, '塞特生以挪士之后，又活了八百零七年，并且生儿养女。'),
('CUV', '创世纪', 1, 5, 8, '塞特共活了九百一十二岁就死了。'),
('CUV', '创世纪', 1, 5, 9, '以挪士活到九十岁，生了该南。'),
('CUV', '创世纪', 1, 5, 10, '以挪士生该南之后，又活了八百一十五年，并且生儿养女。'),
('CUV', '创世纪', 1, 5, 11, '以挪士共活了九百零五岁就死了。'),
('CUV', '创世纪', 1, 5, 12, '该南活到七十岁，生了玛勒列。'),
('CUV', '创世纪', 1, 5, 13, '该南生玛勒列之后，又活了八百四十年，并且生儿养女。'),
('CUV', '创世纪', 1, 5, 14, '该南共活了九百一十岁就死了。'),
('CUV', '创世纪', 1, 5, 15, '玛勒列活到六十五岁，生了雅列。'),
('CUV', '创世纪', 1, 5, 16, '玛勒列生雅列之后，又活了八百三十年，并且生儿养女。'),
('CUV', '创世纪', 1, 5, 17, '玛勒列共活了八百九十五岁就死了。'),
('CUV', '创世纪', 1, 5, 18, '雅列活到一百六十二岁，生了以诺。'),
('CUV', '创世纪', 1, 5, 19, '雅列生以诺之后，又活了八百年，并且生儿养女。'),
('CUV', '创世纪', 1, 5, 20, '雅列共活了九百六十二岁就死了.。'),
('CUV', '创世纪', 1, 5, 21, '以诺活到六十五岁，生了玛土撒拉。'),
('CUV', '创世纪', 1, 5, 22, '以诺生玛土撒拉之后，与神同行三百年，并且生儿养女。'),
('CUV', '创世纪', 1, 5, 23, '以诺共活了三百六十五岁。'),
('CUV', '创世纪', 1, 5, 24, '以诺与神同行，神将他取去，他就不在世了。'),
('CUV', '创世纪', 1, 5, 25, '玛土撒拉活到一百八十七岁，生了拉麦。'),
('CUV', '创世纪', 1, 5, 26, '玛土撒拉生拉麦之后，又活了七百八十二年，并且生儿养女。'),
('CUV', '创世纪', 1, 5, 27, '玛土撒拉共活了九百六十九岁就死了。'),
('CUV', '创世纪', 1, 5, 28, '拉麦活到一百八十二岁，生了一个儿子，'),
('CUV', '创世纪', 1, 5, 29, '给他起名叫挪亚，说：这个儿子必为我们的操作和手中的劳苦安慰我们；这操作劳苦是因为耶和华咒诅地。'),
('CUV', '创世纪', 1, 5, 30, '拉麦生挪亚之后，又活了五百九十五年，并且生儿养女。'),
('CUV', '创世纪', 1, 5, 31, '拉麦共活了七百七十七岁就死了。'),
('CUV', '创世纪', 1, 5, 32, '挪亚五百岁生了闪、含、雅弗。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 6, 1, '当人在世上多起来又生女儿的时候，'),
('CUV', '创世纪', 1, 6, 2, '神的儿子们看见人的女子美貌，就随意挑选，娶来为妻。'),
('CUV', '创世纪', 1, 6, 3, '耶和华说：人既属乎血气，我的灵就不永远住在他里面；然而他的日子还可到一百二十年。'),
('CUV', '创世纪', 1, 6, 4, '那时候有伟人在地上，后来神的儿子们和人的女子们交合生子；那就是上古英武有名的人。'),
('CUV', '创世纪', 1, 6, 5, '耶和华见人在地上罪恶很大，终日所思想的尽都是恶，'),
('CUV', '创世纪', 1, 6, 6, '耶和华就后悔造人在地上，心中忧伤。'),
('CUV', '创世纪', 1, 6, 7, '耶和华说：我要将所造的人和走兽，并昆虫，以及空中的飞鸟，都从地上除灭，因为我造他们后悔了。'),
('CUV', '创世纪', 1, 6, 8, '惟有挪亚在耶和华眼前蒙恩。'),
('CUV', '创世纪', 1, 6, 9, '挪亚的后代记在下面。挪亚是个义人，在当时的世代是个完全人。挪亚与神同行。'),
('CUV', '创世纪', 1, 6, 10, '挪亚生了三个儿子，就是闪、含、雅弗。'),
('CUV', '创世纪', 1, 6, 11, '世界在神面前败坏，地上满了强暴.。'),
('CUV', '创世纪', 1, 6, 12, '神观看世界，见是败坏了；凡有血气的人在地上.都败坏了行为。'),
('CUV', '创世纪', 1, 6, 13, '神就对挪亚说：凡有血气的人，他的尽头已经来到我面前；因为地上满了他们的强暴，我要把他们和地一并毁灭。'),
('CUV', '创世纪', 1, 6, 14, '你要用歌斐木造一只方舟，分一间一间地造，里外抹上松香。'),
('CUV', '创世纪', 1, 6, 15, '方舟的造法乃是这样：要长三百肘，宽五十肘，高三十肘。'),
('CUV', '创世纪', 1, 6, 16, '方舟上边要留透光处，高一肘。方舟的门要开在旁边。方舟要分上、中、下三层。'),
('CUV', '创世纪', 1, 6, 17, '看哪，我要使洪水泛滥在地上，毁灭天下；凡地上有血肉、有气息的活物，无一不死。'),
('CUV', '创世纪', 1, 6, 18, '我却要与你立约；你同你的妻，与儿子儿妇，都要进入方舟。'),
('CUV', '创世纪', 1, 6, 19, '凡有血肉的活物，每样两个，一公一母，你要带进方舟，好在你那里保全生命。'),
('CUV', '创世纪', 1, 6, 20, '飞鸟各从其类，牲畜各从其类，地上的昆虫各从其类，每样两个，要到你那里，好保全生命。'),
('CUV', '创世纪', 1, 6, 21, '你要拿各样食物积蓄起来，好作你和他们的食物。'),
('CUV', '创世纪', 1, 6, 22, '挪亚就这样行。凡神所吩咐的，他都照样行了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 7, 1, '耶和华对挪亚说：你和你的全家都要进入方舟；因为在这世代中，我见你在我面前是义人。'),
('CUV', '创世纪', 1, 7, 2, '凡洁净的畜类，你要带七公七母；不洁净的畜类，你要带一公一母；'),
('CUV', '创世纪', 1, 7, 3, '空中的飞鸟也要带七公七母，可以留种，活在全地上；'),
('CUV', '创世纪', 1, 7, 4, '因为再过七天，我要降雨在地上四十昼夜，把我所造的各种活物都从地上除灭。'),
('CUV', '创世纪', 1, 7, 5, '挪亚就遵著耶和华所吩咐的行了。'),
('CUV', '创世纪', 1, 7, 6, '当洪水泛滥在地上的时候，挪亚整六百岁。'),
('CUV', '创世纪', 1, 7, 7, '挪亚就同他的妻和儿子儿妇都进入方舟，躲避洪水。'),
('CUV', '创世纪', 1, 7, 8, '洁净的畜类和不洁净的畜类，飞鸟并地上一切的昆虫，'),
('CUV', '创世纪', 1, 7, 9, '都是一对一对的，有公有母，到挪亚那里进入方舟，正如神所吩咐挪亚的。'),
('CUV', '创世纪', 1, 7, 10, '过了那七天，洪水泛滥在地上。'),
('CUV', '创世纪', 1, 7, 11, '当挪亚六百岁，二月十七日那一天，大渊的泉源都裂开了，天上的窗户也敞开了'),
('CUV', '创世纪', 1, 7, 12, '四十昼夜降大雨在地上。'),
('CUV', '创世纪', 1, 7, 13, '正当那日，挪亚和他三个儿子闪、含、雅弗，并挪亚的妻子和三个儿妇，都进入方舟。'),
('CUV', '创世纪', 1, 7, 14, '他们和百兽，各从其类，一切牲畜，各从其类，爬在地上的昆虫，各从其类，一切禽鸟，各从其类，都进入方舟。'),
('CUV', '创世纪', 1, 7, 15, '凡有血肉、有气息的活物，都一对一对地到挪亚那里，进入方舟。'),
('CUV', '创世纪', 1, 7, 16, '凡有血肉进入方舟的，都是有公有母，正如神所吩咐挪亚的。耶和华就把他关在方舟里头。'),
('CUV', '创世纪', 1, 7, 17, '洪水泛滥在地上四十天，水往上长，把方舟从地上漂起。'),
('CUV', '创世纪', 1, 7, 18, '水势浩大，在地上大大地往上长，方舟在水面上漂来漂去。'),
('CUV', '创世纪', 1, 7, 19, '水势在地上极其浩大，天下的高山都淹没了。'),
('CUV', '创世纪', 1, 7, 20, '水势比山高过十五肘，山岭都淹没了。'),
('CUV', '创世纪', 1, 7, 21, '凡在地上有血肉的动物，就是飞鸟、牲畜、走兽，和爬在地上的昆虫，以及所有的人，都死了。'),
('CUV', '创世纪', 1, 7, 22, '凡在旱地上、鼻孔有气息的生灵都死了。'),
('CUV', '创世纪', 1, 7, 23, '凡地上各类的活物，连人带牲畜、昆虫，以及空中的飞鸟，都从地上除灭了，只留下挪亚和那些与他同在方舟里的。'),
('CUV', '创世纪', 1, 7, 24, '水势浩大，在地上共一百五十天。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 8, 1, '神记念挪亚和挪亚方舟里的一切走兽牲畜。神叫风吹地，水势渐落。'),
('CUV', '创世纪', 1, 8, 2, '渊源和天上的窗户都闭塞了，天上的大雨也止住了。'),
('CUV', '创世纪', 1, 8, 3, '水从地上渐退。过了一百五十天，水就渐消。'),
('CUV', '创世纪', 1, 8, 4, '七月十七日，方舟停在亚拉腊山上。'),
('CUV', '创世纪', 1, 8, 5, '水又渐消，到十月初一日，山顶都现出来了。'),
('CUV', '创世纪', 1, 8, 6, '过了四十天，挪亚开了方舟的窗户，'),
('CUV', '创世纪', 1, 8, 7, '放出一只乌鸦去；那乌鸦飞来飞去，直到地上的水都干了。'),
('CUV', '创世纪', 1, 8, 8, '他又放出一只鸽子去，要看看水从地上退了没有。'),
('CUV', '创世纪', 1, 8, 9, '但遍地上都是水，鸽子找不著落脚之地，就回到方舟挪亚那里，挪亚伸手把鸽子接进方舟来。'),
('CUV', '创世纪', 1, 8, 10, '他又等了七天，再把鸽子从方舟放出去。'),
('CUV', '创世纪', 1, 8, 11, '到了晚上，鸽子回到他那里，嘴里叼著一个新拧下来的橄榄叶子，挪亚就知道地上的水退了。'),
('CUV', '创世纪', 1, 8, 12, '他又等了七天，放出鸽子去，鸽子就不再回来了。'),
('CUV', '创世纪', 1, 8, 13, '到挪亚六百零一岁，正月初一日，地上的水都干了。挪亚撤去方舟的盖观看，便见地面上干了。'),
('CUV', '创世纪', 1, 8, 14, '到了二月二十七日，地就都干了。'),
('CUV', '创世纪', 1, 8, 15, '神对挪亚说：'),
('CUV', '创世纪', 1, 8, 16, '你和你的妻子、儿子、儿妇都可以出方舟。'),
('CUV', '创世纪', 1, 8, 17, '在你那里凡有血肉的活物，就是飞鸟、牲畜，和一切爬在地上的昆虫，都要带出来，叫他在地上多多滋生，大大兴旺。'),
('CUV', '创世纪', 1, 8, 18, '于是挪亚和他的妻子、儿子、儿妇都出来了。'),
('CUV', '创世纪', 1, 8, 19, '一切走兽、昆虫、飞鸟，和地上所有的动物，各从其类，也都出了方舟。'),
('CUV', '创世纪', 1, 8, 20, '挪亚为耶和华筑了一座坛，拿各类洁净的牲畜、飞鸟献在坛上为燔祭。'),
('CUV', '创世纪', 1, 8, 21, '耶和华闻那馨香之气，就心里说：我不再因人的缘故咒诅地（人从小时心里怀著恶念），也不再按著我才行的灭各种的活物了。'),
('CUV', '创世纪', 1, 8, 22, '地还存留的时候，稼穑、寒暑、冬夏、昼夜就永不停息了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 9, 1, '神赐福给挪亚和他的儿子，对他们说：你们要生养众多，遍满了地。'),
('CUV', '创世纪', 1, 9, 2, '凡地上的走兽和空中的飞鸟都必惊恐，惧怕你们，连地上一切的昆虫并海里一切的鱼都交付你们的手。'),
('CUV', '创世纪', 1, 9, 3, '凡活著的动物都可以作你们的食物。这一切我都赐给你们，如同菜蔬一样。'),
('CUV', '创世纪', 1, 9, 4, '惟独肉带著血，那就是他的生命，你们不可吃。'),
('CUV', '创世纪', 1, 9, 5, '流你们血、害你们命的，无论是兽是人，我必讨他的罪，就是向各人的弟兄也是如此。'),
('CUV', '创世纪', 1, 9, 6, '凡流人血的，他的血也必被人所流，因为神造人是照自己的形像造的。'),
('CUV', '创世纪', 1, 9, 7, '你们要生养众多，在地上昌盛繁茂。'),
('CUV', '创世纪', 1, 9, 8, '神晓谕挪亚和他的儿子说：'),
('CUV', '创世纪', 1, 9, 9, '我与你们和你们的后裔立约，'),
('CUV', '创世纪', 1, 9, 10, '并与你们这里的一切活物─就是飞鸟、牲畜、走兽，凡从方舟里出来的活物─立约。'),
('CUV', '创世纪', 1, 9, 11, '我与你们立约，凡有血肉的，不再被洪水灭绝，也不再有洪水毁坏地了。'),
('CUV', '创世纪', 1, 9, 12, '神说：我与你们并你们这里的各样活物所立的永约是有记号的。'),
('CUV', '创世纪', 1, 9, 13, '我把虹放在云彩中，这就可作我与地立约的记号了。'),
('CUV', '创世纪', 1, 9, 14, '我使云彩盖地的时候，必有虹现在云彩中，'),
('CUV', '创世纪', 1, 9, 15, '我便记念我与你们和各样有血肉的活物所立的约，水就再不泛滥、毁坏一切有血肉的物了。'),
('CUV', '创世纪', 1, 9, 16, '虹必现在云彩中，我看见，就要记念我与地上各样有血肉的活物所立的永约。'),
('CUV', '创世纪', 1, 9, 17, '神对挪亚说：这就是我与地上一切有血肉之物立约的记号了。'),
('CUV', '创世纪', 1, 9, 18, '出方舟挪亚的儿子就是闪、含、雅弗。含是迦南的父亲。'),
('CUV', '创世纪', 1, 9, 19, '这是挪亚的三个儿子，他们的后裔分散在全地。'),
('CUV', '创世纪', 1, 9, 20, '挪亚作起农夫来，栽了一个葡萄园。'),
('CUV', '创世纪', 1, 9, 21, '他喝了园中的酒便醉了，在帐棚里赤著身子。'),
('CUV', '创世纪', 1, 9, 22, '迦南的父亲含看见他父亲赤身，就到外边告诉他两个弟兄。'),
('CUV', '创世纪', 1, 9, 23, '于是闪和雅弗拿件衣服搭在肩上，倒退著进去，给他父亲盖上；他们背著脸就看不见父亲的赤身。'),
('CUV', '创世纪', 1, 9, 24, '挪亚醒了酒，知道小儿子向他所作的事，'),
('CUV', '创世纪', 1, 9, 25, '就说：迦南当受咒诅，必给他弟兄作奴仆的奴仆；'),
('CUV', '创世纪', 1, 9, 26, '又说：耶和华─闪的神是应当称颂的！愿迦南作闪的奴仆。'),
('CUV', '创世纪', 1, 9, 27, '愿神使雅弗扩张，使他住在闪的帐棚里；又愿迦南作他的奴仆。'),
('CUV', '创世纪', 1, 9, 28, '洪水以后，挪亚又活了三百五十年。'),
('CUV', '创世纪', 1, 9, 29, '挪亚共活了九百五十岁就死了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 10, 1, '挪亚的儿子闪、含、雅弗的后代记在下面。洪水以后，他们都生了儿子。'),
('CUV', '创世纪', 1, 10, 2, '雅弗的儿子是歌篾、玛各、玛代、雅完、土巴、米设、提拉。'),
('CUV', '创世纪', 1, 10, 3, '歌篾的儿子是亚实基拿、利法、陀迦玛。'),
('CUV', '创世纪', 1, 10, 4, '雅完的儿子是以利沙、他施、基提、多单。'),
('CUV', '创世纪', 1, 10, 5, '这些人的后裔将各国的地土、海岛分开居住，各随各的方言、宗族立国。'),
('CUV', '创世纪', 1, 10, 6, '含的儿子是古实、麦西、弗、迦南。'),
('CUV', '创世纪', 1, 10, 7, '古实的儿子是西巴、哈腓拉、撒弗他、拉玛、撒弗提迦。拉玛的儿子是示巴、底但。'),
('CUV', '创世纪', 1, 10, 8, '古实又生宁录，他为世上英雄之首。'),
('CUV', '创世纪', 1, 10, 9, '他在耶和华面前是个英勇的猎户，所以俗语说：像宁录在耶和华面前是个英勇的猎户。'),
('CUV', '创世纪', 1, 10, 10, '他国的起头是巴别、以力、亚甲、甲尼，都在示拿地。'),
('CUV', '创世纪', 1, 10, 11, '他从那地出来往亚述去，建造尼尼微、利河伯、迦拉，'),
('CUV', '创世纪', 1, 10, 12, '和尼尼微、迦拉中间的利鲜，这就是那大城。'),
('CUV', '创世纪', 1, 10, 13, '麦西生路低人、亚拿米人、利哈比人、拿弗土希人、'),
('CUV', '创世纪', 1, 10, 14, '帕斯鲁细人、迦斯路希人、迦斐托人；从迦斐托出来的有非利士人。'),
('CUV', '创世纪', 1, 10, 15, '迦南生长子西顿，又生赫'),
('CUV', '创世纪', 1, 10, 16, '和耶布斯人、亚摩利人、革迦撒人、'),
('CUV', '创世纪', 1, 10, 17, '希未人、亚基人、西尼人、'),
('CUV', '创世纪', 1, 10, 18, '亚瓦底人、洗玛利人、哈马人，后来迦南的诸族分散了。'),
('CUV', '创世纪', 1, 10, 19, '迦南的境界是从西顿向基拉耳的路上，直到迦萨，又向所多玛、蛾摩拉、押玛、洗扁的路上，直到拉沙。'),
('CUV', '创世纪', 1, 10, 20, '这就是含的后裔，各随他们的宗族、方言，所住的地土、邦国。'),
('CUV', '创世纪', 1, 10, 21, '雅弗的哥哥闪，是希伯子孙之祖，他也生了儿子。'),
('CUV', '创世纪', 1, 10, 22, '闪的儿子是以拦、亚述、亚法撒、路德、亚兰。'),
('CUV', '创世纪', 1, 10, 23, '亚兰的儿子是乌斯、户勒、基帖、玛施。'),
('CUV', '创世纪', 1, 10, 24, '亚法撒生沙拉；沙拉生希伯。'),
('CUV', '创世纪', 1, 10, 25, '希伯生了两个儿子，一个名叫法勒(法勒就是分的意思)，因为那时人就分地居住；法勒的兄弟名叫约坍。'),
('CUV', '创世纪', 1, 10, 26, '约坍生亚摩答、沙列、哈萨玛非、耶拉、'),
('CUV', '创世纪', 1, 10, 27, '哈多兰、乌萨、德拉、'),
('CUV', '创世纪', 1, 10, 28, '俄巴路、亚比玛利、示巴、'),
('CUV', '创世纪', 1, 10, 29, '阿斐、哈腓拉、约巴，这都是约坍的儿子。'),
('CUV', '创世纪', 1, 10, 30, '他们所住的地方是从米沙直到西发东边的山。'),
('CUV', '创世纪', 1, 10, 31, '这就是闪的子孙，各随他们的宗族、方言，所住的地土、邦国。'),
('CUV', '创世纪', 1, 10, 32, '这些都是挪亚三个儿子的宗族，各随他们的支派立国。洪水以后，他们在地上分为邦国。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 11, 1, '那时，天下人的口音、言语都是一样。'),
('CUV', '创世纪', 1, 11, 2, '他们往东边迁移的时候，在示拿地遇见一片平原，就住在那里。'),
('CUV', '创世纪', 1, 11, 3, '他们彼此商量说：来罢！我们要作砖，把砖烧透了。他们就拿砖当石头，又拿石漆当灰泥。'),
('CUV', '创世纪', 1, 11, 4, '他们说：来罢！我们要建造一座城和一座塔，塔顶通天，为要传扬我们的名，免得我们分散在全地上。'),
('CUV', '创世纪', 1, 11, 5, '耶和华降临，要看看世人所建造的城和塔。'),
('CUV', '创世纪', 1, 11, 6, '耶和华说：看哪，他们成为一样的人民，都是一样的言语，如今既作起这事来，以后他们所要作的事就没有不成就的了。'),
('CUV', '创世纪', 1, 11, 7, '我们下去，在那里变乱他们的口音，使他们的言语彼此不通。'),
('CUV', '创世纪', 1, 11, 8, '于是耶和华使他们从那里分散在全地上；他们就停工，不造那城了。'),
('CUV', '创世纪', 1, 11, 9, '因为耶和华在那里变乱天下人的言语，使众人分散在全地上，所以那城名叫巴别(就是变乱的意思)。'),
('CUV', '创世纪', 1, 11, 10, '闪的后代记在下面。洪水以后二年，闪一百岁生了亚法撒。'),
('CUV', '创世纪', 1, 11, 11, '闪生亚法撒之后又活了五百年，并且生儿养女。'),
('CUV', '创世纪', 1, 11, 12, '亚法撒活到三十五岁，生了沙拉。'),
('CUV', '创世纪', 1, 11, 13, '亚法撒生沙拉之后又活了四百零三年，并且生儿养女。'),
('CUV', '创世纪', 1, 11, 14, '沙拉活到三十岁，生了希伯。'),
('CUV', '创世纪', 1, 11, 15, '沙拉生希伯之后又活了四百零三年，并且生儿养女。'),
('CUV', '创世纪', 1, 11, 16, '希伯活到三十四岁，生了法勒。'),
('CUV', '创世纪', 1, 11, 17, '希伯生法勒之后又活了四百三十年，并且生儿养女。'),
('CUV', '创世纪', 1, 11, 18, '法勒活到三十岁，生了拉吴。'),
('CUV', '创世纪', 1, 11, 19, '法勒生拉吴之后又活了二百零九年，并且生儿养女。'),
('CUV', '创世纪', 1, 11, 20, '拉吴活到三十二岁，生了西鹿。'),
('CUV', '创世纪', 1, 11, 21, '拉吴生西鹿之后又活了二百零七年，并且生儿养女。'),
('CUV', '创世纪', 1, 11, 22, '西鹿活到三十岁，生了拿鹤。'),
('CUV', '创世纪', 1, 11, 23, '西鹿生拿鹤之后又活了二百年，并且生儿养女。'),
('CUV', '创世纪', 1, 11, 24, '拿鹤活到二十九岁，生了他拉。'),
('CUV', '创世纪', 1, 11, 25, '拿鹤生他拉之后又活了一百一十九年，并且生儿养女。'),
('CUV', '创世纪', 1, 11, 26, '他拉活到七十岁，生了亚伯兰、拿鹤、哈兰。'),
('CUV', '创世纪', 1, 11, 27, '他拉的后代记在下面。他拉生亚伯兰、拿鹤、哈兰；哈兰生罗得。'),
('CUV', '创世纪', 1, 11, 28, '哈兰死在他的本地迦勒底的吾珥，在他父亲他拉之先。'),
('CUV', '创世纪', 1, 11, 29, '亚伯兰、拿鹤各娶了妻：亚伯兰的妻子名叫撒莱；拿鹤的妻子名叫密迦，是哈兰的女儿；哈兰是密迦和亦迦的父亲。'),
('CUV', '创世纪', 1, 11, 30, '撒莱不生育，没有孩子。'),
('CUV', '创世纪', 1, 11, 31, '他拉带著他儿子亚伯兰和他孙子哈兰的儿子罗得，并他儿妇亚伯兰的妻子撒莱，出了迦勒底的吾珥，要往迦南地去；他们走到哈兰，就住在那里。'),
('CUV', '创世纪', 1, 11, 32, '他拉共活了二百零五岁，就死在哈兰。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 12, 1, '耶和华对亚伯兰说：你要离开本地、本族、父家，往我所要指示你的地去。'),
('CUV', '创世纪', 1, 12, 2, '我必叫你成为大国。我必赐福给你，叫你的名为大；你也要叫别人得福。'),
('CUV', '创世纪', 1, 12, 3, '为你祝福的，我必赐福与他；那咒诅你的，我必咒诅他。地上的万族都要因你得福。'),
('CUV', '创世纪', 1, 12, 4, '亚伯兰就照著耶和华的吩咐去了；罗得也和他同去。亚伯兰出哈兰的时候年七十五岁。'),
('CUV', '创世纪', 1, 12, 5, '亚伯兰将他妻子撒莱和姪儿罗得，连他们在哈兰所积蓄的财物、所得的人口，都带往迦南地去。他们就到了迦南地。'),
('CUV', '创世纪', 1, 12, 6, '亚伯兰经过那地，到了示剑地方、摩利橡树那里。那时迦南人住在那地。'),
('CUV', '创世纪', 1, 12, 7, '耶和华向亚伯兰显现，说：我要把这地赐给你的后裔。亚伯兰就在那里为向他显现的耶和华筑了一座坛。'),
('CUV', '创世纪', 1, 12, 8, '从那里他又迁到伯特利东边的山，支搭帐棚；西边是伯特利，东边是艾。他在那里又为耶和华筑了一座坛，求告耶和华的名。'),
('CUV', '创世纪', 1, 12, 9, '后来亚伯兰又渐渐迁往南地去。'),
('CUV', '创世纪', 1, 12, 10, '那地遭遇饥荒。因饥荒甚大，亚伯兰就下埃及去，要在那里暂居。'),
('CUV', '创世纪', 1, 12, 11, '将近埃及，就对他妻子撒莱说：我知道你是容貌俊美的妇人。'),
('CUV', '创世纪', 1, 12, 12, '埃及人看见你必说：这是他的妻子，他们就要杀我，却叫你存活。'),
('CUV', '创世纪', 1, 12, 13, '求你说，你是我的妹子，使我因你得平安，我的命也因你存活。'),
('CUV', '创世纪', 1, 12, 14, '及至亚伯兰到了埃及，埃及人看见那妇人极其美貌。'),
('CUV', '创世纪', 1, 12, 15, '法老的臣宰看见了他，就在法老面前夸奖他。那妇人就被带进法老的宫去。'),
('CUV', '创世纪', 1, 12, 16, '法老因这妇人就厚待亚伯兰，亚伯兰得了许多牛、羊、骆驼、公驴、母驴、仆婢。'),
('CUV', '创世纪', 1, 12, 17, '耶和华因亚伯兰妻子撒莱的缘故，降大灾与法老和他的全家。'),
('CUV', '创世纪', 1, 12, 18, '法老就召了亚伯兰来，说：你这向我作的是甚么事呢？为甚么没有告诉我他是你的妻子？'),
('CUV', '创世纪', 1, 12, 19, '为甚么说他是你的妹子，以致我把他取来要作我的妻子？现在你的妻子在这里，可以带他走罢。'),
('CUV', '创世纪', 1, 12, 20, '于是法老吩咐人将亚伯兰和他妻子，并他所有的都送走了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 13, 1, '亚伯兰带著他的妻子与罗得，并一切所有的，都从埃及上南地去。'),
('CUV', '创世纪', 1, 13, 2, '亚伯兰的金、银、牲畜极多。'),
('CUV', '创世纪', 1, 13, 3, '他从南地渐渐往伯特利去，到了伯特利和艾的中间，就是从前支搭帐棚的地方，'),
('CUV', '创世纪', 1, 13, 4, '也是他起先筑坛的地方；他又在那里求告耶和华的名。'),
('CUV', '创世纪', 1, 13, 5, '与亚伯兰同行的罗得也有牛群、羊群、帐棚。'),
('CUV', '创世纪', 1, 13, 6, '那地容不下他们；因为他们的财物甚多，使他们不能同居。'),
('CUV', '创世纪', 1, 13, 7, '当时，迦南人与比利洗人在那地居住。亚伯兰的牧人和罗得的牧人相争。'),
('CUV', '创世纪', 1, 13, 8, '亚伯兰就对罗得说：你我不可相争，你的牧人和我的牧人也不可相争，因为我们是骨肉(原文作弟兄)。'),
('CUV', '创世纪', 1, 13, 9, '遍地不都在你眼前么？请你离开我：你向左，我就向右；你向右，我就向左。'),
('CUV', '创世纪', 1, 13, 10, '罗得举目看见约但河的全平原，直到琐珥，都是滋润的，那地在耶和华未灭所多玛、蛾摩拉以先如同耶和华的园子，也像埃及地。'),
('CUV', '创世纪', 1, 13, 11, '于是罗得选择约但河的全平原，往东迁移；他们就彼此分离了。'),
('CUV', '创世纪', 1, 13, 12, '亚伯兰住在迦南地，罗得住在平原的城邑，渐渐挪移帐棚，直到所多玛。'),
('CUV', '创世纪', 1, 13, 13, '所多玛人在耶和华面前罪大恶极。'),
('CUV', '创世纪', 1, 13, 14, '罗得离别亚伯兰以后，耶和华对亚伯兰说：从你所在的地方，你举目向东西南北观看；'),
('CUV', '创世纪', 1, 13, 15, '凡你所看见的一切地，我都要赐给你和你的后裔，直到永远。'),
('CUV', '创世纪', 1, 13, 16, '我也要使你的后裔如同地上的尘沙那样多，人若能数算地上的尘沙才能数算你的后裔。'),
('CUV', '创世纪', 1, 13, 17, '你起来，纵横走遍这地，因为我必把这地赐给你。'),
('CUV', '创世纪', 1, 13, 18, '亚伯兰就搬了帐棚，来到希伯仑幔利的橡树那里居住，在那里为耶和华筑了一座坛。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 14, 1, '当暗拉非作示拿王，亚略作以拉撒王，基大老玛作以拦王，提达作戈印王的时候，'),
('CUV', '创世纪', 1, 14, 2, '他们都攻打所多玛王比拉、蛾摩拉王比沙、押玛王示纳、洗扁王善以别，和比拉王；比拉就是琐珥。'),
('CUV', '创世纪', 1, 14, 3, '这五王都在西订谷会合；西订谷就是盐海。'),
('CUV', '创世纪', 1, 14, 4, '他们已经事奉基大老玛十二年，到十三年就背叛了。'),
('CUV', '创世纪', 1, 14, 5, '十四年，基大老玛和同盟的王都来在亚特律加宁，杀败了利乏音人，在哈麦杀败了苏西人，在沙微基列亭杀败了以米人，'),
('CUV', '创世纪', 1, 14, 6, '在何利人的西珥山杀败了何利人，一直杀到靠近旷野的伊勒巴兰。'),
('CUV', '创世纪', 1, 14, 7, '他们回到安密巴，就是加低斯，杀败了亚玛力全地的人，以及住在哈洗逊他玛的亚摩利人。'),
('CUV', '创世纪', 1, 14, 8, '于是所多玛王、蛾摩拉王、押玛王、洗扁王，和比拉王（比拉就是琐珥）都出来，在西订谷摆阵，与他们交战，'),
('CUV', '创世纪', 1, 14, 9, '就是与以拦王基大老玛、戈印王提达、示拿王暗拉非、以拉撒王亚略交战；乃是四王与五王交战。'),
('CUV', '创世纪', 1, 14, 10, '西订谷有许多石漆坑。所多玛王和蛾摩拉王逃跑，有掉在坑里的，其余的人都往山上逃跑。'),
('CUV', '创世纪', 1, 14, 11, '四王就把所多玛和蛾摩拉所有的财物，并一切的粮食都掳掠去了；'),
('CUV', '创世纪', 1, 14, 12, '又把亚伯兰的姪儿罗得和罗得的财物掳掠去了。当时罗得正住在所多玛。'),
('CUV', '创世纪', 1, 14, 13, '有一个逃出来的人告诉希伯来人亚伯兰；亚伯兰正住在亚摩利人幔利的橡树那里。幔利和以实各并亚乃都是弟兄，曾与亚伯兰联盟。'),
('CUV', '创世纪', 1, 14, 14, '亚伯兰听见他姪儿(原文作弟兄)被掳去，就率领他家里生养的精练壮丁三百一十八人，直追到但，'),
('CUV', '创世纪', 1, 14, 15, '便在夜间，自己同仆人分队杀败敌人，又追到大马色左边的何把，'),
('CUV', '创世纪', 1, 14, 16, '将被掳掠的一切财物夺回来，连他姪儿罗得和他的财物，以及妇女、人民也都夺回来。'),
('CUV', '创世纪', 1, 14, 17, '亚伯兰杀败基大老玛和与他同盟的王回来的时候，所多玛王出来，在沙微谷迎接他；沙微谷就是王谷。'),
('CUV', '创世纪', 1, 14, 18, '又有撒冷王麦基洗德带著饼和酒出来迎接；他是至高神的祭司。'),
('CUV', '创世纪', 1, 14, 19, '他为亚伯兰祝福，说：愿天地的主、至高的神赐福与亚伯兰！'),
('CUV', '创世纪', 1, 14, 20, '至高的神把敌人交在你手里，是应当称颂的！亚伯兰就把所得的拿出十分之一来，给麦基洗德。'),
('CUV', '创世纪', 1, 14, 21, '所多玛王对亚伯兰说：你把人口给我，财物你自己拿去罢！'),
('CUV', '创世纪', 1, 14, 22, '亚伯兰对所多玛王说：我已经向天地的主─至高的神耶和华起誓：'),
('CUV', '创世纪', 1, 14, 23, '凡是你的东西，就是一根线、一根鞋带，我都不拿，免得你说：我使亚伯兰富足！'),
('CUV', '创世纪', 1, 14, 24, '只有仆人所吃的，并与我同行的亚乃、以实各、幔利所应得的分，可以任凭他们拿去。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 15, 1, '这事以后，耶和华在异象中有话对亚伯兰说：亚伯兰，你不要惧怕！我是你的盾牌，必大大的赏赐你。'),
('CUV', '创世纪', 1, 15, 2, '亚伯兰说：主耶和华阿，我既无子，你还赐我甚么呢？并且要承受我家业的是大马色人以利以谢。'),
('CUV', '创世纪', 1, 15, 3, '亚伯兰又说：你没有给我儿子；那生在我家中的人就是我的后嗣。'),
('CUV', '创世纪', 1, 15, 4, '耶和华又有话对他说：这人必不成为你的后嗣；你本身所生的才成为你的后嗣。'),
('CUV', '创世纪', 1, 15, 5, '于是领他走到外边，说：你向天观看，数算众星，能数得过来么？又对他说：你的后裔将要如此。'),
('CUV', '创世纪', 1, 15, 6, '亚伯兰信耶和华，耶和华就以此为他的义。'),
('CUV', '创世纪', 1, 15, 7, '耶和华又对他说：我是耶和华，曾领你出了迦勒底的吾珥，为要将这地赐你为业。'),
('CUV', '创世纪', 1, 15, 8, '亚伯兰说：主耶和华阿，我怎能知道必得这地为业呢？'),
('CUV', '创世纪', 1, 15, 9, '他说：你为我取一只三年的母牛，一只三年的母山羊，一只三年的公绵羊，一只斑鸠，一只雏鸽。'),
('CUV', '创世纪', 1, 15, 10, '亚伯兰就取了这些来，每样劈开，分成两半，一半对著一半地摆列，只有鸟没有劈开。'),
('CUV', '创世纪', 1, 15, 11, '有鸷鸟下来，落在那死畜的肉上，亚伯兰就把他吓飞了。'),
('CUV', '创世纪', 1, 15, 12, '日头正落的时候，亚伯兰沉沉地睡了；忽然有惊人的大黑暗落在他身上。'),
('CUV', '创世纪', 1, 15, 13, '耶和华对亚伯兰说：你要的确知道，你的后裔必寄居别人的地，又服事那地的人；那地的人要苦待他们四百年。'),
('CUV', '创世纪', 1, 15, 14, '并且他们所要服事的那国，我要惩罚，后来他们必带著许多财物从那里出来。'),
('CUV', '创世纪', 1, 15, 15, '但你要享大寿数，平平安安地归到你列祖那里，被人埋葬。'),
('CUV', '创世纪', 1, 15, 16, '到了第四代，他们必回到此地，因为亚摩利人的罪孽还没有满盈。'),
('CUV', '创世纪', 1, 15, 17, '日落天黑，不料有冒烟的炉并烧著的火把从那些肉块中经过。'),
('CUV', '创世纪', 1, 15, 18, '当那日，耶和华与亚伯兰立约，说：我已赐给你的后裔，从埃及河直到伯拉大河之地，'),
('CUV', '创世纪', 1, 15, 19, '就是基尼人、基尼洗人、甲摩尼人、'),
('CUV', '创世纪', 1, 15, 20, '赫人、比利洗人、利乏音人、'),
('CUV', '创世纪', 1, 15, 21, '亚摩利人、迦南人、革迦撒人、耶布斯人之地。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 16, 1, '亚伯兰的妻子撒莱不给他生儿女。撒莱有一个使女，名叫夏甲，是埃及人。'),
('CUV', '创世纪', 1, 16, 2, '撒莱对亚伯兰说：耶和华使我不能生育。求你和我的使女同房，或者我可以因他得孩子(原文作被建立)。亚伯兰听从了撒莱的话。'),
('CUV', '创世纪', 1, 16, 3, '于是亚伯兰的妻子撒莱将使女埃及人夏甲给了丈夫为妾；那时亚伯兰在迦南已经住了十年。'),
('CUV', '创世纪', 1, 16, 4, '亚伯兰与夏甲同房，夏甲就怀了孕；他见自己有孕，就小看他的主母。'),
('CUV', '创世纪', 1, 16, 5, '撒莱对亚伯兰说：我因你受屈。我将我的使女放在你怀中，他见自己有了孕，就小看我。愿耶和华在你我中间判断。'),
('CUV', '创世纪', 1, 16, 6, '亚伯兰对撒莱说：使女在你手下，你可以随意待他。撒莱苦待他，他就从撒莱面前逃走了。'),
('CUV', '创世纪', 1, 16, 7, '耶和华的使者在旷野书珥路上的水泉旁遇见他，'),
('CUV', '创世纪', 1, 16, 8, '对他说：撒莱的使女夏甲，你从那里来？要往那里去？夏甲说：我从我的主母撒莱面前逃出来。'),
('CUV', '创世纪', 1, 16, 9, '耶和华的使者对他说：你回到你主母那里，服在他手下；'),
('CUV', '创世纪', 1, 16, 10, '又说：我必使你的后裔极其繁多，甚至不可胜数；'),
('CUV', '创世纪', 1, 16, 11, '并说：你如今怀孕要生一个儿子，可以给他起名叫以实玛利，因为耶和华听见了你的苦情。(以实玛利就是神听见的意思)'),
('CUV', '创世纪', 1, 16, 12, '他为人必像野驴。他的手要攻打人，人的手也要攻打他；他必住在众弟兄的东边。'),
('CUV', '创世纪', 1, 16, 13, '夏甲就称那对他说话的耶和华为看顾人的神。因而说：在这里我也看见那看顾我的么？'),
('CUV', '创世纪', 1, 16, 14, '所以这井名叫庇耳拉海莱。这井正在加低斯和巴列中间。'),
('CUV', '创世纪', 1, 16, 15, '后来夏甲给亚伯兰生了一个儿子；亚伯兰给他起名叫以实玛利。'),
('CUV', '创世纪', 1, 16, 16, '夏甲给亚伯兰生以实玛利的时候，亚伯兰年八十六岁。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 17, 1, '亚伯兰年九十九岁的时候，耶和华向他显现，对他说：我是全能的神。你当在我面前作完全人，'),
('CUV', '创世纪', 1, 17, 2, '我就与你立约，使你的后裔极其繁多。'),
('CUV', '创世纪', 1, 17, 3, '亚伯兰俯伏在地；神又对他说：'),
('CUV', '创世纪', 1, 17, 4, '我与你立约：你要作多国的父。'),
('CUV', '创世纪', 1, 17, 5, '从此以后，你的名不再叫亚伯兰，要叫亚伯拉罕，因为我已立你作多国的父。'),
('CUV', '创世纪', 1, 17, 6, '我必使你的后裔极其繁多；国度从你而立，君王从你而出。'),
('CUV', '创世纪', 1, 17, 7, '我要与你并你世世代代的后裔坚立我的约，作永远的约，是要作你和你后裔的神。'),
('CUV', '创世纪', 1, 17, 8, '我要将你现在寄居的地，就是迦南全地，赐给你和你的后裔永远为业，我也必作他们的神。'),
('CUV', '创世纪', 1, 17, 9, '神又对亚伯拉罕说：你和你的后裔必世世代代遵守我的约。'),
('CUV', '创世纪', 1, 17, 10, '你们所有的男子都要受割礼；这就是我与你并你的后裔所立的约，是你们所当遵守的。'),
('CUV', '创世纪', 1, 17, 11, '你们都要受割礼(原文作割阳皮；14，23，24，25节同)；这是我与你们立约的证据。'),
('CUV', '创世纪', 1, 17, 12, '你们世世代代的男子，无论是家里生的，是在你后裔之外用银子从外人买的，生下来第八日，都要受割礼。'),
('CUV', '创世纪', 1, 17, 13, '你家里生的和你用银子买的，都必须受割礼。这样，我的约就立在你们肉体上作永远的约。'),
('CUV', '创世纪', 1, 17, 14, '但不受割礼的男子必从民中剪除，因他背了我的约。'),
('CUV', '创世纪', 1, 17, 15, '神又对亚伯拉罕说：你的妻子撒莱不可再叫撒莱，他的名要叫撒拉。'),
('CUV', '创世纪', 1, 17, 16, '我必赐福给他，也要使你从他得一个儿子。我要赐福给他，他也要作多国之母；必有百姓的君王从他而出。'),
('CUV', '创世纪', 1, 17, 17, '亚伯拉罕就俯伏在地喜笑，心里说：一百岁的人还能得孩子么？撒拉已经九十岁了，还能生养么？'),
('CUV', '创世纪', 1, 17, 18, '亚伯拉罕对神说：但愿以实玛利活在你面前。'),
('CUV', '创世纪', 1, 17, 19, '神说：不然，你妻子撒拉要给你生一个儿子，你要给他起名叫以撒。我要与他坚定所立的约，作他后裔永远的约。'),
('CUV', '创世纪', 1, 17, 20, '至于以实玛利，我也应允你：我必赐福给他，使他昌盛，极其繁多。他必生十二个族长；我也要使他成为大国。'),
('CUV', '创世纪', 1, 17, 21, '到明年这时节，撒拉必给你生以撒，我要与他坚定所立的约。'),
('CUV', '创世纪', 1, 17, 22, '神和亚伯拉罕说完了话，就离开他上升去了。'),
('CUV', '创世纪', 1, 17, 23, '正当那日，亚伯拉罕遵著神的命，给他的儿子以实玛利和家里的一切男子，无论是在家里生的，是用银子买的，都行了割礼。'),
('CUV', '创世纪', 1, 17, 24, '亚伯拉罕受割礼的时候年九十九岁。'),
('CUV', '创世纪', 1, 17, 25, '他儿子以实玛利受割礼的时候年十三岁。'),
('CUV', '创世纪', 1, 17, 26, '正当那日，亚伯拉罕和他儿子以实玛利一同受了割礼。'),
('CUV', '创世纪', 1, 17, 27, '家里所有的人，无论是在家里生的，是用银子从外人买的，也都一同受了割礼。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 18, 1, '耶和华在幔利橡树那里向亚伯拉罕显现出来。那时正热，亚伯拉罕坐在帐棚门口，'),
('CUV', '创世纪', 1, 18, 2, '举目观看，见有三个人在对面站著。他一见，就从帐棚门口跑去迎接他们，俯伏在地，'),
('CUV', '创世纪', 1, 18, 3, '说：我主，我若在你眼前蒙恩，求你不要离开仆人往前去。'),
('CUV', '创世纪', 1, 18, 4, '容我拿点水来，你们洗洗脚，在树下歇息歇息。'),
('CUV', '创世纪', 1, 18, 5, '我再拿一点饼来，你们可以加添心力，然后往前去。你们既到仆人这里来，理当如此。他们说：就照你说的行罢。'),
('CUV', '创世纪', 1, 18, 6, '亚伯拉罕急忙进帐棚见撒拉，说：你速速拿三细亚细面调和作饼。'),
('CUV', '创世纪', 1, 18, 7, '亚伯拉罕又跑到牛群里，牵了一只又嫩又好的牛犊来，交给仆人，仆人急忙预备好了。'),
('CUV', '创世纪', 1, 18, 8, '亚伯拉罕又取了奶油和奶，并预备好的牛犊来，摆在他们面前，自己在树下站在旁边，他们就吃了。'),
('CUV', '创世纪', 1, 18, 9, '他们问亚伯拉罕说：你妻子撒拉在那里？他说：在帐棚里。'),
('CUV', '创世纪', 1, 18, 10, '三人中有一位说：到明年这时候，我必要回到你这里；你的妻子撒拉必生一个儿子。撒拉在那人后边的帐棚门口也听见了这话。'),
('CUV', '创世纪', 1, 18, 11, '亚伯拉罕和撒拉年纪老迈，撒拉的月经已断绝了。'),
('CUV', '创世纪', 1, 18, 12, '撒拉心里暗笑，说：我既已衰败，我主也老迈，岂能有这喜事呢？'),
('CUV', '创世纪', 1, 18, 13, '耶和华对亚伯拉罕说：撒拉为甚么暗笑，说：我既已年老，果真能生养么？'),
('CUV', '创世纪', 1, 18, 14, '耶和华岂有难成的事么？到了日期，明年这时候，我必回到你这里，撒拉必生一个儿子。'),
('CUV', '创世纪', 1, 18, 15, '撒拉就害怕，不承认，说：我没有笑。那位说：不然，你实在笑了。'),
('CUV', '创世纪', 1, 18, 16, '三人就从那里起行，向所多玛观看，亚伯拉罕也与他们同行，要送他们一程。'),
('CUV', '创世纪', 1, 18, 17, '耶和华说：我所要作的事岂可瞒著亚伯拉罕呢？'),
('CUV', '创世纪', 1, 18, 18, '亚伯拉罕必要成为强大的国；地上的万国都必因他得福。'),
('CUV', '创世纪', 1, 18, 19, '我眷顾他，为要叫他吩咐他的众子和他的眷属遵守我的道，秉公行义，使我所应许亚伯拉罕的话都成就了。'),
('CUV', '创世纪', 1, 18, 20, '耶和华说：所多玛和蛾摩拉的罪恶甚重，声闻于我。'),
('CUV', '创世纪', 1, 18, 21, '我现在要下去，察看他们所行的，果然尽像那达到我耳中的声音一样么？若是不然，我也必知道。'),
('CUV', '创世纪', 1, 18, 22, '二人转身离开那里，向所多玛去；但亚伯拉罕仍旧站在耶和华面前。'),
('CUV', '创世纪', 1, 18, 23, '亚伯拉罕近前来，说：无论善恶，你都要剿灭么？'),
('CUV', '创世纪', 1, 18, 24, '假若那城里有五十个义人，你还剿灭那地方么？不为城里这五十个义人饶恕其中的人么？'),
('CUV', '创世纪', 1, 18, 25, '将义人与恶人同杀，将义人与恶人一样看待，这断不是你所行的。审判全地的主岂不行公义么？'),
('CUV', '创世纪', 1, 18, 26, '耶和华说：我若在所多玛城里见有五十个义人，我就为他们的缘故饶恕那地方的众人。'),
('CUV', '创世纪', 1, 18, 27, '亚伯拉罕说：我虽然是灰尘，还敢对主说话。'),
('CUV', '创世纪', 1, 18, 28, '假若这五十个义人短了五个，你就因为短了五个毁灭全城么？他说：我在那里若见有四十五个，也不毁灭那城。'),
('CUV', '创世纪', 1, 18, 29, '亚伯拉罕又对他说：假若在那里见有四十个怎么样呢？他说：为这四十个的缘故，我也不作这事。'),
('CUV', '创世纪', 1, 18, 30, '亚伯拉罕说：求主不要动怒，容我说，假若在那里见有三十个怎么样呢？他说：我在那里若见有三十个，我也不作这事。'),
('CUV', '创世纪', 1, 18, 31, '亚伯拉罕说：我还敢对主说话，假若在那里见有二十个怎么样呢？他说：为这二十个的缘故，我也不毁灭那城。'),
('CUV', '创世纪', 1, 18, 32, '亚伯拉罕说：求主不要动怒，我再说这一次，假若在那里见有十个呢？他说：为这十个的缘故，我也不毁灭那城。'),
('CUV', '创世纪', 1, 18, 33, '耶和华与亚伯拉罕说完了话就走了；亚伯拉罕也回到自己的地方去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 19, 1, '那两个天使晚上到了所多玛；罗得正坐在所多玛城门口，看见他们，就起来迎接，脸伏于地下拜，'),
('CUV', '创世纪', 1, 19, 2, '说：我主阿，请你们到仆人家里洗洗脚，住一夜，清早起来再走。他们说：不！我们要在街上过夜。'),
('CUV', '创世纪', 1, 19, 3, '罗得切切的请他们，他们这才进去，到他屋里。罗得为他们预备筵席，烤无酵饼，他们就吃了。'),
('CUV', '创世纪', 1, 19, 4, '他们还没有躺下，所多玛城里各处的人，连老带少，都来围住那房子，'),
('CUV', '创世纪', 1, 19, 5, '呼叫罗得说：今日晚上到你这里来的人在那里呢？把他们带出来，任我们所为。'),
('CUV', '创世纪', 1, 19, 6, '罗得出来，把门关上，到众人那里，'),
('CUV', '创世纪', 1, 19, 7, '说：众弟兄，请你们不要作这恶事。'),
('CUV', '创世纪', 1, 19, 8, '我有两个女儿，还是处女，容我领出来，任凭你们的心愿而行；只是这两个人既然到我舍下，不要向他们作甚么。'),
('CUV', '创世纪', 1, 19, 9, '众人说：退去罢！又说：这个人来寄居，还想要作官哪！现在我们要害你比害他们更甚。众人就向前拥挤罗得，要攻破房门。'),
('CUV', '创世纪', 1, 19, 10, '只是那二人伸出手来，将罗得拉进屋去，把门关上，'),
('CUV', '创世纪', 1, 19, 11, '并且使门外的人，无论老少，眼都昏迷；他们摸来摸去，总寻不著房门。'),
('CUV', '创世纪', 1, 19, 12, '二人对罗得说：你这里还有甚么人么？无论是女婿是儿女，和这城中一切属你的人，你都要将他们从这地方带出去。'),
('CUV', '创世纪', 1, 19, 13, '我们要毁灭这地方；因为城内罪恶的声音在耶和华面前甚大，耶和华差我们来，要毁灭这地方。'),
('CUV', '创世纪', 1, 19, 14, '罗得就出去，告诉娶了(或作将要娶)他女儿的女婿们说：你们起来离开这地方，因为耶和华要毁灭这城。他女婿们却以为他说的是戏言。'),
('CUV', '创世纪', 1, 19, 15, '天明了，天使催逼罗得说：起来！带著你的妻子和你在这里的两个女儿出去，免得你因这城里的罪恶同被剿灭。'),
('CUV', '创世纪', 1, 19, 16, '但罗得迟延不走。二人因为耶和华怜恤罗得，就拉著他的手和他妻子的手，并他两个女儿的手，把他们领出来，安置在城外；'),
('CUV', '创世纪', 1, 19, 17, '领他们出来以后，就说：逃命罢！不可回头看，也不可在平原站住。要往山上逃跑，免得你被剿灭。'),
('CUV', '创世纪', 1, 19, 18, '罗得对他们说：我主阿，不要如此！'),
('CUV', '创世纪', 1, 19, 19, '你仆人已经在你眼前蒙恩；你又向我显出莫大的慈爱，救我的性命。我不能逃到山上去，恐怕这灾祸临到我，我便死了。'),
('CUV', '创世纪', 1, 19, 20, '看哪，这座城又小又近，容易逃到，这不是一个小的么？求你容我逃到那里，我的性命就得存活。'),
('CUV', '创世纪', 1, 19, 21, '天使对他说：这事我也应允你；我不倾覆你所说的这城。'),
('CUV', '创世纪', 1, 19, 22, '你要速速地逃到那城；因为你还没有到那里，我不能作甚么。因此那城名叫琐珥(就是小的意思)。'),
('CUV', '创世纪', 1, 19, 23, '罗得到了琐珥，日头已经出来了。'),
('CUV', '创世纪', 1, 19, 24, '当时，耶和华将硫磺与火从天上耶和华那里降与所多玛和蛾摩拉，'),
('CUV', '创世纪', 1, 19, 25, '把那些城和全平原，并城里所有的居民，连地上生长的，都毁灭了。'),
('CUV', '创世纪', 1, 19, 26, '罗得的妻子在后边回头一看，就变成了一根盐柱。'),
('CUV', '创世纪', 1, 19, 27, '亚伯拉罕清早起来，到了他从前站在耶和华面前的地方，'),
('CUV', '创世纪', 1, 19, 28, '向所多玛和蛾摩拉与平原的全地观看，不料，那地方烟气上腾，如同烧窑一般。'),
('CUV', '创世纪', 1, 19, 29, '当神毁灭平原诸城的时候，他记念亚伯拉罕，正在倾覆罗得所住之城的时候，就打发罗得从倾覆之中出来。'),
('CUV', '创世纪', 1, 19, 30, '罗得因为怕住在琐珥，就同他两个女儿从琐珥上去，住在山里；他和两个女儿住在一个洞里。'),
('CUV', '创世纪', 1, 19, 31, '大女儿对小女儿说：我们的父亲老了，地上又无人按著世上的常规进到我们这里。'),
('CUV', '创世纪', 1, 19, 32, '来！我们可以叫父亲喝酒，与他同寝。这样，我们好从他存留后裔。'),
('CUV', '创世纪', 1, 19, 33, '于是，那夜他们叫父亲喝酒，大女儿就进去和他父亲同寝；他几时躺下，几时起来，父亲都不知道。'),
('CUV', '创世纪', 1, 19, 34, '第二天，大女儿对小女儿说：我昨夜与父亲同寝。今夜我们再叫他喝酒，你可以进去与他同寝。这样，我们好从父亲存留后裔。'),
('CUV', '创世纪', 1, 19, 35, '于是，那夜他们又叫父亲喝酒，小女儿起来与他父亲同寝；他几时躺下，几时起来，父亲都不知道。'),
('CUV', '创世纪', 1, 19, 36, '这样，罗得的两个女儿都从他父亲怀了孕。'),
('CUV', '创世纪', 1, 19, 37, '大女儿生了儿子，给他起名叫摩押，就是现今摩押人的始祖。'),
('CUV', '创世纪', 1, 19, 38, '小女儿也生了儿子，给他起名叫便亚米，就是现今亚扪人的始祖。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 20, 1, '亚伯拉罕从那里向南地迁去，寄居在加低斯和书珥中间的基拉耳。'),
('CUV', '创世纪', 1, 20, 2, '亚伯拉罕称他的妻撒拉为妹子，基拉耳王亚比米勒差人把撒拉取了去。'),
('CUV', '创世纪', 1, 20, 3, '但夜间，神来，在梦中对亚比米勒说：你是个死人哪！因为你取了那女人来；他原是别人的妻子。'),
('CUV', '创世纪', 1, 20, 4, '亚比米勒却还没有亲近撒拉；他说：主阿，连有义的国，你也要毁灭么？'),
('CUV', '创世纪', 1, 20, 5, '那人岂不是自己对我说他是我的妹子么？就是女人也自己说：他是我的哥哥。我作这事是心正手洁的。'),
('CUV', '创世纪', 1, 20, 6, '神在梦中对他说：我知道你作这事是心中正直；我也拦阻了你，免得你得罪我，所以我不容你沾著他。'),
('CUV', '创世纪', 1, 20, 7, '现在你把这人的妻子归还他；因为他是先知，他要为你祷告，使你存活。你若不归还他，你当知道，你和你所有的人都必要死。'),
('CUV', '创世纪', 1, 20, 8, '亚比米勒清早起来，召了众臣仆来，将这些事都说给他们听，他们都甚惧怕。'),
('CUV', '创世纪', 1, 20, 9, '亚比米勒召了亚伯拉罕来，对他说：你怎么向我这样行呢？我在甚么事上得罪了你，你竟使我和我国里的人陷在大罪里？你向我行不当行的事了！'),
('CUV', '创世纪', 1, 20, 10, '亚比米勒又对亚伯拉罕说：你见了甚么才做这事呢？'),
('CUV', '创世纪', 1, 20, 11, '亚伯拉罕说：我以为这地方的人总不惧怕神，必为我妻子的缘故杀我。'),
('CUV', '创世纪', 1, 20, 12, '况且他也实在是我的妹子；他与我是同父异母，后来作了我的妻子。'),
('CUV', '创世纪', 1, 20, 13, '当神叫我离开父家、飘流在外的时候，我对他说：我们无论走到甚么地方，你可以对人说：他是我的哥哥；这就是你待我的恩典了。'),
('CUV', '创世纪', 1, 20, 14, '亚比米勒把牛、羊、仆婢赐给亚伯拉罕，又把他的妻子撒拉归还他。'),
('CUV', '创世纪', 1, 20, 15, '亚比米勒又说：看哪，我的地都在你面前，你可以随意居住；'),
('CUV', '创世纪', 1, 20, 16, '又对撒拉说：我给你哥哥一千银子，作为你在合家人面前遮羞(原文作眼)的，你就在众人面前没有不是了。'),
('CUV', '创世纪', 1, 20, 17, '亚伯拉罕祷告神，神就医好了亚比米勒和他的妻子，并他的众女仆，他们便能生育。'),
('CUV', '创世纪', 1, 20, 18, '因耶和华为亚伯拉罕的妻子撒拉的缘故，已经使亚比米勒家中的妇人不能生育。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 21, 1, '耶和华按著先前的话眷顾撒拉，便照他所说的给撒拉成就。'),
('CUV', '创世纪', 1, 21, 2, '当亚伯拉罕年老的时候，撒拉怀了孕；到神所说的日期，就给亚伯拉罕生了一个儿子。'),
('CUV', '创世纪', 1, 21, 3, '亚伯拉罕给撒拉所生的儿子起名叫以撒。'),
('CUV', '创世纪', 1, 21, 4, '以撒生下来第八日，亚伯拉罕照著神所吩咐的，给以撒行了割礼。'),
('CUV', '创世纪', 1, 21, 5, '他儿子以撒生的时候，亚伯拉罕年一百岁。'),
('CUV', '创世纪', 1, 21, 6, '撒拉说：神使我喜笑，凡听见的必与我一同喜笑；'),
('CUV', '创世纪', 1, 21, 7, '又说：谁能预先对亚伯拉罕说撒拉要乳养婴孩呢？因为在他年老的时候，我给他生了一个儿子。'),
('CUV', '创世纪', 1, 21, 8, '孩子渐长，就断了奶。以撒断奶的日子，亚伯拉罕设摆丰盛的筵席。'),
('CUV', '创世纪', 1, 21, 9, '当时，撒拉看见埃及人夏甲给亚伯拉罕所生的儿子戏笑，'),
('CUV', '创世纪', 1, 21, 10, '就对亚伯拉罕说：你把这使女和他儿子赶出去！因为这使女的儿子不可与我的儿子以撒一同承受产业。'),
('CUV', '创世纪', 1, 21, 11, '亚伯拉罕因他儿子的缘故很忧愁。'),
('CUV', '创世纪', 1, 21, 12, '神对亚伯拉罕说：你不必为这童子和你的使女忧愁。凡撒拉对你说的话，你都该听从；因为从以撒生的，才要称为你的后裔。'),
('CUV', '创世纪', 1, 21, 13, '至于使女的儿子，我也必使他的后裔成立一国，因为他是你所生的。'),
('CUV', '创世纪', 1, 21, 14, '亚伯拉罕清早起来，拿饼和一皮袋水，给了夏甲，搭在他的肩上，又把孩子交给他，打发他走。夏甲就走了，在别是巴的旷野走迷了路。'),
('CUV', '创世纪', 1, 21, 15, '皮袋的水用尽了，夏甲就把孩子撇在小树底下，'),
('CUV', '创世纪', 1, 21, 16, '自己走开约有一箭之远，相对而坐，说：我不忍见孩子死，就相对而坐，放声大哭。'),
('CUV', '创世纪', 1, 21, 17, '神听见童子的声音；神的使者从天上呼叫夏甲说：夏甲，你为何这样呢？不要害怕，神已经听见童子的声音了。'),
('CUV', '创世纪', 1, 21, 18, '起来！把童子抱在怀(原文作手)中，我必使他的后裔成为大国。'),
('CUV', '创世纪', 1, 21, 19, '神使夏甲的眼睛明亮，他就看见一口水井，便去将皮袋盛满了水，给童子喝。'),
('CUV', '创世纪', 1, 21, 20, '神保佑童子，他就渐长，住在旷野，成了弓箭手。'),
('CUV', '创世纪', 1, 21, 21, '他住在巴兰的旷野；他母亲从埃及地给他娶了一个妻子。'),
('CUV', '创世纪', 1, 21, 22, '当那时候，亚比米勒同他军长非各对亚伯拉罕说：凡你所行的事都有神的保佑。'),
('CUV', '创世纪', 1, 21, 23, '我愿你如今在这里指著神对我起誓，不要欺负我与我的儿子，并我的子孙。我怎样厚待了你，你也要照样厚待我与你所寄居这地的民。'),
('CUV', '创世纪', 1, 21, 24, '亚伯拉罕说：我情愿起誓。'),
('CUV', '创世纪', 1, 21, 25, '从前，亚比米勒的仆人霸占了一口水井，亚伯拉罕为这事指责亚比米勒。'),
('CUV', '创世纪', 1, 21, 26, '亚比米勒说：谁做这事，我不知道，你也没有告诉我，今日我才听见了。'),
('CUV', '创世纪', 1, 21, 27, '亚伯拉罕把羊和牛给了亚比米勒，二人就彼此立约。'),
('CUV', '创世纪', 1, 21, 28, '亚伯拉罕把七只母羊羔另放在一处。'),
('CUV', '创世纪', 1, 21, 29, '亚比米勒问亚伯拉罕说：你把这七只母羊羔另放在一处，是甚么意思呢？'),
('CUV', '创世纪', 1, 21, 30, '他说：你要从我手里受这七只母羊羔，作我挖这口井的证据。'),
('CUV', '创世纪', 1, 21, 31, '所以他给那地方起名叫别是巴，因为他们二人在那里起了誓。(别是巴就是盟誓的井的意思)'),
('CUV', '创世纪', 1, 21, 32, '他们在别是巴立了约，亚比米勒就同他军长非各起身回非利士地去了。'),
('CUV', '创世纪', 1, 21, 33, '亚伯拉罕在别是巴栽上一棵垂丝柳树，又在那里求告耶和华─永生神的名。'),
('CUV', '创世纪', 1, 21, 34, '亚伯拉罕在非利士人的地寄居了多日。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 22, 1, '这些事以后，神要试验亚伯拉罕，就呼叫他说：亚伯拉罕！他说：我在这里。'),
('CUV', '创世纪', 1, 22, 2, '神说：你带著你的儿子，就是你独生的儿子，你所爱的以撒，往摩利亚地去，在我所要指示你的山上，把他献为燔祭。'),
('CUV', '创世纪', 1, 22, 3, '亚伯拉罕清早起来，备上驴，带著两个仆人和他儿子以撒，也劈好了燔祭的柴，就起身往神所指示他的地方去了。'),
('CUV', '创世纪', 1, 22, 4, '到了第三日，亚伯拉罕举目远远的看见那地方。'),
('CUV', '创世纪', 1, 22, 5, '亚伯拉罕对他的仆人说：你们和驴在此等候，我与童子往那里去拜一拜，就回到你们这里来。'),
('CUV', '创世纪', 1, 22, 6, '亚伯拉罕把燔祭的柴放在他儿子以撒身上，自己手里拿著火与刀；于是二人同行。'),
('CUV', '创世纪', 1, 22, 7, '以撒对他父亲亚伯拉罕说：父亲哪！亚伯拉罕说：我儿，我在这里。以撒说：请看，火与柴都有了，但燔祭的羊羔在那里呢？'),
('CUV', '创世纪', 1, 22, 8, '亚伯拉罕说：我儿，神必自己预备作燔祭的羊羔。于是二人同行。'),
('CUV', '创世纪', 1, 22, 9, '他们到了神所指示的地方，亚伯拉罕在那里筑坛，把柴摆好，捆绑他的儿子以撒，放在坛的柴上。'),
('CUV', '创世纪', 1, 22, 10, '亚伯拉罕就伸手拿刀，要杀他的儿子。'),
('CUV', '创世纪', 1, 22, 11, '耶和华的使者从天上呼叫他说：亚伯拉罕！亚伯拉罕！他说：我在这里。'),
('CUV', '创世纪', 1, 22, 12, '天使说：你不可在这童子身上下手。一点不可害他！现在我知道你是敬畏神的了；因为你没有将你的儿子，就是你独生的儿子，留下不给我。'),
('CUV', '创世纪', 1, 22, 13, '亚伯拉罕举目观看，不料，有一只公羊，两角扣在稠密的小树中，亚伯拉罕就取了那只公羊来，献为燔祭，代替他的儿子。'),
('CUV', '创世纪', 1, 22, 14, '亚伯拉罕给那地方起名叫耶和华以勒(意思就是耶和华必预备的意思)，直到今日人还说：在耶和华的山上必有预备。'),
('CUV', '创世纪', 1, 22, 15, '耶和华的使者第二次从天上呼叫亚伯拉罕说：'),
('CUV', '创世纪', 1, 22, 16, '耶和华说：你既行了这事，不留下你的儿子，就是你独生的儿子，我便指著自己起誓说：'),
('CUV', '创世纪', 1, 22, 17, '论福，我必赐大福给你；论子孙，我必叫你的子孙多起来，如同天上的星，海边的沙。你子孙必得著仇敌的城门，'),
('CUV', '创世纪', 1, 22, 18, '并且地上万国都必因你的后裔得福，因为你听从了我的话。'),
('CUV', '创世纪', 1, 22, 19, '于是亚伯拉罕回到他仆人那里，他们一同起身往别是巴去，亚伯拉罕就住在别是巴。'),
('CUV', '创世纪', 1, 22, 20, '这事以后，有人告诉亚伯拉罕说：密迦给你兄弟拿鹤生了几个儿子，'),
('CUV', '创世纪', 1, 22, 21, '长子是乌斯，他的兄弟是布斯和亚兰的父亲基母利，'),
('CUV', '创世纪', 1, 22, 22, '并基薛、哈琐、必达、益拉、彼土利（彼土利生利百加）。'),
('CUV', '创世纪', 1, 22, 23, '这八个人都是密迦给亚伯拉罕的兄弟拿鹤生的。'),
('CUV', '创世纪', 1, 22, 24, '拿鹤的妾名叫流玛，生了提八、迦含、他辖，和玛迦。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 23, 1, '撒拉享寿一百二十七岁，这是撒拉一生的岁数。'),
('CUV', '创世纪', 1, 23, 2, '撒拉死在迦南地的基列亚巴，就是希伯仑。亚伯拉罕为他哀恸哭号。'),
('CUV', '创世纪', 1, 23, 3, '后来亚伯拉罕从死人面前起来，对赫人说：'),
('CUV', '创世纪', 1, 23, 4, '我在你们中间是外人，是寄居的。求你们在这里给我一块地，我好埋葬我的死人，使他不在我眼前。'),
('CUV', '创世纪', 1, 23, 5, '赫人回答亚伯拉罕说：'),
('CUV', '创世纪', 1, 23, 6, '我主请听。你在我们中间是一位尊大的王子，只管在我们最好的坟地里埋葬你的死人；我们没有一人不容你在他的坟地里埋葬你的死人。'),
('CUV', '创世纪', 1, 23, 7, '亚伯拉罕就起来，向那地的赫人下拜，'),
('CUV', '创世纪', 1, 23, 8, '对他们说：你们若有意叫我埋葬我的死人，使他不在我眼前，就请听我的话，为我求琐辖的儿子以弗仑，'),
('CUV', '创世纪', 1, 23, 9, '把田头上那麦比拉洞给我；他可以按著足价卖给我，作我在你们中间的坟地。'),
('CUV', '创世纪', 1, 23, 10, '当时以弗仑正坐在赫人中间。于是，赫人以弗仑在城门出入的赫人面前对亚伯拉罕说：'),
('CUV', '创世纪', 1, 23, 11, '不然，我主请听。我送给你这块田，连田间的洞也送给你，在我同族的人面前都给你，可以埋葬你的死人。'),
('CUV', '创世纪', 1, 23, 12, '亚伯拉罕就在那地的人民面前下拜，'),
('CUV', '创世纪', 1, 23, 13, '在他们面前对以弗仑说：你若应允，请听我的话。我要把田价给你，求你收下，我就在那里埋葬我的死人。'),
('CUV', '创世纪', 1, 23, 14, '以弗仑回答亚伯拉罕说：'),
('CUV', '创世纪', 1, 23, 15, '我主请听。值四百舍客勒银子的一块田，在你我中间还算甚么呢？只管埋葬你的死人罢！'),
('CUV', '创世纪', 1, 23, 16, '亚伯拉罕听从了以弗仑，照著他在赫人面前所说的话，把买卖通用的银子平了四百舍客勒给以弗仑。'),
('CUV', '创世纪', 1, 23, 17, '于是，麦比拉、幔利前、以弗仑的那块田和其中的洞，并田间四围的树木，'),
('CUV', '创世纪', 1, 23, 18, '都定准归与亚伯拉罕，乃是他在赫人面前并城门出入的人面前买妥的。'),
('CUV', '创世纪', 1, 23, 19, '此后，亚伯拉罕把他妻子撒拉埋葬在迦南地幔利前的麦比拉田间的洞里。〈幔利就是希伯仑〉。'),
('CUV', '创世纪', 1, 23, 20, '从此，那块田和田间的洞就藉著赫人定准归与亚伯拉罕作坟地。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 24, 1, '亚伯拉罕年纪老迈，向来在一切事上耶和华都赐福给他。'),
('CUV', '创世纪', 1, 24, 2, '亚伯拉罕对管理他全业最老的仆人说：请你把手放在我大腿底下。'),
('CUV', '创世纪', 1, 24, 3, '我要叫你指著耶和华─天地的主起誓，不要为我儿子娶这迦南地中的女子为妻。'),
('CUV', '创世纪', 1, 24, 4, '你要往我本地本族去，为我的儿子以撒娶一个妻子。'),
('CUV', '创世纪', 1, 24, 5, '仆人对他说：倘若女子不肯跟我到这地方来，我必须将你的儿子带回你原出之地么？'),
('CUV', '创世纪', 1, 24, 6, '亚伯拉罕对他说：你要谨慎，不要带我的儿子回那里去。'),
('CUV', '创世纪', 1, 24, 7, '耶和华─天上的主曾带领我离开父家和本族的地，对我说话，向我起誓说：我要将这地赐给你的后裔。他必差遣使者在你面前，你就可以从那里为我儿子娶一个妻子。'),
('CUV', '创世纪', 1, 24, 8, '倘若女子不肯跟你来，我使你起的誓就与你无干了，只是不可带我的儿子回那里去。'),
('CUV', '创世纪', 1, 24, 9, '仆人就把手放在他主人亚伯拉罕的大腿底下，为这事向他起誓。'),
('CUV', '创世纪', 1, 24, 10, '那仆人从他主人的骆驼里取了十匹骆驼，并带些他主人各样的财物，起身往米所波大米去，到了拿鹤的城。'),
('CUV', '创世纪', 1, 24, 11, '天将晚，众女子出来打水的时候，他便叫骆驼跪在城外的水井那里。'),
('CUV', '创世纪', 1, 24, 12, '他说：耶和华─我主人亚伯拉罕的神阿，求你施恩给我主人亚伯拉罕，使我今日遇见好机会。'),
('CUV', '创世纪', 1, 24, 13, '我现今站在井旁，城内居民的女子们正出来打水。'),
('CUV', '创世纪', 1, 24, 14, '我向那一个女子说：请你拿下水瓶来，给我水喝，他若说：请喝！我也给你的骆驼喝，愿那女子就作你所预定给你仆人以撒的妻。这样，我便知道你施恩给我主人了。'),
('CUV', '创世纪', 1, 24, 15, '话还没有说完，不料，利百加肩头上扛著水瓶出来。利百加是彼土利所生的；彼土利是亚伯拉罕兄弟拿鹤妻子密迦的儿子。'),
('CUV', '创世纪', 1, 24, 16, '那女子容貌极其俊美，还是处女，也未曾有人亲近他。他下到井旁，打满了瓶，又上来。'),
('CUV', '创世纪', 1, 24, 17, '仆人跑上前去迎著他，说：求你将瓶里的水给我一点喝。'),
('CUV', '创世纪', 1, 24, 18, '女子说：我主请喝！就急忙拿下瓶来，托在手上给他喝。'),
('CUV', '创世纪', 1, 24, 19, '女子给他喝了，就说：我再为你的骆驼打水，叫骆驼也喝足。'),
('CUV', '创世纪', 1, 24, 20, '他就急忙把瓶里的水倒在槽里，又跑到井旁打水，就为所有的骆驼打上水来。'),
('CUV', '创世纪', 1, 24, 21, '那人定睛看他，一句话也不说，要晓得耶和华赐他通达的道路没有。'),
('CUV', '创世纪', 1, 24, 22, '骆驼喝足了，那人就拿一个金环，重半舍客勒，两个金镯，重十舍客勒，给了那女子，'),
('CUV', '创世纪', 1, 24, 23, '说：请告诉我，你是谁的女儿？你父亲家里有我们住宿的地方没有？'),
('CUV', '创世纪', 1, 24, 24, '女子说：我是密迦与拿鹤之子彼土利的女儿；'),
('CUV', '创世纪', 1, 24, 25, '又说：我们家里足有粮草，也有住宿的地方。'),
('CUV', '创世纪', 1, 24, 26, '那人就低头向耶和华下拜，'),
('CUV', '创世纪', 1, 24, 27, '说：耶和华─我主人亚伯拉罕的神是应当称颂的，因他不断地以慈爱诚实待我主人。至于我，耶和华在路上引领我，直走到我主人的兄弟家里。'),
('CUV', '创世纪', 1, 24, 28, '女子跑回去，照著这些话告诉他母亲和他家里的人。'),
('CUV', '创世纪', 1, 24, 29, '利百加有一个哥哥，名叫拉班，看见金环，又看见金镯在他妹子的手上，并听见他妹子利百加的话，说那人对我如此如此说。拉班就跑出来往井旁去，到那人跟前，见他仍站在骆驼旁边的井旁那里，'),
('CUV', '创世纪', 1, 24, 30, 'a'),
('CUV', '创世纪', 1, 24, 31, '便对他说：你这蒙耶和华赐福的，请进来，为甚么站在外边？我已经收拾了房屋，也为骆驼预备了地方。'),
('CUV', '创世纪', 1, 24, 32, '那人就进了拉班的家。拉班卸了骆驼，用草料喂上，拿水给那人和跟随的人洗脚，'),
('CUV', '创世纪', 1, 24, 33, '把饭摆在他面前，叫他吃，他却说：我不吃，等我说明白我的事情再吃。拉班说：请说。'),
('CUV', '创世纪', 1, 24, 34, '他说：我是亚伯拉罕的仆人。'),
('CUV', '创世纪', 1, 24, 35, '耶和华大大地赐福给我主人，使他昌大，又赐给他羊群、牛群、金银、仆婢、骆驼，和驴。'),
('CUV', '创世纪', 1, 24, 36, '我主人的妻子撒拉年老的时候给我主人生了一个儿子；我主人也将一切所有的都给了这个儿子。'),
('CUV', '创世纪', 1, 24, 37, '我主人叫我起誓说：你不要为我儿子娶迦南地的女子为妻。'),
('CUV', '创世纪', 1, 24, 38, '你要往我父家、我本族那里去，为我的儿子娶一个妻子。'),
('CUV', '创世纪', 1, 24, 39, '我对我主人说：恐怕女子不肯跟我来。'),
('CUV', '创世纪', 1, 24, 40, '他就说：我所事奉的耶和华必要差遣他的使者与你同去，叫你的道路通达，你就得以在我父家、我本族那里，给我的儿子娶一个妻子。'),
('CUV', '创世纪', 1, 24, 41, '只要你到了我本族那里，我使你起的誓就与你无干。他们若不把女子交给你，我使你起的誓也与你无干。'),
('CUV', '创世纪', 1, 24, 42, '我今日到了井旁，便说：耶和华─我主人亚伯拉罕的神阿，愿你叫我所行的道路通达。'),
('CUV', '创世纪', 1, 24, 43, '我如今站在井旁，对那一个出来打水的女子说：请你把你瓶里的水给我一点喝；'),
('CUV', '创世纪', 1, 24, 44, '他若说：你只管喝，我也为你的骆驼打水；愿那女子就作耶和华给我主人儿子所预定的妻。'),
('CUV', '创世纪', 1, 24, 45, '我心里的话还没有说完，利百加就出来，肩头上扛著水瓶，下到井旁打水。我便对他说：请你给我水喝。'),
('CUV', '创世纪', 1, 24, 46, '他就急忙从肩头上拿下瓶来，说：请喝！我也给你的骆驼喝。我便喝了；他又给我的骆驼喝了。'),
('CUV', '创世纪', 1, 24, 47, '我问他说：你是谁的女儿？他说：我是密迦与拿鹤之子彼土利的女儿。我就把环子戴在他鼻子上，把镯子戴在他两手上。'),
('CUV', '创世纪', 1, 24, 48, '随后我低头向耶和华下拜，称颂耶和华─我主人亚伯拉罕的神；因为他引导我走合式的道路，使我得著我主人兄弟的孙女，给我主人的儿子为妻。'),
('CUV', '创世纪', 1, 24, 49, '现在你们若愿以慈爱诚实待我主人，就告诉我；若不然，也告诉我，使我可以或向左，或向右。'),
('CUV', '创世纪', 1, 24, 50, '拉班和彼土利回答说：这事乃出于耶和华，我们不能向你说好说歹。'),
('CUV', '创世纪', 1, 24, 51, '看哪，利百加在你面前，可以将他带去，照著耶和华所说的，给你主人的儿子为妻。'),
('CUV', '创世纪', 1, 24, 52, '亚伯拉罕的仆人听见他们这话，就向耶和华俯伏在地。'),
('CUV', '创世纪', 1, 24, 53, '当下仆人拿出金器、银器，和衣服送给利百加，又将宝物送给他哥哥和他母亲。'),
('CUV', '创世纪', 1, 24, 54, '仆人和跟从他的人吃了喝了，住了一夜。早晨起来，仆人就说：请打发我回我主人那里去罢。'),
('CUV', '创世纪', 1, 24, 55, '利百加的哥哥和他母亲说：让女子同我们再住几天，至少十天，然后他可以去。'),
('CUV', '创世纪', 1, 24, 56, '仆人说：耶和华既赐给我通达的道路，你们不要耽误我，请打发我走，回我主人那里去罢。'),
('CUV', '创世纪', 1, 24, 57, '他们说：我们把女子叫来问问他，'),
('CUV', '创世纪', 1, 24, 58, '就叫了利百加来，问他说：你和这人同去么？利百加说：我去。'),
('CUV', '创世纪', 1, 24, 59, '于是他们打发妹子利百加和他的乳母，同亚伯拉罕的仆人，并跟从仆人的，都走了。'),
('CUV', '创世纪', 1, 24, 60, '他们就给利百加祝福说：我们的妹子阿，愿你作千万人的母！愿你的后裔得著仇敌的城门！'),
('CUV', '创世纪', 1, 24, 61, '利百加和他的使女们起来，骑上骆驼，跟著那仆人，仆人就带著利百加走了。'),
('CUV', '创世纪', 1, 24, 62, '那时，以撒住在南地，刚从庇耳•拉海•莱回来。'),
('CUV', '创世纪', 1, 24, 63, '天将晚，以撒出来在田间默想，举目一看，见来了些骆驼。'),
('CUV', '创世纪', 1, 24, 64, '利百加举目看见以撒，就急忙下了骆驼，'),
('CUV', '创世纪', 1, 24, 65, '问那仆人说：这田间走来迎接我们的是谁？仆人说：是我的主人。利百加就拿帕子蒙上脸。'),
('CUV', '创世纪', 1, 24, 66, '仆人就将所办的一切事都告诉以撒。'),
('CUV', '创世纪', 1, 24, 67, '以撒便领利百加进了他母亲撒拉的帐棚，娶了他为妻，并且爱他。以撒自从他母亲不在了，这才得了安慰。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 25, 1, '亚伯拉罕又娶了一妻，名叫基土拉。'),
('CUV', '创世纪', 1, 25, 2, '基土拉给他生了心兰、约珊、米但、米甸、伊施巴，和书亚。'),
('CUV', '创世纪', 1, 25, 3, '约珊生了示巴和底但。底但的子孙是亚书利族、利都是族，和利乌米族。'),
('CUV', '创世纪', 1, 25, 4, '米甸的儿子是以法、以弗、哈诺、亚比大，和以勒大。这都是基土拉的子孙。'),
('CUV', '创世纪', 1, 25, 5, '亚伯拉罕将一切所有的都给了以撒。'),
('CUV', '创世纪', 1, 25, 6, '亚伯拉罕把财物分给他庶出的众子，趁著自己还在世的时候打发他们离开他的儿子以撒，往东方去。'),
('CUV', '创世纪', 1, 25, 7, '亚伯拉罕一生的年日是一百七十五岁。'),
('CUV', '创世纪', 1, 25, 8, '亚伯拉罕寿高年迈，气绝而死，归到他列祖(原文作本民)那里。'),
('CUV', '创世纪', 1, 25, 9, '他两个儿子以撒、以实玛利把他埋葬在麦比拉洞里。这洞在幔利前、赫人琐辖的儿子以弗仑的田中，'),
('CUV', '创世纪', 1, 25, 10, '就是亚伯拉罕向赫人买的那块田。亚伯拉罕和他妻子撒拉都葬在那里。'),
('CUV', '创世纪', 1, 25, 11, '亚伯拉罕死了以后，神赐福给他的儿子以撒。以撒靠近庇耳拉海莱居住。'),
('CUV', '创世纪', 1, 25, 12, '撒拉的使女埃及人夏甲给亚伯拉罕所生的儿子是以实玛利。'),
('CUV', '创世纪', 1, 25, 13, '以实玛利儿子们的名字，按著他们的家谱记在下面。以实玛利的长子是尼拜约，又有基达、亚德别、米比衫、'),
('CUV', '创世纪', 1, 25, 14, '米施玛、度玛、玛撒、'),
('CUV', '创世纪', 1, 25, 15, '哈大、提玛、伊突、拿非施、基底玛。'),
('CUV', '创世纪', 1, 25, 16, '这是以实玛利众子的名字，照著他们的村庄、营寨，作了十二族的族长。'),
('CUV', '创世纪', 1, 25, 17, '以实玛利享寿一百三十七岁，气绝而死，归到他列祖(原文作本民)那里。'),
('CUV', '创世纪', 1, 25, 18, '他子孙的住处在他众弟兄东边，从哈腓拉直到埃及前的书珥，正在亚述的道上。'),
('CUV', '创世纪', 1, 25, 19, '亚伯拉罕的儿子以撒的后代记在下面。亚伯拉罕生以撒。'),
('CUV', '创世纪', 1, 25, 20, '以撒娶利百加为妻的时候正四十岁。利百加是巴旦亚兰地的亚兰人彼土利的女儿，是亚兰人拉班的妹子。'),
('CUV', '创世纪', 1, 25, 21, '以撒因他妻子不生育，就为他祈求耶和华；耶和华应允他的祈求，他的妻子利百加就怀了孕。'),
('CUV', '创世纪', 1, 25, 22, '孩子们在他腹中彼此相争，他就说：若是这样，我为甚么活著呢(或作我为甚么如此呢)？他就去求问耶和华。'),
('CUV', '创世纪', 1, 25, 23, '耶和华对他说：两国在你腹内；两族要从你身上出来。这族必强于那族；将来大的要服事小的。'),
('CUV', '创世纪', 1, 25, 24, '生产的日子到了，腹中果然是双子。'),
('CUV', '创世纪', 1, 25, 25, '先产的身体发红，浑身有毛，如同皮衣，他们就给他起名叫以扫(就是有毛的意思)。'),
('CUV', '创世纪', 1, 25, 26, '随后又生了以扫的兄弟，手抓住以扫的脚跟，因此给他起名叫雅各(就是抓住的意思)。利百加生下两个儿子的时候，以撒年正六十岁。'),
('CUV', '创世纪', 1, 25, 27, '两个孩子渐渐长大，以扫善于打猎，常在田野；雅各为人安静，常住在帐棚里。'),
('CUV', '创世纪', 1, 25, 28, '以撒爱以扫，因为常吃他的野味；利百加却爱雅各。'),
('CUV', '创世纪', 1, 25, 29, '有一天，雅各熬汤，以扫从田野回来累昏了。'),
('CUV', '创世纪', 1, 25, 30, '以扫对雅各说：我累昏了，求你把这红汤给我喝。因此以扫又叫以东(就是红的意思)。'),
('CUV', '创世纪', 1, 25, 31, '雅各说：你今日把长子的名分卖给我罢。'),
('CUV', '创世纪', 1, 25, 32, '以扫说：我将要死，这长子的名分于我有甚么益处呢？'),
('CUV', '创世纪', 1, 25, 33, '雅各说：你今日对我起誓罢。以扫就对他起了誓，把长子的名分卖给雅各。'),
('CUV', '创世纪', 1, 25, 34, '于是雅各将饼和红豆汤给了以扫，以扫吃了喝了，便起来走了。这就是以扫轻看了他长子的名分。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 26, 1, '在亚伯拉罕的日子，那地有一次饥荒；这时又有饥荒，以撒就往基拉耳去，到非利士人的王亚比米勒那里。'),
('CUV', '创世纪', 1, 26, 2, '耶和华向以撒显现，说：你不要下去，要住在我所指示你的地。'),
('CUV', '创世纪', 1, 26, 3, '你寄居在这地，我必与你同在，赐福给你，因为我要将这些地都赐给你和你的后裔。我必坚定我向你父亚伯拉罕所起的誓。'),
('CUV', '创世纪', 1, 26, 4, '我要加增你的后裔，像天上的星那样多，又要将这些地都赐给你的后裔。并且地上万国必因你的后裔得福─'),
('CUV', '创世纪', 1, 26, 5, '都因亚伯拉罕听从我的话，遵守我的吩咐和我的命令、律例、法度。'),
('CUV', '创世纪', 1, 26, 6, '以撒就住在基拉耳。'),
('CUV', '创世纪', 1, 26, 7, '那地方的人问到他的妻子，他便说：那是我的妹子。原来他怕说：是我的妻子；他心里想：恐怕这地方的人为利百加的缘故杀我，因为他容貌俊美。'),
('CUV', '创世纪', 1, 26, 8, '他在那里住了许久。有一天，非利士人的王亚比米勒从窗户里往外观看，见以撒和他的妻子利百加戏玩。'),
('CUV', '创世纪', 1, 26, 9, '亚比米勒召了以撒来，对他说：他实在是你的妻子，你怎么说他是你的妹子？以撒说：我心里想，恐怕我因他而死。'),
('CUV', '创世纪', 1, 26, 10, '亚比米勒说：你向我们做的是甚么事呢？民中险些有人和你的妻同寝，把我们陷在罪里。'),
('CUV', '创世纪', 1, 26, 11, '于是亚比米勒晓谕众民说：凡沾著这个人，或是他妻子的，定要把他治死。'),
('CUV', '创世纪', 1, 26, 12, '以撒在那地耕种，那一年有百倍的收成。耶和华赐福给他，'),
('CUV', '创世纪', 1, 26, 13, '他就昌大，日增月盛，成了大富户。'),
('CUV', '创世纪', 1, 26, 14, '他有羊群牛群，又有许多仆人，非利士人就嫉妒他。'),
('CUV', '创世纪', 1, 26, 15, '当他父亲亚伯拉罕在世的日子，他父亲的仆人所挖的井，非利士人全都塞住，填满了土。'),
('CUV', '创世纪', 1, 26, 16, '亚比米勒对以撒说：你离开我们去罢。因为你比我们强盛得多。'),
('CUV', '创世纪', 1, 26, 17, '以撒就离开那里，在基拉耳谷支搭帐棚，住在那里。'),
('CUV', '创世纪', 1, 26, 18, '当他父亲亚伯拉罕在世之日所挖的水井因非利士人在亚伯拉罕死后塞住了，以撒就重新挖出来，仍照他父亲所叫的叫那些井的名字。'),
('CUV', '创世纪', 1, 26, 19, '以撒的仆人在谷中挖井，便得了一口活水井。'),
('CUV', '创世纪', 1, 26, 20, '基拉耳的牧人与以撒的牧人争竞，说：这水是我们的。以撒就给那井起名叫埃色(就是相争的意思)，因为他们和他相争。'),
('CUV', '创世纪', 1, 26, 21, '以撒的仆人又挖了一口井，他们又为这井争竞，因此以撒给这井起名叫西提拿(就是为敌的意思)。'),
('CUV', '创世纪', 1, 26, 22, '以撒离开那里，又挖了一口井，他们不为这井争竞了，他就给那井起名叫利河伯(就是宽阔的意思)。他说：耶和华现在给我们宽阔之地，我们必在这地昌盛。'),
('CUV', '创世纪', 1, 26, 23, '以撒从那里上别是巴去。'),
('CUV', '创世纪', 1, 26, 24, '当夜耶和华向他显现，说：我是你父亲亚伯拉罕的神，不要惧怕！因为我与你同在，要赐福给你，并要为我仆人亚伯拉罕的缘故，使你的后裔繁多。'),
('CUV', '创世纪', 1, 26, 25, '以撒就在那里筑了一座坛，求告耶和华的名，并且支搭帐棚；他的仆人便在那里挖了一口井。'),
('CUV', '创世纪', 1, 26, 26, '亚比米勒，同他的朋友亚户撒和他的军长非各，从基拉耳来见以撒。'),
('CUV', '创世纪', 1, 26, 27, '以撒对他们说：你们既然恨我，打发我走了，为甚么到我这里来呢？'),
('CUV', '创世纪', 1, 26, 28, '他们说：我们明明的看见耶和华与你同在，便说，不如我们两下彼此起誓，彼此立约，'),
('CUV', '创世纪', 1, 26, 29, '使你不害我们，正如我们未曾害你，一味的厚待你，并且打发你平平安安的走。你是蒙耶和华赐福的了。'),
('CUV', '创世纪', 1, 26, 30, '以撒就为他们设摆筵席，他们便吃了喝了。'),
('CUV', '创世纪', 1, 26, 31, '他们清早起来彼此起誓。以撒打发他们走，他们就平平安安的离开他走了。'),
('CUV', '创世纪', 1, 26, 32, '那一天，以撒的仆人来，将挖井的事告诉他说：我们得了水了。'),
('CUV', '创世纪', 1, 26, 33, '他就给那井起名叫示巴；因此那城叫做别是巴，直到今日。'),
('CUV', '创世纪', 1, 26, 34, '以扫四十岁的时候娶了赫人比利的女儿犹滴，与赫人以伦的女儿巴实抹为妻。'),
('CUV', '创世纪', 1, 26, 35, '他们常使以撒和利百加心里愁烦。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 27, 1, '以撒年老，眼睛昏花，不能看见，就叫了他大儿子以扫来，说：我儿。以扫说：我在这里。'),
('CUV', '创世纪', 1, 27, 2, '他说：我如今老了，不知道那一天死。'),
('CUV', '创世纪', 1, 27, 3, '现在拿你的器械，就是箭囊和弓，往田野去为我打猎，'),
('CUV', '创世纪', 1, 27, 4, '照我所爱的做成美味，拿来给我吃，使我在未死之先给你祝福。'),
('CUV', '创世纪', 1, 27, 5, '以撒对他儿子以扫说话，利百加也听见了。以扫往田野去打猎，要得野味带来。'),
('CUV', '创世纪', 1, 27, 6, '利百加就对他儿子雅各说：我听见你父亲对你哥哥以扫说：'),
('CUV', '创世纪', 1, 27, 7, '你去把野兽带来，做成美味给我吃，我好在未死之先，在耶和华面前给你祝福。'),
('CUV', '创世纪', 1, 27, 8, '现在，我儿，你要照著我所吩咐你的，听从我的话。'),
('CUV', '创世纪', 1, 27, 9, '你到羊群里去，给我拿两只肥山羊羔来，我便照你父亲所爱的给他做成美味。'),
('CUV', '创世纪', 1, 27, 10, '你拿到你父亲那里给他吃，使他在未死之先给你祝福。'),
('CUV', '创世纪', 1, 27, 11, '雅各对他母亲利百加说：我哥哥以扫浑身是有毛的，我身上是光滑的；'),
('CUV', '创世纪', 1, 27, 12, '倘若我父亲摸著我，必以我为欺哄人的，我就招咒诅，不得祝福。'),
('CUV', '创世纪', 1, 27, 13, '他母亲对他说：我儿，你招的咒诅归到我身上；你只管听我的话，去把羊羔给我拿来。'),
('CUV', '创世纪', 1, 27, 14, '他便去拿来，交给他母亲；他母亲就照他父亲所爱的做成美味。'),
('CUV', '创世纪', 1, 27, 15, '利百加又把家里所存大儿子以扫上好的衣服给他小儿子雅各穿上，'),
('CUV', '创世纪', 1, 27, 16, '又用山羊羔皮包在雅各的手上和颈项的光滑处，'),
('CUV', '创世纪', 1, 27, 17, '就把所做的美味和饼交在他儿子雅各的手里。'),
('CUV', '创世纪', 1, 27, 18, '雅各到他父亲那里说：我父亲！他说：我在这里。我儿，你是谁？'),
('CUV', '创世纪', 1, 27, 19, '雅各对他父亲说：我是你的长子以扫；我已照你所吩咐我的行了。请起来坐著，吃我的野味，好给我祝福。'),
('CUV', '创世纪', 1, 27, 20, '以撒对他儿子说：我儿，你如何找得这么快呢？他说：因为耶和华─你的神使我遇见好机会得著的。'),
('CUV', '创世纪', 1, 27, 21, '以撒对雅各说：我儿，你近前来，我摸摸你，知道你真是我的儿子以扫不是？'),
('CUV', '创世纪', 1, 27, 22, '雅各就挨近他父亲以撒。以撒摸著他，说：声音是雅各的声音，手却是以扫的手。'),
('CUV', '创世纪', 1, 27, 23, '以撒就辨不出他来；因为他手上有毛，像他哥哥以扫的手一样，就给他祝福；'),
('CUV', '创世纪', 1, 27, 24, '又说：你真是我儿子以扫么？他说：我是。'),
('CUV', '创世纪', 1, 27, 25, '以撒说：你递给我，我好吃我儿子的野味，给你祝福。雅各就递给他，他便吃了，又拿酒给他，他也喝了。'),
('CUV', '创世纪', 1, 27, 26, '他父亲以撒对他说：我儿，你上前来与我亲嘴。'),
('CUV', '创世纪', 1, 27, 27, '他就上前与父亲亲嘴。他父亲一闻他衣服上的香气，就给他祝福，说：我儿的香气如同耶和华赐福之田地的香气一样。'),
('CUV', '创世纪', 1, 27, 28, '愿神赐你天上的甘露，地上的肥土，并许多五谷新酒。'),
('CUV', '创世纪', 1, 27, 29, '愿多民事奉你，多国跪拜你。愿你作你弟兄的主；你母亲的儿子向你跪拜。凡咒诅你的，愿他受咒诅；为你祝福的，愿他蒙福。'),
('CUV', '创世纪', 1, 27, 30, '以撒为雅各祝福已毕，雅各从他父亲那里才出来，他哥哥以扫正打猎回来，'),
('CUV', '创世纪', 1, 27, 31, '也做了美味，拿来给他父亲，说：请父亲起来，吃你儿子的野味，好给我祝福。'),
('CUV', '创世纪', 1, 27, 32, '他父亲以撒对他说：你是谁？他说：我是你的长子以扫。'),
('CUV', '创世纪', 1, 27, 33, '以撒就大大地战兢，说：你未来之先，是谁得了野味拿来给我呢？我已经吃了，为他祝福；他将来也必蒙福。'),
('CUV', '创世纪', 1, 27, 34, '以扫听了他父亲的话，就放声痛哭，说：我父阿，求你也为我祝福！'),
('CUV', '创世纪', 1, 27, 35, '以撒说：你兄弟已经用诡计来将你的福分夺去了。'),
('CUV', '创世纪', 1, 27, 36, '以扫说：他名雅各，岂不是正对么？因为他欺骗了我两次：他从前夺了我长子的名分，你看，他现在又夺了我的福分。以扫又说：你没有留下为我可祝的福么？'),
('CUV', '创世纪', 1, 27, 37, '以撒回答以扫说：我已立他为你的主，使他的弟兄都给他作仆人，并赐他五谷新酒可以养生。我儿，现在我还能为你做甚么呢？'),
('CUV', '创世纪', 1, 27, 38, '以扫对他父亲说：父阿，你只有一样可祝的福么？我父阿，求你也为我祝福！以扫就放声而哭。'),
('CUV', '创世纪', 1, 27, 39, '他父亲以撒说：地上的肥土必为你所住；天上的甘露必为你所得。'),
('CUV', '创世纪', 1, 27, 40, '你必倚靠刀剑度日，又必事奉你的兄弟；到你强盛的时候，必从你颈项上挣开他的轭。'),
('CUV', '创世纪', 1, 27, 41, '以扫因他父亲给雅各祝的福，就怨恨雅各，心里说：为我父亲居丧的日子近了，到那时候，我要杀我的兄弟雅各。'),
('CUV', '创世纪', 1, 27, 42, '有人把利百加大儿子以扫的话告诉利百加，他就打发人去，叫了他小儿子雅各来，对他说：你哥哥以扫想要杀你，报仇雪恨。'),
('CUV', '创世纪', 1, 27, 43, '现在，我儿，你要听我的话：起来，逃往哈兰、我哥哥拉班那里去，'),
('CUV', '创世纪', 1, 27, 44, '同他住些日子，直等你哥哥的怒气消了。'),
('CUV', '创世纪', 1, 27, 45, '你哥哥向你消了怒气，忘了你向他所做的事，我便打发人去把你从那里带回来。为甚么一日丧你们二人呢？'),
('CUV', '创世纪', 1, 27, 46, '利百加对以撒说：我因这赫人的女子连性命都厌烦了；倘若雅各也娶赫人的女子为妻，像这些一样，我活著还有甚么益处呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 28, 1, '以撒叫了雅各来，给他祝福，并嘱咐他说：你不要娶迦南的女子为妻。'),
('CUV', '创世纪', 1, 28, 2, '你起身往巴旦亚兰去，到你外祖彼土利家里，在你母舅拉班的女儿中娶一女为妻。'),
('CUV', '创世纪', 1, 28, 3, '愿全能的神赐福给你，使你生养众多，成为多族，'),
('CUV', '创世纪', 1, 28, 4, '将应许亚伯拉罕的福赐给你和你的后裔，使你承受你所寄居的地为业，就是神赐给亚伯拉罕的地。'),
('CUV', '创世纪', 1, 28, 5, '以撒打发雅各走了，他就往巴旦亚兰去，到亚兰人彼土利的儿子拉班那里。拉班是雅各、以扫的母舅。'),
('CUV', '创世纪', 1, 28, 6, '以扫见以撒已经给雅各祝福，而且打发他往巴旦亚兰去，在那里娶妻，并见祝福的时候嘱咐他说：不要娶迦南的女子为妻，'),
('CUV', '创世纪', 1, 28, 7, '又见雅各听从父母的话往巴旦亚兰去了，'),
('CUV', '创世纪', 1, 28, 8, '以扫就晓得他父亲以撒看不中迦南的女子，'),
('CUV', '创世纪', 1, 28, 9, '便往以实玛利那里去，在他二妻之外又娶了玛哈拉为妻。他是亚伯拉罕儿子以实玛利的女儿，尼拜约的妹子。'),
('CUV', '创世纪', 1, 28, 10, '雅各出了别是巴，向哈兰走去；'),
('CUV', '创世纪', 1, 28, 11, '到了一个地方，因为太阳落了，就在那里住宿，便拾起那地方的一块石头枕在头下，在那里躺卧睡了，'),
('CUV', '创世纪', 1, 28, 12, '梦见一个梯子立在地上，梯子的头顶著天，有神的使者在梯子上，上去下来。'),
('CUV', '创世纪', 1, 28, 13, '耶和华站在梯子以上(或作站在他旁边)，说：我是耶和华─你祖亚伯拉罕的神，也是以撒的神；我要将你现在所躺卧之地赐给你和你的后裔。'),
('CUV', '创世纪', 1, 28, 14, '你的后裔必像地上的尘沙那样多，必向东西南北开展；地上万族必因你和你的后裔得福。'),
('CUV', '创世纪', 1, 28, 15, '我也与你同在。你无论往那里去，我必保佑你，领你归回这地，总不离弃你，直到我成全了向你所应许的。'),
('CUV', '创世纪', 1, 28, 16, '雅各睡醒了，说：耶和华真在这里，我竟不知道！'),
('CUV', '创世纪', 1, 28, 17, '就惧怕，说：这地方何等可畏！这不是别的，乃是神的殿，也是天的门。'),
('CUV', '创世纪', 1, 28, 18, '雅各清早起来，把所枕的石头立作柱子，浇油在上面。'),
('CUV', '创世纪', 1, 28, 19, '他就给那地方起名叫伯特利(就是神殿的意思)；但那地方起先名叫路斯。'),
('CUV', '创世纪', 1, 28, 20, '雅各许愿说：神若与我同在，在我所行的路上保佑我，又给我食物吃，衣服穿，'),
('CUV', '创世纪', 1, 28, 21, '使我平平安安地回到我父亲的家，我就必以耶和华为我的神。'),
('CUV', '创世纪', 1, 28, 22, '我所立为柱子的石头也必作神的殿，凡你所赐给我的，我必将十分之一献给你。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 29, 1, '雅各起行，到了东方人之地，'),
('CUV', '创世纪', 1, 29, 2, '看见田间有一口井，有三群羊卧在井旁；因为人饮羊群都是用那井里的水。井口上的石头是大的。'),
('CUV', '创世纪', 1, 29, 3, '常有羊群在那里聚集，牧人把石头转离井口饮羊，随后又把石头放在井口的原处。'),
('CUV', '创世纪', 1, 29, 4, '雅各对牧人说：弟兄们，你们是那里来的？他们说：我们是哈兰来的。'),
('CUV', '创世纪', 1, 29, 5, '他问他们说：拿鹤的孙子拉班，你们认识么？他们说：我们认识。'),
('CUV', '创世纪', 1, 29, 6, '雅各说：他平安么？他们说：平安。看哪，他女儿拉结领著羊来了。'),
('CUV', '创世纪', 1, 29, 7, '雅各说：日头还高，不是羊群聚集的时候，你们不如饮羊，再去放一放。'),
('CUV', '创世纪', 1, 29, 8, '他们说：我们不能，必等羊群聚齐，人把石头转离井口才可饮羊。'),
('CUV', '创世纪', 1, 29, 9, '雅各正和他们说话的时候，拉结领著他父亲的羊来了，因为那些羊是他牧放的。'),
('CUV', '创世纪', 1, 29, 10, '雅各看见母舅拉班的女儿拉结和母舅拉班的羊群，就上前把石头转离井口，饮他母舅拉班的羊群。'),
('CUV', '创世纪', 1, 29, 11, '雅各与拉结亲嘴，就放声而哭。'),
('CUV', '创世纪', 1, 29, 12, '雅各告诉拉结，自己是他父亲的外甥，是利百加的儿子，拉结就跑去告诉他父亲。'),
('CUV', '创世纪', 1, 29, 13, '拉班听见外甥雅各的信息，就跑去迎接，抱著他，与他亲嘴，领他到自己的家。雅各将一切的情由告诉拉班。'),
('CUV', '创世纪', 1, 29, 14, '拉班对他说：你实在是我的骨肉。雅各就和他同住了一个月。'),
('CUV', '创世纪', 1, 29, 15, '拉班对雅各说：你虽是我的骨肉(原文作弟兄)，岂可白白地服事我？请告诉我，你要甚么为工价？'),
('CUV', '创世纪', 1, 29, 16, '拉班有两个女儿，大的名叫利亚，小的名叫拉结。'),
('CUV', '创世纪', 1, 29, 17, '利亚的眼睛没有神气，拉结却生得美貌俊秀。'),
('CUV', '创世纪', 1, 29, 18, '雅各爱拉结，就说：我愿为你小女儿拉结服事你七年。'),
('CUV', '创世纪', 1, 29, 19, '拉班说：我把他给你，胜似给别人，你与我同住罢！'),
('CUV', '创世纪', 1, 29, 20, '雅各就为拉结服事了七年；他因为深爱拉结，就看这七年如同几天。'),
('CUV', '创世纪', 1, 29, 21, '雅各对拉班说：日期已经满了，求你把我的妻子给我，我好与他同房。'),
('CUV', '创世纪', 1, 29, 22, '拉班就摆设筵席，请齐了那地方的众人。'),
('CUV', '创世纪', 1, 29, 23, '到晚上，拉班将女儿利亚送来给雅各，雅各就与他同房。'),
('CUV', '创世纪', 1, 29, 24, '拉班又将婢女悉帕给女儿利亚作使女。'),
('CUV', '创世纪', 1, 29, 25, '到了早晨，雅各一看是利亚，就对拉班说：你向我做的是甚么事呢？我服事你，不是为拉结么？你为甚么欺哄我呢？'),
('CUV', '创世纪', 1, 29, 26, '拉班说：大女儿还没有给人，先把小女儿给人，在我们这地方没有这规矩。'),
('CUV', '创世纪', 1, 29, 27, '你为这个满了七日，我就把那个也给你，你再为他服事我七年。'),
('CUV', '创世纪', 1, 29, 28, '雅各就如此行。满了利亚的七日，拉班便将女儿拉结给雅各为妻。'),
('CUV', '创世纪', 1, 29, 29, '拉班又将婢女辟拉给女儿拉结作使女。'),
('CUV', '创世纪', 1, 29, 30, '雅各也与拉结同房，并且爱拉结胜似爱利亚，于是又服事了拉班七年。'),
('CUV', '创世纪', 1, 29, 31, '耶和华见利亚失宠(原文作被恨；下同)，就使他生育，拉结却不生育。'),
('CUV', '创世纪', 1, 29, 32, '利亚怀孕生子，就给他起名叫流便(就是有儿子的意思)，因而说：耶和华看见我的苦情，如今我的丈夫必爱我。'),
('CUV', '创世纪', 1, 29, 33, '他又怀孕生子，就说：耶和华因为听见我失宠，所以又赐给我这个儿子，于是给他起名叫西缅(就是听见的意思)。'),
('CUV', '创世纪', 1, 29, 34, '他又怀孕生子，起名叫利未(就是联合的意思)，说：我给丈夫生了三个儿子，他必与我联合。'),
('CUV', '创世纪', 1, 29, 35, '他又怀孕生子，说：这回我要赞美耶和华，因此给他起名叫犹大(就是赞美的意思)。这才停了生育。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 30, 1, '拉结见自己不给雅各生子，就嫉妒他姊姊，对雅各说：你给我孩子，不然我就死了。'),
('CUV', '创世纪', 1, 30, 2, '雅各向拉结生气，说：叫你不生育的是神，我岂能代替他作主呢？'),
('CUV', '创世纪', 1, 30, 3, '拉结说：有我的使女辟拉在这里，你可以与他同房，使他生子在我膝下，我便因他也得孩子(原文作被建立)。'),
('CUV', '创世纪', 1, 30, 4, '拉结就把他的使女辟拉给丈夫为妾；雅各便与他同房，'),
('CUV', '创世纪', 1, 30, 5, '辟拉就怀孕，给雅各生了一个儿子。'),
('CUV', '创世纪', 1, 30, 6, '拉结说：神伸了我的冤，也听了我的声音，赐我一个儿子，因此给他起名叫但(就是伸冤的意思)。'),
('CUV', '创世纪', 1, 30, 7, '拉结的使女辟拉又怀孕，给雅各生了第二个儿子。'),
('CUV', '创世纪', 1, 30, 8, '拉结说：我与我姊姊大大相争，并且得胜，于是给他起名叫拿弗他利(就是相争的意思)。'),
('CUV', '创世纪', 1, 30, 9, '利亚见自己停了生育，就把使女悉帕给雅各为妾。'),
('CUV', '创世纪', 1, 30, 10, '利亚的使女悉帕给雅各生了一个儿子。'),
('CUV', '创世纪', 1, 30, 11, '利亚说：万幸！于是给他起名叫迦得(就是万幸的意思)。'),
('CUV', '创世纪', 1, 30, 12, '利亚的使女悉帕又给雅各生了第二个儿子。'),
('CUV', '创世纪', 1, 30, 13, '利亚说：我有福阿，众女子都要称我是有福的，于是给他起名叫亚设(就是有福的意思)。'),
('CUV', '创世纪', 1, 30, 14, '割麦子的时候，流便往田里去，寻见风茄，拿来给他母亲利亚。拉结对利亚说：请你把你儿子的风茄给我些。'),
('CUV', '创世纪', 1, 30, 15, '利亚说：你夺了我的丈夫还算小事么？你又要夺我儿子的风茄么？拉结说：为你儿子的风茄，今夜他可以与你同寝。'),
('CUV', '创世纪', 1, 30, 16, '到了晚上，雅各从田里回来，利亚出来迎接他，说：你要与我同寝，因为我实在用我儿子的风茄把你雇下了。那一夜，雅各就与他同寝。'),
('CUV', '创世纪', 1, 30, 17, '神应允了利亚，他就怀孕，给雅各生了第五个儿子。'),
('CUV', '创世纪', 1, 30, 18, '利亚说：神给了我价值，因为我把使女给了我丈夫，于是给他起名叫以萨迦(就是价值的意思)。'),
('CUV', '创世纪', 1, 30, 19, '利亚又怀孕，给雅各生了第六个儿子。'),
('CUV', '创世纪', 1, 30, 20, '利亚说：神赐我厚赏；我丈夫必与我同住，因我给他生了六个儿子，于是给他起名西布伦(就是同住的意思)。'),
('CUV', '创世纪', 1, 30, 21, '后来又生了一个女儿，给他起名叫底拿。'),
('CUV', '创世纪', 1, 30, 22, '神顾念拉结，应允了他，使他能生育。'),
('CUV', '创世纪', 1, 30, 23, '拉结怀孕生子，说：神除去了我的羞耻，'),
('CUV', '创世纪', 1, 30, 24, '就给他起名叫约瑟(就是增添的意思)，意思说：愿耶和华再增添我一个儿子。'),
('CUV', '创世纪', 1, 30, 25, '拉结生约瑟之后，雅各对拉班说：请打发我走，叫我回到我本乡本土去。'),
('CUV', '创世纪', 1, 30, 26, '请你把我服事你所得的妻子和儿女给我，让我走；我怎样服事你，你都知道。'),
('CUV', '创世纪', 1, 30, 27, '拉班对他说：我若在你眼前蒙恩，请你仍与我同住，因为我已算定，耶和华赐福与我是为你的缘故；'),
('CUV', '创世纪', 1, 30, 28, '又说：请你定你的工价，我就给你。'),
('CUV', '创世纪', 1, 30, 29, '雅各对他说：我怎样服事你，你的牲畜在我手里怎样，是你知道的。'),
('CUV', '创世纪', 1, 30, 30, '我未来之先，你所有的很少，现今却发大众多，耶和华随我的脚步赐福与你。如今，我甚么时候才为自己兴家立业呢？'),
('CUV', '创世纪', 1, 30, 31, '拉班说：我当给你甚么呢？雅各说：甚么你也不必给我，只有一件事，你若应承，我便仍旧牧放你的羊群。'),
('CUV', '创世纪', 1, 30, 32, '今天我要走遍你的羊群，把绵羊中凡有点的、有斑的，和黑色的，并山羊中凡有斑的、有点的，都挑出来；将来这一等的就算我的工价。'),
('CUV', '创世纪', 1, 30, 33, '以后你来查看我的工价，凡在我手里的山羊不是有点有斑的，绵羊不是黑色的，那就算是我偷的；这样便可证出我的公义来。'),
('CUV', '创世纪', 1, 30, 34, '拉班说：好阿！我情愿照著你的话行。'),
('CUV', '创世纪', 1, 30, 35, '当日，拉班把有纹的、有斑的公山羊，有点的、有斑的、有杂白纹的母山羊，并黑色的绵羊，都挑出来，交在他儿子们的手下，'),
('CUV', '创世纪', 1, 30, 36, '又使自己和雅各相离三天的路程。雅各就牧养拉班其余的羊。'),
('CUV', '创世纪', 1, 30, 37, '雅各拿杨树、杏树、枫树的嫩枝，将皮剥成白纹，使枝子露出白的来，'),
('CUV', '创世纪', 1, 30, 38, '将剥了皮的枝子，对著羊群，插在饮羊的水沟里和水槽里，羊来喝的时候，牝牡配合。'),
('CUV', '创世纪', 1, 30, 39, '羊对著枝子配合，就生下有纹的、有点的、有斑的来。'),
('CUV', '创世纪', 1, 30, 40, '雅各把羊羔分出来，使拉班的羊与这有纹和黑色的羊相对，把自己的羊另放一处，不叫他和拉班的羊混杂。'),
('CUV', '创世纪', 1, 30, 41, '到羊群肥壮配合的时候，雅各就把枝子插在水沟里，使羊对著枝子配合。'),
('CUV', '创世纪', 1, 30, 42, '只是到羊瘦弱配合的时候就不插枝子。这样，瘦弱的就归拉班，肥壮的就归雅各。'),
('CUV', '创世纪', 1, 30, 43, '于是雅各极其发大，得了许多的羊群、仆婢、骆驼，和驴。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 31, 1, '雅各听见拉班的儿子们有话说：雅各把我们父亲所有的都夺了去，并藉著我们父亲的，得了这一切的荣耀(或作财)。'),
('CUV', '创世纪', 1, 31, 2, '雅各见拉班的气色向他不如从前了。'),
('CUV', '创世纪', 1, 31, 3, '耶和华对雅各说：你要回你祖、你父之地，到你亲族那里去，我必与你同在。'),
('CUV', '创世纪', 1, 31, 4, '雅各就打发人，叫拉结和利亚到田野羊群那里来，'),
('CUV', '创世纪', 1, 31, 5, '对他们说：我看你们父亲的气色向我不如从前了；但我父亲的神向来与我同在。'),
('CUV', '创世纪', 1, 31, 6, '你们也知道，我尽了我的力量服事你们的父亲。'),
('CUV', '创世纪', 1, 31, 7, '你们的父亲欺哄我，十次改了我的工价；然而神不容他害我。'),
('CUV', '创世纪', 1, 31, 8, '他若说：有点的归你作工价，羊群所生的都有点；他若说：有纹的归你作工价，羊群所生的都有纹。'),
('CUV', '创世纪', 1, 31, 9, '这样，神把你们父亲的牲畜夺来赐给我了。'),
('CUV', '创世纪', 1, 31, 10, '羊配合的时候，我梦中举目一看，见跳母羊的公羊都是有纹的、有点的、有花斑的。'),
('CUV', '创世纪', 1, 31, 11, '神的使者在那梦中呼叫我说：雅各。我说：我在这里。'),
('CUV', '创世纪', 1, 31, 12, '他说：你举目观看，跳母羊的公羊都是有纹的、有点的、有花斑的；凡拉班向你所做的，我都看见了。'),
('CUV', '创世纪', 1, 31, 13, '我是伯特利的神；你在那里用油浇过柱子，向我许过愿。现今你起来，离开这地，回你本地去罢！'),
('CUV', '创世纪', 1, 31, 14, '拉结和利亚回答雅各说：在我们父亲的家里还有我们可得的分么？还有我们的产业么？'),
('CUV', '创世纪', 1, 31, 15, '我们不是被他当作外人么？因为他卖了我们，吞了我们的价值。'),
('CUV', '创世纪', 1, 31, 16, '神从我们父亲所夺出来的一切财物，那就是我们和我们孩子们的。现今凡神所吩咐你的，你只管去行罢！'),
('CUV', '创世纪', 1, 31, 17, '雅各起来，使他的儿子和妻子都骑上骆驼，'),
('CUV', '创世纪', 1, 31, 18, '又带著他在巴旦亚兰所得的一切牲畜和财物，往迦南地、他父亲以撒那里去了。'),
('CUV', '创世纪', 1, 31, 19, '当时拉班剪羊毛去了，拉结偷了他父亲家中的神像。'),
('CUV', '创世纪', 1, 31, 20, '雅各背著亚兰人拉班偷走了，并不告诉他，'),
('CUV', '创世纪', 1, 31, 21, '就带著所有的逃跑。他起身过大河，面向基列山行去。'),
('CUV', '创世纪', 1, 31, 22, '到第三日，有人告诉拉班，雅各逃跑了。'),
('CUV', '创世纪', 1, 31, 23, '拉班带领他的众弟兄去追赶，追了七日，在基列山就追上了。'),
('CUV', '创世纪', 1, 31, 24, '夜间，神到亚兰人拉班那里，在梦中对他说：你要小心，不可与雅各说好说歹。'),
('CUV', '创世纪', 1, 31, 25, '拉班追上雅各。雅各在山上支搭帐棚；拉班和他的众弟兄也在基列山上支搭帐棚。'),
('CUV', '创世纪', 1, 31, 26, '拉班对雅各说：你做的是甚么事呢？你背著我偷走了，又把我的女儿们带了去，如同用刀剑掳去的一般。'),
('CUV', '创世纪', 1, 31, 27, '你为甚么暗暗地逃跑，偷著走，并不告诉我，叫我可以欢乐、唱歌、击鼓、弹琴的送你回去？'),
('CUV', '创世纪', 1, 31, 28, '又不容我与外孙和女儿亲嘴？你所行的真是愚昧！'),
('CUV', '创世纪', 1, 31, 29, '我手中原有能力害你，只是你父亲的神昨夜对我说：你要小心，不可与雅各说好说歹。'),
('CUV', '创世纪', 1, 31, 30, '现在你虽然想你父家，不得不去，为甚么又偷了我的神像呢？'),
('CUV', '创世纪', 1, 31, 31, '雅各回答拉班说：恐怕你把你的女儿从我夺去，所以我逃跑。'),
('CUV', '创世纪', 1, 31, 32, '至于你的神像，你在谁那里搜出来，就不容谁存活。当著我们的众弟兄，你认一认，在我这里有甚么东西是你的，就拿去。原来雅各不知道拉结偷了那些神像。'),
('CUV', '创世纪', 1, 31, 33, '拉班进了雅各、利亚，并两个使女的帐棚，都没有搜出来，就从利亚的帐棚出来，进了拉结的帐棚。'),
('CUV', '创世纪', 1, 31, 34, '拉结已经把神像藏在骆驼的驮篓里，便坐在上头。拉班摸遍了那帐棚，并没有摸著。'),
('CUV', '创世纪', 1, 31, 35, '拉结对他父亲说：现在我身上不便，不能在你面前起来，求我主不要生气。这样，拉班搜寻神像，竟没有搜出来。'),
('CUV', '创世纪', 1, 31, 36, '雅各就发怒斥责拉班说：我有甚么过犯，有甚么罪恶，你竟这样火速的追我？'),
('CUV', '创世纪', 1, 31, 37, '你摸遍了我一切的家具，你搜出甚么来呢？可以放在你我弟兄面前，叫他们在你我中间辨别辨别。'),
('CUV', '创世纪', 1, 31, 38, '我在你家这二十年，你的母绵羊、母山羊没有掉过胎。你群中的公羊，我没有吃过；'),
('CUV', '创世纪', 1, 31, 39, '被野兽撕裂的，我没有带来给你，是我自己赔上。无论是白日，是黑夜，被偷去的，你都向我索要。'),
('CUV', '创世纪', 1, 31, 40, '我白日受尽干热，黑夜受尽寒霜，不得合眼睡著，我常是这样。'),
('CUV', '创世纪', 1, 31, 41, '我这二十年在你家里，为你的两个女儿服事你十四年，为你的羊群服事你六年，你又十次改了我的工价。'),
('CUV', '创世纪', 1, 31, 42, '若不是我父亲以撒所敬畏的神，就是亚伯拉罕的神与我同在，你如今必定打发我空手而去。神看见我的苦情和我的劳碌，就在昨夜责备你。'),
('CUV', '创世纪', 1, 31, 43, '拉班回答雅各说：这女儿是我的女儿，这些孩子是我的孩子，这些羊群也是我的羊群；凡在你眼前的都是我的。我的女儿并他们所生的孩子，我今日能向他们做甚么呢？'),
('CUV', '创世纪', 1, 31, 44, '来罢！你我二人可以立约，作你我中间的证据。'),
('CUV', '创世纪', 1, 31, 45, '雅各就拿一块石头立作柱子，'),
('CUV', '创世纪', 1, 31, 46, '又对众弟兄说：你们堆聚石头。他们就拿石头来堆成一堆，大家便在旁边吃喝。'),
('CUV', '创世纪', 1, 31, 47, '拉班称那石堆为伊迦尔撒哈杜他，雅各却称那石堆为迦累得(都是以石堆为证的意思)。'),
('CUV', '创世纪', 1, 31, 48, '拉班说：今日这石堆作你我中间的证据。因此这地方名叫迦累得，'),
('CUV', '创世纪', 1, 31, 49, '又叫米斯巴，意思说：我们彼此离别以后，愿耶和华在你我中间鉴察。'),
('CUV', '创世纪', 1, 31, 50, '你若苦待我的女儿，又在我的女儿以外另娶妻，虽没有人知道，却有神在你我中间作见证。'),
('CUV', '创世纪', 1, 31, 51, '拉班又说：你看我在你我中间所立的这石堆和柱子。'),
('CUV', '创世纪', 1, 31, 52, '这石堆作证据，这柱子也作证据。我必不过这石堆去害你；你也不可过这石堆和柱子来害我。'),
('CUV', '创世纪', 1, 31, 53, '但愿亚伯拉罕的神和拿鹤的神，就是他们父亲的神，在你我中间判断。雅各就指著他父亲以撒所敬畏的神起誓，'),
('CUV', '创世纪', 1, 31, 54, '又在山上献祭，请众弟兄来吃饭。他们吃了饭，便在山上住宿。'),
('CUV', '创世纪', 1, 31, 55, '拉班清早起来，与他外孙和女儿亲嘴，给他们祝福，回往自己的地方去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 32, 1, '雅各仍旧行路，神的使者遇见他。'),
('CUV', '创世纪', 1, 32, 2, '雅各看见他们就说：这是神的军兵，于是给那地方起名叫玛哈念(就是二军兵的意思)。'),
('CUV', '创世纪', 1, 32, 3, '雅各打发人先往西珥地去，就是以东地，见他哥哥以扫，'),
('CUV', '创世纪', 1, 32, 4, '吩咐他们说：你们对我主以扫说：你的仆人雅各这样说：我在拉班那里寄居，直到如今。'),
('CUV', '创世纪', 1, 32, 5, '我有牛、驴、羊群、仆婢，现在打发人来报告我主，为要在你眼前蒙恩。'),
('CUV', '创世纪', 1, 32, 6, '所打发的人回到雅各那里，说：我们到了你哥哥以扫那里，他带著四百人，正迎著你来。'),
('CUV', '创世纪', 1, 32, 7, '雅各就甚惧怕，而且愁烦，便把那与他同在的人口和羊群、牛群、骆驼分做两队，'),
('CUV', '创世纪', 1, 32, 8, '说：以扫若来击杀这一队，剩下的那一队还可以逃避。'),
('CUV', '创世纪', 1, 32, 9, '雅各说：耶和华─我祖亚伯拉罕的神，我父亲以撒的神阿，你曾对我说：回你本地本族去，我要厚待你。'),
('CUV', '创世纪', 1, 32, 10, '你向仆人所施的一切慈爱和诚实，我一点也不配得；我先前只拿著我的杖过这约但河，如今我却成了两队了。'),
('CUV', '创世纪', 1, 32, 11, '求你救我脱离我哥哥以扫的手；因为我怕他来杀我，连妻子带儿女一同杀了。'),
('CUV', '创世纪', 1, 32, 12, '你曾说：我必定厚待你，使你的后裔如同海边的沙，多得不可胜数。'),
('CUV', '创世纪', 1, 32, 13, '当夜，雅各在那里住宿，就从他所有的物中拿礼物要送给他哥哥以扫：'),
('CUV', '创世纪', 1, 32, 14, '母山羊二百只，公山羊二十只，母绵羊二百只，公绵羊二十只，'),
('CUV', '创世纪', 1, 32, 15, '奶崽子的骆驼三十只─各带著崽子，母牛四十只，公牛十只，母驴二十匹，驴驹十匹；'),
('CUV', '创世纪', 1, 32, 16, '每样各分一群，交在仆人手下，就对仆人说：你们要在我前头过去，使群群相离，有空闲的地方；'),
('CUV', '创世纪', 1, 32, 17, '又吩咐尽先走的说：我哥哥以扫遇见你的时候，问你说：你是那家的人？要往那里去？你前头？这些是谁的？'),
('CUV', '创世纪', 1, 32, 18, '你就说：是你仆人雅各的，是送给我主以扫的礼物；他自己也在我们后边？。'),
('CUV', '创世纪', 1, 32, 19, '又吩咐第二、第三，和一切赶群畜的人说：你们遇见以扫的时候也要这样对他说；'),
('CUV', '创世纪', 1, 32, 20, '并且你们要说：你仆人雅各在我们后边。因雅各心里说：我藉著在我前头去的礼物解他的恨，然后再见他的面，或者他容纳我。'),
('CUV', '创世纪', 1, 32, 21, '于是礼物先过去了；那夜，雅各在队中住宿。'),
('CUV', '创世纪', 1, 32, 22, '他夜间起来，带著两个妻子，两个使女，并十一个儿子，都过了雅博渡口，'),
('CUV', '创世纪', 1, 32, 23, '先打发他们过河，又打发所有的都过去，'),
('CUV', '创世纪', 1, 32, 24, '只剩下雅各一人。有一个人来和他摔跤，直到黎明。'),
('CUV', '创世纪', 1, 32, 25, '那人见自己胜不过他，就将他的大腿窝摸了一把，雅各的大腿窝正在摔跤的时候就扭了。'),
('CUV', '创世纪', 1, 32, 26, '那人说：天黎明了，容我去罢！雅各说：你不给我祝福，我就不容你去。'),
('CUV', '创世纪', 1, 32, 27, '那人说：你名叫甚么？他说：我名叫雅各。'),
('CUV', '创世纪', 1, 32, 28, '那人说：你的名不要再叫雅各，要叫以色列；因为你与神与人较力，都得了胜。'),
('CUV', '创世纪', 1, 32, 29, '雅各问他说：请将你的名告诉我。那人说：何必问我的名？于是在那里给雅各祝福。'),
('CUV', '创世纪', 1, 32, 30, '雅各便给那地方起名叫毘努伊勒(就是神之面的意思)，意思说：我面对面见了神，我的性命仍得保全。'),
('CUV', '创世纪', 1, 32, 31, '日头刚出来的时候，雅各经过毘努伊勒，他的大腿就瘸了。'),
('CUV', '创世纪', 1, 32, 32, '故此，以色列人不吃大腿窝的筋，直到今日，因为那人摸了雅各大腿窝的筋。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 33, 1, '雅各举目观看，见以扫来了，后头跟著四百人，他就把孩子们分开交给利亚、拉结，和两个使女，'),
('CUV', '创世纪', 1, 33, 2, '并且叫两个使女和他们的孩子在前头，利亚和他的孩子在后头，拉结和约瑟在尽后头。'),
('CUV', '创世纪', 1, 33, 3, '他自己在他们前头过去，一连七次俯伏在地才就近他哥哥。'),
('CUV', '创世纪', 1, 33, 4, '以扫跑来迎接他，将他抱住，又搂著他的颈项，与他亲嘴，两个人就哭了。'),
('CUV', '创世纪', 1, 33, 5, '以扫举目看见妇人孩子，就说：这些？和你同行的是谁呢？雅各说：这些孩子是神施恩给你的仆人的。'),
('CUV', '创世纪', 1, 33, 6, '于是两个使女和他们的孩子前来下拜；'),
('CUV', '创世纪', 1, 33, 7, '利亚和他的孩子也前来下拜；随后约瑟和拉结也前来下拜。'),
('CUV', '创世纪', 1, 33, 8, '以扫说：我所遇见的这些群畜是甚么意思呢？雅各说：是要在我主面前蒙恩的。'),
('CUV', '创世纪', 1, 33, 9, '以扫说：兄弟阿，我的已经够了，你的仍归你罢！'),
('CUV', '创世纪', 1, 33, 10, '雅各说：不然，我若在你眼前蒙恩，就求你从我手里收下这礼物；因为我见了你的面，如同见了神的面，并且你容纳了我。'),
('CUV', '创世纪', 1, 33, 11, '求你收下我带来给你的礼物；因为神恩待我，使我充足。雅各再三地求他，他才收下了。'),
('CUV', '创世纪', 1, 33, 12, '以扫说：我们可以起身前往，我在你前头走。'),
('CUV', '创世纪', 1, 33, 13, '雅各对他说：我主知道孩子们年幼娇嫩，牛羊也正在乳养的时候，若是催赶一天，群畜都必死了。'),
('CUV', '创世纪', 1, 33, 14, '求我主在仆人前头走，我要量著在我面前群畜和孩子的力量慢慢地前行，直走到西珥我主那里。'),
('CUV', '创世纪', 1, 33, 15, '以扫说：容我把跟随我的人留几个在你这里。雅各说：何必呢？只要在我主眼前蒙恩就是了。'),
('CUV', '创世纪', 1, 33, 16, '于是，以扫当日起行，回往西珥去了。'),
('CUV', '创世纪', 1, 33, 17, '雅各就往疏割去，在那里为自己盖造房屋，又为牲畜搭棚；因此那地方名叫疏割(就是棚的意思)。'),
('CUV', '创世纪', 1, 33, 18, '雅各从巴旦亚兰回来的时候，平平安安地到了迦南地的示剑城，在城东支搭帐棚，'),
('CUV', '创世纪', 1, 33, 19, '就用一百块银子向示剑的父亲、哈抹的子孙买了支帐棚的那块地，'),
('CUV', '创世纪', 1, 33, 20, '在那里筑了一座坛，起名叫伊利伊罗伊以色列(就是神、以色列神的意思)。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 34, 1, '利亚给雅各所生的女儿底拿出去，要见那地的女子们。'),
('CUV', '创世纪', 1, 34, 2, '那地的主─希未人、哈抹的儿子示剑看见他，就拉住他，与他行淫，玷辱他。'),
('CUV', '创世纪', 1, 34, 3, '示剑的心系恋雅各的女儿底拿，喜爱这女子，甜言蜜语地安慰他。'),
('CUV', '创世纪', 1, 34, 4, '示剑对他父亲哈抹说：求你为我聘这女子为妻。'),
('CUV', '创世纪', 1, 34, 5, '雅各听见示剑玷污了他的女儿底拿。那时他的儿子们正和群畜在田野，雅各就闭口不言，等他们回来。'),
('CUV', '创世纪', 1, 34, 6, '示剑的父亲哈抹出来见雅各，要和他商议。'),
('CUV', '创世纪', 1, 34, 7, '雅各的儿子们听见这事，就从田野回来，人人忿恨，十分恼怒；因示剑在以色列家作了丑事，与雅各的女儿行淫，这本是不该做的事。'),
('CUV', '创世纪', 1, 34, 8, '哈抹和他们商议说：我儿子示剑的心恋慕这女子，求你们将他给我的儿子为妻。'),
('CUV', '创世纪', 1, 34, 9, '你们与我们彼此结亲；你们可以把女儿给我们，也可以娶我们的女儿。'),
('CUV', '创世纪', 1, 34, 10, '你们与我们同住罢！这地都在你们面前，只管在此居住，做买卖，置产业。'),
('CUV', '创世纪', 1, 34, 11, '示剑对女儿的父亲和弟兄们说：但愿我在你们眼前蒙恩，你们向我要甚么，我必给你们。'),
('CUV', '创世纪', 1, 34, 12, '任凭向我要多重的聘金和礼物，我必照你们所说的给你们；只要把女子给我为妻。'),
('CUV', '创世纪', 1, 34, 13, '雅各的儿子们因为示剑玷污了他们的妹子底拿，就用诡诈的话回答示剑和他父亲哈抹，'),
('CUV', '创世纪', 1, 34, 14, '对他们说：我们不能把我们的妹子给没有受割礼的人为妻，因为那是我们的羞辱。'),
('CUV', '创世纪', 1, 34, 15, '惟有一件才可以应允：若你们所有的男丁都受割礼，和我们一样，'),
('CUV', '创世纪', 1, 34, 16, '我们就把女儿给你们，也娶你们的女儿；我们便与你们同住，两下成为一样的人民。'),
('CUV', '创世纪', 1, 34, 17, '倘若你们不听从我们受割礼，我们就带著妹子走了。'),
('CUV', '创世纪', 1, 34, 18, '哈抹和他的儿子示剑喜欢这话。'),
('CUV', '创世纪', 1, 34, 19, '那少年人做这事并不迟延，因为他喜爱雅各的女儿；他在他父亲家中也是人最尊重的。'),
('CUV', '创世纪', 1, 34, 20, '哈抹和他儿子示剑到本城的门口，对本城的人说：'),
('CUV', '创世纪', 1, 34, 21, '这些人与我们和睦，不如许他们在这地居住，做买卖；这地也宽阔，足可容下他们。我们可以娶他们的女儿为妻，也可以把我们的女儿嫁给他们。'),
('CUV', '创世纪', 1, 34, 22, '惟有一件事我们必须做，他们才肯应允和我们同住，成为一样的人民：就是我们中间所有的男丁都要受割礼，和他们一样。'),
('CUV', '创世纪', 1, 34, 23, '他们的群畜、货财，和一切的牲口岂不都归我们么？只要依从他们，他们就与我们同住。'),
('CUV', '创世纪', 1, 34, 24, '凡从城门出入的人就都听从哈抹和他儿子示剑的话；于是凡从城门出入的男丁都受了割礼。'),
('CUV', '创世纪', 1, 34, 25, '到第三天，众人正在疼痛的时候，雅各的两个儿子，就是底拿的哥哥西缅和利未，各拿刀剑，趁著众人想不到的时候来到城中，把一切男丁都杀了，'),
('CUV', '创世纪', 1, 34, 26, '又用刀杀了哈抹和他儿子示剑，把底拿从示剑家里带出来就走了。'),
('CUV', '创世纪', 1, 34, 27, '雅各的儿子们因为他们的妹子受了玷污，就来到被杀的人那里，掳掠那城，'),
('CUV', '创世纪', 1, 34, 28, '夺了他们的羊群、牛群，和驴，并城里田间所有的；'),
('CUV', '创世纪', 1, 34, 29, '又把他们一切货财、孩子、妇女，并各房中所有的，都掳掠去了。'),
('CUV', '创世纪', 1, 34, 30, '雅各对西缅和利未说：你们连累我，使我在这地的居民中，就是在迦南人和比利洗人中，有了臭名。我的人丁既然稀少，他们必聚集来击杀我，我和全家的人都必灭绝。'),
('CUV', '创世纪', 1, 34, 31, '他们说：他岂可待我们的妹子如同妓女么？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 35, 1, '神对雅各说：起来！上伯特利去，住在那里；要在那里筑一座坛给神，就是你逃避你哥哥以扫的时候向你显现的那位。'),
('CUV', '创世纪', 1, 35, 2, '雅各就对他家中的人并一切与他同在的人说：你们要除掉你们中间的外邦神，也要自洁，更换衣裳。'),
('CUV', '创世纪', 1, 35, 3, '我们要起来，上伯特利去，在那里我要筑一座坛给神，就是在我遭难的日子应允我的祷告、在我行的路上保佑我的那位。'),
('CUV', '创世纪', 1, 35, 4, '他们就把外邦人的神像和他们耳朵上的环子交给雅各；雅各都藏在示剑那里的橡树底下。'),
('CUV', '创世纪', 1, 35, 5, '他们便起行前往。神使那周围城邑的人都甚惊惧，就不追赶雅各的众子了。'),
('CUV', '创世纪', 1, 35, 6, '于是雅各和一切与他同在的人到了迦南地的路斯，就是伯特利。'),
('CUV', '创世纪', 1, 35, 7, '他在那里筑了一座坛，就给那地方起名叫伊勒伯特利(就是伯特利之神的意思)；因为他逃避他哥哥的时候，神在那里向他显现。'),
('CUV', '创世纪', 1, 35, 8, '利百加的奶母底波拉死了，就葬在伯特利下边橡树底下；那棵树名叫亚伦巴古。'),
('CUV', '创世纪', 1, 35, 9, '雅各从巴旦亚兰回来，神又向他显现，赐福与他，'),
('CUV', '创世纪', 1, 35, 10, '且对他说：你的名原是雅各，从今以后不要再叫雅各，要叫以色列。这样，他就改名叫以色列。'),
('CUV', '创世纪', 1, 35, 11, '神又对他说：我是全能的神；你要生养众多，将来有一族和多国的民从你而生，又有君王从你而出。'),
('CUV', '创世纪', 1, 35, 12, '我所赐给亚伯拉罕和以撒的地，我要赐给你与你的后裔。'),
('CUV', '创世纪', 1, 35, 13, '神就从那与雅各说话的地方升上去了。'),
('CUV', '创世纪', 1, 35, 14, '雅各便在那里立了一根石柱，在柱子上奠酒，浇油。'),
('CUV', '创世纪', 1, 35, 15, '雅各就给那地方起名叫伯特利。'),
('CUV', '创世纪', 1, 35, 16, '他们从伯特利起行，离以法他还有一段路程，拉结临产甚是艰难。'),
('CUV', '创世纪', 1, 35, 17, '正在艰难的时候，收生婆对他说：不要怕，你又要得一个儿子了。'),
('CUV', '创世纪', 1, 35, 18, '他将近于死，灵魂要走的时候，就给他儿子起名叫便俄尼；他父亲却给他起名叫便雅悯。'),
('CUV', '创世纪', 1, 35, 19, '拉结死了，葬在以法他的路旁；以法他就是伯利恒。'),
('CUV', '创世纪', 1, 35, 20, '雅各在他的坟上立了一统碑，就是拉结的墓碑，到今日还在。'),
('CUV', '创世纪', 1, 35, 21, '以色列起行前往，在以得台那边支搭帐棚。'),
('CUV', '创世纪', 1, 35, 22, '以色列住在那地的时候，流便去与他父亲的妾辟拉同寝，以色列也听见了。雅各共有十二个儿子。'),
('CUV', '创世纪', 1, 35, 23, '利亚所生的是雅各的长子流便，还有西缅、利未、犹大、以萨迦、西布伦。'),
('CUV', '创世纪', 1, 35, 24, '拉结所生的是约瑟、便雅悯。'),
('CUV', '创世纪', 1, 35, 25, '拉结的使女辟拉所生的是但、拿弗他利。'),
('CUV', '创世纪', 1, 35, 26, '利亚的使女悉帕所生的是迦得、亚设。这是雅各在巴旦亚兰所生的儿子。'),
('CUV', '创世纪', 1, 35, 27, '雅各来到他父亲以撒那里，到了基列亚巴的幔利，乃是亚伯拉罕和以撒寄居的地方；基列亚巴就是希伯仑。'),
('CUV', '创世纪', 1, 35, 28, '以撒共活了一百八十岁。'),
('CUV', '创世纪', 1, 35, 29, '以撒年纪老迈，日子满足，气绝而死，归到他列祖(原文作本民)那里。他两个儿子以扫、雅各把他埋葬了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 36, 1, '以扫就是以东，他的后代记在下面。'),
('CUV', '创世纪', 1, 36, 2, '以扫娶迦南的女子为妻，就是赫人以伦的女儿亚大和希未人祭便的孙女、亚拿的女儿阿何利巴玛，'),
('CUV', '创世纪', 1, 36, 3, '又娶了以实玛利的女儿、尼拜约的妹子巴实抹。'),
('CUV', '创世纪', 1, 36, 4, '亚大给以扫生了以利法；巴实抹生了流珥；'),
('CUV', '创世纪', 1, 36, 5, '阿何利巴玛生了耶乌施、雅兰、可拉。这都是以扫的儿子，是在迦南地生的。'),
('CUV', '创世纪', 1, 36, 6, '以扫带著他的妻子、儿女，与家中一切的人口，并他的牛羊、牲畜，和一切货财，就是他在迦南地所得的，往别处去，离了他兄弟雅各。'),
('CUV', '创世纪', 1, 36, 7, '因为二人的财物群畜甚多，寄居的地方容不下他们，所以不能同居。'),
('CUV', '创世纪', 1, 36, 8, '于是以扫住在西珥山里；以扫就是以东。'),
('CUV', '创世纪', 1, 36, 9, '以扫是西珥山里以东人的始祖，他的后代记在下面。'),
('CUV', '创世纪', 1, 36, 10, '以扫众子的名字如下。以扫的妻子亚大生以利法；以扫的妻子巴实抹生流珥。'),
('CUV', '创世纪', 1, 36, 11, '以利法的儿子是提幔、阿抹、洗玻、迦坦、基纳斯。'),
('CUV', '创世纪', 1, 36, 12, '亭纳是以扫儿子以利法的妾；他给以利法生了亚玛力。这是以扫的妻子亚大的子孙。'),
('CUV', '创世纪', 1, 36, 13, '流珥的儿子是拿哈、谢拉、沙玛、米撒。这是以扫妻子巴实抹的子孙。'),
('CUV', '创世纪', 1, 36, 14, '以扫的妻子阿何利巴玛是祭便的孙女，亚拿的女儿；他给以扫生了耶乌施、雅兰、可拉。'),
('CUV', '创世纪', 1, 36, 15, '以扫子孙中作族长的记在下面。以扫的长子以利法的子孙中，有提幔族长、阿抹族长、洗玻族长，基纳斯族长、'),
('CUV', '创世纪', 1, 36, 16, '可拉族长、迦坦族长、亚玛力族长。这是在以东地从以利法所出的族长，都是亚大的子孙。'),
('CUV', '创世纪', 1, 36, 17, '以扫的儿子流珥的子孙中，有拿哈族长、谢拉族长、沙玛族长、米撒族长。这是在以东地从流珥所出的族长，都是以扫妻子巴实抹的子孙。'),
('CUV', '创世纪', 1, 36, 18, '以扫的妻子阿何利巴玛的子孙中，有耶乌施族长、雅兰族长、可拉族长。这是从以扫妻子，亚拿的女儿，阿何利巴玛子孙中所出的族长。'),
('CUV', '创世纪', 1, 36, 19, '以上的族长都是以扫的子孙；以扫就是以东。'),
('CUV', '创世纪', 1, 36, 20, '那地原有的居民─何利人西珥的子孙记在下面：就是罗坍、朔巴、祭便、亚拿、'),
('CUV', '创世纪', 1, 36, 21, '底顺、以察、底珊。这是从以东地的何利人西珥子孙中所出的族长。'),
('CUV', '创世纪', 1, 36, 22, '罗坍的儿子是何利、希幔；罗坍的妹子是亭纳。'),
('CUV', '创世纪', 1, 36, 23, '朔巴的儿子是亚勒文、玛拿辖、以巴录、示玻、阿南。'),
('CUV', '创世纪', 1, 36, 24, '祭便的儿子是亚雅、亚拿〈当时在旷野放他父亲祭便的驴，遇著温泉的，就是这亚拿〉。'),
('CUV', '创世纪', 1, 36, 25, '亚拿的儿子是底顺；亚拿的女儿是阿何利巴玛。'),
('CUV', '创世纪', 1, 36, 26, '底顺的儿子是欣但、伊是班、益兰、基兰。'),
('CUV', '创世纪', 1, 36, 27, '以察的儿子是辟罕、撒番、亚干。'),
('CUV', '创世纪', 1, 36, 28, '底珊的儿子是乌斯、亚兰。'),
('CUV', '创世纪', 1, 36, 29, '从何利人所出的族长记在下面：就是罗坍族长、朔巴族长、祭便族长、亚拿族长、'),
('CUV', '创世纪', 1, 36, 30, '底顺族长、以察族长、底珊族长。这是从何利人所出的族长，都在西珥地，按著宗族作族长。'),
('CUV', '创世纪', 1, 36, 31, '以色列人未有君王治理以先，在以东地作王的记在下面。'),
('CUV', '创世纪', 1, 36, 32, '比珥的儿子比拉在以东作王，他的京城名叫亭哈巴。'),
('CUV', '创世纪', 1, 36, 33, '比拉死了，波斯拉人谢拉的儿子约巴接续他作王。'),
('CUV', '创世纪', 1, 36, 34, '约巴死了，提幔地的人户珊接续他作王。'),
('CUV', '创世纪', 1, 36, 35, '户珊死了，比达的儿子哈达接续他作王；这哈达就是在摩押地杀败米甸人的，他的京城名叫亚未得。'),
('CUV', '创世纪', 1, 36, 36, '哈达死了，玛士利加人桑拉接续他作王。'),
('CUV', '创世纪', 1, 36, 37, '桑拉死了，大河边的利河伯人扫罗接续他作王。'),
('CUV', '创世纪', 1, 36, 38, '扫罗死了，亚革波的儿子巴勒哈南接续他作王。'),
('CUV', '创世纪', 1, 36, 39, '亚革波的儿子巴勒哈南死了，哈达接续他作王，他的京城名叫巴乌；他的妻子名叫米希他别，是米萨合的孙女，玛特列的女儿。'),
('CUV', '创世纪', 1, 36, 40, '从以扫所出的族长，按著他们的宗族、住处、名字记在下面：就是亭纳族长、亚勒瓦族长、耶帖族长、'),
('CUV', '创世纪', 1, 36, 41, '阿何利巴玛族长、以拉族长、比嫩族长、'),
('CUV', '创世纪', 1, 36, 42, '基纳斯族长、提幔族长、米比萨族长、'),
('CUV', '创世纪', 1, 36, 43, '玛基叠族长、以兰族长。这是以东人在所得为业的地上，按著他们的住处。〈所有的族长都是以东人的始祖以扫的后代。〉')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 37, 1, '雅各住在迦南地，就是他父亲寄居的地。'),
('CUV', '创世纪', 1, 37, 2, '雅各的记略如下。约瑟十七岁与他哥哥们一同牧羊。他是个童子，与他父亲的妾辟拉、悉帕的儿子们常在一处。约瑟将他哥哥们的恶行报给他们的父亲。'),
('CUV', '创世纪', 1, 37, 3, '以色列原来爱约瑟过于爱他的众子，因为约瑟是他年老生的；他给约瑟做了一件彩衣。'),
('CUV', '创世纪', 1, 37, 4, '约瑟的哥哥们见父亲爱约瑟过于爱他们，就恨约瑟，不与他说和睦的话。'),
('CUV', '创世纪', 1, 37, 5, '约瑟做了一梦，告诉他哥哥们，他们就越发恨他。'),
('CUV', '创世纪', 1, 37, 6, '约瑟对他们说：请听我所做的梦：'),
('CUV', '创世纪', 1, 37, 7, '我们在田里捆禾稼，我的捆起来站著，你们的捆来围著我的捆下拜。'),
('CUV', '创世纪', 1, 37, 8, '他的哥哥们回答说：难道你真要作我们的王么？难道你真要管辖我们么？他们就因为他的梦和他的话越发恨他。'),
('CUV', '创世纪', 1, 37, 9, '后来他又做了一梦，也告诉他的哥哥们说：看哪，我又做了一梦，梦见太阳、月亮，与十一个星向我下拜。'),
('CUV', '创世纪', 1, 37, 10, '约瑟将这梦告诉他父亲和他哥哥们，他父亲就责备他说：你做的这是甚么梦！难道我和你母亲、你弟兄果然要来俯伏在地，向你下拜么？'),
('CUV', '创世纪', 1, 37, 11, '他哥哥们都嫉妒他，他父亲却把这话存在心里。'),
('CUV', '创世纪', 1, 37, 12, '约瑟的哥哥们往示剑去放他们父亲的羊。'),
('CUV', '创世纪', 1, 37, 13, '以色列对约瑟说：你哥哥们不是在示剑放羊么？你来，我要打发你往他们那里去。约瑟说：我在这里。'),
('CUV', '创世纪', 1, 37, 14, '以色列说：你去看看你哥哥们平安不平安，群羊平安不平安，就回来报信给我；于是打发他出希伯仑谷，他就往示剑去了。'),
('CUV', '创世纪', 1, 37, 15, '有人遇见他在田野走迷了路，就问他说：你找甚么？'),
('CUV', '创世纪', 1, 37, 16, '他说：我找我的哥哥们，求你告诉我，他们在何处放羊。'),
('CUV', '创世纪', 1, 37, 17, '那人说：他们已经走了，我听见他们说要往多坍去。约瑟就去追赶他哥哥们，遇见他们在多坍。'),
('CUV', '创世纪', 1, 37, 18, '他们远远地看见他，趁他还没有走到跟前，大家就同谋要害死他，'),
('CUV', '创世纪', 1, 37, 19, '彼此说：你看！那做梦的来了。'),
('CUV', '创世纪', 1, 37, 20, '来罢！我们将他杀了，丢在一个坑里，就说有恶兽把他吃了。我们且看他的梦将来怎么样。'),
('CUV', '创世纪', 1, 37, 21, '流便听见了，要救他脱离他们的手，说：我们不可害他的性命；'),
('CUV', '创世纪', 1, 37, 22, '又说：不可流他的血，可以把他丢在这野地的坑里，不可下手害他。流便的意思是要救他脱离他们的手，把他归还他的父亲。'),
('CUV', '创世纪', 1, 37, 23, '约瑟到了他哥哥们那里，他们就剥了他的外衣，就是他穿的那件彩衣，'),
('CUV', '创世纪', 1, 37, 24, '把他丢在坑里；那坑是空的，里头没有水。'),
('CUV', '创世纪', 1, 37, 25, '他们坐下吃饭，举目观看，见有一伙米甸的以实玛利人从基列来，用骆驼驮著香料、乳香、没药，要带下埃及去。'),
('CUV', '创世纪', 1, 37, 26, '犹大对众弟兄说：我们杀我们的兄弟，藏了他的血有甚么益处呢？'),
('CUV', '创世纪', 1, 37, 27, '我们不如将他卖给以实玛利人，不可下手害他；因为他是我们的兄弟，我们的骨肉。众弟兄就听从了他。'),
('CUV', '创世纪', 1, 37, 28, '有些米甸的商人从那里经过，哥哥们就把约瑟从坑里拉上来，讲定二十舍客勒银子，把约瑟卖给以实玛利人。他们就把约瑟带到埃及去了。'),
('CUV', '创世纪', 1, 37, 29, '流便回到坑边，见约瑟不在坑里，就撕裂衣服，'),
('CUV', '创世纪', 1, 37, 30, '回到兄弟们那里，说：童子没有了。我往那里去才好呢？'),
('CUV', '创世纪', 1, 37, 31, '他们宰了一只公山羊，把约瑟的那件彩衣染了血，'),
('CUV', '创世纪', 1, 37, 32, '打发人送到他们的父亲那里，说：我们捡了这个；请认一认是你儿子的外衣不是？'),
('CUV', '创世纪', 1, 37, 33, '他认得，就说：这是我儿子的外衣。有恶兽把他吃了，约瑟被撕碎了！撕碎了！'),
('CUV', '创世纪', 1, 37, 34, '雅各便撕裂衣服，腰间围上麻布，为他儿子悲哀了多日。'),
('CUV', '创世纪', 1, 37, 35, '他的儿女都起来安慰他，他却不肯受安慰，说：我必悲哀著下阴间，到我儿子那里。约瑟的父亲就为他哀哭。'),
('CUV', '创世纪', 1, 37, 36, '米甸人带约瑟到埃及，把他卖给法老的内臣─护卫长波提乏。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 38, 1, '那时，犹大离开他弟兄下去，到一个亚杜兰人名叫希拉的家里去。'),
('CUV', '创世纪', 1, 38, 2, '犹大在那里看见一个迦南人名叫书亚的女儿，就娶他为妻，与他同房，'),
('CUV', '创世纪', 1, 38, 3, '他就怀孕生了儿子，犹大给他起名叫珥。'),
('CUV', '创世纪', 1, 38, 4, '他又怀孕生了儿子，母亲给他起名叫俄南。'),
('CUV', '创世纪', 1, 38, 5, '他复又生了儿子，给他起名叫示拉。他生示拉的时候，犹大正在基悉。'),
('CUV', '创世纪', 1, 38, 6, '犹大为长子珥娶妻，名叫他玛。'),
('CUV', '创世纪', 1, 38, 7, '犹大的长子珥在耶和华眼中看为恶，耶和华就叫他死了。'),
('CUV', '创世纪', 1, 38, 8, '犹大对俄南说：你当与你哥哥的妻子同房，向他尽你为弟的本分，为你哥哥生子立后。'),
('CUV', '创世纪', 1, 38, 9, '俄南知道生子不归自己，所以同房的时候便遗在地，免得给他哥哥留后。'),
('CUV', '创世纪', 1, 38, 10, '俄南所做的在耶和华眼中看为恶，耶和华也就叫他死了。'),
('CUV', '创世纪', 1, 38, 11, '犹大心里说：恐怕示拉也死，像他两个哥哥一样，就对他儿妇他玛说：你去，在你父亲家里守寡，等我儿子示拉长大。他玛就回去，住在他父亲家里。'),
('CUV', '创世纪', 1, 38, 12, '过了许久，犹大的妻子书亚的女儿死了。犹大得了安慰，就和他朋友亚杜兰人希拉上亭拿去，到他剪羊毛的人那里。'),
('CUV', '创世纪', 1, 38, 13, '有人告诉他玛说：你的公公上亭拿剪羊毛去了。'),
('CUV', '创世纪', 1, 38, 14, '他玛见示拉已经长大，还没有娶他为妻，就脱了他作寡妇的衣裳，用帕子蒙著脸，又遮住身体，坐在亭拿路上的伊拿印城门口。'),
('CUV', '创世纪', 1, 38, 15, '犹大看见他，以为是妓女，因为他蒙著脸。'),
('CUV', '创世纪', 1, 38, 16, '犹大就转到他那里去，说：来罢！让我与你同寝。他原不知道是他的儿妇。他玛说：你要与我同寝，把甚么给我呢？'),
('CUV', '创世纪', 1, 38, 17, '犹大说：我从羊群里取一只山羊羔，打发人送来给你。他玛说：在未送以先，你愿意给我一个当头么？'),
('CUV', '创世纪', 1, 38, 18, '他说：我给你甚么当头呢？他玛说：你的印、你的带子，和你手里的杖。犹大就给了他，与他同寝，他就从犹大怀了孕。'),
('CUV', '创世纪', 1, 38, 19, '他玛起来走了，除去帕子，仍旧穿上作寡妇的衣裳。'),
('CUV', '创世纪', 1, 38, 20, '犹大托他朋友亚杜兰人送一只山羊羔去，要从那女人手里取回当头来，却找不著他，'),
('CUV', '创世纪', 1, 38, 21, '就问那地方的人说：伊拿印路旁的妓女在那里？他们说：这里并没有妓女。'),
('CUV', '创世纪', 1, 38, 22, '他回去见犹大说：我没有找著他，并且那地方的人说：这里没有妓女。'),
('CUV', '创世纪', 1, 38, 23, '犹大说：我把这山羊羔送去了，你竟找不著他。任凭他拿去罢，免得我们被羞辱。'),
('CUV', '创世纪', 1, 38, 24, '约过了三个月，有人告诉犹大说：你的儿妇他玛作了妓女，且因行淫有了身孕。犹大说：拉出他来，把他烧了！'),
('CUV', '创世纪', 1, 38, 25, '他玛被拉出来的时候便打发人去见他公公，对他说：这些东西是谁的，我就是从谁怀的孕。请你认一认，这印和带子并杖都是谁的？'),
('CUV', '创世纪', 1, 38, 26, '犹大承认说：他比我更有义，因为我没有将他给我的儿子示拉。从此犹大不再与他同寝了。'),
('CUV', '创世纪', 1, 38, 27, '他玛将要生产，不料他腹里是一对双生。'),
('CUV', '创世纪', 1, 38, 28, '到生产的时候，一个孩子伸出一只手来；收生婆拿红线拴在他手上，说：这是头生的。'),
('CUV', '创世纪', 1, 38, 29, '随后这孩子把手收回去，他哥哥生出来了；收生婆说：你为甚么抢著来呢？因此给他起名叫法勒斯。'),
('CUV', '创世纪', 1, 38, 30, '后来，他兄弟那手上有红线的也生出来，就给他起名叫谢拉。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 39, 1, '约瑟被带下埃及去。有一个埃及人，是法老的内臣─护卫长波提乏，从那些带下他来的以实玛利人手下买了他去。'),
('CUV', '创世纪', 1, 39, 2, '约瑟住在他主人埃及人的家中，耶和华与他同在，他就百事顺利。'),
('CUV', '创世纪', 1, 39, 3, '他主人见耶和华与他同在，又见耶和华使他手里所办的尽都顺利，'),
('CUV', '创世纪', 1, 39, 4, '约瑟就在主人眼前蒙恩，伺候他主人，并且主人派他管理家务，把一切所有的都交在他手里。'),
('CUV', '创世纪', 1, 39, 5, '自从主人派约瑟管理家务和他一切所有的，耶和华就因约瑟的缘故赐福与那埃及人的家；凡家里和田间一切所有的都蒙耶和华赐福。'),
('CUV', '创世纪', 1, 39, 6, '波提乏将一切所有的都交在约瑟的手中，除了自己所吃的饭，别的事一概不知。约瑟原来秀雅俊美。'),
('CUV', '创世纪', 1, 39, 7, '这事以后，约瑟主人的妻以目送情给约瑟，说：你与我同寝罢！'),
('CUV', '创世纪', 1, 39, 8, '约瑟不从，对他主人的妻说：看哪，一切家务，我主人都不知道；他把所有的都交在我手里。'),
('CUV', '创世纪', 1, 39, 9, '在这家里没有比我大的；并且他没有留下一样不交给我，只留下了你，因为你是他的妻子。我怎能作这大恶，得罪神呢？'),
('CUV', '创世纪', 1, 39, 10, '后来他天天和约瑟说，约瑟却不听从他，不与他同寝，也不和他在一处。'),
('CUV', '创世纪', 1, 39, 11, '有一天，约瑟进屋里去办事，家中人没有一个在那屋里，'),
('CUV', '创世纪', 1, 39, 12, '妇人就拉住他的衣裳，说：你与我同寝罢！约瑟把衣裳丢在妇人手里，跑到外边去了。'),
('CUV', '创世纪', 1, 39, 13, '妇人看见约瑟把衣裳丢在他手里跑出去了，'),
('CUV', '创世纪', 1, 39, 14, '就叫了家里的人来，对他们说：你们看！他带了一个希伯来人进入我们家里，要戏弄我们。他到我这里来，要与我同寝，我就大声喊叫。'),
('CUV', '创世纪', 1, 39, 15, '他听见我放声喊起来，就把衣裳丢在我这里，跑到外边去了。'),
('CUV', '创世纪', 1, 39, 16, '妇人把约瑟的衣裳放在自己那里，等著他主人回家，'),
('CUV', '创世纪', 1, 39, 17, '就对他如此如此说：你所带到我们这里的那希伯来仆人进来要戏弄我，'),
('CUV', '创世纪', 1, 39, 18, '我放声喊起来，他就把衣裳丢在我这里，跑出去了。'),
('CUV', '创世纪', 1, 39, 19, '约瑟的主人听见他妻子对他所说的话，说：你的仆人如此如此待我，他就生气，'),
('CUV', '创世纪', 1, 39, 20, '把约瑟下在监里，就是王的囚犯被囚的地方。于是约瑟在那里坐监。'),
('CUV', '创世纪', 1, 39, 21, '但耶和华与约瑟同在，向他施恩，使他在司狱的眼前蒙恩。'),
('CUV', '创世纪', 1, 39, 22, '司狱就把监里所有的囚犯都交在约瑟手下；他们在那里所办的事都是经他的手。'),
('CUV', '创世纪', 1, 39, 23, '凡在约瑟手下的事，司狱一概不察，因为耶和华与约瑟同在；耶和华使他所做的尽都顺利。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 40, 1, '这事以后，埃及王的酒政和膳长得罪了他们的主─埃及王，'),
('CUV', '创世纪', 1, 40, 2, '法老就恼怒酒政和膳长这二臣，'),
('CUV', '创世纪', 1, 40, 3, '把他们下在护卫长府内的监里，就是约瑟被囚的地方。'),
('CUV', '创世纪', 1, 40, 4, '护卫长把他们交给约瑟，约瑟便伺候他们；他们有些日子在监里。'),
('CUV', '创世纪', 1, 40, 5, '被囚在监之埃及王的酒政和膳长二人同夜各做一梦，各梦都有讲解。'),
('CUV', '创世纪', 1, 40, 6, '到了早晨，约瑟进到他们那里，见他们有愁闷的样子。'),
('CUV', '创世纪', 1, 40, 7, '他便问法老的二臣，就是与他同囚在他主人府里的，说：他们今日为甚么面带愁容呢？'),
('CUV', '创世纪', 1, 40, 8, '他们对他说：我们各人做了一梦，没有人能解。约瑟说：解梦不是出于神么？请你们将梦告诉我。'),
('CUV', '创世纪', 1, 40, 9, '酒政便将他的梦告诉约瑟说：我梦见在我面前有一棵葡萄树，'),
('CUV', '创世纪', 1, 40, 10, '树上有三根枝子，好像发了芽，开了花，上头的葡萄都成熟了。'),
('CUV', '创世纪', 1, 40, 11, '法老的杯在我手中，我就拿葡萄挤在法老的杯里，将杯递在他手中。'),
('CUV', '创世纪', 1, 40, 12, '约瑟对他说：他所做的梦是这样解：三根枝子就是三天；'),
('CUV', '创世纪', 1, 40, 13, '三天之内，法老必提你出监，叫你官复原职，你仍要递杯在法老的手中，和先前作他的酒政一样。'),
('CUV', '创世纪', 1, 40, 14, '但你得好处的时候，求你记念我，施恩与我，在法老面前题说我，救我出这监牢。'),
('CUV', '创世纪', 1, 40, 15, '我实在是从希伯来人之地被拐来的；我在这里也没有做过甚么，叫他们把我下在监里。'),
('CUV', '创世纪', 1, 40, 16, '膳长见梦解得好，就对约瑟说：我在梦中见我头上顶著三筐白饼；'),
('CUV', '创世纪', 1, 40, 17, '极上的筐子里有为法老烤的各样食物，有飞鸟来吃我头上筐子里的食物。'),
('CUV', '创世纪', 1, 40, 18, '约瑟说：你的梦是这样解：三个筐子就是三天；'),
('CUV', '创世纪', 1, 40, 19, '三天之内，法老必斩断你的头，把你挂在木头上，必有飞鸟来吃你身上的肉。'),
('CUV', '创世纪', 1, 40, 20, '到了第三天，是法老的生日，他为众臣仆设摆筵席，把酒政和膳长提出监来，'),
('CUV', '创世纪', 1, 40, 21, '使酒政官复原职，他仍旧递杯在法老手中；'),
('CUV', '创世纪', 1, 40, 22, '但把膳长挂起来，正如约瑟向他们所解的话。'),
('CUV', '创世纪', 1, 40, 23, '酒政却不记念约瑟，竟忘了他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 41, 1, '过了两年，法老做梦，梦见自己站在河边，'),
('CUV', '创世纪', 1, 41, 2, '有七只母牛从河里上来，又美好又肥壮，在芦荻中吃草。'),
('CUV', '创世纪', 1, 41, 3, '随后又有七只母牛从河里上来，又丑陋又干瘦，与那七只母牛一同站在河边。'),
('CUV', '创世纪', 1, 41, 4, '这又丑陋又干瘦的七只母牛吃尽了那又美好又肥壮的七只母牛。法老就醒了。'),
('CUV', '创世纪', 1, 41, 5, '他又睡著，第二回做梦，梦见一棵麦子长了七个穗子，又肥大又佳美，'),
('CUV', '创世纪', 1, 41, 6, '随后又长了七个穗子，又细弱又被东风吹焦了。'),
('CUV', '创世纪', 1, 41, 7, '这细弱的穗子吞了那七个又肥大又饱满的穗子。法老醒了，不料是个梦。'),
('CUV', '创世纪', 1, 41, 8, '到了早晨，法老心里不安，就差人召了埃及所有的术士和博士来；法老就把所做的梦告诉他们，却没有人能给法老圆解。'),
('CUV', '创世纪', 1, 41, 9, '那时酒政对法老说：我今日想起我的罪来。'),
('CUV', '创世纪', 1, 41, 10, '从前法老恼怒臣仆，把我和膳长下在护卫长府内的监里。'),
('CUV', '创世纪', 1, 41, 11, '我们二人同夜各做一梦，各梦都有讲解。'),
('CUV', '创世纪', 1, 41, 12, '在那里同著我们有一个希伯来的少年人，是护卫长的仆人，我们告诉他，他就把我们的梦圆解，是按著各人的梦圆解的。'),
('CUV', '创世纪', 1, 41, 13, '后来正如他给我们圆解的成就了；我官复原职，膳长被挂起来了。'),
('CUV', '创世纪', 1, 41, 14, '法老遂即差人去召约瑟，他们便急忙带他出监，他就剃头，刮脸，换衣裳，进到法老面前。'),
('CUV', '创世纪', 1, 41, 15, '法老对约瑟说：我做了一梦，没有人能解；我听见人说，你听了梦就能解。'),
('CUV', '创世纪', 1, 41, 16, '约瑟回答法老说：这不在乎我，神必将平安的话回答法老。'),
('CUV', '创世纪', 1, 41, 17, '法老对约瑟说：我梦见我站在河边，'),
('CUV', '创世纪', 1, 41, 18, '有七只母牛从河里上来，又肥壮又美好，在芦荻中吃草。'),
('CUV', '创世纪', 1, 41, 19, '随后又有七只母牛上来，又软弱又丑陋又干瘦，在埃及遍地，我没有见过这样不好的。'),
('CUV', '创世纪', 1, 41, 20, '这又干瘦又丑陋的母牛吃尽了那以先的七只肥母牛，'),
('CUV', '创世纪', 1, 41, 21, '吃了以后却看不出是吃了，那丑陋的样子仍旧和先前一样。我就醒了。'),
('CUV', '创世纪', 1, 41, 22, '我又梦见一棵麦子，长了七个穗子，又饱满又佳美，'),
('CUV', '创世纪', 1, 41, 23, '随后又长了七个穗子，枯槁细弱，被东风吹焦了。'),
('CUV', '创世纪', 1, 41, 24, '这些细弱的穗子吞了那七个佳美的穗子。我将这梦告诉了术士，却没有人能给我解说。'),
('CUV', '创世纪', 1, 41, 25, '约瑟对法老说：法老的梦乃是一个。神已将所要做的事指示法老了。'),
('CUV', '创世纪', 1, 41, 26, '七只好母牛是七年，七个好穗子也是七年；这梦乃是一个。'),
('CUV', '创世纪', 1, 41, 27, '那随后上来的七只又干瘦又丑陋的母牛是七年，那七个虚空、被东风吹焦的穗子也是七年，都是七个荒年。'),
('CUV', '创世纪', 1, 41, 28, '这就是我对法老所说，神已将所要做的事显明给法老了。'),
('CUV', '创世纪', 1, 41, 29, '埃及遍地必来七个大丰年，'),
('CUV', '创世纪', 1, 41, 30, '随后又要来七个荒年，甚至埃及地都忘了先前的丰收，全地必被饥荒所灭。'),
('CUV', '创世纪', 1, 41, 31, '因那以后的饥荒甚大，便不觉得先前的丰收了。'),
('CUV', '创世纪', 1, 41, 32, '至于法老两回做梦，是因神命定这事，而且必速速成就。'),
('CUV', '创世纪', 1, 41, 33, '所以，法老当拣选一个有聪明有智慧的人，派他治理埃及地。'),
('CUV', '创世纪', 1, 41, 34, '法老当这样行，又派官员管理这地。当七个丰年的时候，征收埃及地的五分之一，'),
('CUV', '创世纪', 1, 41, 35, '叫他们把将来丰年一切的粮食聚敛起来，积蓄五谷，收存在各城里做食物，归于法老的手下。'),
('CUV', '创世纪', 1, 41, 36, '所积蓄的粮食可以防备埃及地将来的七个荒年，免得这地被饥荒所灭。'),
('CUV', '创世纪', 1, 41, 37, '法老和他一切臣仆都以这事为妙。'),
('CUV', '创世纪', 1, 41, 38, '法老对臣仆说：像这样的人，有神的灵在他里头，我们岂能找得著呢？'),
('CUV', '创世纪', 1, 41, 39, '法老对约瑟说：神既将这事都指示你，可见没有人像你这样有聪明有智慧。'),
('CUV', '创世纪', 1, 41, 40, '你可以掌管我的家；我的民都必听从你的话。惟独在宝座上我比你大。'),
('CUV', '创世纪', 1, 41, 41, '法老又对约瑟说：我派你治理埃及全地。'),
('CUV', '创世纪', 1, 41, 42, '法老就摘下手上打印的戒指，戴在约瑟的手上，给他穿上细麻衣，把金链戴在他的颈项上，'),
('CUV', '创世纪', 1, 41, 43, '又叫约瑟坐他的副车，喝道的在前呼叫说：跪下。这样、法老派他治理埃及全地。'),
('CUV', '创世纪', 1, 41, 44, '法老对约瑟说：我是法老，在埃及全地，若没有你的命令，不许人擅自办事(原文作动手动脚)。'),
('CUV', '创世纪', 1, 41, 45, '法老赐名给约瑟，叫撒发那忒巴内亚，又将安城的祭司波提非拉的女儿亚西纳给他为妻。约瑟就出去巡行埃及地。'),
('CUV', '创世纪', 1, 41, 46, '约瑟见埃及王法老的时候年三十岁。他从法老面前出去，遍行埃及全地。'),
('CUV', '创世纪', 1, 41, 47, '七个丰年之内，地的出产极丰极盛(原文作一把一把的)，'),
('CUV', '创世纪', 1, 41, 48, '约瑟聚歛埃及地七个丰年一切的粮食，把粮食积存在各城里；各城周围田地的粮食都积存在本城里。'),
('CUV', '创世纪', 1, 41, 49, '约瑟积蓄五谷甚多，如同海边的沙，无法计算，因为谷不可胜数。'),
('CUV', '创世纪', 1, 41, 50, '荒年未到以前，安城的祭司波提非拉的女儿亚西纳给约瑟生了两个儿子。'),
('CUV', '创世纪', 1, 41, 51, '约瑟给长子起名叫玛拿西(就是使之忘了的意思)，因为他说：神使我忘了一切的困苦和我父的全家。'),
('CUV', '创世纪', 1, 41, 52, '他给次子起名叫以法莲(就是使之昌盛的意思)，因为他说：神使我在受苦的地方昌盛。'),
('CUV', '创世纪', 1, 41, 53, '埃及地的七个丰年一完，'),
('CUV', '创世纪', 1, 41, 54, '七个荒年就来了。正如约瑟所说的，各地都有饥荒；惟独埃及全地有粮食。'),
('CUV', '创世纪', 1, 41, 55, '及至埃及全地有了饥荒，众民向法老哀求粮食，法老对他们说：你们往约瑟那里去，凡他所说的，你们都要做。'),
('CUV', '创世纪', 1, 41, 56, '当时饥荒遍满天下，约瑟开了各处的仓，粜粮给埃及人；在埃及地饥荒甚大。'),
('CUV', '创世纪', 1, 41, 57, '各地的人都往埃及去，到约瑟那里籴粮，因为天下的饥荒甚大。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 42, 1, '雅各见埃及有粮，就对儿子们说：你们为甚么彼此观望呢？'),
('CUV', '创世纪', 1, 42, 2, '我听见埃及有粮，你们可以下去，从那里为我们籴些来，使我们可以存活，不至于死。'),
('CUV', '创世纪', 1, 42, 3, '于是，约瑟的十个哥哥都下埃及籴粮去了。'),
('CUV', '创世纪', 1, 42, 4, '但约瑟的兄弟便雅悯，雅各没有打发他和哥哥们同去，因为雅各说：恐怕他遭害。'),
('CUV', '创世纪', 1, 42, 5, '来籴粮的人中有以色列的儿子们，因为迦南地也有饥荒。'),
('CUV', '创世纪', 1, 42, 6, '当时治理埃及地的是约瑟；粜粮给那地众民的就是他。约瑟的哥哥们来了，脸伏于地，向他下拜。'),
('CUV', '创世纪', 1, 42, 7, '约瑟看见他哥哥们，就认得他们，却装作生人，向他们说些严厉话，问他们说：你们从那里来？他们说：我们从迦南地来籴粮。'),
('CUV', '创世纪', 1, 42, 8, '约瑟认得他哥哥们，他们却不认得他。'),
('CUV', '创世纪', 1, 42, 9, '约瑟想起从前所做的那两个梦，就对他们说：你们是奸细，来窥探这地的虚实。'),
('CUV', '创世纪', 1, 42, 10, '他们对他说：我主阿，不是的。仆人们是籴粮来的。'),
('CUV', '创世纪', 1, 42, 11, '我们都是一个人的儿子，是诚实人；仆人们并不是奸细。'),
('CUV', '创世纪', 1, 42, 12, '约瑟说：不然，你们必是窥探这地的虚实来的。'),
('CUV', '创世纪', 1, 42, 13, '他们说：仆人们本是弟兄十二人，是迦南地一个人的儿子，顶小的现今在我们的父亲那里，有一个没有了。'),
('CUV', '创世纪', 1, 42, 14, '约瑟说：我才说你们是奸细，这话实在不错。'),
('CUV', '创世纪', 1, 42, 15, '我指著法老的性命起誓，若是你们的小兄弟不到这里，你们就不得出这地方，从此就可以把你们证验出来了。'),
('CUV', '创世纪', 1, 42, 16, '须要打发你们中间一个人去，把你们的兄弟带来。至于你们，都要囚在这里，好证验你们的话真不真，若不真，我指著法老的性命起誓，你们一定是奸细。'),
('CUV', '创世纪', 1, 42, 17, '于是约瑟把他们都下在监里三天。'),
('CUV', '创世纪', 1, 42, 18, '到了第三天，约瑟对他们说：我是敬畏神的；你们照我的话行就可以存活。'),
('CUV', '创世纪', 1, 42, 19, '你们如果是诚实人，可以留你们中间的一个人囚在监里，但你们可以带著粮食回去，救你们家里的饥荒。'),
('CUV', '创世纪', 1, 42, 20, '把你们的小兄弟带到我这里来，如此，你们的话便有证据，你们也不至于死。他们就照样而行。'),
('CUV', '创世纪', 1, 42, 21, '他们彼此说：我们在兄弟身上实在有罪。他哀求我们的时候，我们见他心里的愁苦，却不肯听，所以这场苦难临到我们身上。'),
('CUV', '创世纪', 1, 42, 22, '流便说：我岂不是对你们说过，不可伤害那孩子么？只是你们不肯听，所以流他血的罪向我们追讨。'),
('CUV', '创世纪', 1, 42, 23, '他们不知道约瑟听得出来，因为在他们中间用通事传话。'),
('CUV', '创世纪', 1, 42, 24, '约瑟转身退去，哭了一场，又回来对他们说话，就从他们中间挑出西缅来，在他们眼前把他捆绑。'),
('CUV', '创世纪', 1, 42, 25, '约瑟吩咐人把粮食装满他们的器具，把各人的银子归还在各人的口袋里，又给他们路上用的食物，人就照他的话办了。'),
('CUV', '创世纪', 1, 42, 26, '他们就把粮食驮在驴上，离开那里去了。'),
('CUV', '创世纪', 1, 42, 27, '到了住宿的地方，他们中间有一个人打开口袋，要拿料喂驴，才看见自己的银子仍在口袋里，'),
('CUV', '创世纪', 1, 42, 28, '就对弟兄们说：我的银子归还了，看哪，仍在我口袋里！他们就提心吊胆，战战兢兢的彼此说：这是神向我们做甚么呢？'),
('CUV', '创世纪', 1, 42, 29, '他们来到迦南地、他们的父亲雅各那里，将所遭遇的事都告诉他，说：'),
('CUV', '创世纪', 1, 42, 30, '那地的主对我们说严厉的话，把我们当作窥探那地的奸细。'),
('CUV', '创世纪', 1, 42, 31, '我们对他说：我们是诚实人，并不是奸细。'),
('CUV', '创世纪', 1, 42, 32, '我们本是弟兄十二人，都是一个父亲的儿子，有一个没有了，顶小的如今同我们的父亲在迦南地。'),
('CUV', '创世纪', 1, 42, 33, '那地的主对我们说：若要我知道你们是诚实人，可以留下你们中间的一个人在我这里，你们可以带著粮食回去，救你们家里的饥荒。'),
('CUV', '创世纪', 1, 42, 34, '把你们的小兄弟带到我这里来，我便知道你们不是奸细，乃是诚实人。这样，我就把你们的弟兄交给你们，你们也可以在这地做买卖。'),
('CUV', '创世纪', 1, 42, 35, '后来他们倒口袋，不料，各人的银包都在口袋里；他们和父亲看见银包就都害怕。'),
('CUV', '创世纪', 1, 42, 36, '他们的父亲雅各对他们说：你们使我丧失我的儿子：约瑟没有了，西缅也没有了，你们又要将便雅悯带去；这些事都归到我身上了。'),
('CUV', '创世纪', 1, 42, 37, '流便对他父亲说：我若不带他回来交给你，你可以杀我的两个儿子。只管把他交在我手里，我必带他回来交给你。'),
('CUV', '创世纪', 1, 42, 38, '雅各说：我的儿子不可与你们一同下去；他哥哥死了，只剩下他，他若在你们所行的路上遭害，那便是你们使我白发苍苍、悲悲惨惨的下阴间去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 43, 1, '那地的饥荒甚大。'),
('CUV', '创世纪', 1, 43, 2, '他们从埃及带来的粮食吃尽了，他们的父亲就对他们说：『你们再去给我籴些粮来。』'),
('CUV', '创世纪', 1, 43, 3, '犹大对他说：『那人谆谆地告诫我们说：「你们的兄弟若不与你们同来，你们就不得见我的面。」'),
('CUV', '创世纪', 1, 43, 4, '你若打发我们的兄弟与我们同去，我们就下去给你籴粮；'),
('CUV', '创世纪', 1, 43, 5, '你若不打发他去，我们就不下去，因为那人对我们说：「你们的兄弟若不与你们同来，你们就不得见我的面。」』'),
('CUV', '创世纪', 1, 43, 6, '以色列说：『你们为什么这样害我，告诉那人你们还有兄弟呢？』'),
('CUV', '创世纪', 1, 43, 7, '他们回答说：『那人详细问到我们和我们的亲属，说：「你们的父亲还在吗？你们还有兄弟吗？」我们就按著他所问的告诉他，焉能知道他要说「必须把你们的兄弟带下来」呢？』'),
('CUV', '创世纪', 1, 43, 8, '犹大又对他父亲以色列说：『你打发童子与我同去，我们就起身下去，好叫我们和你，并我们的妇人孩子，都得存活，不至于死。'),
('CUV', '创世纪', 1, 43, 9, '我为他作保；你可以从我手中追讨，我若不带他回来交在你面前，我情愿永远担罪。'),
('CUV', '创世纪', 1, 43, 10, '我们若没有耽搁，如今第二次都回来了。』'),
('CUV', '创世纪', 1, 43, 11, '他们的父亲以色列说：『若必须如此，你们就当这样行：可以将这地土产中最好的乳香、蜂蜜、香料、没药、榧子、杏仁都取一点，收在器具里，带下去送给那人作礼物，'),
('CUV', '创世纪', 1, 43, 12, '又要手里加倍地带银子，并将归还在你们口袋内的银子仍带在手里；那或者是错了。'),
('CUV', '创世纪', 1, 43, 13, '也带著你们的兄弟，起身去见那人。'),
('CUV', '创世纪', 1, 43, 14, '但愿全能的神使你们在那人面前蒙怜悯，释放你们的那弟兄和便雅悯回来。我若丧了儿子，就丧了吧!』'),
('CUV', '创世纪', 1, 43, 15, '于是，他们拿著那礼物，又手里加倍地带银子，并且带著便雅悯，起身下到埃及，站在约瑟面前。'),
('CUV', '创世纪', 1, 43, 16, '约瑟见便雅悯和他们同来，就对家宰说：『将这些人领到屋里。要宰杀牲畜，预备筵席，因为晌午这些人同我吃饭。』'),
('CUV', '创世纪', 1, 43, 17, '家宰就遵著约瑟的命去行，领他们进约瑟的屋里。'),
('CUV', '创世纪', 1, 43, 18, '他们因为被领到约瑟的屋里，就害怕，说：『领我们到这里来，必是因为头次归还在我们口袋里的银子，找我们的错缝，下手害我们，强取我们为奴仆，抢夺我们的驴。』'),
('CUV', '创世纪', 1, 43, 19, '他们就挨近约瑟的家宰，在屋门口和他说话，'),
('CUV', '创世纪', 1, 43, 20, '说：『我主啊，我们头次下来实在是要籴粮。'),
('CUV', '创世纪', 1, 43, 21, '后来到了住宿的地方，我们打开口袋，不料，各人的银子，分量足数，仍在各人的口袋内，现在我们手里又带回来了。'),
('CUV', '创世纪', 1, 43, 22, '另外又带下银子来籴粮。不知道先前谁把银子放在我们的口袋里。』'),
('CUV', '创世纪', 1, 43, 23, '家宰说：『你们可以放心，不要害怕，是你们的神和你们父亲的神赐给你们财宝在你们的口袋里；你们的银子，我早已收了。』他就把西缅带出来，交给他们。'),
('CUV', '创世纪', 1, 43, 24, '家宰就领他们进约瑟的屋里，给他们水洗脚，又给他们草料喂驴。'),
('CUV', '创世纪', 1, 43, 25, '他们就预备那礼物，等候约瑟晌午来，因为他们听见要在那里吃饭。'),
('CUV', '创世纪', 1, 43, 26, '约瑟来到家里，他们就把手中的礼物拿进屋去给他，又俯伏在地，向他下拜。'),
('CUV', '创世纪', 1, 43, 27, '约瑟问他们好，又问：『你们的父亲─就是你们所说的那老人家平安吗？他还在吗？』'),
('CUV', '创世纪', 1, 43, 28, '他们回答说：『你仆人─我们的父亲平安；他还在。』于是他们低头下拜。'),
('CUV', '创世纪', 1, 43, 29, '约瑟举目看见他同母的兄弟便雅悯，就说：『你们向我所说那顶小的兄弟就是这位吗？』又说：『小儿啊，愿神赐恩给你!』'),
('CUV', '创世纪', 1, 43, 30, '约瑟爱弟之情发动，就急忙寻找可哭之地，进入自己的屋里，哭了一场。'),
('CUV', '创世纪', 1, 43, 31, '他洗了脸出来，勉强隐忍，吩咐人摆饭。'),
('CUV', '创世纪', 1, 43, 32, '他们就为约瑟单摆了一席，为那些人又摆了一席，也为和约瑟同吃饭的埃及人另摆了一席，因为埃及人不可和希伯来人一同吃饭；那原是埃及人所厌恶的。'),
('CUV', '创世纪', 1, 43, 33, '约瑟使众弟兄在他面前排列坐席，都按著长幼的次序，众弟兄就彼此诧异。'),
('CUV', '创世纪', 1, 43, 34, '约瑟把他面前的食物分出来，送给他们；但便雅悯所得的比别人多五倍。他们就饮酒，和约瑟一同宴乐。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 44, 1, '约瑟吩咐家宰说：『把粮食装满这些人的口袋，尽著他们的驴所能驮的，又把各人的银子放在各人的口袋里，'),
('CUV', '创世纪', 1, 44, 2, '并将我的银杯和那少年人籴粮的银子一同装在他的口袋里。』家宰就照约瑟所说的话行了；'),
('CUV', '创世纪', 1, 44, 3, '天一亮就打发那些人带著驴走了。'),
('CUV', '创世纪', 1, 44, 4, '他们出城走了不远，约瑟对家宰说：『起来，追那些人去，追上了就对他们说：「你们为甚么以恶报善呢？'),
('CUV', '创世纪', 1, 44, 5, '这不是我主人饮酒的杯吗？岂不是他占卜用的吗？你们这样行是作恶了。」』'),
('CUV', '创世纪', 1, 44, 6, '家宰追上他们，将这些话对他们说了。'),
('CUV', '创世纪', 1, 44, 7, '他们回答说：『我主为甚么说这样的话呢？你仆人断不能作这样的事。'),
('CUV', '创世纪', 1, 44, 8, '你看，我们从前在口袋里所见的银子，尚且从迦南地带来还你，我们怎能从你主人家里偷窃金银呢？'),
('CUV', '创世纪', 1, 44, 9, '你仆人中无论在谁那里搜出来，就叫他死，我们也作我主的奴仆。』'),
('CUV', '创世纪', 1, 44, 10, '家宰说：『现在就照你们的话行吧!在谁那里搜出来，谁就作我的奴仆；其余的都没有罪。』'),
('CUV', '创世纪', 1, 44, 11, '于是他们各人急忙把口袋卸在地下，各人打开口袋。'),
('CUV', '创世纪', 1, 44, 12, '家宰就搜查，从年长的起到年幼的为止，那杯竟在便雅悯的口袋里搜出来。'),
('CUV', '创世纪', 1, 44, 13, '他们就撕裂衣服，各人把驮子抬在驴上，回城去了。'),
('CUV', '创世纪', 1, 44, 14, '犹大和他弟兄们来到约瑟的屋中，约瑟还在那里，他们就在他面前俯伏于地。'),
('CUV', '创世纪', 1, 44, 15, '约瑟对他们说：『你们作的是甚么事呢？你们岂不知像我这样的人必能占卜吗？』'),
('CUV', '创世纪', 1, 44, 16, '犹大说：『我们对我主说甚么呢？还有甚么话可说呢？我们怎能自己表白出来呢？神已经查出仆人的罪孽了。我们与那在他手中搜出杯来的都是我主的奴仆。'),
('CUV', '创世纪', 1, 44, 17, '约瑟说：『我断不能这样行!在谁的手中搜出杯来，谁就作我的奴仆；至于你们，可以平平安安地上你们父亲那里去。』'),
('CUV', '创世纪', 1, 44, 18, '犹大挨近他，说：『我主啊，求你容仆人说一句话给我主听，不要向仆人发烈怒，因为你如同法老一样。'),
('CUV', '创世纪', 1, 44, 19, '我主曾问仆人们说：「你们有父亲有兄弟没有？」'),
('CUV', '创世纪', 1, 44, 20, '我们对我主说：「我们有父亲，已经年老，还有他老年所生的一个小孩子。他哥哥死了，他母亲只撇下他一人，他父亲疼爱他。」'),
('CUV', '创世纪', 1, 44, 21, '你对仆人说：「把他带到我这里来，叫我亲眼看看他。」'),
('CUV', '创世纪', 1, 44, 22, '我们对我主说：童子不能离开他父亲，若是离开，他父亲必死。'),
('CUV', '创世纪', 1, 44, 23, '你对仆人说：你们的小兄弟若不与你们一同下来，你们就不得再见我的面。'),
('CUV', '创世纪', 1, 44, 24, '我们上到你仆人─我们父亲那里，就把我主的话告诉了他。'),
('CUV', '创世纪', 1, 44, 25, '我们的父亲说：你们再去给我籴些粮来。'),
('CUV', '创世纪', 1, 44, 26, '我们就说：我们不能下去。我们的小兄弟若和我们同往，我们就可以下去。因为，小兄弟若不与我们同往，我们必不得见那人的面。'),
('CUV', '创世纪', 1, 44, 27, '你仆人─我父亲对我们说：你们知道我的妻子给我生了两个儿子。'),
('CUV', '创世纪', 1, 44, 28, '一个离开我出去了；我说他必是被撕碎了，直到如今我也没有见他。'),
('CUV', '创世纪', 1, 44, 29, '现在你们又要把这个带去离开我，倘若他遭害，那便是你们使我白发苍苍、悲悲惨惨地下阴间去了。'),
('CUV', '创世纪', 1, 44, 30, '我父亲的命与这童子的命相连。如今我回到你仆人─我父亲那里，若没有童子与我们同在，'),
('CUV', '创世纪', 1, 44, 31, '我们的父亲见没有童子，他就必死。这便是我们使你仆人─我们的父亲白发苍苍、悲悲惨惨地下阴间去了。'),
('CUV', '创世纪', 1, 44, 32, '因为仆人曾向我父亲为这童子作保，说：我若不带他回来交给父亲，我便在父亲面前永远担罪。'),
('CUV', '创世纪', 1, 44, 33, '现在求你容仆人住下，替这童子作我主的奴仆，叫童子和他哥哥们一同上去。'),
('CUV', '创世纪', 1, 44, 34, '若童子不和我同去，我怎能上去见我父亲呢？恐怕我看见灾祸临到我父亲身上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 45, 1, '约瑟在左右站著的人面前情不自禁，吩咐一声说：人都要离开我出去！约瑟和弟兄相认的时候并没有一人站在他面前。'),
('CUV', '创世纪', 1, 45, 2, '他就放声大哭，埃及人和法老家中的人都听见了。'),
('CUV', '创世纪', 1, 45, 3, '约瑟对他弟兄们说：我是约瑟。我的父亲还在么？他弟兄不能回答，因为在他面前都惊惶。'),
('CUV', '创世纪', 1, 45, 4, '约瑟又对他弟兄们说：请你们近前来。他们就近前来。他说：我是你们的兄弟约瑟，就是你们所卖到埃及的。'),
('CUV', '创世纪', 1, 45, 5, '现在，不要因为把我卖到这里自忧自恨。这是神差我在你们以先来，为要保全生命。'),
('CUV', '创世纪', 1, 45, 6, '现在这地的饥荒已经二年了，还有五年不能耕种，不能收成。'),
('CUV', '创世纪', 1, 45, 7, '神差我在你们以先来，为要给你们存留余种在世上，又要大施拯救，保全你们的生命。'),
('CUV', '创世纪', 1, 45, 8, '这样看来，差我到这里来的不是你们，乃是神。他又使我如法老的父，作他全家的主，并埃及全地的宰相。'),
('CUV', '创世纪', 1, 45, 9, '你们要赶紧上到我父亲那里。对他说：你儿子约瑟这样说：神使我作全埃及的主，请你下到我这里来，不要耽延。'),
('CUV', '创世纪', 1, 45, 10, '你和你我儿子孙子，连牛群羊群，并一切所有的，都可以住在歌珊地，与我相近。'),
('CUV', '创世纪', 1, 45, 11, '我要在那里奉养你；因为还有五年的饥荒，免得你和你的眷属，并一切所有的，都败落了。'),
('CUV', '创世纪', 1, 45, 12, '况且你们的眼和我兄弟便雅悯的眼都看见是我亲口对你们说话。'),
('CUV', '创世纪', 1, 45, 13, '你们也要将我在埃及一切的荣耀和你们所看见的事都告诉我父亲，又要赶紧的将我父亲搬到我这里来。'),
('CUV', '创世纪', 1, 45, 14, '于是约瑟伏在他兄弟便雅悯的颈项上哭，便雅悯也在他的颈项上哭。'),
('CUV', '创世纪', 1, 45, 15, '他又与众弟兄亲嘴，抱著他们哭，随后他弟兄就和他说话。'),
('CUV', '创世纪', 1, 45, 16, '这风声传到法老的宫里，说：约瑟的弟兄们来了。法老和他的臣仆都很喜欢。'),
('CUV', '创世纪', 1, 45, 17, '法老对约瑟说：你吩咐你的弟兄们说：你们要这样行：把驮子抬在牲口上，起身往迦南地去。'),
('CUV', '创世纪', 1, 45, 18, '将你们的父亲和你们的眷属都搬到我这里来，我要把埃及地的美物赐给你们，你们也要吃这地肥美的出产。'),
('CUV', '创世纪', 1, 45, 19, '现在我吩咐你们要这样行：从埃及地带著车辆去，把你们的孩子和妻子，并你们的父亲都搬来。'),
('CUV', '创世纪', 1, 45, 20, '你们眼中不要爱惜你们的家具，因为埃及全地的美物都是你们的。'),
('CUV', '创世纪', 1, 45, 21, '以色列的儿子们就如此行。约瑟照著法老的吩咐给他们车辆和路上用的食物，'),
('CUV', '创世纪', 1, 45, 22, '又给他们各人一套衣服，惟独给便雅悯三百银子，五套衣服；'),
('CUV', '创世纪', 1, 45, 23, '送给他父亲公驴十匹，驮著埃及的美物，母驴十匹，驮著粮食与饼和菜，为他父亲路上用。'),
('CUV', '创世纪', 1, 45, 24, '于是约瑟打发他弟兄们回去，又对他们说：你们不要在路上相争。'),
('CUV', '创世纪', 1, 45, 25, '他们从埃及上去，来到迦南地、他们的父亲雅各那里，'),
('CUV', '创世纪', 1, 45, 26, '告诉他说：约瑟还在，并且作埃及全地的宰相。雅各心里冰凉，因为不信他们。'),
('CUV', '创世纪', 1, 45, 27, '他们便将约瑟对他们说的一切话都告诉了他。他们父亲雅各又看见约瑟打发来接他的车辆，心就苏醒了。'),
('CUV', '创世纪', 1, 45, 28, '以色列说：罢了！罢了！我的儿子约瑟还在，趁我未死以先，我要去见他一面。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 46, 1, '以色列带著一切所有的，起身来到别是巴，就献祭给他父亲以撒的神。'),
('CUV', '创世纪', 1, 46, 2, '夜间，神在异象中对以色列说：雅各！雅各！他说：我在这里。'),
('CUV', '创世纪', 1, 46, 3, '神说：我是神，就是你父亲的神。你下埃及去不要害怕，因为我必使你在那里成为大族。'),
('CUV', '创世纪', 1, 46, 4, '我要和你同下埃及去，也必定带你上来；约瑟必给你送终(原文作将手按在你的眼睛上)。'),
('CUV', '创世纪', 1, 46, 5, '雅各就从别是巴起行。以色列的儿子们使他们的父亲雅各和他们的妻子、儿女都坐在法老为雅各送来的车上。'),
('CUV', '创世纪', 1, 46, 6, '他们又带著迦南地所得的牲畜、货财来到埃及。雅各和他的一切子孙都一同来了，'),
('CUV', '创世纪', 1, 46, 7, '雅各把他的儿子、孙子、女儿、孙女，并他的子子孙孙，一同带到埃及。'),
('CUV', '创世纪', 1, 46, 8, '来到埃及的以色列人名字记在下面。雅各和他的儿孙：雅各的长子是流便。'),
('CUV', '创世纪', 1, 46, 9, '流便的儿子是哈诺、法路、希斯伦、迦米。'),
('CUV', '创世纪', 1, 46, 10, '西缅的儿子是耶母利、雅悯、阿辖、雅斤、琐辖，还有迦南女子所生的扫罗。'),
('CUV', '创世纪', 1, 46, 11, '利未的儿子是革顺、哥辖、米拉利。'),
('CUV', '创世纪', 1, 46, 12, '犹大的儿子是珥、俄南、示拉、法勒斯、谢拉；惟有珥与俄南死在迦南地。法勒斯的儿子是希斯伦、哈母勒。'),
('CUV', '创世纪', 1, 46, 13, '以萨迦的儿子是陀拉、普瓦、约伯、伸仑。'),
('CUV', '创世纪', 1, 46, 14, '西布伦的儿子是西烈、以伦、雅利。'),
('CUV', '创世纪', 1, 46, 15, '这是利亚在巴旦亚兰给雅各所生的儿子，还在女儿底拿。儿孙共三十三人。'),
('CUV', '创世纪', 1, 46, 16, '迦得的儿子是洗非芸、哈基、书尼、以斯本、以利、亚罗底、亚列利。'),
('CUV', '创世纪', 1, 46, 17, '亚设的儿子是音拿、亦施瓦、亦施韦、比利亚，还有他们的妹子西拉。比利亚的儿子是希别、玛结。'),
('CUV', '创世纪', 1, 46, 18, '这是拉班给他女儿利亚的婢女悉帕从雅各所生的儿孙，共有十六人。'),
('CUV', '创世纪', 1, 46, 19, '雅各之妻拉结的儿子是约瑟和便雅悯。'),
('CUV', '创世纪', 1, 46, 20, '约瑟在埃及地生了玛拿西和以法莲，就是安城的祭司波提非拉的女儿亚西纳给约瑟生的。'),
('CUV', '创世纪', 1, 46, 21, '便雅悯的儿子是比拉、比结、亚实别、基拉、乃幔、以希、罗实、母平、户平、亚勒。'),
('CUV', '创世纪', 1, 46, 22, '这是拉结给雅各所生的儿孙，共有十四人。'),
('CUV', '创世纪', 1, 46, 23, '但的儿子是户伸。'),
('CUV', '创世纪', 1, 46, 24, '拿弗他利的儿子是雅薛、沽尼、耶色、示冷。'),
('CUV', '创世纪', 1, 46, 25, '这是拉班给他女儿拉结的婢女辟拉从雅各所生的儿孙，共有七人。'),
('CUV', '创世纪', 1, 46, 26, '那与雅各同到埃及的，除了他儿妇之外，凡从他所生的，共有六十六人。'),
('CUV', '创世纪', 1, 46, 27, '还有约瑟在埃及所生的两个儿子。雅各家来到埃及的共有七十人。'),
('CUV', '创世纪', 1, 46, 28, '雅各打发犹大先去见约瑟，请派人引路往歌珊去；于是他们来到歌珊地。'),
('CUV', '创世纪', 1, 46, 29, '约瑟套车往歌珊去，迎接他父亲以色列，及至见了面，就伏在父亲的颈项，哭了许久。'),
('CUV', '创世纪', 1, 46, 30, '以色列对约瑟说：我既得见你的面，知道你还在，就是死我也甘心。'),
('CUV', '创世纪', 1, 46, 31, '约瑟对他的弟兄和他父的全家说：我要上去告诉法老，对他说：我的弟兄和我父的全家从前在迦南地，现今都到我这里来了。'),
('CUV', '创世纪', 1, 46, 32, '他们本是牧羊的人，以养牲畜为业；他们把羊群牛群和一切所有的都带来了。'),
('CUV', '创世纪', 1, 46, 33, '等法老召你们的时候，问你们说：你们以何事为业？'),
('CUV', '创世纪', 1, 46, 34, '你们要说：你的仆人，从幼年直到如今，都以养牲畜为业，连我们的祖宗也都以此为业。这样，你们可以住在歌珊地，因为凡牧羊的都被埃及人所厌恶。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 47, 1, '约瑟进去告诉法老说：我的父亲和我的弟兄带著羊群牛群，并一切所有的，从迦南地来了，如今在歌珊地。'),
('CUV', '创世纪', 1, 47, 2, '约瑟从他弟兄中挑出五个人来，引他们去见法老。'),
('CUV', '创世纪', 1, 47, 3, '法老问约瑟的弟兄说：你们以可事为业？他们对法老说：你仆人是牧羊的，连我们的祖宗也是牧羊的。'),
('CUV', '创世纪', 1, 47, 4, '他们又对法老说：迦南地的饥荒甚大，仆人的羊群没有草吃，所以我们来到这地寄居。现在求你容仆人住在歌珊地。'),
('CUV', '创世纪', 1, 47, 5, '法老对约瑟说：你父亲和你弟兄到你这里来了，'),
('CUV', '创世纪', 1, 47, 6, '埃及地都在你面前，只管叫你父亲和你弟兄住在国中最好的地；他们可以住在歌珊地。你若知道他们中间有甚么能人，就派他们看管我的牲畜。'),
('CUV', '创世纪', 1, 47, 7, '约瑟领他父亲雅各进到法老面前，雅各就给法老祝福。'),
('CUV', '创世纪', 1, 47, 8, '法老问雅各说：你平生的年日是多少呢？'),
('CUV', '创世纪', 1, 47, 9, '雅各对法老说：我寄居在世的年日是一百三十岁，我平生的年日又少又苦，不及我列祖早在世寄居的年日。'),
('CUV', '创世纪', 1, 47, 10, '雅各又给法老祝福，就从法老面前出去了。'),
('CUV', '创世纪', 1, 47, 11, '约瑟遵著法老的命，把埃及国最好的地，就是兰塞境内的地，给他父亲和弟兄居住，作为产业。'),
('CUV', '创世纪', 1, 47, 12, '约瑟用粮食奉养他父亲和他弟兄，并他父亲全家的眷属，都是照各家的人口奉养他们。'),
('CUV', '创世纪', 1, 47, 13, '饥荒甚大，全地都绝了粮，甚至埃及地和迦南地的人因那饥荒的缘故都饿昏了。'),
('CUV', '创世纪', 1, 47, 14, '约瑟收聚了埃及地和迦南地所有的银子，就是众人籴粮的银子，约瑟就把那银子带到法老的宫里。'),
('CUV', '创世纪', 1, 47, 15, '埃及地和迦南地的银子都花尽了，埃及众人都来见约瑟，说：我们的银子都用尽了，求你给我们粮食，我们为甚么死在你面前呢？'),
('CUV', '创世纪', 1, 47, 16, '约瑟说：若是银子用尽了，可以把你们的牲畜给我，我就为你们的牲畜给你们粮食。'),
('CUV', '创世纪', 1, 47, 17, '于是他们把牲畜赶到约瑟那里，约瑟就拿粮食换了他们的牛、羊、驴、马；那一年因换他们一切的牲畜，就用粮食养活他们。'),
('CUV', '创世纪', 1, 47, 18, '那一年过去，第二年他们又来见约瑟，说：我们不瞒我主，我们的银子都花尽了，牲畜也都归了我主。我们在我主眼前，除了我们的身体和田地之外，一无所剩。'),
('CUV', '创世纪', 1, 47, 19, '你何忍见我们人死地荒呢？求你用粮食买我们的我们的地，我们和我们的地就要给法老效力。又求你给我们种子，使我们得以存活，不至死亡，地土也不至荒凉。'),
('CUV', '创世纪', 1, 47, 20, '于是，约瑟为法老买了埃及所有的地，埃及人因被饥荒所迫，各都卖了自己的田地；那地就都归了法老。'),
('CUV', '创世纪', 1, 47, 21, '至于百姓，约瑟叫他们，从埃及这边直到埃及那边，都各归各城。'),
('CUV', '创世纪', 1, 47, 22, '惟有祭司的地，约瑟没有买，因为祭司有从法老所得的常俸。他们吃法老所给的常俸，所以他们不卖自己的地。'),
('CUV', '创世纪', 1, 47, 23, '约瑟对百姓说：我今日为法老买了你们和你们的地，看哪，这里有种子给你们，你们可以种地。'),
('CUV', '创世纪', 1, 47, 24, '后来打粮食的时候，你们要把五分之一纳给法老，四分可以归你们做地里的种子，也做你们和你们家口孩童的食物。'),
('CUV', '创世纪', 1, 47, 25, '他们说：你救了我们的性命。但愿我们在我主眼前蒙恩，我们就作法老的仆人。'),
('CUV', '创世纪', 1, 47, 26, '于是约瑟为埃及地定下常例，直到今日：法老必得五分之一，惟独祭司的地不归法老。'),
('CUV', '创世纪', 1, 47, 27, '以色列人住在埃及的歌珊地。他们在那里置了产业，并且生育甚多。'),
('CUV', '创世纪', 1, 47, 28, '雅各住在埃及地十七年，雅各平生的年日是一百四十七岁。'),
('CUV', '创世纪', 1, 47, 29, '以色列的死期临近了，他就叫了他儿子约瑟来，说：我若在你眼前蒙恩，请你把手放在我大腿底下，用慈爱和诚实待我，请你不要将我葬在埃及。'),
('CUV', '创世纪', 1, 47, 30, '我与我祖我父同睡的时候，你要将我带出埃及，葬在他们所葬的地方。约瑟说：我必遵著你的命而行。'),
('CUV', '创世纪', 1, 47, 31, '雅各说：你要向我起誓。约瑟就向他起了誓，于是以色列在床头上(或作扶著杖头)敬拜神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 48, 1, '这事以后，有人告诉约瑟说：你的父亲病了。他就带著两个儿子玛拿西和以法莲同去。'),
('CUV', '创世纪', 1, 48, 2, '有人告诉雅各说：请看，你儿子约瑟到你这里来了。以色列就勉强在床上坐起来。'),
('CUV', '创世纪', 1, 48, 3, '雅各对约瑟说：全能的神曾在迦南地的路斯向我显现，赐福与我，'),
('CUV', '创世纪', 1, 48, 4, '对我说：我必使你生养众多，成为多民，又要把这地赐给你的后裔，永远为业。'),
('CUV', '创世纪', 1, 48, 5, '未到埃及见你之先，你在埃及地所生的以法莲和玛拿西这两个儿子是我的，正如流便和西缅是我的一样。'),
('CUV', '创世纪', 1, 48, 6, '你在他们以后所生的就是你的，他们可以归于他们弟兄的名下得产业。'),
('CUV', '创世纪', 1, 48, 7, '至于我，我从巴旦来的时候，拉结死在我眼前，在迦南地的路上，离以法他还有一段路程，我就把他葬在以法他的路上〈以法他就是伯利恒〉。'),
('CUV', '创世纪', 1, 48, 8, '以色列看见约瑟的两个儿子，就说：这是谁？'),
('CUV', '创世纪', 1, 48, 9, '约瑟对他父亲说：这是神在这里赐给我的儿子。以色列说：请你领他们到我跟前，我要给他们祝福。'),
('CUV', '创世纪', 1, 48, 10, '以色列年纪老迈，眼睛昏花，不能看见。约瑟领他们到他跟前，他就和他们亲嘴，抱著他们。'),
('CUV', '创世纪', 1, 48, 11, '以色列对约瑟说：我想不到得见你的面，不料，神又使我得见你的儿子。'),
('CUV', '创世纪', 1, 48, 12, '约瑟把两个儿子从以色列两膝中领出来，自己就脸伏于地下拜。'),
('CUV', '创世纪', 1, 48, 13, '随后，约瑟又拉著他们两个，以法莲在他的右手里，对著以色列的左手，玛拿西在他的左手里，对著以色列的右手，领他们到以色列的跟前。'),
('CUV', '创世纪', 1, 48, 14, '以色列伸出右手来，按在以法莲的头上〈以法莲乃是次子〉，又剪搭过左手来，按在玛拿西的头上〈玛拿西原是长子〉。'),
('CUV', '创世纪', 1, 48, 15, '他就给约瑟祝福说：愿我祖亚伯拉罕和我父以撒所事奉的神，就是一生牧养我直到今日的神，'),
('CUV', '创世纪', 1, 48, 16, '救赎我脱离一切患难的那使者，赐福与这两个童子。愿他们归在我的名下和我祖亚伯拉罕、我父以撒的名下。又愿他们在世界中生养众多。'),
('CUV', '创世纪', 1, 48, 17, '约瑟见他父亲把右手按在以法莲的头上，就不喜悦，便提起他父亲的手，要从以法莲的头上挪到玛拿西的头上。'),
('CUV', '创世纪', 1, 48, 18, '约瑟对他父亲说：我父，不是这样。这本是长子，求你把右手按在他的头上。'),
('CUV', '创世纪', 1, 48, 19, '他父亲不从，说：我知道，我儿，我知道。他也必成为一族，也必昌大。只是他的兄弟将来比他还大；他兄弟的后裔要成为多族。'),
('CUV', '创世纪', 1, 48, 20, '当日就给他们祝福说：以色列人要指著你们祝福说：愿神使你如以法莲、玛拿西一样。于是立以法莲在玛拿西以上。'),
('CUV', '创世纪', 1, 48, 21, '以色列又对约瑟说：我要死了，但神必与你们同在，领你们回到你们列祖之地。'),
('CUV', '创世纪', 1, 48, 22, '并且我从前用弓用刀从亚摩利人手下夺的那块地，我都赐给你，使你比众弟兄多得一分。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 49, 1, '雅各叫了他的儿子们来，说：你们都来聚集，我好把你们日后必遇的事告诉你们。'),
('CUV', '创世纪', 1, 49, 2, '雅各的儿子们，你们要聚集而听，要听你们父亲以色列的话。'),
('CUV', '创世纪', 1, 49, 3, '流便哪，你是我的长子，是我力量强壮的时候生的，本当大有尊荣，权力超众。'),
('CUV', '创世纪', 1, 49, 4, '但你放纵情欲，滚沸如水，必不得居首位；因为你上了你父亲的床，污秽了我的榻。'),
('CUV', '创世纪', 1, 49, 5, '西缅和利未是弟兄；他们的刀剑是残忍的器具。'),
('CUV', '创世纪', 1, 49, 6, '我的灵阿，不要与他们同谋；我的心哪，不要与他们联络；因为他们趁怒杀害人命，任意砍断牛腿大筋。'),
('CUV', '创世纪', 1, 49, 7, '他们的怒气暴烈可咒；他们的忿恨残忍可诅。我要使他们分居在雅各家里，散住在以色列地中。'),
('CUV', '创世纪', 1, 49, 8, '犹大阿，你弟兄们必赞美你；你手必掐住仇敌的颈项；你父亲的儿子们必向你下拜。'),
('CUV', '创世纪', 1, 49, 9, '犹大是个小狮子；我儿阿，你抓了食便上去。你屈下身去，卧如公狮，蹲如母狮，谁敢惹你？'),
('CUV', '创世纪', 1, 49, 10, '圭必不离犹大，杖必不离他两脚之间，直等细罗(就是赐平安者)来到，万民都必归顺。'),
('CUV', '创世纪', 1, 49, 11, '犹大把小驴拴在葡萄树上，把驴驹拴在美好的葡萄树上。他在葡萄酒中洗了衣服，在葡萄汁中洗了袍褂。'),
('CUV', '创世纪', 1, 49, 12, '他的眼睛必因酒红润；他的牙齿必因奶白亮。'),
('CUV', '创世纪', 1, 49, 13, '西布伦必住在海口，必成为停船的海口；他的境界必延到西顿。'),
('CUV', '创世纪', 1, 49, 14, '以萨迦是个强壮的驴，卧在羊圈之中。'),
('CUV', '创世纪', 1, 49, 15, '他以安静为佳，以肥地为美，便低肩背重，成为服苦的仆人。'),
('CUV', '创世纪', 1, 49, 16, '但必判断他的民，作以色列支派之一。'),
('CUV', '创世纪', 1, 49, 17, '但必作道上的蛇，路中的虺，咬伤马蹄，使骑马的坠落于后。'),
('CUV', '创世纪', 1, 49, 18, '耶和华阿，我向来等候你的救恩。'),
('CUV', '创世纪', 1, 49, 19, '迦得必被敌军追逼，他却要追逼他们的脚跟。'),
('CUV', '创世纪', 1, 49, 20, '亚设之地必出肥美的粮食，且出君王的美味。'),
('CUV', '创世纪', 1, 49, 21, '拿弗他利是被释放的母鹿；他出嘉美的言语。'),
('CUV', '创世纪', 1, 49, 22, '约瑟是多结果子的树枝，是泉旁多结果的枝子；他的枝条探出墙外。'),
('CUV', '创世纪', 1, 49, 23, '弓箭手将他苦害，向他射箭，逼迫他。'),
('CUV', '创世纪', 1, 49, 24, '但他的弓仍旧坚硬；他的手健壮敏捷。这是因以色列的牧者，以色列的磐石─就是雅各的大能者。'),
('CUV', '创世纪', 1, 49, 25, '你父亲的神必帮助你；那全能者必将天上所有的福，地里所藏的福，以及生产乳养的福，都赐给你。'),
('CUV', '创世纪', 1, 49, 26, '你父亲所祝的福，胜过我祖先所祝的福，如永世的山岭，至极的边界；这些福必降在约瑟的头上，临到那与弟兄迥别之人的顶上。'),
('CUV', '创世纪', 1, 49, 27, '便雅悯是个撕掠的狼，早晨要吃他所抓的，晚上要分他所夺的。'),
('CUV', '创世纪', 1, 49, 28, '这一切是以色列的十二支派；这也是他们的父亲对他们所说的话，为他们所祝的福，都是按著各人的福分为他们祝福。'),
('CUV', '创世纪', 1, 49, 29, '他又嘱咐他们说：我将要归到我列祖(原文作本民)那里，你们要将我葬在赫人以弗仑田间的洞里，与我祖我父在一处，'),
('CUV', '创世纪', 1, 49, 30, '就是在迦南地幔利前、麦比拉田间的洞；那洞和田是亚伯拉罕向赫人以弗仑买来为业，作坟地的。'),
('CUV', '创世纪', 1, 49, 31, '他们在那里葬了亚伯拉罕和他妻撒拉，又在那里葬了以撒和他的妻子利百加；我也在那里葬了利亚。'),
('CUV', '创世纪', 1, 49, 32, '那块田和田间的洞原是向赫人买的。'),
('CUV', '创世纪', 1, 49, 33, '雅各嘱咐众子已毕，就把脚收在床上，气绝而死，归到列祖(原文作本民)那里去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '创世纪', 1, 50, 1, '约瑟伏在他父亲的面上哀哭，与他亲嘴。'),
('CUV', '创世纪', 1, 50, 2, '约瑟吩咐伺候他的医生用香料薰他父亲，医生就用香料薰了以色列。'),
('CUV', '创世纪', 1, 50, 3, '薰尸的常例是四十天；那四十天满了，埃及人为他哀哭了七十天。'),
('CUV', '创世纪', 1, 50, 4, '为他哀哭的日子过了，约瑟对法老家中的人说：我若在你们眼前蒙恩，请你们报告法老说：'),
('CUV', '创世纪', 1, 50, 5, '我父亲要死的时候叫我起誓说：你要将我葬在迦南地，在我为自己所掘的坟墓里。现在求你让我上去葬我父亲，以后我必回来。'),
('CUV', '创世纪', 1, 50, 6, '法老说：你可以上去，照著你父亲叫你起的誓，将他葬埋。'),
('CUV', '创世纪', 1, 50, 7, '于是约瑟上去葬他父亲。与他一同上去的，有法老的臣仆和法老家中的长老，并埃及国的长老，'),
('CUV', '创世纪', 1, 50, 8, '还有约瑟的全家和他的弟兄们，并他父亲的眷属；只有他们的妇人孩子，和羊群牛群，都留在歌珊地。'),
('CUV', '创世纪', 1, 50, 9, '又有车辆马兵，和他一同上去；那一帮人甚多。'),
('CUV', '创世纪', 1, 50, 10, '他们到了约但河外、亚达的禾场，就在那里大大地号咷痛哭。约瑟为他父亲哀哭了七天。'),
('CUV', '创世纪', 1, 50, 11, '迦南的居民见亚达禾场上的哀哭，就说：这是埃及人一场大的哀哭。因此那地方名叫亚伯麦西，是在约但河东。'),
('CUV', '创世纪', 1, 50, 12, '雅各的儿子们就遵著他父亲所吩咐的办了，'),
('CUV', '创世纪', 1, 50, 13, '把他搬到迦南地，葬在幔利前、麦比拉田间的洞里；那洞和田是亚伯拉罕向赫人以弗仑买来为业，作坟地的。'),
('CUV', '创世纪', 1, 50, 14, '约瑟葬了他父亲以后，就和众弟兄，并一切同他上去葬他父亲的人，都回埃及去了。'),
('CUV', '创世纪', 1, 50, 15, '约瑟的哥哥们见父亲死了，就说：或者约瑟怀恨我们，照著我们从前待他一切的恶足足的报复我们。'),
('CUV', '创世纪', 1, 50, 16, '他们就打发人去见约瑟，说：你父亲未死以先吩咐说：'),
('CUV', '创世纪', 1, 50, 17, '你们要对约瑟这样说：从前你哥哥们恶待你，求你饶恕他们的过犯和罪恶。如今求你饶恕你父亲神之仆人的过犯。他们对约瑟说这话，约瑟就哭了。'),
('CUV', '创世纪', 1, 50, 18, '他的哥哥们又来俯伏在他面前，说：我们是你的仆人。'),
('CUV', '创世纪', 1, 50, 19, '约瑟对他们说：不要害怕，我岂能代替神呢？'),
('CUV', '创世纪', 1, 50, 20, '从前你们的意思是要害我，但神的意思原是好的，要保全许多人的性命，成就今日的光景。'),
('CUV', '创世纪', 1, 50, 21, '现在你们不要害怕，我必养活你们和你们的妇人孩子。于是约瑟用亲爱的话安慰他们。'),
('CUV', '创世纪', 1, 50, 22, '约瑟和他父亲的眷属都住在埃及。约瑟活了一百一十岁。'),
('CUV', '创世纪', 1, 50, 23, '约瑟得见以法莲第三代的子孙。玛拿西的孙子、玛吉的儿子也养在约瑟的膝上。'),
('CUV', '创世纪', 1, 50, 24, '约瑟对他弟兄们说：我要死了，但神必定看顾你们，领你们从这地上去，到他起誓所应许给亚伯拉罕、以撒、雅各之地。'),
('CUV', '创世纪', 1, 50, 25, '约瑟叫以色列的子孙起誓说：神必定看顾你们；你们要把我的骸骨从这里搬上去。'),
('CUV', '创世纪', 1, 50, 26, '约瑟死了，正一百一十岁。人用香料将他薰了，把他收殓在棺材里，停在埃及。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 1, 1, '以色列的众子，各带家眷，和雅各一同来到埃及。他们的名字记在下面。'),
('CUV', '出埃及记', 2, 1, 2, '有流便、西缅、利未、犹大、'),
('CUV', '出埃及记', 2, 1, 3, '以萨迦、西布伦、便雅悯、'),
('CUV', '出埃及记', 2, 1, 4, '但、拿弗他利、迦得、亚设。'),
('CUV', '出埃及记', 2, 1, 5, '凡从雅各而生的，共有七十人。约瑟已经在埃及。'),
('CUV', '出埃及记', 2, 1, 6, '约瑟和他的弟兄，并那一代的人，都死了。'),
('CUV', '出埃及记', 2, 1, 7, '以色列人生养众多，并且繁茂，极其强盛，满了那地。'),
('CUV', '出埃及记', 2, 1, 8, '有不认识约瑟的新王起来，治理埃及，'),
('CUV', '出埃及记', 2, 1, 9, '对他的百姓说：看哪，这以色列民比我们还多，又比我们强盛。'),
('CUV', '出埃及记', 2, 1, 10, '来罢，我们不如用巧计待他们，恐怕他们多起来，日后若遇甚么争战的事，就连合我们的仇敌攻击我们，离开这地去了。'),
('CUV', '出埃及记', 2, 1, 11, '于是埃及人派督工的辖制他们，加重担苦害他们。他们为法老建造两座积货城，就是比东和兰塞。'),
('CUV', '出埃及记', 2, 1, 12, '只是越发苦害他们，他们越发多起来，越发蔓延；埃及人就因以色列人愁烦。'),
('CUV', '出埃及记', 2, 1, 13, '埃及人严严的使以色列人做工，'),
('CUV', '出埃及记', 2, 1, 14, '使他们因做苦工觉得命苦；无论是和泥，是作砖，是作田间各样的工，在一切的工上都严严的待他们。'),
('CUV', '出埃及记', 2, 1, 15, '有希伯来的两个收生婆，一名施弗拉，一名普阿；埃及王对他们说：'),
('CUV', '出埃及记', 2, 1, 16, '你们为希伯来妇人收生，看他们临盆的时候，若是男孩，就把他杀了；若是女孩，就留他存活。'),
('CUV', '出埃及记', 2, 1, 17, '但是收生婆敬畏神，不照埃及王的吩咐行，竟存留男孩的性命。'),
('CUV', '出埃及记', 2, 1, 18, '埃及王召了收生婆来，说：你们为甚么做这事，存留男孩的性命呢？'),
('CUV', '出埃及记', 2, 1, 19, '收生婆对法老说：因为希伯来妇人与埃及妇人不同；希伯来妇人本是健壮的（原文作活泼的），收生婆还没有到，他们已经生产了。'),
('CUV', '出埃及记', 2, 1, 20, '神厚待收生婆。以色列人多起来，极其强盛。'),
('CUV', '出埃及记', 2, 1, 21, '收生婆因为敬畏神，神便叫他们成立家室。'),
('CUV', '出埃及记', 2, 1, 22, '法老吩咐他的众民说：以色列人所生的男孩，你们都要丢在河里；一切的女孩，你们要存留他的性命。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 2, 1, '有一个利未家的人娶了一个利未女子为妻。'),
('CUV', '出埃及记', 2, 2, 2, '那女人怀孕，生一个儿子，见他俊美，就藏了他三个月，'),
('CUV', '出埃及记', 2, 2, 3, '后来不能再藏，就取了一个蒲草箱，抹上石漆和石油，将孩子放在里头，把箱子搁在河边的芦荻中。'),
('CUV', '出埃及记', 2, 2, 4, '孩子的姊姊远远站著，要知道他究竟怎么样。'),
('CUV', '出埃及记', 2, 2, 5, '法老的女儿来到河边洗澡，他的使女们在河边行走。他看见箱子在芦荻中，就打发一个婢女拿来。'),
('CUV', '出埃及记', 2, 2, 6, '他打开箱子，看见那孩子。孩子哭了，他就可怜他，说：「这是希伯来人的一个孩子。」'),
('CUV', '出埃及记', 2, 2, 7, '孩子的姊姊对法老的女儿说：「我去在希伯来妇人中叫一个奶妈来，为你奶这孩子，可以不可以？」'),
('CUV', '出埃及记', 2, 2, 8, '法老的女儿说：「可以。」童女就去叫了孩子的母亲来。'),
('CUV', '出埃及记', 2, 2, 9, '法老的女儿对他说：「你把这孩子抱去，为我奶他，我必给你工价。」妇人就抱了孩子去奶他。'),
('CUV', '出埃及记', 2, 2, 10, '孩子渐长，妇人把他带到法老的女儿那里，就作了他的儿子。他给孩子起名叫摩西，意思说：因我把他从水里拉出来。'),
('CUV', '出埃及记', 2, 2, 11, '后来，摩西长大，他出去到他弟兄那里，看他们的重担，见一个埃及人打希伯来人的一个弟兄。'),
('CUV', '出埃及记', 2, 2, 12, '他左右观看，见没有人，就把埃及人打死了，藏在沙土里。'),
('CUV', '出埃及记', 2, 2, 13, '第二天他出去，见有两个希伯来人争斗，就对那欺负人的说：「你为甚么打你同族的人呢？」'),
('CUV', '出埃及记', 2, 2, 14, '那人说：「谁立你作我们的首领和审判官呢？难道你要杀我，像杀那埃及人么？」摩西便惧怕，说：「这事必是被人知道了。」'),
('CUV', '出埃及记', 2, 2, 15, '法老听见这事，就想杀摩西，但摩西躲避法老，逃往米甸地居住。'),
('CUV', '出埃及记', 2, 2, 16, '一日，他在井旁坐下。米甸的祭司有七个女儿；他们来打水，打满了槽，要饮父亲的群羊。'),
('CUV', '出埃及记', 2, 2, 17, '有牧羊的人来，把他们赶走了，摩西却起来帮助他们，又饮了他们的群羊。'),
('CUV', '出埃及记', 2, 2, 18, '他们来到父亲流珥那里；他说：「今日你们为何来得这么快呢？」'),
('CUV', '出埃及记', 2, 2, 19, '他们说：「有一个埃及人救我们脱离牧羊人的手，并且为我们打水饮了群羊。」'),
('CUV', '出埃及记', 2, 2, 20, '他对女儿们说：「那个人在那里？你们为甚么撇下他呢？你们去请他来吃饭。」'),
('CUV', '出埃及记', 2, 2, 21, '摩西甘心和那人同住；那人把他的女儿西坡拉给摩西为妻。'),
('CUV', '出埃及记', 2, 2, 22, '西坡拉生了一个儿子，摩西给他起名叫革舜，意思说：「因我在外邦作了寄居的。」'),
('CUV', '出埃及记', 2, 2, 23, '过了多年，埃及王死了。以色列人因做苦工，就叹息哀求，他们的哀声达于神。'),
('CUV', '出埃及记', 2, 2, 24, '神听见他们的哀声，就记念他与亚伯拉罕、以撒、雅各所立的约。'),
('CUV', '出埃及记', 2, 2, 25, '神看顾以色列人，也知道他们的苦情。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 3, 1, '摩西牧养他岳父米甸祭司叶忒罗的羊群；一日领羊群往野外去，到了神的山，就是何烈山。'),
('CUV', '出埃及记', 2, 3, 2, '耶和华的使者从荆棘里火燄中向摩西显现。摩西观看，不料，荆棘被火烧著，却没有烧毁。'),
('CUV', '出埃及记', 2, 3, 3, '摩西说：我要过去看这大异象，这荆棘为何没有烧坏呢？'),
('CUV', '出埃及记', 2, 3, 4, '耶和华神见他过去要看，就从荆棘里呼叫说：摩西！摩西！他说：我在这里。'),
('CUV', '出埃及记', 2, 3, 5, '神说：不要近前来。当把你脚上的鞋脱下来，因为你所站之地是圣地；'),
('CUV', '出埃及记', 2, 3, 6, '又说：我是你父亲的神，是亚伯拉罕的神，以撒的神，雅各的神。摩西蒙上脸，因为怕看神。'),
('CUV', '出埃及记', 2, 3, 7, '耶和华说：我的百姓在埃及所受的困苦，我实在看见了；他们因受督工的辖制所发的哀声，我也听见了。我原知道他们的痛苦，'),
('CUV', '出埃及记', 2, 3, 8, '我下来是要救他们脱离埃及人的手，领他们出了那地，到美好、宽阔、流奶与蜜之地，就是到迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人之地。'),
('CUV', '出埃及记', 2, 3, 9, '现在以色列人的哀声达到我耳中，我也看见埃及人怎样欺压他们。'),
('CUV', '出埃及记', 2, 3, 10, '故此，我要打发你去见法老，使你可以将我的百姓以色列人从埃及领出来。'),
('CUV', '出埃及记', 2, 3, 11, '摩西对神说：我是甚么人，竟能去见法老，将以色列人从埃及领出来呢？'),
('CUV', '出埃及记', 2, 3, 12, '神说：我必与你同在。你将百姓从埃及领出来之后，你们必在这山上事奉我；这就是我打发你去的证据。'),
('CUV', '出埃及记', 2, 3, 13, '摩西对神说：我到以色列人那里，对他们说：你们祖宗的神打发我到你们这里来。他们若问我说：他叫甚么名字？我要对他们说甚么呢？'),
('CUV', '出埃及记', 2, 3, 14, '神对摩西说：我是自有永有的；又说：你要对以色列人这样说：那自有的打发我到你们这里来。'),
('CUV', '出埃及记', 2, 3, 15, '神又对摩西说：你要对以色列人这样说：耶和华─你们祖宗的神，就是亚伯拉罕的神，以撒的神，雅各的神，打发我到你们这里来。耶和华是我的名，直到永远；这也是我的纪念，直到万代。'),
('CUV', '出埃及记', 2, 3, 16, '你去招聚以色列的长老，对他们说：耶和华你们祖宗的神，就是亚伯拉罕的神，以撒的神，雅各的神，向我显现，说：我实在眷顾了你们，我也看见埃及人怎样待你们。'),
('CUV', '出埃及记', 2, 3, 17, '我也说：要将你们从埃及的困苦中领出来，往迦南人、赫人、亚摩利人、比利洗人、希未人、耶布斯人的地去，就是到流奶与蜜之地。'),
('CUV', '出埃及记', 2, 3, 18, '他们必听你的话。你和以色列的长老要去见埃及王，对他说：耶和华希伯来人的神遇见了我们，现在求你容我们往旷野去，走三天的路程，为要祭祀耶和华我们的神。'),
('CUV', '出埃及记', 2, 3, 19, '我知道虽用大能的手，埃及王也不容你们去。'),
('CUV', '出埃及记', 2, 3, 20, '我必伸手在埃及中间施行我一切的奇事，攻击那地，然后他才容你们去。'),
('CUV', '出埃及记', 2, 3, 21, '我必叫你们在埃及人眼前蒙恩，你们去的时候就不至于空手而去。'),
('CUV', '出埃及记', 2, 3, 22, '但各妇女必向他的邻舍，并居住在他家里的女人，要金器银器和衣裳，好给你们的儿女穿戴。这样你们就把埃及人的财物夺去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 4, 1, '摩西回答说：他们必不信我，也不听我的话，必说：耶和华并没有向你显现。'),
('CUV', '出埃及记', 2, 4, 2, '耶和华对摩西说：你手里是甚么？他说：是杖。'),
('CUV', '出埃及记', 2, 4, 3, '耶和华说：丢在地上。他一丢下去，就变作蛇；摩西便跑开。'),
('CUV', '出埃及记', 2, 4, 4, '耶和华对摩西说：伸出手来，拿住他的尾巴，他必在你手中仍变为杖；'),
('CUV', '出埃及记', 2, 4, 5, '如此好叫他们信耶和华─他们祖宗的神，就是亚伯拉罕的神，以撒的神，雅各的神，是向你显现了。'),
('CUV', '出埃及记', 2, 4, 6, '耶和华又对他说：把手放在怀里。他就把手放在怀里，及至抽出来，不料，手长了大痲疯，有雪那样白。'),
('CUV', '出埃及记', 2, 4, 7, '耶和华说：再把手放在怀里。他就再把手放在怀里，及至从怀里抽出来，不料，手已经复原，与周身的肉一样；'),
('CUV', '出埃及记', 2, 4, 8, '又说：倘或他们不听你的话，也不信头一个神迹，他们必信第二个神迹。'),
('CUV', '出埃及记', 2, 4, 9, '这两个神迹若都不信，也不听你的话，你就从河里取些水，倒在旱地上，你从河里取的水必在旱地上变作血。'),
('CUV', '出埃及记', 2, 4, 10, '摩西对耶和华说：主阿，我素日不是能言的人，就是从你对仆人说话以后，也是这样。我本是拙口笨舌的。'),
('CUV', '出埃及记', 2, 4, 11, '耶和华对他说：谁造人的口呢？谁使人口哑、耳聋、目明、眼瞎呢？岂不是我─耶和华么？'),
('CUV', '出埃及记', 2, 4, 12, '现在去罢，我必赐你口才，指教你所当说的话。'),
('CUV', '出埃及记', 2, 4, 13, '摩西说：主阿，你愿意打发谁，就打发谁去罢！'),
('CUV', '出埃及记', 2, 4, 14, '耶和华向摩西发怒说：不是有你的哥哥利未人亚伦么？我知道他是能言的；现在他出来迎接你，他一见你，心里就欢喜。'),
('CUV', '出埃及记', 2, 4, 15, '你要将当说的话传给他；我也要赐你和他口才，又要指教你们所当行的事。'),
('CUV', '出埃及记', 2, 4, 16, '他要替你对百姓说话；你要以他当作口，他要以你当作神。'),
('CUV', '出埃及记', 2, 4, 17, '你手里要拿这杖，好行神迹。'),
('CUV', '出埃及记', 2, 4, 18, '于是，摩西回到他岳父叶忒罗那里，对他说：求你容我回去见我在埃及的弟兄，看他们还在不在。叶忒罗对摩西说：你可以平平安安地去罢！'),
('CUV', '出埃及记', 2, 4, 19, '耶和华在米甸对摩西说：你要回埃及去，因为寻索你命的人都死了。'),
('CUV', '出埃及记', 2, 4, 20, '摩西就带著妻子和两个儿子，叫他们骑上驴，回埃及地去。摩西手里拿著神的杖。'),
('CUV', '出埃及记', 2, 4, 21, '耶和华对摩西说：你回到埃及的时候，要留意将我指示你的一切奇事行在法老面前。但我要使（或作：任凭；下同）他的心刚硬，他必不容百姓去。'),
('CUV', '出埃及记', 2, 4, 22, '你要对法老说：耶和华这样说：以色列是我的儿子，我的长子。'),
('CUV', '出埃及记', 2, 4, 23, '我对你说过：容我的儿子去，好事奉我。你还是不肯容他去。看哪，我要杀你的长子。'),
('CUV', '出埃及记', 2, 4, 24, '摩西在路上住宿的地方，耶和华遇见他，想要杀他。'),
('CUV', '出埃及记', 2, 4, 25, '西坡拉就拿一块火石，割下他儿子的阳皮，丢在摩西脚前，说：你真是我的血郎了。'),
('CUV', '出埃及记', 2, 4, 26, '这样，耶和华才放了他。西坡拉说：你因割礼就是血郎了。'),
('CUV', '出埃及记', 2, 4, 27, '耶和华对亚伦说：你往旷野去迎接摩西。他就去，在神的山遇见摩西，和他亲嘴。'),
('CUV', '出埃及记', 2, 4, 28, '摩西将耶和华打发他所说的言语和嘱咐他所行的神迹都告诉了亚伦。'),
('CUV', '出埃及记', 2, 4, 29, '摩西、亚伦就去招聚以色列的众长老。'),
('CUV', '出埃及记', 2, 4, 30, '亚伦将耶和华对摩西所说的一切话述说了一遍，又在百姓眼前行了那些神迹，'),
('CUV', '出埃及记', 2, 4, 31, '百姓就信了。以色列人听见耶和华眷顾他们，鉴察他们的困苦，就低头下拜。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 5, 1, '后来摩西、亚伦去对法老说：耶和华─以色列的神这样说：容我的百姓去，在旷野向我守节。'),
('CUV', '出埃及记', 2, 5, 2, '法老说：耶和华是谁，使我听他的话，容以色列人去呢？我不认识耶和华，也不容以色列人去！'),
('CUV', '出埃及记', 2, 5, 3, '他们说：希伯来人的神遇见了我们。求你容我们往旷野去，走三天的路程，祭祀耶和华─我们的神，免得他用瘟疫、刀兵攻击我们。'),
('CUV', '出埃及记', 2, 5, 4, '埃及王对他们说：摩西、亚伦！你们为甚么叫百姓旷工呢？你们去担你们的担子罢！'),
('CUV', '出埃及记', 2, 5, 5, '又说：看哪，这地的以色列人如今众多，你们竟叫他们歇下担子！'),
('CUV', '出埃及记', 2, 5, 6, '当天，法老吩咐督工的和官长说：'),
('CUV', '出埃及记', 2, 5, 7, '你们不可照常把草给百姓做砖，叫他们自己去捡草。'),
('CUV', '出埃及记', 2, 5, 8, '他们素常做砖的数目，你们仍旧向他们要，一点不可减少；因为他们是懒惰的，所以呼求说：容我们去祭祀我们的神。'),
('CUV', '出埃及记', 2, 5, 9, '你们要把更重的工夫加在这些人身上，叫他们劳碌，不听虚谎的言语。'),
('CUV', '出埃及记', 2, 5, 10, '督工的和官长出来对百姓说：法老这样说：我不给你们草。'),
('CUV', '出埃及记', 2, 5, 11, '你们自己在那里能找草，就往那里去找罢！但你们的工一点不可减少。'),
('CUV', '出埃及记', 2, 5, 12, '于是百姓散在埃及遍地，捡碎秸当作草。'),
('CUV', '出埃及记', 2, 5, 13, '督工的催著说：你们一天当完一天的工，与先前有草一样。'),
('CUV', '出埃及记', 2, 5, 14, '法老督工的，责打他所派以色列人的官长，说：你们昨天今天为甚么没有照向来的数目做砖、完你们的工作呢？'),
('CUV', '出埃及记', 2, 5, 15, '以色列人的官长就来哀求法老说：为甚么这样待你的仆人？'),
('CUV', '出埃及记', 2, 5, 16, '督工的不把草给仆人，并且对我们说：做砖罢！看哪，你仆人挨了打，其实是你百姓的错。'),
('CUV', '出埃及记', 2, 5, 17, '但法老说：你们是懒惰的！你们是懒惰的！所以说：容我们去祭祀耶和华。'),
('CUV', '出埃及记', 2, 5, 18, '现在你们去做工罢！草是不给你们的，砖却要如数交纳。'),
('CUV', '出埃及记', 2, 5, 19, '以色列人的官长听说你们每天做砖的工作一点不可减少，就知道是遭遇祸患了。'),
('CUV', '出埃及记', 2, 5, 20, '他们离了法老出来，正遇见摩西、亚伦站在对面，'),
('CUV', '出埃及记', 2, 5, 21, '就向他们说：愿耶和华鉴察你们，施行判断；因你们使我们在法老和他臣仆面前有了臭名，把刀递在他们手中杀我们。'),
('CUV', '出埃及记', 2, 5, 22, '摩西回到耶和华那里，说：主阿，你为甚么苦待这百姓呢？为甚么打发我去呢？'),
('CUV', '出埃及记', 2, 5, 23, '自从我去见法老，奉你的名说话，他就苦待这百姓，你一点也没有拯救他们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 6, 1, '耶和华对摩西说：现在你必看见我向法老所行的事，使他因我大能的手容以色列人去，且把他们赶出他的地。'),
('CUV', '出埃及记', 2, 6, 2, '神晓谕摩西说：我是耶和华。'),
('CUV', '出埃及记', 2, 6, 3, '我从前向亚伯拉罕、以撒、雅各显现为全能的神；至于我名耶和华，他们未曾知道。'),
('CUV', '出埃及记', 2, 6, 4, '我与他们坚定所立的约，要把他们寄居的迦南地赐给他们。'),
('CUV', '出埃及记', 2, 6, 5, '我也听见以色列人被埃及人苦待的哀声，我也记念我的约。'),
('CUV', '出埃及记', 2, 6, 6, '所以你要对以色列人说：我是耶和华；我要用伸出来的膀臂重重的刑罚埃及人，救赎你们脱离他们的重担，不做他们的苦工。'),
('CUV', '出埃及记', 2, 6, 7, '我要以你们为我的百姓，我也要作你们的神。你们要知道我是耶和华─你们的神，是救你们脱离埃及人之重担的。'),
('CUV', '出埃及记', 2, 6, 8, '我起誓应许给亚伯拉罕、以撒、雅各的那地，我要把你们领进去，将那地赐给你们为业。我是耶和华。'),
('CUV', '出埃及记', 2, 6, 9, '摩西将这话告诉以色列人，只是他们因苦工愁烦，不肯听他的话。'),
('CUV', '出埃及记', 2, 6, 10, '耶和华晓谕摩西说：'),
('CUV', '出埃及记', 2, 6, 11, '你进去对埃及王法老说，要容以色列人出他的地。'),
('CUV', '出埃及记', 2, 6, 12, '摩西在耶和华面前说：以色列人尚且不听我的话，法老怎肯听我这拙口笨舌的人呢？'),
('CUV', '出埃及记', 2, 6, 13, '耶和华吩咐摩西、亚伦往以色列人和埃及王法老那里去，把以色列人从埃及地领出来。'),
('CUV', '出埃及记', 2, 6, 14, '以色列人家长的名字记在下面。以色列长子流便的儿子是哈诺、法路、希斯仑、迦米；这是流便的各家。'),
('CUV', '出埃及记', 2, 6, 15, '西缅的儿子是耶母利、雅悯、阿辖、雅斤、琐辖，和迦南女子的儿子扫罗；这是西缅的各家。'),
('CUV', '出埃及记', 2, 6, 16, '利未众子的名字按著他们的后代记在下面：就是革顺、哥辖、米拉利。利未一生的岁数是一百三十七岁。'),
('CUV', '出埃及记', 2, 6, 17, '革顺的儿子按著家室是立尼、示每。'),
('CUV', '出埃及记', 2, 6, 18, '哥辖的儿子是暗兰、以斯哈、希伯伦、乌薛。哥辖一生的岁数是一百三十三岁。'),
('CUV', '出埃及记', 2, 6, 19, '米拉利的儿子是抹利和母示；这是利未的家，都按著他们的后代。'),
('CUV', '出埃及记', 2, 6, 20, '暗兰娶了他父亲的妹妹约基别为妻，他给他生了亚伦和摩西。暗兰一生的岁数是一百三十七岁。'),
('CUV', '出埃及记', 2, 6, 21, '以斯哈的儿子是可拉、尼斐、细基利。'),
('CUV', '出埃及记', 2, 6, 22, '乌薛的儿子是米沙利、以利撒反、西提利。'),
('CUV', '出埃及记', 2, 6, 23, '亚伦娶了亚米拿达的女儿，拿顺的妹妹，以利沙巴为妻，他给他生了拿答、亚比户、以利亚撒、以他玛。'),
('CUV', '出埃及记', 2, 6, 24, '可拉的儿子是亚惜、以利加拿、亚比亚撒；这是可拉的各家。'),
('CUV', '出埃及记', 2, 6, 25, '亚伦的儿子以利亚撒娶了普铁的一个女儿为妻，他给他生了非尼哈。这是利未人的家长，都按著他们的家。'),
('CUV', '出埃及记', 2, 6, 26, '耶和华说：将以色列人按著他们的军队从埃及地领出来。这是对那亚伦、摩西说的。'),
('CUV', '出埃及记', 2, 6, 27, '对埃及王法老说要将以色列人从埃及领出来的，就是这摩西、亚伦。'),
('CUV', '出埃及记', 2, 6, 28, '当耶和华在埃及地对摩西说话的日子，'),
('CUV', '出埃及记', 2, 6, 29, '他向摩西说：我是耶和华；我对你说的一切话，你都要告诉埃及王法老。'),
('CUV', '出埃及记', 2, 6, 30, '摩西在耶和华面前说：看哪，我是拙口笨舌的人，法老怎肯听我呢？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 7, 1, '耶和华对摩西说：我使你在法老面前代替神，你的哥哥亚伦是替你说话的。'),
('CUV', '出埃及记', 2, 7, 2, '凡我所吩咐你的，你都要说。你的哥哥亚伦要对法老说，容以色列人出他的地。'),
('CUV', '出埃及记', 2, 7, 3, '我要使法老的心刚硬，也要在埃及地多行神迹奇事。'),
('CUV', '出埃及记', 2, 7, 4, '但法老必不听你们；我要伸手重重的刑罚埃及，将我的军队以色列民从埃及地领出来。'),
('CUV', '出埃及记', 2, 7, 5, '我伸手攻击埃及，将以色列人从他们中间领出来的时候，埃及人就要知道我是耶和华。'),
('CUV', '出埃及记', 2, 7, 6, '摩西、亚伦这样行；耶和华怎样吩咐他们，他们就照样行了。'),
('CUV', '出埃及记', 2, 7, 7, '摩西、亚伦与法老说话的时候，摩西八十岁，亚伦八十三岁。'),
('CUV', '出埃及记', 2, 7, 8, '耶和华晓谕摩西、亚伦说：'),
('CUV', '出埃及记', 2, 7, 9, '法老若对你们说：你们行件奇事罢！你就吩咐亚伦说：把杖丢在法老面前，使杖变作蛇。'),
('CUV', '出埃及记', 2, 7, 10, '摩西、亚伦进去见法老，就照耶和华所吩咐的行。亚伦把杖丢在法老和臣仆面前，杖就变作蛇。'),
('CUV', '出埃及记', 2, 7, 11, '于是法老召了博士和术士来；他们是埃及行法术的，也用邪术照样而行。'),
('CUV', '出埃及记', 2, 7, 12, '他们各人丢下自己的杖，杖就变作蛇；但亚伦的杖吞了他们的杖。'),
('CUV', '出埃及记', 2, 7, 13, '法老心里刚硬，不肯听从摩西、亚伦，正如耶和华所说的。'),
('CUV', '出埃及记', 2, 7, 14, '耶和华对摩西说：法老心里固执，不肯容百姓去。'),
('CUV', '出埃及记', 2, 7, 15, '明日早晨，他出来往水边去，你要往河边迎接他，手里要拿著那变过蛇的杖，'),
('CUV', '出埃及记', 2, 7, 16, '对他说：耶和华─希伯来人的神打发我来见你，说：容我的百姓去，好在旷野事奉我。到如今你还是不听。'),
('CUV', '出埃及记', 2, 7, 17, '耶和华这样说：我要用我手里的杖击打河中的水，水就变作血；因此，你必知道我是耶和华。'),
('CUV', '出埃及记', 2, 7, 18, '河里的鱼必死，河也要腥臭，埃及人就要厌恶吃这河里的水。'),
('CUV', '出埃及记', 2, 7, 19, '耶和华晓谕摩西说：你对亚伦说：把你的杖伸在埃及所有的水以上，就是在他们的江、河、池、塘以上，叫水都变作血。在埃及遍地，无论在木器中，石器中，都必有血。'),
('CUV', '出埃及记', 2, 7, 20, '摩西、亚伦就照耶和华所吩咐的行。亚伦在法老和臣仆眼前举杖击打河里的水，河里的水都变作血了。'),
('CUV', '出埃及记', 2, 7, 21, '河里的鱼死了，河也腥臭了，埃及人就不能吃这河里的水；埃及遍地都有了血。'),
('CUV', '出埃及记', 2, 7, 22, '埃及行法术的，也用邪术照样而行。法老心里刚硬，不肯听摩西、亚伦，正如耶和华所说的。'),
('CUV', '出埃及记', 2, 7, 23, '法老转身进宫，也不把这事放在心上。'),
('CUV', '出埃及记', 2, 7, 24, '埃及人都在河的两边挖地，要得水喝，因为他们不能喝这河里的水。'),
('CUV', '出埃及记', 2, 7, 25, '耶和华击打河以后满了七天。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 8, 1, '耶和华吩咐摩西说：你进去见法老，对他说：耶和华这样说：容我的百姓去，好事奉我。'),
('CUV', '出埃及记', 2, 8, 2, '你若不肯容他们去，我必使青蛙蹧蹋你的四境。'),
('CUV', '出埃及记', 2, 8, 3, '河里要滋生青蛙；这青蛙要上来进你的宫殿和你的卧房，上你的床榻，进你臣仆的房屋，上你百姓的身上，进你的炉灶和你的抟面盆，'),
('CUV', '出埃及记', 2, 8, 4, '又要上你和你百姓并你众臣仆的身上。'),
('CUV', '出埃及记', 2, 8, 5, '耶和华晓谕摩西说：你对亚伦说：把你的杖伸在江、河、池以上，使青蛙到埃及地上来。'),
('CUV', '出埃及记', 2, 8, 6, '亚伦便伸杖在埃及的诸水以上，青蛙就上来，遮满了埃及地。'),
('CUV', '出埃及记', 2, 8, 7, '行法术的也用他们的邪术照样而行，叫青蛙上了埃及地。'),
('CUV', '出埃及记', 2, 8, 8, '法老召了摩西、亚伦来，说：请你们求耶和华使这青蛙离开我和我的民，我就容百姓去祭祀耶和华。'),
('CUV', '出埃及记', 2, 8, 9, '摩西对法老说：任凭你罢，我要何时为你和你的臣仆并你的百姓祈求，除灭青蛙离开你和你的宫殿只留在河里呢？'),
('CUV', '出埃及记', 2, 8, 10, '他说：明天。摩西说：可以照你的话罢，好叫你知道没有像耶和华─我们神的。'),
('CUV', '出埃及记', 2, 8, 11, '青蛙要离开你和你的宫殿，并你的臣仆与你的百姓，只留在河里。'),
('CUV', '出埃及记', 2, 8, 12, '于是摩西、亚伦离开法老出去。摩西为扰害法老的青蛙呼求耶和华。'),
('CUV', '出埃及记', 2, 8, 13, '耶和华就照摩西的话行。凡在房里、院中、田间的青蛙都死了。'),
('CUV', '出埃及记', 2, 8, 14, '众人把青蛙聚拢成堆，遍地就都腥臭。'),
('CUV', '出埃及记', 2, 8, 15, '但法老见灾祸松缓，就硬著心，不肯听他们，正如耶和华所说的。'),
('CUV', '出埃及记', 2, 8, 16, '耶和华吩咐摩西说：你对亚伦说：伸出你的杖击打地上的尘土，使尘土在埃及遍地变作虱子（或译：虼蚤；下同）。'),
('CUV', '出埃及记', 2, 8, 17, '他们就这样行。亚伦伸杖击打地上的尘土，就在人身上和牲畜身上有了虱子；埃及遍地的尘土都变成虱子了。'),
('CUV', '出埃及记', 2, 8, 18, '行法术的也用邪术要生出虱子来，却是不能。于是在人身上和牲畜身上都有了虱子。'),
('CUV', '出埃及记', 2, 8, 19, '行法术的就对法老说：这是神的手段。法老心里刚硬，不肯听摩西、亚伦，正如耶和华所说的。'),
('CUV', '出埃及记', 2, 8, 20, '耶和华对摩西说：你清早起来，法老来到水边，你站在他面前，对他说：耶和华这样说：容我的百姓去，好事奉我。'),
('CUV', '出埃及记', 2, 8, 21, '你若不容我的百姓去，我要叫成群的苍蝇到你和你臣仆并你百姓的身上，进你的房屋，并且埃及人的房屋和他们所住的地都要满了成群的苍蝇。'),
('CUV', '出埃及记', 2, 8, 22, '当那日，我必分别我百姓所住的歌珊地，使那里没有成群的苍蝇，好叫你知道我是天下的耶和华。'),
('CUV', '出埃及记', 2, 8, 23, '我要将我的百姓和你的百姓分别出来。明天必有这神迹。'),
('CUV', '出埃及记', 2, 8, 24, '耶和华就这样行。苍蝇成了大群，进入法老的宫殿，和他臣仆的房屋；埃及遍地就因这成群的苍蝇败坏了。'),
('CUV', '出埃及记', 2, 8, 25, '法老召了摩西、亚伦来，说：你们去，在这地祭祀你们的神罢！'),
('CUV', '出埃及记', 2, 8, 26, '摩西说：这样行本不相宜，因为我们要把埃及人所厌恶的祭祀耶和华─我们的神；若把埃及人所厌恶的在他们眼前献为祭，他们岂不拿石头打死我们么？'),
('CUV', '出埃及记', 2, 8, 27, '我们要往旷野去，走三天的路程，照著耶和华─我们神所要吩咐我们的祭祀他。'),
('CUV', '出埃及记', 2, 8, 28, '法老说：我容你们去，在旷野祭祀耶和华─你们的神；只是不要走得很远。求你们为我祈祷。'),
('CUV', '出埃及记', 2, 8, 29, '摩西说：我要出去求耶和华，使成群的苍蝇明天离开法老和法老的臣仆并法老的百姓；法老却不可再行诡诈，不容百姓去祭祀耶和华。'),
('CUV', '出埃及记', 2, 8, 30, '于是摩西离开法老去求耶和华。'),
('CUV', '出埃及记', 2, 8, 31, '耶和华就照摩西的话行，叫成群的苍蝇离开法老和他的臣仆并他的百姓，一个也没有留下。'),
('CUV', '出埃及记', 2, 8, 32, '这一次法老又硬著心，不容百姓去。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 9, 1, '耶和华吩咐摩西说：你进去见法老，对他说：耶和华─希伯来人的神这样说：容我的百姓去，好事奉我。'),
('CUV', '出埃及记', 2, 9, 2, '你若不肯容他们去，仍旧强留他们，'),
('CUV', '出埃及记', 2, 9, 3, '耶和华的手加在你田间的牲畜上，就是在马、驴、骆驼、牛群、羊群上，必有重重的瘟疫。'),
('CUV', '出埃及记', 2, 9, 4, '耶和华要分别以色列的牲畜和埃及的牲畜，凡属以色列人的，一样都不死。'),
('CUV', '出埃及记', 2, 9, 5, '耶和华就定了时候，说：明天耶和华必在此地行这事。'),
('CUV', '出埃及记', 2, 9, 6, '第二天，耶和华就行这事。埃及的牲畜几乎都死了，只是以色列人的牲畜，一个都没有死。'),
('CUV', '出埃及记', 2, 9, 7, '法老打发人去看，谁知以色列人的牲畜连一个都没有死。法老的心却是固执，不容百姓去。'),
('CUV', '出埃及记', 2, 9, 8, '耶和华吩咐摩西、亚伦说：你们取几捧炉灰，摩西要在法老面前向天扬起来。'),
('CUV', '出埃及记', 2, 9, 9, '这灰要在埃及全地变作尘土，在人身上和牲畜身上成了起泡的疮。'),
('CUV', '出埃及记', 2, 9, 10, '摩西、亚伦取了炉灰，站在法老面前。摩西向天扬起来，就在人身上和牲畜身上成了起泡的疮。'),
('CUV', '出埃及记', 2, 9, 11, '行法术的在摩西面前站立不住，因为在他们身上和一切埃及人身上都有这疮。'),
('CUV', '出埃及记', 2, 9, 12, '耶和华使法老的心刚硬，不听他们，正如耶和华对摩西所说的。'),
('CUV', '出埃及记', 2, 9, 13, '耶和华对摩西说：你清早起来，站在法老面前，对他说：耶和华─希伯来人的神这样说：容我的百姓去，好事奉我。'),
('CUV', '出埃及记', 2, 9, 14, '因为这一次我要叫一切的灾殃临到你和你臣仆并你百姓的身上，叫你知道在普天下没有像我的。'),
('CUV', '出埃及记', 2, 9, 15, '我若伸手用瘟疫攻击你和你的百姓，你早就从地上除灭了。'),
('CUV', '出埃及记', 2, 9, 16, '其实，我叫你存立，是特要向你显我的大能，并要使我的名传遍天下。'),
('CUV', '出埃及记', 2, 9, 17, '你还向我的百姓自高，不容他们去么？'),
('CUV', '出埃及记', 2, 9, 18, '到明天约在这时候，我必叫重大的冰雹降下，自从埃及开国以来，没有这样的冰雹。'),
('CUV', '出埃及记', 2, 9, 19, '现在你要打发人把你的牲畜和你田间一切所有的催进来；凡在田间不收回家的，无论是人是牲畜，冰雹必降在他们身上，他们就必死。'),
('CUV', '出埃及记', 2, 9, 20, '法老的臣仆中，惧怕耶和华这话的，便叫他的奴仆和牲畜跑进家来。'),
('CUV', '出埃及记', 2, 9, 21, '但那不把耶和华这话放在心上的，就将他的奴仆和牲畜留在田里。'),
('CUV', '出埃及记', 2, 9, 22, '耶和华对摩西说：你向天伸杖，使埃及遍地的人身上和牲畜身上，并田间各样菜蔬上，都有冰雹。'),
('CUV', '出埃及记', 2, 9, 23, '摩西向天伸杖，耶和华就打雷下雹，有火闪到地上；耶和华下雹在埃及地上。'),
('CUV', '出埃及记', 2, 9, 24, '那时，雹与火搀杂，甚是利害，自从埃及成国以来，遍地没有这样的。'),
('CUV', '出埃及记', 2, 9, 25, '在埃及遍地，雹击打了田间所有的人和牲畜，并一切的菜蔬，又打坏田间一切的树木。'),
('CUV', '出埃及记', 2, 9, 26, '惟独以色列人所住的歌珊地没有冰雹。'),
('CUV', '出埃及记', 2, 9, 27, '法老打发人召摩西、亚伦来，对他们说：这一次我犯了罪了。耶和华是公义的；我和我的百姓是邪恶的。'),
('CUV', '出埃及记', 2, 9, 28, '这雷轰和冰雹已经够了。请你们求耶和华，我就容你们去，不再留住你们。'),
('CUV', '出埃及记', 2, 9, 29, '摩西对他说：我一出城，就要向耶和华举手祷告；雷必止住，也不再有冰雹，叫你知道全地都是属耶和华的。'),
('CUV', '出埃及记', 2, 9, 30, '至于你和你的臣仆，我知道你们还是不惧怕耶和华神。'),
('CUV', '出埃及记', 2, 9, 31, '那时，麻和大麦被雹击打；因为大麦已经吐穗，麻也开了花。'),
('CUV', '出埃及记', 2, 9, 32, '只是小麦和粗麦没有被击打，因为还没有长成。）'),
('CUV', '出埃及记', 2, 9, 33, '摩西离了法老出城，向耶和华举手祷告；雷和雹就止住，雨也不再浇在地上了。'),
('CUV', '出埃及记', 2, 9, 34, '法老见雨和雹与雷止住，就越发犯罪；他和他的臣仆都硬著心。'),
('CUV', '出埃及记', 2, 9, 35, '法老的心刚硬，不容以色列人去，正如耶和华藉著摩西所说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 10, 1, '耶和华对摩西说：你进去见法老。我使他和他臣仆的心刚硬，为要在他们中间显我这些神迹，'),
('CUV', '出埃及记', 2, 10, 2, '并要叫你将我向埃及人所做的事，和在他们中间所行的神迹，传于你儿子和你孙子的耳中，好叫你们知道我是耶和华。'),
('CUV', '出埃及记', 2, 10, 3, '摩西、亚伦就进去见法老，对他说：耶和华─希伯来人的神这样说：你在我面前不肯自卑要到几时呢？容我的百姓去，好事奉我。'),
('CUV', '出埃及记', 2, 10, 4, '你若不肯容我的百姓去，明天我要使蝗虫进入你的境内，'),
('CUV', '出埃及记', 2, 10, 5, '遮满地面，甚至看不见地，并且吃那冰雹所剩的和田间所长的一切树木。'),
('CUV', '出埃及记', 2, 10, 6, '你的宫殿和你众臣仆的房屋，并一切埃及人的房屋，都要被蝗虫占满了；自从你祖宗和你祖宗的祖宗在世以来，直到今日，没有见过这样的灾。摩西就转身离开法老出去。'),
('CUV', '出埃及记', 2, 10, 7, '法老的臣仆对法老说：这人为我们的网罗要到几时呢？容这些人去事奉耶和华─他们的神罢！埃及已经败坏了，你还不知道么？'),
('CUV', '出埃及记', 2, 10, 8, '于是摩西、亚伦被召回来见法老；法老对他们说：你们去事奉耶和华─你们的神；但那要去的是谁呢？'),
('CUV', '出埃及记', 2, 10, 9, '摩西说：我们要和我们老的少的、儿子女儿同去，且把羊群牛群一同带去，因为我们务要向耶和华守节。'),
('CUV', '出埃及记', 2, 10, 10, '法老对他们说：我容你们和你们妇人孩子去的时候，耶和华与你们同在罢！你们要谨慎；因为有祸在你们眼前（或作：你们存著恶意），'),
('CUV', '出埃及记', 2, 10, 11, '不可都去！你们这壮年人去事奉耶和华罢，因为这是你们所求的。于是把他们从法老面前撵出去。'),
('CUV', '出埃及记', 2, 10, 12, '耶和华对摩西说：你向埃及地伸杖，使蝗虫到埃及地上来，吃地上一切的菜蔬，就是冰雹所剩的。'),
('CUV', '出埃及记', 2, 10, 13, '摩西就向埃及地伸杖，那一昼一夜，耶和华使东风刮在埃及地上；到了早晨，东风把蝗虫刮了来。'),
('CUV', '出埃及记', 2, 10, 14, '蝗虫上来，落在埃及的四境，甚是厉害；以前没有这样的，以后也必没有。'),
('CUV', '出埃及记', 2, 10, 15, '因为这蝗虫遮满地面，甚至地都黑暗了，又吃地上一切的菜蔬和冰雹所剩树上的果子。埃及遍地，无论是树木，是田间的菜蔬，连一点青的也没有留下。'),
('CUV', '出埃及记', 2, 10, 16, '于是法老急忙召了摩西、亚伦来，说：我得罪耶和华─你们的神，又得罪了你们。'),
('CUV', '出埃及记', 2, 10, 17, '现在求你，只这一次，饶恕我的罪，求耶和华─你们的神使我脱离这一次的死亡。'),
('CUV', '出埃及记', 2, 10, 18, '摩西就离开法老去求耶和华。'),
('CUV', '出埃及记', 2, 10, 19, '耶和华转了极大的西风，把蝗虫刮起，吹入红海；在埃及的四境连一个也没有留下。'),
('CUV', '出埃及记', 2, 10, 20, '但耶和华使法老的心刚硬，不容以色列人去。'),
('CUV', '出埃及记', 2, 10, 21, '耶和华对摩西说：你向天伸杖，使埃及地黑暗；这黑暗似乎摸得著。'),
('CUV', '出埃及记', 2, 10, 22, '摩西向天伸杖，埃及遍地就乌黑了三天。'),
('CUV', '出埃及记', 2, 10, 23, '三天之久，人不能相见，谁也不敢起来离开本处；惟有以色列人家中都有亮光。'),
('CUV', '出埃及记', 2, 10, 24, '法老就召摩西来，说：你们去事奉耶和华；只是你们的羊群牛群要留下；你们的妇人孩子可以和你们同去。'),
('CUV', '出埃及记', 2, 10, 25, '摩西说：你总要把祭物和燔祭牲交给我们，使我们可以祭祀耶和华─我们的神。'),
('CUV', '出埃及记', 2, 10, 26, '我们的牲畜也要带去，连一蹄也不留下；因为我们要从其中取出来，事奉耶和华─我们的神。我们未到那里，还不知道用甚么事奉耶和华。'),
('CUV', '出埃及记', 2, 10, 27, '但耶和华使法老的心刚硬，不肯容他们去。'),
('CUV', '出埃及记', 2, 10, 28, '法老对摩西说：你离开我去罢，你要小心，不要再见我的面！因为你见我面的那日你就必死！'),
('CUV', '出埃及记', 2, 10, 29, '摩西说：你说得好！我必不再见你的面了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 11, 1, '耶和华对摩西说：我再使一样的灾殃临到法老和埃及，然后他必容你们离开这地。他容你们去的时候，总要催逼你们都从这地出去。'),
('CUV', '出埃及记', 2, 11, 2, '你要传于百姓的耳中，叫他们男女各人向邻舍要金器银器。'),
('CUV', '出埃及记', 2, 11, 3, '耶和华叫百姓在埃及人眼前蒙恩，并且摩西在埃及地、法老臣仆，和百姓的眼中看为极大。'),
('CUV', '出埃及记', 2, 11, 4, '摩西说：耶和华这样说：约到半夜，我必出去巡行埃及遍地。'),
('CUV', '出埃及记', 2, 11, 5, '凡在埃及地，从坐宝座的法老直到磨子后的婢女所有的长子，以及一切头生的牲畜，都必死。'),
('CUV', '出埃及记', 2, 11, 6, '埃及遍地必有大哀号；从前没有这样的，后来也必没有。'),
('CUV', '出埃及记', 2, 11, 7, '至于以色列中，无论是人是牲畜，连狗也不敢向他们摇舌，好叫你们知道耶和华是将埃及人和以色列人分别出来。'),
('CUV', '出埃及记', 2, 11, 8, '你这一切臣仆都要俯伏来见我，说：求你和跟从你的百姓都出去，然后我要出去。于是，摩西气忿忿的离开法老，出去了。'),
('CUV', '出埃及记', 2, 11, 9, '耶和华对摩西说：法老必不听你们，使我的奇事在埃及地多起来。'),
('CUV', '出埃及记', 2, 11, 10, '摩西、亚伦在法老面前行了这一切奇事；耶和华使法老的心刚硬，不容以色列人出离他的地。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 12, 1, '耶和华在埃及地晓谕摩西、亚伦说：'),
('CUV', '出埃及记', 2, 12, 2, '你们要以本月为正月，为一年之首。'),
('CUV', '出埃及记', 2, 12, 3, '你们吩咐以色列全会众说：本月初十日，各人要按著父家取羊羔，一家一只。'),
('CUV', '出埃及记', 2, 12, 4, '若是一家的人太少，吃不了一只羊羔，本人就要和他隔壁的邻舍共取一只。你们预备羊羔，要按著人数和饭量计算。'),
('CUV', '出埃及记', 2, 12, 5, '要无残疾、一岁的公羊羔，你们或从绵羊里取，或从山羊里取，都可以。'),
('CUV', '出埃及记', 2, 12, 6, '要留到本月十四日，在黄昏的时候，以色列全会众把羊羔宰了。'),
('CUV', '出埃及记', 2, 12, 7, '各家要取点血，涂在吃羊羔的房屋左右的门框上和门楣上。'),
('CUV', '出埃及记', 2, 12, 8, '当夜要吃羊羔的肉；用火烤了，与无酵饼和苦菜同吃。'),
('CUV', '出埃及记', 2, 12, 9, '不可吃生的，断不可吃水煮的，要带著头、腿、五脏，用火烤了吃。'),
('CUV', '出埃及记', 2, 12, 10, '不可剩下一点留到早晨；若留到早晨，要用火烧了。'),
('CUV', '出埃及记', 2, 12, 11, '你们吃羊羔当腰间束带，脚上穿鞋，手中拿杖，赶紧的吃；这是耶和华的逾越节。'),
('CUV', '出埃及记', 2, 12, 12, '因为那夜我要巡行埃及地，把埃及地一切头生的，无论是人是牲畜，都击杀了，又要败坏埃及一切的神。我是耶和华。'),
('CUV', '出埃及记', 2, 12, 13, '这血要在你们所住的房屋上作记号；我一见这血，就越过你们去。我击杀埃及地头生的时候，灾殃必不临到你们身上灭你们。'),
('CUV', '出埃及记', 2, 12, 14, '你们要记念这日，守为耶和华的节，作为你们世世代代永远的定例。'),
('CUV', '出埃及记', 2, 12, 15, '你们要吃无酵饼七日。头一日要把酵从你们各家中除去；因为从头一日起，到第七日为止，凡吃有酵之饼的，必从以色列中剪除。'),
('CUV', '出埃及记', 2, 12, 16, '头一日你们当有圣会，第七日也当有圣会。这两日之内，除了预备各人所要吃的以外，无论何工都不可做。'),
('CUV', '出埃及记', 2, 12, 17, '你们要守无酵节，因为我正当这日把你们的军队从埃及地领出来。所以，你们要守这日，作为世世代代永远的定例。'),
('CUV', '出埃及记', 2, 12, 18, '从正月十四日晚上，直到二十一日晚上，你们要吃无酵饼。'),
('CUV', '出埃及记', 2, 12, 19, '在你们各家中，七日之内不可有酵；因为凡吃有酵之物的，无论是寄居的，是本地的，必从以色列的会中剪除。'),
('CUV', '出埃及记', 2, 12, 20, '有酵的物，你们都不可吃；在你们一切住处要吃无酵饼。'),
('CUV', '出埃及记', 2, 12, 21, '于是，摩西召了以色列的众长老来，对他们说：你们要按著家口取出羊羔，把这逾越节的羊羔宰了。'),
('CUV', '出埃及记', 2, 12, 22, '拿一把牛膝草，蘸盆里的血，打在门楣上和左右的门框上。你们谁也不可出自己的房门，直到早晨。'),
('CUV', '出埃及记', 2, 12, 23, '因为耶和华要巡行击杀埃及人，他看见血在门楣上和左右的门框上，就必越过那门，不容灭命的进你们的房屋，击杀你们。'),
('CUV', '出埃及记', 2, 12, 24, '这例，你们要守著，作为你们和你们子孙永远的定例。'),
('CUV', '出埃及记', 2, 12, 25, '日后，你们到了耶和华按著所应许赐给你们的那地，就要守这礼。'),
('CUV', '出埃及记', 2, 12, 26, '你们的儿女问你们说：行这礼是甚么意思？'),
('CUV', '出埃及记', 2, 12, 27, '你们就说：这是献给耶和华逾越节的祭。当以色列人在埃及的时候，他击杀埃及人，越过以色列人的房屋，救了我们各家。于是百姓低头下拜。'),
('CUV', '出埃及记', 2, 12, 28, '耶和华怎样吩咐摩西、亚伦，以色列人就怎样行。'),
('CUV', '出埃及记', 2, 12, 29, '到了半夜，耶和华把埃及地所有的长子，就是从坐宝座的法老，直到被掳囚在监里之人的长子，以及一切头生的牲畜，尽都杀了。'),
('CUV', '出埃及记', 2, 12, 30, '法老和一切臣仆，并埃及众人，夜间都起来了。在埃及有大哀号，无一家不死一个人的。'),
('CUV', '出埃及记', 2, 12, 31, '夜间，法老召了摩西、亚伦来，说：起来！连你们带以色列人，从我民中出去，依你们所说的，去事奉耶和华罢！'),
('CUV', '出埃及记', 2, 12, 32, '也依你们所说的，连羊群牛群带著走罢！并要为我祝福。'),
('CUV', '出埃及记', 2, 12, 33, '埃及人催促百姓，打发他们快快出离那地，因为埃及人说：我们都要死了。'),
('CUV', '出埃及记', 2, 12, 34, '百姓就拿著没有酵的生面，把抟面盆包在衣服中，扛在肩头上。'),
('CUV', '出埃及记', 2, 12, 35, '以色列人照著摩西的话行，向埃及人要金器、银器，和衣裳。'),
('CUV', '出埃及记', 2, 12, 36, '耶和华叫百姓在埃及人眼前蒙恩，以致埃及人给他们所要的。他们就把埃及人的财物夺去了。'),
('CUV', '出埃及记', 2, 12, 37, '以色列人从兰塞起行，往疏割去；除了妇人孩子，步行的男人约有六十万。'),
('CUV', '出埃及记', 2, 12, 38, '又有许多闲杂人，并有羊群牛群，和他们一同上去。'),
('CUV', '出埃及记', 2, 12, 39, '他们用埃及带出来的生面烤成无酵饼。这生面原没有发起；因为他们被催逼离开埃及，不能耽延，也没有为自己预备甚么食物。'),
('CUV', '出埃及记', 2, 12, 40, '以色列人住在埃及共有四百三十年。'),
('CUV', '出埃及记', 2, 12, 41, '正满了四百三十年的那一天，耶和华的军队都从埃及地出来了。'),
('CUV', '出埃及记', 2, 12, 42, '这夜是耶和华的夜；因耶和华领他们出了埃及地，所以当向耶和华谨守，是以色列众人世世代代该谨守的。'),
('CUV', '出埃及记', 2, 12, 43, '耶和华对摩西、亚伦说：逾越节的例是这样：外邦人都不可吃这羊羔。'),
('CUV', '出埃及记', 2, 12, 44, '但各人用银子买的奴仆，既受了割礼就可以吃。'),
('CUV', '出埃及记', 2, 12, 45, '寄居的和雇工人都不可吃。'),
('CUV', '出埃及记', 2, 12, 46, '应当在一个房子里吃；不可把一点肉从房子里带到外头去。羊羔的骨头一根也不可折断。'),
('CUV', '出埃及记', 2, 12, 47, '以色列全会众都要守这礼。'),
('CUV', '出埃及记', 2, 12, 48, '若有外人寄居在你们中间，愿向耶和华守逾越节，他所有的男子务要受割礼，然后才容他前来遵守，他也就像本地人一样；但未受割礼的，都不可吃这羊羔。'),
('CUV', '出埃及记', 2, 12, 49, '本地人和寄居在你们中间的外人同归一例。'),
('CUV', '出埃及记', 2, 12, 50, '耶和华怎样吩咐摩西、亚伦，以色列众人就怎样行了。'),
('CUV', '出埃及记', 2, 12, 51, '正当那日，耶和华将以色列人按著他们的军队，从埃及地领出来。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 13, 1, '耶和华晓谕摩西说：'),
('CUV', '出埃及记', 2, 13, 2, '以色列中凡头生的，无论是人是牲畜，都是我的，要分别为圣归我。'),
('CUV', '出埃及记', 2, 13, 3, '摩西对百姓说：你们要记念从埃及为奴之家出来的这日，因为耶和华用大能的手将你们从这地方领出来。有酵的饼都不可吃。'),
('CUV', '出埃及记', 2, 13, 4, '亚笔月间的这日是你们出来的日子。'),
('CUV', '出埃及记', 2, 13, 5, '将来耶和华领你进迦南人、赫人、亚摩利人、希未人、耶布斯人之地，就是他向你的祖宗起誓应许给你那流奶与蜜之地，那时你要在这月间守这礼。'),
('CUV', '出埃及记', 2, 13, 6, '你要吃无酵饼七日，到第七日要向耶和华守节。'),
('CUV', '出埃及记', 2, 13, 7, '这七日之久，要吃无酵饼；在你四境之内不可见有酵的饼，也不可见发酵的物。'),
('CUV', '出埃及记', 2, 13, 8, '当那日，你要告诉你的儿子说：这是因耶和华在我出埃及的时候为我所行的事。'),
('CUV', '出埃及记', 2, 13, 9, '这要在你手上作记号，在你额上作纪念，使耶和华的律法常在你口中，因为耶和华曾用大能的手将你从埃及领出来。'),
('CUV', '出埃及记', 2, 13, 10, '所以你每年要按著日期守这例。'),
('CUV', '出埃及记', 2, 13, 11, '将来，耶和华照他向你和你祖宗所起的誓将你领进迦南人之地，把这地赐给你，'),
('CUV', '出埃及记', 2, 13, 12, '那时你要将一切头生的，并牲畜中头生的，归给耶和华；公的都要属耶和华。'),
('CUV', '出埃及记', 2, 13, 13, '凡头生的驴，你要用羊羔代赎；若不代赎，就要打折他的颈项。凡你儿子中头生的都要赎出来。'),
('CUV', '出埃及记', 2, 13, 14, '日后，你的儿子问你说：这是甚么意思？你就说：耶和华用大能的手将我们从埃及为奴之家领出来。'),
('CUV', '出埃及记', 2, 13, 15, '那时法老几乎不容我们去，耶和华就把埃及地所有头生的，无论是人是牲畜，都杀了。因此，我把一切头生的公牲畜献给耶和华为祭，但将头生的儿子都赎出来。'),
('CUV', '出埃及记', 2, 13, 16, '这要在你手上作记号，在你额上作经文，因为耶和华用大能的手将我们从埃及领出来。'),
('CUV', '出埃及记', 2, 13, 17, '法老容百姓去的时候，非利士地的道路虽近，神却不领他们从那里走；因为神说：恐怕百姓遇见打仗后悔，就回埃及去。'),
('CUV', '出埃及记', 2, 13, 18, '所以神领百姓绕道而行，走红海旷野的路。以色列人出埃及地，都带著兵器上去。'),
('CUV', '出埃及记', 2, 13, 19, '摩西把约瑟的骸骨一同带去；因为约瑟曾叫以色列人严严地起誓，对他们说：神必眷顾你们，你们要把我的骸骨从这里一同带上去。'),
('CUV', '出埃及记', 2, 13, 20, '他们从疏割起行，在旷野边的以倘安营。'),
('CUV', '出埃及记', 2, 13, 21, '日间，耶和华在云柱中领他们的路；夜间，在火柱中光照他们，使他们日夜都可以行走。'),
('CUV', '出埃及记', 2, 13, 22, '日间云柱，夜间火柱，总不离开百姓的面前。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 14, 1, '耶和华晓谕摩西说：'),
('CUV', '出埃及记', 2, 14, 2, '你吩咐以色列人转回，安营在比哈希录前，密夺和海的中间，对著巴力洗分，靠近海边安营。'),
('CUV', '出埃及记', 2, 14, 3, '法老必说：以色列人在地中绕迷了，旷野把他们困住了。'),
('CUV', '出埃及记', 2, 14, 4, '我要使法老的心刚硬，他要追赶他们，我便在法老和他全军身上得荣耀；埃及人就知道我是耶和华。于是以色列人这样行了。'),
('CUV', '出埃及记', 2, 14, 5, '有人告诉埃及王说：百姓逃跑。法老和他的臣仆就向百姓变心，说：我们容以色列人去，不再服事我们，这做的是甚么事呢？'),
('CUV', '出埃及记', 2, 14, 6, '法老就预备他的车辆，带领军兵同去，'),
('CUV', '出埃及记', 2, 14, 7, '并带著六百辆特选的车和埃及所有的车，每辆都有车兵长。'),
('CUV', '出埃及记', 2, 14, 8, '耶和华使埃及王法老的心刚硬，他就追赶以色列人，因为以色列人是昂然无惧地出埃及。'),
('CUV', '出埃及记', 2, 14, 9, '埃及人追赶他们，法老一切的马匹、车辆、马兵，与军兵就在海边上，靠近比哈希录，对著巴力洗分，在他们安营的地方追上了。'),
('CUV', '出埃及记', 2, 14, 10, '法老临近的时候，以色列人举目看见埃及人赶来，就甚惧怕，向耶和华哀求。'),
('CUV', '出埃及记', 2, 14, 11, '他们对摩西说：难道在埃及没有坟地，你把我们带来死在旷野么？你为甚么这样待我们，将我们从埃及领出来呢？'),
('CUV', '出埃及记', 2, 14, 12, '我们在埃及岂没有对你说过，不要搅扰我们，容我们服事埃及人么？因为服事埃及人比死在旷野还好。'),
('CUV', '出埃及记', 2, 14, 13, '摩西对百姓说：不要惧怕，只管站住！看耶和华今天向你们所要施行的救恩。因为，你们今天所看见的埃及人必永远不再看见了。'),
('CUV', '出埃及记', 2, 14, 14, '耶和华必为你们争战；你们只管静默，不要作声。'),
('CUV', '出埃及记', 2, 14, 15, '耶和华对摩西说：你为甚么向我哀求呢？你吩咐以色列人往前走。'),
('CUV', '出埃及记', 2, 14, 16, '你举手向海伸杖，把水分开。以色列人要下海中走干地。'),
('CUV', '出埃及记', 2, 14, 17, '我要使埃及人的心刚硬，他们就跟著下去。我要在法老和他的全军、车辆、马兵上得荣耀。'),
('CUV', '出埃及记', 2, 14, 18, '我在法老和他的车辆、马兵上得荣耀的时候，埃及人就知道我是耶和华了。'),
('CUV', '出埃及记', 2, 14, 19, '在以色列营前行走神的使者，转到他们后边去；云柱也从他们前边转到他们后边立住。'),
('CUV', '出埃及记', 2, 14, 20, '在埃及营和以色列营中间有云柱，一边黑暗，一边发光，终夜两下不得相近。'),
('CUV', '出埃及记', 2, 14, 21, '摩西向海伸杖，耶和华便用大东风，使海水一夜退去，水便分开，海就成了干地。'),
('CUV', '出埃及记', 2, 14, 22, '以色列人下海中走干地，水在他们的左右作了墙垣。'),
('CUV', '出埃及记', 2, 14, 23, '埃及人追赶他们，法老一切的马匹、车辆，和马兵都跟著下到海中。'),
('CUV', '出埃及记', 2, 14, 24, '到了晨更的时候，耶和华从云火柱中向埃及的军兵观看，使埃及的军兵混乱了；'),
('CUV', '出埃及记', 2, 14, 25, '又使他们的车轮脱落难以行走，以致埃及人说：我们从以色列人面前逃跑罢！因耶和华为他们攻击我们了'),
('CUV', '出埃及记', 2, 14, 26, '耶和华对摩西说：你向海伸杖，叫水仍合在埃及人并他们的车辆、马兵身上。'),
('CUV', '出埃及记', 2, 14, 27, '摩西就向海伸杖，到了天一亮，海水仍旧复原。埃及人避水逃跑的时候，耶和华把他们推翻在海中，'),
('CUV', '出埃及记', 2, 14, 28, '水就回流，淹没了车辆和马兵。那些跟著以色列人下海法老的全军，连一个也没有剩下。'),
('CUV', '出埃及记', 2, 14, 29, '以色列人却在海中走干地；水在他们的左右作了墙垣。'),
('CUV', '出埃及记', 2, 14, 30, '当日，耶和华这样拯救以色列人脱离埃及人的手，以色列人看见埃及人的死尸都在海边了。'),
('CUV', '出埃及记', 2, 14, 31, '以色列人看见耶和华向埃及人所行的大事，就敬畏耶和华，又信服他和他的仆人摩西。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 15, 1, '那时，摩西和以色列人向耶和华唱歌说：我要向耶和华歌唱，因他大大战胜，将马和骑马的投在海中。'),
('CUV', '出埃及记', 2, 15, 2, '耶和华是我的力量，我的诗歌，也成了我的拯救。这是我的神，我要赞美他，是我父亲的神，我要尊崇他。'),
('CUV', '出埃及记', 2, 15, 3, '耶和华是战士；他的名是耶和华。'),
('CUV', '出埃及记', 2, 15, 4, '法老的车辆、军兵，耶和华已抛在海中；他特选的军长都沉于红海。'),
('CUV', '出埃及记', 2, 15, 5, '深水淹没他们；他们如同石头坠到深处。'),
('CUV', '出埃及记', 2, 15, 6, '耶和华阿，你的右手施展能力，显出荣耀；耶和华阿，你的右手摔碎仇敌。'),
('CUV', '出埃及记', 2, 15, 7, '你大发威严，推翻那些起来攻击你的；你发出烈怒如火，烧灭他们像烧碎一样。'),
('CUV', '出埃及记', 2, 15, 8, '你发鼻中的气，水便聚起成堆，大水直立如垒，海中的深水凝结。'),
('CUV', '出埃及记', 2, 15, 9, '仇敌说：我要追赶，我要追上；我要分掳物，我要在他们身上称我的心愿。我要拔出刀来，亲手杀灭他们。'),
('CUV', '出埃及记', 2, 15, 10, '你叫风一吹，海就把他们淹没；他们如铅沉在大水之中。'),
('CUV', '出埃及记', 2, 15, 11, '耶和华阿，众神之中，谁能像你？谁能像你─至圣至荣，可颂可畏，施行奇事？'),
('CUV', '出埃及记', 2, 15, 12, '你伸出右手，地便吞灭他们。'),
('CUV', '出埃及记', 2, 15, 13, '你凭慈爱领了你所赎的百姓；你凭能力引他们到了你的圣所。'),
('CUV', '出埃及记', 2, 15, 14, '外邦人听见就发颤；疼痛抓住非利士的居民。'),
('CUV', '出埃及记', 2, 15, 15, '那时，以东的族长惊惶，摩押的英雄被战兢抓住，迦南的居民心都消化了。'),
('CUV', '出埃及记', 2, 15, 16, '惊骇恐惧临到他们。耶和华阿，因你膀臂的大能，他们如石头寂然不动，等候你的百姓过去，等候你所赎的百姓过去。'),
('CUV', '出埃及记', 2, 15, 17, '你要将他们领进去，栽于你产业的山上─耶和华阿，就是你为自己所造的住处；主阿，就是你手所建立的圣所。'),
('CUV', '出埃及记', 2, 15, 18, '耶和华必作王，直到永永远远！'),
('CUV', '出埃及记', 2, 15, 19, '法老的马匹、车辆，和马兵下到海中，耶和华使海水回流，淹没他们；惟有以色列人在海中走干地。'),
('CUV', '出埃及记', 2, 15, 20, '亚伦的姊姊，女先知米利暗，手里拿著鼓；众妇女也跟他出去拿鼓跳舞。'),
('CUV', '出埃及记', 2, 15, 21, '米利暗应声说：你们要歌颂耶和华，因他大大战胜，将马和骑马的投在海中。'),
('CUV', '出埃及记', 2, 15, 22, '摩西领以色列人从红海往前行，到了书珥的旷野，在旷野走了三天，找不著水。'),
('CUV', '出埃及记', 2, 15, 23, '到了玛拉，不能喝那里的水；因为水苦，所以那地名叫玛拉。'),
('CUV', '出埃及记', 2, 15, 24, '百姓就向摩西发怨言，说：我们喝甚么呢？'),
('CUV', '出埃及记', 2, 15, 25, '摩西呼求耶和华，耶和华指示他一棵树。他把树丢在水里，水就变甜了。耶和华在那里为他们定了律例、典章，在那里试验他们；'),
('CUV', '出埃及记', 2, 15, 26, '又说：你若留意听耶和华─你神的话，又行我眼中看为正的事，留心听我的诫命，守我一切的律例，我就不将所加与埃及人的疾病加在你身上，因为我─耶和华是医治你的。'),
('CUV', '出埃及记', 2, 15, 27, '他们到了以琳，在那里有十二股水泉，七十棵棕树；他们就在那里的水边安营。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 16, 1, '以色列全会众从以琳起行，在出埃及后第二个月十五日到了以琳和西乃中间、汛的旷野。'),
('CUV', '出埃及记', 2, 16, 2, '以色列全会众在旷野向摩西、亚伦发怨言，'),
('CUV', '出埃及记', 2, 16, 3, '说：巴不得我们早死在埃及地、耶和华的手下；那时我们坐在肉锅旁边，吃得饱足。你们将我们领出来，到这旷野，是要叫这全会众都饿死阿！'),
('CUV', '出埃及记', 2, 16, 4, '耶和华对摩西说：我要将粮食从天降给你们。百姓可以出去，每天收每天的分，我好试验他们遵不遵我的法度。'),
('CUV', '出埃及记', 2, 16, 5, '到第六天，他们要把所收进来的预备好了，比每天所收的多一倍。'),
('CUV', '出埃及记', 2, 16, 6, '摩西、亚伦对以色列众人说：到了晚上，你们要知道是耶和华将你们从埃及地领出来的。'),
('CUV', '出埃及记', 2, 16, 7, '早晨，你们要看见耶和华的荣耀，因为耶和华听见你们向他所发的怨言了。我们算甚么，你们竟向我们发怨言呢？'),
('CUV', '出埃及记', 2, 16, 8, '摩西又说：耶和华晚上必给你们肉吃，早晨必给你们食物得饱；因为你们向耶和华发的怨言，他都听见了。我们算甚么，你们的怨言不是向我们发的，乃是向耶和华发的。'),
('CUV', '出埃及记', 2, 16, 9, '摩西对亚伦说：你告诉以色列全会众说：你们就近耶和华面前，因为他已经听见你们的怨言了。'),
('CUV', '出埃及记', 2, 16, 10, '亚伦正对以色列全会众说话的时候，他们向旷野观看，不料，耶和华的荣光在云中显现。'),
('CUV', '出埃及记', 2, 16, 11, '耶和华晓谕摩西说：'),
('CUV', '出埃及记', 2, 16, 12, '我已经听见以色列人的怨言。你告诉他们说：到黄昏的时候，你们要吃肉，早晨必有食物得饱，你们就知道我是耶和华─你们的神。'),
('CUV', '出埃及记', 2, 16, 13, '到了晚上，有鹌鹑飞来，遮满了营；早晨在营四围的地上有露水。'),
('CUV', '出埃及记', 2, 16, 14, '露水上升之后，不料，野地面上有如白霜的小圆物。'),
('CUV', '出埃及记', 2, 16, 15, '以色列人看见，不知道是甚么，就彼此对问说：这是甚么呢？摩西对他们说：这就是耶和华给你们吃的食物。'),
('CUV', '出埃及记', 2, 16, 16, '耶和华所吩咐的是这样：你们要按著各人的饭量，为帐棚里的人，按著人数收起来，各拿一俄梅珥。'),
('CUV', '出埃及记', 2, 16, 17, '以色列人就这样行；有多收的，有少收的。'),
('CUV', '出埃及记', 2, 16, 18, '及至用俄梅珥量一量，多收的也没有余，少收的也没有缺；各人按著自己的饭量收取。'),
('CUV', '出埃及记', 2, 16, 19, '摩西对他们说：所收的，不许甚么人留到早晨。'),
('CUV', '出埃及记', 2, 16, 20, '然而他们不听摩西的话，内中有留到早晨的，就生虫变臭了；摩西便向他们发怒。'),
('CUV', '出埃及记', 2, 16, 21, '他们每日早晨，按著各人的饭量收取，日头一发热，就消化了。'),
('CUV', '出埃及记', 2, 16, 22, '到第六天，他们收了双倍的食物，每人两俄梅珥。会众的官长来告诉摩西；'),
('CUV', '出埃及记', 2, 16, 23, '摩西对他们说：耶和华这样说：明天是圣安息日，是向耶和华守的圣安息日。你们要烤的就烤了，要煮的就煮了，所剩下的都留到早晨。'),
('CUV', '出埃及记', 2, 16, 24, '他们就照摩西的吩咐留到早晨，也不臭，里头也没有虫子。'),
('CUV', '出埃及记', 2, 16, 25, '摩西说：你们今天吃这个罢！因为今天是向耶和华守的安息日；你们在田野必找不著了。'),
('CUV', '出埃及记', 2, 16, 26, '六天可以收取，第七天乃是安息日，那一天必没有了。'),
('CUV', '出埃及记', 2, 16, 27, '第七天，百姓中有人出去收，甚么也找不著。'),
('CUV', '出埃及记', 2, 16, 28, '耶和华对摩西说：你们不肯守我的诫命和律法，要到几时呢？'),
('CUV', '出埃及记', 2, 16, 29, '你们看！耶和华既将安息日赐给你们，所以第六天他赐给你们两天的食物，第七天各人要住在自己的地方，不许甚么人出去。'),
('CUV', '出埃及记', 2, 16, 30, '于是百姓第七天安息了。'),
('CUV', '出埃及记', 2, 16, 31, '这食物，以色列家叫吗哪；样子像芫荽子，颜色是白的，滋味如同搀蜜的薄饼。'),
('CUV', '出埃及记', 2, 16, 32, '摩西说：耶和华所吩咐的是这样：要将一满俄梅珥俄梅珥就是伊法十分之一）吗哪留到世世代代，使后人可以看见我当日将你们领出埃及地，在旷野所给你们吃的食物。'),
('CUV', '出埃及记', 2, 16, 33, '摩西对亚伦说：你拿一个罐子，盛一满俄梅珥吗哪，存在耶和华面前，要留到世世代代。'),
('CUV', '出埃及记', 2, 16, 34, '耶和华怎么吩咐摩西，亚伦就怎么行，把吗哪放在法柜前存留。'),
('CUV', '出埃及记', 2, 16, 35, '以色列人吃吗哪共四十年，直到进了有人居住之地，就是迦南的境界。'),
('CUV', '出埃及记', 2, 16, 36, '俄梅珥就是伊法十分之一。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 17, 1, '以色列全会众都遵耶和华的吩咐，按著站口从汛的旷野往前行，在利非订安营。百姓没有水喝，'),
('CUV', '出埃及记', 2, 17, 2, '所以与摩西争闹，说：给我们水喝罢！摩西对他们说：你们为甚么与我争闹？为甚么试探耶和华呢？'),
('CUV', '出埃及记', 2, 17, 3, '百姓在那里甚渴，要喝水，就向摩西发怨言，说：你为甚么将我们从埃及领出来，使我们和我们的儿女并牲畜都渴死呢？'),
('CUV', '出埃及记', 2, 17, 4, '摩西就呼求耶和华说：我向这百姓怎样行呢？他们几乎要拿石头打死我。'),
('CUV', '出埃及记', 2, 17, 5, '耶和华对摩西说：你手里拿著你先前击打河水的杖，带领以色列的几个长老，从百姓面前走过去。'),
('CUV', '出埃及记', 2, 17, 6, '我必在何烈的磐石那里，站在你面前。你要击打磐石，从磐石里必有水流出来，使百姓可以喝。摩西就在以色列的长老眼前这样行了。'),
('CUV', '出埃及记', 2, 17, 7, '他给那地方起名叫玛撒（就是试探的意思），又叫米利巴（就是争闹的意思）；因以色列人争闹，又因他们试探耶和华，说：耶和华是在我们中间不是？'),
('CUV', '出埃及记', 2, 17, 8, '那时，亚玛力人来在利非订，和以色列人争战。'),
('CUV', '出埃及记', 2, 17, 9, '摩西对约书亚说：你为我们选出人来，出去和亚玛力人争战。明天我手里要拿著神的杖，站在山顶上。'),
('CUV', '出埃及记', 2, 17, 10, '于是约书亚照著摩西对他所说的话行，和亚玛力人争战。摩西、亚伦，与户珥都上了山顶。'),
('CUV', '出埃及记', 2, 17, 11, '摩西何时举手，以色列人就得胜，何时垂手，亚玛力人就得胜。'),
('CUV', '出埃及记', 2, 17, 12, '但摩西的手发沉，他们就搬石头来，放在他以下，他就坐在上面。亚伦与户珥扶著他的手，一个在这边，一个在那边，他的手就稳住，直到日落的时候。'),
('CUV', '出埃及记', 2, 17, 13, '约书亚用刀杀了亚玛力王和他的百姓。'),
('CUV', '出埃及记', 2, 17, 14, '耶和华对摩西说：我要将亚玛力的名号从天下全然涂抹了；你要将这话写在书上作纪念，又念给约书亚听。'),
('CUV', '出埃及记', 2, 17, 15, '摩西筑了一座坛，起名叫耶和华尼西（就是耶和华是我旌旗的意思），'),
('CUV', '出埃及记', 2, 17, 16, '又说：耶和华已经起了誓，必世世代代和亚玛力人争战。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 18, 1, '摩西的岳父，米甸祭司叶忒罗，听见神为摩西和神的百姓以色列所行的一切事，就是耶和华将以色列从埃及领出来的事，'),
('CUV', '出埃及记', 2, 18, 2, '便带著摩西的妻子西坡拉，就是摩西从前打发回去的，'),
('CUV', '出埃及记', 2, 18, 3, '又带著西坡拉的两个儿子，一个名叫革舜，因为摩西说：我在外邦作了寄居的；'),
('CUV', '出埃及记', 2, 18, 4, '一个名叫以利以谢因为他说：我父亲的神帮助了我，救我脱离法老的刀。'),
('CUV', '出埃及记', 2, 18, 5, '摩西的岳父叶忒罗带著摩西的妻子和两个儿子来到神的山，就是摩西在旷野安营的地方。'),
('CUV', '出埃及记', 2, 18, 6, '他对摩西说：我是你岳父叶忒罗，带著你的妻子和两个儿子来到你这里。'),
('CUV', '出埃及记', 2, 18, 7, '摩西迎接他的岳父，向他下拜，与他亲嘴，彼此问安，都进了帐棚。'),
('CUV', '出埃及记', 2, 18, 8, '摩西将耶和华为以色列的缘故向法老和埃及人所行的一切事，以及路上所遭遇的一切艰难，并耶和华怎样搭救他们，都述说与他岳父听。'),
('CUV', '出埃及记', 2, 18, 9, '叶忒罗因耶和华待以色列的一切好处，就是拯救他们脱离埃及人的手，便甚欢喜。'),
('CUV', '出埃及记', 2, 18, 10, '叶忒罗说：耶和华是应当称颂的；他救了你们脱离埃及人和法老的手，将这百姓从埃及人的手下救出来。'),
('CUV', '出埃及记', 2, 18, 11, '我现今在埃及人向这百姓发狂傲的事上得知，耶和华比万神都大。'),
('CUV', '出埃及记', 2, 18, 12, '摩西的岳父叶忒罗把燔祭和平安祭献给神。亚伦和以色列的众长老都来了，与摩西的岳父在神面前吃饭。'),
('CUV', '出埃及记', 2, 18, 13, '第二天，摩西坐著审判百姓，百姓从早到晚都站在摩西的左右。'),
('CUV', '出埃及记', 2, 18, 14, '摩西的岳父看见他向百姓所做的一切事，就说：你向百姓做的是甚么事呢？你为甚么独自坐著，众百姓从早到晚都站在你的左右呢？'),
('CUV', '出埃及记', 2, 18, 15, '摩西对岳父说：这是因百姓到我这里来求问神。'),
('CUV', '出埃及记', 2, 18, 16, '他们有事的时候就到我这里来，我便在两造之间施行审判；我又叫他们知道神的律例和法度。'),
('CUV', '出埃及记', 2, 18, 17, '摩西的岳父说：你这做的不好。'),
('CUV', '出埃及记', 2, 18, 18, '你和这些百姓必都疲惫；因为这事太重，你独自一人办理不了。'),
('CUV', '出埃及记', 2, 18, 19, '现在你要听我的话。我为你出个主意，愿神与你同在。你要替百姓到神面前，将案件奏告神；'),
('CUV', '出埃及记', 2, 18, 20, '又要将律例和法度教训他们，指示他们当行的道，当做的事；'),
('CUV', '出埃及记', 2, 18, 21, '并要从百姓中拣选有才能的人，就是敬畏神、诚实无妄、恨不义之财的人，派他们作千夫长、百夫长、五十夫长、十夫长，管理百姓，'),
('CUV', '出埃及记', 2, 18, 22, '叫他们随时审判百姓，大事都要呈到你这里，小事他们自己可以审判。这样，你就轻省些，他们也可以同当此任。'),
('CUV', '出埃及记', 2, 18, 23, '你若这样行，神也这样吩咐你，你就能受得住，这百姓也都平平安安归回他们的住处。'),
('CUV', '出埃及记', 2, 18, 24, '于是，摩西听从他岳父的话，按著他所说的去行。'),
('CUV', '出埃及记', 2, 18, 25, '摩西从以色列人中拣选了有才能的人，立他们为百姓的首领，作千夫长、百夫长、五十夫长、十夫长。'),
('CUV', '出埃及记', 2, 18, 26, '他们随时审判百姓，有难断的案件就呈到摩西那里，但各样小事他们自己审判。'),
('CUV', '出埃及记', 2, 18, 27, '此后，摩西让他的岳父去，他就往本地去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 19, 1, '以色列人出埃及地以后，满了三个月的那一天，就来到西乃的旷野。'),
('CUV', '出埃及记', 2, 19, 2, '他们离了利非订，来到西乃的旷野，就在那里的山下安营。'),
('CUV', '出埃及记', 2, 19, 3, '摩西到神那里，耶和华从山上呼唤他说：你要这样告诉雅各家，晓谕以色列人说：'),
('CUV', '出埃及记', 2, 19, 4, '我向埃及人所行的事，你们都看见了，且看见我如鹰将你们背在翅膀上，带来归我。'),
('CUV', '出埃及记', 2, 19, 5, '如今你们若实在听从我的话，遵守我的约，就要在万民中作属我的子民，因为全地都是我的。'),
('CUV', '出埃及记', 2, 19, 6, '你们要归我作祭司的国度，为圣洁的国民。这些话你要告诉以色列人。'),
('CUV', '出埃及记', 2, 19, 7, '摩西去召了民间的长老来，将耶和华所吩咐他的话都在他们面前陈明。'),
('CUV', '出埃及记', 2, 19, 8, '百姓都同声回答说：凡耶和华所说的，我们都要遵行。摩西就将百姓的话回复耶和华。'),
('CUV', '出埃及记', 2, 19, 9, '耶和华对摩西说：我要在密云中临到你那里，叫百姓在我与你说话的时候可以听见，也可以永远信你了。于是，摩西将百姓的话奏告耶和华。'),
('CUV', '出埃及记', 2, 19, 10, '耶和华又对摩西说：你往百姓那里去，叫他们今天明天自洁，又叫他们洗衣服。'),
('CUV', '出埃及记', 2, 19, 11, '到第三天要预备好了，因为第三天耶和华要在众百姓眼前降临在西乃山上。'),
('CUV', '出埃及记', 2, 19, 12, '你要在山的四围给百姓定界限，说：你们当谨慎，不可上山去，也不可摸山的边界；凡摸这山的，必要治死他。'),
('CUV', '出埃及记', 2, 19, 13, '不可用手摸他，必用石头打死，或用箭射透；无论是人是牲畜，都不得活。到角声拖长的时候，他们才可到山根来。'),
('CUV', '出埃及记', 2, 19, 14, '摩西下山往百姓那里去，叫他们自洁，他们就洗衣服。'),
('CUV', '出埃及记', 2, 19, 15, '他对百姓说：到第三天要预备好了。不可亲近女人。'),
('CUV', '出埃及记', 2, 19, 16, '到了第三天早晨，在山上有雷轰、闪电，和密云，并且角声甚大，营中的百姓尽都发颤。'),
('CUV', '出埃及记', 2, 19, 17, '摩西率领百姓出营迎接神，都站在山下。'),
('CUV', '出埃及记', 2, 19, 18, '西乃全山冒烟，因为耶和华在火中降于山上。山的烟气上腾，如烧窑一般，遍山大大的震动。'),
('CUV', '出埃及记', 2, 19, 19, '角声渐渐的高而又高，摩西就说话，神有声音答应他。'),
('CUV', '出埃及记', 2, 19, 20, '耶和华降临在西乃山顶上，耶和华召摩西上山顶，摩西就上去。'),
('CUV', '出埃及记', 2, 19, 21, '耶和华对摩西说：你下去嘱咐百姓，不可闯过来到我面前观看，恐怕他们有多人死亡；'),
('CUV', '出埃及记', 2, 19, 22, '又叫亲近我的祭司自洁，恐怕我忽然出来击杀他们。'),
('CUV', '出埃及记', 2, 19, 23, '摩西对耶和华说：百姓不能上西乃山，因为你已经嘱咐我们说：要在山的四围定界限，叫山成圣。'),
('CUV', '出埃及记', 2, 19, 24, '耶和华对他说：下去罢，你要和亚伦一同上来；只是祭司和百姓不可闯过来上到我面前，恐怕我忽然出来击杀他们。'),
('CUV', '出埃及记', 2, 19, 25, '于是摩西下到百姓那里告诉他们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 20, 1, '神吩咐这一切的话说：'),
('CUV', '出埃及记', 2, 20, 2, '我是耶和华─你的神，曾将你从埃及地为奴之家领出来。'),
('CUV', '出埃及记', 2, 20, 3, '除了我以外，你不可有别的神。'),
('CUV', '出埃及记', 2, 20, 4, '不可为自己雕刻偶像，也不可做甚么形像仿佛上天、下地，和地底下、水中的百物。'),
('CUV', '出埃及记', 2, 20, 5, '不可跪拜那些像，也不可事奉他，因为我耶和华─你的神是忌邪的神。恨我的，我必追讨他的罪，自父及子，直到三四代；'),
('CUV', '出埃及记', 2, 20, 6, '爱我、守我诫命的，我必向他们发慈爱，直到千代。'),
('CUV', '出埃及记', 2, 20, 7, '不可妄称耶和华─你神的名；因为妄称耶和华名的，耶和华必不以他为无罪。'),
('CUV', '出埃及记', 2, 20, 8, '当记念安息日，守为圣日。'),
('CUV', '出埃及记', 2, 20, 9, '六日要劳碌做你一切的工，'),
('CUV', '出埃及记', 2, 20, 10, '但第七日是向耶和华─你神当守的安息日。这一日你和你的儿女、仆婢、牲畜，并你城里寄居的客旅，无论何工都不可做；'),
('CUV', '出埃及记', 2, 20, 11, '因为六日之内，耶和华造天、地、海，和其中的万物，第七日便安息，所以耶和华赐福与安息日，定为圣日。'),
('CUV', '出埃及记', 2, 20, 12, '当孝敬父母，使你的日子在耶和华─你神所赐你的地上得以长久。'),
('CUV', '出埃及记', 2, 20, 13, '不可杀人。'),
('CUV', '出埃及记', 2, 20, 14, '不可奸淫。'),
('CUV', '出埃及记', 2, 20, 15, '不可偷盗。'),
('CUV', '出埃及记', 2, 20, 16, '不可作假见证陷害人。'),
('CUV', '出埃及记', 2, 20, 17, '不可贪恋人的房屋；也不可贪恋人的妻子、仆婢、牛驴，并他一切所有的。'),
('CUV', '出埃及记', 2, 20, 18, '众百姓见雷轰、闪电、角声、山上冒烟，就都发颤，远远的站立，'),
('CUV', '出埃及记', 2, 20, 19, '对摩西说：求你和我们说话，我们必听；不要神和我们说话，恐怕我们死亡。'),
('CUV', '出埃及记', 2, 20, 20, '摩西对百姓说：不要惧怕；因为神降临是要试验你们，叫你们时常敬畏他，不致犯罪。'),
('CUV', '出埃及记', 2, 20, 21, '于是百姓远远地站立；摩西就挨近神所在的幽暗之中。'),
('CUV', '出埃及记', 2, 20, 22, '耶和华对摩西说：你要向以色列人这样说：你们自己看见我从天上和你们说话了。'),
('CUV', '出埃及记', 2, 20, 23, '你们不可做甚么神像与我相配，不可为自己做金银的神像。'),
('CUV', '出埃及记', 2, 20, 24, '你要为我筑土坛，在上面以牛羊献为燔祭和平安祭。凡记下我名的地方，我必到那里赐福给你。'),
('CUV', '出埃及记', 2, 20, 25, '你若为我筑一座石坛，不可用凿成的石头，因你在上头一动家具，就把坛污秽了。'),
('CUV', '出埃及记', 2, 20, 26, '你上我的坛，不可用台阶，免得露出你的下体来。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 21, 1, '你在百姓面前所要立的典章是这样：'),
('CUV', '出埃及记', 2, 21, 2, '你若买希伯来人作奴仆，他必服事你六年；第七年他可以自由，白白的出去。'),
('CUV', '出埃及记', 2, 21, 3, '他若孤身来就可以孤身去；他若有妻，他的妻就可以同他出去。'),
('CUV', '出埃及记', 2, 21, 4, '他主人若给他妻子，妻子给他生了儿子或女儿，妻子和儿女要归主人，他要独自出去。'),
('CUV', '出埃及记', 2, 21, 5, '倘或奴仆明说：我爱我的主人和我的妻子儿女，不愿意自由出去。'),
('CUV', '出埃及记', 2, 21, 6, '他的主人就要带他到审判官（审判官或作：神；下同）那里，又要带他到门前，靠近门框，用锥子穿他的耳朵，他就永远服事主人。'),
('CUV', '出埃及记', 2, 21, 7, '人若卖女儿作婢女，婢女不可像男仆那样出去。'),
('CUV', '出埃及记', 2, 21, 8, '主人选定他归自己，若不喜欢他，就要许他赎身；主人既然用诡诈待他，就没有权柄卖给外邦人。'),
('CUV', '出埃及记', 2, 21, 9, '主人若选定他给自己的儿子，就当待他如同女儿。'),
('CUV', '出埃及记', 2, 21, 10, '若另娶一个，那女子的吃食、衣服，并好合的事，仍不可减少。'),
('CUV', '出埃及记', 2, 21, 11, '若不向他行这三样，他就可以不用钱赎，白白的出去。'),
('CUV', '出埃及记', 2, 21, 12, '打人以致打死的，必要把他治死。'),
('CUV', '出埃及记', 2, 21, 13, '人若不是埋伏著杀人，乃是神交在他手中，我就设下一个地方，他可以往那里逃跑。'),
('CUV', '出埃及记', 2, 21, 14, '人若任意用诡计杀了他的邻舍，就是逃到我的坛那里，也当捉去把他治死。'),
('CUV', '出埃及记', 2, 21, 15, '打父母的，必要把他治死。'),
('CUV', '出埃及记', 2, 21, 16, '拐带人口，或是把人卖了，或是留在他手下，必要把他治死。'),
('CUV', '出埃及记', 2, 21, 17, '咒骂父母的，必要把他治死。'),
('CUV', '出埃及记', 2, 21, 18, '人若彼此相争，这个用石头或是拳头打那个，尚且不至于死，不过躺卧在床，'),
('CUV', '出埃及记', 2, 21, 19, '若再能起来扶杖而出，那打他的可算无罪；但要将他耽误的工夫用钱赔补，并要将他全然医好。'),
('CUV', '出埃及记', 2, 21, 20, '人若用棍子打奴仆或婢女，立时死在他的手下，他必要受刑。'),
('CUV', '出埃及记', 2, 21, 21, '若过一两天才死，就可以不受刑，因为是用钱买的。'),
('CUV', '出埃及记', 2, 21, 22, '人若彼此争斗，伤害有孕的妇人，甚至坠胎，随后却无别害，那伤害他的，总要按妇人的丈夫所要的，照审判官所断的，受罚。'),
('CUV', '出埃及记', 2, 21, 23, '若有别害，就要以命偿命，'),
('CUV', '出埃及记', 2, 21, 24, '以眼还眼，以牙还牙，以手还手，以脚还脚，'),
('CUV', '出埃及记', 2, 21, 25, '以烙还烙，以伤还伤，以打还打。'),
('CUV', '出埃及记', 2, 21, 26, '人若打坏了他奴仆或是婢女的一只眼，就要因他的眼放他去得以自由。'),
('CUV', '出埃及记', 2, 21, 27, '若打掉了他奴仆或是婢女的一个牙，就要因他的牙放他去得以自由。'),
('CUV', '出埃及记', 2, 21, 28, '牛若触死男人或是女人，总要用石头打死那牛，却不可吃他的肉；牛的主人可算无罪。'),
('CUV', '出埃及记', 2, 21, 29, '倘若那牛素来是触人的，有人报告了牛主，他竟不把牛拴著，以致把男人或是女人触死，就要用石头打死那牛，牛主也必治死。'),
('CUV', '出埃及记', 2, 21, 30, '若罚他赎命的价银，他必照所罚的赎他的命。'),
('CUV', '出埃及记', 2, 21, 31, '牛无论触了人的儿子或是女儿，必照这例办理。'),
('CUV', '出埃及记', 2, 21, 32, '牛若触了奴仆或是婢女，必将银子三十舍客勒给他们的主人，也要用石头把牛打死。'),
('CUV', '出埃及记', 2, 21, 33, '人若敞著井口，或挖井不遮盖，有牛或驴掉在里头，'),
('CUV', '出埃及记', 2, 21, 34, '井主要拿钱赔还本主人，死牲畜要归自己。'),
('CUV', '出埃及记', 2, 21, 35, '这人的牛若伤了那人的牛，以至于死，他们要卖了活牛，平分价值，也要平分死牛。'),
('CUV', '出埃及记', 2, 21, 36, '人若知道这牛素来是触人的，主人竟不把牛拴著，他必要以牛还牛，死牛要归自己。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 22, 1, '人若偷牛或羊，无论是宰了，是卖了，他就要以五牛赔一牛，四羊赔一羊。'),
('CUV', '出埃及记', 2, 22, 2, '人若遇见贼挖窟窿，把贼打了，以至于死，就不能为他有流血的罪。'),
('CUV', '出埃及记', 2, 22, 3, '若太阳已经出来，就为他有流血的罪。贼若被拿，总要赔还。若他一无所有，就要被卖，顶他所偷的物。'),
('CUV', '出埃及记', 2, 22, 4, '若他所偷的，或牛，或驴，或羊，仍在他手下存活，他就要加倍赔还。'),
('CUV', '出埃及记', 2, 22, 5, '人若在田间或在葡萄园里放牲畜，任凭牲畜上别人的田里去吃，就必拿自己田间上好的和葡萄园上好的赔还。'),
('CUV', '出埃及记', 2, 22, 6, '若点火焚烧荆棘，以致将别人堆积的禾捆，站著的禾稼，或是田园，都烧尽了，那点火的必要赔还。'),
('CUV', '出埃及记', 2, 22, 7, '人若将银钱或家具交付邻舍看守，这物从那人的家被偷去，若把贼找到了，贼要加倍赔还；'),
('CUV', '出埃及记', 2, 22, 8, '若找不到贼，那家主必就近审判官，要看看他拿了原主的物件没有。'),
('CUV', '出埃及记', 2, 22, 9, '两个人的案件，无论是为甚么过犯，或是为牛，为驴，为羊，为衣裳，或是为甚么失掉之物，有一人说：这是我的，两造就要将案件禀告审判官，审判官定谁有罪，谁就要加倍赔还。'),
('CUV', '出埃及记', 2, 22, 10, '人若将驴，或牛，或羊，或别的牲畜，交付邻舍看守，牲畜或死，或受伤，或被赶去，无人看见，'),
('CUV', '出埃及记', 2, 22, 11, '那看守的人要凭著耶和华起誓，手里未曾拿邻舍的物，本主就要罢休，看守的人不必赔还。'),
('CUV', '出埃及记', 2, 22, 12, '牲畜若从看守的那里被偷去，他就要赔还本主；'),
('CUV', '出埃及记', 2, 22, 13, '若被野兽撕碎，看守的要带来当作证据，所撕的不必赔还。'),
('CUV', '出埃及记', 2, 22, 14, '人若向邻舍借甚么，所借的或受伤，或死，本主没有同在一处，借的人总要赔还；'),
('CUV', '出埃及记', 2, 22, 15, '若本主同在一处，他就不必赔还；若是雇的，也不必赔还，本是为雇价来的。'),
('CUV', '出埃及记', 2, 22, 16, '人若引诱没有受聘的处女，与他行淫，他总要交出聘礼，娶他为妻。'),
('CUV', '出埃及记', 2, 22, 17, '若女子的父亲决不肯将女子给他，他就要按处女的聘礼，交出钱来。'),
('CUV', '出埃及记', 2, 22, 18, '行邪术的女人，不可容他存活。'),
('CUV', '出埃及记', 2, 22, 19, '凡与兽淫合的，总要把他治死。'),
('CUV', '出埃及记', 2, 22, 20, '祭祀别神，不单单祭祀耶和华的，那人必要灭绝。'),
('CUV', '出埃及记', 2, 22, 21, '不可亏负寄居的，也不可欺压他，因为你们在埃及地也作过寄居的。'),
('CUV', '出埃及记', 2, 22, 22, '不可苦待寡妇和孤儿；'),
('CUV', '出埃及记', 2, 22, 23, '若是苦待他们一点，他们向我一哀求，我总要听他们的哀声，'),
('CUV', '出埃及记', 2, 22, 24, '并要发烈怒，用刀杀你们，使你们的妻子为寡妇，儿女为孤儿。'),
('CUV', '出埃及记', 2, 22, 25, '我民中有贫穷人与你同住，你若借钱给他，不可如放债的向他取利。'),
('CUV', '出埃及记', 2, 22, 26, '你即或拿邻舍的衣服作当头，必在日落以先归还他；'),
('CUV', '出埃及记', 2, 22, 27, '因他只有这一件当盖头，是他盖身的衣服，若是没有，他拿甚么睡觉呢？他哀求我，我就应允，因为我是有恩惠的。'),
('CUV', '出埃及记', 2, 22, 28, '不可毁谤神；也不可毁谤你百姓的官长。'),
('CUV', '出埃及记', 2, 22, 29, '你要从你庄稼中的谷和酒醡中滴出来的酒拿来献上，不可迟延。你要将头生的儿子归给我。'),
('CUV', '出埃及记', 2, 22, 30, '你牛羊头生的，也要这样；七天当跟著母，第八天要归给我。'),
('CUV', '出埃及记', 2, 22, 31, '你要在我面前为圣洁的人。因此，田间被野兽撕裂牲畜的肉，你们不可吃，要丢给狗吃。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 23, 1, '不可随伙布散谣言；不可与恶人连手妄作见证。'),
('CUV', '出埃及记', 2, 23, 2, '不可随众行恶；不可在争讼的事上随众偏行，作见证屈枉正直；'),
('CUV', '出埃及记', 2, 23, 3, '也不可在争讼的事上偏护穷人。'),
('CUV', '出埃及记', 2, 23, 4, '若遇见你仇敌的牛或驴失迷了路，总要牵回来交给他。'),
('CUV', '出埃及记', 2, 23, 5, '若看见恨你人的驴压卧在重驮之下，不可走开，务要和驴主一同抬开重驮。'),
('CUV', '出埃及记', 2, 23, 6, '不可在穷人争讼的事上屈枉正直。'),
('CUV', '出埃及记', 2, 23, 7, '当远离虚假的事。不可杀无辜和有义的人，因我必不以恶人为义。'),
('CUV', '出埃及记', 2, 23, 8, '不可受贿赂；因为贿赂能叫明眼人变瞎了，又能颠倒义人的话。'),
('CUV', '出埃及记', 2, 23, 9, '不可欺压寄居的；因为你们在埃及地作过寄居的，知道寄居的心。'),
('CUV', '出埃及记', 2, 23, 10, '六年你要耕种田地，收藏土产，'),
('CUV', '出埃及记', 2, 23, 11, '只是第七年要叫地歇息，不耕不种，使你民中的穷人有吃的；他们所剩下的，野兽可以吃。你的葡萄园和橄榄园也要照样办理。'),
('CUV', '出埃及记', 2, 23, 12, '六日你要做工，第七日要安息，使牛、驴可以歇息，并使你婢女的儿子和寄居的都可以舒畅。'),
('CUV', '出埃及记', 2, 23, 13, '凡我对你们说的话，你们要谨守。别神的名，你不可题，也不可从你口中传说。'),
('CUV', '出埃及记', 2, 23, 14, '一年三次，你要向我守节。'),
('CUV', '出埃及记', 2, 23, 15, '你要守除酵节，照我所吩咐你的，在亚笔月内所定的日期，吃无酵饼七天。谁也不可空手朝见我，因为你是这月出了埃及。'),
('CUV', '出埃及记', 2, 23, 16, '又要守收割节，所收的是你田间所种、劳碌得来初熟之物。并在年底收藏，要守收藏节。'),
('CUV', '出埃及记', 2, 23, 17, '一切的男丁要一年三次朝见主耶和华。'),
('CUV', '出埃及记', 2, 23, 18, '不可将我祭牲的血和有酵的饼一同献上；也不可将我节上祭牲的脂油留到早晨。'),
('CUV', '出埃及记', 2, 23, 19, '地里首先初熟之物要送到耶和华─你神的殿。不可用山羊羔母的奶煮山羊羔。'),
('CUV', '出埃及记', 2, 23, 20, '看哪，我差遣使者在你前面，在路上保护你，领你到我所预备的地方去。'),
('CUV', '出埃及记', 2, 23, 21, '他是奉我名来的；你们要在他面前谨慎，听从他的话，不可惹（惹或作：违背）他，因为他必不赦免你们的过犯。'),
('CUV', '出埃及记', 2, 23, 22, '你若实在听从他的话，照著我一切所说的去行，我就向你的仇敌作仇敌，向你的敌人作敌人。'),
('CUV', '出埃及记', 2, 23, 23, '我的使者要在你前面行，领你到亚摩利人、赫人、比利洗人、迦南人、希未人、耶布斯人那里去，我必将他们剪除。'),
('CUV', '出埃及记', 2, 23, 24, '你不可跪拜他们的神，不可事奉他，也不可效法他们的行为，却要把神像尽行拆毁，打碎他们的柱像。'),
('CUV', '出埃及记', 2, 23, 25, '你们要事奉耶和华─你们的神，他必赐福与你的粮与你的水，也必从你们中间除去疾病。'),
('CUV', '出埃及记', 2, 23, 26, '你境内必没有坠胎的，不生产的。我要使你满了你年日的数目。'),
('CUV', '出埃及记', 2, 23, 27, '凡你所到的地方，我要使那里的众民在你面前惊骇，扰乱，又要使你一切仇敌转背逃跑。'),
('CUV', '出埃及记', 2, 23, 28, '我要打发黄蜂飞在你前面，把希未人、迦南人、赫人撵出去。'),
('CUV', '出埃及记', 2, 23, 29, '我不在一年之内将他们从你面前撵出去，恐怕地成为荒凉，野地的兽多起来害你。'),
('CUV', '出埃及记', 2, 23, 30, '我要渐渐地将他们从你面前撵出去，等到你的人数加多，承受那地为业。'),
('CUV', '出埃及记', 2, 23, 31, '我要定你的境界，从红海直到非利士海，又从旷野直到大河。我要将那地的居民交在你手中，你要将他们从你面前撵出去。'),
('CUV', '出埃及记', 2, 23, 32, '不可和他们并他们的神立约。'),
('CUV', '出埃及记', 2, 23, 33, '他们不可住在你的地上，恐怕他们使你得罪我。你若事奉他们的神，这必成为你的网罗。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 24, 1, '耶和华对摩西说：你和亚伦、拿答、亚比户，并以色列长老中的七十人，都要上到我这里来，远远的下拜。'),
('CUV', '出埃及记', 2, 24, 2, '惟独你可以亲近耶和华；他们却不可亲近；百姓也不可和你一同上来。'),
('CUV', '出埃及记', 2, 24, 3, '摩西下山，将耶和华的命令典章都述说与百姓听。众百姓齐声说：耶和华所吩咐的，我们都必遵行。'),
('CUV', '出埃及记', 2, 24, 4, '摩西将耶和华的命令都写上。清早起来，在山下筑一座坛，按以色列十二支派立十二根柱子，'),
('CUV', '出埃及记', 2, 24, 5, '又打发以色列人中的少年人去献燔祭，又向耶和华献牛为平安祭。'),
('CUV', '出埃及记', 2, 24, 6, '摩西将血一半盛在盆中，一半洒在坛上；'),
('CUV', '出埃及记', 2, 24, 7, '又将约书念给百姓听。他们说：耶和华所吩咐的，我们都必遵行。'),
('CUV', '出埃及记', 2, 24, 8, '摩西将血洒在百姓身上，说：你看！这是立约的血，是耶和华按这一切话与你们立约的凭据。'),
('CUV', '出埃及记', 2, 24, 9, '摩西、亚伦、拿答、亚比户，并以色列长老中的七十人，都上了山。'),
('CUV', '出埃及记', 2, 24, 10, '他们看见以色列的神，他脚下仿佛有平铺的蓝宝石，如同天色明净。'),
('CUV', '出埃及记', 2, 24, 11, '他的手不加害在以色列的尊者身上。他们观看神；他们又吃又喝。'),
('CUV', '出埃及记', 2, 24, 12, '耶和华对摩西说：你上山到我这里来，住在这里，我要将石版并我所写的律法和诫命赐给你，使你可以教训百姓。'),
('CUV', '出埃及记', 2, 24, 13, '摩西和他的帮手约书亚起来，上了神的山。'),
('CUV', '出埃及记', 2, 24, 14, '摩西对长老说：你们在这里等著，等到我们再回来，有亚伦、户珥与你们同在。凡有争讼的，都可以就近他们去。'),
('CUV', '出埃及记', 2, 24, 15, '摩西上山，有云彩把山遮盖。'),
('CUV', '出埃及记', 2, 24, 16, '耶和华的荣耀停于西乃山；云彩遮盖山六天，第七天他从云中召摩西。'),
('CUV', '出埃及记', 2, 24, 17, '耶和华的荣耀在山顶上，在以色列人眼前，形状如烈火。'),
('CUV', '出埃及记', 2, 24, 18, '摩西进入云中上山，在山上四十昼夜。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 25, 1, '耶和华晓谕摩西说：'),
('CUV', '出埃及记', 2, 25, 2, '你告诉以色列人当为我送礼物来；凡甘心乐意的，你们就可以收下归我。'),
('CUV', '出埃及记', 2, 25, 3, '所要收的礼物：就是金、银、铜，'),
('CUV', '出埃及记', 2, 25, 4, '蓝色、紫色、朱红色线，细麻，山羊毛，'),
('CUV', '出埃及记', 2, 25, 5, '染红的公羊皮，海狗皮，皂荚木，'),
('CUV', '出埃及记', 2, 25, 6, '点灯的油并做膏油和香的香料，'),
('CUV', '出埃及记', 2, 25, 7, '红玛瑙与别样的宝石，可以镶嵌在以弗得和胸牌上。'),
('CUV', '出埃及记', 2, 25, 8, '又当为我造圣所，使我可以住在他们中间。'),
('CUV', '出埃及记', 2, 25, 9, '制造帐幕和其中的一切器具都要照我所指示你的样式。'),
('CUV', '出埃及记', 2, 25, 10, '要用皂荚木做一柜，长二肘半，宽一肘半，高一肘半。'),
('CUV', '出埃及记', 2, 25, 11, '要里外包上精金，四围镶上金牙边。'),
('CUV', '出埃及记', 2, 25, 12, '也要铸四个金环，安在柜的四脚上；这边两环，那边两环。'),
('CUV', '出埃及记', 2, 25, 13, '要用皂荚木做两根杠，用金包裹。'),
('CUV', '出埃及记', 2, 25, 14, '要把杠穿在柜旁的环内，以便抬柜。'),
('CUV', '出埃及记', 2, 25, 15, '这杠要常在柜的环内，不可抽出来。'),
('CUV', '出埃及记', 2, 25, 16, '必将我所要赐给你的法版放在柜里。'),
('CUV', '出埃及记', 2, 25, 17, '要用精金做施恩座（施恩：或作蔽罪；下同），长二肘半，宽一肘半。'),
('CUV', '出埃及记', 2, 25, 18, '要用金子锤出两个基路伯来，安在施恩座的两头。'),
('CUV', '出埃及记', 2, 25, 19, '这头做一个基路伯，那头做一个基路伯，二基路伯要接连一块，在施恩座的两头。'),
('CUV', '出埃及记', 2, 25, 20, '二基路伯要高张翅膀，遮掩施恩座。基路伯要脸对脸，朝著施恩座。'),
('CUV', '出埃及记', 2, 25, 21, '要将施恩座安在柜的上边，又将我所要赐给你的法版放在柜里。'),
('CUV', '出埃及记', 2, 25, 22, '我要在那里与你相会，又要从法柜施恩座上二基路伯中间，和你说我所要吩咐你传给以色列人的一切事。'),
('CUV', '出埃及记', 2, 25, 23, '要用皂荚木做一张桌子，长二肘，宽一肘，高一肘半。'),
('CUV', '出埃及记', 2, 25, 24, '要包上精金，四围镶上金牙边。'),
('CUV', '出埃及记', 2, 25, 25, '桌子的四围各做一掌宽的横梁，横梁上镶著金牙边。'),
('CUV', '出埃及记', 2, 25, 26, '要做四个金环，安在桌子的四角上，就是桌子四脚上的四角。'),
('CUV', '出埃及记', 2, 25, 27, '安环子的地方要挨近横梁，可以穿杠抬桌子。'),
('CUV', '出埃及记', 2, 25, 28, '要用皂荚木做两根杠，用金包裹，以便抬桌子。'),
('CUV', '出埃及记', 2, 25, 29, '要做桌子上的盘子、调羹，并奠酒的爵和瓶；这都要用精金制作。'),
('CUV', '出埃及记', 2, 25, 30, '又要在桌子上，在我面前，常摆陈设饼。'),
('CUV', '出埃及记', 2, 25, 31, '要用精金做一个灯台。灯台的座和干与杯、球、花，都要接连一块锤出来。'),
('CUV', '出埃及记', 2, 25, 32, '灯台两旁要杈出六个枝子：这旁三个，那旁三个。'),
('CUV', '出埃及记', 2, 25, 33, '这旁每枝上有三个杯，形状像杏花，有球，有花；那旁每枝上也有三个杯，形状像杏花，有球，有花。从灯台杈出来的六个枝子都是如此。'),
('CUV', '出埃及记', 2, 25, 34, '灯台上有四个杯，形状像杏花，有球，有花。'),
('CUV', '出埃及记', 2, 25, 35, '灯台每两个枝子以下有球与枝子接连一块。灯台出的六个枝子都是如此。'),
('CUV', '出埃及记', 2, 25, 36, '球和枝子要接连一块，都是一块精金锤出来的。'),
('CUV', '出埃及记', 2, 25, 37, '要做灯台的七个灯盏。祭司要点这灯，使灯光对照。'),
('CUV', '出埃及记', 2, 25, 38, '灯台的蜡剪和蜡花盘也是要精金的。'),
('CUV', '出埃及记', 2, 25, 39, '做灯台和这一切的器具要用精金一他连得。'),
('CUV', '出埃及记', 2, 25, 40, '要谨慎做这些物件，都要照著在山上指示你的样式。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 26, 1, '你要用十幅幔子做帐幕。这些幔子要用撚的细麻和蓝色、紫色、朱红色线制造，并用巧匠的手工绣上基路伯。'),
('CUV', '出埃及记', 2, 26, 2, '每幅幔子要长二十八肘，宽四肘，幔子都要一样的尺寸。'),
('CUV', '出埃及记', 2, 26, 3, '这五幅幔子要幅幅相连；那五幅幔子也要幅幅相连。'),
('CUV', '出埃及记', 2, 26, 4, '在这相连的幔子末幅边上要做蓝色的钮扣；在那相连的幔子末幅边上也要照样做。'),
('CUV', '出埃及记', 2, 26, 5, '要在这相连的幔子上做五十个钮扣；在那相连的幔子上也做五十个钮扣，都要两两相对。'),
('CUV', '出埃及记', 2, 26, 6, '又要做五十个金钩，用钩使幔子相连，这才成了一个帐幕。'),
('CUV', '出埃及记', 2, 26, 7, '你要用山羊毛织十一幅幔子，作为帐幕以上的罩棚。'),
('CUV', '出埃及记', 2, 26, 8, '每幅幔子要长三十肘，宽四肘；十一幅幔子都要一样的尺寸。'),
('CUV', '出埃及记', 2, 26, 9, '要把五幅幔子连成一幅，又把六幅幔子连成一幅，这第六幅幔子要在罩棚的前面折上去。'),
('CUV', '出埃及记', 2, 26, 10, '在这相连的幔子末幅边上要做五十个钮扣；在那相连的幔子末幅边上也做五十个钮扣。'),
('CUV', '出埃及记', 2, 26, 11, '又要做五十个铜钩，钩在钮扣中，使罩棚连成一个。'),
('CUV', '出埃及记', 2, 26, 12, '罩棚的幔子所余那垂下来的半幅幔子，要垂在帐幕的后头。'),
('CUV', '出埃及记', 2, 26, 13, '罩棚的幔子所余长的，这边一肘，那边一肘，要垂在帐幕的两旁，遮盖帐幕。'),
('CUV', '出埃及记', 2, 26, 14, '又要用染红的公羊皮做罩棚的盖；再用海狗皮做一层罩棚上的顶盖。'),
('CUV', '出埃及记', 2, 26, 15, '你要用皂荚木做帐幕的竖板。'),
('CUV', '出埃及记', 2, 26, 16, '每块要长十肘，宽一肘半；'),
('CUV', '出埃及记', 2, 26, 17, '每块必有两榫相对。帐幕一切的板都要这样做。'),
('CUV', '出埃及记', 2, 26, 18, '帐幕的南面要做板二十块。'),
('CUV', '出埃及记', 2, 26, 19, '在这二十块板底下要做四十个带卯的银座，两卯接这块板上的两榫，两卯接那块板上的两榫。'),
('CUV', '出埃及记', 2, 26, 20, '帐幕第二面，就是北面，也要做板二十块'),
('CUV', '出埃及记', 2, 26, 21, '和带卯的银座四十个；这板底下有两卯，那板底下也有两卯。'),
('CUV', '出埃及记', 2, 26, 22, '帐幕的后面，就是西面，要做板六块。'),
('CUV', '出埃及记', 2, 26, 23, '帐幕后面的拐角要做板两块。'),
('CUV', '出埃及记', 2, 26, 24, '板的下半截要双的，上半截要整的，直顶到第一个环子；两块都要这样做两个拐角。'),
('CUV', '出埃及记', 2, 26, 25, '必有八块板和十六个带卯的银座；这板底下有两卯，那板底下也有两卯。'),
('CUV', '出埃及记', 2, 26, 26, '你要用皂荚木做闩：为帐幕这面的板做五闩，'),
('CUV', '出埃及记', 2, 26, 27, '为帐幕那面的板做五闩，又为帐幕后面的板做五闩。'),
('CUV', '出埃及记', 2, 26, 28, '板腰间的中闩要从这一头通到那一头。'),
('CUV', '出埃及记', 2, 26, 29, '板要用金子包裹，又要做板上的金环套闩；闩也要用金子包裹。'),
('CUV', '出埃及记', 2, 26, 30, '要照著在山上指示你的样式立起帐幕。'),
('CUV', '出埃及记', 2, 26, 31, '你要用蓝色、紫色、朱红色线，和撚的细麻织幔子，以巧匠的手工绣上基路伯。'),
('CUV', '出埃及记', 2, 26, 32, '要把幔子挂在四根包金的皂荚木柱子上，柱子上当有金钩，柱子安在四个带卯的银座上。'),
('CUV', '出埃及记', 2, 26, 33, '要使幔子垂在钩子下，把法柜抬进幔子内；这幔子要将圣所和至圣所隔开。'),
('CUV', '出埃及记', 2, 26, 34, '又要把施恩座安在至圣所内的法柜上，'),
('CUV', '出埃及记', 2, 26, 35, '把桌子安在幔子外帐幕的北面；把灯台安在帐幕的南面，彼此相对。'),
('CUV', '出埃及记', 2, 26, 36, '你要拿蓝色、紫色、朱红色线，和撚的细麻，用绣花的手工织帐幕的门帘。'),
('CUV', '出埃及记', 2, 26, 37, '要用皂荚木为帘子做五根柱子，用金子包裹。柱子上当有金钩；又要为柱子用铜铸造五个带卯的座。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 27, 1, '你要用皂荚木做坛。这坛要四方的，长五肘，宽五肘，高三肘。'),
('CUV', '出埃及记', 2, 27, 2, '要在坛的四拐角上做四个角，与坛接连一块，用铜把坛包裹。'),
('CUV', '出埃及记', 2, 27, 3, '要做盆，收去坛上的灰，又做铲子、盘子、肉锸子、火鼎；坛上一切的器具都用铜做。'),
('CUV', '出埃及记', 2, 27, 4, '要为坛做一个铜网，在网的四角上做四个铜环，'),
('CUV', '出埃及记', 2, 27, 5, '把网安在坛四面的围腰板以下，使网从下达到坛的半腰。'),
('CUV', '出埃及记', 2, 27, 6, '又要用皂荚木为坛做杠，用铜包裹。'),
('CUV', '出埃及记', 2, 27, 7, '这杠要穿在坛两旁的环子内，用以抬坛。'),
('CUV', '出埃及记', 2, 27, 8, '要用板做坛，坛是空的，都照著在山上指示你的样式作。'),
('CUV', '出埃及记', 2, 27, 9, '你要做帐幕的院子。院子的南面要用撚的细麻做帷子，长一百肘。'),
('CUV', '出埃及记', 2, 27, 10, '帷子的柱子要二十根，带卯的铜座二十个。柱子上的钩子和杆子都要用银子做。'),
('CUV', '出埃及记', 2, 27, 11, '北面也当有帷子，长一百肘，帷子的柱子二十根，带卯的铜座二十个。柱子上的钩子和杆子都要用银子做。'),
('CUV', '出埃及记', 2, 27, 12, '院子的西面当有帷子，宽五十肘，帷子的柱子十根，带卯的座十个。'),
('CUV', '出埃及记', 2, 27, 13, '院子的东面要宽五十肘。'),
('CUV', '出埃及记', 2, 27, 14, '门这边的帷子要十五肘，帷子的柱子三根，带卯的座三个。'),
('CUV', '出埃及记', 2, 27, 15, '门那边的帷子也要十五肘，帷子的柱子三根，带卯的座三个。'),
('CUV', '出埃及记', 2, 27, 16, '院子的门当有帘子，长二十肘，要拿蓝色、紫色、朱红色线，和撚的细麻，用绣花的手工织成，柱子四根，带卯的座四个。'),
('CUV', '出埃及记', 2, 27, 17, '院子四围一切的柱子都要用银杆连络，柱子上的钩子要用银做，带卯的座要用铜做。'),
('CUV', '出埃及记', 2, 27, 18, '院子要长一百肘，宽五十肘，高五肘，帷子要用撚的细麻做，带卯的座要用铜做。'),
('CUV', '出埃及记', 2, 27, 19, '帐幕各样用处的器具，并帐幕一切的橛子，和院子里一切的橛子，都要用铜做。'),
('CUV', '出埃及记', 2, 27, 20, '你要吩咐以色列人，把那为点灯捣成的清橄榄油拿来给你，使灯常常点著。'),
('CUV', '出埃及记', 2, 27, 21, '在会幕中法柜前的幔外，亚伦和他的儿子，从晚上到早晨，要在耶和华面前经理这灯。这要作以色列人世世代代永远的定例。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 28, 1, '你要从以色列人中，使你的哥哥亚伦和他的儿子拿答、亚比户、以利亚撒、以他玛一同就近你，给我供祭司的职分。'),
('CUV', '出埃及记', 2, 28, 2, '你要给你哥哥亚伦做圣衣为荣耀，为华美。'),
('CUV', '出埃及记', 2, 28, 3, '又要吩咐一切心中有智慧的，就是我用智慧的灵所充满的，给亚伦做衣服，使他分别为圣，可以给我供祭司的职分。'),
('CUV', '出埃及记', 2, 28, 4, '所要做的就是胸牌、以弗得、外袍、杂色的内袍、冠冕、腰带，使你哥哥亚伦和他儿子穿这圣服，可以给我供祭司的职分。'),
('CUV', '出埃及记', 2, 28, 5, '要用金线和蓝色、紫色、朱红色线，并细麻去做。'),
('CUV', '出埃及记', 2, 28, 6, '他们要拿金线和蓝色、紫色、朱红色线，并撚的细麻，用巧匠的手工做以弗得。'),
('CUV', '出埃及记', 2, 28, 7, '以弗得当有两条肩带，接上两头，使他相连。'),
('CUV', '出埃及记', 2, 28, 8, '其上巧工织的带子，要和以弗得一样的做法，用以束上，与以弗得接连一块，要用金线和蓝色、紫色、朱红色线，并撚的细麻做成。'),
('CUV', '出埃及记', 2, 28, 9, '要取两块红玛瑙，在上面刻以色列儿子的名字：'),
('CUV', '出埃及记', 2, 28, 10, '六个名字在这块宝石上，六个名字在那块宝石上，都照他们生来的次序。'),
('CUV', '出埃及记', 2, 28, 11, '要用刻宝石的手工，仿佛刻图书，按著以色列儿子的名字，刻这两块宝石，要镶在金槽上。'),
('CUV', '出埃及记', 2, 28, 12, '要将这两块宝石安在以弗得的两条肩带上，为以色列人做纪念石。亚伦要在两肩上担他们的名字，在耶和华面前作为纪念。'),
('CUV', '出埃及记', 2, 28, 13, '要用金子做二槽，'),
('CUV', '出埃及记', 2, 28, 14, '又拿精金，用拧工仿佛拧绳子，做两条链子，把这拧成的链子搭在二槽上。'),
('CUV', '出埃及记', 2, 28, 15, '你要用巧匠的手工做一个决断的胸牌。要和以弗得一样的做法：用金线和蓝色、紫色、朱红色线，并撚的细麻做成。'),
('CUV', '出埃及记', 2, 28, 16, '这胸牌要四方的，叠为两层，长一虎口，宽一虎口。'),
('CUV', '出埃及记', 2, 28, 17, '要在上面镶宝石四行：第一行是红宝石、红璧玺、红玉；'),
('CUV', '出埃及记', 2, 28, 18, '第二行是绿宝石、蓝宝石、金钢石；'),
('CUV', '出埃及记', 2, 28, 19, '第三行是紫玛瑙、白玛瑙、紫晶；'),
('CUV', '出埃及记', 2, 28, 20, '第四行是水苍玉、红玛瑙、碧玉。这都要镶在金槽中。'),
('CUV', '出埃及记', 2, 28, 21, '这些宝石都要按著以色列十二个儿子的名字，仿佛刻图书，刻十二个支派的名字。'),
('CUV', '出埃及记', 2, 28, 22, '要在胸牌上用精金拧成如绳的链子。'),
('CUV', '出埃及记', 2, 28, 23, '在胸牌上也要做两个金环，安在胸牌的两头。'),
('CUV', '出埃及记', 2, 28, 24, '要把那两条拧成的金链子，穿过胸牌两头的环子。'),
('CUV', '出埃及记', 2, 28, 25, '又要把链子的那两头接在两槽上，安在以弗得前面肩带上。'),
('CUV', '出埃及记', 2, 28, 26, '要做两个金环，安在胸牌的两头，在以弗得里面的边上。'),
('CUV', '出埃及记', 2, 28, 27, '又要做两个金环，安在以弗得前面两条肩带的下边，挨近相接之处，在以弗得巧工织的带子以上。'),
('CUV', '出埃及记', 2, 28, 28, '要用蓝细带子把胸牌的环子与以弗得的环子系住，使胸牌贴在以弗得巧工织的带子上，不可与以弗得离缝。'),
('CUV', '出埃及记', 2, 28, 29, '亚伦进圣所的时候，要将决断胸牌，就是刻著以色列儿子名字的，带在胸前，在耶和华面前常作纪念。'),
('CUV', '出埃及记', 2, 28, 30, '又要将乌陵和土明放在决断的胸牌里；亚伦进到耶和华面前的时候，要带在胸前，在耶和华面前常将以色列人的决断牌带在胸前。'),
('CUV', '出埃及记', 2, 28, 31, '你要做以弗得的外袍，颜色全是蓝的。'),
('CUV', '出埃及记', 2, 28, 32, '袍上要为头留一领口，口的周围织出领边来，仿佛铠甲的领口，免得破裂。'),
('CUV', '出埃及记', 2, 28, 33, '袍子周围底边上要用蓝色、紫色、朱红色线做石榴。在袍子周围的石榴中间要有金铃铛：'),
('CUV', '出埃及记', 2, 28, 34, '一个金铃铛一个石榴，一个金铃铛一个石榴，在袍子周围的底边上。'),
('CUV', '出埃及记', 2, 28, 35, '亚伦供职的时候要穿这袍子。他进圣所到耶和华面前，以及出来的时候，袍上的响声必被听见，使他不至于死亡。'),
('CUV', '出埃及记', 2, 28, 36, '你要用精金做一面牌，在上面按刻图书之法刻著归耶和华为圣。'),
('CUV', '出埃及记', 2, 28, 37, '要用一条蓝细带子将牌系在冠冕的前面。'),
('CUV', '出埃及记', 2, 28, 38, '这牌必在亚伦的额上，亚伦要担当干犯圣物条例的罪孽；这圣物是以色列人在一切的圣礼物上所分别为圣的。这牌要常在他的额上，使他们可以在耶和华面前蒙悦纳。'),
('CUV', '出埃及记', 2, 28, 39, '要用杂色细麻线织内袍，用细麻布做冠冕，又用绣花的手工做腰带。'),
('CUV', '出埃及记', 2, 28, 40, '你要为亚伦的儿子做内袍、腰带、裹头巾，为荣耀，为华美。'),
('CUV', '出埃及记', 2, 28, 41, '要把这些给你的哥哥亚伦和他的儿子穿戴，又要膏他们，将他们分别为圣，好给我供祭司的职分。'),
('CUV', '出埃及记', 2, 28, 42, '要给他们做细麻布裤子，遮掩下体；裤子当从腰达到大腿。'),
('CUV', '出埃及记', 2, 28, 43, '亚伦和他儿子进入会幕，或就近坛，在圣所供职的时候必穿上，免得担罪而死。这要为亚伦和他的后裔作永远的定例。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 29, 1, '你使亚伦和他儿子成圣，给我供祭司的职分，要如此行：取一只公牛犊，两只无残疾的公绵羊，'),
('CUV', '出埃及记', 2, 29, 2, '无酵饼和调油的无酵饼，与抹油的无酵薄饼；这都要用细麦面做成。'),
('CUV', '出埃及记', 2, 29, 3, '这饼要装在一个筐子里，连筐子带来，又把公牛和两只公绵羊牵来。'),
('CUV', '出埃及记', 2, 29, 4, '要使亚伦和他儿子到会幕门口来，用水洗身。'),
('CUV', '出埃及记', 2, 29, 5, '要给亚伦穿上内袍和以弗得的外袍，并以弗得，又带上胸牌，束上以弗得巧工织的带子。'),
('CUV', '出埃及记', 2, 29, 6, '把冠冕戴在他头上，将圣冠加在冠冕上，'),
('CUV', '出埃及记', 2, 29, 7, '就把膏油倒在他头上膏他。'),
('CUV', '出埃及记', 2, 29, 8, '要叫他的儿子来，给他们穿上内袍。'),
('CUV', '出埃及记', 2, 29, 9, '给亚伦和他儿子束上腰带，包上裹头巾，他们就凭永远的定例得了祭司的职任。又要将亚伦和他儿子分别为圣。'),
('CUV', '出埃及记', 2, 29, 10, '你要把公牛带到会幕前，亚伦和他儿子要按手在公牛的头上。'),
('CUV', '出埃及记', 2, 29, 11, '你要在耶和华面前，在会幕门口，宰这公牛。'),
('CUV', '出埃及记', 2, 29, 12, '要取些公牛的血，用指头抹在坛的四角上，把血都倒在坛脚那里。'),
('CUV', '出埃及记', 2, 29, 13, '要把一切盖脏的脂油与肝上的网子，并两个腰子和腰子上的脂油，都烧在坛上。'),
('CUV', '出埃及记', 2, 29, 14, '只是公牛的皮、肉、粪都要用火烧在营外。这牛是赎罪祭。'),
('CUV', '出埃及记', 2, 29, 15, '你要牵一只公绵羊来，亚伦和他儿子要按手在这羊的头上。'),
('CUV', '出埃及记', 2, 29, 16, '要宰这羊，把血洒在坛的周围。'),
('CUV', '出埃及记', 2, 29, 17, '要把羊切成块子，洗净五脏和腿，连块子带头，都放在一处。'),
('CUV', '出埃及记', 2, 29, 18, '要把全羊烧在坛上，是给耶和华献的燔祭，是献给耶和华为馨香的火祭。'),
('CUV', '出埃及记', 2, 29, 19, '你要将那一只公绵羊牵来，亚伦和他儿子要按手在羊的头上。'),
('CUV', '出埃及记', 2, 29, 20, '你要宰这羊，取点血抹在亚伦的右耳垂上和他儿子的右耳垂上，又抹在他们右手的大拇指上和右脚的大拇指上；并要把血洒在坛的四围。'),
('CUV', '出埃及记', 2, 29, 21, '你要取点膏油和坛上的血，弹在亚伦和他的衣服上，并他儿子和他儿子的衣服上，他们和他们的衣服就一同成圣。'),
('CUV', '出埃及记', 2, 29, 22, '你要取这羊的脂油和肥尾巴，并盖脏的脂油与肝上的网子，两个腰子和腰子上的脂油并右腿（这是承接圣职所献的羊）。'),
('CUV', '出埃及记', 2, 29, 23, '再从耶和华面前装无酵饼的筐子中取一个饼，一个调油的饼和一个薄饼，'),
('CUV', '出埃及记', 2, 29, 24, '都放在亚伦的手上和他儿子的手上，作为摇祭，在耶和华面前摇一摇。'),
('CUV', '出埃及记', 2, 29, 25, '要从他们手中接过来，烧在耶和华面前坛上的燔祭上，是献给耶和华为馨香的火祭。'),
('CUV', '出埃及记', 2, 29, 26, '你要取亚伦承接圣职所献公羊的胸，作为摇祭，在耶和华面前摇一摇，这就可以作你的分。'),
('CUV', '出埃及记', 2, 29, 27, '那摇祭的胸和举祭的腿，就是承接圣职所摇的、所举的，是归亚伦和他儿子的。这些你都要成为圣，'),
('CUV', '出埃及记', 2, 29, 28, '作亚伦和他子孙从以色列人中永远所得的分，因为是举祭。这要从以色列人的平安祭中，作为献给耶和华的举祭。'),
('CUV', '出埃及记', 2, 29, 29, '亚伦的圣衣要留给他的子孙，可以穿著受膏，又穿著承接圣职。'),
('CUV', '出埃及记', 2, 29, 30, '他的子孙接续他当祭司的，每逢进会幕在圣所供职的时候，要穿七天。'),
('CUV', '出埃及记', 2, 29, 31, '你要将承接圣职所献公羊的肉煮在圣处。'),
('CUV', '出埃及记', 2, 29, 32, '亚伦和他儿子要在会幕门口吃这羊的肉和筐内的饼。'),
('CUV', '出埃及记', 2, 29, 33, '他们吃那些赎罪之物，好承接圣职，使他们成圣；只是外人不可吃，因为这是圣物。'),
('CUV', '出埃及记', 2, 29, 34, '那承接圣职所献的肉或饼，若有一点留到早晨，就要用火烧了，不可吃这物，因为是圣物。'),
('CUV', '出埃及记', 2, 29, 35, '你要这样照我一切所吩咐的，向亚伦和他儿子行承接圣职的礼七天。'),
('CUV', '出埃及记', 2, 29, 36, '每天要献公牛一只为赎罪祭。你洁净坛的时候，坛就洁净了；且要用膏抹坛，使坛成圣。'),
('CUV', '出埃及记', 2, 29, 37, '要洁净坛七天，使坛成圣，坛就成为至圣。凡挨著坛的都成为圣。'),
('CUV', '出埃及记', 2, 29, 38, '你每天所要献在坛上的就是两只一岁的羊羔；'),
('CUV', '出埃及记', 2, 29, 39, '早晨要献这一只，黄昏的时候要献那一只。'),
('CUV', '出埃及记', 2, 29, 40, '和这一只羊羔同献的，要用细面伊法十分之一与捣成的油一欣四分之一调和，又用酒一欣四分之一作为奠祭。'),
('CUV', '出埃及记', 2, 29, 41, '那一只羊羔要在黄昏的时候献上，照著早晨的素祭和奠祭的礼办理，作为献给耶和华馨香的火祭。'),
('CUV', '出埃及记', 2, 29, 42, '这要在耶和华面前、会幕门口，作你们世世代代常献的燔祭。我要在那里与你们相会，和你们说话。'),
('CUV', '出埃及记', 2, 29, 43, '我要在那里与以色列人相会，会幕就要因我的荣耀成为圣。'),
('CUV', '出埃及记', 2, 29, 44, '我要使会幕和坛成圣，也要使亚伦和他的儿子成圣，给我供祭司的职分。'),
('CUV', '出埃及记', 2, 29, 45, '我要住在以色列人中间，作他们的神。'),
('CUV', '出埃及记', 2, 29, 46, '他们必知道我是耶和华─他们的神，是将他们从埃及地领出来的，为要住在他们中间。我是耶和华─他们的神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 30, 1, '你要用皂荚木做一座烧香的坛。'),
('CUV', '出埃及记', 2, 30, 2, '这坛要四方的，长一肘，宽一肘，高二肘；坛的四角要与坛接连一块。'),
('CUV', '出埃及记', 2, 30, 3, '要用精金把坛的上面与坛的四围，并坛的四角，包裹；又要在坛的四围镶上金牙边。'),
('CUV', '出埃及记', 2, 30, 4, '要做两个金环安在牙子边以下，在坛的两旁，两根横撑上，作为穿杠的用处，以便抬坛。'),
('CUV', '出埃及记', 2, 30, 5, '要用皂荚木做杠，用金包裹。'),
('CUV', '出埃及记', 2, 30, 6, '要把坛放在法柜前的幔子外，对著法柜上的施恩座，就是我要与你相会的地方。'),
('CUV', '出埃及记', 2, 30, 7, '亚伦在坛上要烧馨香料做的香；每早晨他收拾灯的时候，要烧这香。'),
('CUV', '出埃及记', 2, 30, 8, '黄昏点灯的时候，他要在耶和华面前烧这香，作为世世代代常烧的香。'),
('CUV', '出埃及记', 2, 30, 9, '在这坛上不可奉上异样的香，不可献燔祭、素祭，也不可浇上奠祭。'),
('CUV', '出埃及记', 2, 30, 10, '亚伦一年一次要在坛的角上行赎罪之礼。他一年一次要用赎罪祭牲的血在坛上行赎罪之礼，作为世世代代的定例。这坛在耶和华面前为至圣。'),
('CUV', '出埃及记', 2, 30, 11, '耶和华晓谕摩西说：'),
('CUV', '出埃及记', 2, 30, 12, '你要按以色列人被数的，计算总数，你数的时候，他们各人要为自己的生命把赎价奉给耶和华，免得数的时候在他们中间有灾殃。'),
('CUV', '出埃及记', 2, 30, 13, '凡过去归那些被数之人的，每人要按圣所的平，拿银子半舍客勒；这半舍客勒是奉给耶和华的礼物（一舍客勒是二十季拉）。'),
('CUV', '出埃及记', 2, 30, 14, '凡过去归那些被数的人，从二十岁以外的，要将这礼物奉给耶和华。'),
('CUV', '出埃及记', 2, 30, 15, '他们为赎生命将礼物奉给耶和华，富足的不可多出，贫穷的也不可少出，各人要出半舍客勒。'),
('CUV', '出埃及记', 2, 30, 16, '你要从以色列人收这赎罪银，作为会幕的使用，可以在耶和华面前为以色列人作纪念，赎生命。'),
('CUV', '出埃及记', 2, 30, 17, '耶和华晓谕摩西说：'),
('CUV', '出埃及记', 2, 30, 18, '你要用铜做洗濯盆和盆座，以便洗濯。要将盆放在会幕和坛的中间，在盆里盛水。'),
('CUV', '出埃及记', 2, 30, 19, '亚伦和他的儿子要在这盆里洗手洗脚。'),
('CUV', '出埃及记', 2, 30, 20, '他们进会幕，或是就近坛前供职给耶和华献火祭的时候，必用水洗濯，免得死亡。'),
('CUV', '出埃及记', 2, 30, 21, '他们洗手洗脚就免得死亡。这要作亚伦和他后裔世世代代永远的定例。'),
('CUV', '出埃及记', 2, 30, 22, '耶和华晓谕摩西说：'),
('CUV', '出埃及记', 2, 30, 23, '你要取上品的香料，就是流质的没药五百舍客勒，香肉桂一半，就是二百五十舍客勒，菖蒲二百五十舍客勒，'),
('CUV', '出埃及记', 2, 30, 24, '桂皮五百舍客勒，都按著圣所的平，又取橄榄油一欣，'),
('CUV', '出埃及记', 2, 30, 25, '按做香之法调和做成圣膏油。'),
('CUV', '出埃及记', 2, 30, 26, '要用这膏油抹会幕和法柜，'),
('CUV', '出埃及记', 2, 30, 27, '桌子与桌子的一切器具，灯台和灯台的器具，并香坛、'),
('CUV', '出埃及记', 2, 30, 28, '燔祭坛，和坛的一切器具，洗濯盆和盆座。'),
('CUV', '出埃及记', 2, 30, 29, '要使这些物成为圣，好成为至圣；凡挨著的都成为圣。'),
('CUV', '出埃及记', 2, 30, 30, '要膏亚伦和他的儿子，使他们成为圣，可以给我供祭司的职分。'),
('CUV', '出埃及记', 2, 30, 31, '你要对以色列人说：这油，我要世世代代以为圣膏油。'),
('CUV', '出埃及记', 2, 30, 32, '不可倒在别人的身上，也不可按这调和之法做与此相似的。这膏油是圣的，你们也要以为圣。'),
('CUV', '出埃及记', 2, 30, 33, '凡调和与此相似的，或将这膏膏在别人身上的，这人要从民中剪除。'),
('CUV', '出埃及记', 2, 30, 34, '耶和华吩咐摩西说：你要取馨香的香料，就是拿他弗、施喜列、喜利比拿；这馨香的香料和净乳香各样要一般大的分量。'),
('CUV', '出埃及记', 2, 30, 35, '你要用这些加上盐，按做香之法做成清净圣洁的香。'),
('CUV', '出埃及记', 2, 30, 36, '这香要取点捣得极细，放在会幕内、法柜前，我要在那里与你相会。你们要以这香为至圣。'),
('CUV', '出埃及记', 2, 30, 37, '你们不可按这调和之法为自己做香；要以这香为圣，归耶和华。'),
('CUV', '出埃及记', 2, 30, 38, '凡做香和这香一样，为要闻香味的，这人要从民中剪除。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 31, 1, '耶和华晓谕摩西说'),
('CUV', '出埃及记', 2, 31, 2, '看哪，犹大支派中，户珥的孙子、乌利的儿子比撒列，我已经题他的名召他。'),
('CUV', '出埃及记', 2, 31, 3, '我也以我的灵充满了他，使他有智慧，有聪明，有知识，能做各样的工，'),
('CUV', '出埃及记', 2, 31, 4, '能想出巧工，用金、银、铜制造各物，'),
('CUV', '出埃及记', 2, 31, 5, '又能刻宝石，可以镶嵌，能雕刻木头，能做各样的工。'),
('CUV', '出埃及记', 2, 31, 6, '我分派但支派中、亚希撒抹的儿子亚何利亚伯与他同工。凡心里有智慧的，我更使他们有智慧，能做我一切所吩咐的，'),
('CUV', '出埃及记', 2, 31, 7, '就是会幕和法柜，并其上的施恩座，与会幕中一切的器具，'),
('CUV', '出埃及记', 2, 31, 8, '桌子和桌子的器具，精金的灯台和灯台的一切器具并香坛，'),
('CUV', '出埃及记', 2, 31, 9, '燔祭坛和坛的一切器具，并洗濯盆与盆座，'),
('CUV', '出埃及记', 2, 31, 10, '精工做的礼服，和祭司亚伦并他儿子用以供祭司职分的圣衣，'),
('CUV', '出埃及记', 2, 31, 11, '膏油和为圣所用馨香的香料。他们都要照我一切所吩咐的去做。'),
('CUV', '出埃及记', 2, 31, 12, '耶和华晓谕摩西说：'),
('CUV', '出埃及记', 2, 31, 13, '你要吩咐以色列人说：你们务要守我的安息日；因为这是你我之间世世代代的证据，使你们知道我─耶和华是叫你们成为圣的。'),
('CUV', '出埃及记', 2, 31, 14, '所以你们要守安息日，以为圣日。凡干犯这日的，必要把他治死；凡在这日做工的，必从民中剪除。'),
('CUV', '出埃及记', 2, 31, 15, '六日要做工，但第七日是安息圣日，是向耶和华守为圣的。凡在安息日做工的，必要把他治死。'),
('CUV', '出埃及记', 2, 31, 16, '故此，以色列人要世世代代守安息日为永远的约。'),
('CUV', '出埃及记', 2, 31, 17, '这是我和以色列人永远的证据；因为六日之内耶和华造天地，第七日便安息舒畅。'),
('CUV', '出埃及记', 2, 31, 18, '耶和华在西乃山和摩西说完了话，就把两块法版交给他，是神用指头写的石版。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 32, 1, '百姓见摩西迟延不下山，就大家聚集到亚伦那里，对他说：起来！为我们做神像，可以在我们前面引路；因为领我们出埃及地的那个摩西，我们不知道他遭了甚么事。'),
('CUV', '出埃及记', 2, 32, 2, '亚伦对他们说：你们去摘下你们妻子、儿女耳上的金环，拿来给我。'),
('CUV', '出埃及记', 2, 32, 3, '百姓就都摘下他们耳上的金环，拿来给亚伦。'),
('CUV', '出埃及记', 2, 32, 4, '亚伦从他们手里接过来，铸了一只牛犊，用雕刻的器具做成。他们就说：以色列阿，这是领你出埃及地的神。'),
('CUV', '出埃及记', 2, 32, 5, '亚伦看见，就在牛犊面前筑坛，且宣告说：明日要向耶和华守节。'),
('CUV', '出埃及记', 2, 32, 6, '次日清早，百姓起来献燔祭和平安祭，就坐下吃喝，起来玩耍。'),
('CUV', '出埃及记', 2, 32, 7, '耶和华吩咐摩西说：下去罢，因为你的百姓，就是你从埃及地领出来的，已经败坏了。'),
('CUV', '出埃及记', 2, 32, 8, '他们快快偏离了我所吩咐的道，为自己铸了一只牛犊，向他下拜献祭，说：以色列阿，这就是领你出埃及地的神。'),
('CUV', '出埃及记', 2, 32, 9, '耶和华对摩西说：我看这百姓真是硬著颈项的百姓。'),
('CUV', '出埃及记', 2, 32, 10, '你且由著我，我要向他们发烈怒，将他们灭绝，使你的后裔成为大国。'),
('CUV', '出埃及记', 2, 32, 11, '摩西便恳求耶和华─他的神说：耶和华阿，你为甚么向你的百姓发烈怒呢？这百姓是你用大力和大能的手从埃及地领出来的。'),
('CUV', '出埃及记', 2, 32, 12, '为甚么使埃及人议论说他领他们出去，是要降祸与他们，把他们杀在山中，将他们从地上除灭？求你转意，不发你的烈怒，后悔，不降祸与你的百姓。'),
('CUV', '出埃及记', 2, 32, 13, '求你记念你的仆人亚伯拉罕、以撒、以色列。你曾指著自己起誓说：我必使你们的后裔像天上的星那样多，并且我所应许的这全地，必给你们的后裔，他们要永远承受为业。'),
('CUV', '出埃及记', 2, 32, 14, '于是耶和华后悔，不把所说的祸降与他的百姓。'),
('CUV', '出埃及记', 2, 32, 15, '摩西转身下山，手里拿著两块法版。这版是两面写的，这面那面都有字，'),
('CUV', '出埃及记', 2, 32, 16, '是神的工作，字是神写的，刻在版上。'),
('CUV', '出埃及记', 2, 32, 17, '约书亚一听见百姓呼喊的声音，就对摩西说：在营里有争战的声音。'),
('CUV', '出埃及记', 2, 32, 18, '摩西说：这不是人打胜仗的声音，也不是人打败仗的声音，我所听见的乃是人歌唱的声音。'),
('CUV', '出埃及记', 2, 32, 19, '摩西挨近营前就看见牛犊，又看见人跳舞，便发烈怒，把两块版扔在山下摔碎了，'),
('CUV', '出埃及记', 2, 32, 20, '又将他们所铸的牛犊用火焚烧，磨得粉碎，撒在水面上，叫以色列人喝。'),
('CUV', '出埃及记', 2, 32, 21, '摩西对亚伦说：这百姓向你做了甚么？你竟使他们陷在大罪里！'),
('CUV', '出埃及记', 2, 32, 22, '亚伦说：求我主不要发烈怒。这百姓专于作恶，是你知道的。'),
('CUV', '出埃及记', 2, 32, 23, '他们对我说：你为我们做神像，可以在我们前面引路；因为领我们出埃及地的那个摩西，我们不知道他遭了甚么事。'),
('CUV', '出埃及记', 2, 32, 24, '我对他们说：凡有金环的可以摘下来，他们就给了我。我把金环扔在火中，这牛犊便出来了。'),
('CUV', '出埃及记', 2, 32, 25, '摩西见百姓放肆（亚伦纵容他们，使他们在仇敌中间被讥刺），'),
('CUV', '出埃及记', 2, 32, 26, '就站在营门中，说：凡属耶和华的，都要到我这里来！于是利未的子孙都到他那里聚集。'),
('CUV', '出埃及记', 2, 32, 27, '他对他们说：耶和华─以色列的神这样说：你们各人把刀跨在腰间，在营中往来，从这门到那门，各人杀他的弟兄与同伴并邻舍。'),
('CUV', '出埃及记', 2, 32, 28, '利未的子孙照摩西的话行了。那一天百姓中被杀的约有三千。'),
('CUV', '出埃及记', 2, 32, 29, '摩西说：今天你们要自洁，归耶和华为圣，各人攻击他的儿子和弟兄，使耶和华赐福与你们。'),
('CUV', '出埃及记', 2, 32, 30, '到了第二天，摩西对百姓说：你们犯了大罪。我如今要上耶和华那里去，或者可以为你们赎罪。'),
('CUV', '出埃及记', 2, 32, 31, '摩西回到耶和华那里，说：唉！这百姓犯了大罪，为自己做了金像。'),
('CUV', '出埃及记', 2, 32, 32, '倘或你肯赦免他们的罪……不然，求你从你所写的册上涂抹我的名。'),
('CUV', '出埃及记', 2, 32, 33, '耶和华对摩西说：谁得罪我，我就从我的册上涂抹谁的名。'),
('CUV', '出埃及记', 2, 32, 34, '现在你去领这百姓，往我所告诉你的地方去，我的使者必在你前面引路；只是到我追讨的日子，我必追讨他们的罪。'),
('CUV', '出埃及记', 2, 32, 35, '耶和华杀百姓的缘故是因他们同亚伦做了牛犊。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 33, 1, '耶和华吩咐摩西说：我曾起誓应许亚伯拉罕、以撒、雅各说：要将迦南地赐给你的后裔。现在你和你从埃及地所领出来的百姓，要从这里往那地去。'),
('CUV', '出埃及记', 2, 33, 2, '我要差遣使者在你前面，撵出迦南人、亚摩利人、赫人、比利洗人、希未人、耶布斯人，'),
('CUV', '出埃及记', 2, 33, 3, '领你到那流奶与蜜之地。我自己不同你们上去；因为你们是硬著颈项的百姓，恐怕我在路上把你们灭绝。'),
('CUV', '出埃及记', 2, 33, 4, '百姓听见这凶信就悲哀，也没有人佩戴妆饰。'),
('CUV', '出埃及记', 2, 33, 5, '耶和华对摩西说：你告诉以色列人说：耶和华说：你们是硬著颈项的百姓，我若一霎时临到你们中间，必灭绝你们。现在你们要把身上的妆饰摘下来，使我可以知道怎样待你们'),
('CUV', '出埃及记', 2, 33, 6, '以色列人从住何烈山以后，就把身上的妆饰摘得干净。'),
('CUV', '出埃及记', 2, 33, 7, '摩西素常将帐棚支搭在营外，离营却远，他称这帐棚为会幕。凡求问耶和华的，就到营外的会幕那里去。'),
('CUV', '出埃及记', 2, 33, 8, '当摩西出营到会幕去的时候，百姓就都起来，各人站在自己帐棚的门口，望著摩西，直等到他进了会幕。'),
('CUV', '出埃及记', 2, 33, 9, '摩西进会幕的时候，云柱降下来，立在会幕的门前，耶和华便与摩西说话。'),
('CUV', '出埃及记', 2, 33, 10, '众百姓看见云柱立在会幕门前，就都起来，各人在自己帐棚的门口下拜。'),
('CUV', '出埃及记', 2, 33, 11, '耶和华与摩西面对面说话，好像人与朋友说话一般。摩西转到营里去，惟有他的帮手─一个少年人嫩的儿子约书亚不离开会幕。'),
('CUV', '出埃及记', 2, 33, 12, '摩西对耶和华说：你吩咐我说：将这百姓领上去，却没有叫我知道你要打发谁与我同去，只说：我按你的名认识你，你在我眼前也蒙了恩。'),
('CUV', '出埃及记', 2, 33, 13, '我如今若在你眼前蒙恩，求你将你的道指示我，使我可以认识你，好在你眼前蒙恩。求你想到这民是你的民。'),
('CUV', '出埃及记', 2, 33, 14, '耶和华说：我必亲自和你同去，使你得安息。'),
('CUV', '出埃及记', 2, 33, 15, '摩西说：你若不亲自和我同去，就不要把我们从这里领上去。'),
('CUV', '出埃及记', 2, 33, 16, '人在何事上得以知道我和你的百姓在你眼前蒙恩呢？岂不是因你与我们同去、使我和你的百姓与地上的万民有分别么？'),
('CUV', '出埃及记', 2, 33, 17, '耶和华对摩西说：你这所求的我也要行；因为你在我眼前蒙了恩，并且我按你的名认识你。'),
('CUV', '出埃及记', 2, 33, 18, '摩西说：求你显出你的荣耀给我看。'),
('CUV', '出埃及记', 2, 33, 19, '耶和华说：我要显我一切的恩慈，在你面前经过，宣告我的名。我要恩待谁就恩待谁；要怜悯谁就怜悯谁；'),
('CUV', '出埃及记', 2, 33, 20, '又说：你不能看见我的面，因为人见我的面不能存活。'),
('CUV', '出埃及记', 2, 33, 21, '耶和华说：看哪，在我这里有地方，你要站在磐石上。'),
('CUV', '出埃及记', 2, 33, 22, '我的荣耀经过的时候，我必将你放在磐石穴中，用我的手遮掩你，等我过去，'),
('CUV', '出埃及记', 2, 33, 23, '然后我要将我的手收回，你就得见我的背，却不得见我的面。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 34, 1, '耶和华吩咐摩西说：你要凿出两块石版，和先前你摔碎的那版一样；其上的字我要写在这版上。'),
('CUV', '出埃及记', 2, 34, 2, '明日早晨，你要预备好了，上西乃山，在山顶上站在我面前。'),
('CUV', '出埃及记', 2, 34, 3, '谁也不可和你一同上去，遍山都不可有人，在山根也不可叫羊群牛群吃草。'),
('CUV', '出埃及记', 2, 34, 4, '摩西就凿出两块石版，和先前的一样。清晨起来，照耶和华所吩咐的上西乃山去，手里拿著两块石版。'),
('CUV', '出埃及记', 2, 34, 5, '耶和华在云中降临，和摩西一同站在那里，宣告耶和华的名。'),
('CUV', '出埃及记', 2, 34, 6, '耶和华在他面前宣告说：耶和华，耶和华，是有怜悯有恩典的神，不轻易发怒，并有丰盛的慈爱和诚实，'),
('CUV', '出埃及记', 2, 34, 7, '为千万人存留慈爱，赦免罪孽、过犯，和罪恶，万不以有罪的为无罪，必追讨他的罪，自父及子，直到三、四代。'),
('CUV', '出埃及记', 2, 34, 8, '摩西急忙伏地下拜，'),
('CUV', '出埃及记', 2, 34, 9, '说：主阿，我若在你眼前蒙恩，求你在我们中间同行，因为这是硬著颈项的百姓。又求你赦免我们的罪孽和罪恶，以我们为你的产业。'),
('CUV', '出埃及记', 2, 34, 10, '耶和华说：我要立约，要在百姓面前行奇妙的事，是在遍地万国中所未曾行的。在你四围的外邦人就要看见耶和华的作为，因我向你所行的是可畏惧的事。'),
('CUV', '出埃及记', 2, 34, 11, '我今天所吩咐你的，你要谨守。我要从你面前撵出亚摩利人、迦南人、赫人、比利洗人、希未人、耶布斯人。'),
('CUV', '出埃及记', 2, 34, 12, '你要谨慎，不可与你所去那地的居民立约，恐怕成为你们中间的网罗；'),
('CUV', '出埃及记', 2, 34, 13, '却要拆毁他们的祭坛，打碎他们的柱像，砍下他们的木偶。'),
('CUV', '出埃及记', 2, 34, 14, '不可敬拜别神；因为耶和华是忌邪的神，名为忌邪者。'),
('CUV', '出埃及记', 2, 34, 15, '只怕你与那地的居民立约，百姓随从他们的神，就行邪淫，祭祀他们的神，有人叫你，你便吃他的祭物，'),
('CUV', '出埃及记', 2, 34, 16, '又为你的儿子娶他们的女儿为妻，他们的女儿随从他们的神，就行邪淫，使你的儿子也随从他们的神行邪淫。'),
('CUV', '出埃及记', 2, 34, 17, '不可为自己铸造神像。'),
('CUV', '出埃及记', 2, 34, 18, '你要守除酵节，照我所吩咐你的，在亚笔月内所定的日期吃无酵饼七天，因为你是这亚笔月内出了埃及。'),
('CUV', '出埃及记', 2, 34, 19, '凡头生的都是我的；一切牲畜头生的，无论是牛是羊，公的都是我的。'),
('CUV', '出埃及记', 2, 34, 20, '头生的驴要用羊羔代赎，若不代赎就要打折他的颈项。凡头生的儿子都要赎出来。谁也不可空手朝见我。'),
('CUV', '出埃及记', 2, 34, 21, '你六日要做工，第七日要安息，虽在耕种收割的时候也要安息。'),
('CUV', '出埃及记', 2, 34, 22, '在收割初熟麦子的时候要守七七节；又在年底要守收藏节。'),
('CUV', '出埃及记', 2, 34, 23, '你们一切男丁要一年三次朝见主耶和华─以色列的神。'),
('CUV', '出埃及记', 2, 34, 24, '我要从你面前赶出外邦人，扩张你的境界。你一年三次上去朝见耶和华─你神的时候，必没有人贪慕你的地土。'),
('CUV', '出埃及记', 2, 34, 25, '你不可将我祭物的血和有酵的饼一同献上。逾越节的祭物也不可留到早晨。'),
('CUV', '出埃及记', 2, 34, 26, '地里首先初熟之物要送到耶和华─你神的殿。不可用山羊羔母的奶煮山羊羔。'),
('CUV', '出埃及记', 2, 34, 27, '耶和华吩咐摩西说：你要将这些话写上，因为我是按这话与你和以色列人立约。'),
('CUV', '出埃及记', 2, 34, 28, '摩西在耶和华那里四十昼夜，也不吃饭也不喝水。耶和华将这约的话，就是十条诫，写在两块版上。'),
('CUV', '出埃及记', 2, 34, 29, '摩西手里拿著两块法版下西乃山的时候，不知道自己的面皮因耶和华和他说话就发了光。'),
('CUV', '出埃及记', 2, 34, 30, '亚伦和以色列众人看见摩西的面皮发光就怕挨近他。'),
('CUV', '出埃及记', 2, 34, 31, '摩西叫他们来；于是亚伦和会众的官长都到他那里去，摩西就与他们说话。'),
('CUV', '出埃及记', 2, 34, 32, '随后以色列众人都近前来，他就把耶和华在西乃山与他所说的一切话都吩咐他们。'),
('CUV', '出埃及记', 2, 34, 33, '摩西与他们说完了话就用帕子蒙上脸。'),
('CUV', '出埃及记', 2, 34, 34, '但摩西进到耶和华面前与他说话就揭去帕子，及至出来的时候便将耶和华所吩咐的告诉以色列人。'),
('CUV', '出埃及记', 2, 34, 35, '以色列人看见摩西的面皮发光。摩西又用帕子蒙上脸，等到他进去与耶和华说话就揭去帕子。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 35, 1, '摩西招聚以色列全会众，对他们说：这是耶和华所吩咐的话，叫你们照著行：'),
('CUV', '出埃及记', 2, 35, 2, '六日要做工，第七日乃为圣日，当向耶和华守为安息圣日。凡这日之内做工的，必把他治死。'),
('CUV', '出埃及记', 2, 35, 3, '当安息日，不可在你们一切的住处生火。'),
('CUV', '出埃及记', 2, 35, 4, '摩西对以色列全会众说：耶和华所吩咐的是这样：'),
('CUV', '出埃及记', 2, 35, 5, '你们中间要拿礼物献给耶和华，凡乐意献的可以拿耶和华的礼物来，就是金、银、铜，'),
('CUV', '出埃及记', 2, 35, 6, '蓝色、紫色、朱红色线，细麻，山羊毛，'),
('CUV', '出埃及记', 2, 35, 7, '染红的公羊皮，海狗皮，皂荚木，'),
('CUV', '出埃及记', 2, 35, 8, '点灯的油，并做膏油和香的香料，'),
('CUV', '出埃及记', 2, 35, 9, '红玛瑙与别样的宝石，可以镶嵌在以弗得和胸牌上'),
('CUV', '出埃及记', 2, 35, 10, '你们中间凡心里有智慧的都要来做耶和华一切所吩咐的：'),
('CUV', '出埃及记', 2, 35, 11, '就是帐幕和帐幕的罩棚，并帐幕的盖、钩子、板、闩、柱子、带卯的座，'),
('CUV', '出埃及记', 2, 35, 12, '柜和柜的杠，施恩座和遮掩柜的幔子，'),
('CUV', '出埃及记', 2, 35, 13, '桌子和桌子的杠与桌子的一切器具，并陈设饼，'),
('CUV', '出埃及记', 2, 35, 14, '灯台和灯台的器具，灯盏并点灯的油，'),
('CUV', '出埃及记', 2, 35, 15, '香坛和坛的杠，膏油和馨香的香料，并帐幕门口的帘子，'),
('CUV', '出埃及记', 2, 35, 16, '燔祭坛和坛的铜网，坛的杠并坛的一切器具，洗濯盆和盆座，'),
('CUV', '出埃及记', 2, 35, 17, '院子的帷子和帷子的柱子，带卯的座和院子的门帘，'),
('CUV', '出埃及记', 2, 35, 18, '帐幕的橛子并院子的橛子，和这两处的绳子，'),
('CUV', '出埃及记', 2, 35, 19, '精工做的礼服和祭司亚伦并他儿子在圣所用以供祭司职分的圣衣。'),
('CUV', '出埃及记', 2, 35, 20, '以色列全会众从摩西面前退去。'),
('CUV', '出埃及记', 2, 35, 21, '凡心里受感和甘心乐意的都拿耶和华的礼物来，用以做会幕和其中一切的使用，又用以做圣衣。'),
('CUV', '出埃及记', 2, 35, 22, '凡心里乐意献礼物的，连男带女，各将金器，就是胸前针、耳环（或作：鼻环）、打印的戒指，和手钏带来献给耶和华。'),
('CUV', '出埃及记', 2, 35, 23, '凡有蓝色、紫色、朱红色线，细麻，山羊毛，染红的公羊皮，海狗皮的，都拿了来；'),
('CUV', '出埃及记', 2, 35, 24, '凡献银子和铜给耶和华为礼物的都拿了来；凡有皂荚木可做甚么使用的也拿了来。'),
('CUV', '出埃及记', 2, 35, 25, '凡心中有智慧的妇女亲手纺线，把所纺的蓝色、紫色、朱红色线，和细麻都拿了来。'),
('CUV', '出埃及记', 2, 35, 26, '凡有智慧、心里受感的妇女就纺山羊毛。'),
('CUV', '出埃及记', 2, 35, 27, '众官长把红玛瑙和别样的宝石，可以镶嵌在以弗得与胸牌上的，都拿了来；'),
('CUV', '出埃及记', 2, 35, 28, '又拿香料做香，拿油点灯，做膏油。'),
('CUV', '出埃及记', 2, 35, 29, '以色列人，无论男女，凡甘心乐意献礼物给耶和华的，都将礼物拿来，做耶和华藉摩西所吩咐的一切工。'),
('CUV', '出埃及记', 2, 35, 30, '摩西对以色列人说：犹大支派中，户珥的孙子、乌利的儿子比撒列，耶和华已经题他的名召他，'),
('CUV', '出埃及记', 2, 35, 31, '又以神的灵充满了他，使他有智慧、聪明、知识，能做各样的工，'),
('CUV', '出埃及记', 2, 35, 32, '能想出巧工，用金、银、铜制造各物，'),
('CUV', '出埃及记', 2, 35, 33, '又能刻宝石，可以镶嵌，能雕刻木头，能做各样的巧工。'),
('CUV', '出埃及记', 2, 35, 34, '耶和华又使他，和但支派中亚希撒抹的儿子亚何利亚伯，心里灵明，能教导人。'),
('CUV', '出埃及记', 2, 35, 35, '耶和华使他们的心满有智慧，能做各样的工，无论是雕刻的工，巧匠的工，用蓝色、紫色、朱红色线，和细麻、绣花的工，并机匠的工，他们都能做，也能想出奇巧的工。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 36, 1, '比撒列和亚何利亚伯，并一切心里有智慧的，就是蒙耶和华赐智慧聪明、叫他知道做圣所各样使用之工的，都要照耶和华所吩咐的做工。'),
('CUV', '出埃及记', 2, 36, 2, '凡耶和华赐他心里有智慧、而且受感前来做这工的，摩西把他们和比撒列并亚何利亚伯一同召来。'),
('CUV', '出埃及记', 2, 36, 3, '这些人就从摩西收了以色列人为做圣所并圣所使用之工所拿来的礼物。百姓每早晨还把甘心献的礼物拿来。'),
('CUV', '出埃及记', 2, 36, 4, '凡做圣所一切工的智慧人各都离开他所作的工，'),
('CUV', '出埃及记', 2, 36, 5, '来对摩西说：百姓为耶和华吩咐使用之工所拿来的，富富有余。'),
('CUV', '出埃及记', 2, 36, 6, '摩西传命，他们就在全营中宣告说：无论男女，不必再为圣所拿甚么礼物来。这样才拦住百姓不再拿礼物来。'),
('CUV', '出埃及记', 2, 36, 7, '因为他们所有的材料够做一切当做的物，而且有余。'),
('CUV', '出埃及记', 2, 36, 8, '他们中间，凡心里有智慧做工的，用十幅幔子做帐幕。这幔子是比撒列用撚的细麻和蓝色、紫色、朱红色线制造的，并用巧匠的手工绣上基路伯。'),
('CUV', '出埃及记', 2, 36, 9, '每幅幔子长二十八肘，宽四肘，都是一样的尺寸。'),
('CUV', '出埃及记', 2, 36, 10, '他使这五幅幔子幅幅相连，又使那五幅幔子幅幅相连；'),
('CUV', '出埃及记', 2, 36, 11, '在这相连的幔子末幅边上做蓝色的钮扣，在那相连的幔子末幅边上也照样做；'),
('CUV', '出埃及记', 2, 36, 12, '在这相连的幔子上做五十个钮扣，在那相连的幔子上也做五十个钮扣，都是两两相对；'),
('CUV', '出埃及记', 2, 36, 13, '又做五十个金钩，使幔子相连。这才成了一个帐幕。'),
('CUV', '出埃及记', 2, 36, 14, '他用山羊毛织十一幅幔子，作为帐幕以上的罩棚。'),
('CUV', '出埃及记', 2, 36, 15, '每幅幔子长三十肘，宽四肘；十一幅幔子都是一样的尺寸。'),
('CUV', '出埃及记', 2, 36, 16, '他把五幅幔子连成一幅，又把六幅幔子连成一幅；'),
('CUV', '出埃及记', 2, 36, 17, '在这相连的幔子末幅边上做五十个钮扣，在那相连的幔子末幅边上也做五十个钮扣；'),
('CUV', '出埃及记', 2, 36, 18, '又做五十个铜钩，使罩棚连成一个；'),
('CUV', '出埃及记', 2, 36, 19, '并用染红的公羊皮做罩棚的盖，再用海狗皮做一层罩棚上的顶盖。'),
('CUV', '出埃及记', 2, 36, 20, '他用皂荚木做帐幕的竖板。'),
('CUV', '出埃及记', 2, 36, 21, '每块长十肘，宽一肘半；'),
('CUV', '出埃及记', 2, 36, 22, '每块有两榫相对。帐幕一切的板都是这样做。'),
('CUV', '出埃及记', 2, 36, 23, '帐幕的南面做板二十块。'),
('CUV', '出埃及记', 2, 36, 24, '在这二十块板底下又做四十个带卯的银座：两卯接这块板上的两榫，两卯接那块板上的两榫。'),
('CUV', '出埃及记', 2, 36, 25, '帐幕的第二面，就是北面，也做板二十块'),
('CUV', '出埃及记', 2, 36, 26, '和带卯的银座四十个：这板底下有两卯，那板底下也有两卯。'),
('CUV', '出埃及记', 2, 36, 27, '帐幕的后面，就是西面，做板六块。'),
('CUV', '出埃及记', 2, 36, 28, '帐幕后面的拐角做板两块。'),
('CUV', '出埃及记', 2, 36, 29, '板的下半截是双的，上半截是整的，直到第一个环子；在帐幕的两个拐角上都是这样做。'),
('CUV', '出埃及记', 2, 36, 30, '有八块板和十六个带卯的银座，每块板底下有两卯。'),
('CUV', '出埃及记', 2, 36, 31, '他用皂荚木做闩：为帐幕这面的板做五闩，'),
('CUV', '出埃及记', 2, 36, 32, '为帐幕那面的板做五闩，又为帐幕后面的板做五闩，'),
('CUV', '出埃及记', 2, 36, 33, '使板腰间的中闩从这一头通到那一头。'),
('CUV', '出埃及记', 2, 36, 34, '用金子将板包裹，又做板上的金环套闩；闩也用金子包裹。'),
('CUV', '出埃及记', 2, 36, 35, '他用蓝色、紫色、朱红色线，和撚的细麻织幔子，以巧匠的手工绣上基路伯。'),
('CUV', '出埃及记', 2, 36, 36, '为幔子做四根皂荚木柱子，用金包裹，柱子上有金钩，又为柱子铸了四个带卯的银座。'),
('CUV', '出埃及记', 2, 36, 37, '拿蓝色、紫色、朱红色线，和撚的细麻，用绣花的手工织帐幕的门帘；'),
('CUV', '出埃及记', 2, 36, 38, '又为帘子做五根柱子和柱子上的钩子，用金子把柱顶和柱子上的杆子包裹。柱子有五个带卯的座，是铜的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 37, 1, '比撒列用皂荚木做柜，长二肘半，宽一肘半，高一肘半。'),
('CUV', '出埃及记', 2, 37, 2, '里外包上精金，四围镶上金牙边，'),
('CUV', '出埃及记', 2, 37, 3, '又铸四个金环，安在柜的四脚上：这边两环，那边两环。'),
('CUV', '出埃及记', 2, 37, 4, '用皂荚木做两根杠，用金包裹。'),
('CUV', '出埃及记', 2, 37, 5, '把杠穿在柜旁的环内，以便抬柜。'),
('CUV', '出埃及记', 2, 37, 6, '用精金做施恩座，长二肘半，宽一肘半。'),
('CUV', '出埃及记', 2, 37, 7, '用金子锤出两个基路伯来，安在施恩座的两头，'),
('CUV', '出埃及记', 2, 37, 8, '这头做一个基路伯，那头做一个基路伯，二基路伯接连一块，在施恩座的两头。'),
('CUV', '出埃及记', 2, 37, 9, '二基路伯高张翅膀，遮掩施恩座；基路伯是脸对脸，朝著施恩座。'),
('CUV', '出埃及记', 2, 37, 10, '他用皂荚木做一张桌子，长二肘，宽一肘，高一肘半，'),
('CUV', '出埃及记', 2, 37, 11, '又包上精金，四围镶上金牙边。'),
('CUV', '出埃及记', 2, 37, 12, '桌子的四围各做一掌宽的横梁，横梁上镶著金牙边，'),
('CUV', '出埃及记', 2, 37, 13, '又铸了四个金环，安在桌子四脚的四角上。'),
('CUV', '出埃及记', 2, 37, 14, '安环子的地方是挨近横梁，可以穿杠抬桌子。'),
('CUV', '出埃及记', 2, 37, 15, '他用皂荚木做两根杠，用金包裹，以便抬桌子；'),
('CUV', '出埃及记', 2, 37, 16, '又用精金做桌子上的器皿，就是盘子、调羹，并奠酒的瓶和爵。'),
('CUV', '出埃及记', 2, 37, 17, '他用精金做一个灯台；这灯台的座和干，与杯、球、花，都是接连一块锤出来的。'),
('CUV', '出埃及记', 2, 37, 18, '灯台两旁杈出六个枝子：这旁三个，那旁三个。'),
('CUV', '出埃及记', 2, 37, 19, '这旁每枝上有三个杯，形状像杏花，有球有花；那旁每枝上也有三个杯，形状像杏花，有球有花。从灯台杈出来的六个枝子都是如此。'),
('CUV', '出埃及记', 2, 37, 20, '灯台上有四个杯，形状像杏花，有球有花。'),
('CUV', '出埃及记', 2, 37, 21, '灯台每两个枝子以下有球，与枝子接连一块；灯台杈出的六个枝子都是如此。'),
('CUV', '出埃及记', 2, 37, 22, '球和枝子是接连一块，都是一块精金锤出来的。'),
('CUV', '出埃及记', 2, 37, 23, '用精金做灯台的七个灯盏，并灯台的蜡剪和蜡花盘。'),
('CUV', '出埃及记', 2, 37, 24, '他用精金一他连得做灯台和灯台的一切器具。'),
('CUV', '出埃及记', 2, 37, 25, '他用皂荚木做香坛，是四方的，长一肘，宽一肘，高二肘，坛的四角与坛接连一块；'),
('CUV', '出埃及记', 2, 37, 26, '又用精金把坛的上面与坛的四面并坛的四角包裹，又在坛的四围镶上金牙边。'),
('CUV', '出埃及记', 2, 37, 27, '做两个金环，安在牙子边以下，在坛的两旁、两根横撑上，作为穿杠的用处，以便抬坛。'),
('CUV', '出埃及记', 2, 37, 28, '用皂荚木做杠，用金包裹。'),
('CUV', '出埃及记', 2, 37, 29, '又按做香之法做圣膏油和馨香料的净香。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 38, 1, '他用皂荚木做燔祭坛，是四方的，长五肘，宽五肘，高三肘，'),
('CUV', '出埃及记', 2, 38, 2, '在坛的四拐角上做四个角，与坛接连一块，用铜把坛包裹。'),
('CUV', '出埃及记', 2, 38, 3, '他做坛上的盆、铲子、盘子、肉锸子、火鼎；这一切器具都是用铜做的。'),
('CUV', '出埃及记', 2, 38, 4, '又为坛做一个铜网，安在坛四面的围腰板以下，从下达到坛的半腰。'),
('CUV', '出埃及记', 2, 38, 5, '为铜网的四角铸四个环子，作为穿杠的用处。'),
('CUV', '出埃及记', 2, 38, 6, '用皂荚木做杠，用铜包裹，'),
('CUV', '出埃及记', 2, 38, 7, '把杠穿在坛两旁的环子内，用以抬坛，并用板做坛；坛是空的。'),
('CUV', '出埃及记', 2, 38, 8, '他用铜做洗濯盆和盆座，是用会幕门前伺候的妇人之镜子作的。'),
('CUV', '出埃及记', 2, 38, 9, '他做帐幕的院子。院子的南面用撚的细麻做帷子，宽一百肘。'),
('CUV', '出埃及记', 2, 38, 10, '帷子的柱子二十根，带卯的铜座二十个；柱子上的钩子和杆子都是用银子做的。'),
('CUV', '出埃及记', 2, 38, 11, '北面也有帷子，宽一百肘。帷子的柱子二十根，带卯的铜座二十个；柱子上的钩子和杆子都是用银子做的。'),
('CUV', '出埃及记', 2, 38, 12, '院子的西面有帷子，宽五十肘。帷子的柱子十根，带卯的座十个；柱子的钩子和杆子都是用银子做的。'),
('CUV', '出埃及记', 2, 38, 13, '院子的东面，宽五十肘。'),
('CUV', '出埃及记', 2, 38, 14, '门这边的帷子十五肘，那边也是一样。帷子的柱子三根，带卯的座三个。在门的左右各有帷子十五肘，帷子的柱子三根，带卯的座三个。'),
('CUV', '出埃及记', 2, 38, 15, 'a'),
('CUV', '出埃及记', 2, 38, 16, '院子四面的帷子都是用撚的细麻做的。'),
('CUV', '出埃及记', 2, 38, 17, '柱子带卯的座是铜的，柱子上的钩子和杆子是银的，柱顶是用银子包的。院子一切的柱子都是用银杆连络的。'),
('CUV', '出埃及记', 2, 38, 18, '院子的门帘是以绣花的手工，用蓝色、紫色、朱红色线，和撚的细麻织的，宽二十肘，高五肘，与院子的帷子相配。'),
('CUV', '出埃及记', 2, 38, 19, '帷子的柱子四根，带卯的铜座四个；柱子上的钩子和杆子是银的；柱顶是用银子包的。'),
('CUV', '出埃及记', 2, 38, 20, '帐幕一切的橛子和院子四围的橛子都是铜的。'),
('CUV', '出埃及记', 2, 38, 21, '这是法柜的帐幕中利未人所用物件的总数，是照摩西的吩咐，经祭司亚伦的儿子以他玛的手数点的。'),
('CUV', '出埃及记', 2, 38, 22, '凡耶和华所吩咐摩西的都是犹大支派户珥的孙子、乌利的儿子比撒列做的。'),
('CUV', '出埃及记', 2, 38, 23, '与他同工的有但支派中亚希撒抹的儿子亚何利亚伯；他是雕刻匠，又是巧匠，又能用蓝色、紫色、朱红色线，和细麻绣花。'),
('CUV', '出埃及记', 2, 38, 24, '为圣所一切工作使用所献的金子，按圣所的平，有二十九他连得并七百三十舍客勒。'),
('CUV', '出埃及记', 2, 38, 25, '会中被数的人所出的银子，按圣所的平，有一百他连得并一千七百七十五舍客勒。'),
('CUV', '出埃及记', 2, 38, 26, '凡过去归那些被数之人的，从二十岁以外，有六十万零三千五百五十人。按圣所的平，每人出银半舍客勒，就是一比加。'),
('CUV', '出埃及记', 2, 38, 27, '用那一百他连得银子铸造圣所带卯的座和幔子柱子带卯的座；一百他连得共一百带卯的座，每带卯的座用一他连得。'),
('CUV', '出埃及记', 2, 38, 28, '用那一千七百七十五舍客勒银子做柱子上的钩子，包裹柱顶并柱子上的杆子。'),
('CUV', '出埃及记', 2, 38, 29, '所献的铜有七十他连得并二千四百舍客勒。'),
('CUV', '出埃及记', 2, 38, 30, '用这铜做会幕门带卯的座和铜坛，并坛上的铜网和坛的一切器具，'),
('CUV', '出埃及记', 2, 38, 31, '并院子四围带卯的座和院门带卯的座，与帐幕一切的橛子和院子四围所有的橛子。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 39, 1, '比撒列用蓝色、紫色、朱红色线做精致的衣服，在圣所用以供职，又为亚伦做圣衣，是照耶和华所吩咐摩西的。'),
('CUV', '出埃及记', 2, 39, 2, '他用金线和蓝色、紫色、朱红色线，并撚的细麻做以弗得；'),
('CUV', '出埃及记', 2, 39, 3, '把金子锤成薄片，剪出线来，与蓝色、紫色、朱红色线，用巧匠的手工一同绣上。'),
('CUV', '出埃及记', 2, 39, 4, '又为以弗得做两条相连的肩带，接连在以弗得的两头。'),
('CUV', '出埃及记', 2, 39, 5, '其上巧工织的带子和以弗得一样的做法，用以束上，与以弗得接连一块，是用金线和蓝色、紫色、朱红色线，并撚的细麻做的，是照耶和华所吩咐摩西的。'),
('CUV', '出埃及记', 2, 39, 6, '又琢出两块红玛瑙，镶在金槽上，仿佛刻图书，按著以色列儿子的名字雕刻；'),
('CUV', '出埃及记', 2, 39, 7, '将这两块宝石安在以弗得的两条肩带上，为以色列人做纪念石，是照耶和华所吩咐摩西的。'),
('CUV', '出埃及记', 2, 39, 8, '他用巧匠的手工做胸牌，和以弗得一样的做法，用金线与蓝色、紫色、朱红色线，并撚的细麻做的。'),
('CUV', '出埃及记', 2, 39, 9, '胸牌是四方的，叠为两层；这两层长一虎口，宽一虎口，'),
('CUV', '出埃及记', 2, 39, 10, '上面镶著宝石四行：第一行是红宝石、红璧玺、红玉；'),
('CUV', '出埃及记', 2, 39, 11, '第二行是绿宝石、蓝宝石、金钢石；'),
('CUV', '出埃及记', 2, 39, 12, '第三行是紫玛瑙、白玛瑙、紫晶；'),
('CUV', '出埃及记', 2, 39, 13, '第四行是水苍玉、红玛瑙、碧玉。这都镶在金槽中。'),
('CUV', '出埃及记', 2, 39, 14, '这些宝石都是按著以色列十二个儿子的名字，仿佛刻图书，刻十二个支派的名字。'),
('CUV', '出埃及记', 2, 39, 15, '在胸牌上，用精金拧成如绳子的链子。'),
('CUV', '出埃及记', 2, 39, 16, '又做两个金槽和两个金环，安在胸牌的两头。'),
('CUV', '出埃及记', 2, 39, 17, '把那两条拧成的金链子穿过胸牌两头的环子，'),
('CUV', '出埃及记', 2, 39, 18, '又把链子的那两头接在两槽上，安在以弗得前面肩带上。'),
('CUV', '出埃及记', 2, 39, 19, '做两个金环，安在胸牌的两头，在以弗得里面的边上，'),
('CUV', '出埃及记', 2, 39, 20, '又做两个金环，安在以弗得前面两条肩带的下边，挨近相接之处，在以弗得巧工织的带子以上。'),
('CUV', '出埃及记', 2, 39, 21, '用一条蓝细带子把胸牌的环子和以弗得的环子系住，使胸牌贴在以弗得巧工织的带子上，不可与以弗得离缝，是照耶和华所吩咐摩西的。'),
('CUV', '出埃及记', 2, 39, 22, '他用织工做以弗得的外袍，颜色全是蓝的。'),
('CUV', '出埃及记', 2, 39, 23, '袍上留一领口，口的周围织出领边来，仿佛铠甲的领口，免得破裂。'),
('CUV', '出埃及记', 2, 39, 24, '在袍子底边上，用蓝色、紫色、朱红色线，并撚的细麻做石榴，'),
('CUV', '出埃及记', 2, 39, 25, '又用精金做铃铛，把铃铛钉在袍子周围底边上的石榴中间：'),
('CUV', '出埃及记', 2, 39, 26, '一个铃铛一个石榴，一个铃铛一个石榴，在袍子周围底边上用以供职，是照耶和华所吩咐摩西的。'),
('CUV', '出埃及记', 2, 39, 27, '他用织成的细麻布为亚伦和他的儿子做内袍，'),
('CUV', '出埃及记', 2, 39, 28, '并用细麻布做冠冕和华美的裹头巾，用撚的细麻布做裤子，'),
('CUV', '出埃及记', 2, 39, 29, '又用蓝色、紫色、朱红色线，并撚的细麻，以绣花的手工做腰带，是照耶和华所吩咐摩西的。'),
('CUV', '出埃及记', 2, 39, 30, '他用精金做圣冠上的牌，在上面按刻图书之法，刻著归耶和华为圣。'),
('CUV', '出埃及记', 2, 39, 31, '又用一条蓝细带子将牌系在冠冕上，是照耶和华所吩咐摩西的。'),
('CUV', '出埃及记', 2, 39, 32, '帐幕，就是会幕，一切的工就这样做完了。凡耶和华所吩咐摩西的，以色列人都照样作了。'),
('CUV', '出埃及记', 2, 39, 33, '他们送到摩西那里。帐幕和帐幕的一切器具，就是钩子、板、闩、柱子、带卯的座，'),
('CUV', '出埃及记', 2, 39, 34, '染红公羊皮的盖、海狗皮的顶盖，和遮掩柜的幔子，'),
('CUV', '出埃及记', 2, 39, 35, '法柜和柜的杠并施恩座，'),
('CUV', '出埃及记', 2, 39, 36, '桌子和桌子的一切器具并陈设饼，'),
('CUV', '出埃及记', 2, 39, 37, '精金的灯台和摆列的灯盏，与灯台的一切器具，并点灯的油，'),
('CUV', '出埃及记', 2, 39, 38, '金坛、膏油、馨香的香料、会幕的门帘，'),
('CUV', '出埃及记', 2, 39, 39, '铜坛和坛上的铜网，坛的杠并坛的一切器具，洗濯盆和盆座，'),
('CUV', '出埃及记', 2, 39, 40, '院子的帷子和柱子，并带卯的座，院子的门帘、绳子、橛子，并帐幕和会幕中一切使用的器具，'),
('CUV', '出埃及记', 2, 39, 41, '精工做的礼服，和祭司亚伦并他儿子在圣所用以供祭司职分的圣衣。'),
('CUV', '出埃及记', 2, 39, 42, '这一切工作都是以色列人照耶和华所吩咐摩西做的。'),
('CUV', '出埃及记', 2, 39, 43, '耶和华怎样吩咐的，他们就怎样做了。摩西看见一切的工都做成了，就给他们祝福。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '出埃及记', 2, 40, 1, '耶和华晓谕摩西说：'),
('CUV', '出埃及记', 2, 40, 2, '正月初一日，你要立起帐幕，'),
('CUV', '出埃及记', 2, 40, 3, '把法柜安放在里面，用幔子将柜遮掩。'),
('CUV', '出埃及记', 2, 40, 4, '把桌子搬进去，摆设上面的物。把灯台搬进去，点其上的灯。'),
('CUV', '出埃及记', 2, 40, 5, '把烧香的金坛安在法柜前，挂上帐幕的门帘。'),
('CUV', '出埃及记', 2, 40, 6, '把燔祭坛安在帐幕门前。'),
('CUV', '出埃及记', 2, 40, 7, '把洗濯盆安在会幕和坛的中间，在盆里盛水。'),
('CUV', '出埃及记', 2, 40, 8, '又在四围立院帷，把院子的门帘挂上。'),
('CUV', '出埃及记', 2, 40, 9, '用膏油把帐幕和其中所有的都抹上，使帐幕和一切器具成圣，就都成圣。'),
('CUV', '出埃及记', 2, 40, 10, '又要抹燔祭坛和一切器具，使坛成圣，就都成为至圣。'),
('CUV', '出埃及记', 2, 40, 11, '要抹洗濯盆和盆座，使盆成圣。'),
('CUV', '出埃及记', 2, 40, 12, '要使亚伦和他儿子到会幕门口来，用水洗身。'),
('CUV', '出埃及记', 2, 40, 13, '要给亚伦穿上圣衣，又膏他，使他成圣，可以给我供祭司的职分；'),
('CUV', '出埃及记', 2, 40, 14, '又要使他儿子来，给他们穿上内袍。'),
('CUV', '出埃及记', 2, 40, 15, '怎样膏他们的父亲，也要照样膏他们，使他们给我供祭司的职分。他们世世代代凡受膏的，就永远当祭司的职任。'),
('CUV', '出埃及记', 2, 40, 16, '摩西这样行，都是照耶和华所吩咐他的。'),
('CUV', '出埃及记', 2, 40, 17, '第二年正月初一日，帐幕就立起来。'),
('CUV', '出埃及记', 2, 40, 18, '摩西立起帐幕，安上带卯的座，立上板，穿上闩，立起柱子。'),
('CUV', '出埃及记', 2, 40, 19, '在帐幕以上搭罩棚，把罩棚的顶盖盖在其上，是照耶和华所吩咐他的。'),
('CUV', '出埃及记', 2, 40, 20, '又把法版放在柜里，把杠穿在柜的两旁，把施恩座安在柜上。'),
('CUV', '出埃及记', 2, 40, 21, '把柜抬进帐幕，挂上遮掩柜的幔子，把法柜遮掩了，是照耶和华所吩咐他的。'),
('CUV', '出埃及记', 2, 40, 22, '又把桌子安在会幕内，在帐幕北边，在幔子外。'),
('CUV', '出埃及记', 2, 40, 23, '在桌子上将饼陈设在耶和华面前，是照耶和华所吩咐他的'),
('CUV', '出埃及记', 2, 40, 24, '又把灯台安在会幕内，在帐幕南边，与桌子相对，'),
('CUV', '出埃及记', 2, 40, 25, '在耶和华面前点灯，是照耶和华所吩咐他的。'),
('CUV', '出埃及记', 2, 40, 26, '把金坛安在会幕内的幔子前，'),
('CUV', '出埃及记', 2, 40, 27, '在坛上烧了馨香料做的香，是照耶和华所吩咐他的。'),
('CUV', '出埃及记', 2, 40, 28, '又挂上帐幕的门帘。'),
('CUV', '出埃及记', 2, 40, 29, '在会幕的帐幕门前，安设燔祭坛，把燔祭和素祭献在其上，是照耶和华所吩咐他的。'),
('CUV', '出埃及记', 2, 40, 30, '把洗濯盆安在会幕和坛的中间，盆中盛水，以便洗濯。'),
('CUV', '出埃及记', 2, 40, 31, '摩西和亚伦并亚伦的儿子在这盆里洗手洗脚。'),
('CUV', '出埃及记', 2, 40, 32, '他们进会幕或就近坛的时候，便都洗濯，是照耶和华所吩咐他的。'),
('CUV', '出埃及记', 2, 40, 33, '在帐幕和坛的四围立了院帷，把院子的门帘挂上。这样，摩西就完了工。'),
('CUV', '出埃及记', 2, 40, 34, '当时，云彩遮盖会幕，耶和华的荣光就充满了帐幕。'),
('CUV', '出埃及记', 2, 40, 35, '摩西不能进会幕；因为云彩停在其上，并且耶和华的荣光充满了帐幕。'),
('CUV', '出埃及记', 2, 40, 36, '每逢云彩从帐幕收上去，以色列人就起程前往；'),
('CUV', '出埃及记', 2, 40, 37, '云彩若不收上去，他们就不起程，直等到云彩收上去。'),
('CUV', '出埃及记', 2, 40, 38, '日间，耶和华的云彩是在帐幕以上；夜间，云中有火，在以色列全家的眼前。在他们所行的路上都是这样。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 1, 1, '耶和华从会幕中呼叫摩西，对他说：'),
('CUV', '利未记', 3, 1, 2, '你晓谕以色列人说：你们中间若有人献供物给耶和华，要从牛群羊群中献牲畜为供物。'),
('CUV', '利未记', 3, 1, 3, '他的供物若以牛为燔祭，就要在会幕门口献一只没有残疾的公牛，可以在耶和华面前蒙悦纳。'),
('CUV', '利未记', 3, 1, 4, '他要按手在燔祭牲的头上，燔祭便蒙悦纳，为他赎罪。'),
('CUV', '利未记', 3, 1, 5, '他要在耶和华面前宰公牛；亚伦子孙作祭司的，要奉上血，把血洒在会幕门口、坛的周围。'),
('CUV', '利未记', 3, 1, 6, '那人要剥去燔祭牲的皮，把燔祭牲切成块子。'),
('CUV', '利未记', 3, 1, 7, '祭司亚伦的子孙要把火放在坛上，把柴摆在火上。'),
('CUV', '利未记', 3, 1, 8, '亚伦子孙作祭司的，要把肉块和头并脂油摆在坛上火的柴上。'),
('CUV', '利未记', 3, 1, 9, '但燔祭的脏腑与腿要用水洗。祭司就要把一切全烧在坛上，当作燔祭，献与耶和华为馨香的火祭。'),
('CUV', '利未记', 3, 1, 10, '人的供物若以绵羊或山羊为燔祭，就要献上没有残疾的公羊。'),
('CUV', '利未记', 3, 1, 11, '要把羊宰于坛的北边，在耶和华面前；亚伦子孙作祭司的，要把羊血洒在坛的周围。'),
('CUV', '利未记', 3, 1, 12, '要把燔祭牲切成块子，连头和脂油，祭司就要摆在坛上火的柴上；'),
('CUV', '利未记', 3, 1, 13, '但脏腑与腿要用水洗，祭司就要全然奉献，烧在坛上。这是燔祭，是献与耶和华为馨香的火祭。'),
('CUV', '利未记', 3, 1, 14, '人奉给耶和华的供物，若以鸟为燔祭，就要献斑鸠或是雏鸽为供物。'),
('CUV', '利未记', 3, 1, 15, '祭司要把鸟拿到坛前，揪下头来，把鸟烧在坛上；鸟的血要流在坛的旁边；'),
('CUV', '利未记', 3, 1, 16, '又要把鸟的嗉子和脏物除掉，（脏物：或作翎毛）丢在坛的东边倒灰的地方。'),
('CUV', '利未记', 3, 1, 17, '要拿著鸟的两个翅膀，把鸟撕开，只是不可撕断；祭司要在坛上、在火的柴上焚烧。这是燔祭，是献与耶和华为馨香的火祭。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 2, 1, '若有人献素祭为供物给耶和华，要用细面浇上油，加上乳香，'),
('CUV', '利未记', 3, 2, 2, '带到亚伦子孙作祭司的那里；祭司就要从细面中取出一把来，并取些油和所有的乳香，然后要把所取的这些作为纪念，烧在坛上，是献与耶和华为馨香的火祭。'),
('CUV', '利未记', 3, 2, 3, '素祭所剩的要归给亚伦和他的子孙；这是献与耶和华的火祭中为至圣的。'),
('CUV', '利未记', 3, 2, 4, '若用炉中烤的物为素祭，就要用调油的无酵细面饼，或是抹油的无酵薄饼。'),
('CUV', '利未记', 3, 2, 5, '若用铁鏊上做的物为素祭，就要用调油的无酵细面，'),
('CUV', '利未记', 3, 2, 6, '分成块子，浇上油；这是素祭。'),
('CUV', '利未记', 3, 2, 7, '若用煎盘做的物为素祭，就要用油与细面作成。'),
('CUV', '利未记', 3, 2, 8, '要把这些东西做的素祭带到耶和华面前，并奉给祭司，带到坛前。'),
('CUV', '利未记', 3, 2, 9, '祭司要从素祭中取出作为纪念的，烧在坛上，是献与耶和华为馨香的火祭。'),
('CUV', '利未记', 3, 2, 10, '素祭所剩的要归给亚伦和他的子孙。这是献与耶和华的火祭中为至圣的。'),
('CUV', '利未记', 3, 2, 11, '凡献给耶和华的素祭都不可有酵；因为你们不可烧一点酵、一点蜜当作火祭献给耶和华。'),
('CUV', '利未记', 3, 2, 12, '这些物要献给耶和华作为初熟的供物，只是不可在坛上献为馨香的祭。'),
('CUV', '利未记', 3, 2, 13, '凡献为素祭的供物都要用盐调和，在素祭上不可缺了你神立约的盐。一切的供物都要配盐而献。'),
('CUV', '利未记', 3, 2, 14, '若向耶和华献初熟之物为素祭，要献上烘了的禾穗子，就是轧了的新穗子，当作初熟之物的素祭。'),
('CUV', '利未记', 3, 2, 15, '并要抹上油，加上乳香；这是素祭。'),
('CUV', '利未记', 3, 2, 16, '祭司要把其中作为纪念的，就是一些轧了的禾穗子和一些油，并所有的乳香，都焚烧，是向耶和华献的火祭。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 3, 1, '人献供物为平安祭（平安：或作酬恩；下同），若是从牛群中献，无论是公的是母的，必用没有残疾的献在耶和华面前。'),
('CUV', '利未记', 3, 3, 2, '他要按手在供物的头上，宰于会幕门口。亚伦子孙作祭司的，要把血洒在坛的周围。'),
('CUV', '利未记', 3, 3, 3, '从平安祭中，将火祭献给耶和华，也要把盖脏的脂油和脏上所有的脂油，'),
('CUV', '利未记', 3, 3, 4, '并两个腰子和腰子上的脂油，就是靠腰两旁的脂油，与肝上的网子和腰子，一概取下。'),
('CUV', '利未记', 3, 3, 5, '亚伦的子孙要把这些烧在坛的燔祭上，就是在火的柴上，是献与耶和华为馨香的火祭。'),
('CUV', '利未记', 3, 3, 6, '人向耶和华献供物为平安祭，若是从羊群中献，无论是公的是母的，必用没有残疾的。'),
('CUV', '利未记', 3, 3, 7, '若献一只羊羔为供物，必在耶和华面前献上，'),
('CUV', '利未记', 3, 3, 8, '并要按手在供物的头上，宰于会幕前。亚伦的子孙要把血洒在坛的周围。'),
('CUV', '利未记', 3, 3, 9, '从平安祭中，将火祭献给耶和华，其中的脂油和整肥尾巴都要在靠近脊骨处取下，并要把盖脏的脂油和脏上所有的脂油，'),
('CUV', '利未记', 3, 3, 10, '两个腰子和腰子上的脂油，就是靠腰两旁的脂油，并肝上的网子和腰子，一概取下。'),
('CUV', '利未记', 3, 3, 11, '祭司要在坛上焚烧，是献给耶和华为食物的火祭。'),
('CUV', '利未记', 3, 3, 12, '人的供物若是山羊，必在耶和华面前献上。'),
('CUV', '利未记', 3, 3, 13, '要按手在山羊头上，宰于会幕前。亚伦的子孙要把血洒在坛的周围，'),
('CUV', '利未记', 3, 3, 14, '又把盖脏的脂油和脏上所有的脂油，两个腰子和腰子上的脂油，就是靠腰两旁的脂油，并肝上的网子和腰子，一概取下，献给耶和华为火祭。'),
('CUV', '利未记', 3, 3, 15, 'a'),
('CUV', '利未记', 3, 3, 16, '祭司要在坛上焚烧，作为馨香火祭的食物。脂油都是耶和华的。'),
('CUV', '利未记', 3, 3, 17, '在你们一切的住处，脂油和血都不可吃；这要成为你们世世代代永远的定例。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 4, 1, '耶和华对摩西说：'),
('CUV', '利未记', 3, 4, 2, '你晓谕以色列人说：若有人在耶和华所吩咐不可行的甚么事上误犯了一件，'),
('CUV', '利未记', 3, 4, 3, '或是受膏的祭司犯罪，使百姓陷在罪里，就当为他所犯的罪把没有残疾的公牛犊献给耶和华为赎罪祭。'),
('CUV', '利未记', 3, 4, 4, '他要牵公牛到会幕门口，在耶和华面前按手在牛的头上，把牛宰于耶和华面前。'),
('CUV', '利未记', 3, 4, 5, '受膏的祭司要取些公牛的血带到会幕，'),
('CUV', '利未记', 3, 4, 6, '把指头蘸于血中，在耶和华面前对著圣所的幔子弹血七次，'),
('CUV', '利未记', 3, 4, 7, '又要把些血抹在会幕内、耶和华面前香坛的四角上，再把公牛所有的血倒在会幕门口、燔祭坛的脚那里。'),
('CUV', '利未记', 3, 4, 8, '要把赎罪祭公牛所有的脂油，乃是盖脏的脂油和脏上所有的脂油，'),
('CUV', '利未记', 3, 4, 9, '并两个腰子和腰子上的脂油，就是靠腰两旁的脂油，与肝上的网子和腰子，一概取下，'),
('CUV', '利未记', 3, 4, 10, '与平安祭公牛上所取的一样；祭司要把这些烧在燔祭的坛上。'),
('CUV', '利未记', 3, 4, 11, '公牛的皮和所有的肉，并头、腿、脏、腑、粪，'),
('CUV', '利未记', 3, 4, 12, '就是全公牛，要搬到营外洁净之地、倒灰之所，用火烧在柴上。'),
('CUV', '利未记', 3, 4, 13, '以色列全会众若行了耶和华所吩咐不可行的甚么事，误犯了罪，是隐而未现，会众看不出来的，'),
('CUV', '利未记', 3, 4, 14, '会众一知道所犯的罪就要献一只公牛犊为赎罪祭，牵到会幕前。'),
('CUV', '利未记', 3, 4, 15, '会中的长老就要在耶和华面前按手在牛的头上，将牛在耶和华面前宰了。'),
('CUV', '利未记', 3, 4, 16, '受膏的祭司要取些公牛的血带到会幕，'),
('CUV', '利未记', 3, 4, 17, '把指头蘸于血中，在耶和华面前对著幔子弹血七次，'),
('CUV', '利未记', 3, 4, 18, '又要把些血抹在会幕内、耶和华面前坛的四角上，再把所有的血倒在会幕门口、燔祭坛的脚那里。'),
('CUV', '利未记', 3, 4, 19, '把牛所有的脂油都取下，烧在坛上；'),
('CUV', '利未记', 3, 4, 20, '收拾这牛，与那赎罪祭的牛一样。祭司要为他们赎罪，他们必蒙赦免。'),
('CUV', '利未记', 3, 4, 21, '他要把牛搬到营外烧了，像烧头一个牛一样；这是会众的赎罪祭。'),
('CUV', '利未记', 3, 4, 22, '官长若行了耶和华─他神所吩咐不可行的甚么事，误犯了罪，'),
('CUV', '利未记', 3, 4, 23, '所犯的罪自己知道了，就要牵一只没有残疾的公山羊为供物，'),
('CUV', '利未记', 3, 4, 24, '按手在羊的头上，宰于耶和华面前、宰燔祭牲的地方；这是赎罪祭。'),
('CUV', '利未记', 3, 4, 25, '祭司要用指头蘸些赎罪祭牲的血，抹在燔祭坛的四角上，把血倒在燔祭坛的脚那里。'),
('CUV', '利未记', 3, 4, 26, '所有的脂油，祭司都要烧在坛上，正如平安祭的脂油一样。至于他的罪，祭司要为他赎了，他必蒙赦免。'),
('CUV', '利未记', 3, 4, 27, '民中若有人行了耶和华所吩咐不可行的甚么事，误犯了罪，'),
('CUV', '利未记', 3, 4, 28, '所犯的罪自己知道了，就要为所犯的罪牵一只没有残疾的母山羊为供物，'),
('CUV', '利未记', 3, 4, 29, '按手在赎罪祭牲的头上，在那宰燔祭牲的地方宰了。'),
('CUV', '利未记', 3, 4, 30, '祭司要用指头蘸些羊的血，抹在燔祭坛的四角上，所有的血都要倒在坛的脚那里，'),
('CUV', '利未记', 3, 4, 31, '又要把羊所有的脂油都取下，正如取平安祭牲的脂油一样。祭司要在坛上焚烧，在耶和华面前作为馨香的祭，为他赎罪，他必蒙赦免。'),
('CUV', '利未记', 3, 4, 32, '人若牵一只绵羊羔为赎罪祭的供物，必要牵一只没有残疾的母羊，'),
('CUV', '利未记', 3, 4, 33, '按手在赎罪祭牲的头上，在那宰燔祭牲的地方宰了作赎罪祭。'),
('CUV', '利未记', 3, 4, 34, '祭司要用指头蘸些赎罪祭牲的血，抹在燔祭坛的四角上，所有的血都要倒在坛的脚那里，'),
('CUV', '利未记', 3, 4, 35, '又要把所有的脂油都取下，正如取平安祭羊羔的脂油一样。祭司要按献给耶和华火祭的条例，烧在坛上。至于所犯的罪，祭司要为他赎了，他必蒙赦免。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 5, 1, '若有人听见发誓的声音（或作：若有人听见叫人发誓的声音），他本是见证，却不把所看见的、所知道的说出来，这就是罪；他要担当他的罪孽。'),
('CUV', '利未记', 3, 5, 2, '或是有人摸了不洁的物，无论是不洁的死兽，是不洁的死畜，是不洁的死虫，他却不知道，因此成了不洁，就有了罪。'),
('CUV', '利未记', 3, 5, 3, '或是他摸了别人的污秽，无论是染了甚么污秽，他却不知道，一知道了就有了罪。'),
('CUV', '利未记', 3, 5, 4, '或是有人嘴里冒失发誓，要行恶，要行善，无论人在甚么事上冒失发誓，他却不知道，一知道了就要在这其中的一件上有了罪。'),
('CUV', '利未记', 3, 5, 5, '他有了罪的时候，就要承认所犯的罪，'),
('CUV', '利未记', 3, 5, 6, '并要因所犯的罪，把他的赎愆祭牲─就是羊群中的母羊，或是一只羊羔，或是一只山羊─牵到耶和华面前为赎罪祭。至于他的罪，祭司要为他赎了。'),
('CUV', '利未记', 3, 5, 7, '他的力量若不够献一只羊羔，就要因所犯的罪，把两只斑鸠或是两只雏鸽带到耶和华面前为赎愆祭：一只作赎罪祭，一只作燔祭。'),
('CUV', '利未记', 3, 5, 8, '把这些带到祭司那里，祭司就要先把那赎罪祭献上，从鸟的颈项上揪下头来，只是不可把鸟撕断，'),
('CUV', '利未记', 3, 5, 9, '也把些赎罪祭牲的血弹在坛的旁边，剩下的血要流在坛的脚那里；这是赎罪祭。'),
('CUV', '利未记', 3, 5, 10, '他要照例献第二只为燔祭。至于他所犯的罪，祭司要为他赎了，他必蒙赦免。'),
('CUV', '利未记', 3, 5, 11, '他的力量若不够献两只斑鸠或是两只雏鸽，就要因所犯的罪带供物来，就是细面伊法十分之一为赎罪祭；不可加上油，也不可加上乳香，因为是赎罪祭。'),
('CUV', '利未记', 3, 5, 12, '他要把供物带到祭司那里，祭司要取出自己的一把来作为纪念，按献给耶和华火祭的条例烧在坛上；这是赎罪祭。'),
('CUV', '利未记', 3, 5, 13, '至于他在这几件事中所犯的罪，祭司要为他赎了，他必蒙赦免。剩下的面都归与祭司，和素祭一样。'),
('CUV', '利未记', 3, 5, 14, '耶和华晓谕摩西说：'),
('CUV', '利未记', 3, 5, 15, '人若在耶和华的圣物上误犯了罪，有了过犯，就要照你所估的，按圣所的舍客勒拿银子，将赎愆祭牲─就是羊群中一只没有残疾的公绵羊─牵到耶和华面前为赎愆祭；'),
('CUV', '利未记', 3, 5, 16, '并且他因在圣物上的差错要偿还，另外加五分之一，都给祭司。祭司要用赎愆祭的公绵羊为他赎罪，他必蒙赦免。'),
('CUV', '利未记', 3, 5, 17, '若有人犯罪，行了耶和华所吩咐不可行的甚么事，他虽然不知道，还是有了罪，就要担当他的罪孽；'),
('CUV', '利未记', 3, 5, 18, '也要照你所估定的价，从羊群中牵一只没有残疾的公绵羊来，给祭司作赎愆祭。至于他误行的那错事，祭司要为他赎罪，他必蒙赦免。'),
('CUV', '利未记', 3, 5, 19, '这是赎愆祭，因他在耶和华面前实在有了罪。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 6, 1, '耶和华晓谕摩西说：'),
('CUV', '利未记', 3, 6, 2, '若有人犯罪，干犯耶和华，在邻舍交付他的物上，或是在交易上行了诡诈，或是抢夺人的财物，或是欺压邻舍，'),
('CUV', '利未记', 3, 6, 3, '或是在捡了遗失的物上行了诡诈，说谎起誓，在这一切的事上犯了甚么罪；'),
('CUV', '利未记', 3, 6, 4, '他既犯了罪，有了过犯，就要归还他所抢夺的，或是因欺压所得的，或是人交付他的，或是人遗失他所捡的物，'),
('CUV', '利未记', 3, 6, 5, '或是他因甚么物起了假誓，就要如数归还，另外加上五分之一，在查出他有罪的日子要交还本主。'),
('CUV', '利未记', 3, 6, 6, '也要照你所估定的价，把赎愆祭牲─就是羊群中一只没有残疾的公绵羊─牵到耶和华面前，给祭司为赎愆祭。'),
('CUV', '利未记', 3, 6, 7, '祭司要在耶和华面前为他赎罪；他无论行了甚么事，使他有了罪，都必蒙赦免。'),
('CUV', '利未记', 3, 6, 8, '耶和华晓谕摩西说：'),
('CUV', '利未记', 3, 6, 9, '你要吩咐亚伦和他的子孙说，燔祭的条例乃是这样：燔祭要放在坛的柴上，从晚上到天亮，坛上的火要常常烧著。'),
('CUV', '利未记', 3, 6, 10, '祭司要穿上细麻布衣服，又要把细麻布裤子穿在身上，把坛上所烧的燔祭灰收起来，倒在坛的旁边；'),
('CUV', '利未记', 3, 6, 11, '随后要脱去这衣服，穿上别的衣服，把灰拿到营外洁净之处。'),
('CUV', '利未记', 3, 6, 12, '坛上的火要在其上常常烧著，不可熄灭。祭司要每日早晨在上面烧柴，并要把燔祭摆在坛上，在其上烧平安祭牲的脂油。'),
('CUV', '利未记', 3, 6, 13, '在坛上必有常常烧著的火，不可熄灭。'),
('CUV', '利未记', 3, 6, 14, '素祭的条例乃是这样：亚伦的子孙要在坛前把这祭献在耶和华面前。'),
('CUV', '利未记', 3, 6, 15, '祭司要从其中─就是从素祭的细面中─取出自己的一把，又要取些油和素祭上所有的乳香，烧在坛上，奉给耶和华为馨香素祭的纪念。'),
('CUV', '利未记', 3, 6, 16, '所剩下的，亚伦和他子孙要吃，必在圣处不带酵而吃，要在会幕的院子里吃。'),
('CUV', '利未记', 3, 6, 17, '烤的时候不可搀酵。这是从所献给我的火祭中赐给他们的分，是至圣的，和赎罪祭并赎愆祭一样。'),
('CUV', '利未记', 3, 6, 18, '凡献给耶和华的火祭，亚伦子孙中的男丁都要吃这一分，直到万代，作他们永得的分。摸这些祭物的，都要成为圣。'),
('CUV', '利未记', 3, 6, 19, '耶和华晓谕摩西说：'),
('CUV', '利未记', 3, 6, 20, '当亚伦受膏的日子，他和他子孙所要献给耶和华的供物，就是细面伊法十分之一，为常献的素祭：早晨一半，晚上一半。'),
('CUV', '利未记', 3, 6, 21, '要在铁鏊上用油调和做成，调匀了，你就拿进来；烤好了分成块子，献给耶和华为馨香的素祭。'),
('CUV', '利未记', 3, 6, 22, '亚伦的子孙中，接续他为受膏的祭司，要把这素祭献上，要全烧给耶和华。这是永远的定例。'),
('CUV', '利未记', 3, 6, 23, '祭司的素祭都要烧了，却不可吃。'),
('CUV', '利未记', 3, 6, 24, '耶和华晓谕摩西说：'),
('CUV', '利未记', 3, 6, 25, '你对亚伦和他的子孙说，赎罪祭的条例乃是这样：要在耶和华面前、宰燔祭牲的地方宰赎罪祭牲；这是至圣的。'),
('CUV', '利未记', 3, 6, 26, '为赎罪献这祭的祭司要吃，要在圣处，就是在会幕的院子里吃。'),
('CUV', '利未记', 3, 6, 27, '凡摸这祭肉的要成为圣；这祭牲的血若弹在甚么衣服上，所弹的那一件要在圣处洗净。'),
('CUV', '利未记', 3, 6, 28, '惟有煮祭物的瓦器要打碎；若是煮在铜器里，这铜器要擦磨，在水中涮净。'),
('CUV', '利未记', 3, 6, 29, '凡祭司中的男丁都可以吃；这是至圣的。'),
('CUV', '利未记', 3, 6, 30, '凡赎罪祭，若将血带进会幕在圣所赎罪，那肉都不可吃，必用火焚烧。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 7, 1, '赎愆祭的条例乃是如此：这祭是至圣的。'),
('CUV', '利未记', 3, 7, 2, '人在那里宰燔祭牲，也要在那里宰赎愆祭牲；其血，祭司要洒在坛的周围。'),
('CUV', '利未记', 3, 7, 3, '又要将肥尾巴和盖脏的脂油，'),
('CUV', '利未记', 3, 7, 4, '两个腰子和腰子上的脂油，就是靠腰两旁的脂油，并肝上的网子和腰子，一概取下。'),
('CUV', '利未记', 3, 7, 5, '祭司要在坛上焚烧，为献给耶和华的火祭，是赎愆祭。'),
('CUV', '利未记', 3, 7, 6, '祭司中的男丁都可以吃这祭物；要在圣处吃，是至圣的。'),
('CUV', '利未记', 3, 7, 7, '赎罪祭怎样，赎愆祭也是怎样，两个祭是一个条例。献赎愆祭赎罪的祭司要得这祭物。'),
('CUV', '利未记', 3, 7, 8, '献燔祭的祭司，无论为谁奉献，要亲自得他所献那燔祭牲的皮。'),
('CUV', '利未记', 3, 7, 9, '凡在炉中烤的素祭和煎盘中做的，并铁鏊上做的，都要归那献祭的祭司。'),
('CUV', '利未记', 3, 7, 10, '凡素祭，无论是油调和的是干的，都要归亚伦的子孙，大家均分。'),
('CUV', '利未记', 3, 7, 11, '人献与耶和华平安祭的条例乃是这样：'),
('CUV', '利未记', 3, 7, 12, '他若为感谢献上，就要用调油的无酵饼和抹油的无酵薄饼，并用油调匀细面做的饼，与感谢祭一同献上。'),
('CUV', '利未记', 3, 7, 13, '要用有酵的饼和为感谢献的平安祭，与供物一同献上。'),
('CUV', '利未记', 3, 7, 14, '从各样的供物中，他要把一个饼献给耶和华为举祭，是要归给洒平安祭牲血的祭司。'),
('CUV', '利未记', 3, 7, 15, '为感谢献平安祭牲的肉，要在献的日子吃，一点不可留到早晨。'),
('CUV', '利未记', 3, 7, 16, '若所献的是为还愿，或是甘心献的，必在献祭的日子吃，所剩下的第二天也可以吃。'),
('CUV', '利未记', 3, 7, 17, '但所剩下的祭肉，到第三天要用火焚烧；'),
('CUV', '利未记', 3, 7, 18, '第三天若吃了平安祭的肉，这祭必不蒙悦纳，人所献的也不算为祭，反为可憎嫌的，吃这祭肉的，就必担当他的罪孽。'),
('CUV', '利未记', 3, 7, 19, '挨了污秽物的肉就不可吃，要用火焚烧。至于平安祭的肉，凡洁净的人都要吃；'),
('CUV', '利未记', 3, 7, 20, '只是献与耶和华平安祭的肉，人若不洁净而吃了，这人必从民中剪除。'),
('CUV', '利未记', 3, 7, 21, '有人摸了甚么不洁净的物，或是人的不洁净，或是不洁净的牲畜，或是不洁可憎之物，吃了献与耶和华平安祭的肉，这人必从民中剪除。'),
('CUV', '利未记', 3, 7, 22, '耶和华对摩西说：'),
('CUV', '利未记', 3, 7, 23, '你晓谕以色列人说：牛的脂油、绵羊的脂油、山羊的脂油，你们都不可吃。'),
('CUV', '利未记', 3, 7, 24, '自死的和被野兽撕裂的，那脂油可以做别的使用，只是你们万不可吃。'),
('CUV', '利未记', 3, 7, 25, '无论何人吃了献给耶和华当火祭牲畜的脂油，那人必从民中剪除。'),
('CUV', '利未记', 3, 7, 26, '在你们一切的住处，无论是雀鸟的血是野兽的血，你们都不可吃。'),
('CUV', '利未记', 3, 7, 27, '无论是谁吃血，那人必从民中剪除。'),
('CUV', '利未记', 3, 7, 28, '耶和华对摩西说：'),
('CUV', '利未记', 3, 7, 29, '你晓谕以色列人说：献平安祭给耶和华的，要从平安祭中取些来奉给耶和华。'),
('CUV', '利未记', 3, 7, 30, '他亲手献给耶和华的火祭，就是脂油和胸，要带来，好把胸在耶和华面前作摇祭，摇一摇。'),
('CUV', '利未记', 3, 7, 31, '祭司要把脂油在坛上焚烧，但胸要归亚伦和他的子孙。'),
('CUV', '利未记', 3, 7, 32, '你们要从平安祭中把右腿作举祭，奉给祭司。'),
('CUV', '利未记', 3, 7, 33, '亚伦子孙中，献平安祭牲血和脂油的，要得这右腿为分；'),
('CUV', '利未记', 3, 7, 34, '因为我从以色列人的平安祭中，取了这摇的胸和举的腿给祭司亚伦和他子孙，作他们从以色列人中所永得的分。'),
('CUV', '利未记', 3, 7, 35, '这是从耶和华火祭中，作亚伦受膏的分和他子孙受膏的分，正在摩西（原文是他）叫他们前来给耶和华供祭司职分的日子，'),
('CUV', '利未记', 3, 7, 36, '就是在摩西（原文是他）膏他们的日子，耶和华吩咐以色列人给他们的。这是他们世世代代永得的分。'),
('CUV', '利未记', 3, 7, 37, '这就是燔祭、素祭、赎罪祭、赎愆祭，和平安祭的条例，并承接圣职的礼，'),
('CUV', '利未记', 3, 7, 38, '都是耶和华在西乃山所吩咐摩西的，就是他在西乃旷野吩咐以色列人献供物给耶和华之日所说的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 8, 1, '耶和华晓谕摩西说：'),
('CUV', '利未记', 3, 8, 2, '你将亚伦和他儿子一同带来，并将圣衣、膏油，与赎罪祭的一只公牛、两只公绵羊、一筐无酵饼都带来，'),
('CUV', '利未记', 3, 8, 3, '又招聚会众到会幕门口。'),
('CUV', '利未记', 3, 8, 4, '摩西就照耶和华所吩咐的行了；于是会众聚集在会幕门口。'),
('CUV', '利未记', 3, 8, 5, '摩西告诉会众说：这就是耶和华所吩咐当行的事。'),
('CUV', '利未记', 3, 8, 6, '摩西带了亚伦和他儿子来，用水洗了他们。'),
('CUV', '利未记', 3, 8, 7, '给亚伦穿上内袍，束上腰带，穿上外袍，又加上以弗得，用其上巧工织的带子把以弗得系在他身上，'),
('CUV', '利未记', 3, 8, 8, '又给他戴上胸牌，把乌陵和土明放在胸牌内，'),
('CUV', '利未记', 3, 8, 9, '把冠冕戴在他头上，在冠冕的前面钉上金牌，就是圣冠，都是照耶和华所吩咐摩西的。'),
('CUV', '利未记', 3, 8, 10, '摩西用膏油抹帐幕和其中所有的，使他成圣；'),
('CUV', '利未记', 3, 8, 11, '又用膏油在坛上弹了七次，又抹了坛和坛的一切器皿，并洗濯盆和盆座，使他成圣；'),
('CUV', '利未记', 3, 8, 12, '又把膏油倒在亚伦的头上膏他，使他成圣。'),
('CUV', '利未记', 3, 8, 13, '摩西带了亚伦的儿子来，给他们穿上内袍，束上腰带，包上裹头巾，都是照耶和华所吩咐摩西的。'),
('CUV', '利未记', 3, 8, 14, '他牵了赎罪祭的公牛来，亚伦和他儿子按手在赎罪祭公牛的头上，'),
('CUV', '利未记', 3, 8, 15, '就宰了公牛。摩西用指头蘸血，抹在坛上四角的周围，使坛洁净，把血倒在坛的脚那里，使坛成圣，坛就洁净了；'),
('CUV', '利未记', 3, 8, 16, '又取脏上所有的脂油和肝上的网子，并两个腰子与腰子上的脂油，都烧在坛上；'),
('CUV', '利未记', 3, 8, 17, '惟有公牛，连皮带肉并粪，用火烧在营外，都是照耶和华所吩咐摩西的。'),
('CUV', '利未记', 3, 8, 18, '他奉上燔祭的公绵羊；亚伦和他儿子按手在羊的头上，'),
('CUV', '利未记', 3, 8, 19, '就宰了公羊。摩西把血洒在坛的周围，'),
('CUV', '利未记', 3, 8, 20, '把羊切成块子，把头和肉块并脂油都烧了。'),
('CUV', '利未记', 3, 8, 21, '用水洗了脏腑和腿，就把全羊烧在坛上为馨香的燔祭，是献给耶和华的火祭，都是照耶和华所吩咐摩西的。'),
('CUV', '利未记', 3, 8, 22, '他又奉上第二只公绵羊，就是承接圣职之礼的羊；亚伦和他儿子按手在羊的头上，'),
('CUV', '利未记', 3, 8, 23, '就宰了羊。摩西把些血抹在亚伦的右耳垂上和右手的大拇指上，并右脚的大拇指上，'),
('CUV', '利未记', 3, 8, 24, '又带了亚伦的儿子来，把些血抹在他们的右耳垂上和右手的大拇指上，并右脚的大拇指上，又把血洒在坛的周围。'),
('CUV', '利未记', 3, 8, 25, '取脂油和肥尾巴，并脏上一切的脂油与肝上的网子，两个腰子和腰子上的脂油，并右腿，'),
('CUV', '利未记', 3, 8, 26, '再从耶和华面前、盛无酵饼的筐子里取出一个无酵饼，一个油饼，一个薄饼，都放在脂油和右腿上，'),
('CUV', '利未记', 3, 8, 27, '把这一切放在亚伦的手上和他儿子的手上作摇祭，在耶和华面前摇一摇。'),
('CUV', '利未记', 3, 8, 28, '摩西从他们的手上拿下来，烧在坛上的燔祭上，都是为承接圣职献给耶和华馨香的火祭。'),
('CUV', '利未记', 3, 8, 29, '摩西拿羊的胸作为摇祭，在耶和华面前摇一摇，是承接圣职之礼，归摩西的分，都是照耶和华所吩咐摩西的。'),
('CUV', '利未记', 3, 8, 30, '摩西取点膏油和坛上的血，弹在亚伦和他的衣服上，并他儿子和他儿子的衣服上，使他和他们的衣服一同成圣。'),
('CUV', '利未记', 3, 8, 31, '摩西对亚伦和他儿子说：把肉煮在会幕门口，在那里吃，又吃承接圣职筐子里的饼，按我所吩咐的说（或作：按所吩咐我的说）：这是亚伦和他儿子要吃的。'),
('CUV', '利未记', 3, 8, 32, '剩下的肉和饼，你们要用火焚烧。'),
('CUV', '利未记', 3, 8, 33, '你们七天不可出会幕的门，等到你们承接圣职的日子满了，因为主叫你们七天承接圣职。'),
('CUV', '利未记', 3, 8, 34, '像今天所行的都是耶和华吩咐行的，为你们赎罪。'),
('CUV', '利未记', 3, 8, 35, '七天你们要昼夜住在会幕门口，遵守耶和华的吩咐，免得你们死亡，因为所吩咐我的就是这样。'),
('CUV', '利未记', 3, 8, 36, '于是亚伦和他儿子行了耶和华藉著摩西所吩咐的一切事。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 9, 1, '到了第八天，摩西召了亚伦和他儿子，并以色列的众长老来，'),
('CUV', '利未记', 3, 9, 2, '对亚伦说：你当取牛群中的一只公牛犊作赎罪祭，一只公绵羊作燔祭，都要没有残疾的，献在耶和华面前。'),
('CUV', '利未记', 3, 9, 3, '你也要对以色列人说：你们当取一只公山羊作赎罪祭，又取一只牛犊和一只绵羊羔，都要一岁、没有残疾的，作燔祭，'),
('CUV', '利未记', 3, 9, 4, '又取一只公牛，一只公绵羊作平安祭，献在耶和华面前，并取调油的素祭，因为今天耶和华要向你们显现。'),
('CUV', '利未记', 3, 9, 5, '于是他们把摩西所吩咐的，带到会幕前；全会众都近前来，站在耶和华面前。'),
('CUV', '利未记', 3, 9, 6, '摩西说：这是耶和华吩咐你们所当行的；耶和华的荣光就要向你们显现。'),
('CUV', '利未记', 3, 9, 7, '摩西对亚伦说：你就近坛前，献你的赎罪祭和燔祭，为自己与百姓赎罪，又献上百姓的供物，为他们赎罪，都照耶和华所吩咐的。'),
('CUV', '利未记', 3, 9, 8, '于是，亚伦就近坛前，宰了为自己作赎罪祭的牛犊。'),
('CUV', '利未记', 3, 9, 9, '亚伦的儿子把血奉给他，他就把指头蘸在血中，抹在坛的四角上，又把血倒在坛脚那里。'),
('CUV', '利未记', 3, 9, 10, '惟有赎罪祭的脂油和腰子，并肝上取的网子，都烧在坛上，是照耶和华所吩咐摩西的；'),
('CUV', '利未记', 3, 9, 11, '又用火将肉和皮烧在营外。'),
('CUV', '利未记', 3, 9, 12, '亚伦宰了燔祭牲，他儿子把血递给他，他就洒在坛的周围，'),
('CUV', '利未记', 3, 9, 13, '又把燔祭一块一块的、连头递给他，他都烧在坛上；'),
('CUV', '利未记', 3, 9, 14, '又洗了脏腑和腿，烧在坛上的燔祭上。'),
('CUV', '利未记', 3, 9, 15, '他奉上百姓的供物，把那给百姓作赎罪祭的公山羊宰了，为罪献上，和先献的一样；'),
('CUV', '利未记', 3, 9, 16, '也奉上燔祭，照例而献。'),
('CUV', '利未记', 3, 9, 17, '他又奉上素祭，从其中取一满把，烧在坛上；这是在早晨的燔祭以外。'),
('CUV', '利未记', 3, 9, 18, '亚伦宰了那给百姓作平安祭的公牛和公绵羊。他儿子把血递给他，他就洒在坛的周围；'),
('CUV', '利未记', 3, 9, 19, '又把公牛和公绵羊的脂油、肥尾巴，并盖脏的脂油与腰子，和肝上的网子，都递给他；'),
('CUV', '利未记', 3, 9, 20, '把脂油放在胸上，他就把脂油烧在坛上。'),
('CUV', '利未记', 3, 9, 21, '胸和右腿，亚伦当作摇祭，在耶和华面前摇一摇，都是照摩西所吩咐的。'),
('CUV', '利未记', 3, 9, 22, '亚伦向百姓举手，为他们祝福。他献了赎罪祭、燔祭、平安祭就下来了。'),
('CUV', '利未记', 3, 9, 23, '摩西、亚伦进入会幕，又出来为百姓祝福，耶和华的荣光就向众民显现。'),
('CUV', '利未记', 3, 9, 24, '有火从耶和华面前出来，在坛上烧尽燔祭和脂油；众民一见，就都欢呼，俯伏在地。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 10, 1, '亚伦的儿子拿答、亚比户各拿自己的香炉，盛上火，加上香，在耶和华面前献上凡火，是耶和华没有吩咐他们的，'),
('CUV', '利未记', 3, 10, 2, '就有火从耶和华面前出来，把他们烧灭，他们就死在耶和华面前。'),
('CUV', '利未记', 3, 10, 3, '于是摩西对亚伦说：这就是耶和华所说：我在亲近我的人中要显为圣；在众民面前，我要得荣耀。亚伦就默默不言。'),
('CUV', '利未记', 3, 10, 4, '摩西召了亚伦叔父乌薛的儿子米沙利、以利撒反来，对他们说：上前来，把你们的亲属从圣所前抬到营外。'),
('CUV', '利未记', 3, 10, 5, '于是二人上前来，把他们穿著袍子抬到营外，是照摩西所吩咐的。'),
('CUV', '利未记', 3, 10, 6, '摩西对亚伦和他儿子以利亚撒、以他玛说：不可蓬头散发，也不可撕裂衣裳，免得你们死亡，又免得耶和华向会众发怒；只要你们的弟兄以色列全家为耶和华所发的火哀哭。'),
('CUV', '利未记', 3, 10, 7, '你们也不可出会幕的门，恐怕你们死亡，因为耶和华的膏油在你们的身上。他们就照摩西的话行了。'),
('CUV', '利未记', 3, 10, 8, '耶和华晓谕亚伦说：'),
('CUV', '利未记', 3, 10, 9, '你和你儿子进会幕的时候，清酒、浓酒都不可喝，免得你们死亡；这要作你们世世代代永远的定例。'),
('CUV', '利未记', 3, 10, 10, '使你们可以将圣的、俗的，洁净的、不洁净的，分别出来；'),
('CUV', '利未记', 3, 10, 11, '又使你们可以将耶和华藉摩西晓谕以色列人的一切律例教训他们。'),
('CUV', '利未记', 3, 10, 12, '摩西对亚伦和他剩下的儿子以利亚撒、以他玛说：你们献给耶和华火祭中所剩的素祭，要在坛旁不带酵而吃，因为是至圣的。'),
('CUV', '利未记', 3, 10, 13, '你们要在圣处吃；因为在献给耶和华的火祭中，这是你的分和你儿子的分；所吩咐我的本是这样。'),
('CUV', '利未记', 3, 10, 14, '所摇的胸，所举的腿，你们要在洁净地方吃。你和你的儿女都要同吃；因为这些是从以色列人平安祭中给你，当你的分和你儿子的分。'),
('CUV', '利未记', 3, 10, 15, '所举的腿，所摇的胸，他们要与火祭的脂油一同带来当摇祭，在耶和华面前摇一摇；这要归你和你儿子，当作永得的分，都是照耶和华所吩咐的。'),
('CUV', '利未记', 3, 10, 16, '当下摩西急切的寻找作赎罪祭的公山羊，谁知已经焚烧了，便向亚伦剩下的儿子以利亚撒、以他玛发怒，说：'),
('CUV', '利未记', 3, 10, 17, '这赎罪祭既是至圣的，主又给了你们，为要你们担当会众的罪孽，在耶和华面前为他们赎罪，你们为何没有在圣所吃呢？'),
('CUV', '利未记', 3, 10, 18, '看哪，这祭牲的血并没有拿到圣所里去，你们本当照我所吩咐的，在圣所里吃这祭肉。'),
('CUV', '利未记', 3, 10, 19, '亚伦对摩西说：今天他们在耶和华面前献上赎罪祭和燔祭，我又遇见这样的灾，若今天吃了赎罪祭，耶和华岂能看为美呢？'),
('CUV', '利未记', 3, 10, 20, '摩西听见这话，便以为美。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 11, 1, '耶和华对摩西、亚伦说：'),
('CUV', '利未记', 3, 11, 2, '你们晓谕以色列人说，在地上一切走兽中可吃的乃是这些：'),
('CUV', '利未记', 3, 11, 3, '凡蹄分两瓣、倒嚼的走兽，你们都可以吃。'),
('CUV', '利未记', 3, 11, 4, '但那倒嚼或分蹄之中不可吃的乃是：骆驼─因为倒嚼不分蹄，就与你们不洁净；'),
('CUV', '利未记', 3, 11, 5, '沙番─因为倒嚼不分蹄，就与你们不洁净；'),
('CUV', '利未记', 3, 11, 6, '兔子─因为倒嚼不分蹄，就与你们不洁净；'),
('CUV', '利未记', 3, 11, 7, '猪─因为蹄分两瓣，却不倒嚼，就与你们不洁净。'),
('CUV', '利未记', 3, 11, 8, '这些兽的肉，你们不可吃；死的，你们不可摸，都与你们不洁净。'),
('CUV', '利未记', 3, 11, 9, '水中可吃的乃是这些：凡在水里、海里、河里、有翅有鳞的，都可以吃。'),
('CUV', '利未记', 3, 11, 10, '凡在海里、河里，并一切水里游动的活物，无翅无鳞的，你们都当以为可憎。'),
('CUV', '利未记', 3, 11, 11, '这些无翅无鳞、以为可憎的，你们不可吃他的肉；死的也当以为可憎。'),
('CUV', '利未记', 3, 11, 12, '凡水里无翅无鳞的，你们都当以为可憎。'),
('CUV', '利未记', 3, 11, 13, '雀鸟中你们当以为可憎、不可吃的乃是：雕、狗头雕、红头雕、'),
('CUV', '利未记', 3, 11, 14, '鹞鹰、小鹰与其类；'),
('CUV', '利未记', 3, 11, 15, '乌鸦与其类；'),
('CUV', '利未记', 3, 11, 16, '鸵鸟、夜鹰、鱼鹰、鹰与其类；'),
('CUV', '利未记', 3, 11, 17, '鸮鸟、鸬鹚、猫头鹰、'),
('CUV', '利未记', 3, 11, 18, '角鸱、鹈鹕、秃雕、'),
('CUV', '利未记', 3, 11, 19, '鹳、鹭鸶与其类；戴鵀与蝙蝠。'),
('CUV', '利未记', 3, 11, 20, '凡有翅膀用四足爬行的物，你们都当以为可憎。'),
('CUV', '利未记', 3, 11, 21, '只是有翅膀用四足爬行的物中，有足有腿，在地上蹦跳的，你们还可以吃。'),
('CUV', '利未记', 3, 11, 22, '其中有蝗虫、蚂蚱、蟋蟀与其类；蚱蜢与其类；这些你们都可以吃。'),
('CUV', '利未记', 3, 11, 23, '但是有翅膀有四足的爬物，你们都当以为可憎。'),
('CUV', '利未记', 3, 11, 24, '这些都能使你们不洁净。凡摸了死的，必不洁净到晚上。'),
('CUV', '利未记', 3, 11, 25, '凡拿了死的，必不洁净到晚上，并要洗衣服。'),
('CUV', '利未记', 3, 11, 26, '凡走兽分蹄不成两瓣、也不倒嚼的，是与你们不洁净；凡摸了的就不洁净。'),
('CUV', '利未记', 3, 11, 27, '凡四足的走兽，用掌行走的，是与你们不洁净；摸其尸的，必不洁净到晚上。'),
('CUV', '利未记', 3, 11, 28, '拿其尸的，必不洁净到晚上，并要洗衣服。这些是与你们不洁净的。'),
('CUV', '利未记', 3, 11, 29, '地上爬物与你们不洁净的乃是这些：鼬鼠、鼫鼠、蜥蜴与其类；'),
('CUV', '利未记', 3, 11, 30, '壁虎、龙子、守宫、蛇医、蝘蜓。'),
('CUV', '利未记', 3, 11, 31, '这些爬物都是与你们不洁净的。在他死了以后，凡摸了的，必不洁净到晚上。'),
('CUV', '利未记', 3, 11, 32, '其中死了的，掉在甚么东西上，这东西就不洁净，无论是木器、衣服、皮子、口袋，不拘是做甚么工用的器皿，须要放在水中，必不洁净到晚上，到晚上才洁净了。'),
('CUV', '利未记', 3, 11, 33, '若有死了掉在瓦器里的，其中不拘有甚么，就不洁净，你们要把这瓦器打破了。'),
('CUV', '利未记', 3, 11, 34, '其中一切可吃的食物，沾水的就不洁净，并且那样器皿中一切可喝的，也必不洁净。'),
('CUV', '利未记', 3, 11, 35, '其中已死的，若有一点掉在甚么物件上，那物件就不洁净，不拘是炉子，是锅台，就要打碎，都不洁净，也必与你们不洁净。'),
('CUV', '利未记', 3, 11, 36, '但是泉源或是聚水的池子仍是洁净；惟挨了那死的，就不洁净。'),
('CUV', '利未记', 3, 11, 37, '若是死的，有一点掉在要种的子粒上，子粒仍是洁净；'),
('CUV', '利未记', 3, 11, 38, '若水已经浇在子粒上，那死的有一点掉在上头，这子粒就与你们不洁净。'),
('CUV', '利未记', 3, 11, 39, '你们可吃的走兽若是死了，有人摸他，必不洁净到晚上；'),
('CUV', '利未记', 3, 11, 40, '有人吃那死了的走兽，必不洁净到晚上，并要洗衣服；拿了死走兽的，必不洁净到晚上，并要洗衣服。'),
('CUV', '利未记', 3, 11, 41, '凡地上的爬物是可憎的，都不可吃。'),
('CUV', '利未记', 3, 11, 42, '凡用肚子行走的和用四足行走的，或是有许多足的，就是一切爬在地上的，你们都不可吃，因为是可憎的。'),
('CUV', '利未记', 3, 11, 43, '你们不可因甚么爬物使自己成为可憎的，也不可因这些使自己不洁净，以致染了污秽。'),
('CUV', '利未记', 3, 11, 44, '我是耶和华─你们的神；所以你们要成为圣洁，因为我是圣洁的。你们也不可在地上的爬物污秽自己。'),
('CUV', '利未记', 3, 11, 45, '我是把你们从埃及地领出来的耶和华，要作你们的神；所以你们要圣洁，因为我是圣洁的。'),
('CUV', '利未记', 3, 11, 46, '这是走兽、飞鸟，和水中游动的活物，并地上爬物的条例。'),
('CUV', '利未记', 3, 11, 47, '要把洁净的和不洁净的，可吃的与不可吃的活物，都分别出来。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 12, 1, '耶和华对摩西说：'),
('CUV', '利未记', 3, 12, 2, '你晓谕以色列人说：若有妇人怀孕生男孩，他就不洁净七天，像在月经污秽的日子不洁净一样。'),
('CUV', '利未记', 3, 12, 3, '第八天，要给婴孩行割礼。'),
('CUV', '利未记', 3, 12, 4, '妇人在产血不洁之中，要家居三十三天。他洁净的日子未满，不可摸圣物，也不可进入圣所。'),
('CUV', '利未记', 3, 12, 5, '他若生女孩，就不洁净两个七天，像污秽的时候一样，要在产血不洁之中，家居六十六天。'),
('CUV', '利未记', 3, 12, 6, '满了洁净的日子，无论是为男孩是为女孩，他要把一岁的羊羔为燔祭，一只雏鸽或是一只斑鸠为赎罪祭，带到会幕门口交给祭司。'),
('CUV', '利未记', 3, 12, 7, '祭司要献在耶和华面前，为他赎罪，他的血源就洁净了。这条例是为生育的妇人，无论是生男生女。'),
('CUV', '利未记', 3, 12, 8, '他的力量不够献一只羊羔，他就要取两只斑鸠或是两只雏鸽，一只为燔祭，一只为赎罪祭。祭司要为他赎罪，他就洁净了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 13, 1, '耶和华晓谕摩西、亚伦说：'),
('CUV', '利未记', 3, 13, 2, '人的肉皮上若长了疖子，或长了癣，或长了火斑，在他肉皮上成了大痲疯的灾病，就要将他带到祭司亚伦或亚伦作祭司的一个子孙面前。'),
('CUV', '利未记', 3, 13, 3, '祭司要察看肉皮上的灾病，若灾病处的毛已经变白，灾病的现象深于肉上的皮，这便是大痲疯的灾病。祭司要察看他，定他为不洁净。'),
('CUV', '利未记', 3, 13, 4, '若火斑在他肉皮上是白的，现象不深于皮，其上的毛也没有变白，祭司就要将有灾病的人关锁七天。'),
('CUV', '利未记', 3, 13, 5, '第七天，祭司要察看他，若看灾病止住了，没有在皮上发散，祭司还要将他关锁七天。'),
('CUV', '利未记', 3, 13, 6, '第七天，祭司要再察看他，若灾病发暗，而且没有在皮上发散，祭司要定他为洁净，原来是癣；那人就要洗衣服，得为洁净。'),
('CUV', '利未记', 3, 13, 7, '但他为得洁净，将身体给祭司察看以后，癣若在皮上发散开了，他要再将身体给祭司察看。'),
('CUV', '利未记', 3, 13, 8, '祭司要察看，癣若在皮上发散，就要定他为不洁净，是大痲疯。'),
('CUV', '利未记', 3, 13, 9, '人有了大痲疯的灾病，就要将他带到祭司面前。'),
('CUV', '利未记', 3, 13, 10, '祭司要察看，皮上若长了白疖，使毛变白，在长白疖之处有了红瘀肉，'),
('CUV', '利未记', 3, 13, 11, '这是肉皮上的旧大痲疯，祭司要定他为不洁净，不用将他关锁，因为他是不洁净了。'),
('CUV', '利未记', 3, 13, 12, '大痲疯若在皮上四外发散，长满了患灾病人的皮，据祭司察看，从头到脚无处不有，'),
('CUV', '利未记', 3, 13, 13, '祭司就要察看，全身的肉若长满了大痲疯，就要定那患灾病的为洁净；全身都变为白，他乃洁净了。'),
('CUV', '利未记', 3, 13, 14, '但红肉几时显在他的身上就几时不洁净。'),
('CUV', '利未记', 3, 13, 15, '祭司一看那红肉就定他为不洁净。红肉本是不洁净，是大痲疯。'),
('CUV', '利未记', 3, 13, 16, '红肉若复原，又变白了，他就要来见祭司。'),
('CUV', '利未记', 3, 13, 17, '祭司要察看，灾病处若变白了，祭司就要定那患灾病的为洁净，他乃洁净了。'),
('CUV', '利未记', 3, 13, 18, '人若在皮肉上长疮，却治好了，'),
('CUV', '利未记', 3, 13, 19, '在长疮之处又起了白疖，或是白中带红的火斑，就要给祭司察看。'),
('CUV', '利未记', 3, 13, 20, '祭司要察看，若现象洼于皮，其上的毛也变白了，就要定他为不洁净，是大痲疯的灾病发在疮中。'),
('CUV', '利未记', 3, 13, 21, '祭司若察看，其上没有白毛，也没有洼于皮，乃是发暗，就要将他关锁七天。'),
('CUV', '利未记', 3, 13, 22, '若在皮上发散开了，祭司就要定他为不洁净，是灾病。'),
('CUV', '利未记', 3, 13, 23, '火斑若在原处止住，没有发散，便是疮的痕迹，祭司就要定他为洁净。'),
('CUV', '利未记', 3, 13, 24, '人的皮肉上若起了火毒，火毒的瘀肉成了火斑，或是白中带红的，或是全白的，'),
('CUV', '利未记', 3, 13, 25, '祭司就要察看，火斑中的毛若变白了，现象又深于皮，是大痲疯在火毒中发出，就要定他为不洁净，是大痲疯的灾病。'),
('CUV', '利未记', 3, 13, 26, '但是祭司察看，在火斑中若没有白毛，也没有洼于皮，乃是发暗，就要将他关锁七天。'),
('CUV', '利未记', 3, 13, 27, '到第七天，祭司要察看他，火斑若在皮上发散开了，就要定他为不洁净，是大痲疯的灾病。'),
('CUV', '利未记', 3, 13, 28, '火斑若在原处止住，没有在皮上发散，乃是发暗，是起的火毒，祭司要定他为洁净，不过是火毒的痕迹。'),
('CUV', '利未记', 3, 13, 29, '无论男女，若在头上有灾病，或是男人胡须上有灾病，'),
('CUV', '利未记', 3, 13, 30, '祭司就要察看；这灾病现象若深于皮，其间有细黄毛，就要定他为不洁净，这是头疥，是头上或是胡须上的大痲疯。'),
('CUV', '利未记', 3, 13, 31, '祭司若察看头疥的灾病，现象不深于皮，其间也没有黑毛，就要将长头疥灾病的关锁七天。'),
('CUV', '利未记', 3, 13, 32, '第七天，祭司要察看灾病，若头疥没有发散，其间也没有黄毛，头疥的现象不深于皮，'),
('CUV', '利未记', 3, 13, 33, '那人就要剃去须发，但他不可剃头疥之处。祭司要将那长头疥的，再关锁七天。'),
('CUV', '利未记', 3, 13, 34, '第七天，祭司要察看头疥，头疥若没有在皮上发散，现象也不深于皮，就要定他为洁净，他要洗衣服，便成为洁净。'),
('CUV', '利未记', 3, 13, 35, '但他得洁净以后，头疥若在皮上发散开了，'),
('CUV', '利未记', 3, 13, 36, '祭司就要察看他。头疥若在皮上发散，就不必找那黄毛，他是不洁净了。'),
('CUV', '利未记', 3, 13, 37, '祭司若看头疥已经止住，其间也长了黑毛，头疥已然痊愈，那人是洁净了，就要定他为洁净。'),
('CUV', '利未记', 3, 13, 38, '无论男女，皮肉上若起了火斑，就是白火斑，'),
('CUV', '利未记', 3, 13, 39, '祭司就要察看，他们肉皮上的火斑若白中带黑，这是皮上发出的白癣，那人是洁净了。'),
('CUV', '利未记', 3, 13, 40, '人头上的发若掉了，他不过是头秃，还是洁净。'),
('CUV', '利未记', 3, 13, 41, '他顶前若掉了头发，他不过是顶门秃，还是洁净。'),
('CUV', '利未记', 3, 13, 42, '头秃处或是顶门秃处若有白中带红的灾病，这就是大痲疯发在他头秃处或是顶门秃处，'),
('CUV', '利未记', 3, 13, 43, '祭司就要察看，他起的那灾病若在头秃处或是顶门秃处有白中带红的，像肉皮上大痲疯的现象，'),
('CUV', '利未记', 3, 13, 44, '那人就是长大痲疯，不洁净的，祭司总要定他为不洁净，他的灾病是在头上。'),
('CUV', '利未记', 3, 13, 45, '身上有长大痲疯灾病的，他的衣服要撕裂，也要蓬头散发，蒙著上唇，喊叫说：不洁净了！不洁净了！'),
('CUV', '利未记', 3, 13, 46, '灾病在他身上的日子，他便是不洁净；他既是不洁净，就要独居营外。'),
('CUV', '利未记', 3, 13, 47, '染了大痲疯灾病的衣服，无论是羊毛衣服、是麻布衣服，'),
('CUV', '利未记', 3, 13, 48, '无论是在经上、在纬上，是麻布的、是羊毛的，是在皮子上，或在皮子做的甚么物件上，'),
('CUV', '利未记', 3, 13, 49, '或在衣服上、皮子上，经上、纬上，或在皮子做的甚么物件上，这灾病若是发绿，或是发红，是大痲疯的灾病，要给祭司察看。'),
('CUV', '利未记', 3, 13, 50, '祭司就要察看那灾病，把染了灾病的物件关锁七天。'),
('CUV', '利未记', 3, 13, 51, '第七天，他要察看那灾病，灾病或在衣服上，经上、纬上，皮子上，若发散，这皮子无论当作何用，这灾病是蚕食的大痲疯，都是不洁净了。'),
('CUV', '利未记', 3, 13, 52, '那染了灾病的衣服，或是经上、纬上，羊毛上，麻衣上，或是皮子做的甚么物件上，他都要焚烧；因为这是蚕食的大痲疯，必在火中焚烧。'),
('CUV', '利未记', 3, 13, 53, '祭司要察看，若灾病在衣服上，经上、纬上，或是皮子做的甚么物件上，没有发散，'),
('CUV', '利未记', 3, 13, 54, '祭司就要吩咐他们，把染了灾病的物件洗了，再关锁七天。'),
('CUV', '利未记', 3, 13, 55, '洗过以后，祭司要察看，那物件若没有变色，灾病也没有消散，那物件就不洁净，是透重的灾病，无论正面反面，都要在火中焚烧。'),
('CUV', '利未记', 3, 13, 56, '洗过以后，祭司要察看，若见那灾病发暗，他就要把那灾病从衣服上、皮子上、经上、纬上，都撕去。'),
('CUV', '利未记', 3, 13, 57, '若仍现在衣服上，或是经上、纬上、皮子做的甚么物件上，这就是灾病又发了、必用火焚烧那染灾病的物件。'),
('CUV', '利未记', 3, 13, 58, '所洗的衣服，或是经，或是纬，或是皮子做的甚么物件，若灾病离开了，要再洗，就洁净了。'),
('CUV', '利未记', 3, 13, 59, '这就是大痲疯灾病的条例，无论是在羊毛衣服上，麻布衣服上，经上、纬上，和皮子做的甚么物件上，可以定为洁净或是不洁净。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 14, 1, '耶和华晓谕摩西说：'),
('CUV', '利未记', 3, 14, 2, '长大痲疯得洁净的日子，其例乃是这样：要带他去见祭司；'),
('CUV', '利未记', 3, 14, 3, '祭司要出到营外察看，若见他的大痲疯痊愈了'),
('CUV', '利未记', 3, 14, 4, '就要吩咐人为那求洁净的拿两只洁净的活鸟和香柏木、朱红色线，并牛膝草来。'),
('CUV', '利未记', 3, 14, 5, '祭司要吩咐用瓦器盛活水，把一只鸟宰在上面。'),
('CUV', '利未记', 3, 14, 6, '至于那只活鸟，祭司要把他和香柏木、朱红色线并牛膝草一同蘸于宰在活水上的鸟血中，'),
('CUV', '利未记', 3, 14, 7, '用以在那长大痲疯求洁净的人身上洒七次，就定他为洁净，又把活鸟放在田野里。'),
('CUV', '利未记', 3, 14, 8, '求洁净的人当洗衣服，剃去毛发，用水洗澡，就洁净了；然后可以进营，只是要在自己的帐棚外居住七天。'),
('CUV', '利未记', 3, 14, 9, '第七天，再把头上所有的头发与胡须、眉毛，并全身的毛，都剃了；又要洗衣服，用水洗身，就洁净了。'),
('CUV', '利未记', 3, 14, 10, '第八天，他要取两只没有残疾的公羊羔和一只没有残疾、一岁的母羊羔，又要把调油的细面伊法十分之三为素祭，并油一罗革，一同取来。'),
('CUV', '利未记', 3, 14, 11, '行洁净之礼的祭司要将那求洁净的人和这些东西安置在会幕门口、耶和华面前。'),
('CUV', '利未记', 3, 14, 12, '祭司要取一只公羊羔献为赎愆祭，和那一罗革油一同作摇祭，在耶和华面前摇一摇；'),
('CUV', '利未记', 3, 14, 13, '把公羊羔宰于圣地，就是宰赎罪祭牲和燔祭牲之地。赎愆祭要归祭司，与赎罪祭一样，是至圣的。'),
('CUV', '利未记', 3, 14, 14, '祭司要取些赎愆祭牲的血，抹在求洁净人的右耳垂上和右手的大拇指上，并右脚的大拇指上。'),
('CUV', '利未记', 3, 14, 15, '祭司要从那一罗革油中取些倒在自己的左手掌里，'),
('CUV', '利未记', 3, 14, 16, '把右手的一个指头蘸在左手的油里，在耶和华面前用指头弹七次。'),
('CUV', '利未记', 3, 14, 17, '将手里所剩的油抹在那求洁净人的右耳垂上和右手的大拇指上，并右脚的大拇指上，就是抹在赎愆祭牲的血上。'),
('CUV', '利未记', 3, 14, 18, '祭司手里所剩的油要抹在那求洁净人的头上，在耶和华面前为他赎罪。'),
('CUV', '利未记', 3, 14, 19, '祭司要献赎罪祭，为那本不洁净、求洁净的人赎罪；然后要宰燔祭牲，'),
('CUV', '利未记', 3, 14, 20, '把燔祭和素祭献在坛上，为他赎罪，他就洁净了。'),
('CUV', '利未记', 3, 14, 21, '他若贫穷不能预备够数，就要取一只公羊羔作赎愆祭，可以摇一摇，为他赎罪；也要把调油的细面伊法十分之一为素祭，和油一罗革一同取来；'),
('CUV', '利未记', 3, 14, 22, '又照他的力量取两只斑鸠或是两只雏鸽，一只作赎罪祭，一只作燔祭。'),
('CUV', '利未记', 3, 14, 23, '第八天，要为洁净，把这些带到会幕门口、耶和华面前，交给祭司。'),
('CUV', '利未记', 3, 14, 24, '祭司要把赎愆祭的羊羔和那一罗革油一同作摇祭，在耶和华面前摇一摇。'),
('CUV', '利未记', 3, 14, 25, '要宰了赎愆祭的羊羔，取些赎愆祭牲的血，抹在那求洁净人的右耳垂上和右手的大拇指上，并右脚的大拇指上。'),
('CUV', '利未记', 3, 14, 26, '祭司要把些油倒在自己的左手掌里，'),
('CUV', '利未记', 3, 14, 27, '把左手里的油，在耶和华面前，用右手的一个指头弹七次，'),
('CUV', '利未记', 3, 14, 28, '又把手里的油抹些在那求洁净人的右耳垂上和右手的大拇指上，并右脚的大拇指上，就是抹赎愆祭之血的原处。'),
('CUV', '利未记', 3, 14, 29, '祭司手里所剩的油要抹在那求洁净人的头上，在耶和华面前为他赎罪。'),
('CUV', '利未记', 3, 14, 30, '那人又要照他的力量献上一只斑鸠或是一只雏鸽，'),
('CUV', '利未记', 3, 14, 31, '就是他所能办的，一只为赎罪祭，一只为燔祭，与素祭一同献上；祭司要在耶和华面前为他赎罪。'),
('CUV', '利未记', 3, 14, 32, '这是那有大痲疯灾病的人、不能将关乎得洁净之物预备够数的条例。'),
('CUV', '利未记', 3, 14, 33, '耶和华晓谕摩西、亚伦说：'),
('CUV', '利未记', 3, 14, 34, '你们到了我赐给你们为业的迦南地，我若使你们所得为业之地的房屋中有大痲疯的灾病，'),
('CUV', '利未记', 3, 14, 35, '房主就要去告诉祭司说：据我看，房屋中似乎有灾病。'),
('CUV', '利未记', 3, 14, 36, '祭司还没有进去察看灾病以前，就要吩咐人把房子腾空，免得房子里所有的都成了不洁净；然后祭司要进去察看房子。'),
('CUV', '利未记', 3, 14, 37, '他要察看那灾病，灾病若在房子的墙上有发绿或发红的凹斑纹，现象洼于墙，'),
('CUV', '利未记', 3, 14, 38, '祭司就要出到房门外，把房子封锁七天。'),
('CUV', '利未记', 3, 14, 39, '第七天，祭司要再去察看，灾病若在房子的墙上发散，'),
('CUV', '利未记', 3, 14, 40, '就要吩咐人把那有灾病的石头挖出来，扔在城外不洁净之处；'),
('CUV', '利未记', 3, 14, 41, '也要叫人刮房内的四围，所刮掉的灰泥要倒在城外不洁净之处；'),
('CUV', '利未记', 3, 14, 42, '又要用别的石头代替那挖出来的石头，要另用灰泥墁房子。'),
('CUV', '利未记', 3, 14, 43, '他挖出石头，刮了房子，墁了以后，灾病若在房子里又发现，'),
('CUV', '利未记', 3, 14, 44, '祭司就要进去察看，灾病若在房子里发散，这就是房内蚕食的大痲疯，是不洁净。'),
('CUV', '利未记', 3, 14, 45, '他就要拆毁房子，把石头、木头、灰泥都搬到城外不洁净之处。'),
('CUV', '利未记', 3, 14, 46, '在房子封锁的时候，进去的人必不洁净到晚上；'),
('CUV', '利未记', 3, 14, 47, '在房子里躺著的必洗衣服；在房子里吃饭的也必洗衣服。'),
('CUV', '利未记', 3, 14, 48, '房子墁了以后，祭司若进去察看，见灾病在房内没有发散，就要定房子为洁净，因为灾病已经消除。'),
('CUV', '利未记', 3, 14, 49, '要为洁净房子取两只鸟和香柏木、朱红色线并牛膝草，'),
('CUV', '利未记', 3, 14, 50, '用瓦器盛活水，把一只鸟宰在上面，'),
('CUV', '利未记', 3, 14, 51, '把香柏木、牛膝草、朱红色线，并那活鸟，都蘸在被宰的鸟血中与活水中，用以洒房子七次。'),
('CUV', '利未记', 3, 14, 52, '要用鸟血、活水、活鸟、香柏木、牛膝草，并朱红色线，洁净那房子。'),
('CUV', '利未记', 3, 14, 53, '但要把活鸟放在城外田野里。这样洁净房子（原文是为房子赎罪），房子就洁净了。'),
('CUV', '利未记', 3, 14, 54, '这是为各类大痲疯的灾病和头疥，'),
('CUV', '利未记', 3, 14, 55, '并衣服与房子的大痲疯，'),
('CUV', '利未记', 3, 14, 56, '以及疖子、癣、火斑所立的条例，'),
('CUV', '利未记', 3, 14, 57, '指明何时为洁净，何时为不洁净。这是大痲疯的条例。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 15, 1, '耶和华对摩西、亚伦说：'),
('CUV', '利未记', 3, 15, 2, '你们晓谕以色列人说：人若身患漏症，他因这漏症就不洁净了。'),
('CUV', '利未记', 3, 15, 3, '他患漏症，无论是下流的，是止住的，都是不洁净。'),
('CUV', '利未记', 3, 15, 4, '他所躺的床都为不洁净，所坐的物也为不洁净。'),
('CUV', '利未记', 3, 15, 5, '凡摸那床的，必不洁净到晚上，并要洗衣服，用水洗澡。'),
('CUV', '利未记', 3, 15, 6, '那坐患漏症人所坐之物的，必不洁净到晚上，并要洗衣服，用水洗澡。'),
('CUV', '利未记', 3, 15, 7, '那摸患漏症人身体的，必不洁净到晚上，并要洗衣服，用水洗澡。'),
('CUV', '利未记', 3, 15, 8, '若患漏症人吐在洁净的人身上，那人必不洁净到晚上，并要洗衣服，用水洗澡。'),
('CUV', '利未记', 3, 15, 9, '患漏症人所骑的鞍子也为不洁净。'),
('CUV', '利未记', 3, 15, 10, '凡摸了他身下之物的，必不洁净到晚上；拿了那物的，必不洁净到晚上，并要洗衣服，用水洗澡。'),
('CUV', '利未记', 3, 15, 11, '患漏症的人没有用水涮手，无论摸了谁，谁必不洁净到晚上，并要洗衣服，用水洗澡。'),
('CUV', '利未记', 3, 15, 12, '患漏症人所摸的瓦器就必打破；所摸的一切木器也必用水涮洗。'),
('CUV', '利未记', 3, 15, 13, '患漏症的人痊愈了，就要为洁净自己计算七天，也必洗衣服，用活水洗身，就洁净了。'),
('CUV', '利未记', 3, 15, 14, '第八天，要取两只斑鸠或是两只雏鸽，来到会幕门口、耶和华面前，把鸟交给祭司。'),
('CUV', '利未记', 3, 15, 15, '祭司要献上一只为赎罪祭，一只为燔祭；因那人患的漏症，祭司要在耶和华面前为他赎罪。'),
('CUV', '利未记', 3, 15, 16, '人若梦遗，他必不洁净到晚上，并要用水洗全身。'),
('CUV', '利未记', 3, 15, 17, '无论是衣服是皮子，被精所染，必不洁净到晚上，并要用水洗。'),
('CUV', '利未记', 3, 15, 18, '若男女交合，两个人必不洁净到晚上，并要用水洗澡。'),
('CUV', '利未记', 3, 15, 19, '女人行经，必污秽七天；凡摸他的，必不洁净到晚上。'),
('CUV', '利未记', 3, 15, 20, '女人在污秽之中，凡他所躺的物件都为不洁净，所坐的物件也都不洁净。'),
('CUV', '利未记', 3, 15, 21, '凡摸他床的，必不洁净到晚上，并要洗衣服，用水洗澡。'),
('CUV', '利未记', 3, 15, 22, '凡摸他所坐甚么物件的，必不洁净到晚上，并要洗衣服，用水洗澡。'),
('CUV', '利未记', 3, 15, 23, '在女人的床上，或在他坐的物上，若有别的物件，人一摸了，必不洁净到晚上。'),
('CUV', '利未记', 3, 15, 24, '男人若与那女人同房，染了他的污秽，就要七天不洁净；所躺的床也为不洁净。'),
('CUV', '利未记', 3, 15, 25, '女人若在经期以外患多日的血漏，或是经期过长，有了漏症，他就因这漏症不洁净，与他在经期不洁净一样。'),
('CUV', '利未记', 3, 15, 26, '他在患漏症的日子所躺的床、所坐的物都要看为不洁净，与他月经的时候一样。'),
('CUV', '利未记', 3, 15, 27, '凡摸这些物件的，就为不洁净，必不洁净到晚上，并要洗衣服，用水洗澡。'),
('CUV', '利未记', 3, 15, 28, '女人的漏症若好了，就要计算七天，然后才为洁净。'),
('CUV', '利未记', 3, 15, 29, '第八天，要取两只斑鸠或是两只雏鸽，带到会幕门口给祭司。'),
('CUV', '利未记', 3, 15, 30, '祭司要献一只为赎罪祭，一只为燔祭；因那人血漏不洁，祭司要在耶和华面前为他赎罪。'),
('CUV', '利未记', 3, 15, 31, '你们要这样使以色列人与他们的污秽隔绝，免得他们玷污我的帐幕，就因自己的污秽死亡。'),
('CUV', '利未记', 3, 15, 32, '这是患漏症和梦遗而不洁净的，'),
('CUV', '利未记', 3, 15, 33, '并有月经病的和患漏症的，无论男女，并人与不洁净女人同房的条例。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 16, 1, '亚伦的两个儿子近到耶和华面前死了。死了之后，耶和华晓谕摩西说：'),
('CUV', '利未记', 3, 16, 2, '要告诉你哥哥亚伦，不可随时进圣所的幔子内、到柜上的施恩座前，免得他死亡，因为我要从云中显现在施恩座上。'),
('CUV', '利未记', 3, 16, 3, '亚伦进圣所，要带一只公牛犊为赎罪祭，一只公绵羊为燔祭。'),
('CUV', '利未记', 3, 16, 4, '要穿上细麻布圣内袍，把细麻布裤子穿在身上，腰束细麻布带子，头戴细麻布冠冕；这都是圣服。他要用水洗身，然后穿戴。'),
('CUV', '利未记', 3, 16, 5, '要从以色列会众取两只公山羊为赎罪祭，一只公绵羊为燔祭。'),
('CUV', '利未记', 3, 16, 6, '亚伦要把赎罪祭的公牛奉上，为自己和本家赎罪；'),
('CUV', '利未记', 3, 16, 7, '也要把两只公山羊安置在会幕门口、耶和华面前，'),
('CUV', '利未记', 3, 16, 8, '为那两只羊拈阄，一阄归与耶和华，一阄归与阿撒泻勒。'),
('CUV', '利未记', 3, 16, 9, '亚伦要把那拈阄归与耶和华的羊献为赎罪祭，'),
('CUV', '利未记', 3, 16, 10, '但那拈阄归与阿撒泻勒的羊要活著安置在耶和华面前，用以赎罪，打发人送到旷野去，归与阿撒泻勒。'),
('CUV', '利未记', 3, 16, 11, '亚伦要把赎罪祭的公牛带来宰了，为自己和本家赎罪；'),
('CUV', '利未记', 3, 16, 12, '拿香炉，从耶和华面前的坛上盛满火炭，又拿一捧捣细的香料，都带入幔子内，'),
('CUV', '利未记', 3, 16, 13, '在耶和华面前，把香放在火上，使香的烟云遮掩法柜上的施恩座，免得他死亡；'),
('CUV', '利未记', 3, 16, 14, '也要取些公牛的血，用指头弹在施恩座的东面，又在施恩座的前面弹血七次。'),
('CUV', '利未记', 3, 16, 15, '随后他要宰那为百姓作赎罪祭的公山羊，把羊的血带入幔子内，弹在施恩座的上面和前面，好像弹公牛的血一样。'),
('CUV', '利未记', 3, 16, 16, '他因以色列人诸般的污秽、过犯，就是他们一切的罪愆，当这样在圣所行赎罪之礼，并因会幕在他们污秽之中，也要照样而行。'),
('CUV', '利未记', 3, 16, 17, '他进圣所赎罪的时候，会幕里不可有人，直等到他为自己和本家并以色列全会众赎了罪出来。'),
('CUV', '利未记', 3, 16, 18, '他出来，要到耶和华面前的坛那里，在坛上行赎罪之礼，又要取些公牛的血和公山羊的血，抹在坛上四角的周围；'),
('CUV', '利未记', 3, 16, 19, '也要用指头把血弹在坛上七次，洁净了坛，从坛上除掉以色列人诸般的污秽，使坛成圣。'),
('CUV', '利未记', 3, 16, 20, '亚伦为圣所和会幕并坛献完了赎罪祭，就要把那只活著的公山羊奉上。'),
('CUV', '利未记', 3, 16, 21, '两手按在羊头上，承认以色列人诸般的罪孽过犯，就是他们一切的罪愆，把这罪都归在羊的头上，藉著所派之人的手，送到旷野去。'),
('CUV', '利未记', 3, 16, 22, '要把这羊放在旷野，这羊要担当他们一切的罪孽，带到无人之地。'),
('CUV', '利未记', 3, 16, 23, '亚伦要进会幕，把他进圣所时所穿的细麻布衣服脱下，放在那里，'),
('CUV', '利未记', 3, 16, 24, '又要在圣处用水洗身，穿上衣服，出来，把自己的燔祭和百姓的燔祭献上，为自己和百姓赎罪。'),
('CUV', '利未记', 3, 16, 25, '赎罪祭牲的脂油要在坛上焚烧。'),
('CUV', '利未记', 3, 16, 26, '那放羊归与阿撒泻勒的人要洗衣服，用水洗身，然后进营。'),
('CUV', '利未记', 3, 16, 27, '作赎罪祭的公牛和公山羊的血既带入圣所赎罪，这牛羊就要搬到营外，将皮、肉、粪用火焚烧。'),
('CUV', '利未记', 3, 16, 28, '焚烧的人要洗衣服，用水洗身，然后进营。'),
('CUV', '利未记', 3, 16, 29, '每逢七月初十日，你们要刻苦己心，无论是本地人，是寄居在你们中间的外人，甚么工都不可做；这要作你们永远的定例。'),
('CUV', '利未记', 3, 16, 30, '因在这日要为你们赎罪，使你们洁净。你们要在耶和华面前得以洁净，脱尽一切的罪愆。'),
('CUV', '利未记', 3, 16, 31, '这日你们要守为圣安息日，要刻苦己心；这为永远的定例。'),
('CUV', '利未记', 3, 16, 32, '那受膏、接续他父亲承接圣职的祭司要穿上细麻布的圣衣，行赎罪之礼。'),
('CUV', '利未记', 3, 16, 33, '他要在至圣所和会幕与坛行赎罪之礼，并要为众祭司和会众的百姓赎罪。'),
('CUV', '利未记', 3, 16, 34, '这要作你们永远的定例─就是因以色列人一切的罪，要一年一次为他们赎罪。于是，亚伦照耶和华所吩咐摩西的行了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 17, 1, '耶和华对摩西说：'),
('CUV', '利未记', 3, 17, 2, '你晓谕亚伦和他儿子并以色列众人说，耶和华所吩咐的乃是这样：'),
('CUV', '利未记', 3, 17, 3, '凡以色列家中的人宰公牛，或是绵羊羔，或是山羊，不拘宰于营内营外，'),
('CUV', '利未记', 3, 17, 4, '若未曾牵到会幕门口、耶和华的帐幕前献给耶和华为供物，流血的罪必归到那人身上。他流了血，要从民中剪除。'),
('CUV', '利未记', 3, 17, 5, '这是为要使以色列人把他们在田野里所献的祭带到会幕门口、耶和华面前，交给祭司，献与耶和华为平安祭。'),
('CUV', '利未记', 3, 17, 6, '祭司要把血洒在会幕门口、耶和华的坛上，把脂油焚烧，献给耶和华为馨香的祭。'),
('CUV', '利未记', 3, 17, 7, '他们不可再献祭给他们行邪淫所随从的鬼魔（原文作公山羊）；这要作他们世世代代永远的定例。'),
('CUV', '利未记', 3, 17, 8, '你要晓谕他们说：凡以色列家中的人，或是寄居在他们中间的外人，献燔祭或是平安祭，'),
('CUV', '利未记', 3, 17, 9, '若不带到会幕门口献给耶和华，那人必从民中剪除。'),
('CUV', '利未记', 3, 17, 10, '凡以色列家中的人，或是寄居在他们中间的外人，若吃甚么血，我必向那吃血的人变脸，把他从民中剪除。'),
('CUV', '利未记', 3, 17, 11, '因为活物的生命是在血中。我把这血赐给你们，可以在坛上为你们的生命赎罪；因血里有生命，所以能赎罪。'),
('CUV', '利未记', 3, 17, 12, '因此，我对以色列人说：你们都不可吃血；寄居在你们中间的外人也不可吃血。'),
('CUV', '利未记', 3, 17, 13, '凡以色列人，或是寄居在他们中间的外人，若打猎得了可吃的禽兽，必放出他的血来，用土掩盖。'),
('CUV', '利未记', 3, 17, 14, '论到一切活物的生命，就在血中。所以我对以色列人说：无论甚么活物的血，你们都不可吃，因为一切活物的血就是他的生命。凡吃了血的，必被剪除。'),
('CUV', '利未记', 3, 17, 15, '凡吃自死的，或是被野兽撕裂的，无论是本地人，是寄居的，必不洁净到晚上，都要洗衣服，用水洗身，到了晚上才为洁净。'),
('CUV', '利未记', 3, 17, 16, '但他若不洗衣服，也不洗身，就必担当他的罪孽。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 18, 1, '耶和华对摩西说：'),
('CUV', '利未记', 3, 18, 2, '你晓谕以色列人说：我是耶和华─你们的神。'),
('CUV', '利未记', 3, 18, 3, '你们从前住的埃及地，那里人的行为，你们不可效法，我要领你们到的迦南地，那里人的行为也不可效法，也不可照他们的恶俗行。'),
('CUV', '利未记', 3, 18, 4, '你们要遵我的典章，守我的律例，按此而行。我是耶和华─你们的神。'),
('CUV', '利未记', 3, 18, 5, '所以，你们要守我的律例典章；人若遵行，就必因此活著。我是耶和华。'),
('CUV', '利未记', 3, 18, 6, '你们都不可露骨肉之亲的下体，亲近他们。我是耶和华。'),
('CUV', '利未记', 3, 18, 7, '不可露你母亲的下体，羞辱了你父亲。他是你的母亲，不可露他的下体。'),
('CUV', '利未记', 3, 18, 8, '不可露你继母的下体；这本是你父亲的下体。'),
('CUV', '利未记', 3, 18, 9, '你的姊妹，不拘是异母同父的，是异父同母的，无论是生在家生在外的，都不可露他们的下体。'),
('CUV', '利未记', 3, 18, 10, '不可露你孙女或是外孙女的下体，露了他们的下体就是露了自己的下体。'),
('CUV', '利未记', 3, 18, 11, '你继母从你父亲生的女儿本是你的妹妹，不可露他的下体。'),
('CUV', '利未记', 3, 18, 12, '不可露你姑母的下体；他是你父亲的骨肉之亲。'),
('CUV', '利未记', 3, 18, 13, '不可露你姨母的下体；他是你母亲的骨肉之亲。'),
('CUV', '利未记', 3, 18, 14, '不可亲近你伯叔之妻，羞辱了你伯叔；他是你的伯叔母。'),
('CUV', '利未记', 3, 18, 15, '不可露你儿妇的下体；他是你儿子的妻，不可露他的下体。'),
('CUV', '利未记', 3, 18, 16, '不可露你弟兄妻子的下体；这本是你弟兄的下体。'),
('CUV', '利未记', 3, 18, 17, '不可露了妇人的下体，又露他女儿的下体，也不可娶他孙女或是外孙女，露他们的下体；他们是骨肉之亲，这本是大恶。'),
('CUV', '利未记', 3, 18, 18, '你妻还在的时候，不可另娶他的姊妹作对头，露他的下体。'),
('CUV', '利未记', 3, 18, 19, '女人行经不洁净的时候，不可露他的下体，与他亲近。'),
('CUV', '利未记', 3, 18, 20, '不可与邻舍的妻行淫，玷污自己。'),
('CUV', '利未记', 3, 18, 21, '不可使你的儿女经火归与摩洛，也不可亵渎你神的名。我是耶和华。'),
('CUV', '利未记', 3, 18, 22, '不可与男人苟合，像与女人一样；这本是可憎恶的。'),
('CUV', '利未记', 3, 18, 23, '不可与兽淫合，玷污自己。女人也不可站在兽前，与他淫合；这本是逆性的事。'),
('CUV', '利未记', 3, 18, 24, '在这一切的事上，你们都不可玷污自己；因为我在你们面前所逐出的列邦，在这一切的事上玷污了自己；'),
('CUV', '利未记', 3, 18, 25, '连地也玷污了，所以我追讨那地的罪孽，那地也吐出他的居民。'),
('CUV', '利未记', 3, 18, 26, '故此，你们要守我的律例典章。这一切可憎恶的事，无论是本地人，是寄居在你们中间的外人，都不可行，'),
('CUV', '利未记', 3, 18, 27, '在你们以先居住那地的人行了这一切可憎恶的事，地就玷污了，'),
('CUV', '利未记', 3, 18, 28, '免得你们玷污那地的时候，地就把你们吐出，像吐出在你们以先的国民一样。'),
('CUV', '利未记', 3, 18, 29, '无论甚么人，行了其中可憎的一件事，必从民中剪除。'),
('CUV', '利未记', 3, 18, 30, '所以，你们要守我所吩咐的，免得你们随从那些可憎的恶俗，就是在你们以先的人所常行的，以致玷污了自己。我是耶和华─你们的神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 19, 1, '耶和华对摩西说：'),
('CUV', '利未记', 3, 19, 2, '你晓谕以色列全会众说：你们要圣洁，因为我耶和华─你们的神是圣洁的。'),
('CUV', '利未记', 3, 19, 3, '你们各人都当孝敬父母，也要守我的安息日。我是耶和华─你们的神。'),
('CUV', '利未记', 3, 19, 4, '你们不可偏向虚无的神，也不可为自己铸造神像。我是耶和华─你们的神。'),
('CUV', '利未记', 3, 19, 5, '你们献平安祭给耶和华的时候，要献得可蒙悦纳。'),
('CUV', '利未记', 3, 19, 6, '这祭物要在献的那一天和第二天吃，若有剩到第三天的，就必用火焚烧。'),
('CUV', '利未记', 3, 19, 7, '第三天若再吃，这就为可憎恶的，必不蒙悦纳。'),
('CUV', '利未记', 3, 19, 8, '凡吃的人必担当他的罪孽；因为他亵渎了耶和华的圣物，那人必从民中剪除。'),
('CUV', '利未记', 3, 19, 9, '在你们的地收割庄稼，不可割尽田角，也不可拾取所遗落的。'),
('CUV', '利未记', 3, 19, 10, '不可摘尽葡萄园的果子，也不可拾取葡萄园所掉的果子；要留给穷人和寄居的。我是耶和华你─们的神。'),
('CUV', '利未记', 3, 19, 11, '你们不可偷盗，不可欺骗，也不可彼此说谎。'),
('CUV', '利未记', 3, 19, 12, '不可指著我的名起假誓，亵渎你神的名。我是耶和华。'),
('CUV', '利未记', 3, 19, 13, '不可欺压你的邻舍，也不可抢夺他的物。雇工人的工价，不可在你那里过夜，留到早晨。'),
('CUV', '利未记', 3, 19, 14, '不可咒骂聋子，也不可将绊脚石放在瞎子面前，只要敬畏你的神。我是耶和华。'),
('CUV', '利未记', 3, 19, 15, '你们施行审判，不可行不义；不可偏护穷人，也不可重看有势力的人，只要按著公义审判你的邻舍。'),
('CUV', '利未记', 3, 19, 16, '不可在民中往来搬弄是非，也不可与邻舍为敌，置之于死（原文作流他的血）。我是耶和华。'),
('CUV', '利未记', 3, 19, 17, '不可心里恨你的弟兄；总要指摘你的邻舍，免得因他担罪。'),
('CUV', '利未记', 3, 19, 18, '不可报仇，也不可埋怨你本国的子民，却要爱人如己。我是耶和华。'),
('CUV', '利未记', 3, 19, 19, '你们要守我的律例。不可叫你的牲畜与异类配合；不可用两样搀杂的种种你的地，也不可用两样搀杂的料做衣服穿在身上。'),
('CUV', '利未记', 3, 19, 20, '婢女许配了丈夫，还没有被赎、得释放，人若与他行淫，二人要受刑罚，却不把他们治死，因为婢女还没有得自由。'),
('CUV', '利未记', 3, 19, 21, '那人要把赎愆祭，就是一只公绵羊牵到会幕门口、耶和华面前。'),
('CUV', '利未记', 3, 19, 22, '祭司要用赎愆祭的羊在耶和华面前赎他所犯的罪，他的罪就必蒙赦免。'),
('CUV', '利未记', 3, 19, 23, '你们到了迦南地，栽种各样结果子的树木，就要以所结的果子如未受割礼的一样。三年之久，你们要以这些果子，如未受割礼的，是不可吃的。'),
('CUV', '利未记', 3, 19, 24, '但第四年所结的果子全要成为圣，用以赞美耶和华。'),
('CUV', '利未记', 3, 19, 25, '第五年，你们要吃那树上的果子，好叫树给你们结果子更多。我是耶和华─你们的神。'),
('CUV', '利未记', 3, 19, 26, '你们不可吃带血的物；不可用法术，也不可观兆。'),
('CUV', '利未记', 3, 19, 27, '头的周围不可剃，（周围或作：两鬓）胡须的周围也不可损坏。'),
('CUV', '利未记', 3, 19, 28, '不可为死人用刀划身，也不可在身上刺花纹。我是耶和华。'),
('CUV', '利未记', 3, 19, 29, '不可辱没你的女儿，使他为娼妓，恐怕地上的人专向淫乱，地就满了大恶。'),
('CUV', '利未记', 3, 19, 30, '你们要守我的安息日，敬我的圣所。我是耶和华。'),
('CUV', '利未记', 3, 19, 31, '不可偏向那些交鬼的和行巫术的；不可求问他们，以致被他们玷污了。我是耶和华─你们的神。'),
('CUV', '利未记', 3, 19, 32, '在白发的人面前，你要站起来；也要尊敬老人，又要敬畏你的神。我是耶和华。'),
('CUV', '利未记', 3, 19, 33, '若有外人在你们国中和你同居，就不可欺负他。'),
('CUV', '利未记', 3, 19, 34, '和你们同居的外人，你们要看他如本地人一样，并要爱他如己，因为你们在埃及地也作过寄居的。我是耶和华─你们的神。'),
('CUV', '利未记', 3, 19, 35, '你们施行审判，不可行不义；在尺、秤、升、斗上也是如此。'),
('CUV', '利未记', 3, 19, 36, '要用公道天平、公道法码、公道升斗、公道秤。我是耶和华─你们的神，曾把你们从埃及地领出来的。'),
('CUV', '利未记', 3, 19, 37, '你们要谨守遵行我一切的律例典章。我是耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 20, 1, '耶和华对摩西说：'),
('CUV', '利未记', 3, 20, 2, '你还要晓谕以色列人说：凡以色列人，或是在以色列中寄居的外人，把自己的儿女献给摩洛的，总要治死他；本地人要用石头把他打死。'),
('CUV', '利未记', 3, 20, 3, '我也要向那人变脸，把他从民中剪除；因为他把儿女献给摩洛，玷污我的圣所，亵渎我的圣名。'),
('CUV', '利未记', 3, 20, 4, '那人把儿女献给摩洛，本地人若佯为不见，不把他治死，'),
('CUV', '利未记', 3, 20, 5, '我就要向这人和他的家变脸，把他和一切随他与摩洛行邪淫的人都从民中剪除。'),
('CUV', '利未记', 3, 20, 6, '人偏向交鬼的和行巫术的，随他们行邪淫，我要向那人变脸，把他从民中剪除。'),
('CUV', '利未记', 3, 20, 7, '所以你们要自洁成圣，因为我是耶和华─你们的神。'),
('CUV', '利未记', 3, 20, 8, '你们要谨守遵行我的律例；我是叫你们成圣的耶和华。'),
('CUV', '利未记', 3, 20, 9, '凡咒骂父母的，总要治死他；他咒骂了父母，他的罪要归到他身上。（罪原文作血；本章同）'),
('CUV', '利未记', 3, 20, 10, '与邻舍之妻行淫的，奸夫淫妇都必治死。'),
('CUV', '利未记', 3, 20, 11, '与继母行淫的，就是羞辱了他父亲，总要把他们二人治死，罪要归到他们身上。'),
('CUV', '利未记', 3, 20, 12, '与儿妇同房的，总要把他们二人治死；他们行了逆伦的事，罪要归到他们身上。'),
('CUV', '利未记', 3, 20, 13, '人若与男人苟合，像与女人一样，他们二人行了可憎的事，总要把他们治死，罪要归到他们身上。'),
('CUV', '利未记', 3, 20, 14, '人若娶妻，并娶其母，便是大恶，要把这三人用火焚烧，使你们中间免去大恶。'),
('CUV', '利未记', 3, 20, 15, '人若与兽淫合，总要治死他，也要杀那兽。'),
('CUV', '利未记', 3, 20, 16, '女人若与兽亲近，与他淫合，你要杀那女人和那兽，总要把他们治死，罪要归到他们身上。'),
('CUV', '利未记', 3, 20, 17, '人若娶他的姊妹，无论是异母同父的，是异父同母的，彼此见了下体，这是可耻的事；他们必在本民的眼前被剪除。他露了姊妹的下体，必担当自己的罪孽。'),
('CUV', '利未记', 3, 20, 18, '妇人有月经，若与他同房，露了他的下体，就是露了妇人的血源，妇人也露了自己的血源，二人必从民中剪除。'),
('CUV', '利未记', 3, 20, 19, '不可露姨母或是姑母的下体，这是露了骨肉之亲的下体；二人必担当自己的罪孽。'),
('CUV', '利未记', 3, 20, 20, '人若与伯叔之妻同房，就羞辱了他的伯叔；二人要担当自己的罪，必无子女而死。'),
('CUV', '利未记', 3, 20, 21, '人若娶弟兄之妻，这本是污秽的事，羞辱了他的弟兄；二人必无子女。'),
('CUV', '利未记', 3, 20, 22, '所以，你们要谨守遵行我一切的律例典章，免得我领你们去住的那地把你们吐出。'),
('CUV', '利未记', 3, 20, 23, '我在你们面前所逐出的国民，你们不可随从他们的风俗；因为他们行了这一切的事，所以我厌恶他们。'),
('CUV', '利未记', 3, 20, 24, '但我对你们说过，你们要承受他们的地，就是我要赐给你们为业、流奶与蜜之地。我是耶和华─你们的神，使你们与万民有分别的。'),
('CUV', '利未记', 3, 20, 25, '所以，你们要把洁净和不洁净的禽兽分别出来；不可因我给你们分为不洁净的禽兽，或是滋生在地上的活物，使自己成为可憎恶的。'),
('CUV', '利未记', 3, 20, 26, '你们要归我为圣，因为我─耶和华是圣的，并叫你们与万民有分别，使你们作我的民。'),
('CUV', '利未记', 3, 20, 27, '无论男女，是交鬼的或行巫术的，总要治死他们。人必用石头把他们打死，罪要归到他们身上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 21, 1, '耶和华对摩西说：你告诉亚伦子孙作祭司的说：祭司不可为民中的死人沾染自己，'),
('CUV', '利未记', 3, 21, 2, '除非为他骨肉之亲的父母、儿女、弟兄，'),
('CUV', '利未记', 3, 21, 3, '和未曾出嫁、作处女的姊妹，才可以沾染自己。'),
('CUV', '利未记', 3, 21, 4, '祭司既在民中为首，就不可从俗沾染自己。'),
('CUV', '利未记', 3, 21, 5, '不可使头光秃；不可剃除胡须的周围，也不可用刀划身。'),
('CUV', '利未记', 3, 21, 6, '要归神为圣，不可亵渎神的名；因为耶和华的火祭，就是神的食物，是他们献的，所以他们要成为圣。'),
('CUV', '利未记', 3, 21, 7, '不可娶妓女或被污的女人为妻，也不可娶被休的妇人为妻，因为祭司是归神为圣。'),
('CUV', '利未记', 3, 21, 8, '所以你要使他成圣，因为他奉献你神的食物；你要以他为圣，因为我─使你们成圣的耶和华─是圣的。'),
('CUV', '利未记', 3, 21, 9, '祭司的女儿若行淫辱没自己，就辱没了父亲，必用火将他焚烧。'),
('CUV', '利未记', 3, 21, 10, '在弟兄中作大祭司、头上倒了膏油、又承接圣职，穿了圣衣的，不可蓬头散发，也不可撕裂衣服。'),
('CUV', '利未记', 3, 21, 11, '不可挨近死尸，也不可为父母沾染自己。'),
('CUV', '利未记', 3, 21, 12, '不可出圣所，也不可亵渎神的圣所，因为神膏油的冠冕在他头上。我是耶和华。'),
('CUV', '利未记', 3, 21, 13, '他要娶处女为妻。'),
('CUV', '利未记', 3, 21, 14, '寡妇或是被休的妇人，或是被污为妓的女人，都不可娶；只可娶本民中的处女为妻。'),
('CUV', '利未记', 3, 21, 15, '不可在民中辱没他的儿女，因为我是叫他成圣的耶和华。'),
('CUV', '利未记', 3, 21, 16, '耶和华对摩西说：'),
('CUV', '利未记', 3, 21, 17, '你告诉亚伦说：你世世代代的后裔，凡有残疾的，都不可近前来献他神的食物。'),
('CUV', '利未记', 3, 21, 18, '因为凡有残疾的，无论是瞎眼的、瘸腿的、塌鼻子的、肢体有余的、'),
('CUV', '利未记', 3, 21, 19, '折脚折手的、'),
('CUV', '利未记', 3, 21, 20, '驼背的、矮矬的、眼睛有毛病的、长癣的、长疥的，或是损坏肾子的，都不可近前来。'),
('CUV', '利未记', 3, 21, 21, '祭司亚伦的后裔，凡有残疾的，都不可近前来，将火祭献给耶和华。他有残疾，不可近前来献神的食物。'),
('CUV', '利未记', 3, 21, 22, '神的食物，无论是圣的，至圣的，他都可以吃。'),
('CUV', '利未记', 3, 21, 23, '但不可进到幔子前，也不可就近坛前；因为他有残疾，免得亵渎我的圣所。我是叫他成圣的耶和华。'),
('CUV', '利未记', 3, 21, 24, '于是，摩西晓谕亚伦和亚伦的子孙，并以色列众人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 22, 1, '耶和华对摩西说：'),
('CUV', '利未记', 3, 22, 2, '你吩咐亚伦和他子孙说：要远离以色列人所分别为圣、归给我的圣物，免得亵渎我的圣名。我是耶和华。'),
('CUV', '利未记', 3, 22, 3, '你要对他们说：你们世世代代的后裔，凡身上有污秽、亲近以色列人所分别为圣、归耶和华圣物的，那人必在我面前剪除。我是耶和华。'),
('CUV', '利未记', 3, 22, 4, '亚伦的后裔，凡长大痲疯的，或是有漏症的，不可吃圣物，直等他洁净了。无论谁摸那因死尸不洁净的物（物或作：人），或是遗精的人，'),
('CUV', '利未记', 3, 22, 5, '或是摸甚么使他不洁净的爬物，或是摸那使他不洁净的人（不拘那人有甚么不洁净），'),
('CUV', '利未记', 3, 22, 6, '摸了这些人、物的，必不洁净到晚上；若不用水洗身，就不可吃圣物。'),
('CUV', '利未记', 3, 22, 7, '日落的时候，他就洁净了，然后可以吃圣物，因为这是他的食物。'),
('CUV', '利未记', 3, 22, 8, '自死的或是被野兽撕裂的，他不可吃，因此污秽自己。我是耶和华。'),
('CUV', '利未记', 3, 22, 9, '所以他们要守我所吩咐的，免得轻忽了，因此担罪而死。我是叫他们成圣的耶和华。'),
('CUV', '利未记', 3, 22, 10, '凡外人不可吃圣物；寄居在祭司家的，或是雇工人，都不可吃圣物；'),
('CUV', '利未记', 3, 22, 11, '倘若祭司买人，是他的钱买的，那人就可以吃圣物；生在他家的人也可以吃。'),
('CUV', '利未记', 3, 22, 12, '祭司的女儿若嫁外人，就不可吃举祭的圣物。'),
('CUV', '利未记', 3, 22, 13, '但祭司的女儿若是寡妇，或是被休的，没有孩子，又归回父家，与他青年一样，就可以吃他父亲的食物；只是外人不可吃。'),
('CUV', '利未记', 3, 22, 14, '若有人误吃了圣物，要照圣物的原数加上五分之一交给祭司。'),
('CUV', '利未记', 3, 22, 15, '祭司不可亵渎以色列人所献给耶和华的圣物，'),
('CUV', '利未记', 3, 22, 16, '免得他们在吃圣物上自取罪孽，因为我是叫他们成圣的耶和华。'),
('CUV', '利未记', 3, 22, 17, '耶和华对摩西说：'),
('CUV', '利未记', 3, 22, 18, '你晓谕亚伦和他子孙，并以色列众人说：以色列家中的人，或在以色列中寄居的，凡献供物，无论是所许的愿，是甘心献的，就是献给耶和华作燔祭的，'),
('CUV', '利未记', 3, 22, 19, '要将没有残疾的公牛，或是绵羊，或是山羊献上，如此方蒙悦纳。'),
('CUV', '利未记', 3, 22, 20, '凡有残疾的，你们不可献上，因为这不蒙悦纳。'),
('CUV', '利未记', 3, 22, 21, '凡从牛群或是羊群中，将平安祭献给耶和华，为要还特许的愿，或是作甘心献的，所献的必纯全无残疾的才蒙悦纳。'),
('CUV', '利未记', 3, 22, 22, '瞎眼的、折伤的、残废的、有瘤子的、长癣的、长疥的都不可献给耶和华，也不可在坛上作为火祭献给耶和华。'),
('CUV', '利未记', 3, 22, 23, '无论是公牛是绵羊羔，若肢体有余的，或是缺少的，只可作甘心祭献上；用以还愿，却不蒙悦纳。'),
('CUV', '利未记', 3, 22, 24, '肾子损伤的，或是压碎的，或是破裂的，或是骟了的，不可献给耶和华，在你们的地上也不可这样行。'),
('CUV', '利未记', 3, 22, 25, '这类的物，你们从外人的手，一样也不可接受作你们神的食物献上；因为这些都有损坏，有残疾，不蒙悦纳。'),
('CUV', '利未记', 3, 22, 26, '耶和华晓谕摩西说：'),
('CUV', '利未记', 3, 22, 27, '才生的公牛，或是绵羊或是山羊，七天当跟著母；从第八天以后，可以当供物蒙悦纳，作为耶和华的火祭。'),
('CUV', '利未记', 3, 22, 28, '无论是母牛是母羊，不可同日宰母和子。'),
('CUV', '利未记', 3, 22, 29, '你们献感谢祭给耶和华，要献得可蒙悦纳。'),
('CUV', '利未记', 3, 22, 30, '要当天吃，一点不可留到早晨。我是耶和华。'),
('CUV', '利未记', 3, 22, 31, '你们要谨守遵行我的诫命。我是耶和华。'),
('CUV', '利未记', 3, 22, 32, '你们不可亵渎我的圣名；我在以色列人中，却要被尊为圣。我是叫你们成圣的耶和华，'),
('CUV', '利未记', 3, 22, 33, '把你们从埃及地领出来，作你们的神。我是耶和华。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 23, 1, '耶和华对摩西说：'),
('CUV', '利未记', 3, 23, 2, '你晓谕以色列人说：耶和华的节期，你们要宣告为圣会的节期。'),
('CUV', '利未记', 3, 23, 3, '六日要做工，第七日是圣安息日，当有圣会；你们甚么工都不可做。这是在你们一切的住处向耶和华守的安息日。'),
('CUV', '利未记', 3, 23, 4, '耶和华的节期，就是你们到了日期要宣告为圣会的，乃是这些。'),
('CUV', '利未记', 3, 23, 5, '正月十四日，黄昏的时候，是耶和华的逾越节。'),
('CUV', '利未记', 3, 23, 6, '这月十五日是向耶和华守的无酵节；你们要吃无酵饼七日。'),
('CUV', '利未记', 3, 23, 7, '第一日当有圣会，甚么劳碌的工都不可做；'),
('CUV', '利未记', 3, 23, 8, '要将火祭献给耶和华七日。第七日是圣会，甚么劳碌的工都不可做。'),
('CUV', '利未记', 3, 23, 9, '耶和华对摩西说：'),
('CUV', '利未记', 3, 23, 10, '你晓谕以色列人说：你们到了我赐给你们的地，收割庄稼的时候，要将初熟的庄稼一捆带给祭司。'),
('CUV', '利未记', 3, 23, 11, '他要把这一捆在耶和华面前摇一摇，使你们得蒙悦纳。祭司要在安息日的次日把这捆摇一摇。'),
('CUV', '利未记', 3, 23, 12, '摇这捆的日子，你们要把一岁、没有残疾的公绵羊羔献给耶和华为燔祭。'),
('CUV', '利未记', 3, 23, 13, '同献的素祭，就是调油的细面伊法十分之二，作为馨香的火祭，献给耶和华。同献的奠祭，要酒一欣四分之一。'),
('CUV', '利未记', 3, 23, 14, '无论是饼，是烘的子粒，是新穗子，你们都不可吃，直等到把你们献给神的供物带来的那一天才可以吃。这在你们一切的住处作为世世代代永远的定例。'),
('CUV', '利未记', 3, 23, 15, '你们要从安息日的次日，献禾捆为摇祭的那日算起，要满了七个安息日。'),
('CUV', '利未记', 3, 23, 16, '到第七个安息日的次日，共计五十天，又要将新素祭献给耶和华。'),
('CUV', '利未记', 3, 23, 17, '要从你们的住处取出细面伊法十分之二，加酵，烤成两个摇祭的饼，当作初熟之物献给耶和华。'),
('CUV', '利未记', 3, 23, 18, '又要将一岁、没有残疾的羊羔七只、公牛犊一只、公绵羊两只，和饼一同奉上。这些与同献的素祭和奠祭要作为燔祭献给耶和华，就是作馨香的火祭献给耶和华。'),
('CUV', '利未记', 3, 23, 19, '你们要献一只公山羊为赎罪祭，两只一岁的公绵羊羔为平安祭。'),
('CUV', '利未记', 3, 23, 20, '祭司要把这些和初熟麦子做的饼一同作摇祭，在耶和华面前摇一摇；这是献与耶和华为圣物归给祭司的。'),
('CUV', '利未记', 3, 23, 21, '当这日，你们要宣告圣会；甚么劳碌的工都不可做。这在你们一切的住处作为世世代代永远的定例。'),
('CUV', '利未记', 3, 23, 22, '在你们的地收割庄稼，不可割尽田角，也不可拾取所遗落的；要留给穷人和寄居的。我是耶和华─你们的神。'),
('CUV', '利未记', 3, 23, 23, '耶和华对摩西说：'),
('CUV', '利未记', 3, 23, 24, '你晓谕以色列人说：七月初一，你们要守为圣安息日，要吹角作纪念，当有圣会。'),
('CUV', '利未记', 3, 23, 25, '甚么劳碌的工都不可做；要将火祭献给耶和华。'),
('CUV', '利未记', 3, 23, 26, '耶和华晓谕摩西说：'),
('CUV', '利未记', 3, 23, 27, '七月初十是赎罪日；你们要守为圣会，并要刻苦己心，也要将火祭献给耶和华。'),
('CUV', '利未记', 3, 23, 28, '当这日，甚么工都不可做；因为是赎罪日，要在耶和华─你们的神面前赎罪。'),
('CUV', '利未记', 3, 23, 29, '当这日，凡不刻苦己心的，必从民中剪除。'),
('CUV', '利未记', 3, 23, 30, '凡这日做甚么工的，我必将他从民中除灭。'),
('CUV', '利未记', 3, 23, 31, '你们甚么工都不可做。这在你们一切的住处作为世世代代永远的定例。'),
('CUV', '利未记', 3, 23, 32, '你们要守这日为圣安息日，并要刻苦己心。从这月初九日晚上到次日晚上，要守为安息日。'),
('CUV', '利未记', 3, 23, 33, '耶和华对摩西说：'),
('CUV', '利未记', 3, 23, 34, '你晓谕以色列人说：这七月十五日是住棚节，要在耶和华面前守这节七日。'),
('CUV', '利未记', 3, 23, 35, '第一日当有圣会，甚么劳碌的工都不可做。'),
('CUV', '利未记', 3, 23, 36, '七日内要将火祭献给耶和华。第八日当守圣会，要将火祭献给耶和华。这是严肃会，甚么劳碌的工都不可做。'),
('CUV', '利未记', 3, 23, 37, '这是耶和华的节期，就是你们要宣告为圣会的节期；要将火祭、燔祭、素祭、祭物，并奠祭，各归各日，献给耶和华。'),
('CUV', '利未记', 3, 23, 38, '这是在耶和华的安息日以外，又在你们的供物和所许的愿，并甘心献给耶和华的以外。'),
('CUV', '利未记', 3, 23, 39, '你们收藏了地的出产，就从七月十五日起，要守耶和华的节七日。第一日为圣安息；第八日也为圣安息。'),
('CUV', '利未记', 3, 23, 40, '第一日要拿美好树上的果子和棕树上的枝子，与茂密树的枝条并河旁的柳枝，在耶和华─你们的神面前欢乐七日。'),
('CUV', '利未记', 3, 23, 41, '每年七月间，要向耶和华守这节七日。这为你们世世代代永远的定例。'),
('CUV', '利未记', 3, 23, 42, '你们要住在棚里七日；凡以色列家的人都要住在棚里，'),
('CUV', '利未记', 3, 23, 43, '好叫你们世世代代知道，我领以色列人出埃及地的时候曾使他们住在棚里。我是耶和华─你们的神。'),
('CUV', '利未记', 3, 23, 44, '于是，摩西将耶和华的节期传给以色列人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 24, 1, '耶和华晓谕摩西说：'),
('CUV', '利未记', 3, 24, 2, '要吩咐以色列人，把那为点灯捣成的清橄榄油拿来给你，使灯常常点著。'),
('CUV', '利未记', 3, 24, 3, '在会幕中法柜的幔子外，亚伦从晚上到早晨必在耶和华面前经理这灯。这要作你们世世代代永远的定例。'),
('CUV', '利未记', 3, 24, 4, '他要在耶和华面前常收拾精金灯台上的灯。'),
('CUV', '利未记', 3, 24, 5, '你要取细面，烤成十二个饼，每饼用面伊法十分之二。'),
('CUV', '利未记', 3, 24, 6, '要把饼摆列两行（或作：摞；下同），每行六个，在耶和华面前精金的桌子上；'),
('CUV', '利未记', 3, 24, 7, '又要把净乳香放在每行饼上，作为纪念，就是作为火祭献给耶和华。'),
('CUV', '利未记', 3, 24, 8, '每安息日要常摆在耶和华面前；这为以色列人作永远的约。'),
('CUV', '利未记', 3, 24, 9, '这饼是要给亚伦和他子孙的；他们要在圣处吃，为永远的定例，因为在献给耶和华的火祭中是至圣的。'),
('CUV', '利未记', 3, 24, 10, '有一个以色列妇人的儿子，他父亲是埃及人，一日闲游在以色列人中。这以色列妇人的儿子和一个以色列人在营里争斗。'),
('CUV', '利未记', 3, 24, 11, '这以色列妇人的儿子亵渎了圣名，并且咒诅，就有人把他送到摩西那里。（他母亲名叫示罗密，是但支派底伯利的女儿。）'),
('CUV', '利未记', 3, 24, 12, '他们把那人收在监里，要得耶和华所指示的话。'),
('CUV', '利未记', 3, 24, 13, '耶和华晓谕摩西说：'),
('CUV', '利未记', 3, 24, 14, '把那咒诅圣名的人带到营外。叫听见的人都放手在他头上；全会众就要用石头打死他。'),
('CUV', '利未记', 3, 24, 15, '你要晓谕以色列人说：凡咒诅神的，必担当他的罪。'),
('CUV', '利未记', 3, 24, 16, '那亵渎耶和华名的，必被治死；全会众总要用石头打死他。不管是寄居的是本地人，他亵渎耶和华名的时候，必被治死。'),
('CUV', '利未记', 3, 24, 17, '打死人的，必被治死；'),
('CUV', '利未记', 3, 24, 18, '打死牲畜的，必赔上牲畜，以命偿命。'),
('CUV', '利未记', 3, 24, 19, '人若使他邻舍的身体有残疾，他怎样行，也要照样向他行：'),
('CUV', '利未记', 3, 24, 20, '以伤还伤，以眼还眼，以牙还牙。他怎样叫人的身体有残疾，也要照样向他行。'),
('CUV', '利未记', 3, 24, 21, '打死牲畜的，必赔上牲畜；打死人的，必被治死。'),
('CUV', '利未记', 3, 24, 22, '不管是寄居的是本地人，同归一例。我是耶和华─你们的神。'),
('CUV', '利未记', 3, 24, 23, '于是，摩西晓谕以色列人，他们就把那咒诅圣名的人带到营外，用石头打死。以色列人就照耶和华所吩咐摩西的行了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 25, 1, '耶和华在西乃山对摩西说：'),
('CUV', '利未记', 3, 25, 2, '你晓谕以色列人说：你们到了我所赐你们那地的时候，地就要向耶和华守安息。'),
('CUV', '利未记', 3, 25, 3, '六年要耕种田地，也要修理葡萄园，收藏地的出产。'),
('CUV', '利未记', 3, 25, 4, '第七年，地要守圣安息，就是向耶和华守的安息，不可耕种田地，也不可修理葡萄园。'),
('CUV', '利未记', 3, 25, 5, '遗落自长的庄稼不可收割；没有修理的葡萄树也不可摘取葡萄。这年，地要守圣安息。'),
('CUV', '利未记', 3, 25, 6, '地在安息年所出的，要给你和你的仆人、婢女、雇工人，并寄居的外人当食物。'),
('CUV', '利未记', 3, 25, 7, '这年的土产也要给你的牲畜和你地上的走兽当食物。'),
('CUV', '利未记', 3, 25, 8, '你要计算七个安息年，就是七七年。这便为你成了七个安息年，共是四十九年。'),
('CUV', '利未记', 3, 25, 9, '当年七月初十日，你要大发角声；这日就是赎罪日，要在遍地发出角声。'),
('CUV', '利未记', 3, 25, 10, '第五十年，你们要当作圣年，在遍地给一切的居民宣告自由。这年必为你们的禧年，各人要归自己的产业，各归本家。'),
('CUV', '利未记', 3, 25, 11, '第五十年要作为你们的禧年。这年不可耕种；地中自长的，不可收割；没有修理的葡萄树也不可摘取葡萄。'),
('CUV', '利未记', 3, 25, 12, '因为这是禧年，你们要当作圣年，吃地中自出的土产。'),
('CUV', '利未记', 3, 25, 13, '这禧年，你们各人要归自己的地业。'),
('CUV', '利未记', 3, 25, 14, '你若卖甚么给邻舍，或是从邻舍的手中买甚么，彼此不可亏负。'),
('CUV', '利未记', 3, 25, 15, '你要按禧年以后的年数向邻舍买；他也要按年数的收成卖给你。'),
('CUV', '利未记', 3, 25, 16, '年岁若多，要照数加添价值；年岁若少，要照数减去价值，因为他照收成的数目卖给你。'),
('CUV', '利未记', 3, 25, 17, '你们彼此不可亏负，只要敬畏你们的神，因为我是耶和华─你们的神。'),
('CUV', '利未记', 3, 25, 18, '我的律例，你们要遵行，我的典章，你们要谨守，就可以在那地上安然居住。'),
('CUV', '利未记', 3, 25, 19, '地必出土产，你们就要吃饱，在那地上安然居住。'),
('CUV', '利未记', 3, 25, 20, '你们若说：这第七年我们不耕种，也不收藏土产，吃甚么呢？'),
('CUV', '利未记', 3, 25, 21, '我必在第六年将我所命的福赐给你们，地便生三年的土产。'),
('CUV', '利未记', 3, 25, 22, '第八年，你们要耕种，也要吃陈粮，等到第九年出产收来的时候，你们还吃陈粮。'),
('CUV', '利未记', 3, 25, 23, '地不可永卖，因为地是我的；你们在我面前是客旅，是寄居的。'),
('CUV', '利未记', 3, 25, 24, '在你们所得为业的全地，也要准人将地赎回。'),
('CUV', '利未记', 3, 25, 25, '你的弟兄（弟兄是指本国人说；下同）若渐渐穷乏，卖了几分地业，他至近的亲属就要来把弟兄所卖的赎回。'),
('CUV', '利未记', 3, 25, 26, '若没有能给他赎回的，他自己渐渐富足，能够赎回，'),
('CUV', '利未记', 3, 25, 27, '就要算出卖地的年数，把余剩年数的价值还那买主，自己便归回自己的地业。'),
('CUV', '利未记', 3, 25, 28, '倘若不能为自己得回所卖的，仍要存在买主的手里直到禧年；到了禧年，地业要出买主的手，自己便归回自己的地业。'),
('CUV', '利未记', 3, 25, 29, '人若卖城内的住宅，卖了以后，一年之内可以赎回；在一整年，必有赎回的权柄。'),
('CUV', '利未记', 3, 25, 30, '若在一整年之内不赎回，这城内的房屋就定准永归买主，世世代代为业；在禧年也不得出买主的手。'),
('CUV', '利未记', 3, 25, 31, '但房屋在无城墙的村庄里，要看如乡下的田地一样，可以赎回；到了禧年，都要出买主的手。'),
('CUV', '利未记', 3, 25, 32, '然而利未人所得为业的城邑，其中的房屋，利未人可以随时赎回。'),
('CUV', '利未记', 3, 25, 33, '若是一个利未人不将所卖的房屋赎回，是在所得为业的城内，到了禧年就要出买主的手，因为利未人城邑的房屋是他们在以色列人中的产业。'),
('CUV', '利未记', 3, 25, 34, '只是他们各城郊野之地不可卖，因为是他们永远的产业。'),
('CUV', '利未记', 3, 25, 35, '你的弟兄在你那里若渐渐贫穷，手中缺乏，你就要帮补他，使他与你同住，像外人和寄居的一样。'),
('CUV', '利未记', 3, 25, 36, '不可向他取利，也不可向他多要；只要敬畏你的神，使你的弟兄与你同住。'),
('CUV', '利未记', 3, 25, 37, '你借钱给他，不可向他取利；借粮给他，也不可向他多要。'),
('CUV', '利未记', 3, 25, 38, '我是耶和华─你们的神，曾领你们从埃及地出来，为要把迦南地赐给你们，要作你们的神。'),
('CUV', '利未记', 3, 25, 39, '你的弟兄若在你那里渐渐穷乏，将自己卖给你，不可叫他像奴仆服事你。'),
('CUV', '利未记', 3, 25, 40, '他要在你那里像雇工人和寄居的一样，要服事你直到禧年。'),
('CUV', '利未记', 3, 25, 41, '到了禧年，他和他儿女要离开你，一同出去归回本家，到他祖宗的地业那里去。'),
('CUV', '利未记', 3, 25, 42, '因为他们是我的仆人，是我从埃及地领出来的，不可卖为奴仆。'),
('CUV', '利未记', 3, 25, 43, '不可严严的辖管他，只要敬畏你的神。'),
('CUV', '利未记', 3, 25, 44, '至于你的奴仆、婢女，可以从你四围的国中买。'),
('CUV', '利未记', 3, 25, 45, '并且那寄居在你们中间的外人和他们的家属，在你们地上所生的，你们也可以从其中买人；他们要作你们的产业。'),
('CUV', '利未记', 3, 25, 46, '你们要将他们遗留给你们的子孙为产业，要永远从他们中间拣出奴仆；只是你们的弟兄以色列人，你们不可严严的辖管。'),
('CUV', '利未记', 3, 25, 47, '住在你那里的外人，或是寄居的，若渐渐富足，你的弟兄却渐渐穷乏，将自己卖给那外人，或是寄居的，或是外人的宗族，'),
('CUV', '利未记', 3, 25, 48, '卖了以后，可以将他赎回。无论是他的弟兄，'),
('CUV', '利未记', 3, 25, 49, '或伯叔、伯叔的儿子，本家的近支，都可以赎他。他自己若渐渐富足，也可以自赎。'),
('CUV', '利未记', 3, 25, 50, '他要和买主计算，从卖自己的那年起，算到禧年；所卖的价值照著年数多少，好像工人每年的工价。'),
('CUV', '利未记', 3, 25, 51, '若缺少的年数多，就要按著年数从买价中偿还他的赎价'),
('CUV', '利未记', 3, 25, 52, '若到禧年只缺少几年，就要按著年数和买主计算，偿还他的赎价。'),
('CUV', '利未记', 3, 25, 53, '他和买主同住，要像每年雇的工人，买主不可严严的辖管他。'),
('CUV', '利未记', 3, 25, 54, '他若不这样被赎，到了禧年，要和他的儿女一同出去。'),
('CUV', '利未记', 3, 25, 55, '因为以色列人都是我的仆人，是我从埃及地领出来的。我是耶和华─你们的神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 26, 1, '你们不可做甚么虚无的神像，不可立雕刻的偶像或是柱像，也不可在你们的地上安甚么錾成的石像，向他跪拜，因为我是耶和华─你们的神。'),
('CUV', '利未记', 3, 26, 2, '你们要守我的安息日，敬我的圣所。我是耶和华。'),
('CUV', '利未记', 3, 26, 3, '你们若遵行我的律例，谨守我的诫命，'),
('CUV', '利未记', 3, 26, 4, '我就给你们降下时雨，叫地生出土产，田野的树木结果子。'),
('CUV', '利未记', 3, 26, 5, '你们打粮食要打到摘葡萄的时候，摘葡萄要摘到撒种的时候；并且要吃得饱足，在你们的地上安然居住。'),
('CUV', '利未记', 3, 26, 6, '我要赐平安在你们的地上；你们躺卧，无人惊吓。我要叫恶兽从你们的地上息灭；刀剑也必不经过你们的地。'),
('CUV', '利未记', 3, 26, 7, '你们要追赶仇敌，他们必倒在你们刀下。'),
('CUV', '利未记', 3, 26, 8, '你们五个人要追赶一百人，一百人要追赶一万人；仇敌必倒在你们刀下。'),
('CUV', '利未记', 3, 26, 9, '我要眷顾你们，使你们生养众多，也要与你们坚定所立的约。'),
('CUV', '利未记', 3, 26, 10, '你们要吃陈粮，又因新粮挪开陈粮。'),
('CUV', '利未记', 3, 26, 11, '我要在你们中间立我的帐幕；我的心也不厌恶你们。'),
('CUV', '利未记', 3, 26, 12, '我要在你们中间行走；我要作你们的神，你们要作我的子民。'),
('CUV', '利未记', 3, 26, 13, '我是耶和华─你们的神，曾将你们从埃及地领出来，使你们不作埃及人的奴仆；我也折断你们所负的轭，叫你们挺身而走。'),
('CUV', '利未记', 3, 26, 14, '你们若不听从我，不遵行我的诫命，'),
('CUV', '利未记', 3, 26, 15, '厌弃我的律例，厌恶我的典章，不遵行我一切的诫命，背弃我的约，'),
('CUV', '利未记', 3, 26, 16, '我待你们就要这样：我必命定惊惶，叫眼目干瘪、精神消耗的痨病热病辖制你们。你们也要白白的撒种，因为仇敌要吃你们所种的。'),
('CUV', '利未记', 3, 26, 17, '我要向你们变脸，你们就要败在仇敌面前。恨恶你们的，必辖管你们；无人追赶，你们却要逃跑。'),
('CUV', '利未记', 3, 26, 18, '你们因这些事若还不听从我，我就要为你们的罪加七倍惩罚你们。'),
('CUV', '利未记', 3, 26, 19, '我必断绝你们因势力而有的骄傲，又要使覆你们的天如铁，载你们的地如铜。'),
('CUV', '利未记', 3, 26, 20, '你们要白白的劳力；因为你们的地不出土产，其上的树木也不结果子。'),
('CUV', '利未记', 3, 26, 21, '你们行事若与我反对，不肯听从我，我就要按你们的罪加七倍降灾与你们。'),
('CUV', '利未记', 3, 26, 22, '我也要打发野地的走兽到你们中间，抢吃你们的儿女，吞灭你们的牲畜，使你们的人数减少，道路荒凉。'),
('CUV', '利未记', 3, 26, 23, '你们因这些事若仍不改正归我，行事与我反对，'),
('CUV', '利未记', 3, 26, 24, '我就要行事与你们反对，因你们的罪击打你们七次。'),
('CUV', '利未记', 3, 26, 25, '我又要使刀剑临到你们，报复你们背约的仇；聚集你们在各城内，降瘟疫在你们中间，也必将你们交在仇敌的手中。'),
('CUV', '利未记', 3, 26, 26, '我要折断你们的杖，就是断绝你们的粮。那时，必有十个女人在一个炉子给你们烤饼，按分量秤给你们；你们要吃，也吃不饱。'),
('CUV', '利未记', 3, 26, 27, '你们因这一切的事若不听从我，却行事与我反对，'),
('CUV', '利未记', 3, 26, 28, '我就要发烈怒，行事与你们反对，又因你们的罪惩罚你们七次。'),
('CUV', '利未记', 3, 26, 29, '并且你们要吃儿子的肉，也要吃女儿的肉。'),
('CUV', '利未记', 3, 26, 30, '我又要毁坏你们的邱坛，砍下你们的日像，把你们的尸首扔在你们偶像的身上；我的心也必厌恶你们。'),
('CUV', '利未记', 3, 26, 31, '我要使你们的城邑变为荒凉，使你们的众圣所成为荒场；我也不闻你们馨香的香气。'),
('CUV', '利未记', 3, 26, 32, '我要使地成为荒场，住在其上的仇敌就因此诧异。'),
('CUV', '利未记', 3, 26, 33, '我要把你们散在列邦中；我也要拔刀追赶你们。你们的地要成为荒场；你们的城邑要变为荒凉。'),
('CUV', '利未记', 3, 26, 34, '你们在仇敌之地居住的时候，你们的地荒凉，要享受众安息；正在那时候，地要歇息，享受安息。'),
('CUV', '利未记', 3, 26, 35, '地多时为荒场，就要多时歇息；地这样歇息，是你们住在其上的安息年所不能得的。'),
('CUV', '利未记', 3, 26, 36, '至于你们剩下的人，我要使他们在仇敌之地心惊胆怯。叶子被风吹的响声，要追赶他们；他们要逃避，像人逃避刀剑，无人追赶，却要跌倒。'),
('CUV', '利未记', 3, 26, 37, '无人追赶，他们要彼此撞跌，像在刀剑之前。你们在仇敌面前也必站立不住。'),
('CUV', '利未记', 3, 26, 38, '你们要在列邦中灭亡；仇敌之地要吞吃你们。'),
('CUV', '利未记', 3, 26, 39, '你们剩下的人必因自己的罪孽和祖宗的罪孽在仇敌之地消灭。'),
('CUV', '利未记', 3, 26, 40, '他们要承认自己的罪和他们祖宗的罪，就是干犯我的那罪，并且承认自己行事与我反对，'),
('CUV', '利未记', 3, 26, 41, '我所以行事与他们反对，把他们带到仇敌之地。那时，他们未受割礼的心若谦卑了，他们也服了罪孽的刑罚，'),
('CUV', '利未记', 3, 26, 42, '我就要记念我与雅各所立的约，与以撒所立的约，与亚伯拉罕所立的约，并要记念这地。'),
('CUV', '利未记', 3, 26, 43, '他们离开这地，地在荒废无人的时候就要享受安息。并且他们要服罪孽的刑罚；因为他们厌弃了我的典章，心中厌恶了我的律例。'),
('CUV', '利未记', 3, 26, 44, '虽是这样，他们在仇敌之地，我却不厌弃他们，也不厌恶他们，将他们尽行灭绝，也不背弃我与他们所立的约，因为我是耶和华─他们的神。'),
('CUV', '利未记', 3, 26, 45, '我却要为他们的缘故记念我与他们先祖所立的约。他们的先祖是我在列邦人眼前、从埃及地领出来的，为要作他们的神。我是耶和华。'),
('CUV', '利未记', 3, 26, 46, '这些律例、典章，和法度是耶和华与以色列人在西乃山藉著摩西立的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '利未记', 3, 27, 1, '耶和华对摩西说：'),
('CUV', '利未记', 3, 27, 2, '你晓谕以色列人说：人还特许的愿，被许的人要按你所估的价值归给耶和华。'),
('CUV', '利未记', 3, 27, 3, '你估定的，从二十岁到六十岁的男人，要按圣所的平，估定价银五十舍客勒。'),
('CUV', '利未记', 3, 27, 4, '若是女人，你要估定三十舍客勒。'),
('CUV', '利未记', 3, 27, 5, '若是从五岁到二十岁，男子你要估定二十舍客勒，女子估定十舍客勒。'),
('CUV', '利未记', 3, 27, 6, '若是从一月到五岁，男子你要估定五舍客勒，女子估定三舍客勒。'),
('CUV', '利未记', 3, 27, 7, '若是从六十岁以上，男人你要估定十五舍客勒，女人估定十舍客勒。'),
('CUV', '利未记', 3, 27, 8, '他若贫穷，不能照你所估定的价，就要把他带到祭司面前，祭司要按许愿人的力量估定他的价。'),
('CUV', '利未记', 3, 27, 9, '所许的若是牲畜，就是人献给耶和华为供物的，凡这一类献给耶和华的，都要成为圣。'),
('CUV', '利未记', 3, 27, 10, '人不可改换，也不可更换，或是好的换坏的，或是坏的换好的。若以牲畜更换牲畜，所许的与所换的都要成为圣。'),
('CUV', '利未记', 3, 27, 11, '若牲畜不洁净，是不可献给耶和华为供物的，就要把牲畜安置在祭司面前。'),
('CUV', '利未记', 3, 27, 12, '祭司就要估定价值；牲畜是好是坏，祭司怎样估定，就要以怎样为是。'),
('CUV', '利未记', 3, 27, 13, '他若一定要赎回，就要在你所估定的价值以外加上五分之一。'),
('CUV', '利未记', 3, 27, 14, '人将房屋分别为圣，归给耶和华，祭司就要估定价值。房屋是好是坏，祭司怎样估定，就要以怎样为定。'),
('CUV', '利未记', 3, 27, 15, '将房屋分别为圣的人，若要赎回房屋，就必在你所估定的价值以外加上五分之一，房屋仍旧归他。'),
('CUV', '利未记', 3, 27, 16, '人若将承受为业的几分地分别为圣，归给耶和华，你要按这地撒种多少估定价值，若撒大麦一贺梅珥，要估价五十舍客勒。'),
('CUV', '利未记', 3, 27, 17, '他若从禧年将地分别为圣，就要以你所估定的价为定。'),
('CUV', '利未记', 3, 27, 18, '倘若他在禧年以后将地分别为圣，祭司就要按著未到禧年所剩的年数推算价值，也要从你所估的减去价值。'),
('CUV', '利未记', 3, 27, 19, '将地分别为圣的人若定要把地赎回，他便要在你所估的价值以外加上五分之一，地就准定归他。'),
('CUV', '利未记', 3, 27, 20, '他若不赎回那地，或是将地卖给别人，就再不能赎了。'),
('CUV', '利未记', 3, 27, 21, '但到了禧年，那地从买主手下出来的时候，就要归耶和华为圣，和永献的地一样，要归祭司为业。'),
('CUV', '利未记', 3, 27, 22, '他若将所买的一块地，不是承受为业的，分别为圣归给耶和华，'),
('CUV', '利未记', 3, 27, 23, '祭司就要将你所估的价值给他推算到禧年。当日，他要以你所估的价银为圣，归给耶和华。'),
('CUV', '利未记', 3, 27, 24, '到了禧年，那地要归卖主，就是那承受为业的原主。'),
('CUV', '利未记', 3, 27, 25, '凡你所估定的价银都要按著圣所的平：二十季拉为一舍客勒。'),
('CUV', '利未记', 3, 27, 26, '惟独牲畜中头生的，无论是牛是羊，既归耶和华，谁也不可再分别为圣，因为这是耶和华的。'),
('CUV', '利未记', 3, 27, 27, '若是不洁净的牲畜生的，就要按你所估定的价值加上五分之一赎回；若不赎回，就要按你所估定的价值卖了。'),
('CUV', '利未记', 3, 27, 28, '但一切永献的，就是人从他所有永献给耶和华的，无论是人，是牲畜，是他承受为业的地，都不可卖，也不可赎。凡永献的是归给耶和华为至圣。'),
('CUV', '利未记', 3, 27, 29, '凡从人中当灭的都不可赎，必被治死。'),
('CUV', '利未记', 3, 27, 30, '地上所有的，无论是地上的种子是树上的果子，十分之一是耶和华的，是归给耶和华为圣的。'),
('CUV', '利未记', 3, 27, 31, '人若要赎这十分之一的甚么物，就要加上五分之一。'),
('CUV', '利未记', 3, 27, 32, '凡牛群羊群中，一切从杖下经过的，每第十只要归给耶和华为圣。'),
('CUV', '利未记', 3, 27, 33, '不可问是好是坏，也不可更换；若定要更换，所更换的与本来的牲畜都要成为圣，不可赎回。'),
('CUV', '利未记', 3, 27, 34, '这就是耶和华在西乃山为以色列人所吩咐摩西的命令。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 1, 1, '以色列人出埃及地后，第二年二月初一日，耶和华在西乃的旷野、会幕中晓谕摩西说：'),
('CUV', '民数记', 4, 1, 2, '你要按以色列全会众的家室、宗族、人名的数目计算所有的男丁。'),
('CUV', '民数记', 4, 1, 3, '凡以色列中，从二十岁以外，能出去打仗的，你和亚伦要照他们的军队数点。'),
('CUV', '民数记', 4, 1, 4, '每支派中必有一人作本支派的族长，帮助你们。'),
('CUV', '民数记', 4, 1, 5, '他们的名字：属流便的，有示丢珥的儿子以利蓿；'),
('CUV', '民数记', 4, 1, 6, '属西缅的，有苏利沙代的儿子示路蔑；'),
('CUV', '民数记', 4, 1, 7, '属犹大的，有亚米拿达的儿子拿顺；'),
('CUV', '民数记', 4, 1, 8, '属以萨迦的，有苏押的儿子拿坦业；'),
('CUV', '民数记', 4, 1, 9, '属西布伦的，有希伦的儿子以利押；'),
('CUV', '民数记', 4, 1, 10, '约瑟子孙、属以法莲的，有亚米忽的儿子以利沙玛；属玛拿西的，有比大蓿的儿子迦玛列；'),
('CUV', '民数记', 4, 1, 11, '属便雅悯的，有基多尼的儿子亚比但；'),
('CUV', '民数记', 4, 1, 12, '属但的，有亚米沙代的儿子亚希以谢；'),
('CUV', '民数记', 4, 1, 13, '属亚设的，有俄兰的儿子帕结；'),
('CUV', '民数记', 4, 1, 14, '属迦得的，有丢珥的儿子以利雅萨；'),
('CUV', '民数记', 4, 1, 15, '属拿弗他利的，有以南的儿子亚希拉。'),
('CUV', '民数记', 4, 1, 16, '这都是从会中选召的，各作本支派的首领，都是以色列军中的统领。'),
('CUV', '民数记', 4, 1, 17, '于是，摩西、亚伦带著这些按名指定的人，'),
('CUV', '民数记', 4, 1, 18, '当二月初一日招聚全会众。会众就照他们的家室、宗族、人名的数目，从二十岁以外的，都述说自己的家谱。'),
('CUV', '民数记', 4, 1, 19, '耶和华怎样吩咐摩西，他就怎样在西乃的旷野数点他们。'),
('CUV', '民数记', 4, 1, 20, '以色列的长子，流便子孙的后代，照著家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的男丁，共有四万六千五百名。'),
('CUV', '民数记', 4, 1, 21, 'a'),
('CUV', '民数记', 4, 1, 22, '西缅子孙的后代，照著家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的男丁，共有五万九千三百名。'),
('CUV', '民数记', 4, 1, 23, 'a'),
('CUV', '民数记', 4, 1, 24, '迦得子孙的后代，照著家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有四万五千六百五十名。'),
('CUV', '民数记', 4, 1, 25, 'a'),
('CUV', '民数记', 4, 1, 26, '犹大子孙的后代，照著家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有七万四千六百名。'),
('CUV', '民数记', 4, 1, 27, 'a'),
('CUV', '民数记', 4, 1, 28, '以萨迦子孙的后代，照著家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有五万四千四百名。'),
('CUV', '民数记', 4, 1, 29, 'a'),
('CUV', '民数记', 4, 1, 30, '西布伦子孙的后代，照著家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有五万七千四百名。'),
('CUV', '民数记', 4, 1, 31, 'a'),
('CUV', '民数记', 4, 1, 32, '约瑟子孙属以法莲子孙的后代，照著家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有四万零五百名。'),
('CUV', '民数记', 4, 1, 33, 'a'),
('CUV', '民数记', 4, 1, 34, '玛拿西子孙的后代，照著家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有三万二千二百名。'),
('CUV', '民数记', 4, 1, 35, 'a'),
('CUV', '民数记', 4, 1, 36, '便雅悯子孙的后代，照著家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有三万五千四百名。'),
('CUV', '民数记', 4, 1, 37, 'a'),
('CUV', '民数记', 4, 1, 38, '但子孙的后代，照著家室、宗族、人名的数目，从二十岁以外，凡能出去打仗，被数的，共有六万二千七百名。'),
('CUV', '民数记', 4, 1, 39, 'a'),
('CUV', '民数记', 4, 1, 40, '亚设子孙的后代，照著家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有四万一千五百名。'),
('CUV', '民数记', 4, 1, 41, 'a'),
('CUV', '民数记', 4, 1, 42, '拿弗他利子孙的后代，照著家室、宗族、人名的数目，从二十岁以外，凡能出去打仗、被数的，共有五万三千四百名。'),
('CUV', '民数记', 4, 1, 43, 'a'),
('CUV', '民数记', 4, 1, 44, '这些就是被数点的，是摩西、亚伦，和以色列中十二个首领所数点的；这十二个人各作各宗族的代表。'),
('CUV', '民数记', 4, 1, 45, '这样，凡以色列人中被数的，照著宗族，从二十岁以外，能出去打仗、被数的，共有六十万零三千五百五十名。'),
('CUV', '民数记', 4, 1, 46, 'a'),
('CUV', '民数记', 4, 1, 47, '利未人却没有按著支派数在其中，'),
('CUV', '民数记', 4, 1, 48, '因为耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 1, 49, '惟独利未支派你不可数点，也不可在以色列人中计算他们的总数。'),
('CUV', '民数记', 4, 1, 50, '只要派利未人管法柜的帐幕和其中的器具，并属乎帐幕的；他们要抬帐幕和其中的器具，（抬或作：搬运）并要办理帐幕的事，在帐幕的四围安营。'),
('CUV', '民数记', 4, 1, 51, '帐幕将往前行的时候，利未人要拆卸；将支搭的时候，利未人要竖起。近前来的外人必被治死。'),
('CUV', '民数记', 4, 1, 52, '以色列人支搭帐棚，要照他们的军队，各归本营，各归本纛。'),
('CUV', '民数记', 4, 1, 53, '但利未人要在法柜帐幕的四围安营，免得忿怒临到以色列会众；利未人并要谨守法柜的帐幕。'),
('CUV', '民数记', 4, 1, 54, '以色列人就这样行。凡耶和华所吩咐摩西的，他们就照样行了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 2, 1, '耶和华晓谕摩西、亚伦说：'),
('CUV', '民数记', 4, 2, 2, '以色列人要各归自己的纛下，在本族的旗号那里，对著会幕的四围安营。'),
('CUV', '民数记', 4, 2, 3, '在东边，向日出之地，照著军队安营的是犹大营的纛。有亚米拿达的儿子拿顺作犹大人的首领。'),
('CUV', '民数记', 4, 2, 4, '他军队被数的，共有七万四千六百名。'),
('CUV', '民数记', 4, 2, 5, '挨著他安营的是以萨迦支派。有苏押的儿子拿坦业作以萨迦人的首领。'),
('CUV', '民数记', 4, 2, 6, '他军队被数的，共有五万四千四百名。'),
('CUV', '民数记', 4, 2, 7, '又有西布伦支派。希伦的儿子以利押作西布伦人的首领。'),
('CUV', '民数记', 4, 2, 8, '他军队被数的，共有五万七千四百名。'),
('CUV', '民数记', 4, 2, 9, '凡属犹大营、按著军队被数的，共有十八万六千四百名，要作第一队往前行。'),
('CUV', '民数记', 4, 2, 10, '在南边，按著军队是流便营的纛。有示丢珥的儿子以利蓿作流便人的首领。'),
('CUV', '民数记', 4, 2, 11, '他军队被数的，共有四万六千五百名。'),
('CUV', '民数记', 4, 2, 12, '挨著他安营的是西缅支派。苏利沙代的儿子示路蔑作西缅人的首领。'),
('CUV', '民数记', 4, 2, 13, '他军队被数的，共有五万九千三百名。'),
('CUV', '民数记', 4, 2, 14, '又有迦得支派。丢珥的儿子以利雅萨作迦得人的首领。'),
('CUV', '民数记', 4, 2, 15, '他军队被数的，共有四万五千六百五十名，'),
('CUV', '民数记', 4, 2, 16, '凡属流便营、按著军队被数的，共有十五万一千四百五十名，要作第二队往前行。'),
('CUV', '民数记', 4, 2, 17, '随后，会幕要往前行，有利未营在诸营中间。他们怎样安营就怎样往前行，各按本位，各归本纛。'),
('CUV', '民数记', 4, 2, 18, '在西边，按著军队是以法莲营的纛。亚米忽的儿子以利沙玛作以法莲人的首领。'),
('CUV', '民数记', 4, 2, 19, '他军队被数的，共有四万零五百名。'),
('CUV', '民数记', 4, 2, 20, '挨著他的是玛拿西支派。比大蓿的儿子迦玛列作玛拿西人的首领。'),
('CUV', '民数记', 4, 2, 21, '他军队被数的，共有三万二千二百名。'),
('CUV', '民数记', 4, 2, 22, '又有便雅悯支派。基多尼的儿子亚比但作便雅悯人的首领。'),
('CUV', '民数记', 4, 2, 23, '他军队被数的，共有三万五千四百名。'),
('CUV', '民数记', 4, 2, 24, '凡属以法莲营、按著军队被数的，共有十万零八千一百名，要作第三队往前行。'),
('CUV', '民数记', 4, 2, 25, '在北边，按著军队是但营的纛。亚米沙代的儿子亚希以谢作但人的首领。'),
('CUV', '民数记', 4, 2, 26, '他军队被数的，共有六万二千七百名。'),
('CUV', '民数记', 4, 2, 27, '挨著他安营的是亚设支派。俄兰的儿子帕结作亚设人的首领。'),
('CUV', '民数记', 4, 2, 28, '他军队被数的，共有四万一千五百名。'),
('CUV', '民数记', 4, 2, 29, '又有拿弗他利支派。以南的儿子亚希拉作拿弗他利人的首领。'),
('CUV', '民数记', 4, 2, 30, '他军队被数的，共有五万三千四百名。'),
('CUV', '民数记', 4, 2, 31, '凡但营被数的，共有十五万七千六百名，要归本纛作末队往前行。'),
('CUV', '民数记', 4, 2, 32, '这些以色列人，照他们的宗族，按他们的军队，在诸营中被数的，共有六十万零三千五百五十名。'),
('CUV', '民数记', 4, 2, 33, '惟独利未人没有数在以色列人中，是照耶和华所吩咐摩西的。'),
('CUV', '民数记', 4, 2, 34, '以色列人就这样行，各人照他们的家室、宗族归于本纛，安营起行，都是照耶和华所吩咐摩西的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 3, 1, '耶和华在西乃山晓谕摩西的日子，亚伦和摩西的后代如下：'),
('CUV', '民数记', 4, 3, 2, '亚伦的儿子，长子名叫拿答，还有亚比户、以利亚撒、以他玛。'),
('CUV', '民数记', 4, 3, 3, '这是亚伦儿子的名字，都是受膏的祭司，是摩西叫他们承接圣职供祭司职分的。'),
('CUV', '民数记', 4, 3, 4, '拿答、亚比户在西乃的旷野向耶和华献凡火的时候就死在耶和华面前了。他们也没有儿子。以利亚撒、以他玛在他们的父亲亚伦面前供祭司的职分。'),
('CUV', '民数记', 4, 3, 5, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 3, 6, '你使利未支派近前来，站在祭司亚伦面前好服事他，'),
('CUV', '民数记', 4, 3, 7, '替他和会众在会幕前守所吩咐的，办理帐幕的事。'),
('CUV', '民数记', 4, 3, 8, '又要看守会幕的器具，并守所吩咐以色列人的，办理帐幕的事。'),
('CUV', '民数记', 4, 3, 9, '你要将利未人给亚伦和他的儿子，因为他们是从以色列人中选出来给他的。'),
('CUV', '民数记', 4, 3, 10, '你要嘱咐亚伦和他的儿子谨守自己祭司的职任。近前来的外人必被治死。'),
('CUV', '民数记', 4, 3, 11, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 3, 12, '我从以色列人中拣选了利未人，代替以色列人一切头生的；利未人要归我。'),
('CUV', '民数记', 4, 3, 13, '因为凡头生的是我的；我在埃及地击杀一切头生的那日就把以色列中一切头生的，连人带牲畜都分别为圣归我；他们定要属我。我是耶和华。'),
('CUV', '民数记', 4, 3, 14, '耶和华在西乃的旷野晓谕摩西说：'),
('CUV', '民数记', 4, 3, 15, '你要照利未人的宗族、家室数点他们。凡一个月以外的男子都要数点。'),
('CUV', '民数记', 4, 3, 16, '于是摩西照耶和华所吩咐的数点他们。'),
('CUV', '民数记', 4, 3, 17, '利未众子的名字是革顺、哥辖、米拉利。'),
('CUV', '民数记', 4, 3, 18, '革顺的儿子，按著家室，是立尼、示每。'),
('CUV', '民数记', 4, 3, 19, '哥辖的儿子，按著家室，是暗兰、以斯哈、希伯伦、乌薛。'),
('CUV', '民数记', 4, 3, 20, '米拉利的儿子，按著家室，是抹利、母示。这些按著宗族是利未人的家室。'),
('CUV', '民数记', 4, 3, 21, '属革顺的，有立尼族、示每族。这是革顺的二族。'),
('CUV', '民数记', 4, 3, 22, '其中被数、从一个月以外所有的男子共有七千五百名。'),
('CUV', '民数记', 4, 3, 23, '这革顺的二族要在帐幕后西边安营。'),
('CUV', '民数记', 4, 3, 24, '拉伊勒的儿子以利雅萨作革顺人宗族的首领。'),
('CUV', '民数记', 4, 3, 25, '革顺的子孙在会幕中所要看守的，就是帐幕和罩棚，并罩棚的盖与会幕的门帘，'),
('CUV', '民数记', 4, 3, 26, '院子的帷子和门帘（院子是围帐幕和坛的），并一切使用的绳子。'),
('CUV', '民数记', 4, 3, 27, '属哥辖的，有暗兰族、以斯哈族、希伯伦族、乌薛族。这是哥辖的诸族。'),
('CUV', '民数记', 4, 3, 28, '按所有男子的数目，从一个月以外看守圣所的，共有八千六百名。'),
('CUV', '民数记', 4, 3, 29, '哥辖儿子的诸族要在帐幕的南边安营。'),
('CUV', '民数记', 4, 3, 30, '乌薛的儿子以利撒反作哥辖宗族家室的首领。'),
('CUV', '民数记', 4, 3, 31, '他们所要看守的是约柜、桌子、灯台、两座坛与圣所内使用的器皿，并帘子和一切使用之物。'),
('CUV', '民数记', 4, 3, 32, '祭司亚伦的儿子以利亚撒作利未人众首领的领袖，要监察那些看守圣所的人。'),
('CUV', '民数记', 4, 3, 33, '属米拉利的，有抹利族、母示族。这是米拉利的二族。'),
('CUV', '民数记', 4, 3, 34, '他们被数的，按所有男子的数目，从一个月以外的，共有六千二百名。'),
('CUV', '民数记', 4, 3, 35, '亚比亥的儿子苏列作米拉利二宗族的首领。他们要在帐幕的北边安营。'),
('CUV', '民数记', 4, 3, 36, '米拉利子孙的职分是看守帐幕的板、闩、柱子、带卯的座，和帐幕一切所使用的器具，'),
('CUV', '民数记', 4, 3, 37, '院子四围的柱子、带卯的座、橛子，和绳子。'),
('CUV', '民数记', 4, 3, 38, '在帐幕前东边，向日出之地安营的是摩西、亚伦，和亚伦的儿子。他们看守圣所，替以色列人守耶和华所吩咐的。近前来的外人必被治死。'),
('CUV', '民数记', 4, 3, 39, '凡被数的利未人，就是摩西、亚伦照耶和华吩咐所数的，按著家室，从一个月以外的男子，共有二万二千名。'),
('CUV', '民数记', 4, 3, 40, '耶和华对摩西说：你要从以色列人中数点一个月以外、凡头生的男子，把他们的名字记下。'),
('CUV', '民数记', 4, 3, 41, '我是耶和华。你要拣选利未人归我，代替以色列人所有头生的，也取利未人的牲畜代替以色列所有头生的牲畜。'),
('CUV', '民数记', 4, 3, 42, '摩西就照耶和华所吩咐的把以色列人头生的都数点了。'),
('CUV', '民数记', 4, 3, 43, '按人名的数目，从一个月以外、凡头生的男子，共有二万二千二百七十三名。'),
('CUV', '民数记', 4, 3, 44, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 3, 45, '你拣选利未人代替以色列人所有头生的，也取利未人的牲畜代替以色列人的牲畜。利未人要归我；我是耶和华。'),
('CUV', '民数记', 4, 3, 46, '以色列人中头生的男子比利未人多二百七十三个，必当将他们赎出来。'),
('CUV', '民数记', 4, 3, 47, '你要按人丁，照圣所的平，每人取赎银五舍客勒（一舍客勒是二十季拉），'),
('CUV', '民数记', 4, 3, 48, '把那多余之人的赎银交给亚伦和他的儿子。'),
('CUV', '民数记', 4, 3, 49, '于是摩西从那被利未人所赎以外的人取了赎银。'),
('CUV', '民数记', 4, 3, 50, '从以色列人头生的所取之银，按圣所的平，有一千三百六十五舍客勒。'),
('CUV', '民数记', 4, 3, 51, '摩西照耶和华的话把这赎银给亚伦和他的儿子，正如耶和华所吩咐的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 4, 1, '耶和华晓谕摩西、亚伦说：'),
('CUV', '民数记', 4, 4, 2, '你从利未人中，将哥辖子孙的总数，照他们的家室、宗族，'),
('CUV', '民数记', 4, 4, 3, '从三十岁直到五十岁，凡前来任职、在会幕里办事的，全都计算。'),
('CUV', '民数记', 4, 4, 4, '哥辖子孙在会幕搬运至圣之物，所办的事乃是这样：'),
('CUV', '民数记', 4, 4, 5, '起营的时候，亚伦和他儿子要进去摘下遮掩柜的幔子，用以蒙盖法柜，'),
('CUV', '民数记', 4, 4, 6, '又用海狗皮盖在上头，再蒙上纯蓝色的毯子，把杠穿上。'),
('CUV', '民数记', 4, 4, 7, '又用蓝色毯子铺在陈设饼的桌子上，将盘子、调羹、奠酒的爵，和杯摆在上头。桌子上也必有常设的饼。'),
('CUV', '民数记', 4, 4, 8, '在其上又要蒙朱红色的毯子，再蒙上海狗皮，把杠穿上。'),
('CUV', '民数记', 4, 4, 9, '要拿蓝色毯子，把灯台和灯台上所用的灯盏、剪子、蜡花盘，并一切盛油的器皿，全都遮盖。'),
('CUV', '民数记', 4, 4, 10, '又要把灯台和灯台的一切器具包在海狗皮里，放在抬架上。'),
('CUV', '民数记', 4, 4, 11, '在金坛上要铺蓝色毯子，蒙上海狗皮，把杠穿上。'),
('CUV', '民数记', 4, 4, 12, '又要把圣所用的一切器具包在蓝色毯子里，用海狗皮蒙上，放在抬架上。'),
('CUV', '民数记', 4, 4, 13, '要收去坛上的灰，把紫色毯子铺在坛上；'),
('CUV', '民数记', 4, 4, 14, '又要把所用的一切器具，就是火鼎、肉锸子、铲子、盘子，一切属坛的器具都摆在坛上，又蒙上海狗皮，把杠穿上。'),
('CUV', '民数记', 4, 4, 15, '将要起营的时候，亚伦和他儿子把圣所和圣所的一切器具遮盖完了，哥辖的子孙就要来抬，只是不可摸圣物，免得他们死亡。会幕里这些物件是哥辖子孙所当抬的。'),
('CUV', '民数记', 4, 4, 16, '祭司亚伦的儿子以利亚撒所要看守的是点灯的油与香料，并当献的素祭和膏油，也要看守全帐幕与其中所有的，并圣所和圣所的器具。'),
('CUV', '民数记', 4, 4, 17, '耶和华晓谕摩西、亚伦说：'),
('CUV', '民数记', 4, 4, 18, '你们不可将哥辖人的支派从利未人中剪除。'),
('CUV', '民数记', 4, 4, 19, '他们挨近至圣物的时候，亚伦和他儿子要进去派他们各人所当办的，所当抬的。这样待他们，好使他们活著，不至死亡。'),
('CUV', '民数记', 4, 4, 20, '只是他们连片时不可进去观看圣所，免得他们死亡。'),
('CUV', '民数记', 4, 4, 21, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 4, 22, '你要将革顺子孙的总数，照著宗族、家室，'),
('CUV', '民数记', 4, 4, 23, '从三十岁直到五十岁，凡前来任职、在会幕里办事的，全都数点。'),
('CUV', '民数记', 4, 4, 24, '革顺人各族所办的事、所抬的物乃是这样：'),
('CUV', '民数记', 4, 4, 25, '他们要抬帐幕的幔子和会幕，并会幕的盖与其上的海狗皮，和会幕的门帘，'),
('CUV', '民数记', 4, 4, 26, '院子的帷子和门帘（院子是围帐幕和坛的）、绳子，并所用的器具，不论是做甚么用的，他们都要经理。'),
('CUV', '民数记', 4, 4, 27, '革顺的子孙在一切抬物办事之上都要凭亚伦和他儿子的吩咐；他们所当抬的，要派他们看守。'),
('CUV', '民数记', 4, 4, 28, '这是革顺子孙的各族在会幕里所办的事；他们所看守的，必在祭司亚伦儿子以他玛的手下。'),
('CUV', '民数记', 4, 4, 29, '至于米拉利的子孙，你要照著家室、宗族把他们数点。'),
('CUV', '民数记', 4, 4, 30, '从三十岁直到五十岁，凡前来任职、在会幕里办事的，你都要数点。'),
('CUV', '民数记', 4, 4, 31, '他们办理会幕的事，就是抬帐幕的板、闩、柱子，和带卯的座，'),
('CUV', '民数记', 4, 4, 32, '院子四围的柱子和其上带卯的座、橛子、绳子，并一切使用的器具。他们所抬的器具，你们要按名指定。'),
('CUV', '民数记', 4, 4, 33, '这是米拉利子孙各族在会幕里所办的事，都在祭司亚伦儿子以他玛的手下。'),
('CUV', '民数记', 4, 4, 34, '摩西、亚伦与会众的诸首领将哥辖的子孙，照著家室、宗族，'),
('CUV', '民数记', 4, 4, 35, '从三十岁直到五十岁，凡前来任职、在会幕里办事的，都数点了。'),
('CUV', '民数记', 4, 4, 36, '被数的共有二千七百五十名。'),
('CUV', '民数记', 4, 4, 37, '这是哥辖各族中被数的，是在会幕里办事的，就是摩西、亚伦照耶和华藉摩西所吩咐数点的。'),
('CUV', '民数记', 4, 4, 38, '革顺子孙被数的，照著家室、宗族，'),
('CUV', '民数记', 4, 4, 39, '从三十岁直到五十岁，凡前来任职、在会幕里办事的，共有二千六百三十名。'),
('CUV', '民数记', 4, 4, 40, 'a'),
('CUV', '民数记', 4, 4, 41, '这是革顺子孙各族中被数的，是在会幕里办事的，就是摩西、亚伦照耶和华藉摩西所吩咐数点的。'),
('CUV', '民数记', 4, 4, 42, '米拉利子孙中各族被数的，照著家室、宗族，'),
('CUV', '民数记', 4, 4, 43, '从三十岁直到五十岁，凡前来任职、在会幕里办事的，共有三千二百名。'),
('CUV', '民数记', 4, 4, 44, 'a'),
('CUV', '民数记', 4, 4, 45, '这是米拉利子孙各族中被数的，就是摩西、亚伦照耶和华藉摩西所吩咐数点的。'),
('CUV', '民数记', 4, 4, 46, '凡被数的利未人，就是摩西、亚伦并以色列众首领，照著家室、宗族所数点的，'),
('CUV', '民数记', 4, 4, 47, '从三十岁直到五十岁，凡前来任职、在会幕里做抬物之工的，共有八千五百八十名。'),
('CUV', '民数记', 4, 4, 48, 'a'),
('CUV', '民数记', 4, 4, 49, '摩西按他们所办的事、所抬的物，凭耶和华的吩咐数点他们；他们这样被摩西数点，正如耶和华所吩咐他的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 5, 1, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 5, 2, '你吩咐以色列人，使一切长大痲疯的，患漏症的，并因死尸不洁净的，都出营外去。'),
('CUV', '民数记', 4, 5, 3, '无论男女都要使他们出到营外，免得污秽他们的营；这营是我所住的。'),
('CUV', '民数记', 4, 5, 4, '以色列人就这样行，使他们出到营外。耶和华怎样吩咐摩西，以色列人就怎样行了。'),
('CUV', '民数记', 4, 5, 5, '耶和华对摩西说：'),
('CUV', '民数记', 4, 5, 6, '你晓谕以色列人说：无论男女，若犯了人所常犯的罪，以至干犯耶和华，那人就有了罪。'),
('CUV', '民数记', 4, 5, 7, '他要承认所犯的罪，将所亏负人的，如数赔还，另外加上五分之一，也归与所亏负的人。'),
('CUV', '民数记', 4, 5, 8, '那人若没有亲属可受所赔还的，那所赔还的就要归与服事耶和华的祭司；至于那为他赎罪的公羊是在外。'),
('CUV', '民数记', 4, 5, 9, '以色列人一切的圣物中，所奉给祭司的举祭都要归与祭司。'),
('CUV', '民数记', 4, 5, 10, '各人所分别为圣的物，无论是甚么，都要归给祭司。'),
('CUV', '民数记', 4, 5, 11, '耶和华对摩西说：'),
('CUV', '民数记', 4, 5, 12, '你晓谕以色列人说：人的妻若有邪行，得罪他丈夫，'),
('CUV', '民数记', 4, 5, 13, '有人与他行淫，事情严密，瞒过他丈夫，而且他被玷污，没有作见证的人，当他行淫的时候也没有被捉住，'),
('CUV', '民数记', 4, 5, 14, '他丈夫生了疑恨的心，疑恨他，他是被玷污，或是他丈夫生了疑恨的心，疑恨他，他并没有被玷污，'),
('CUV', '民数记', 4, 5, 15, '这人就要将妻送到祭司那里，又为他带著大麦面伊法十分之一作供物，不可浇上油，也不可加上乳香；因为这是疑恨的素祭，是思念的素祭，使人思念罪孽。'),
('CUV', '民数记', 4, 5, 16, '祭司要使那妇人近前来，站在耶和华面前。'),
('CUV', '民数记', 4, 5, 17, '祭司要把圣水盛在瓦器里，又从帐幕的地上取点尘土，放在水中。'),
('CUV', '民数记', 4, 5, 18, '祭司要叫那妇人蓬头散发，站在耶和华面前，把思念的素祭，就是疑恨的素祭，放在他手中。祭司手里拿著致咒诅的苦水，'),
('CUV', '民数记', 4, 5, 19, '要叫妇人起誓，对他说：若没有人与你行淫，也未曾背著丈夫做污秽的事，你就免受这致咒诅苦水的灾。'),
('CUV', '民数记', 4, 5, 20, '你若背著丈夫行了污秽的事，在你丈夫以外有人与你行淫，'),
('CUV', '民数记', 4, 5, 21, '（祭司叫妇人发咒起誓），愿耶和华叫你大腿消瘦，肚腹发胀，使你在你民中被人咒诅，成了誓语；'),
('CUV', '民数记', 4, 5, 22, '并且这致咒诅的水入你的肠中，要叫你的肚腹发胀，大腿消瘦。妇人要回答说：阿们，阿们。'),
('CUV', '民数记', 4, 5, 23, '祭司要写这咒诅的话，将所写的字抹在苦水里，'),
('CUV', '民数记', 4, 5, 24, '又叫妇人喝这致咒诅的苦水；这水要进入他里面变苦了。'),
('CUV', '民数记', 4, 5, 25, '祭司要从妇人的手中取那疑恨的素祭，在耶和华面前摇一摇，拿到坛前；'),
('CUV', '民数记', 4, 5, 26, '又要从素祭中取出一把，作为这事的纪念，烧在坛上，然后叫妇人喝这水。'),
('CUV', '民数记', 4, 5, 27, '叫他喝了以后，他若被玷污，得罪了丈夫，这致咒诅的水必进入他里面变苦了，他的肚腹就要发胀，大腿就要消瘦，那妇人便要在他民中被人咒诅。'),
('CUV', '民数记', 4, 5, 28, '若妇人没有被玷污，却是清洁的，就要免受这灾，且要怀孕。'),
('CUV', '民数记', 4, 5, 29, '妻子背著丈夫行了污秽的事，'),
('CUV', '民数记', 4, 5, 30, '或是人生了疑恨的心，疑恨他的妻，就有这疑恨的条例。那时他要叫妇人站在耶和华面前，祭司要在他身上照这条例而行。'),
('CUV', '民数记', 4, 5, 31, '男人就为无罪，妇人必担当自己的罪孽。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 6, 1, '耶和华对摩西说：'),
('CUV', '民数记', 4, 6, 2, '你晓谕以色列人说：无论男女许了特别的愿，就是拿细耳人的愿（拿细耳就是归主的意思；下同），要离俗归耶和华。'),
('CUV', '民数记', 4, 6, 3, '他就要远离清酒浓酒，也不可喝甚么清酒浓酒做的醋；不可喝甚么葡萄汁，也不可吃鲜葡萄和干葡萄。'),
('CUV', '民数记', 4, 6, 4, '在一切离俗的日子，凡葡萄树上结的，自核至皮所做的物，都不可吃。'),
('CUV', '民数记', 4, 6, 5, '在他一切许愿离俗的日子，不可用剃头刀剃头，要由发绺长长了。他要圣洁，直到离俗归耶和华的日子满了。'),
('CUV', '民数记', 4, 6, 6, '在他离俗归耶和华的一切日子，不可挨近死尸。'),
('CUV', '民数记', 4, 6, 7, '他的父母或是弟兄姊妹死了的时候，他不可因他们使自己不洁净，因为那离俗归神的凭据是在他头上。'),
('CUV', '民数记', 4, 6, 8, '在他一切离俗的日子是归耶和华为圣。'),
('CUV', '民数记', 4, 6, 9, '若在他旁边忽然有人死了，以至沾染了他离俗的头，他要在第七日，得洁净的时候，剃头。'),
('CUV', '民数记', 4, 6, 10, '第八日，他要把两只斑鸠或两只雏鸽带到会幕门口，交给祭司。'),
('CUV', '民数记', 4, 6, 11, '祭司要献一只作赎罪祭，一只作燔祭，为他赎那因死尸而有的罪，并要当日使他的头成为圣洁。'),
('CUV', '民数记', 4, 6, 12, '他要另选离俗归耶和华的日子，又要牵一只一岁的公羊羔来作赎愆祭；但先前的日子要归徒然，因为他在离俗之间被玷污了。'),
('CUV', '民数记', 4, 6, 13, '拿细耳人满了离俗的日子乃有这条例：人要领他到会幕门口，'),
('CUV', '民数记', 4, 6, 14, '他要将供物奉给耶和华，就是一只没有残疾、一岁的公羊羔作燔祭，一只没有残疾、一岁的母羊羔作赎罪祭，和一只没有残疾的公绵羊作平安祭，'),
('CUV', '民数记', 4, 6, 15, '并一筐子无酵调油的细面饼，与抹油的无酵薄饼，并同献的素祭和奠祭。'),
('CUV', '民数记', 4, 6, 16, '祭司要在耶和华面前献那人的赎罪祭和燔祭；'),
('CUV', '民数记', 4, 6, 17, '也要把那只公羊和那筐无酵饼献给耶和华作平安祭，又要将同献的素祭和奠祭献上。'),
('CUV', '民数记', 4, 6, 18, '拿细耳人要在会幕门口剃离俗的头，把离俗头上的发放在平安祭下的火上。'),
('CUV', '民数记', 4, 6, 19, '他剃了以后，祭司就要取那已煮的公羊一条前腿，又从筐子里取一个无酵饼和一个无酵薄饼，都放在他手上。'),
('CUV', '民数记', 4, 6, 20, '祭司要拿这些作为摇祭，在耶和华面前摇一摇；这与所摇的胸、所举的腿同为圣物，归给祭司。然后拿细耳人可以喝酒。'),
('CUV', '民数记', 4, 6, 21, '许愿的拿细耳人为离俗所献的供物，和他以外所能得的献给耶和华，就有这条例。他怎样许愿就当照离俗的条例行。'),
('CUV', '民数记', 4, 6, 22, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 6, 23, '你告诉亚伦和他儿子说：你们要这样为以色列人祝福，说：'),
('CUV', '民数记', 4, 6, 24, '愿耶和华赐福给你，保护你。'),
('CUV', '民数记', 4, 6, 25, '愿耶和华使他的脸光照你，赐恩给你。'),
('CUV', '民数记', 4, 6, 26, '愿耶和华向你仰脸，赐你平安。'),
('CUV', '民数记', 4, 6, 27, '他们要如此奉我的名为以色列人祝福；我也要赐福给他们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 7, 1, '摩西立完了帐幕，就把帐幕用膏抹了，使他成圣，又把其中的器具和坛，并坛上的器具，都抹了，使他成圣。'),
('CUV', '民数记', 4, 7, 2, '当天，以色列的众首领，就是各族的族长，都来奉献。他们是各支派的首领，管理那些被数的人。'),
('CUV', '民数记', 4, 7, 3, '他们把自己的供物送到耶和华面前，就是六辆篷子车和十二只公牛。每两个首领奉献一辆车，每首领奉献一只牛。他们把这些都奉到帐幕前。'),
('CUV', '民数记', 4, 7, 4, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 7, 5, '你要收下这些，好作会幕的使用，都要照利未人所办的事交给他们。'),
('CUV', '民数记', 4, 7, 6, '于是摩西收了车和牛，交给利未人，'),
('CUV', '民数记', 4, 7, 7, '把两辆车，四只牛，照革顺子孙所办的事交给他们，'),
('CUV', '民数记', 4, 7, 8, '又把四辆车，八只牛，照米拉利子孙所办的事交给他们；他们都在祭司亚伦的儿子以他玛手下。'),
('CUV', '民数记', 4, 7, 9, '但车与牛都没有交给哥辖子孙；因为他们办的是圣所的事，在肩头上抬圣物。'),
('CUV', '民数记', 4, 7, 10, '用膏抹坛的日子，首领都来行奉献坛的礼，众首领就在坛前献供物。'),
('CUV', '民数记', 4, 7, 11, '耶和华对摩西说：众首领为行奉献坛的礼，要每天一个首领来献供物。'),
('CUV', '民数记', 4, 7, 12, '头一日献供物的是犹大支派的亚米拿达的儿子拿顺。'),
('CUV', '民数记', 4, 7, 13, '他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；'),
('CUV', '民数记', 4, 7, 14, '一个金盂，重十舍客勒，盛满了香；'),
('CUV', '民数记', 4, 7, 15, '一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；'),
('CUV', '民数记', 4, 7, 16, '一只公山羊作赎罪祭；'),
('CUV', '民数记', 4, 7, 17, '两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是亚米拿达儿子拿顺的供物。'),
('CUV', '民数记', 4, 7, 18, '第二日来献的是以萨迦子孙的首领、苏押的儿子拿坦业。'),
('CUV', '民数记', 4, 7, 19, '他献为供物的是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；'),
('CUV', '民数记', 4, 7, 20, '一个金盂，重十舍客勒，盛满了香；'),
('CUV', '民数记', 4, 7, 21, '一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；'),
('CUV', '民数记', 4, 7, 22, '一只公山羊作赎罪祭；'),
('CUV', '民数记', 4, 7, 23, '两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是苏押儿子拿坦业的供物。'),
('CUV', '民数记', 4, 7, 24, '第三日来献的是西布伦子孙的首领、希伦的儿子以利押。'),
('CUV', '民数记', 4, 7, 25, '他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；'),
('CUV', '民数记', 4, 7, 26, '一个金盂，重十舍客勒，盛满了香；'),
('CUV', '民数记', 4, 7, 27, '一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；'),
('CUV', '民数记', 4, 7, 28, '一只公山羊作赎罪祭；'),
('CUV', '民数记', 4, 7, 29, '两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是希伦儿子以利押的供物。'),
('CUV', '民数记', 4, 7, 30, '第四日来献的是流便子孙的首领、示丢珥的儿子以利蓿。'),
('CUV', '民数记', 4, 7, 31, '他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；'),
('CUV', '民数记', 4, 7, 32, '一个金盂，重十舍客勒，盛满了香；'),
('CUV', '民数记', 4, 7, 33, '一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；'),
('CUV', '民数记', 4, 7, 34, '一只公山羊作赎罪祭；'),
('CUV', '民数记', 4, 7, 35, '两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是示丢珥的儿子以利蓿的供物。'),
('CUV', '民数记', 4, 7, 36, '第五日来献的是西缅子孙的首领、苏利沙代的儿子示路蔑。'),
('CUV', '民数记', 4, 7, 37, '他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；'),
('CUV', '民数记', 4, 7, 38, '一个金盂，重十舍客勒，盛满了香；'),
('CUV', '民数记', 4, 7, 39, '一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；'),
('CUV', '民数记', 4, 7, 40, '一只公山羊作赎罪祭；'),
('CUV', '民数记', 4, 7, 41, '两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是苏利沙代儿子示路蔑的供物。'),
('CUV', '民数记', 4, 7, 42, '第六日来献的是迦得子孙的首领、丢珥的儿子以利雅萨。'),
('CUV', '民数记', 4, 7, 43, '他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；'),
('CUV', '民数记', 4, 7, 44, '一个金盂，重十舍客勒，盛满了香；'),
('CUV', '民数记', 4, 7, 45, '一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；'),
('CUV', '民数记', 4, 7, 46, '一只公山羊作赎罪祭；'),
('CUV', '民数记', 4, 7, 47, '两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是丢珥的儿子以利雅萨的供物。'),
('CUV', '民数记', 4, 7, 48, '第七日来献的是以法莲子孙的首领、亚米忽的儿子以利沙玛。'),
('CUV', '民数记', 4, 7, 49, '他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；'),
('CUV', '民数记', 4, 7, 50, '一个金盂，重十舍客勒，盛满了香；'),
('CUV', '民数记', 4, 7, 51, '一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；'),
('CUV', '民数记', 4, 7, 52, '一只公山羊作赎罪祭；'),
('CUV', '民数记', 4, 7, 53, '两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是亚米忽儿子以利沙玛的供物。'),
('CUV', '民数记', 4, 7, 54, '第八日来献的是玛拿西子孙的首领、比大蓿的儿子迦玛列。'),
('CUV', '民数记', 4, 7, 55, '他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；'),
('CUV', '民数记', 4, 7, 56, '一个金盂，重十舍客勒，盛满了香；'),
('CUV', '民数记', 4, 7, 57, '一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；'),
('CUV', '民数记', 4, 7, 58, '一只公山羊作赎罪祭；'),
('CUV', '民数记', 4, 7, 59, '两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是比大蓿儿子迦玛列的供物。'),
('CUV', '民数记', 4, 7, 60, '第九日来献的是便雅悯子孙的首领、基多尼的儿子亚比但。'),
('CUV', '民数记', 4, 7, 61, '他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；'),
('CUV', '民数记', 4, 7, 62, '一个金盂，重十舍客勒，盛满了香；'),
('CUV', '民数记', 4, 7, 63, '一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；'),
('CUV', '民数记', 4, 7, 64, '一只公山羊作赎罪祭；'),
('CUV', '民数记', 4, 7, 65, '两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是基多尼儿子亚比但的供物。'),
('CUV', '民数记', 4, 7, 66, '第十日来献的是但子孙的首领、亚米沙代的儿子亚希以谢。'),
('CUV', '民数记', 4, 7, 67, '他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；'),
('CUV', '民数记', 4, 7, 68, '一个金盂，重十舍客勒，盛满了香；'),
('CUV', '民数记', 4, 7, 69, '一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；'),
('CUV', '民数记', 4, 7, 70, '一只公山羊作赎罪祭；'),
('CUV', '民数记', 4, 7, 71, '两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是亚米沙代儿子亚希以谢的供物。'),
('CUV', '民数记', 4, 7, 72, '第十一日来献的是亚设子孙的首领、俄兰的儿子帕结。'),
('CUV', '民数记', 4, 7, 73, '他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；'),
('CUV', '民数记', 4, 7, 74, '一个金盂，重十舍客勒，盛满了香；'),
('CUV', '民数记', 4, 7, 75, '一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；'),
('CUV', '民数记', 4, 7, 76, '一只公山羊作赎罪祭；'),
('CUV', '民数记', 4, 7, 77, '两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是俄兰儿子帕结的供物。'),
('CUV', '民数记', 4, 7, 78, '第十二日来献的是拿弗他利子孙的首领、以南儿子亚希拉。'),
('CUV', '民数记', 4, 7, 79, '他的供物是：一个银盘子，重一百三十舍客勒，一个银碗，重七十舍客勒，都是按圣所的平，也都盛满了调油的细面作素祭；'),
('CUV', '民数记', 4, 7, 80, '一个金盂，重十舍客勒，盛满了香；'),
('CUV', '民数记', 4, 7, 81, '一只公牛犊，一只公绵羊，一只一岁的公羊羔作燔祭；'),
('CUV', '民数记', 4, 7, 82, '一只公山羊作赎罪祭；'),
('CUV', '民数记', 4, 7, 83, '两只公牛，五只公绵羊，五只公山羊，五只一岁的公羊羔作平安祭。这是以南儿子亚希拉的供物。'),
('CUV', '民数记', 4, 7, 84, '用膏抹坛的日子，以色列的众首领为行献坛之礼所献的是：银盘子十二个，银碗十二个，金盂十二个；'),
('CUV', '民数记', 4, 7, 85, '每盘子重一百三十舍客勒，每碗重七十舍客勒。一切器皿的银子，按圣所的平，共有二千四百舍客勒。'),
('CUV', '民数记', 4, 7, 86, '十二个金盂盛满了香，按圣所的平，每盂重十舍客勒，所有的金子共一百二十舍客勒。'),
('CUV', '民数记', 4, 7, 87, '作燔祭的，共有公牛十二只，公羊十二只，一岁的公羊羔十二只，并同献的素祭作赎罪祭的公山羊十二只；'),
('CUV', '民数记', 4, 7, 88, '作平安祭的，共有公牛二十四只，公绵羊六十只，公山羊六十只，一岁的公羊羔六十只。这就是用膏抹坛之后，为行奉献坛之礼所献的。'),
('CUV', '民数记', 4, 7, 89, '摩西进会幕要与耶和华说话的时候，听见法柜的施恩座以上、二基路伯中间有与他说话的声音，就是耶和华与他说话。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 8, 1, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 8, 2, '你告诉亚伦说：点灯的时候，七盏灯都要向灯台前面发光。'),
('CUV', '民数记', 4, 8, 3, '亚伦便这样行。他点灯台上的灯，使灯向前发光，是照耶和华所吩咐摩西的。'),
('CUV', '民数记', 4, 8, 4, '这灯台的作法是用金子锤出来的，连座带花都是锤出来的。摩西制造灯台，是照耶和华所指示的样式。'),
('CUV', '民数记', 4, 8, 5, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 8, 6, '你从以色列人中选出利未人来，洁净他们。'),
('CUV', '民数记', 4, 8, 7, '洁净他们当这样行：用除罪水弹在他们身上，又叫他们用剃头刀刮全身，洗衣服，洁净自己。'),
('CUV', '民数记', 4, 8, 8, '然后叫他们取一只公牛犊，并同献的素祭，就是调油的细面；你要另取一只公牛犊作赎罪祭。'),
('CUV', '民数记', 4, 8, 9, '将利未人奉到会幕前，招聚以色列全会众。'),
('CUV', '民数记', 4, 8, 10, '将利未人奉到耶和华面前，以色列人要按手在他们头上。'),
('CUV', '民数记', 4, 8, 11, '亚伦也将他们奉到耶和华面前，为以色列人当作摇祭，使他们好办耶和华的事。'),
('CUV', '民数记', 4, 8, 12, '利未人要按手在那两只牛的头上；你要将一只作赎罪祭，一只作燔祭，献给耶和华，为利未人赎罪。'),
('CUV', '民数记', 4, 8, 13, '你也要使利未人站在亚伦和他儿子面前，将他们当作摇祭奉给耶和华。'),
('CUV', '民数记', 4, 8, 14, '这样，你从以色列人中将利未人分别出来，利未人便要归我。'),
('CUV', '民数记', 4, 8, 15, '此后利未人要进去办会幕的事，你要洁净他们，将他们当作摇祭奉上；'),
('CUV', '民数记', 4, 8, 16, '因为他们是从以色列人中全然给我的，我拣选他们归我，是代替以色列人中一切头生的。'),
('CUV', '民数记', 4, 8, 17, '以色列人中一切头生的，连人带牲畜，都是我的。我在埃及地击杀一切头生的那天，将他们分别为圣归我。'),
('CUV', '民数记', 4, 8, 18, '我拣选利未人代替以色列人中一切头生的。'),
('CUV', '民数记', 4, 8, 19, '我从以色列人中将利未人当作赏赐给亚伦和他的儿子，在会幕中办以色列人的事，又为以色列人赎罪，免得他们挨近圣所，有灾殃临到他们中间。'),
('CUV', '民数记', 4, 8, 20, '摩西、亚伦，并以色列全会众便向利未人如此行。凡耶和华指著利未人所吩咐摩西的，以色列人就向他们这样行。'),
('CUV', '民数记', 4, 8, 21, '于是利未人洁净自己，除了罪，洗了衣服；亚伦将他们当作摇祭奉到耶和华面前，又为他们赎罪，洁净他们。'),
('CUV', '民数记', 4, 8, 22, '然后利未人进去，在亚伦和他儿子面前，在会幕中办事。耶和华指著利未人怎样吩咐摩西，以色列人就怎样向他们行了。'),
('CUV', '民数记', 4, 8, 23, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 8, 24, '利未人是这样：从二十五岁以外，他们要前来任职，办会幕的事。'),
('CUV', '民数记', 4, 8, 25, '到了五十岁要停工退任，不再办事，'),
('CUV', '民数记', 4, 8, 26, '只要在会幕里，和他们的弟兄一同伺候，谨守所吩咐的，不再办事了。至于所吩咐利未人的，你要这样向他们行。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 9, 1, '以色列人出埃及地以后，第二年正月，耶和华在西乃的旷野吩咐摩西说：'),
('CUV', '民数记', 4, 9, 2, '以色列人应当在所定的日期守逾越节，'),
('CUV', '民数记', 4, 9, 3, '就是本月十四日黄昏的时候，你们要在所定的日期守这节，要按这节的律例典章而守。'),
('CUV', '民数记', 4, 9, 4, '于是摩西吩咐以色列人守逾越节。'),
('CUV', '民数记', 4, 9, 5, '他们就在西乃的旷野，正月十四日黄昏的时候，守逾越节。凡耶和华所吩咐摩西的，以色列人都照样行了。'),
('CUV', '民数记', 4, 9, 6, '有几个人因死尸而不洁净，不能在那日守逾越节。当日他们到摩西、亚伦面前，'),
('CUV', '民数记', 4, 9, 7, '说：我们虽因死尸而不洁净，为何被阻止、不得同以色列人在所定的日期献耶和华的供物呢？'),
('CUV', '民数记', 4, 9, 8, '摩西对他们说：你们暂且等候，我可以去听耶和华指著你们是怎样吩咐的。'),
('CUV', '民数记', 4, 9, 9, '耶和华对摩西说：'),
('CUV', '民数记', 4, 9, 10, '你晓谕以色列人说：你们和你们后代中，若有人因死尸而不洁净，或在远方行路，还要向耶和华守逾越节。'),
('CUV', '民数记', 4, 9, 11, '他们要在二月十四日黄昏的时候，守逾越节。要用无酵饼与苦菜，和逾越节的羊羔同吃。'),
('CUV', '民数记', 4, 9, 12, '一点不可留到早晨；羊羔的骨头一根也不可折断。他们要照逾越节的一切律例而守。'),
('CUV', '民数记', 4, 9, 13, '那洁净而不行路的人若推辞不守逾越节，那人要从民中剪除；因为他在所定的日期不献耶和华的供物，应该担当他的罪。'),
('CUV', '民数记', 4, 9, 14, '若有外人寄居在你们中间，愿意向耶和华守逾越节，他要照逾越节的律例典章行，不管是寄居的是本地人，同归一例。'),
('CUV', '民数记', 4, 9, 15, '立起帐幕的那日，有云彩遮盖帐幕，就是法柜的帐幕；从晚上到早晨，云彩在其上，形状如火。'),
('CUV', '民数记', 4, 9, 16, '常是这样，云彩遮盖帐幕，夜间形状如火。'),
('CUV', '民数记', 4, 9, 17, '云彩几时从帐幕收上去，以色列人就几时起行；云彩在那里停住，以色列人就在那里安营。'),
('CUV', '民数记', 4, 9, 18, '以色列人遵耶和华的吩咐起行，也遵耶和华的吩咐安营。云彩在帐幕上停住几时，他们就住营几时。'),
('CUV', '民数记', 4, 9, 19, '云彩在帐幕上停留许多日子，以色列人就守耶和华所吩咐的不起行。'),
('CUV', '民数记', 4, 9, 20, '有时云彩在帐幕上几天，他们就照耶和华的吩咐住营，也照耶和华的吩咐起行。'),
('CUV', '民数记', 4, 9, 21, '有时从晚上到早晨，有这云彩在帐幕上；早晨云彩收上去，他们就起行。有时昼夜云彩停在帐幕上，收上去的时候，他们就起行。'),
('CUV', '民数记', 4, 9, 22, '云彩停留在帐幕上，无论是两天，是一月，是一年，以色列人就住营不起行；但云彩收上去，他们就起行。'),
('CUV', '民数记', 4, 9, 23, '他们遵耶和华的吩咐安营，也遵耶和华的吩咐起行。他们守耶和华所吩咐的，都是凭耶和华吩咐摩西的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 10, 1, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 10, 2, '你要用银子做两枝号，都要锤出来的，用以招聚会众，并叫众营起行。'),
('CUV', '民数记', 4, 10, 3, '吹这号的时候，全会众要到你那里，聚集在会幕门口。'),
('CUV', '民数记', 4, 10, 4, '若单吹一枝，众首领，就是以色列军中的统领，要聚集到你那里。'),
('CUV', '民数记', 4, 10, 5, '吹出大声的时候，东边安的营都要起行。'),
('CUV', '民数记', 4, 10, 6, '二次吹出大声的时候，南边安的营都要起行。他们将起行，必吹出大声。'),
('CUV', '民数记', 4, 10, 7, '但招聚会众的时候，你们要吹号，却不要吹出大声。'),
('CUV', '民数记', 4, 10, 8, '亚伦子孙作祭司的要吹这号；这要作你们世世代代永远的定例。'),
('CUV', '民数记', 4, 10, 9, '你们在自己的地，与欺压你们的敌人打仗，就要用号吹出大声，便在耶和华─你们的神面前得蒙纪念，也蒙拯救脱离仇敌。'),
('CUV', '民数记', 4, 10, 10, '在你们快乐的日子和节期，并月朔，献燔祭和平安祭，也要吹号，这都要在你们的神面前作为纪念。我是耶和华─你们的神。'),
('CUV', '民数记', 4, 10, 11, '第二年二月二十日，云彩从法柜的帐幕收上去。'),
('CUV', '民数记', 4, 10, 12, '以色列人就按站往前行，离开西乃的旷野，云彩停住在巴兰的旷野。'),
('CUV', '民数记', 4, 10, 13, '这是他们照耶和华藉摩西所吩咐的，初次往前行。'),
('CUV', '民数记', 4, 10, 14, '按著军队首先往前行的是犹大营的纛。统领军队的是亚米拿达的儿子拿顺。'),
('CUV', '民数记', 4, 10, 15, '统领以萨迦支派军队的是苏押的儿子拿坦业。'),
('CUV', '民数记', 4, 10, 16, '统领西布伦支派军队的是希伦的儿子以利押。'),
('CUV', '民数记', 4, 10, 17, '帐幕拆卸，革顺的子孙和米拉利的子孙就抬著帐幕先往前行。'),
('CUV', '民数记', 4, 10, 18, '按著军队往前行的是流便营的纛。统领军队的是示丢珥的儿子以利蓿。'),
('CUV', '民数记', 4, 10, 19, '统领西缅支派军队的是苏利沙代的儿子示路蔑。'),
('CUV', '民数记', 4, 10, 20, '统领迦得支派军队的是丢珥的儿子以利雅萨。'),
('CUV', '民数记', 4, 10, 21, '哥辖人抬著圣物先往前行。他们未到以前，抬帐幕的已经把帐幕支好。'),
('CUV', '民数记', 4, 10, 22, '按著军队往前行的是以法莲营的纛，统领军队的是亚米忽的儿子以利沙玛。'),
('CUV', '民数记', 4, 10, 23, '统领玛拿西支派军队的是比大蓿的儿子迦玛列。'),
('CUV', '民数记', 4, 10, 24, '统领便雅悯支派军队的是基多尼的儿子亚比但。'),
('CUV', '民数记', 4, 10, 25, '在诸营末后的是但营的纛，按著军队往前行。统领军队的是亚米沙代的儿子亚希以谢。'),
('CUV', '民数记', 4, 10, 26, '统领亚设支派军队的是俄兰的儿子帕结。'),
('CUV', '民数记', 4, 10, 27, '统领拿弗他利支派军队的是以南的儿子亚希拉。'),
('CUV', '民数记', 4, 10, 28, '以色列人按著军队往前行，就是这样。'),
('CUV', '民数记', 4, 10, 29, '摩西对他岳父（或作：内兄）─米甸人流珥的儿子何巴─说：我们要行路，往耶和华所应许之地去；他曾说：我要将这地赐给你们。现在求你和我们同去，我们必厚待你，因为耶和华指著以色列人已经应许给好处。'),
('CUV', '民数记', 4, 10, 30, '何巴回答说：我不去；我要回本地本族那里去。'),
('CUV', '民数记', 4, 10, 31, '摩西说：求你不要离开我们；因为你知道我们要在旷野安营，你可以当作我们的眼目。'),
('CUV', '民数记', 4, 10, 32, '你若和我们同去，将来耶和华有甚么好处待我们，我们也必以甚么好处待你。'),
('CUV', '民数记', 4, 10, 33, '以色列人离开耶和华的山，往前行了三天的路程；耶和华的约柜在前头行了三天的路程，为他们寻找安歇的地方。'),
('CUV', '民数记', 4, 10, 34, '他们拔营往前行，日间有耶和华的云彩在他们以上。'),
('CUV', '民数记', 4, 10, 35, '约柜往前行的时候，摩西就说：耶和华阿，求你兴起！愿你的仇敌四散！愿恨你的人从你面前逃跑！'),
('CUV', '民数记', 4, 10, 36, '约柜停住的时候，他就说：耶和华阿，求你回到以色列的千万人中！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 11, 1, '众百姓发怨言，他们的恶语达到耶和华的耳中。耶和华听见了就怒气发作，使火在他们中间焚烧，直烧到营的边界。'),
('CUV', '民数记', 4, 11, 2, '百姓向摩西哀求，摩西祈求耶和华，火就熄了。'),
('CUV', '民数记', 4, 11, 3, '那地方便叫做他备拉，因为耶和华的火烧在他们中间。'),
('CUV', '民数记', 4, 11, 4, '他们中间的闲杂人大起贪欲的心；以色列人又哭号说：谁给我们肉吃呢？'),
('CUV', '民数记', 4, 11, 5, '我们记得，在埃及的时候不花钱就吃鱼，也记得有黄瓜、西瓜、韭菜、葱、蒜。'),
('CUV', '民数记', 4, 11, 6, '现在我们的心血枯竭了，除这吗哪以外，在我们眼前并没有别的东西。'),
('CUV', '民数记', 4, 11, 7, '这吗哪仿佛芫荽子，又好像珍珠。'),
('CUV', '民数记', 4, 11, 8, '百姓周围行走，把吗哪收起来，或用磨推，或用臼捣，煮在锅中，又做成饼，滋味好像新油。'),
('CUV', '民数记', 4, 11, 9, '夜间露水降在营中，吗哪也随著降下。'),
('CUV', '民数记', 4, 11, 10, '摩西听见百姓，各在各家的帐棚门口哭号。耶和华的怒气便大发作，摩西就不喜悦。'),
('CUV', '民数记', 4, 11, 11, '摩西对耶和华说：你为何苦待仆人？我为何不在你眼前蒙恩，竟把这管理百姓的重任加在我身上呢？'),
('CUV', '民数记', 4, 11, 12, '这百姓岂是我怀的胎，岂是我生下来的呢？你竟对我说：把他们抱在怀里，如养育之父抱吃奶的孩子，直抱到你起誓应许给他们祖宗的地去。'),
('CUV', '民数记', 4, 11, 13, '我从那里得肉给这百姓吃呢？他们都向我哭号说：你给我们肉吃罢！'),
('CUV', '民数记', 4, 11, 14, '管理这百姓的责任太重了，我独自担当不起。'),
('CUV', '民数记', 4, 11, 15, '你这样待我，我若在你眼前蒙恩，求你立时将我杀了，不叫我见自己的苦情。'),
('CUV', '民数记', 4, 11, 16, '耶和华对摩西说：你从以色列的长老中招聚七十个人，就是你所知道作百姓的长老和官长的，到我这里来，领他们到会幕前，使他们和你一同站立。'),
('CUV', '民数记', 4, 11, 17, '我要在那里降临，与你说话，也要把降于你身上的灵分赐他们，他们就和你同当这管百姓的重任，免得你独自担当。'),
('CUV', '民数记', 4, 11, 18, '又要对百姓说：你们应当自洁，预备明天吃肉，因为你们哭号说：谁给我们肉吃！我们在埃及很好。这声音达到了耶和华的耳中，所以他必给你们肉吃。'),
('CUV', '民数记', 4, 11, 19, '你们不止吃一天、两天、五天、十天、二十天，'),
('CUV', '民数记', 4, 11, 20, '要吃一个整月，甚至肉从你们鼻孔里喷出来，使你们厌恶了，因为你们厌弃住在你们中间的耶和华，在他面前哭号说：我们为何出了埃及呢？'),
('CUV', '民数记', 4, 11, 21, '摩西对耶和华说：这与我同住的百姓、步行的男人有六十万，你还说：我要把肉给他们，使他们可以吃一个整月。'),
('CUV', '民数记', 4, 11, 22, '难道给他们宰了羊群牛群，或是把海中所有的鱼都聚了来，就够他们吃么？'),
('CUV', '民数记', 4, 11, 23, '耶和华对摩西说：耶和华的膀臂岂是缩短了么？现在要看我的话向你应验不应验。'),
('CUV', '民数记', 4, 11, 24, '摩西出去，将耶和华的话告诉百姓，又招聚百姓的长老中七十个人来，使他们站在会幕的四围。'),
('CUV', '民数记', 4, 11, 25, '耶和华在云中降临，对摩西说话，把降与他身上的灵分赐那七十个长老。灵停在他们身上的时候，他们就受感说话，以后却没有再说。'),
('CUV', '民数记', 4, 11, 26, '但有两个人仍在营里，一个名叫伊利达，一个名叫米达。他们本是在那些被录的人中，却没有到会幕那里去。灵停在他们身上，他们就在营里说预言。'),
('CUV', '民数记', 4, 11, 27, '有个少年人跑来告诉摩西说：伊利达、米达在营里说预言。'),
('CUV', '民数记', 4, 11, 28, '摩西的帮手，嫩的儿子约书亚，就是摩西所拣选的一个人，说：请我主摩西禁止他们。'),
('CUV', '民数记', 4, 11, 29, '摩西对他说：你为我的缘故嫉妒人么？惟愿耶和华的百姓都受感说话！愿耶和华把他的灵降在他们身上！'),
('CUV', '民数记', 4, 11, 30, '于是，摩西和以色列的长老都回到营里去了。'),
('CUV', '民数记', 4, 11, 31, '有风从耶和华那里刮起，把鹌鹑由海面刮来，飞散在营边和营的四围；这边约有一天的路程，那边约有一天的路程，离地面约有二肘。'),
('CUV', '民数记', 4, 11, 32, '百姓起来，终日终夜，并次日一整天，捕取鹌鹑；至少的也取了十贺梅珥，为自己摆列在营的四围。'),
('CUV', '民数记', 4, 11, 33, '肉在他们牙齿之间尚未嚼烂，耶和华的怒气就向他们发作，用最重的灾殃击杀了他们。'),
('CUV', '民数记', 4, 11, 34, '那地方便叫做基博罗哈他瓦（就是贪欲之人的坟墓），因为他们在那里葬埋那起贪欲之心的人。'),
('CUV', '民数记', 4, 11, 35, '百姓从基博罗哈他瓦走到哈洗录，就住在哈洗录。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 12, 1, '摩西娶了古实女子为妻。米利暗和亚伦因他所娶的古实女子，就毁谤他，说：'),
('CUV', '民数记', 4, 12, 2, '难道耶和华单与摩西说话，不也与我们说话么？这话耶和华听见了。'),
('CUV', '民数记', 4, 12, 3, '摩西为人极其谦和，胜过世上的众人。'),
('CUV', '民数记', 4, 12, 4, '耶和华忽然对摩西、亚伦、米利暗说：你们三个人都出来，到会幕这里。他们三个人就出来了。'),
('CUV', '民数记', 4, 12, 5, '耶和华在云柱中降临，站在会幕门口，召亚伦和米利暗，二人就出来了。'),
('CUV', '民数记', 4, 12, 6, '耶和华说：你们且听我的话：你们中间若有先知，我─耶和华必在异象中向他显现，在梦中与他说话。'),
('CUV', '民数记', 4, 12, 7, '我的仆人摩西不是这样；他是在我全家尽忠的。'),
('CUV', '民数记', 4, 12, 8, '我要与他面对面说话，乃是明说，不用谜语，并且他必见我的形像。你们毁谤我的仆人摩西，为何不惧怕呢？'),
('CUV', '民数记', 4, 12, 9, '耶和华就向他们二人发怒而去。'),
('CUV', '民数记', 4, 12, 10, '云彩从会幕上挪开了，不料，米利暗长了大痲疯，有雪那样白，亚伦一看米利暗长了大痲疯，'),
('CUV', '民数记', 4, 12, 11, '就对摩西说：我主阿，求你不要因我们愚昧犯罪，便将这罪加在我们身上。'),
('CUV', '民数记', 4, 12, 12, '求你不要使他像那出母腹、肉已半烂的死胎。'),
('CUV', '民数记', 4, 12, 13, '于是摩西哀求耶和华说：神阿，求你医治他！'),
('CUV', '民数记', 4, 12, 14, '耶和华对摩西说：他父亲若吐唾沫在他脸上，他岂不蒙羞七天么？现在要把他在营外关锁七天，然后才可以领他进来。'),
('CUV', '民数记', 4, 12, 15, '于是米利暗关锁在营外七天。百姓没有行路，直等到把米利暗领进来。'),
('CUV', '民数记', 4, 12, 16, '以后百姓从哈洗录起行，在巴兰的旷野安营。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 13, 1, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 13, 2, '你打发人去窥探我所赐给以色列人的迦南地，他们每支派中要打发一个人，都要作首领的。'),
('CUV', '民数记', 4, 13, 3, '摩西就照耶和华的吩咐，从巴兰的旷野打发他们去；他们都是以色列人的族长。'),
('CUV', '民数记', 4, 13, 4, '他们的名字：属流便支派的有撒刻的儿子沙母亚。'),
('CUV', '民数记', 4, 13, 5, '属西缅支派的有何利的儿子的沙法。'),
('CUV', '民数记', 4, 13, 6, '属犹大支派的有耶孚尼的儿子迦勒。'),
('CUV', '民数记', 4, 13, 7, '属以萨迦支派的有约色的儿子以迦。'),
('CUV', '民数记', 4, 13, 8, '属以法莲支派的有嫩的儿子何西阿。'),
('CUV', '民数记', 4, 13, 9, '属便雅悯支派的有拉孚的儿子帕提。'),
('CUV', '民数记', 4, 13, 10, '属西布伦支派的有梭底的儿子迦叠。'),
('CUV', '民数记', 4, 13, 11, '约瑟的子孙属玛拿西支派的有稣西的儿子迦底。'),
('CUV', '民数记', 4, 13, 12, '属但支派的有基玛利的儿子亚米利。'),
('CUV', '民数记', 4, 13, 13, '属亚设支派的有米迦勒的儿子西帖。'),
('CUV', '民数记', 4, 13, 14, '属拿弗他利支派的有缚西的儿子拿比。'),
('CUV', '民数记', 4, 13, 15, '属迦得支派的有玛基的儿子臼利。'),
('CUV', '民数记', 4, 13, 16, '这就是摩西所打发窥探那地之人的名字。摩西就称嫩的儿子何西阿为约书亚。'),
('CUV', '民数记', 4, 13, 17, '摩西打发他们去窥探迦南地，说：你们从南地上山地去，'),
('CUV', '民数记', 4, 13, 18, '看那地如何，其中所住的民是强是弱，是多是少，'),
('CUV', '民数记', 4, 13, 19, '所住之地是好是歹，所住之处是营盘是坚城。'),
('CUV', '民数记', 4, 13, 20, '又看那地土是肥美是瘠薄，其中有树木没有。你们要放开胆量，把那地的果子带些来。那时正是葡萄初熟的时候。'),
('CUV', '民数记', 4, 13, 21, '他们上去窥探那地，从寻的旷野到利合，直到哈马口。'),
('CUV', '民数记', 4, 13, 22, '他们从南地上去，到了希伯仑；在那里有亚衲族人亚希幔、示筛、挞买。原来希伯仑城被建造比埃及的锁安城早七年。'),
('CUV', '民数记', 4, 13, 23, '他们到了以实各谷，从那里砍了葡萄树的一枝，上头有一挂葡萄，两个人用杠抬著，又带了些石榴和无花果来。'),
('CUV', '民数记', 4, 13, 24, '因为以色列人从那里砍来的那挂葡萄，所以那地方叫做以实各谷。'),
('CUV', '民数记', 4, 13, 25, '过了四十天，他们窥探那地才回来，'),
('CUV', '民数记', 4, 13, 26, '到了巴兰旷野的加低斯，见摩西、亚伦，并以色列的全会众，回报摩西、亚伦，并全会众，又把那地的果子给他们看；'),
('CUV', '民数记', 4, 13, 27, '又告诉摩西说：我们到了你所打发我们去的那地，果然是流奶与蜜之地；这就是那地的果子。'),
('CUV', '民数记', 4, 13, 28, '然而住那地的民强壮，城邑也坚固宽大，并且我们在那里看见了亚衲族的人。'),
('CUV', '民数记', 4, 13, 29, '亚玛力人住在南地；赫人、耶布斯人、亚摩利人、住在山地；迦南人住在海边并约但河旁。'),
('CUV', '民数记', 4, 13, 30, '迦勒在摩西面前安抚百姓，说：我们立刻上去得那地罢！我们足能得胜。'),
('CUV', '民数记', 4, 13, 31, '但那些和他同去的人说：我们不能上去攻击那民，因为他们比我们强壮。'),
('CUV', '民数记', 4, 13, 32, '探子中有人论到所窥探之地，向以色列人报恶信，说：我们所窥探、经过之地是吞吃居民之地，我们在那里所看见的人民都身量高大。'),
('CUV', '民数记', 4, 13, 33, '我们在那里看见亚衲族人，就是伟人；他们是伟人的后裔。据我们看，自己就如蚱蜢一样；据他们看，我们也是如此。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 14, 1, '当下，全会众大声喧嚷；那夜百姓都哭号。'),
('CUV', '民数记', 4, 14, 2, '以色列众人向摩西、亚伦发怨言；全会众对他们说：巴不得我们早死在埃及地，或是死在这旷野。'),
('CUV', '民数记', 4, 14, 3, '耶和华为甚么把我们领到那地，使我们倒在刀下呢？我们的妻子和孩子必被掳掠。我们回埃及去岂不好么？'),
('CUV', '民数记', 4, 14, 4, '众人彼此说：我们不如立一个首领回埃及去罢！'),
('CUV', '民数记', 4, 14, 5, '摩西、亚伦就俯伏在以色列全会众面前。'),
('CUV', '民数记', 4, 14, 6, '窥探地的人中，嫩的儿子约书亚和耶孚尼的儿子迦勒撕裂衣服，'),
('CUV', '民数记', 4, 14, 7, '对以色列全会众说：我们所窥探、经过之地是极美之地。'),
('CUV', '民数记', 4, 14, 8, '耶和华若喜悦我们，就必将我们领进那地，把地赐给我们；那地原是流奶与蜜之地。'),
('CUV', '民数记', 4, 14, 9, '但你们不可背叛耶和华，也不要怕那地的居民；因为他们是我们的食物，并且荫庇他们的已经离开他们。有耶和华与我们同在，不要怕他们！'),
('CUV', '民数记', 4, 14, 10, '但全会众说：拿石头打死他们二人。忽然，耶和华的荣光在会幕中向以色列众人显现。'),
('CUV', '民数记', 4, 14, 11, '耶和华对摩西说：这百姓藐视我要到几时呢？我在他们中间行了这一切神迹，他们还不信我要到几时呢？'),
('CUV', '民数记', 4, 14, 12, '我要用瘟疫击杀他们，使他们不得承受那地，叫你的后裔成为大国，比他们强胜。'),
('CUV', '民数记', 4, 14, 13, '摩西对耶和华说：埃及人必听见这事；因为你曾施展大能，将这百姓从他们中间领上来。'),
('CUV', '民数记', 4, 14, 14, '埃及人要将这事传给迦南地的居民；那民已经听见你─耶和华是在这百姓中间；因为你面对面被人看见，有你的云彩停在他们以上。你日间在云柱中，夜间在火柱中，在他们前面行。'),
('CUV', '民数记', 4, 14, 15, '如今你若把这百姓杀了，如杀一人，那些听见你名声的列邦必议论说：'),
('CUV', '民数记', 4, 14, 16, '耶和华因为不能把这百姓领进他向他们起誓应许之地，所以在旷野把他们杀了。'),
('CUV', '民数记', 4, 14, 17, '现在求主大显能力，照你所说过的话说：'),
('CUV', '民数记', 4, 14, 18, '耶和华不轻易发怒，并有丰盛的慈爱，赦免罪孽和过犯；万不以有罪的为无罪，必追讨他的罪，自父及子，直到三、四代。'),
('CUV', '民数记', 4, 14, 19, '求你照你的大慈爱赦免这百姓的罪孽，好像你从埃及到如今常赦免他们一样。'),
('CUV', '民数记', 4, 14, 20, '耶和华说：我照著你的话赦免了他们。'),
('CUV', '民数记', 4, 14, 21, '然我指著我的永生起誓，遍地要被我的荣耀充满。'),
('CUV', '民数记', 4, 14, 22, '这些人虽看见我的荣耀和我在埃及与旷野所行的神迹，仍然试探我这十次，不听从我的话，'),
('CUV', '民数记', 4, 14, 23, '他们断不得看见我向他们的祖宗所起誓应许之地。凡藐视我的，一个也不得看见；'),
('CUV', '民数记', 4, 14, 24, '惟独我的仆人迦勒，因他另有一个心志，专一跟从我，我就把他领进他所去过的那地；他的后裔也必得那地为业。'),
('CUV', '民数记', 4, 14, 25, '亚玛力人和迦南人住在谷中，明天你们要转回，从红海的路往旷野去。'),
('CUV', '民数记', 4, 14, 26, '耶和华对摩西、亚伦说：'),
('CUV', '民数记', 4, 14, 27, '这恶会众向我发怨言，我忍耐他们要到几时呢？以色列人向我所发的怨言，我都听见了。'),
('CUV', '民数记', 4, 14, 28, '你们告诉他们，耶和华说：我指著我的永生起誓，我必要照你们达到我耳中的话待你们。'),
('CUV', '民数记', 4, 14, 29, '你们的尸首必倒在这旷野，并且你们中间凡被数点、从二十岁以外、向我发怨言的，'),
('CUV', '民数记', 4, 14, 30, '必不得进我起誓应许叫你们住的那地；惟有耶孚尼的儿子迦勒和嫩的儿子约书亚才能进去。'),
('CUV', '民数记', 4, 14, 31, '但你们的妇人孩子，就是你们所说、要被掳掠的，我必把他们领进去，他们就得知你们所厌弃的那地。'),
('CUV', '民数记', 4, 14, 32, '至于你们，你们的尸首必倒在这旷野；'),
('CUV', '民数记', 4, 14, 33, '你们的儿女必在旷野飘流四十年，担当你们淫行的罪，直到你们的尸首在旷野消灭。'),
('CUV', '民数记', 4, 14, 34, '按你们窥探那地的四十日，一年顶一日，你们要担当罪孽四十年，就知道我与你们疏远了，'),
('CUV', '民数记', 4, 14, 35, '我─耶和华说过，我总要这样待这一切聚集敌我的恶会众；他们必在这旷野消灭，在这里死亡。'),
('CUV', '民数记', 4, 14, 36, '摩西所打发、窥探那地的人回来，报那地的恶信，叫全会众向摩西发怨言，'),
('CUV', '民数记', 4, 14, 37, '这些报恶信的人都遭瘟疫，死在耶和华面前。'),
('CUV', '民数记', 4, 14, 38, '其中惟有嫩的儿子约书亚和耶孚尼的儿子迦勒仍然存活。'),
('CUV', '民数记', 4, 14, 39, '摩西将这些话告诉以色列众人，他们就甚悲哀。'),
('CUV', '民数记', 4, 14, 40, '清早起来，上山顶去，说：我们在这里，我们有罪了；情愿上耶和华所应许的地方去。'),
('CUV', '民数记', 4, 14, 41, '摩西说：你们为何违背耶和华的命令呢？这事不能顺利了。'),
('CUV', '民数记', 4, 14, 42, '不要上去；因为耶和华不在你们中间，恐怕你们被仇敌杀败了。'),
('CUV', '民数记', 4, 14, 43, '亚玛力人和迦南人都在你们面前，你们必倒在刀下；因你们退回不跟从耶和华，所以他必不与你们同在。'),
('CUV', '民数记', 4, 14, 44, '他们却擅敢上山顶去，然而耶和华的约柜和摩西没有出营。'),
('CUV', '民数记', 4, 14, 45, '于是亚玛力人和住在那山上的迦南人都下来击打他们，把他们杀退了，直到何珥玛。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 15, 1, '耶和华对摩西说：'),
('CUV', '民数记', 4, 15, 2, '你晓谕以色列人说：你们到了我所赐给你们居住的地，'),
('CUV', '民数记', 4, 15, 3, '若愿意从牛群羊群中取牛羊作火祭，献给耶和华，无论是燔祭是平安祭，为要还特许的愿，或是作甘心祭，或是逢你们节期献的，都要奉给耶和华为馨香之祭。'),
('CUV', '民数记', 4, 15, 4, '那献供物的就要将细面伊法十分之一，并油一欣四分之一，调和作素祭，献给耶和华。'),
('CUV', '民数记', 4, 15, 5, '无论是燔祭是平安祭，你要为每只绵羊羔，一同预备奠祭的酒一欣四分之一。'),
('CUV', '民数记', 4, 15, 6, '为公绵羊预备细面伊法十分之二，并油一欣三分之一，调和作素祭，'),
('CUV', '民数记', 4, 15, 7, '又用酒一欣三分之一作奠祭，献给耶和华为馨香之祭。'),
('CUV', '民数记', 4, 15, 8, '你预备公牛作燔祭，或是作平安祭，为要还特许的愿，或是作平安祭，献给耶和华，'),
('CUV', '民数记', 4, 15, 9, '就要把细面伊法十分之三，并油半欣，调和作素祭，和公牛一同献上，'),
('CUV', '民数记', 4, 15, 10, '又用酒半欣作奠祭，献给耶和华为馨香的火祭。'),
('CUV', '民数记', 4, 15, 11, '献公牛、公绵羊、绵羊羔、山羊羔，每只都要这样办理。'),
('CUV', '民数记', 4, 15, 12, '照你们所预备的数目，按著只数都要这样办理。'),
('CUV', '民数记', 4, 15, 13, '凡本地人将馨香的火祭献给耶和华，都要这样办理。'),
('CUV', '民数记', 4, 15, 14, '若有外人和你们同居，或有人世世代代住在你们中间，愿意将馨香的火祭献给耶和华，你们怎样办理，他也要照样办理。'),
('CUV', '民数记', 4, 15, 15, '至于会众，你们和同居的外人都归一例，作为你们世世代代永远的定例，在耶和华面前，你们怎样，寄居的也要怎样。'),
('CUV', '民数记', 4, 15, 16, '你们并与你们同居的外人当有一样的条例，一样的典章。'),
('CUV', '民数记', 4, 15, 17, '耶和华对摩西说：'),
('CUV', '民数记', 4, 15, 18, '你晓谕以色列人说：你们到了我所领你们进去的那地，'),
('CUV', '民数记', 4, 15, 19, '吃那地的粮食，就要把举祭献给耶和华。'),
('CUV', '民数记', 4, 15, 20, '你们要用初熟的麦子磨面，做饼当举祭奉献；你们举上，好像举禾场的举祭一样，'),
('CUV', '民数记', 4, 15, 21, '你们世世代代要用初熟的麦子磨面，当举祭献给耶和华。'),
('CUV', '民数记', 4, 15, 22, '你们有错误的时候，不守耶和华所晓谕摩西的这一切命令，'),
('CUV', '民数记', 4, 15, 23, '就是耶和华藉摩西一切所吩咐你们的，自那日以至你们的世世代代，'),
('CUV', '民数记', 4, 15, 24, '若有误行，是会众所不知道的，后来全会众就要将一只公牛犊作燔祭，并照典章把素祭和奠祭一同献给耶和华为馨香之祭，又献一只公山羊作赎罪祭。'),
('CUV', '民数记', 4, 15, 25, '祭司要为以色列全会众赎罪，他们就必蒙赦免，因为这是错误。他们又因自己的错误，把供物，就是向耶和华献的火祭和赎罪祭，一并奉到耶和华面前。'),
('CUV', '民数记', 4, 15, 26, '以色列全会众和寄居在他们中间的外人就必蒙赦免，因为这罪是百姓误犯的。'),
('CUV', '民数记', 4, 15, 27, '若有一个人误犯了罪，他就要献一岁的母山羊作赎罪祭。'),
('CUV', '民数记', 4, 15, 28, '那误行的人犯罪的时候，祭司要在耶和华面前为他赎罪，他就必蒙赦免。'),
('CUV', '民数记', 4, 15, 29, '以色列中的本地人和寄居在他们中间的外人，若误行了甚么事，必归一样的条例，'),
('CUV', '民数记', 4, 15, 30, '但那擅敢行事的，无论是本地人是寄居的，他亵渎了耶和华，必从民中剪除。'),
('CUV', '民数记', 4, 15, 31, '因他藐视耶和华的言语，违背耶和华的命令，那人总要剪除；他的罪孽要归到他身上。'),
('CUV', '民数记', 4, 15, 32, '以色列人在旷野的时候，遇见一个人在安息日捡柴。'),
('CUV', '民数记', 4, 15, 33, '遇见他捡柴的人，就把他带到摩西、亚伦并全会众那里，'),
('CUV', '民数记', 4, 15, 34, '将他收在监内；因为当怎样办他，还没有指明。'),
('CUV', '民数记', 4, 15, 35, '耶和华吩咐摩西说：总要把那人治死；全会众要在营外用石头把他打死。'),
('CUV', '民数记', 4, 15, 36, '于是全会众将他带到营外，用石头打死他，是照耶和华所吩咐摩西的。'),
('CUV', '民数记', 4, 15, 37, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 15, 38, '你吩咐以色列人，叫他们世世代代在衣服边上做䍁子，又在底边的䍁子上钉一根蓝细带子。'),
('CUV', '民数记', 4, 15, 39, '你们佩带这䍁子，好叫你们看见就记念遵行耶和华一切的命令，不随从自己的心意、眼目行邪淫，像你们素常一样；'),
('CUV', '民数记', 4, 15, 40, '使你们记念遵行我一切的命令，成为圣洁，归与你们的神。'),
('CUV', '民数记', 4, 15, 41, '我是耶和华─你们的神，曾把你们从埃及地领出来，要作你们的神。我是耶和华─你们的神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 16, 1, '利未的曾孙、哥辖的孙子、以斯哈的儿子可拉，和流便子孙中以利押的儿子大坍、亚比兰，与比勒的儿子安，'),
('CUV', '民数记', 4, 16, 2, '并以色列会中的二百五十个首领，就是有名望选入会中的人，在摩西面前一同起来，'),
('CUV', '民数记', 4, 16, 3, '聚集攻击摩西、亚伦，说：你们擅自专权！全会众个个既是圣洁，耶和华也在他们中间，你们为甚么自高，超过耶和华的会众呢？'),
('CUV', '民数记', 4, 16, 4, '摩西听见这话就俯伏在地，'),
('CUV', '民数记', 4, 16, 5, '对可拉和他一党的人说：到了早晨，耶和华必指示谁是属他的，谁是圣洁的，就叫谁亲近他；他所拣选的是谁，必叫谁亲近他。'),
('CUV', '民数记', 4, 16, 6, '可拉阿，你们要这样行，你和你的一党要拿香炉来。'),
('CUV', '民数记', 4, 16, 7, '明日，在耶和华面前，把火盛在炉中，把香放在其上。耶和华拣选谁，谁就为圣洁。你们这利未的子孙擅自专权了！'),
('CUV', '民数记', 4, 16, 8, '摩西又对可拉说：利未的子孙哪，你们听我说！'),
('CUV', '民数记', 4, 16, 9, '以色列的神从以色列会中将你们分别出来，使你们亲近他，办耶和华帐幕的事，并站在会众面前替他们当差。'),
('CUV', '民数记', 4, 16, 10, '耶和华又使你和你一切弟兄─利未的子孙─一同亲近他，这岂为小事？你们还要求祭司的职任么？'),
('CUV', '民数记', 4, 16, 11, '你和你一党的人聚集是要攻击耶和华。亚伦算甚么，你们竟向他发怨言呢？'),
('CUV', '民数记', 4, 16, 12, '摩西打发人去召以利押的儿子大坍、亚比兰。他们说：我们不上去！'),
('CUV', '民数记', 4, 16, 13, '你将我们从流奶与蜜之地领上来，要在旷野杀我们，这岂为小事？你还要自立为王辖管我们么？'),
('CUV', '民数记', 4, 16, 14, '并且你没有将我们领到流奶与蜜之地，也没有把田地和葡萄园给我们为业。难道你要剜这些人的眼睛么？我们不上去！'),
('CUV', '民数记', 4, 16, 15, '摩西就甚发怒，对耶和华说：求你不要享受他们的供物。我并没有夺过他们一匹驴，也没有害过他们一个人。'),
('CUV', '民数记', 4, 16, 16, '摩西对可拉说：明天，你和你一党的人，并亚伦，都要站在耶和华面前；'),
('CUV', '民数记', 4, 16, 17, '各人要拿一个香炉，共二百五十个，把香放在上面，到耶和华面前。你和亚伦也各拿自己的香炉。'),
('CUV', '民数记', 4, 16, 18, '于是他们各人拿一个香炉，盛上火，加上香，同摩西、亚伦站在会幕门前。'),
('CUV', '民数记', 4, 16, 19, '可拉招聚全会众到会幕门前，要攻击摩西、亚伦；耶和华的荣光就向全会众显现。'),
('CUV', '民数记', 4, 16, 20, '耶和华晓谕摩西、亚伦说：'),
('CUV', '民数记', 4, 16, 21, '你们离开这会众，我好在转眼之间把他们灭绝。'),
('CUV', '民数记', 4, 16, 22, '摩西、亚伦就俯伏在地，说：神，万人之灵的神阿，一人犯罪，你就要向全会众发怒么？'),
('CUV', '民数记', 4, 16, 23, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 16, 24, '你吩咐会众说：你们离开可拉、大坍、亚比兰帐棚的四围。'),
('CUV', '民数记', 4, 16, 25, '摩西起来，往大坍、亚比兰那里去；以色列的长老也随著他去。'),
('CUV', '民数记', 4, 16, 26, '他吩咐会众说：你们离开这恶人的帐棚罢，他们的物件，甚么都不可摸，恐怕你们陷在他们的罪中，与他们一同消灭。'),
('CUV', '民数记', 4, 16, 27, '于是众人离开可拉、大坍、亚比兰帐棚的四围。大坍、亚比兰带著妻子、儿女、小孩子，都出来，站在自己的帐棚门口。'),
('CUV', '民数记', 4, 16, 28, '摩西说：我行的这一切事本不是凭我自己心意行的，乃是耶和华打发我行的，必有证据使你们知道。'),
('CUV', '民数记', 4, 16, 29, '这些人死若与世人无异，或是他们所遭的与世人相同，就不是耶和华打发我来的。'),
('CUV', '民数记', 4, 16, 30, '倘若耶和华创作一件新事，使地开口，把他们和一切属他们的都吞下去，叫他们活活的坠落阴间，你们就明白这些人是藐视耶和华了。'),
('CUV', '民数记', 4, 16, 31, '摩西刚说完了这一切话，他们脚下的地就开了口，'),
('CUV', '民数记', 4, 16, 32, '把他们和他们的家眷，并一切属可拉的人丁、财物，都吞下去。'),
('CUV', '民数记', 4, 16, 33, '这样，他们和一切属他们的，都活活的坠落阴间；地口在他们上头照旧合闭，他们就从会中灭亡。'),
('CUV', '民数记', 4, 16, 34, '在他们四围的以色列众人听他们呼号，就都逃跑，说：恐怕地也把我们吞下去。'),
('CUV', '民数记', 4, 16, 35, '又有火从耶和华那里出来，烧灭了那献香的二百五十个人。'),
('CUV', '民数记', 4, 16, 36, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 16, 37, '你吩咐祭司亚伦的儿子以利亚撒从火中捡起那些香炉来，把火撒在别处，因为那些香炉是圣的。'),
('CUV', '民数记', 4, 16, 38, '把那些犯罪、自害己命之人的香炉，叫人锤成片子，用以包坛。那些香炉本是他们在耶和华面前献过的，所以是圣的，并且可以给以色列人作记号。'),
('CUV', '民数记', 4, 16, 39, '于是祭司以利亚撒将被烧之人所献的铜香炉拿来，人就锤出来，用以包坛，'),
('CUV', '民数记', 4, 16, 40, '给以色列人作纪念，使亚伦后裔之外的人不得近前来在耶和华面前烧香，免得他遭可拉和他一党所遭的。这乃是照耶和华藉著摩西所吩咐的。'),
('CUV', '民数记', 4, 16, 41, '第二天，以色列全会众都向摩西、亚伦发怨言说：你们杀了耶和华的百姓了。'),
('CUV', '民数记', 4, 16, 42, '会众聚集攻击摩西、亚伦的时候，向会幕观看，不料，有云彩遮盖了，耶和华的荣光显现。'),
('CUV', '民数记', 4, 16, 43, '摩西、亚伦就来到会幕前。'),
('CUV', '民数记', 4, 16, 44, '耶和华吩咐摩西说：'),
('CUV', '民数记', 4, 16, 45, '你们离开这会众，我好在转眼之间把他们灭绝。他们二人就俯伏于地。'),
('CUV', '民数记', 4, 16, 46, '摩西对亚伦说：拿你的香炉，把坛上的火盛在其中，又加上香，快快带到会众那里，为他们赎罪；因为有忿怒从耶和华那里出来，瘟疫已经发作了。'),
('CUV', '民数记', 4, 16, 47, '亚伦照著摩西所说的拿来，跑到会中，不料，瘟疫在百姓中已经发作了。他就加上香，为百姓赎罪。'),
('CUV', '民数记', 4, 16, 48, '他站在活人死人中间，瘟疫就止住了。'),
('CUV', '民数记', 4, 16, 49, '除了因可拉事情死的以外，遭瘟疫死的，共有一万四千七百人。'),
('CUV', '民数记', 4, 16, 50, '亚伦回到会幕门口，到摩西那里，瘟疫已经止住了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 17, 1, '耶和华对摩西说：'),
('CUV', '民数记', 4, 17, 2, '你晓谕以色列人，从他们手下取杖，每支派一根；从他们所有的首领，按著支派，共取十二根。你要将各人的名字写在各人的杖上，'),
('CUV', '民数记', 4, 17, 3, '并要将亚伦的名字写在利未的杖上，因为各族长必有一根杖。'),
('CUV', '民数记', 4, 17, 4, '你要把这些杖存在会幕内法柜前，就是我与你们相会之处。'),
('CUV', '民数记', 4, 17, 5, '后来我所拣选的那人，他的杖必发芽。这样，我必使以色列人向你们所发的怨言止息，不再达到我耳中。'),
('CUV', '民数记', 4, 17, 6, '于是摩西晓谕以色列人，他们的首领就把杖交给他，按著支派，每首领一根，共有十二根；亚伦的杖也在其中。'),
('CUV', '民数记', 4, 17, 7, '摩西就把杖存在法柜的帐幕内，在耶和华面前。'),
('CUV', '民数记', 4, 17, 8, '第二天，摩西进法柜的帐幕去。谁知利未族亚伦的杖已经发了芽，生了花苞，开了花，结了熟杏。'),
('CUV', '民数记', 4, 17, 9, '摩西就把所有的杖从耶和华面前拿出来，给以色列众人看；他们看见了，各首领就把自己的杖拿去。'),
('CUV', '民数记', 4, 17, 10, '耶和华吩咐摩西说：把亚伦的杖还放在法柜前，给这些背叛之子留作记号。这样，你就使他们向我发的怨言止息，免得他们死亡。'),
('CUV', '民数记', 4, 17, 11, '摩西就这样行。耶和华怎样吩咐他，他就怎样行了。'),
('CUV', '民数记', 4, 17, 12, '以色列人对摩西说：我们死喇！我们灭亡喇！都灭亡喇！'),
('CUV', '民数记', 4, 17, 13, '凡挨近耶和华帐幕的是必死的。我们都要死亡么？')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 18, 1, '耶和华对亚伦说：你和你的儿子，并你本族的人，要一同担当干犯圣所的罪孽。你和你的儿子也要一同担当干犯祭司职任的罪孽。'),
('CUV', '民数记', 4, 18, 2, '你要带你弟兄利未人，就是你祖宗支派的人前来，使他们与你联合，服事你，只是你和你的儿子，要一同在法柜的帐幕前供职。'),
('CUV', '民数记', 4, 18, 3, '他们要守所吩咐你的，并守全帐幕，只是不可挨近圣所的器具和坛，免得他们和你们都死亡。'),
('CUV', '民数记', 4, 18, 4, '他们要与你联合，也要看守会幕，办理帐幕一切的事，只是外人不可挨近你们。'),
('CUV', '民数记', 4, 18, 5, '你们要看守圣所和坛，免得忿怒再临到以色列人。'),
('CUV', '民数记', 4, 18, 6, '我已将你们的弟兄利未人从以色列人中拣选出来归耶和华，是给你们为赏赐的，为要办理会幕的事。'),
('CUV', '民数记', 4, 18, 7, '你和你的儿子要为一切属坛和幔子内的事一同守祭司的职任。你们要这样供职；我将祭司的职任给你们当作赏赐事奉我。凡挨近的外人必被治死。'),
('CUV', '民数记', 4, 18, 8, '耶和华晓谕亚伦说：我已将归我的举祭，就是以色列人一切分别为圣的物，交给你经管；因你受过膏，把这些都赐给你和你的子孙，当作永得的分。'),
('CUV', '民数记', 4, 18, 9, '以色列人归给我至圣的供物，就是一切的素祭、赎罪祭、赎愆祭，其中所有存留不经火的，都为至圣之物，要归给你和你的子孙。'),
('CUV', '民数记', 4, 18, 10, '你要拿这些当至圣物吃；凡男丁都可以吃。你当以此物为圣。'),
('CUV', '民数记', 4, 18, 11, '以色列人所献的举祭并摇祭都是你的；我已赐给你和你的儿女，当作永得的分；凡在你家中的洁净人都可以吃。'),
('CUV', '民数记', 4, 18, 12, '凡油中、新酒中、五谷中至好的，就是以色列人所献给耶和华初熟之物，我都赐给你。'),
('CUV', '民数记', 4, 18, 13, '凡从他们地上所带来给耶和华初熟之物也都要归与你。你家中的洁净人都可以吃。'),
('CUV', '民数记', 4, 18, 14, '以色列中一切永献的都必归与你。'),
('CUV', '民数记', 4, 18, 15, '他们所有奉给耶和华的，连人带牲畜，凡头生的，都要归给你；只是人头生的，总要赎出来；不洁净牲畜头生的，也要赎出来。'),
('CUV', '民数记', 4, 18, 16, '其中在一月之外所当赎的，要照你所估定的价，按圣所的平，用银子五舍客勒赎出来（一舍客勒是二十季拉）。'),
('CUV', '民数记', 4, 18, 17, '只是头生的牛，或是头生的绵羊和山羊，必不可赎，都是圣的，要把他的血洒在坛上，把他的脂油焚烧，当作馨香的火祭献给耶和华。'),
('CUV', '民数记', 4, 18, 18, '他的肉必归你，像被摇的胸、被举的右腿归你一样。'),
('CUV', '民数记', 4, 18, 19, '凡以色列人所献给耶和华圣物中的举祭，我都赐给你和你的儿女，当作永得的分。这是给你和你的后裔、在耶和华面前作为永远的盐约（盐即不废坏的意思）。'),
('CUV', '民数记', 4, 18, 20, '耶和华对亚伦说：你在以色列人的境内不可有产业，在他们中间也不可有分。我就是你的分，是你的产业。'),
('CUV', '民数记', 4, 18, 21, '凡以色列中出产的十分之一，我已赐给利未的子孙为业；因他们所办的是会幕的事，所以赐给他们为酬他们的劳。'),
('CUV', '民数记', 4, 18, 22, '从今以后，以色列人不可挨近会幕，免得他们担罪而死。'),
('CUV', '民数记', 4, 18, 23, '惟独利未人要办会幕的事，担当罪孽；这要作你们世世代代永远的定例。他们在以色列人中不可有产业；'),
('CUV', '民数记', 4, 18, 24, '因为以色列人中出产的十分之一，就是献给耶和华为举祭的，我已赐给利未人为业。所以我对他们说：在以色列人中不可有产业。'),
('CUV', '民数记', 4, 18, 25, '耶和华吩咐摩西说：'),
('CUV', '民数记', 4, 18, 26, '你晓谕利未人说：你们从以色列人中所取的十分之一，就是我给你们为业的，要再从那十分之一中取十分之一作为举祭献给耶和华，'),
('CUV', '民数记', 4, 18, 27, '这举祭要算为你们场上的谷，又如满酒醡的酒。'),
('CUV', '民数记', 4, 18, 28, '这样，你们从以色列人中所得十分之一也要作举祭献给耶和华，从这十分之一中，将所献给耶和华的举祭归给祭司亚伦。'),
('CUV', '民数记', 4, 18, 29, '奉给你们的一切礼物，要从其中将至好的，就是分别为圣的，献给耶和华为举祭。'),
('CUV', '民数记', 4, 18, 30, '所以你要对利未人说：你们从其中将至好的举起，这就算为你们场上的粮，又如酒醡的酒。'),
('CUV', '民数记', 4, 18, 31, '你们和你们家属随处可以吃；这原是你们的赏赐，是酬你们在会幕里办事的劳。'),
('CUV', '民数记', 4, 18, 32, '你们从其中将至好的举起，就不至因这物担罪。你们不可亵渎以色列人的圣物，免得死亡。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 19, 1, '耶和华晓谕摩西、亚伦说：'),
('CUV', '民数记', 4, 19, 2, '耶和华命定律法中的一条律例乃是这样说：你要吩咐以色列人，把一只没有残疾、未曾负轭、纯红的母牛牵到你这里来，'),
('CUV', '民数记', 4, 19, 3, '交给祭司以利亚撒；他必牵到营外，人就把牛宰在他面前。'),
('CUV', '民数记', 4, 19, 4, '祭司以利亚撒要用指头蘸这牛的血，向会幕前面弹七次。'),
('CUV', '民数记', 4, 19, 5, '人要在他眼前把这母牛焚烧；牛的皮、肉、血、粪都要焚烧。'),
('CUV', '民数记', 4, 19, 6, '祭司要把香柏木、牛膝草、朱红色线都丢在烧牛的火中。'),
('CUV', '民数记', 4, 19, 7, '祭司必不洁净到晚上，要洗衣服，用水洗身，然后可以进营。'),
('CUV', '民数记', 4, 19, 8, '烧牛的人必不洁净到晚上，也要洗衣服，用水洗身。'),
('CUV', '民数记', 4, 19, 9, '必有一个洁净的人收起母牛的灰，存在营外洁净的地方，为以色列会众调做除污秽的水。这本是除罪的。'),
('CUV', '民数记', 4, 19, 10, '收起母牛灰的人必不洁净到晚上，要洗衣服。这要给以色列人和寄居在他们中间的外人作为永远的定例。'),
('CUV', '民数记', 4, 19, 11, '摸了人死尸的，就必七天不洁净。'),
('CUV', '民数记', 4, 19, 12, '那人到第三天要用这除污秽的水洁净自己，第七天就洁净了。他若在第三天不洁净自己，第七天就不洁净了。'),
('CUV', '民数记', 4, 19, 13, '凡摸了人死尸、不洁净自己的，就玷污了耶和华的帐幕，这人必从以色列中剪除；因为那除污秽的水没有洒在他身上，他就为不洁净，污秽还在他身上。'),
('CUV', '民数记', 4, 19, 14, '人死在帐棚里的条例乃是这样：凡进那帐棚的，和一切在帐棚里的，都必七天不洁净。'),
('CUV', '民数记', 4, 19, 15, '凡敞口的器皿，就是没有扎上盖的，也是不洁净。'),
('CUV', '民数记', 4, 19, 16, '无论何人在田野里摸了被刀杀的，或是尸首，或是人的骨头，或是坟墓，就要七天不洁净。'),
('CUV', '民数记', 4, 19, 17, '要为这不洁净的人拿些烧成的除罪灰放在器皿里，倒上活水。'),
('CUV', '民数记', 4, 19, 18, '必当有一个洁净的人拿牛膝草蘸在这水中，把水洒在帐棚上，和一切器皿并帐棚内的众人身上，又洒在摸了骨头，或摸了被杀的，或摸了自死的，或摸了坟墓的那人身上。'),
('CUV', '民数记', 4, 19, 19, '第三天和第七天，洁净的人要洒水在不洁净的人身上，第七天就使他成为洁净。那人要洗衣服，用水洗澡，到晚上就洁净了。'),
('CUV', '民数记', 4, 19, 20, '但那污秽而不洁净自己的，要将他从会中剪除，因为他玷污了耶和华的圣所。除污秽的水没有洒在他身上，他是不洁净的。'),
('CUV', '民数记', 4, 19, 21, '这要给你们作为永远的定例。并且那洒除污秽水的人要洗衣服。凡摸除污秽水的，必不洁净到晚上。'),
('CUV', '民数记', 4, 19, 22, '不洁净人所摸的一切物就不洁净；摸了这物的人必不洁净到晚上。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 20, 1, '正月间，以色列全会众到了寻的旷野，就住在加低斯。米利暗死在那里，就葬在那里。'),
('CUV', '民数记', 4, 20, 2, '会众没有水喝，就聚集攻击摩西、亚伦。'),
('CUV', '民数记', 4, 20, 3, '百姓向摩西争闹说：我们的弟兄曾死在耶和华面前，我们恨不得与他们同死。'),
('CUV', '民数记', 4, 20, 4, '你们为何把耶和华的会众领到这旷野、使我们和牲畜都死在这里呢？'),
('CUV', '民数记', 4, 20, 5, '你们为何逼著我们出埃及、领我们到这坏地方呢？这地方不好撒种，也没有无花果树、葡萄树、石榴树，又没有水喝。'),
('CUV', '民数记', 4, 20, 6, '摩西、亚伦离开会众，到会幕门口，俯伏在地；耶和华的荣光向他们显现。'),
('CUV', '民数记', 4, 20, 7, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 20, 8, '你拿著杖去，和你的哥哥亚伦招聚会众，在他们眼前吩咐磐石发出水来，水就从磐石流出，给会众和他们的牲畜喝。'),
('CUV', '民数记', 4, 20, 9, '于是摩西照耶和华所吩咐的，从耶和华面前取了杖去。'),
('CUV', '民数记', 4, 20, 10, '摩西、亚伦就招聚会众到磐石前。摩西说：你们这些背叛的人听我说：我为你们使水从这磐石中流出来么？'),
('CUV', '民数记', 4, 20, 11, '摩西举手，用杖击打磐石两下，就有许多水流出来，会众和他们的牲畜都喝了。'),
('CUV', '民数记', 4, 20, 12, '耶和华对摩西、亚伦说：因为你们不信我，不在以色列人眼前尊我为圣，所以你们必不得领这会众进我所赐给他们的地去。'),
('CUV', '民数记', 4, 20, 13, '这水名叫米利巴水，是因以色列人向耶和华争闹，耶和华就在他们面前显为圣。（米利巴就是争闹的意思）'),
('CUV', '民数记', 4, 20, 14, '摩西从加低斯差遣使者去见以东王，说：你的弟兄以色列人这样说：我们所遭遇的一切艰难，'),
('CUV', '民数记', 4, 20, 15, '就是我们的列祖下到埃及，我们在埃及久住；埃及人恶待我们的列祖和我们，'),
('CUV', '民数记', 4, 20, 16, '我们哀求耶和华的时候，他听了我们的声音，差遣使者把我们从埃及领出来。这事你都知道。如今，我们在你边界上的城加低斯。'),
('CUV', '民数记', 4, 20, 17, '求你容我们从你的地经过。我们不走田间和葡萄园，也不喝井里的水，只走大道（原文作王道），不偏左右，直到过了你的境界。'),
('CUV', '民数记', 4, 20, 18, '以东王说：你不可从我的地经过，免得我带刀出去攻击你。'),
('CUV', '民数记', 4, 20, 19, '以色列人说：我们要走大道上去；我们和牲畜若喝你的水，必给你价值。不求别的，只求你容我们步行过去。'),
('CUV', '民数记', 4, 20, 20, '以东王说：你们不可经过！就率领许多人出来，要用强硬的手攻击以色列人。'),
('CUV', '民数记', 4, 20, 21, '这样，以东王不肯容以色列人从他的境界过去。于是他们转去，离开他。'),
('CUV', '民数记', 4, 20, 22, '以色列全会众从加低斯起行，到了何珥山。'),
('CUV', '民数记', 4, 20, 23, '耶和华在附近以东边界的何珥山上晓谕摩西、亚伦说：'),
('CUV', '民数记', 4, 20, 24, '亚伦要归到他列祖（原文作本民）那里。他必不得入我所赐给以色列人的地；因为在米利巴水，你们违背了我的命。'),
('CUV', '民数记', 4, 20, 25, '你带亚伦和他的儿子以利亚撒上何珥山，'),
('CUV', '民数记', 4, 20, 26, '把亚伦的圣衣脱下来，给他的儿子以利亚撒穿上；亚伦必死在那里，归他列祖。'),
('CUV', '民数记', 4, 20, 27, '摩西就照耶和华所吩咐的行。三人当著会众的眼前上了何珥山。'),
('CUV', '民数记', 4, 20, 28, '摩西把亚伦的圣衣脱下来，给他的儿子以利亚撒穿上，亚伦就死在山顶那里。于是摩西和以利亚撒下了山。'),
('CUV', '民数记', 4, 20, 29, '全会众，就是以色列全家，见亚伦已经死了，便都为亚伦哀哭了三十天。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 21, 1, '住南地的迦南人亚拉得王，听说以色列人从亚他林路来，就和以色列人争战，掳了他们几个人。'),
('CUV', '民数记', 4, 21, 2, '以色列人向耶和华发愿说：你若将这民交付我手，我就把他们的城邑尽行毁灭。'),
('CUV', '民数记', 4, 21, 3, '耶和华应允了以色列人，把迦南人交付他们，他们就把迦南人和迦南人的城邑尽行毁灭。那地方的名便叫何珥玛（何珥玛就是毁灭的意思）。'),
('CUV', '民数记', 4, 21, 4, '他们从何珥山起行，往红海那条路走，要绕过以东地。百姓因这路难行，心中甚是烦躁，'),
('CUV', '民数记', 4, 21, 5, '就怨讟神和摩西说：你们为甚么把我们从埃及领出来、使我们死在旷野呢？这里没有粮，没有水，我们的心厌恶这淡薄的食物。'),
('CUV', '民数记', 4, 21, 6, '于是耶和华使火蛇进入百姓中间，蛇就咬他们。以色列人中死了许多。'),
('CUV', '民数记', 4, 21, 7, '百姓到摩西那里，说：我们怨讟耶和华和你，有罪了。求你祷告耶和华，叫这些蛇离开我们。于是摩西为百姓祷告。'),
('CUV', '民数记', 4, 21, 8, '耶和华对摩西说：你制造一条火蛇，挂在杆子上；凡被咬的，一望这蛇，就必得活。'),
('CUV', '民数记', 4, 21, 9, '摩西便制造一条铜蛇，挂在杆子上；凡被蛇咬的，一望这铜蛇就活了。'),
('CUV', '民数记', 4, 21, 10, '以色列人起行，安营在阿伯。'),
('CUV', '民数记', 4, 21, 11, '又从阿伯起行，安营在以耶亚巴琳，与摩押相对的旷野，向日出之地。'),
('CUV', '民数记', 4, 21, 12, '从那里起行，安营在撒烈谷。'),
('CUV', '民数记', 4, 21, 13, '从那里起行，安营在亚嫩河那边。这亚嫩河是在旷野，从亚摩利的境界流出来的；原来亚嫩河是摩押的边界，在摩押和亚摩利人搭界的地方。'),
('CUV', '民数记', 4, 21, 14, '所以耶和华的战记上说：苏法的哇哈伯与亚嫩河的谷，'),
('CUV', '民数记', 4, 21, 15, '并向亚珥城众谷的下坡，是靠近摩押的境界。'),
('CUV', '民数记', 4, 21, 16, '以色列人从那里起行，到了比珥（比珥就是井的意思）。从前耶和华吩咐摩西说：招聚百姓，我好给他们水喝，说的就是这井。'),
('CUV', '民数记', 4, 21, 17, '当时，以色列人唱歌说：井阿，涌上水来！你们要向这井歌唱。'),
('CUV', '民数记', 4, 21, 18, '这井是首领和民中的尊贵人用圭用杖所挖所掘的。以色列人从旷野往玛他拿去，'),
('CUV', '民数记', 4, 21, 19, '从玛他拿到拿哈列，从拿哈列到巴末，'),
('CUV', '民数记', 4, 21, 20, '从巴末到了摩押地的谷，又到那下望旷野之毘斯迦的山顶。'),
('CUV', '民数记', 4, 21, 21, '以色列人差遣使者去见亚摩利人的王西宏，说：'),
('CUV', '民数记', 4, 21, 22, '求你容我们从你的地经过；我们不偏入田间和葡萄园，也不喝井里的水，只走大道（原文作王道），直到过了你的境界。'),
('CUV', '民数记', 4, 21, 23, '西宏不容以色列人从他的境界经过，就招聚他的众民出到旷野，要攻击以色列人，到了雅杂与以色列人争战。'),
('CUV', '民数记', 4, 21, 24, '以色列人用刀杀了他，得了他的地，从亚嫩河到雅博河，直到亚扪人的境界，因为亚扪人的境界多有坚垒。'),
('CUV', '民数记', 4, 21, 25, '以色列人夺取这一切的城邑，也住亚摩利人的城邑，就是希实本与希实本的一切乡村。'),
('CUV', '民数记', 4, 21, 26, '这希实本是亚摩利王西宏的京城；西宏曾与摩押的先王争战，从他手中夺取了全地，直到亚嫩河。'),
('CUV', '民数记', 4, 21, 27, '所以那些作诗歌的说：你们来到希实本；愿西宏的城被修造，被建立。'),
('CUV', '民数记', 4, 21, 28, '因为有火从希实本发出，有火燄出于西宏的城，烧尽摩押的亚珥和亚嫩河邱坛的祭司（祭司原文作主）。'),
('CUV', '民数记', 4, 21, 29, '摩押阿，你有祸了！基抹的民哪，你们灭亡了！基抹的男子逃奔，女子被掳，交付亚摩利的王西宏。'),
('CUV', '民数记', 4, 21, 30, '我们射了他们；希实本直到底本尽皆毁灭。我们使地变成荒场，直到挪法；这挪法直延到米底巴。'),
('CUV', '民数记', 4, 21, 31, '这样，以色列人就住在亚摩利人之地。'),
('CUV', '民数记', 4, 21, 32, '摩西打发人去窥探雅谢，以色列人就占了雅谢的镇市，赶出那里的亚摩利人。'),
('CUV', '民数记', 4, 21, 33, '以色列人转回，向巴珊去。巴珊王噩和他的众民都出来，在以得来与他们交战。'),
('CUV', '民数记', 4, 21, 34, '耶和华对摩西说：不要怕他！因我已将他和他的众民，并他的地，都交在你手中；你要待他像从前待住希实本的亚摩利王西宏一般。'),
('CUV', '民数记', 4, 21, 35, '于是他们杀了他和他的众子，并他的众民，没有留下一个，就得了他的地。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 22, 1, '以色列人起行，在摩押平原、约但河东，对著耶利哥安营。'),
('CUV', '民数记', 4, 22, 2, '以色列人向亚摩利人所行的一切事，西拨的儿子巴勒都看见了。'),
('CUV', '民数记', 4, 22, 3, '摩押人因以色列民甚多，就大大惧怕，心内忧急，'),
('CUV', '民数记', 4, 22, 4, '对米甸的长老说：现在这众人要把我们四围所有的一概餂尽，就如牛餂尽田间的草一般。那时西拨的儿子巴勒作摩押王。'),
('CUV', '民数记', 4, 22, 5, '他差遣使者往大河边的毘夺去，到比珥的儿子巴兰本乡那里，召巴兰来，说：有一宗民从埃及出来，遮满地面，与我对居。'),
('CUV', '民数记', 4, 22, 6, '这民比我强盛，现在求你来为我咒诅他们，或者我能得胜，攻打他们，赶出此地。因为我知道，你为谁祝福，谁就得福；你咒诅谁，谁就受咒诅。'),
('CUV', '民数记', 4, 22, 7, '摩押的长老和米甸的长老手里拿著卦金，到了巴兰那里，将巴勒的话都告诉了他。'),
('CUV', '民数记', 4, 22, 8, '巴兰说：你们今夜在这里住宿，我必照耶和华所晓谕我的回报你们。摩押的使臣就在巴兰那里住下了。'),
('CUV', '民数记', 4, 22, 9, '神临到巴兰那里，说：在你这里的人都是谁？'),
('CUV', '民数记', 4, 22, 10, '巴兰回答说：是摩押王西拨的儿子巴勒打发人到我这里来，说：'),
('CUV', '民数记', 4, 22, 11, '从埃及出来的民遮满地面，你来为我咒诅他们，或者我能与他们争战，把他们赶出去。'),
('CUV', '民数记', 4, 22, 12, '神对巴兰说：你不可同他们去，也不可咒诅那民，因为那民是蒙福的。'),
('CUV', '民数记', 4, 22, 13, '巴兰早晨起来，对巴勒的使臣说：你们回本地去罢，因为耶和华不容我和你们同去。'),
('CUV', '民数记', 4, 22, 14, '摩押的使臣就起来，回巴勒那里去，说：巴兰不肯和我们同来。'),
('CUV', '民数记', 4, 22, 15, '巴勒又差遣使臣，比先前的又多又尊贵。'),
('CUV', '民数记', 4, 22, 16, '他们到了巴兰那里，对他说：西拨的儿子巴勒这样说：求你不容甚么事拦阻你不到我这里来，'),
('CUV', '民数记', 4, 22, 17, '因为我必使你得极大的尊荣。你向我要甚么，我就给你甚么；只求你来为我咒诅这民。'),
('CUV', '民数记', 4, 22, 18, '巴兰回答巴勒的臣仆说：巴勒就是将他满屋的金银给我，我行大事小事也不得越过耶和华─我神的命。'),
('CUV', '民数记', 4, 22, 19, '现在我请你们今夜在这里住宿，等我得知耶和华还要对我说甚么。'),
('CUV', '民数记', 4, 22, 20, '当夜，神临到巴兰那里，说：这些人若来召你，你就起来同他们去，你只要遵行我对你所说的话。'),
('CUV', '民数记', 4, 22, 21, '巴兰早晨起来，备上驴，和摩押的使臣一同去了。'),
('CUV', '民数记', 4, 22, 22, '神因他去就发了怒；耶和华的使者站在路上敌挡他。他骑著驴，有两个仆人跟随他。'),
('CUV', '民数记', 4, 22, 23, '驴看见耶和华的使者站在路上，手里有拔出来的刀，就从路上跨进田间，巴兰便打驴，要叫他回转上路。'),
('CUV', '民数记', 4, 22, 24, '耶和华的使者就站在葡萄园的窄路上；这边有墙，那边也有墙。'),
('CUV', '民数记', 4, 22, 25, '驴看见耶和华的使者，就贴靠墙，将巴兰的脚挤伤了；巴兰又打驴。'),
('CUV', '民数记', 4, 22, 26, '耶和华的使者又往前去，站在狭窄之处，左右都没有转折的地方。'),
('CUV', '民数记', 4, 22, 27, '驴看见耶和华的使者，就卧在巴兰底下，巴兰发怒，用杖打驴。'),
('CUV', '民数记', 4, 22, 28, '耶和华叫驴开口，对巴兰说：我向你行了甚么，你竟打我这三次呢？'),
('CUV', '民数记', 4, 22, 29, '巴兰对驴说：因为你戏弄我，我恨不能手中有刀，把你杀了。'),
('CUV', '民数记', 4, 22, 30, '驴对巴兰说：我不是你从小时直到今日所骑的驴么？我素常向你这样行过么？巴兰说：没有。'),
('CUV', '民数记', 4, 22, 31, '当时，耶和华使巴兰的眼目明亮，他就看见耶和华的使者站在路上，手里有拔出来的刀，巴兰便低头俯伏在地。'),
('CUV', '民数记', 4, 22, 32, '耶和华的使者对他说：你为何这三次打你的驴呢？我出来敌挡你，因你所行的，在我面前偏僻。'),
('CUV', '民数记', 4, 22, 33, '驴看见我就三次从我面前偏过去；驴若没有偏过去，我早把你杀了，留他存活。'),
('CUV', '民数记', 4, 22, 34, '巴兰对耶和华的使者说：我有罪了。我不知道你站在路上阻挡我；你若不喜欢我去，我就转回。'),
('CUV', '民数记', 4, 22, 35, '耶和华的使者对巴兰说：你同这些人去罢！你只要说我对你说的话。于是巴兰同著巴勒的使臣去了。'),
('CUV', '民数记', 4, 22, 36, '巴勒听见巴兰来了，就往摩押京城去迎接他；这城是在边界上，在亚嫩河旁。'),
('CUV', '民数记', 4, 22, 37, '巴勒对巴兰说：我不是急急的打发人到你那里去召你么？你为何不到我这里来呢？我岂不能使你得尊荣么？'),
('CUV', '民数记', 4, 22, 38, '巴兰说：我已经到你这里来了！现在我岂能擅自说甚么呢？神将甚么话传给我，我就说甚么。'),
('CUV', '民数记', 4, 22, 39, '巴兰和巴勒同行，来到基列胡琐。'),
('CUV', '民数记', 4, 22, 40, '巴勒宰了（原文作献）牛羊，送给巴兰和陪伴的使臣。'),
('CUV', '民数记', 4, 22, 41, '到了早晨，巴勒领巴兰到巴力的高处；巴兰从那里观看以色列营的边界。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 23, 1, '巴兰对巴勒说：你在这里给我筑七座坛，为我豫备七只公牛，七只公羊。'),
('CUV', '民数记', 4, 23, 2, '巴勒照巴兰的话行了。巴勒和巴兰在每座坛上献一只公牛，一只公羊。'),
('CUV', '民数记', 4, 23, 3, '巴兰对巴勒说：你站在你的燔祭旁边，我且往前去，或者耶和华来迎见我。他指示我甚么，我必告诉你。于是巴兰上一净光的高处。'),
('CUV', '民数记', 4, 23, 4, '神迎见巴兰；巴兰说：我豫备了七座坛，在每座坛上献了一只公牛，一只公羊。'),
('CUV', '民数记', 4, 23, 5, '耶和华将话传给巴兰，又说：你回到巴勒那里，要如此如此说。'),
('CUV', '民数记', 4, 23, 6, '他就回到巴勒那里，见他同摩押的使臣都站在燔祭旁边。'),
('CUV', '民数记', 4, 23, 7, '巴兰便题起诗歌说：巴勒引我出亚兰，摩押王引我出东山，说：来阿，为我咒诅雅各；来阿，怒骂以色列。'),
('CUV', '民数记', 4, 23, 8, '神没有咒诅的，我焉能咒诅？耶和华没有怒骂的，我焉能怒骂？'),
('CUV', '民数记', 4, 23, 9, '我从高峰看他，从小山望他；这是独居的民，不列在万民中。'),
('CUV', '民数记', 4, 23, 10, '谁能数点雅各的尘土？谁能计算以色列的四分之一？我愿如义人之死而死；我愿如义人之终而终。'),
('CUV', '民数记', 4, 23, 11, '巴勒对巴兰说：你向我做的是甚么事呢？我领你来咒诅我的仇敌，不料，你竟为他们祝福。'),
('CUV', '民数记', 4, 23, 12, '他回答说：耶和华传给我的话，我能不谨慎传说么？'),
('CUV', '民数记', 4, 23, 13, '巴勒说：求你同我往别处去，在那里可以看见他们；你不能全看见，只能看见他们边界上的人。在那里要为我咒诅他们。'),
('CUV', '民数记', 4, 23, 14, '于是领巴兰到了琐腓田，上了毘斯迦山顶，筑了七座坛；每座坛上献一只公牛，一只公羊。'),
('CUV', '民数记', 4, 23, 15, '巴兰对巴勒说：你站在这燔祭旁边，等我往那边去迎见耶和华。'),
('CUV', '民数记', 4, 23, 16, '耶和华临到巴兰那里，将话传给他；又说：你回到巴勒那里，要如此如此说。'),
('CUV', '民数记', 4, 23, 17, '他就回到巴勒那里，见他站在燔祭旁边；摩押的使臣也和他在一处。巴勒问他说：耶和华说了甚么话呢？'),
('CUV', '民数记', 4, 23, 18, '巴兰就题诗歌说：巴勒，你起来听；西拨的儿子，你听我言。'),
('CUV', '民数记', 4, 23, 19, '神非人，必不致说谎，也非人子，必不致后悔。他说话岂不照著行呢？他发言岂不要成就呢？'),
('CUV', '民数记', 4, 23, 20, '我奉命祝福；神也曾赐福，此事我不能翻转。'),
('CUV', '民数记', 4, 23, 21, '他未见雅各中有罪孽，也未见以色列中有奸恶。耶和华─他的神和他同在；有欢呼王的声音在他们中间。'),
('CUV', '民数记', 4, 23, 22, '神领他们出埃及；他们似乎有野牛之力。'),
('CUV', '民数记', 4, 23, 23, '断没有法术可以害雅各，也没有占卜可以害以色列。现在必有人论及雅各，就是论及以色列说：神为他行了何等的大事！'),
('CUV', '民数记', 4, 23, 24, '这民起来，仿佛母狮，挺身，好像公狮，未曾吃野食，未曾喝被伤者之血，决不躺卧。'),
('CUV', '民数记', 4, 23, 25, '巴勒对巴兰说：你一点不要咒诅他们，也不要为他们祝福。'),
('CUV', '民数记', 4, 23, 26, '巴兰回答巴勒说：我岂不是告诉你说凡耶和华所说的，我必须遵行么？'),
('CUV', '民数记', 4, 23, 27, '巴勒对巴兰说：来罢，我领你往别处去，或者神喜欢你在那里为我咒诅他们。'),
('CUV', '民数记', 4, 23, 28, '巴勒就领巴兰到那下望旷野的毘珥山顶上。'),
('CUV', '民数记', 4, 23, 29, '巴兰对巴勒说：你在这里为我筑七座坛，又在这里为我豫备七只公牛，七只公羊。'),
('CUV', '民数记', 4, 23, 30, '巴勒就照巴兰的话行，在每座坛上献一只公牛，一只公羊。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 24, 1, '巴兰见耶和华喜欢赐福与以色列，就不像前两次去求法术，却面向旷野。'),
('CUV', '民数记', 4, 24, 2, '巴兰举目，看见以色列人照著支派居住。神的灵就临到他身上，'),
('CUV', '民数记', 4, 24, 3, '他便题起诗歌说：比珥的儿子巴兰说，眼目闭住的人说，（闭住或作：睁开）'),
('CUV', '民数记', 4, 24, 4, '得听神的言语，得见全能者的异象，眼目睁开而仆倒的人说：'),
('CUV', '民数记', 4, 24, 5, '雅各阿，你的帐棚何等华美！以色列阿，你的帐幕何其华丽！'),
('CUV', '民数记', 4, 24, 6, '如接连的山谷，如河旁的园子，如耶和华所栽的沉香树，如水边的香柏木。'),
('CUV', '民数记', 4, 24, 7, '水要从他的桶里流出；种子要撒在多水之处。他的王必超过亚甲；他的国必要振兴。'),
('CUV', '民数记', 4, 24, 8, '神领他出埃及；他似乎有野牛之力。他要吞吃敌国，折断他们的骨头，用箭射透他们。'),
('CUV', '民数记', 4, 24, 9, '他蹲如公狮，卧如母狮，谁敢惹他？凡给你祝福的，愿他蒙福；凡咒诅你的，愿他受咒诅。'),
('CUV', '民数记', 4, 24, 10, '巴勒向巴兰生气，就拍起手来，对巴兰说：我召你来为我咒诅仇敌，不料，你这三次竟为他们祝福。'),
('CUV', '民数记', 4, 24, 11, '如今你快回本地去罢！我想使你得大尊荣，耶和华却阻止你不得尊荣。'),
('CUV', '民数记', 4, 24, 12, '巴兰对巴勒说：我岂不是对你所差遣到我那里的使者说：'),
('CUV', '民数记', 4, 24, 13, '巴勒就是将他满屋的金银给我，我也不得越过耶和华的命，凭自己的心意行好行歹。耶和华说甚么，我就要说甚么？'),
('CUV', '民数记', 4, 24, 14, '现在我要回本族去。你来，我告诉你这民日后要怎样待你的民。'),
('CUV', '民数记', 4, 24, 15, '他就题起诗歌说：比珥的儿子巴兰说：眼目闭住的人说，（闭住或作：睁开）'),
('CUV', '民数记', 4, 24, 16, '得听神的言语，明白至高者的意旨，看见全能者的异象，眼目睁开而仆倒的人说：'),
('CUV', '民数记', 4, 24, 17, '我看他却不在现时；我望他却不在近日。有星要出于雅各，有杖要兴于以色列，必打破摩押的四角，毁坏扰乱.之子。'),
('CUV', '民数记', 4, 24, 18, '他必得以东为基业，又得仇敌之地西珥为产业；以色列必行事勇敢。'),
('CUV', '民数记', 4, 24, 19, '有一位出于雅各的，必掌大权；他要除灭城中的余民。'),
('CUV', '民数记', 4, 24, 20, '巴兰观看亚玛力，就题起诗歌说：亚玛力原为诸国之首，但他终必沉沦。'),
('CUV', '民数记', 4, 24, 21, '巴兰观看基尼人，就题起诗歌说：你的住处本是坚固；你的窝巢做在岩穴中。'),
('CUV', '民数记', 4, 24, 22, '然而基尼必至衰微，直到亚述把你掳去。'),
('CUV', '民数记', 4, 24, 23, '巴兰又题起诗歌说：哀哉！神行这事，谁能得活？'),
('CUV', '民数记', 4, 24, 24, '必有人乘船从基提界而来，苦害亚述，苦害希伯；他也必至沉沦。'),
('CUV', '民数记', 4, 24, 25, '于是巴兰起来，回他本地去；巴勒也回去了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 25, 1, '以色列人住在什亭，百姓与摩押女子行起淫乱。'),
('CUV', '民数记', 4, 25, 2, '因为这女子叫百姓来，一同给他们的神献祭，百姓就吃他们的祭物，跪拜他们的神。'),
('CUV', '民数记', 4, 25, 3, '以色列人与巴力毘珥连合，耶和华的怒气就向以色列人发作。'),
('CUV', '民数记', 4, 25, 4, '耶和华吩咐摩西说：将百姓中所有的族长在我面前对著日头悬挂，使我向以色列人所发的怒气可以消了。'),
('CUV', '民数记', 4, 25, 5, '于是摩西吩咐以色列的审判官说：凡属你们的人，有与巴力毘珥连合的，你们各人要把他们杀了。'),
('CUV', '民数记', 4, 25, 6, '摩西和以色列全会众正在会幕门前哭泣的时候，谁知，有以色列中的一个人，当他们眼前，带著一个米甸女人到他弟兄那里去。'),
('CUV', '民数记', 4, 25, 7, '祭司亚伦的孙子，以利亚撒的儿子非尼哈看见了，就从会中起来，手里拿著枪，'),
('CUV', '民数记', 4, 25, 8, '跟随那以色列人进亭子里去，便将以色列人和那女人由腹中刺透。这样，在以色列人中瘟疫就止息了。'),
('CUV', '民数记', 4, 25, 9, '那时遭瘟疫死的，有二万四千人。'),
('CUV', '民数记', 4, 25, 10, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 25, 11, '祭司亚伦的孙子，以利亚撒的儿子非尼哈，使我向以色列人所发的怒消了；因他在他们中间，以我的忌邪为心，使我不在忌邪中把他们除灭。'),
('CUV', '民数记', 4, 25, 12, '因此，你要说：我将我平安的约赐给他。'),
('CUV', '民数记', 4, 25, 13, '这约要给他和他的后裔，作为永远当祭司职任的约；因他为神有忌邪的心，为以色列人赎罪。'),
('CUV', '民数记', 4, 25, 14, '那与米甸女人一同被杀的以色列人，名叫心利，是撒路的儿子，是西缅一个宗族的首领。'),
('CUV', '民数记', 4, 25, 15, '那被杀的米甸女人，名叫哥斯比，是苏珥的女儿；这苏珥是米甸.一个宗族的首领。'),
('CUV', '民数记', 4, 25, 16, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 25, 17, '你要扰害米甸人，击杀他们；'),
('CUV', '民数记', 4, 25, 18, '因为他们用诡计扰害你们，在毘珥的事上和他们的姊妹、米甸首领的女儿哥斯比的事上，用这诡计诱惑了你们；这哥斯比，当瘟疫流行的日子，因毘珥的事被杀了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 26, 1, '瘟疫之后，耶和华晓谕摩西和祭司亚伦的儿子以利亚撒说：'),
('CUV', '民数记', 4, 26, 2, '你们要将以色列全会众，按他们的宗族，凡以色列中从二十岁以外、能出去打仗的，计算总数。'),
('CUV', '民数记', 4, 26, 3, '摩西和祭司以利亚撒在摩押平原与耶利哥相对的约但河边向以色列人说：'),
('CUV', '民数记', 4, 26, 4, '将你们中间从二十岁以外的计算总数；是照耶和华吩咐出埃及地的摩西和以色列人的话。'),
('CUV', '民数记', 4, 26, 5, '以色列的长子是流便。流便的众子：属哈诺的，有哈诺族；属法路的，有法路族；'),
('CUV', '民数记', 4, 26, 6, '属希斯伦的，有希斯伦族；属迦米的，有迦米族；'),
('CUV', '民数记', 4, 26, 7, '这就是流便的各族；其中被数的，共有四万三千七百三十名。'),
('CUV', '民数记', 4, 26, 8, '法路的儿子是以利押。'),
('CUV', '民数记', 4, 26, 9, '以利押的众子是尼母利、大坍、亚比兰。这大坍、亚比兰，就是从会中选召的，与可拉一党同向耶和华争闹的时候也向摩西、亚伦争闹；'),
('CUV', '民数记', 4, 26, 10, '地便开口吞了他们，和可拉、可拉的党类一同死亡。那时火烧灭了二百五十个人；他们就作了警戒。'),
('CUV', '民数记', 4, 26, 11, '然而可拉的众子没有死亡。'),
('CUV', '民数记', 4, 26, 12, '按著家族，西缅的众子：属尼母利的，有尼母利族；属雅悯的，有雅悯族；属雅斤的，有雅斤族；'),
('CUV', '民数记', 4, 26, 13, '属谢拉的，有谢拉族；属扫罗的，有扫罗族。'),
('CUV', '民数记', 4, 26, 14, '这就是西缅的各族，共有二万二千二百名。'),
('CUV', '民数记', 4, 26, 15, '按著家族，迦得的众子：属洗分的，有洗分族；属哈基的，有哈基族；属书尼的，有书尼族；'),
('CUV', '民数记', 4, 26, 16, '属阿斯尼的，有阿斯尼族；属以利的，有以利族；'),
('CUV', '民数记', 4, 26, 17, '属亚律的，有亚律族；属亚列利的，有亚列利族。'),
('CUV', '民数记', 4, 26, 18, '这就是迦得子孙的各族，照他们中间被数的，共有四万零五百名。'),
('CUV', '民数记', 4, 26, 19, '犹大的儿子是珥和俄南。这珥和俄南死在迦南地。'),
('CUV', '民数记', 4, 26, 20, '按著家族，犹大其余的众子：属示拉的，有示拉族；属法勒斯的，有法勒斯族；属谢拉的，有谢拉族。'),
('CUV', '民数记', 4, 26, 21, '法勒斯的儿子：属希斯伦的，有希斯伦族；属哈母勒的，有哈母勒族。'),
('CUV', '民数记', 4, 26, 22, '这就是犹大的各族，照他们中间被数的，共有七万六千五百名。'),
('CUV', '民数记', 4, 26, 23, '按著家族，以萨迦的众子：属陀拉的，有陀拉族；属普瓦的，有普瓦族；'),
('CUV', '民数记', 4, 26, 24, '属雅述的，有雅述族；属伸仑的，有伸仑族。'),
('CUV', '民数记', 4, 26, 25, '这就是以萨迦的各族，照他们中间被数的，共有六万四千三百名。'),
('CUV', '民数记', 4, 26, 26, '按著家族，西布伦的众子：属西烈的，有西烈族；属以伦的，有以伦族；属雅利的，有雅利族。'),
('CUV', '民数记', 4, 26, 27, '这就是西布伦的各族，照他们中间被数的，共有六万零五百名。'),
('CUV', '民数记', 4, 26, 28, '按著家族，约瑟的儿子有玛拿西、以法莲。'),
('CUV', '民数记', 4, 26, 29, '玛拿西的众子：属玛吉的，有玛吉族；玛吉生基列；属基列的，有基列族。'),
('CUV', '民数记', 4, 26, 30, '基列的众子：属伊以谢的，有伊以谢族；属希勒的，有希勒族；'),
('CUV', '民数记', 4, 26, 31, '属亚斯烈的，有亚斯烈族；属示剑的，有示剑族；'),
('CUV', '民数记', 4, 26, 32, '属示米大的，有示米大族；属希弗的，有希弗族；。'),
('CUV', '民数记', 4, 26, 33, '希弗的儿子西罗非哈没儿子，只有女儿。西罗非哈女儿的名字就是玛拉、挪阿、曷拉、密迦、得撒。'),
('CUV', '民数记', 4, 26, 34, '这就是玛拿西的各族；他们中间被数的，共有五万二千七百名。'),
('CUV', '民数记', 4, 26, 35, '按著家族，以法莲的众子：属书提拉的，有书提拉族；属比结的，有比结族；属他罕的，有他罕族。'),
('CUV', '民数记', 4, 26, 36, '书提拉的众子：属以兰的，有以兰族。'),
('CUV', '民数记', 4, 26, 37, '这就是以法莲子孙的各族，照他们中间被数的，共有三万二千五百名。按著家族，这都是约瑟的子孙。'),
('CUV', '民数记', 4, 26, 38, '按著家族，便雅悯众子，属比拉的，有比拉族；属亚实别的，有亚实别族；属亚希兰的，有亚希兰族；'),
('CUV', '民数记', 4, 26, 39, '属书反的，有书反族；属户反的，有户反族。'),
('CUV', '民数记', 4, 26, 40, '比拉的众子是亚勒、乃幔。属亚勒的，有亚勒族；属乃幔的，有乃幔族。'),
('CUV', '民数记', 4, 26, 41, '按著家族，这就是便雅悯的子孙，其中被数的，共有四万五千六百名。'),
('CUV', '民数记', 4, 26, 42, '按著家族，但的众子：属书含的，有书含族。按著家族，这就是但的各族。'),
('CUV', '民数记', 4, 26, 43, '照其中被数的，书含所有的各族，共有六万四千四百名。'),
('CUV', '民数记', 4, 26, 44, '按著家族，亚设的众子：属音拿的，有音拿族；属亦施韦的，有亦施韦族；属比利亚的，有比利亚族。'),
('CUV', '民数记', 4, 26, 45, '比利亚的众子：属希别的，有希别族；属玛结的，有玛结族。'),
('CUV', '民数记', 4, 26, 46, '亚设的女儿名叫西拉。'),
('CUV', '民数记', 4, 26, 47, '这就是亚设子孙的各族，照他们中间被数的，共有五万三千四百名。'),
('CUV', '民数记', 4, 26, 48, '按著家族，拿弗他利的众子：属雅薛的，有雅薛族；属沽尼的，有沽尼族；'),
('CUV', '民数记', 4, 26, 49, '属耶色的，有耶色族；属示冷的，有示冷族。'),
('CUV', '民数记', 4, 26, 50, '按著家族，这就是拿弗他利的各族；他们中间被数的，共有四万五千四百名。'),
('CUV', '民数记', 4, 26, 51, '以色列人中被数的，共有六十万零一千七百三十名。'),
('CUV', '民数记', 4, 26, 52, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 26, 53, '你要按著人名的数目将地分给这些人为业。'),
('CUV', '民数记', 4, 26, 54, '人多的，你要把产业多分给他们；人少的，你要把产业少分给他们；要照被数的人数，把产业分给各人。'),
('CUV', '民数记', 4, 26, 55, '虽是这样，还要拈阄分地。他们要按著祖宗各支派的名字承受为业。'),
('CUV', '民数记', 4, 26, 56, '要按著所拈的阄，看人数多，人数少，把产业分给他们。'),
('CUV', '民数记', 4, 26, 57, '利未人，按著他们的各族被数的：属革顺的，有革顺族；属哥辖的，有哥辖族；属米拉利的，有米拉利族。'),
('CUV', '民数记', 4, 26, 58, '利未的各族有立尼族、希伯伦族、玛利族、母示族、可拉族。哥辖生暗兰。'),
('CUV', '民数记', 4, 26, 59, '暗兰的妻名叫约基别，是利未女子，生在埃及。他给暗兰生了亚伦、摩西，并他们的姊姊米利暗。'),
('CUV', '民数记', 4, 26, 60, '亚伦生拿答、亚比户、以利亚撒、以他玛。'),
('CUV', '民数记', 4, 26, 61, '拿答、亚比户在耶和华面前献凡火的时候就死了。'),
('CUV', '民数记', 4, 26, 62, '利未人中，凡一个月以外、被数的男丁，共有二万三千。他们本来没有数在以色列人中；因为在以色列人中，没有分给他们产业。'),
('CUV', '民数记', 4, 26, 63, '这些就是被摩西和祭司以利亚撒所数的；他们在摩押平原与耶利哥相对的约但河边数点以色列人。'),
('CUV', '民数记', 4, 26, 64, '但被数的人中，没有一个是摩西和祭司亚伦从前在西乃的旷野所数的以色列人，'),
('CUV', '民数记', 4, 26, 65, '因为耶和华论到他们说：他们必要死在旷野。所以，除了耶孚尼的儿子迦勒和嫩的儿子约书亚以外，连一个人也没有存留。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 27, 1, '属约瑟的儿子玛拿西的各族，有玛拿西的玄孙，玛吉的曾孙，基列的孙子，希弗的儿子西罗非哈的女儿，名叫玛拉、挪阿、曷拉、密迦、得撒。他们前来，'),
('CUV', '民数记', 4, 27, 2, '站在会幕门口，在摩西和祭司以利亚撒，并众首领与全会众面前，说：'),
('CUV', '民数记', 4, 27, 3, '我们的父亲死在旷野。他不与可拉同党聚集攻击耶和华，是在自己罪中死的；他也没有儿子。'),
('CUV', '民数记', 4, 27, 4, '为甚么因我们的父亲没有儿子就把他的名从他族中除掉呢？求你们在我们父亲的弟兄中分给我们产业。'),
('CUV', '民数记', 4, 27, 5, '于是，摩西将他们的案件呈到耶和华面前。'),
('CUV', '民数记', 4, 27, 6, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 27, 7, '西罗非哈的女儿说得有理。你定要在他们父亲的弟兄中，把地分给他们为业；要将他们父亲的产业归给他们。'),
('CUV', '民数记', 4, 27, 8, '你也要晓谕以色列人说：人若死了没有儿子，就要把他的产业归给他的女儿。'),
('CUV', '民数记', 4, 27, 9, '他若没有女儿，就要把他的产业给他的弟兄。'),
('CUV', '民数记', 4, 27, 10, '他若没有弟兄，就要把他的产业给他父亲的弟兄。'),
('CUV', '民数记', 4, 27, 11, '他父亲若没有弟兄，就要把他的产业给他族中最近的亲属，他便要得为业。这要作以色列人的律例典章，是照耶和华吩咐摩西的。'),
('CUV', '民数记', 4, 27, 12, '耶和华对摩西说：你上这亚巴琳山，观看我所赐给以色列人的地。'),
('CUV', '民数记', 4, 27, 13, '看了以后，你也必归到你列祖（原文作本民）那里，像你哥哥亚伦一样。'),
('CUV', '民数记', 4, 27, 14, '因为你们在寻的旷野，当会众争闹的时候，违背了我的命，没有在涌水之地、会众眼前尊我为圣。（这水就是寻的旷野加低斯米利巴水。）'),
('CUV', '民数记', 4, 27, 15, '摩西对耶和华说：'),
('CUV', '民数记', 4, 27, 16, '愿耶和华万人之灵的神，立一个人治理会众，'),
('CUV', '民数记', 4, 27, 17, '可以在他们面前出入，也可以引导他们，免得耶和华的会众如同没有牧人的羊群一般。'),
('CUV', '民数记', 4, 27, 18, '耶和华对摩西说：嫩的儿子约书亚是心中有圣灵的；你将他领来，按手在他头上，'),
('CUV', '民数记', 4, 27, 19, '使他站在祭司以利亚撒和全会众面前，嘱咐他，'),
('CUV', '民数记', 4, 27, 20, '又将你的尊荣给他几分，使以色列全会众都听从他。'),
('CUV', '民数记', 4, 27, 21, '他要站在祭司以利亚撒面前；以利亚撒要凭乌陵的判断，在耶和华面前为他求问。他和以色列全会众都要遵以利亚撒的命出入。'),
('CUV', '民数记', 4, 27, 22, '于是摩西照耶和华所吩咐的将约书亚领来，使他站在祭司以利亚撒和全会众面前。'),
('CUV', '民数记', 4, 27, 23, '按手在他头上，嘱咐他，是照耶和华藉摩西所说的话。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 28, 1, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 28, 2, '你要吩咐以色列人说：献给我的供物，就是献给我作馨香火祭的食物，你们要按日期献给我；'),
('CUV', '民数记', 4, 28, 3, '又要对他们说：你们要献给耶和华的火祭，就是没有残疾、一岁的公羊羔，每日两只，作为常献的燔祭。'),
('CUV', '民数记', 4, 28, 4, '早晨要献一只，黄昏的时候要献一只；'),
('CUV', '民数记', 4, 28, 5, '又用细面伊法十分之一，并捣成的油一欣四分之一，调和作为素祭。'),
('CUV', '民数记', 4, 28, 6, '这是西乃山所命定为常献的燔祭，是献给耶和华为馨香的火祭。'),
('CUV', '民数记', 4, 28, 7, '为这一只羊羔，要同献奠祭的酒一欣四分之一。在圣所中，你要将醇酒奉给耶和华为奠祭。'),
('CUV', '民数记', 4, 28, 8, '晚上，你要献那一只羊羔，必照早晨的素祭和同献的奠祭献上，作为馨香的火祭，献给耶和华。'),
('CUV', '民数记', 4, 28, 9, '当安息日，要献两只没有残疾、一岁的公羊羔，并用调油的细面伊法十分之二为素祭，又将同献的奠祭献上。'),
('CUV', '民数记', 4, 28, 10, '这是每安息日献的燔祭；那常献的燔祭和同献的奠祭在外。'),
('CUV', '民数记', 4, 28, 11, '每月朔，你们要将两只公牛犊，一只公绵羊，七只没有残疾、一岁的公羊羔，献给耶和华为燔祭。'),
('CUV', '民数记', 4, 28, 12, '每只公牛要用调油的细面伊法十分之三作为素祭；那只公羊也用调油的细面伊法十分之二作为素祭；'),
('CUV', '民数记', 4, 28, 13, '每只羊羔要用调油的细面伊法十分之一作为素祭和馨香的燔祭，是献给耶和华的火祭。'),
('CUV', '民数记', 4, 28, 14, '一只公牛要奠酒半欣，一只公羊要奠酒一欣三分之一，一只羊羔也奠酒一欣四分之一。这是每月的燔祭，一年之中要月月如此。'),
('CUV', '民数记', 4, 28, 15, '又要将一只公山羊为赎罪祭，献给耶和华；要献在常献的燔祭和同献的奠祭以外。'),
('CUV', '民数记', 4, 28, 16, '正月十四日是耶和华的逾越节。'),
('CUV', '民数记', 4, 28, 17, '这月十五日是节期，要吃无酵饼七日。'),
('CUV', '民数记', 4, 28, 18, '第一日当有圣会；甚么劳碌的工都不可做。'),
('CUV', '民数记', 4, 28, 19, '当将公牛犊两只，公绵羊一只，一岁的公羊羔七只，都要没有残疾的，用火献给耶和华为燔祭。'),
('CUV', '民数记', 4, 28, 20, '同献的素祭用调油的细面；为一只公牛要献伊法十分之三；为一只公羊要献伊法十分之二；'),
('CUV', '民数记', 4, 28, 21, '为那七只羊羔，每只要献伊法十分之一。'),
('CUV', '民数记', 4, 28, 22, '并献一只公山羊作赎罪祭，为你们赎罪。'),
('CUV', '民数记', 4, 28, 23, '你们献这些，要在早晨常献的燔祭以外。'),
('CUV', '民数记', 4, 28, 24, '一连七日，每日要照这例把馨香火祭的食物献给耶和华，是在常献的燔祭和同献的奠祭以外。'),
('CUV', '民数记', 4, 28, 25, '第七日当有圣会，甚么劳碌的工都不可做。'),
('CUV', '民数记', 4, 28, 26, '七七节庄稼初熟，你们献新素祭给耶和华的日子，当有圣会；甚么劳碌的工都不可做。'),
('CUV', '民数记', 4, 28, 27, '只要将公牛犊两只，公绵羊一只，一岁的公羊羔七只，作为馨香的燔祭献给耶和华。'),
('CUV', '民数记', 4, 28, 28, '同献的素祭用调油的细面；为每只公牛要献伊法十分之三；为一只公羊要献伊法十分之二；'),
('CUV', '民数记', 4, 28, 29, '为那七只羊羔，每只要献伊法十分之一。'),
('CUV', '民数记', 4, 28, 30, '并献一只公山羊为你们赎罪。'),
('CUV', '民数记', 4, 28, 31, '这些，你们要献在常献的燔祭和同献的素祭并同献的奠祭以外，都要没有残疾的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 29, 1, '七月初一日，你们当有圣会；甚么劳碌的工都不可做，是你们当守为吹角的日子。'),
('CUV', '民数记', 4, 29, 2, '你们要将公牛犊一只，公绵羊一只，没有残疾一岁的公羊羔七只，作为馨香的燔祭献给耶和华。'),
('CUV', '民数记', 4, 29, 3, '同献的素祭用调油的细面；为一只公牛要献伊法十分之三；为一只公羊要献伊法十分之二；'),
('CUV', '民数记', 4, 29, 4, '为那七只羊羔，每只要献伊法十分之一。'),
('CUV', '民数记', 4, 29, 5, '又献一只公山羊作赎罪祭，为你们赎罪。'),
('CUV', '民数记', 4, 29, 6, '这些是在月朔的燔祭和同献的素祭，并常献的燔祭与同献的素祭，以及照例同献的奠祭以外，都作为馨香的火祭献给耶和华。'),
('CUV', '民数记', 4, 29, 7, '七月初十日，你们当有圣会；要刻苦己心，甚么工都不可做。'),
('CUV', '民数记', 4, 29, 8, '只要将公牛犊一只，公绵羊一只，一岁的公羊羔七只，都要没有残疾的，作为馨香的燔祭献给耶和华。'),
('CUV', '民数记', 4, 29, 9, '同献的素祭用调油的细面：为一只公牛要献伊法十分之三；为一只公羊要献伊法十分之二；'),
('CUV', '民数记', 4, 29, 10, '为那七只羊羔，每只要献伊法十分之一。'),
('CUV', '民数记', 4, 29, 11, '又献一只公山羊为赎罪祭。这是在赎罪祭和常献的燔祭，与同献的素祭并同献的奠祭以外。'),
('CUV', '民数记', 4, 29, 12, '七月十五日，你们当有圣会；甚么劳碌的工都不可做，要向耶和华守节七日。'),
('CUV', '民数记', 4, 29, 13, '又要将公牛犊十三只，公绵羊两只，一岁的公羊羔十四只，都要没有残疾的，用火献给耶和华为馨香的燔祭。'),
('CUV', '民数记', 4, 29, 14, '同献的素祭用调油的细面；为那十三只公牛，每只要献伊法十分之三；为那两只公羊，每只要献伊法十分之二；'),
('CUV', '民数记', 4, 29, 15, '为那十四只羊羔，每只要献伊法十分之一。'),
('CUV', '民数记', 4, 29, 16, '并献一只公山羊为赎罪祭，这是在常献的燔祭和同献的素祭并同献的奠祭以外。'),
('CUV', '民数记', 4, 29, 17, '第二日要献公牛犊十二只，公绵羊两只，没有残疾、一岁的公羊羔十四只；'),
('CUV', '民数记', 4, 29, 18, '并为公牛、公羊，和羊羔，按数照例，献同献的素祭和同献的奠祭。'),
('CUV', '民数记', 4, 29, 19, '又要献一只公山羊为赎罪祭。这是在常献的燔祭和同献的素祭并同献的奠祭以外。'),
('CUV', '民数记', 4, 29, 20, '第三日要献公牛十一只，公羊两只，没有残疾、一岁的公羊羔十四只；'),
('CUV', '民数记', 4, 29, 21, '并为公牛、公羊，和羊羔，按数照例，献同献的素祭和同献的奠祭。'),
('CUV', '民数记', 4, 29, 22, '又要献一只公山羊为赎罪祭。这是在常献的燔祭和同献的素祭并同献的奠祭以外。'),
('CUV', '民数记', 4, 29, 23, '第四日要献公牛十只，公羊两只，没有残疾、一岁的公羊羔十四只；'),
('CUV', '民数记', 4, 29, 24, '并为公牛、公羊，和羊羔，按数照例，献同献的素祭和同献的奠祭。'),
('CUV', '民数记', 4, 29, 25, '又要献一只公山羊为赎罪祭。这是在常献的燔祭和同献的素祭并同献的奠祭以外。'),
('CUV', '民数记', 4, 29, 26, '第五日要献公牛九只，公羊两只，没有残疾、一岁的公羊羔十四只；'),
('CUV', '民数记', 4, 29, 27, '并为公牛、公羊，和羊羔，按数照例，献同献的素祭和同献的奠祭。'),
('CUV', '民数记', 4, 29, 28, '又要献一只公山羊为赎罪祭。这是在常献的燔祭和同献的素祭并同献的奠祭以外。'),
('CUV', '民数记', 4, 29, 29, '第六日要献公牛八只，公羊两只，没有残疾、一岁的公羊羔十四只；'),
('CUV', '民数记', 4, 29, 30, '并为公牛、公羊，和羊羔，按数照例，献同献的素祭和同献的奠祭。'),
('CUV', '民数记', 4, 29, 31, '又要献一只公山羊为赎罪祭。这是在常献的燔祭和同献的素祭并同献的奠祭以外。'),
('CUV', '民数记', 4, 29, 32, '第七日要献公牛七只，公羊两只，没有残疾、一岁的公羊羔十四只；'),
('CUV', '民数记', 4, 29, 33, '并为公牛、公羊，和羊羔，按数照例，献同献的素祭和同献的奠祭。'),
('CUV', '民数记', 4, 29, 34, '又要献一只公山羊为赎罪祭。这是在常献的燔祭和同献的素祭并同献的奠祭以外。'),
('CUV', '民数记', 4, 29, 35, '第八日你们当有严肃会；甚么劳碌的工都不可做；'),
('CUV', '民数记', 4, 29, 36, '只要将公牛一只，公羊一只，没有残疾、一岁的公羊羔七只作火祭，献给耶和华为馨香的燔祭；'),
('CUV', '民数记', 4, 29, 37, '并为公牛、公羊，和羊羔，按数照例，献同献的素祭和同献的奠祭。'),
('CUV', '民数记', 4, 29, 38, '又要献一只公山羊为赎罪祭。这是在常献的燔祭和同献的素祭并同献的奠祭以外。'),
('CUV', '民数记', 4, 29, 39, '这些祭要在你们的节期献给耶和华，都在所许的愿并甘心所献的以外，作为你们的燔祭、素祭、奠祭，和平安祭。'),
('CUV', '民数记', 4, 29, 40, '于是，摩西照耶和华所吩咐他的一切话告诉以色列人。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 30, 1, '摩西晓谕以色列各支派的首领说：耶和华所吩咐的乃是这样：'),
('CUV', '民数记', 4, 30, 2, '人若向耶和华许愿或起誓，要约束自己，就不可食言，必要按口中所出的一切话行。'),
('CUV', '民数记', 4, 30, 3, '女子年幼、还在父家的时候，若向耶和华许愿，要约束自己，'),
('CUV', '民数记', 4, 30, 4, '他父亲也听见他所许的愿并约束自己的话，却向他默默不言，他所许的愿并约束自己的话就都要为定.。'),
('CUV', '民数记', 4, 30, 5, '但他父亲听见的日子若不应承他所许的愿和约束自己的话，就都不得为定；耶和华也必赦免他，因为他父亲不应承。'),
('CUV', '民数记', 4, 30, 6, '他若出了嫁，有愿在身，或是口中出了约束自己的冒失话，'),
('CUV', '民数记', 4, 30, 7, '他丈夫听见的日子，却向他默默不言，他所许的愿并约束自己的话就都要为定。'),
('CUV', '民数记', 4, 30, 8, '但他丈夫听见的日子，若不应承，就算废了他所许的愿和他出口约束自己的冒失话；耶和华也必赦免他。'),
('CUV', '民数记', 4, 30, 9, '寡妇或是被休的妇人所许的愿，就是他约束自己的话，都要为定。'),
('CUV', '民数记', 4, 30, 10, '他若在丈夫家里许了愿或起了誓，约束自己，'),
('CUV', '民数记', 4, 30, 11, '丈夫听见，却向他默默不言，也没有不应承，他所许的愿并约束自己的话就都要为定。'),
('CUV', '民数记', 4, 30, 12, '丈夫听见的日子，若把这两样全废了，妇人口中所许的愿或是约束自己的话就都不得为定，因他丈夫已经把这两样废了；耶和华也必赦免他。'),
('CUV', '民数记', 4, 30, 13, '凡他所许的愿和刻苦约束自己所起的誓，他丈夫可以坚定，也可以废去。'),
('CUV', '民数记', 4, 30, 14, '倘若他丈夫天天向他默默不言，就算是坚定他所许的愿和约束自己的话；因丈夫听见的日子向他默默不言，就使这两样坚定。'),
('CUV', '民数记', 4, 30, 15, '但他丈夫听见以后，若使这两样全废了，就要担当妇人的罪孽。'),
('CUV', '民数记', 4, 30, 16, '这是丈夫待妻子，父亲待女儿，女儿年幼、还在父家，耶和华所吩咐摩西的律例。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 31, 1, '耶和华吩咐摩西说：'),
('CUV', '民数记', 4, 31, 2, '你要在米甸人身上报以色列人的仇，后来要归到你列祖（原文作本民）那里。'),
('CUV', '民数记', 4, 31, 3, '摩西吩咐百姓说：要从你们中间叫人带兵器出去攻击米甸，好在米甸人身上为耶和华报仇。'),
('CUV', '民数记', 4, 31, 4, '从以色列众支派中，每支派要打发一千人去打仗。'),
('CUV', '民数记', 4, 31, 5, '于是从以色列千万人中，每支派交出一千人，共一万二千人，带著兵器预备打仗。'),
('CUV', '民数记', 4, 31, 6, '摩西就打发每支派的一千人去打仗，并打发祭司以利亚撒的儿子非尼哈同去；非尼哈手里拿著圣所的器皿和吹大声的号筒。'),
('CUV', '民数记', 4, 31, 7, '他们就照耶和华所吩咐摩西的，与米甸人打仗，杀了所有的男丁。'),
('CUV', '民数记', 4, 31, 8, '在所杀的人中，杀了米甸的五王，就是以未、利金、苏珥、户珥、利巴，又用刀杀了比珥的儿子巴兰。'),
('CUV', '民数记', 4, 31, 9, '以色列人掳了米甸人的妇女孩子，并将他们的牲畜、羊群，和所有的财物都夺了来，当作掳物，'),
('CUV', '民数记', 4, 31, 10, '又用火焚烧他们所住的城邑和所有的营寨，'),
('CUV', '民数记', 4, 31, 11, '把一切所夺的、所掳的，连人带牲畜都带了去，'),
('CUV', '民数记', 4, 31, 12, '将所掳的人，所夺的牲畜、财物，都带到摩押平原，在约但河边与耶利哥相对的营盘，交给摩西和祭司以利亚撒，并以色列的会众。'),
('CUV', '民数记', 4, 31, 13, '摩西和祭司以利亚撒，并会众一切的首领，都出到营外迎接他们。'),
('CUV', '民数记', 4, 31, 14, '摩西向打仗回来的军长，就是千夫长、百夫长，发怒，'),
('CUV', '民数记', 4, 31, 15, '对他们说：你们要存留这一切妇女的活命么？'),
('CUV', '民数记', 4, 31, 16, '这些妇女因巴兰的计谋，叫以色列人在毘珥的事上得罪耶和华，以致耶和华的会众遭遇瘟疫。'),
('CUV', '民数记', 4, 31, 17, '所以，你们要把一切的男孩和所有已嫁的女子都杀了。'),
('CUV', '民数记', 4, 31, 18, '但女孩子中，凡没有出嫁的，你们都可以存留他的活命。'),
('CUV', '民数记', 4, 31, 19, '你们要在营外驻扎七日；凡杀了人的，和一切摸了被杀的，并你们所掳来的人口，第三日，第七日，都要洁净自己，'),
('CUV', '民数记', 4, 31, 20, '也要因一切的衣服、皮物、山羊毛织的物，和各样的木器，洁净自己。'),
('CUV', '民数记', 4, 31, 21, '祭司以利亚撒对打仗回来的兵丁说：耶和华所吩咐摩西律法中的条例乃是这样：'),
('CUV', '民数记', 4, 31, 22, '金、银、铜、铁、锡、铅，'),
('CUV', '民数记', 4, 31, 23, '凡能见火的，你们要叫他经火就为洁净，然而还要用除污秽的水洁净他；凡不能见火的，你们要叫他过水。'),
('CUV', '民数记', 4, 31, 24, '第七日，你们要洗衣服，就为洁净，然后可以进营。'),
('CUV', '民数记', 4, 31, 25, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 31, 26, '你和祭司以利亚撒，并会众的各族长，要计算所掳来的人口和牲畜的总数。'),
('CUV', '民数记', 4, 31, 27, '把所掳来的分作两半：一半归与出去打仗的精兵，一半归与全会众。'),
('CUV', '民数记', 4, 31, 28, '又要从出去打仗所得的人口、牛、驴、羊群中，每五百取一，作为贡物奉给耶和华。'),
('CUV', '民数记', 4, 31, 29, '从他们一半之中，要取出来交给祭司以利亚撒，作为耶和华的举祭。'),
('CUV', '民数记', 4, 31, 30, '从以色列人的一半之中，就是从人口、牛、驴、羊群、各样牲畜中，每五十取一，交给看守耶和华帐幕的利未人。'),
('CUV', '民数记', 4, 31, 31, '于是摩西和祭司以利亚撒照耶和华所吩咐摩西的行了。'),
('CUV', '民数记', 4, 31, 32, '除了兵丁所夺的财物以外，所掳来的：羊六十七万五千只；'),
('CUV', '民数记', 4, 31, 33, '牛七万二千只；'),
('CUV', '民数记', 4, 31, 34, '驴六万一千匹；'),
('CUV', '民数记', 4, 31, 35, '女人共三万二千口，都是没有出嫁的。'),
('CUV', '民数记', 4, 31, 36, '出去打仗之人的分，就是他们所得的那一半，共计羊三十三万七千五百只，'),
('CUV', '民数记', 4, 31, 37, '从其中归耶和华为贡物的，有六百七十五只；'),
('CUV', '民数记', 4, 31, 38, '牛三万六千只，从其中归耶和华为贡物的，有七十二只；'),
('CUV', '民数记', 4, 31, 39, '驴三万零五百匹，从其中归耶和华为贡物的，有六十一匹；'),
('CUV', '民数记', 4, 31, 40, '人一万六千口，从其中归耶和华的，有三十二口。'),
('CUV', '民数记', 4, 31, 41, '摩西把贡物，就是归与耶和华的举祭，交给祭司以利亚撒，是照耶和华所吩咐摩西的。'),
('CUV', '民数记', 4, 31, 42, '以色列人所得的那一半，就是摩西从打仗的人取来分给他们的。'),
('CUV', '民数记', 4, 31, 43, '（会众的那一半有：羊三十三万七千五百只；'),
('CUV', '民数记', 4, 31, 44, '牛三万六千只；'),
('CUV', '民数记', 4, 31, 45, '驴三万零五百匹；'),
('CUV', '民数记', 4, 31, 46, '人一万六千口。）'),
('CUV', '民数记', 4, 31, 47, '无论是人口是牲畜，摩西每五十取一，交给看守耶和华帐幕的利未人，是照耶和华所吩咐摩西的。'),
('CUV', '民数记', 4, 31, 48, '带领千军的各军长，就是千夫长、百夫长，都近前来见摩西，'),
('CUV', '民数记', 4, 31, 49, '对他说：仆人权下的兵已经计算总数，并不短少一人。'),
('CUV', '民数记', 4, 31, 50, '如今我们将各人所得的金器，就是脚链子、镯子、打印的戒指、耳环、手钏，都送来为耶和华的供物，好在耶和华面前为我们的生命赎罪。'),
('CUV', '民数记', 4, 31, 51, '摩西和祭司以利亚撒就收了他们的金子，都是打成的器皿。'),
('CUV', '民数记', 4, 31, 52, '千夫长、百夫长所献给耶和华为举祭的金子共有一万六千七百五十舍客勒。'),
('CUV', '民数记', 4, 31, 53, '各兵丁都为自己夺了财物。'),
('CUV', '民数记', 4, 31, 54, '摩西和祭司以利亚撒收了千夫长、百夫长的金子，就带进会幕，在耶和华面前作为以色列人的纪念。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 32, 1, '流便子孙和迦得子孙的牲畜极其众多；他们看见雅谢地和基列地是可牧放牲畜之地，'),
('CUV', '民数记', 4, 32, 2, '就来见摩西和祭司以利亚撒，并会众的首领，说：'),
('CUV', '民数记', 4, 32, 3, '亚大录、底本、雅谢、宁拉、希实本、以利亚利、示班、尼波、比稳，'),
('CUV', '民数记', 4, 32, 4, '就是耶和华在以色列会众前面所攻取之地，是可牧放牲畜之地，你仆人也有牲畜；'),
('CUV', '民数记', 4, 32, 5, '又说：我们若在你眼前蒙恩，求你把这地给我们为业，不要领我们过约但河。'),
('CUV', '民数记', 4, 32, 6, '摩西对迦得子孙和流便子孙说：难道你们的弟兄去打仗，你们竟坐在这里么？'),
('CUV', '民数记', 4, 32, 7, '你们为何使以色列人灰心丧胆、不过去进入耶和华所赐给他们的那地呢？'),
('CUV', '民数记', 4, 32, 8, '我先前从加低斯巴尼亚打发你们先祖去窥探那地，他们也是这样行。'),
('CUV', '民数记', 4, 32, 9, '他们上以实各谷，去窥探那地回来的时候，使以色列人灰心丧胆，不进入耶和华所赐给他们的地。'),
('CUV', '民数记', 4, 32, 10, '当日，耶和华的怒气发作，就起誓说：'),
('CUV', '民数记', 4, 32, 11, '凡从埃及上来、二十岁以外的人断不得看见我对亚伯拉罕、以撒、雅各起誓应许之地，因为他们没有专心跟从我。'),
('CUV', '民数记', 4, 32, 12, '惟有基尼洗族耶孚尼的儿子迦勒和嫩的儿子约书亚可以看见，因为他们专心跟从我。'),
('CUV', '民数记', 4, 32, 13, '耶和华的怒气向以色列人发作，使他们在旷野飘流四十年，等到在耶和华眼前行恶的那一代人都消灭了。'),
('CUV', '民数记', 4, 32, 14, '谁知，你们起来接续先祖，增添罪人的数目，使耶和华向以色列大发烈怒。'),
('CUV', '民数记', 4, 32, 15, '你们若退后不跟从他，他还要把以色列人撇在旷野，便是你们使这众民灭亡。'),
('CUV', '民数记', 4, 32, 16, '两支派的人挨近摩西，说：我们要在这里为牲畜垒圈，为妇人孩子造城。'),
('CUV', '民数记', 4, 32, 17, '我们自己要带兵器行在以色列人的前头，好把他们领到他们的地方；但我们的妇人孩子，因这地居民的缘故，要住在坚固的城内。'),
('CUV', '民数记', 4, 32, 18, '我们不回家，直等到以色列人各承受自己的产业。'),
('CUV', '民数记', 4, 32, 19, '我们不和他们在约但河那边一带之地同受产业，因为我们的产业是坐落在约但河东边这里。'),
('CUV', '民数记', 4, 32, 20, '摩西对他们说：你们若这样行，在耶和华面前带著兵器出去打仗，'),
('CUV', '民数记', 4, 32, 21, '所有带兵器的人都要在耶和华面前过约但河，等他赶出他的仇敌，'),
('CUV', '民数记', 4, 32, 22, '那地被耶和华制伏了，然后你们可以回来，向耶和华和以色列才为无罪，这地也必在耶和华面前归你们为业。'),
('CUV', '民数记', 4, 32, 23, '倘若你们不这样行，就得罪耶和华，要知道你们的罪必追上你们。'),
('CUV', '民数记', 4, 32, 24, '如今你们口中所出的，只管去行，为你们的妇人孩子造城，为你们的羊群垒圈。'),
('CUV', '民数记', 4, 32, 25, '迦得子孙和流便子孙对摩西说：仆人要照我主所吩咐的去行。'),
('CUV', '民数记', 4, 32, 26, '我们的妻子、孩子、羊群，和所有的牲畜都要留在基列的各城。'),
('CUV', '民数记', 4, 32, 27, '但你的仆人，凡带兵器的，都要照我主所说的话，在耶和华面前过去打仗。'),
('CUV', '民数记', 4, 32, 28, '于是，摩西为他们嘱咐祭司以利亚撒和嫩的儿子约书亚，并以色列众支派的族长，说：'),
('CUV', '民数记', 4, 32, 29, '迦得子孙和流便子孙，凡带兵器在耶和华面前去打仗的，若与你们一同过约但河，那地被你们制伏了，你们就要把基列地给他们为业。'),
('CUV', '民数记', 4, 32, 30, '倘若他们不带兵器和你们一同过去，就要在迦南地你们中间得产业。'),
('CUV', '民数记', 4, 32, 31, '迦得子孙和流便子孙回答说：耶和华怎样吩咐仆人，仆人就怎样行。'),
('CUV', '民数记', 4, 32, 32, '我们要带兵器，在耶和华面前过去，进入迦南地，只是约但河这边、我们所得为业之地仍归我们。'),
('CUV', '民数记', 4, 32, 33, '摩西将亚摩利王西宏的国和巴珊王噩的国，连那地和周围的城邑，都给了迦得子孙和流便子孙，并约瑟的儿子玛拿西半个支派。'),
('CUV', '民数记', 4, 32, 34, '迦得子孙建造底本、亚他录、亚罗珥、'),
('CUV', '民数记', 4, 32, 35, '亚他录朔反、雅谢、约比哈、'),
('CUV', '民数记', 4, 32, 36, '伯宁拉、伯哈兰，都是坚固城。他们又垒羊圈。'),
('CUV', '民数记', 4, 32, 37, '流便子孙建造希实本、以利亚利、基列亭、'),
('CUV', '民数记', 4, 32, 38, '尼波、巴力免、西比玛（尼波、巴力免，名字是改了的），又给他们所建造的城另起别名。'),
('CUV', '民数记', 4, 32, 39, '玛拿西的儿子玛吉，他的子孙往基列去，占了那地，赶出那里的亚摩利人。'),
('CUV', '民数记', 4, 32, 40, '摩西将基列赐给玛拿西的儿子玛吉，他子孙就住在那里。'),
('CUV', '民数记', 4, 32, 41, '玛拿西的子孙睚珥去占了基列的村庄，就称这些村庄为哈倭特睚珥。'),
('CUV', '民数记', 4, 32, 42, '挪巴去占了基纳和基纳的乡村，就按自己的名称基纳为挪巴。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 33, 1, '以色列人按著军队，在摩西、亚伦的手下出埃及地所行的路程（或作：站口；下同）记在下面。'),
('CUV', '民数记', 4, 33, 2, '摩西遵著耶和华的吩咐记载他们所行的路程，其路程乃是这样：'),
('CUV', '民数记', 4, 33, 3, '正月十五日，就是逾越节的次日，以色列人从兰塞起行，在一切埃及人眼前昂然无惧的出去。'),
('CUV', '民数记', 4, 33, 4, '那时，埃及人正葬埋他们的长子，就是耶和华在他们中间所击杀的；耶和华也败坏他们的神。'),
('CUV', '民数记', 4, 33, 5, '以色列人从兰塞起行，安营在疏割。'),
('CUV', '民数记', 4, 33, 6, '从疏割起行，安营在旷野边的以倘。'),
('CUV', '民数记', 4, 33, 7, '从以倘起行，转到比哈希录，是在巴力洗分对面，就在密夺安营。'),
('CUV', '民数记', 4, 33, 8, '从比哈希录对面起行，经过海中到了书珥旷野，又在伊坦的旷野走了三天的路程，就安营在玛拉。'),
('CUV', '民数记', 4, 33, 9, '从玛拉起行，来到以琳（以琳有十二股水泉，七十棵棕树），就在那里安营。'),
('CUV', '民数记', 4, 33, 10, '从以琳起行，安营在红海边。'),
('CUV', '民数记', 4, 33, 11, '从红海边起行，安营在汛的旷野。'),
('CUV', '民数记', 4, 33, 12, '从汛的旷野起行，安营在脱加。'),
('CUV', '民数记', 4, 33, 13, '从脱加起行，安营在亚录。'),
('CUV', '民数记', 4, 33, 14, '从亚录起行，安营在利非订；在那里，百姓没有水喝。'),
('CUV', '民数记', 4, 33, 15, '从利非订起行，安营在西乃的旷野。'),
('CUV', '民数记', 4, 33, 16, '从西乃的旷野起行，安营在基博罗哈他瓦。'),
('CUV', '民数记', 4, 33, 17, '从基博罗哈他瓦起行，安营在哈洗录。'),
('CUV', '民数记', 4, 33, 18, '从哈洗录起行，安营在利提玛。'),
('CUV', '民数记', 4, 33, 19, '从利提玛起行，安营在临门帕烈。'),
('CUV', '民数记', 4, 33, 20, '从临门帕烈起行，安营在立拿。'),
('CUV', '民数记', 4, 33, 21, '从立拿起行，安营在勒撒。'),
('CUV', '民数记', 4, 33, 22, '从勒撒起行，安营在基希拉他。'),
('CUV', '民数记', 4, 33, 23, '从基希拉他起行，安营在沙斐山。'),
('CUV', '民数记', 4, 33, 24, '从沙斐山起行，安营在哈拉大。'),
('CUV', '民数记', 4, 33, 25, '从哈拉大起行，安营在玛吉希录。'),
('CUV', '民数记', 4, 33, 26, '从玛吉希录起行，安营在他哈。'),
('CUV', '民数记', 4, 33, 27, '从他哈起行，安营在他拉。'),
('CUV', '民数记', 4, 33, 28, '从他拉起行，安营在密加。'),
('CUV', '民数记', 4, 33, 29, '从密加起行，安营在哈摩拿。'),
('CUV', '民数记', 4, 33, 30, '从哈摩拿起行，安营在摩西录。'),
('CUV', '民数记', 4, 33, 31, '从摩西录起行，安营在比尼亚干。'),
('CUV', '民数记', 4, 33, 32, '从比尼亚干起行，安营在曷哈及甲。'),
('CUV', '民数记', 4, 33, 33, '从曷哈及甲起行，安营在约巴他。'),
('CUV', '民数记', 4, 33, 34, '从约巴他起行，安营在阿博拿。'),
('CUV', '民数记', 4, 33, 35, '从阿博拿起行，安营在以旬迦别。'),
('CUV', '民数记', 4, 33, 36, '从以旬迦别起行，安营在寻的旷野，就是加低斯。'),
('CUV', '民数记', 4, 33, 37, '从加低斯起行，安营在何珥山，以东地的边界。'),
('CUV', '民数记', 4, 33, 38, '以色列人出了埃及地后四十年，五月初一日，祭司亚伦遵著耶和华的吩咐上何珥山，就死在那里。'),
('CUV', '民数记', 4, 33, 39, '亚伦死在何珥山的时候年一百二十三岁。'),
('CUV', '民数记', 4, 33, 40, '住在迦南南地的迦南人亚拉得王听说以色列人来了。'),
('CUV', '民数记', 4, 33, 41, '以色列人从何珥山起行，安营在撒摩拿。'),
('CUV', '民数记', 4, 33, 42, '从撒摩拿起行，安营在普嫩。'),
('CUV', '民数记', 4, 33, 43, '从普嫩起行，安营在阿伯。'),
('CUV', '民数记', 4, 33, 44, '从阿伯起行，安营在以耶亚巴琳，摩押的边界。'),
('CUV', '民数记', 4, 33, 45, '从以耶亚巴琳起行，安营在底本迦得。'),
('CUV', '民数记', 4, 33, 46, '从底本迦得起行，安营在亚门低比拉太音。'),
('CUV', '民数记', 4, 33, 47, '从亚门低比拉太音起行，安营在尼波对面的亚巴琳山里。'),
('CUV', '民数记', 4, 33, 48, '从亚巴琳山起行，安营在摩押平原─约但河边、耶利哥对面。'),
('CUV', '民数记', 4, 33, 49, '他们在摩押平原沿约但河边安营，从伯耶施末直到亚伯什亭。'),
('CUV', '民数记', 4, 33, 50, '耶和华在摩押平原─约但河边、耶利哥对面晓谕摩西说：'),
('CUV', '民数记', 4, 33, 51, '你吩咐以色列人说：你们过约但河进迦南地的时候，'),
('CUV', '民数记', 4, 33, 52, '就要从你们面前赶出那里所有的居民，毁灭他们一切錾成的石像和他们一切铸成的偶像，又拆毁他们一切的邱坛。'),
('CUV', '民数记', 4, 33, 53, '你们要夺那地，住在其中，因我把那地赐给你们为业。'),
('CUV', '民数记', 4, 33, 54, '你们要按家室拈阄，承受那地；人多的，要把产业多分给他们；人少的，要把产业少分给他们。拈出何地给何人，就要归何人。你们要按宗族的支派承受。'),
('CUV', '民数记', 4, 33, 55, '倘若你们不赶出那地的居民，所容留的居民就必作你们眼中的刺，肋下的荆棘，也必在你们所住的地上扰害你们。'),
('CUV', '民数记', 4, 33, 56, '而且我素常有意怎样待他们，也必照样待你们。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 34, 1, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 34, 2, '你吩咐以色列人说：你们到了迦南地，就是归你们为业的迦南四境之地，'),
('CUV', '民数记', 4, 34, 3, '南角要从寻的旷野，贴著以东的边界；南界要从盐海东头起，'),
('CUV', '民数记', 4, 34, 4, '绕到亚克拉滨坡的南边，接连到寻，直通到加低斯巴尼亚的南边，又通到哈萨亚达，接连到押们，'),
('CUV', '民数记', 4, 34, 5, '从押们转到埃及小河，直通到海为止。'),
('CUV', '民数记', 4, 34, 6, '西边要以大海为界；这就是你们的西界。'),
('CUV', '民数记', 4, 34, 7, '北界要从大海起，画到何珥山，'),
('CUV', '民数记', 4, 34, 8, '从何珥山划到哈马口，通到西达达，'),
('CUV', '民数记', 4, 34, 9, '又通到西斐仑，直到哈萨以难。这要作你们的北界。'),
('CUV', '民数记', 4, 34, 10, '你们要从哈萨以难划到示番为东界。'),
('CUV', '民数记', 4, 34, 11, '这界要从示番下到亚延东边的利比拉，又要达到基尼烈湖的东边。'),
('CUV', '民数记', 4, 34, 12, '这界要下到约但河，通到盐海为止。这四围的边界以内，要作你们的地。'),
('CUV', '民数记', 4, 34, 13, '摩西吩咐以色列人说：这地就是耶和华吩咐拈阄给九个半支派承受为业的；'),
('CUV', '民数记', 4, 34, 14, '因为流便支派和迦得支派按著宗族受了产业，玛拿西半个支派也受了产业。'),
('CUV', '民数记', 4, 34, 15, '这两个半支派已经在耶利哥对面、约但河东、向日出之地受了产业。'),
('CUV', '民数记', 4, 34, 16, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 34, 17, '要给你们分地为业之人的名字是祭司以利亚撒和嫩的儿子约书亚。'),
('CUV', '民数记', 4, 34, 18, '又要从每支派中选一个首领帮助他们。'),
('CUV', '民数记', 4, 34, 19, '这些人的名字：犹大支派有耶孚尼的儿子迦勒。'),
('CUV', '民数记', 4, 34, 20, '西缅支派有亚米忽的儿子示母利。'),
('CUV', '民数记', 4, 34, 21, '便雅悯支派有基斯伦的儿子以利达。'),
('CUV', '民数记', 4, 34, 22, '但支派有一个首领，约利的儿子布基。'),
('CUV', '民数记', 4, 34, 23, '约瑟的子孙玛拿西支派有一个首领，以弗的儿子汉聂。'),
('CUV', '民数记', 4, 34, 24, '以法莲支派有一个首领，拾弗但的儿子基母利。'),
('CUV', '民数记', 4, 34, 25, '西布伦支派有一个首领，帕纳的儿子以利撒番。'),
('CUV', '民数记', 4, 34, 26, '以萨迦支派有一个首领，阿散的儿子帕铁。'),
('CUV', '民数记', 4, 34, 27, '亚设支派有一个首领，示罗米的儿子亚希忽。'),
('CUV', '民数记', 4, 34, 28, '拿弗他利支派有一个首领，亚米忽的儿子比大黑。'),
('CUV', '民数记', 4, 34, 29, '这些人就是耶和华所吩咐、在迦南地把产业分给以色列人的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 35, 1, '耶和华在摩押平原─约但河边、耶利哥对面晓谕摩西说：'),
('CUV', '民数记', 4, 35, 2, '你吩咐以色列人，要从所得为业的地中把些城给利未人居住，也要把这城四围的郊野给利未人。'),
('CUV', '民数记', 4, 35, 3, '这城邑要归他们居住，城邑的郊野可以牧养他们的牛羊和各样的牲畜，又可以安置他们的财物。'),
('CUV', '民数记', 4, 35, 4, '你们给利未人的郊野，要从城根起，四围往外量一千肘。'),
('CUV', '民数记', 4, 35, 5, '另外东量二千肘，南量二千肘，西量二千肘，北量二千肘，为边界，城在当中；这要归他们作城邑的郊野。'),
('CUV', '民数记', 4, 35, 6, '你们给利未人的城邑，其中当有六座逃城，使误杀人的可以逃到那里。此外还要给他们四十二座城。'),
('CUV', '民数记', 4, 35, 7, '你们要给利未人的城，共有四十八座，连城带郊野都要给他们。'),
('CUV', '民数记', 4, 35, 8, '以色列人所得的地业从中要把些城邑给利未人；人多的就多给，人少的就少给；各支派要按所承受为业之地把城邑给利未人。'),
('CUV', '民数记', 4, 35, 9, '耶和华晓谕摩西说：'),
('CUV', '民数记', 4, 35, 10, '你吩咐以色列人说：你们过约但河，进了迦南地，'),
('CUV', '民数记', 4, 35, 11, '就要分出几座城，为你们作逃城，使误杀人的可以逃到那里。'),
('CUV', '民数记', 4, 35, 12, '这些城可以作逃避报仇人的城，使误杀人的不至于死，等他站在会众面前听审判。'),
('CUV', '民数记', 4, 35, 13, '你们所分出来的城，要作六座逃城。'),
('CUV', '民数记', 4, 35, 14, '在约但河东要分出三座城，在迦南地也要分出三座城，都作逃城。'),
('CUV', '民数记', 4, 35, 15, '这六座城要给以色列人和他们中间的外人，并寄居的，作为逃城，使误杀人的都可以逃到那里。'),
('CUV', '民数记', 4, 35, 16, '倘若人用铁器打人，以致打死，他就是故杀人的；故杀人的必被治死。'),
('CUV', '民数记', 4, 35, 17, '若用可以打死人的石头打死了人，他就是故杀人的；故杀人的必被治死。'),
('CUV', '民数记', 4, 35, 18, '若用可以打死人的木器打死了人，他就是故杀人的；故杀人的必被治死。'),
('CUV', '民数记', 4, 35, 19, '报血仇的必亲自杀那故杀人的，一遇见就杀他。'),
('CUV', '民数记', 4, 35, 20, '人若因怨恨把人推倒，或是埋伏往人身上扔物，以致于死，'),
('CUV', '民数记', 4, 35, 21, '或是因仇恨用手打人，以致于死，那打人的必被治死。他是故杀人的；报血仇的一遇见就杀他。'),
('CUV', '民数记', 4, 35, 22, '倘若人没有仇恨，忽然将人推倒，或是没有埋伏把物扔在人身上，'),
('CUV', '民数记', 4, 35, 23, '或是没有看见的时候用可以打死人的石头扔在人身上，以致于死，本来与他无仇，也无意害他。'),
('CUV', '民数记', 4, 35, 24, '会众就要照典章，在打死人的和报血仇的中间审判。'),
('CUV', '民数记', 4, 35, 25, '会众要救这误杀人的脱离报血仇人的手，也要使他归入逃城。他要住在其中，直等到受圣膏的大祭司死了。'),
('CUV', '民数记', 4, 35, 26, '但误杀人的，无论甚么时候，若出了逃城的境外，'),
('CUV', '民数记', 4, 35, 27, '报血仇的在逃城境外遇见他，将他杀了，报血仇的就没有流血之罪。'),
('CUV', '民数记', 4, 35, 28, '因为误杀人的该住在逃城里，等到大祭司死了。大祭司死了以后，误杀人的才可以回到他所得为业之地。'),
('CUV', '民数记', 4, 35, 29, '这在你们一切的住处，要作你们世世代代的律例典章。'),
('CUV', '民数记', 4, 35, 30, '无论谁故杀人，要凭几个见证人的口把那故杀人的杀了，只是不可凭一个见证的口叫人死。'),
('CUV', '民数记', 4, 35, 31, '故杀人、犯死罪的，你们不可收赎价代替他的命；他必被治死。'),
('CUV', '民数记', 4, 35, 32, '那逃到逃城的人，你们不可为他收赎价，使他在大祭司未死以先再来住在本地。'),
('CUV', '民数记', 4, 35, 33, '这样，你们就不污秽所住之地，因为血是污秽地的；若有在地上流人血的，非流那杀人者的血，那地就不得洁净（洁净原文作赎）。'),
('CUV', '民数记', 4, 35, 34, '你们不可玷污所住之地，就是我住在其中之地，因为我─耶和华住在以色列人中间。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '民数记', 4, 36, 1, '约瑟的后裔，玛拿西的孙子，玛吉的儿子基列，他子孙中的诸族长来到摩西和作首领的以色列人族长面前，说：'),
('CUV', '民数记', 4, 36, 2, '耶和华曾吩咐我主拈阄分地给以色列人为业，我主也受了耶和华的吩咐将我们兄弟西罗非哈的产业分给他的众女儿。'),
('CUV', '民数记', 4, 36, 3, '他们若嫁以色列别支派的人，就必将我们祖宗所遗留的产业加在他们丈夫支派的产业中。这样，我们拈阄所得的产业就要减少了。'),
('CUV', '民数记', 4, 36, 4, '到了以色列人的禧年，这女儿的产业就必加在他们丈夫支派的产业上。这样，我们祖宗支派的产业就减少了。'),
('CUV', '民数记', 4, 36, 5, '摩西照耶和华的话吩咐以色列人说：约瑟支派的人说得有理。'),
('CUV', '民数记', 4, 36, 6, '论到西罗非哈的众女儿，耶和华这样吩咐说：他们可以随意嫁人，只是要嫁同宗支派的人。'),
('CUV', '民数记', 4, 36, 7, '这样，以色列人的产业就不从这支派归到那支派，因为以色列人要各守各祖宗支派的产业。'),
('CUV', '民数记', 4, 36, 8, '凡在以色列支派中得了产业的女子必作同宗支派人的妻，好叫以色列人各自承受他祖宗的产业。'),
('CUV', '民数记', 4, 36, 9, '这样，他们的产业就不从这支派归到那支派，因为以色列支派的人要各守各的产业。'),
('CUV', '民数记', 4, 36, 10, '耶和华怎样吩咐摩西，西罗非哈的众女儿就怎样行。'),
('CUV', '民数记', 4, 36, 11, '西罗非哈的女儿玛拉、得撒、曷拉、密迦、挪阿都嫁了他们伯叔的儿子。'),
('CUV', '民数记', 4, 36, 12, '他们嫁入约瑟儿子、玛拿西子孙的族中；他们的产业仍留在同宗支派中。'),
('CUV', '民数记', 4, 36, 13, '这是耶和华在摩押平原─约但河边、耶利哥对面─藉著摩西所吩咐以色列人的命令典章。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 1, 1, '以下所记的是摩西在约但河东的旷野、疏弗对面的亚拉巴─就是巴兰、陀弗、拉班、哈洗录、底撒哈中间─向以色列众人所说的话。'),
('CUV', '申命记', 5, 1, 2, '从何烈山经过西珥山到加低斯巴尼亚有十一天的路程。）'),
('CUV', '申命记', 5, 1, 3, '出埃及第四十年十一月初一日，摩西照耶和华藉著他所吩咐以色列人的话都晓谕他们。'),
('CUV', '申命记', 5, 1, 4, '那时，他已经击杀了住希实本的亚摩利王西宏和住以得来、亚斯他录的巴珊王噩。'),
('CUV', '申命记', 5, 1, 5, '摩西在约但河东的摩押地讲律法说：'),
('CUV', '申命记', 5, 1, 6, '耶和华─我们的神在何烈山晓谕我们说：你们在这山上住的日子够了；'),
('CUV', '申命记', 5, 1, 7, '要起行转到亚摩利人的山地和靠近这山地的各处，就是亚拉巴、山地、高原、南地，沿海一带迦南人的地，并利巴嫩山又到伯拉大河。'),
('CUV', '申命记', 5, 1, 8, '如今我将这地摆在你们面前；你们要进去得这地，就是耶和华向你们列祖亚伯拉罕、以撒、雅各起誓应许赐给他们和他们后裔为业之地。'),
('CUV', '申命记', 5, 1, 9, '那时，我对你们说：管理你们的重任，我独自担当不起。'),
('CUV', '申命记', 5, 1, 10, '耶和华─你们的神使你们多起来。看哪，你们今日像天上的星那样多。'),
('CUV', '申命记', 5, 1, 11, '惟愿耶和华─你们列祖的神使你们比如今更多千倍，照他所应许你们的话赐福与你们。'),
('CUV', '申命记', 5, 1, 12, '但你们的麻烦，和管理你们的重任，并你们的争讼，我独自一人怎能担当得起呢？'),
('CUV', '申命记', 5, 1, 13, '你们要按著各支派选举有智慧、有见识、为众人所认识的，我立他们为你们的首领。'),
('CUV', '申命记', 5, 1, 14, '你们回答我说：照你所说的行了为妙。'),
('CUV', '申命记', 5, 1, 15, '我便将你们各支派的首领，有智慧、为众人所认识的，照你们的支派，立他们为官长、千夫长、百夫长、五十夫长、十夫长，管理你们。'),
('CUV', '申命记', 5, 1, 16, '当时，我嘱咐你们的审判官说：你们听讼，无论是弟兄彼此争讼，是与同居的外人争讼，都要按公义判断。'),
('CUV', '申命记', 5, 1, 17, '审判的时候，不可看人的外貌；听讼不可分贵贱，不可惧怕人，因为审判是属乎神的。若有难断的案件，可以呈到我这里，我就判断。'),
('CUV', '申命记', 5, 1, 18, '那时，我将你们所当行的事都吩咐你们了。'),
('CUV', '申命记', 5, 1, 19, '我们照著耶和华─我们神所吩咐的从何烈山起行，经过你们所看见那大而可怕的旷野，往亚摩利人的山地去，到了加低斯巴尼亚。'),
('CUV', '申命记', 5, 1, 20, '我对你们说：你们已经到了耶和华─我们神所赐给我们的亚摩利人之山地。'),
('CUV', '申命记', 5, 1, 21, '看哪，耶和华─你的神已将那地摆在你面前，你要照耶和华─你列祖的神所说的上去得那地为业；不要惧怕，也不要惊惶。'),
('CUV', '申命记', 5, 1, 22, '你们都就近我来说：我们要先打发人去，为我们窥探那地，将我们上去该走何道，必进何城，都回报我们。'),
('CUV', '申命记', 5, 1, 23, '这话我以为美，就从你们中间选了十二个人，每支派一人。'),
('CUV', '申命记', 5, 1, 24, '于是他们起身上山地去，到以实各谷，窥探那地。'),
('CUV', '申命记', 5, 1, 25, '他们手里拿著那地的果子下来，到我们那里，回报说：耶和华─我们的神所赐给我们的是美地。'),
('CUV', '申命记', 5, 1, 26, '你们却不肯上去，竟违背了耶和华─你们神的命令，'),
('CUV', '申命记', 5, 1, 27, '在帐棚内发怨言说：耶和华因为恨我们，所以将我们从埃及地领出来，要交在亚摩利人手中，除灭我们。'),
('CUV', '申命记', 5, 1, 28, '我们上那里去呢？我们的弟兄使我们的心消化，说那地的民比我们又大又高，城邑又广大又坚固，高得顶天，并且我们在那里看见亚衲族的人。'),
('CUV', '申命记', 5, 1, 29, '我就对你们说：不要惊恐，也不要怕他们。'),
('CUV', '申命记', 5, 1, 30, '在你们前面行的耶和华─你们的神必为你们争战，正如他在埃及和旷野，在你们眼前所行的一样。'),
('CUV', '申命记', 5, 1, 31, '你们在旷野所行的路上，也曾见耶和华─你们的神抚养你们，如同人抚养儿子一般，直等你们来到这地方。'),
('CUV', '申命记', 5, 1, 32, '你们在这事上却不信耶和华─你们的神。'),
('CUV', '申命记', 5, 1, 33, '他在路上，在你们前面行，为你们找安营的地方；夜间在火柱里，日间在云柱里，指示你们所当行的路。'),
('CUV', '申命记', 5, 1, 34, '耶和华听见你们这话，就发怒，起誓说：'),
('CUV', '申命记', 5, 1, 35, '这恶世代的人，连一个也不得见我起誓应许赐给你们列祖的美地；'),
('CUV', '申命记', 5, 1, 36, '惟有耶孚尼的儿子迦勒必得看见，并且我要将他所踏过的地{赐给他和他的子孙，因为他专心跟从我。'),
('CUV', '申命记', 5, 1, 37, '耶和华为你们的缘故也向我发怒，说：你必不得进入那地。'),
('CUV', '申命记', 5, 1, 38, '伺候你、嫩的儿子约书亚，他必得进入那地；你要勉励他，因为他要使以色列人承受那地为业。'),
('CUV', '申命记', 5, 1, 39, '并且你们的妇人孩子，就是你们所说、必被掳掠的，和今日不知善恶的儿女，必进入那地。我要将那地赐给他们，他们必得为业。'),
('CUV', '申命记', 5, 1, 40, '至于你们，要转回，从红海的路往旷野去。'),
('CUV', '申命记', 5, 1, 41, '那时，你们回答我说：我们得罪了耶和华，情愿照耶和华─我们神一切所吩咐的上去争战。于是你们各人带著兵器，争先上山地去了。'),
('CUV', '申命记', 5, 1, 42, '耶和华吩咐我说：你对他们说：不要上去，也不要争战；因我不在你们中间，恐怕你们被仇敌杀败了。'),
('CUV', '申命记', 5, 1, 43, '我就告诉了你们，你们却不听从，竟违背耶和华的命令，擅自上山地去了。'),
('CUV', '申命记', 5, 1, 44, '住那山地的亚摩利人就出来攻击你们，追赶你们，如蜂拥一般，在西珥杀退你们，直到何珥玛。'),
('CUV', '申命记', 5, 1, 45, '你们便回来，在耶和华面前哭号；耶和华却不听你们的声音，也不向你们侧耳。'),
('CUV', '申命记', 5, 1, 46, '于是你们在加低斯住了许多日子。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 2, 1, '此后，我们转回，从红海的路往旷野去，是照耶和华所吩咐我的。我们在西珥山绕行了许多日子。'),
('CUV', '申命记', 5, 2, 2, '耶和华对我说：'),
('CUV', '申命记', 5, 2, 3, '你们绕行这山的日子够了，要转向北去。'),
('CUV', '申命记', 5, 2, 4, '你吩咐百姓说：你们弟兄以扫的子孙住在西珥，你们要经过他们的境界。他们必惧怕你们，所以你们要分外谨慎。'),
('CUV', '申命记', 5, 2, 5, '不可与他们争战；他们的地，连脚掌可踏之处，我都不给你们，因我已将西珥山赐给以扫为业。'),
('CUV', '申命记', 5, 2, 6, '你们要用钱向他们买粮吃，也要用钱向他们买水喝。'),
('CUV', '申命记', 5, 2, 7, '因为耶和华─你的神在你手里所办的一切事上已赐福与你。你走这大旷野，他都知道了。这四十年，耶和华─你的神常与你同在，故此你一无所缺。'),
('CUV', '申命记', 5, 2, 8, '于是，我们离了我们弟兄以扫子孙所住的西珥，从亚拉巴的路，经过以拉他、以旬迦别，转向摩押旷野的路去。'),
('CUV', '申命记', 5, 2, 9, '耶和华吩咐我说：不可扰害摩押人，也不可与他们争战。他们的地，我不赐给你为业，因我已将亚珥赐给罗得的子孙为业。'),
('CUV', '申命记', 5, 2, 10, '（先前，有以米人住在那里，民数众多，身体高大，像亚衲人一样。'),
('CUV', '申命记', 5, 2, 11, '这以米人像亚衲人；也算为利乏音人；摩押人称他们为以米人。'),
('CUV', '申命记', 5, 2, 12, '先前，何利人也住在西珥，但以扫的子孙将他们除灭，得了他们的地，接著居住，就如以色列在耶和华赐给他为业之地所行的一样。）'),
('CUV', '申命记', 5, 2, 13, '现在，起来过撒烈溪！于是我们过了撒烈溪。'),
('CUV', '申命记', 5, 2, 14, '自从离开加低斯巴尼亚，到过了撒烈溪的时候，共有三十八年，等那世代的兵丁都从营中灭尽，正如耶和华向他们所起的誓。'),
('CUV', '申命记', 5, 2, 15, '耶和华的手也攻击他们，将他们从营中除灭，直到灭尽。'),
('CUV', '申命记', 5, 2, 16, '兵丁从民中都灭尽死亡以后，'),
('CUV', '申命记', 5, 2, 17, '耶和华吩咐我说：'),
('CUV', '申命记', 5, 2, 18, '你今天要从摩押的境界亚珥经过，'),
('CUV', '申命记', 5, 2, 19, '走近亚扪人之地，不可扰害他们，也不可与他们争战。亚扪人的地，我不赐给你们为业，因我已将那地赐给罗得的子孙为业。'),
('CUV', '申命记', 5, 2, 20, '（那地也算为利乏音人之地，先前利乏音人住在那里，亚扪人称他们为散送冥。'),
('CUV', '申命记', 5, 2, 21, '那民众多，身体高大，像亚衲人一样，但耶和华从亚扪人面前除灭他们，亚扪人就得了他们的地，接著居住。'),
('CUV', '申命记', 5, 2, 22, '正如耶和华从前为住西珥的以扫子孙将何利人从他们面前除灭、他们得了何利人的地、接著居住一样，直到今日。'),
('CUV', '申命记', 5, 2, 23, '从迦斐托出来的迦斐托人将先前住在乡村直到迦萨的亚卫人除灭，接著居住。）'),
('CUV', '申命记', 5, 2, 24, '你们起来前往，过亚嫩谷；我已将亚摩利人希实本王西宏和他的地交在你手中，你要与他争战，得他的地为业。'),
('CUV', '申命记', 5, 2, 25, '从今日起，我要使天下万民听见你的名声都惊恐惧怕，且因你发颤伤恸。'),
('CUV', '申命记', 5, 2, 26, '我从基底莫的旷野差遣使者去见希实本王西宏，用和睦的话说：'),
('CUV', '申命记', 5, 2, 27, '求你容我从你的地经过，只走大道，不偏左右。'),
('CUV', '申命记', 5, 2, 28, '你可以卖粮给我吃，也可以卖水给我喝，只要容我步行过去，'),
('CUV', '申命记', 5, 2, 29, '就如住西珥的以扫子孙和住亚珥的摩押人待我一样，等我过了约但河，好进入耶和华─我们神所赐给我们的地。'),
('CUV', '申命记', 5, 2, 30, '但希实本王西宏不容我们从他那里经过；因为耶和华─你的神使他心中刚硬，性情顽梗，为要将他交在你手中，像今日一样。'),
('CUV', '申命记', 5, 2, 31, '耶和华对我说：从此起首，我要将西宏和他的地交给你；你要得他的地为业。'),
('CUV', '申命记', 5, 2, 32, '那时，西宏和他的众民出来攻击我们，在雅杂与我们交战。'),
('CUV', '申命记', 5, 2, 33, '耶和华─我们的神将他交给我们，我们就把他和他的儿子，并他的众民，都击杀了。'),
('CUV', '申命记', 5, 2, 34, '我们夺了他的一切城邑，将有人烟的各城，连女人带孩子，尽都毁灭，没有留下一个。'),
('CUV', '申命记', 5, 2, 35, '惟有牲畜和所夺的各城，并其中的财物，都取为自己的掠物。'),
('CUV', '申命记', 5, 2, 36, '从亚嫩谷边的亚罗珥和谷中的城，直到基列，耶和华─我们的神都交给我们了，没有一座城高得使我们不能攻取的。'),
('CUV', '申命记', 5, 2, 37, '惟有亚扪人之地，凡靠近雅博河的地，并山地的城邑，与耶和华─我们神所禁止我们去的地方，都没有挨近。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 3, 1, '以后，我们转回，向巴珊去。巴珊王噩和他的众民都出来，在以得来与我们交战。'),
('CUV', '申命记', 5, 3, 2, '耶和华对我说：不要怕他！因我已将他和他的众民，并他的地，都交在你手中；你要待他像从前待住希实本的亚摩利王西宏一样。'),
('CUV', '申命记', 5, 3, 3, '于是耶和华─我们的神也将巴珊王噩和他的众民都交在我们手中；我们杀了他们，没有留下一个。'),
('CUV', '申命记', 5, 3, 4, '那时，我们夺了他所有的城，共有六十座，没有一座城不被我们所夺。这为亚珥歌伯的全境，就是巴珊地噩王的国。'),
('CUV', '申命记', 5, 3, 5, '这些城都有坚固的高墙，有门有闩。此外还有许多无城墙的乡村。'),
('CUV', '申命记', 5, 3, 6, '我们将这些都毁灭了，像从前待希实本王西宏一样，把有人烟的各城，连女人带孩子，尽都毁灭；'),
('CUV', '申命记', 5, 3, 7, '惟有一切牲畜和城中的财物都取为自己的掠物。'),
('CUV', '申命记', 5, 3, 8, '那时，我们从约但河东两个亚摩利王的手将亚嫩谷直到黑门山之地夺过来'),
('CUV', '申命记', 5, 3, 9, '（这黑门山，西顿人称为西连，亚摩利人称为示尼珥），'),
('CUV', '申命记', 5, 3, 10, '就是夺了平原的各城、基列全地、巴珊全地，直到撒迦和以得来，都是巴珊王噩国内的城邑。'),
('CUV', '申命记', 5, 3, 11, '（利乏音人所剩下的只有巴珊王噩。他的床是铁的，长九肘，宽四肘，都是以人肘为度。现今岂不是在亚扪人的拉巴么？）'),
('CUV', '申命记', 5, 3, 12, '那时，我们得了这地。从亚嫩谷边的亚罗珥起，我将基列山地的一半，并其中的城邑，都给了流便人和迦得人。'),
('CUV', '申命记', 5, 3, 13, '其余的基列地和巴珊全地，就是噩王的国，我给了玛拿西半支派。亚珥歌伯全地乃是巴珊全地；这叫做利乏音人之地。'),
('CUV', '申命记', 5, 3, 14, '玛拿西的子孙睚珥占了亚珥歌伯全境，直到基述人和玛迦人的交界，就按自己的名称这巴珊地为哈倭特睚珥，直到今日。'),
('CUV', '申命记', 5, 3, 15, '我又将基列给了玛吉。'),
('CUV', '申命记', 5, 3, 16, '从基列到亚嫩谷，以谷中为界，直到亚扪人交界的雅博河，我给了流便人和迦得人，'),
('CUV', '申命记', 5, 3, 17, '又将亚拉巴和靠近约但河之地，从基尼烈直到亚拉巴海，就是盐海，并毘斯迦山根东边之地，都给了他们。'),
('CUV', '申命记', 5, 3, 18, '那时，我吩咐你们说：耶和华─你们的神已将这地赐给你们为业；你们所有的勇士都要带著兵器，在你们的弟兄以色列人前面过去。'),
('CUV', '申命记', 5, 3, 19, '但你们的妻子、孩子、牲畜（我知道你们有许多的牲畜）可以住在我所赐给你们的各城里。'),
('CUV', '申命记', 5, 3, 20, '等到你们弟兄在约但河那边，也得耶和华─你们神所赐给他们的地，又使他们得享平安，与你们一样，你们才可以回到我所赐给你们为业之地。'),
('CUV', '申命记', 5, 3, 21, '那时我吩咐约书亚说：你亲眼看见了耶和华─你神向这二王所行的；耶和华也必向你所要去的各国照样行。'),
('CUV', '申命记', 5, 3, 22, '你不要怕他们，因那为你争战的是耶和华─你的神。'),
('CUV', '申命记', 5, 3, 23, '那时，我恳求耶和华说：'),
('CUV', '申命记', 5, 3, 24, '主耶和华阿，你已将你的大力大能显给仆人看。在天上，在地下，有甚么神能像你行事、像你有大能的作为呢？'),
('CUV', '申命记', 5, 3, 25, '求你容我过去，看约但河那边的美地，就是那佳美的山地和利巴嫩。'),
('CUV', '申命记', 5, 3, 26, '但耶和华因你们的缘故向我发怒，不应允我，对我说：罢了！你不要向我再题这事。'),
('CUV', '申命记', 5, 3, 27, '你且上毘斯迦山顶去，向东、西、南、北举目观望，因为你必不能过这约但河。'),
('CUV', '申命记', 5, 3, 28, '你却要嘱咐约书亚，勉励他，使他胆壮；因为他必在这百姓前面过去，使他们承受你所要观看之地。'),
('CUV', '申命记', 5, 3, 29, '于是我们住在伯毘珥对面的谷中。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 4, 1, '以色列人哪，现在我所教训你们的律例典章，你们要听从遵行，好叫你们存活，得以进入耶和华─你们列祖之神所赐给你们的地，承受为业。'),
('CUV', '申命记', 5, 4, 2, '所吩咐你们的话，你们不可加添，也不可删减，好叫你们遵守我所吩咐的，就是耶和华─你们神的命令。'),
('CUV', '申命记', 5, 4, 3, '耶和华因巴力毘珥的事所行的，你们亲眼看见了。凡随从巴力毘珥的人，耶和华─你们的神都从你们中间除灭了。'),
('CUV', '申命记', 5, 4, 4, '惟有你们专靠耶和华─你们神的人，今日全都存活。'),
('CUV', '申命记', 5, 4, 5, '我照著耶和华─我神所吩咐的将律例典章教训你们，使你们在所要进去得为业的地上遵行。'),
('CUV', '申命记', 5, 4, 6, '所以你们要谨守遵行；这就是你们在万民眼前的智慧、聪明。他们听见这一切律例，必说：这大国的人真是有智慧，有聪明！'),
('CUV', '申命记', 5, 4, 7, '那一大国的人有神与他们相近，像耶和华─我们的神、在我们求告他的时候与我们相近呢？'),
('CUV', '申命记', 5, 4, 8, '又那一大国有这样公义的律例典章、像我今日在你们面前所陈明的这一切律法呢？'),
('CUV', '申命记', 5, 4, 9, '你只要谨慎，殷勤保守你的心灵，免得忘记你亲眼所看见的事，又免得你一生这事离开你的心；总要传给你的子子孙孙。'),
('CUV', '申命记', 5, 4, 10, '你在何烈山站在耶和华─你神面前的那日，耶和华对我说：你为我招聚百姓，我要叫他们听见我的话，使他们存活在世的日子，可以学习敬畏我，又可以教训儿女这样行。'),
('CUV', '申命记', 5, 4, 11, '那时你们近前来，站在山下；山上有火焰冲天，并有昏黑、密云、幽暗。'),
('CUV', '申命记', 5, 4, 12, '耶和华从火焰中对你们说话，你们只听见声音，却没有看见形像。'),
('CUV', '申命记', 5, 4, 13, '他将所吩咐你们当守的约指示你们，就是十条诫，并将这诫写在两块石版上。'),
('CUV', '申命记', 5, 4, 14, '那时耶和华又吩咐我将律例典章教训你们，使你们在所要过去得为业的地上遵行。'),
('CUV', '申命记', 5, 4, 15, '所以，你们要分外谨慎；因为耶和华在何烈山、从火中对你们说话的那日，你们没有看见甚么形像。'),
('CUV', '申命记', 5, 4, 16, '惟恐你们败坏自己，雕刻偶像，仿佛甚么男像女像，'),
('CUV', '申命记', 5, 4, 17, '或地上走兽的像，或空中飞鸟的像，'),
('CUV', '申命记', 5, 4, 18, '或地上爬物的像，或地底下水中鱼的像。'),
('CUV', '申命记', 5, 4, 19, '又恐怕你向天举目观看，见耶和华─你的神为天下万民所摆列的日月星，就是天上的万象，自己便被勾引敬拜事奉他。'),
('CUV', '申命记', 5, 4, 20, '耶和华将你们从埃及领出来，脱离铁炉，要特作自己产业的子民，像今日一样。'),
('CUV', '申命记', 5, 4, 21, '耶和华又因你们的缘故向我发怒，起誓必不容我过约但河，也不容我进入耶和华─你神所赐你为业的那美地。'),
('CUV', '申命记', 5, 4, 22, '我只得死在这地，不能过约但河；但你们必过去得那美地。'),
('CUV', '申命记', 5, 4, 23, '你们要谨慎，免得忘记耶和华─你们神与你们所立的约，为自己雕刻偶像，就是耶和华─你神所禁止你做的偶像；'),
('CUV', '申命记', 5, 4, 24, '因为耶和华─你的神乃是烈火，是忌邪的神。'),
('CUV', '申命记', 5, 4, 25, '你们在那地住久了，生子生孙，就雕刻偶像，仿佛甚么形像，败坏自己，行耶和华─你神眼中看为恶的事，惹他发怒。'),
('CUV', '申命记', 5, 4, 26, '我今日呼天唤地向你们作见证，你们必在过约但河得为业的地上速速灭尽！你们不能在那地上长久，必尽行除灭。'),
('CUV', '申命记', 5, 4, 27, '耶和华必使你们分散在万民中；在他所领你们到的万国里，你们剩下的人数稀少。'),
('CUV', '申命记', 5, 4, 28, '在那里，你们必事奉人手所造的神，就是用木石造成、不能看、不能听、不能吃、不能闻的神。'),
('CUV', '申命记', 5, 4, 29, '但你们在那里必寻求耶和华─你的神。你尽心尽性寻求他的时候，就必寻见。'),
('CUV', '申命记', 5, 4, 30, '日后你遭遇一切患难的时候，你必归回耶和华─你的神，听从他的话。'),
('CUV', '申命记', 5, 4, 31, '耶和华─你神原是有怜悯的神；他总不撇下你，不灭绝你，也不忘记他起誓与你列祖所立的约。'),
('CUV', '申命记', 5, 4, 32, '你且考察在你以前的世代，自神造人在世以来，从天这边到天那边，曾有何民听见神在火中说话的声音，像你听见还能存活呢？'),
('CUV', '申命记', 5, 4, 33, '这样的大事何曾有、何曾听见呢？'),
('CUV', '申命记', 5, 4, 34, '神何曾从别的国中将一国的人民领出来，用试验、神迹、奇事、争战、大能的手，和伸出来的膀臂，并大可畏的事，像耶和华─你们的神在埃及，在你们眼前为你们所行的一切事呢？'),
('CUV', '申命记', 5, 4, 35, '这是显给你看，要使你知道，惟有耶和华─他是神，除他以外，再无别神。'),
('CUV', '申命记', 5, 4, 36, '他从天上使你听见他的声音，为要教训你，又在地上使你看见他的烈火，并且听见他从火中所说的话。'),
('CUV', '申命记', 5, 4, 37, '因他爱你的列祖，所以拣选他们的后裔，用大能亲自领你出了埃及，'),
('CUV', '申命记', 5, 4, 38, '要将比你强大的国民从你面前赶出，领你进去，将他们的地赐你为业，像今日一样。'),
('CUV', '申命记', 5, 4, 39, '所以，今日你要知道，也要记在心上，天上地下惟有耶和华他是神，除他以外，再无别神。'),
('CUV', '申命记', 5, 4, 40, '我今日将他的律例诫命晓谕你，你要遵守，使你和你的子孙可以得福，并使你的日子在耶和华─你神所赐的地上得以长久。'),
('CUV', '申命记', 5, 4, 41, '那时，摩西在约但河东，向日出之地，分定三座城，'),
('CUV', '申命记', 5, 4, 42, '使那素无仇恨、无心杀了人的，可以逃到这三城之中的一座城，就得存活：'),
('CUV', '申命记', 5, 4, 43, '为流便人分定旷野平原的比悉；为迦得人分定基列的拉末；为玛拿西人分定巴珊的哥兰。'),
('CUV', '申命记', 5, 4, 44, '摩西在以色列人面前所陈明的律法─'),
('CUV', '申命记', 5, 4, 45, '就是摩西在以色列人出埃及后所传给他们的法度、律例、典章；'),
('CUV', '申命记', 5, 4, 46, '在约但河东伯毘珥对面的谷中，在住希实本、亚摩利王西宏之地；这西宏是摩西和以色列人出埃及后所击杀的。'),
('CUV', '申命记', 5, 4, 47, '他们得了他的地，又得了巴珊王噩的地，就是两个亚摩利王，在约但河东向日出之地。'),
('CUV', '申命记', 5, 4, 48, '从亚嫩谷边的亚罗珥，直到西云山，就是黑门山。'),
('CUV', '申命记', 5, 4, 49, '还有约但河东的全亚拉巴，直到亚拉巴海，靠近毘斯迦山根。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 5, 1, '摩西将以色列众人召了来，对他们说：以色列人哪，我今日晓谕你们的律例典章，你们要听，可以学习，谨守遵行。'),
('CUV', '申命记', 5, 5, 2, '耶和华─我们的神在何烈山与我们立约。'),
('CUV', '申命记', 5, 5, 3, '这约不是与我们列祖立的，乃是与我们今日在这里存活之人立的。'),
('CUV', '申命记', 5, 5, 4, '耶和华在山上，从火中，面对面与你们说话─'),
('CUV', '申命记', 5, 5, 5, '那时我站在耶和华和你们中间，要将耶和华的话传给你们；因为你们惧怕那火，没有上山─说：'),
('CUV', '申命记', 5, 5, 6, '我是耶和华─你的神，曾将你从埃及地为奴之家领出来。'),
('CUV', '申命记', 5, 5, 7, '除了我以外，你不可有别的神。'),
('CUV', '申命记', 5, 5, 8, '不可为自己雕刻偶像，也不可做甚么形像，仿佛上天、下地和地底下、水中的百物。'),
('CUV', '申命记', 5, 5, 9, '不可跪拜那些像，也不可事奉他，因为我耶和华─你的神是忌邪的神。恨我的，我必追讨他的罪，自父及子，直到三、四代；'),
('CUV', '申命记', 5, 5, 10, '爱我、守我诫命的，我必向他们发慈爱，直到千代。'),
('CUV', '申命记', 5, 5, 11, '不可妄称耶和华─你神的名；因为妄称耶和华名的，耶和华必不以他为无罪。'),
('CUV', '申命记', 5, 5, 12, '当照耶和华─你神所吩咐的守安息日为圣日。'),
('CUV', '申命记', 5, 5, 13, '六日要劳碌做你一切的工，'),
('CUV', '申命记', 5, 5, 14, '但第七日是向耶和华─你神当守的安息日。这一日，你和你的儿女、仆婢、牛、驴、牲畜，并在你城里寄居的客旅，无论何工都不可做，使你的仆婢可以和你一样安息。'),
('CUV', '申命记', 5, 5, 15, '你也要记念你在埃及地作过奴仆；耶和华─你神用大能的手和伸出来的膀臂将你从那里领出来。因此，耶和华─你的神吩咐你守安息日。'),
('CUV', '申命记', 5, 5, 16, '当照耶和华─你神所吩咐的孝敬父母，使你得福，并使你的日子在耶和华─你神所赐你的地上得以长久。'),
('CUV', '申命记', 5, 5, 17, '不可杀人。'),
('CUV', '申命记', 5, 5, 18, '不可奸淫。'),
('CUV', '申命记', 5, 5, 19, '不可偷盗。'),
('CUV', '申命记', 5, 5, 20, '不可作假见证陷害人。'),
('CUV', '申命记', 5, 5, 21, '不可贪恋人的妻子；也不可贪图人的房屋、田地、仆婢、牛、驴，并他一切所有的。'),
('CUV', '申命记', 5, 5, 22, '这些话是耶和华在山上，从火中、云中、幽暗中，大声晓谕你们全会众的；此外并没有添别的话。他就把这话写在两块石版上，交给我了。'),
('CUV', '申命记', 5, 5, 23, '那时，火焰烧山，你们听见从黑暗中出来的声音；你们支派中所有的首领和长老都来就近我，'),
('CUV', '申命记', 5, 5, 24, '说：看哪，耶和华─我们神将他的荣光和他的大能显给我们看，我们又听见他的声音从火中出来。今日我们得见神与人说话，人还存活。'),
('CUV', '申命记', 5, 5, 25, '现在这大火将要烧灭我们，我们何必冒死呢？若再听见耶和华─我们神的声音就必死亡。'),
('CUV', '申命记', 5, 5, 26, '凡属血气的，曾有何人听见永生神的声音从火中出来，像我们听见还能存活呢？'),
('CUV', '申命记', 5, 5, 27, '求你近前去，听耶和华─我们神所要说的一切话，将他对你说的话都传给我们，我们就听从遵行。'),
('CUV', '申命记', 5, 5, 28, '你们对我说的话，耶和华都听见了。耶和华对我说：这百姓的话，我听见了；他们所说的都是。'),
('CUV', '申命记', 5, 5, 29, '惟愿他们存这样的心敬畏我，常遵守我的一切诫命，使他们和他们的子孙永远得福。'),
('CUV', '申命记', 5, 5, 30, '你去对他们说：你们回帐棚去罢！'),
('CUV', '申命记', 5, 5, 31, '至于你，可以站在我这里，我要将一切诫命、律例、典章传给你；你要教训他们，使他们在我赐他们为业的地上遵行。'),
('CUV', '申命记', 5, 5, 32, '所以，你们要照耶和华─你们神所吩咐的谨守遵行，不可偏离左右。'),
('CUV', '申命记', 5, 5, 33, '耶和华─你们神所吩咐你们行的，你们都要去行，使你们可以存活得福，并使你们的日子在所要承受的地上得以长久。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 6, 1, '这是耶和华─你们神所吩咐教训你们的诫命、律例、典章，使你们在所要过去得为业的地上遵行，'),
('CUV', '申命记', 5, 6, 2, '好叫你和你子子孙孙一生敬畏耶和华─你的神，谨守他的一切律例诫命，就是我所吩咐你的，使你的日子得以长久。'),
('CUV', '申命记', 5, 6, 3, '以色列阿，你要听，要谨守遵行，使你可以在那流奶与蜜之地得以享福，人数极其增多，正如耶和华─你列祖的神所应许你的。'),
('CUV', '申命记', 5, 6, 4, '以色列阿，你要听！耶和华─我们神是独一的主。'),
('CUV', '申命记', 5, 6, 5, '你要尽心、尽性、尽力爱耶和华─你的神。'),
('CUV', '申命记', 5, 6, 6, '我今日所吩咐你的话都要记在心上，'),
('CUV', '申命记', 5, 6, 7, '也要殷勤教训你的儿女。无论你坐在家里，行在路上，躺下，起来，都要谈论。'),
('CUV', '申命记', 5, 6, 8, '也要系在手上为记号，戴在额上为经文；'),
('CUV', '申命记', 5, 6, 9, '又要写在你房屋的门框上，并你的城门上。'),
('CUV', '申命记', 5, 6, 10, '耶和华─你的神领你进他向你列祖亚伯拉罕、以撒、雅各起誓应许给你的地。那里有城邑，又大又美，非你所建造的；'),
('CUV', '申命记', 5, 6, 11, '有房屋，装满各样美物，非你所装满的；有凿成的水井，非你所凿成的；还有葡萄园、橄榄园，非你所栽种的；你吃了而且饱足。'),
('CUV', '申命记', 5, 6, 12, '那时你要谨慎，免得你忘记将你从埃及地、为奴之家领出来的耶和华。'),
('CUV', '申命记', 5, 6, 13, '你要敬畏耶和华─你的神，事奉他，指著他的名起誓。'),
('CUV', '申命记', 5, 6, 14, '不可随从别神，就是你们四围国民的神；'),
('CUV', '申命记', 5, 6, 15, '因为在你们中间的耶和华─你神是忌邪的神，惟恐耶和华─你神的怒气向你发作，就把你从地上除灭。'),
('CUV', '申命记', 5, 6, 16, '你们不可试探耶和华─你们的神，像你们在玛撒那样试探他。'),
('CUV', '申命记', 5, 6, 17, '要留意遵守耶和华─你们神所吩咐的诫命、法度、律例。'),
('CUV', '申命记', 5, 6, 18, '耶和华眼中看为正、看为善的，你都要遵行，使你可以享福，并可以进去得耶和华向你列祖起誓应许的那美地，'),
('CUV', '申命记', 5, 6, 19, '照耶和华所说的，从你面前撵出你的一切仇敌。'),
('CUV', '申命记', 5, 6, 20, '日后，你的儿子问你说：耶和华─我们神吩咐你们的这些法度、律例、典章是甚么意思呢？'),
('CUV', '申命记', 5, 6, 21, '你就告诉你的儿子说：我们在埃及作过法老的奴仆；耶和华用大能的手将我们从埃及领出来，'),
('CUV', '申命记', 5, 6, 22, '在我们眼前，将重大可怕的神迹奇事施行在埃及地和法老并他全家的身上，'),
('CUV', '申命记', 5, 6, 23, '将我们从那里领出来，要领我们进入他向我们列祖起誓应许之地，把这地赐给我们。'),
('CUV', '申命记', 5, 6, 24, '耶和华又吩咐我们遵行这一切律例，要敬畏耶和华─我们的神，使我们常得好处，蒙他保全我们的生命，像今日一样。'),
('CUV', '申命记', 5, 6, 25, '我们若照耶和华─我们神所吩咐的一切诫命谨守遵行，这就是我们的义了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 7, 1, '耶和华─你神领你进入要得为业之地，从你面前赶出许多国民，就是赫人、革迦撒人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人，共七国的民，都比你强大。'),
('CUV', '申命记', 5, 7, 2, '耶和华─你神将他们交给你击杀，那时你要把他们灭绝净尽，不可与他们立约，也不可怜恤他们。'),
('CUV', '申命记', 5, 7, 3, '不可与他们结亲。不可将你的女儿嫁他们的儿子，也不可叫你的儿子娶他们的女儿；'),
('CUV', '申命记', 5, 7, 4, '因为他必使你儿子转离不跟从主，去事奉别神，以致耶和华的怒气向你们发作，就速速地将你们灭绝。'),
('CUV', '申命记', 5, 7, 5, '你们却要这样待他们：拆毁他们的祭坛，打碎他们的柱像，砍下他们的木偶，用火焚烧他们雕刻的偶像。'),
('CUV', '申命记', 5, 7, 6, '因为你归耶和华─你神为圣洁的民；耶和华─你神从地上的万民中拣选你，特作自己的子民。'),
('CUV', '申命记', 5, 7, 7, '耶和华专爱你们，拣选你们，并非因你们的人数多于别民，原来你们的人数在万民中是最少的。'),
('CUV', '申命记', 5, 7, 8, '只因耶和华爱你们，又因要守他向你们列祖所起的誓，就用大能的手领你们出来，从为奴之家救赎你们脱离埃及王法老的手。'),
('CUV', '申命记', 5, 7, 9, '所以，你要知道耶和华─你的神，他是神，是信实的神；向爱他、守他诫命的人守约，施慈爱，直到千代；'),
('CUV', '申命记', 5, 7, 10, '向恨他的人当面报应他们，将他们灭绝。凡恨他的人必报应他们，决不迟延。'),
('CUV', '申命记', 5, 7, 11, '所以，你要谨守遵行我今日所吩咐你的诫命、律例、典章。'),
('CUV', '申命记', 5, 7, 12, '你们果然听从这些典章，谨守遵行，耶和华─你神就必照他向你列祖所起的誓守约，施慈爱。'),
('CUV', '申命记', 5, 7, 13, '他必爱你，赐福与你，使你人数增多，也必在他向你列祖起誓应许给你的地上赐福与你身所生的，地所产的，并你的五谷、新酒，和油，以及牛犊、羊羔。'),
('CUV', '申命记', 5, 7, 14, '你必蒙福胜过万民；你们的男女没有不能生养的，牲畜也没有不能生育的。'),
('CUV', '申命记', 5, 7, 15, '耶和华必使一切的病症离开你；你所知道埃及各样的恶疾，他不加在你身上，只加在一切恨你的人身上。'),
('CUV', '申命记', 5, 7, 16, '耶和华─你神所要交给你的一切人民，你要将他们除灭；你眼不可顾惜他们。你也不可事奉他们的神，因这必成为你的网罗。'),
('CUV', '申命记', 5, 7, 17, '你若心里说，这些国的民比我更多，我怎能赶出他们呢？'),
('CUV', '申命记', 5, 7, 18, '你不要惧怕他们，要牢牢记念耶和华─你神向法老和埃及全地所行的事，'),
('CUV', '申命记', 5, 7, 19, '就是你亲眼所看见的大试验、神迹、奇事，和大能的手，并伸出来的膀臂，都是耶和华─你神领你出来所用的。耶和华─你神必照样待你所惧怕的一切人民。'),
('CUV', '申命记', 5, 7, 20, '并且耶和华─你神必打发黄蜂飞到他们中间，直到那剩下而藏躲的人从你面前灭亡。'),
('CUV', '申命记', 5, 7, 21, '你不要因他们惊恐，因为耶和华─你神在你们中间是大而可畏的神。'),
('CUV', '申命记', 5, 7, 22, '耶和华─你神必将这些国的民从你面前渐渐赶出；你不可把他们速速灭尽，恐怕野地的兽多起来害你。'),
('CUV', '申命记', 5, 7, 23, '耶和华─你神必将他们交给你，大大的扰乱他们，直到他们灭绝了；'),
('CUV', '申命记', 5, 7, 24, '又要将他们的君王交在你手中，你就使他们的名从天下消灭。必无一人能在你面前站立得住，直到你将他们灭绝了。'),
('CUV', '申命记', 5, 7, 25, '他们雕刻的神像，你们要用火焚烧；其上的金银，你不可贪图，也不可收取，免得你因此陷入网罗；这原是耶和华─你神所憎恶的。'),
('CUV', '申命记', 5, 7, 26, '可憎的物，你不可带进家去；不然，你就成了当毁灭的，与那物一样。你要十分厌恶，十分憎嫌，因为这是当毁灭的物。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 8, 1, '我今日所吩咐的一切诫命，你们要谨守遵行，好叫你们存活，人数增多，且进去得耶和华向你们列祖起誓应许的那地。'),
('CUV', '申命记', 5, 8, 2, '你也要记念耶和华─你的神在旷野引导你这四十年，是要苦炼你，试验你，要知道你心内如何，肯守他的诫命不肯。'),
('CUV', '申命记', 5, 8, 3, '他苦炼你，任你饥饿，将你和你列祖所不认识的吗哪赐给你吃，使你知道，人活著不是单靠食物，乃是靠耶和华口里所出的一切话。'),
('CUV', '申命记', 5, 8, 4, '这四十年，你的衣服没有穿破，你的脚也没有肿。'),
('CUV', '申命记', 5, 8, 5, '你当心里思想，耶和华─你神管教你，好像人管教儿子一样。'),
('CUV', '申命记', 5, 8, 6, '你要谨守耶和华─你神的诫命，遵行他的道，敬畏他。'),
('CUV', '申命记', 5, 8, 7, '因为耶和华─你神领你进入美地，那地有河，有泉，有源，从山谷中流出水来。'),
('CUV', '申命记', 5, 8, 8, '那地有小麦、大麦、葡萄树、无花果树、石榴树、橄榄树，和蜜。'),
('CUV', '申命记', 5, 8, 9, '你在那地不缺食物，一无所缺。那地的石头是铁，山内可以挖铜。'),
('CUV', '申命记', 5, 8, 10, '你吃得饱足，就要称颂耶和华─你的神，因他将那美地赐给你了。'),
('CUV', '申命记', 5, 8, 11, '你要谨慎，免得忘记耶和华─你的神，不守他的诫命、典章、律例，就是我今日所吩咐你的；'),
('CUV', '申命记', 5, 8, 12, '恐怕你吃得饱足，建造美好的房屋居住，'),
('CUV', '申命记', 5, 8, 13, '你的牛羊加多，你的金银增添，并你所有的全都加增，'),
('CUV', '申命记', 5, 8, 14, '你就心高气傲，忘记耶和华─你的神，就是将你从埃及地为奴之家领出来的，'),
('CUV', '申命记', 5, 8, 15, '引你经过那大而可怕的旷野，那里有火蛇、蝎子、干旱无水之地。他曾为你使水从坚硬的磐石中流出来，'),
('CUV', '申命记', 5, 8, 16, '又在旷野将你列祖所不认识的吗哪赐给你吃，是要苦炼你，试验你，叫你终久享福；'),
('CUV', '申命记', 5, 8, 17, '恐怕你心里说：这货财是我力量、我能力得来的。'),
('CUV', '申命记', 5, 8, 18, '你要记念耶和华─你的神，因为得货财的力量是他给你的，为要坚定他向你列祖起誓所立的约，像今日一样。'),
('CUV', '申命记', 5, 8, 19, '你若忘记耶和华─你的神，随从别神，事奉敬拜，你们必定灭亡；这是我今日警戒你们的。'),
('CUV', '申命记', 5, 8, 20, '耶和华在你们面前怎样使列国的民灭亡，你们也必照样灭亡，因为你们不听从耶和华─你们神的话。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 9, 1, '以色列阿，你当听！你今日要过约但河，进去赶出比你强大的国民，得著广大坚固、高得顶天的城邑。'),
('CUV', '申命记', 5, 9, 2, '那民是亚衲族的人，又大又高，是你所知道的；也曾听见有人指著他们说：谁能在亚衲族人面前站立得住呢？'),
('CUV', '申命记', 5, 9, 3, '你今日当知道，耶和华─你的神在你前面过去，如同烈火，要灭绝他们，将他们制伏在你面前。这样，你就要照耶和华所说的赶出他们，使他们速速灭亡。'),
('CUV', '申命记', 5, 9, 4, '耶和华─你的神将这些国民从你面前撵出以后，你心里不可说：耶和华将我领进来得这地是因我的义。其实，耶和华将他们从你面前赶出去是因他们的恶。'),
('CUV', '申命记', 5, 9, 5, '你进去得他们的地，并不是因你的义，也不是因你心里正直，乃是因这些国民的恶，耶和华─你的神将他们从你面前赶出去，又因耶和华要坚定他向你列祖亚伯拉罕、以撒、雅各起誓所应许的话。'),
('CUV', '申命记', 5, 9, 6, '你当知道，耶和华─你神将这美地赐你为业，并不是因你的义；你本是硬著颈项的百姓。'),
('CUV', '申命记', 5, 9, 7, '你当记念不忘，你在旷野怎样惹耶和华─你神发怒。自从你出了埃及地的那日，直到你们来到这地方，你们时常悖逆耶和华。'),
('CUV', '申命记', 5, 9, 8, '你们在何烈山又惹耶和华发怒；他恼怒你们，要灭绝你们。'),
('CUV', '申命记', 5, 9, 9, '我上了山，要领受两块石版，就是耶和华与你们立约的版。那时我在山上住了四十昼夜，没有吃饭，也没有喝水。'),
('CUV', '申命记', 5, 9, 10, '耶和华把那两块石版交给我，是神用指头写的。版上所写的是照耶和华在大会的日子、在山上、从火中对你们所说的一切话。'),
('CUV', '申命记', 5, 9, 11, '过了四十昼夜，耶和华把那两块石版，就是约版，交给我。'),
('CUV', '申命记', 5, 9, 12, '对我说：你起来，赶快下去！因为你从埃及领出来的百姓已经败坏了自己；他们快快的偏离了我所吩咐的道，为自己铸成了偶像。'),
('CUV', '申命记', 5, 9, 13, '耶和华又对我说：我看这百姓是硬著颈项的百姓。'),
('CUV', '申命记', 5, 9, 14, '你且由著我，我要灭绝他们，将他们的名从天下涂抹，使你的后裔比他们成为更大更强的国。'),
('CUV', '申命记', 5, 9, 15, '于是我转身下山，山被火烧著，两块约版在我两手之中。'),
('CUV', '申命记', 5, 9, 16, '我一看见你们得罪了耶和华─你们的神，铸成了牛犊，快快的偏离了耶和华所吩咐你们的道，'),
('CUV', '申命记', 5, 9, 17, '我就把那两块版从我手中扔下去，在你们眼前摔碎了。'),
('CUV', '申命记', 5, 9, 18, '因你们所犯的一切罪，行了耶和华眼中看为恶的事，惹他发怒，我就像从前俯伏在耶和华面前四十昼夜，没有吃饭，也没有喝水。'),
('CUV', '申命记', 5, 9, 19, '我因耶和华向你们大发烈怒，要灭绝你们，就甚害怕；但那次耶和华又应允了我。'),
('CUV', '申命记', 5, 9, 20, '耶和华也向亚伦甚是发怒，要灭绝他；那时我又为亚伦祈祷。'),
('CUV', '申命记', 5, 9, 21, '我把那叫你们犯罪所铸的牛犊用火焚烧，又捣碎磨得很细，以至细如灰尘，我就把这灰尘撒在从山上流下来的溪水中。'),
('CUV', '申命记', 5, 9, 22, '你们在他备拉、玛撒、基博罗哈他瓦又惹耶和华发怒。'),
('CUV', '申命记', 5, 9, 23, '耶和华打发你们离开加低斯巴尼亚，说：你们上去得我所赐给你们的地。那时你们违背了耶和华─你们神的命令，不信服他，不听从他的话。'),
('CUV', '申命记', 5, 9, 24, '自从我认识你们以来，你们常常悖逆耶和华。'),
('CUV', '申命记', 5, 9, 25, '我因耶和华说要灭绝你们，就在耶和华面前照旧俯伏四十昼夜。'),
('CUV', '申命记', 5, 9, 26, '我祈祷耶和华说：主耶和华阿，求你不要灭绝你的百姓。他们是你的产业，是你用大力救赎的，用大能从埃及领出来的。'),
('CUV', '申命记', 5, 9, 27, '求你记念你的仆人亚伯拉罕、以撒、雅各，不要想念这百姓的顽梗、邪恶、罪过，'),
('CUV', '申命记', 5, 9, 28, '免得你领我们出来的那地之人说，耶和华因为不能将这百姓领进他所应许之地，又因恨他们，所以领他们出去，要在旷野杀他们。'),
('CUV', '申命记', 5, 9, 29, '其实他们是你的百姓，你的产业，是你用大能和伸出来的膀臂领出来的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 10, 1, '那时，耶和华吩咐我说：你要凿出两块石版，和先前的一样，上山到我这里来，又要做一木柜。'),
('CUV', '申命记', 5, 10, 2, '你先前摔碎的那版，其上的字我要写在这版上；你要将这版放在柜中。'),
('CUV', '申命记', 5, 10, 3, '于是我用皂荚木做了一柜，又凿出两块石版，和先前的一样，手里拿这两块版上山去了。'),
('CUV', '申命记', 5, 10, 4, '耶和华将那大会之日、在山上从火中所传与你们的十条诫，照先前所写的，写在这版上，将版交给我了。'),
('CUV', '申命记', 5, 10, 5, '我转身下山，将这版放在我所做的柜中，现今还在那里，正如耶和华所吩咐我的。'),
('CUV', '申命记', 5, 10, 6, '（以色列人从比罗比尼亚干（或作：亚干井）起行，到了摩西拉。亚伦死在那里，就葬在那里。他儿子以利亚撒接续他供祭司的职分。'),
('CUV', '申命记', 5, 10, 7, '他们从那里起行，到了谷歌大，又从谷歌大到了有溪水之地的约巴他。'),
('CUV', '申命记', 5, 10, 8, '那时，耶和华将利未支派分别出来，抬耶和华的约柜，又侍立在耶和华面前事奉他，奉他的名祝福，直到今日。'),
('CUV', '申命记', 5, 10, 9, '所以利未人在他弟兄中无分无业，耶和华是他的产业，正如耶和华─你神所应许他的。）'),
('CUV', '申命记', 5, 10, 10, '我又像从前在山上住了四十昼夜。那次耶和华也应允我，不忍将你灭绝。'),
('CUV', '申命记', 5, 10, 11, '耶和华吩咐我说：你起来引导这百姓，使他们进去得我向他们列祖起誓应许所赐之地。'),
('CUV', '申命记', 5, 10, 12, '以色列阿，现在耶和华─你神向你所要的是甚么呢？只要你敬畏耶和华─你的神，遵行他的道，爱他，尽心尽性事奉他，'),
('CUV', '申命记', 5, 10, 13, '遵守他的诫命律例，就是我今日所吩咐你的，为要叫你得福。'),
('CUV', '申命记', 5, 10, 14, '看哪，天和天上的天，地和地上所有的，都属耶和华─你的神。'),
('CUV', '申命记', 5, 10, 15, '耶和华但喜悦你的列祖，爱他们，从万民中拣选他们的后裔，就是你们，像今日一样。'),
('CUV', '申命记', 5, 10, 16, '所以你们要将心里的污秽除掉，不可再硬著颈项。'),
('CUV', '申命记', 5, 10, 17, '因为耶和华─你们的神─他是万神之神，万主之主，至大的神，大有能力，大而可畏，不以貌取人，也不受贿赂。'),
('CUV', '申命记', 5, 10, 18, '他为孤儿寡妇伸冤，又怜爱寄居的，赐给他衣食。'),
('CUV', '申命记', 5, 10, 19, '所以你们要怜爱寄居的，因为你们在埃及地也作过寄居的。'),
('CUV', '申命记', 5, 10, 20, '你要敬畏耶和华─你的神，事奉他，专靠他，也要指著他的名起誓。'),
('CUV', '申命记', 5, 10, 21, '他是你所赞美的，是你的神，为你做了那大而可畏的事，是你亲眼所看见的。'),
('CUV', '申命记', 5, 10, 22, '你的列祖七十人下埃及；现在耶和华─你的神使你如同天上的星那样多。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 11, 1, '你要爱耶和华─你的神，常守他的吩咐、律例、典章、诫命。'),
('CUV', '申命记', 5, 11, 2, '你们今日当知道，我本不是和你们的儿女说话；因为他们不知道，也没有看见耶和华─你们神的管教、威严、大能的手，和伸出来的膀臂，'),
('CUV', '申命记', 5, 11, 3, '并他在埃及中向埃及王法老和其全地所行的神迹奇事；'),
('CUV', '申命记', 5, 11, 4, '也没有看见他怎样待埃及的军兵、车马，他们追赶你们的时候，耶和华怎样使红海的水淹没他们，将他们灭绝，直到今日，'),
('CUV', '申命记', 5, 11, 5, '并他在旷野怎样待你们，以至你们来到这地方；'),
('CUV', '申命记', 5, 11, 6, '也没有看见他怎样待流便子孙以利押的儿子大坍、亚比兰，地怎样在以色列人中间开口，吞了他们和他们的家眷，并帐棚与跟他们的一切活物。'),
('CUV', '申命记', 5, 11, 7, '惟有你们亲眼看见耶和华所做的一切大事。'),
('CUV', '申命记', 5, 11, 8, '所以，你们要守我今日所吩咐的一切诫命，使你们胆壮，能以进去，得你们所要得的那地，'),
('CUV', '申命记', 5, 11, 9, '并使你们的日子在耶和华向你们列祖起誓、应许给他们和他们后裔的地上得以长久；那是流奶与蜜之地。'),
('CUV', '申命记', 5, 11, 10, '你要进去得为业的那地，本不像你出来的埃及地。你在那里撒种，用脚浇灌，像浇灌菜园一样。'),
('CUV', '申命记', 5, 11, 11, '你们要过去得为业的那地乃是有山有谷、雨水滋润之地，'),
('CUV', '申命记', 5, 11, 12, '是耶和华─你神所眷顾的；从岁首到年终，耶和华─你神的眼目时常看顾那地。'),
('CUV', '申命记', 5, 11, 13, '你们若留意听从我今日所吩咐的诫命，爱耶和华─你们的神，尽心尽性事奉他，'),
('CUV', '申命记', 5, 11, 14, '他（原文是我）必按时降秋雨春雨在你们的地上，使你们可以收藏五谷、新酒和油，'),
('CUV', '申命记', 5, 11, 15, '也必使你吃得饱足，并使田野为你的牲畜长草。'),
('CUV', '申命记', 5, 11, 16, '你们要谨慎，免得心中受迷惑，就偏离正路，去事奉敬拜别神。'),
('CUV', '申命记', 5, 11, 17, '耶和华的怒气向你们发作，就使天闭塞不下雨，地也不出产，使你们在耶和华所赐给你们的美地上速速灭亡。'),
('CUV', '申命记', 5, 11, 18, '你们要将我这话存在心内，留在意中，系在手上为记号，戴在额上为经文；'),
('CUV', '申命记', 5, 11, 19, '也要教训你们的儿女，无论坐在家里，行在路上，躺下，起来，都要谈论；'),
('CUV', '申命记', 5, 11, 20, '又要写在房屋的门框上，并城门上，'),
('CUV', '申命记', 5, 11, 21, '使你们和你们子孙的日子在耶和华向你们列祖起誓、应许给他们的地上得以增多，如天覆地的日子那样多。'),
('CUV', '申命记', 5, 11, 22, '你们若留意谨守遵行我所吩咐这一切的诫命，爱耶和华─你们的神，行他的道，专靠他，'),
('CUV', '申命记', 5, 11, 23, '他必从你们面前赶出这一切国民，就是比你们更大更强的国民，你们也要得他们的地。'),
('CUV', '申命记', 5, 11, 24, '凡你们脚掌所踏之地都必归你们；从旷野和利巴嫩，并伯拉大河，直到西海，都要作你们的境界。'),
('CUV', '申命记', 5, 11, 25, '必无一人能在你们面前站立得住；耶和华─你们的神必照他所说的，使惧怕惊恐临到你们所踏之地的居民。'),
('CUV', '申命记', 5, 11, 26, '看哪，我今日将祝福与咒诅的话都陈明在你们面前。'),
('CUV', '申命记', 5, 11, 27, '你们若听从耶和华─你们神的诫命，就是我今日所吩咐你们的，就必蒙福。'),
('CUV', '申命记', 5, 11, 28, '你们若不听从耶和华─你们神的诫命，偏离我今日所吩咐你们的道，去事奉你们素来所不认识的别神，就必受祸。'),
('CUV', '申命记', 5, 11, 29, '及至耶和华─你的神领你进入要去得为业的那地，你就要将祝福的话陈明在基利心山上，将咒诅的话陈明在以巴路山上。'),
('CUV', '申命记', 5, 11, 30, '这二山岂不是在约但河那边，日落之处，在住亚拉巴的迦南人之地与吉甲相对，靠近摩利橡树么？'),
('CUV', '申命记', 5, 11, 31, '你们要过约但河，进去得耶和华─你们神所赐你们为业之地，在那地居住。'),
('CUV', '申命记', 5, 11, 32, '你们要谨守遵行我今日在你们面前所陈明的一切律例典章。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 12, 1, '你们存活于世的日子，在耶和华─你们列祖的神所赐你们为业的地上，要谨守遵行的律例典章乃是这些：'),
('CUV', '申命记', 5, 12, 2, '你们要将所赶出的国民事奉神的各地方，无论是在高山，在小山，在各青翠树下，都毁坏了；'),
('CUV', '申命记', 5, 12, 3, '也要拆毁他们的祭坛，打碎他们的柱像，用火焚烧他们的木偶，砍下他们雕刻的神像，并将其名从那地方除灭。'),
('CUV', '申命记', 5, 12, 4, '你们不可照他们那样事奉耶和华─你们的神。'),
('CUV', '申命记', 5, 12, 5, '但耶和华─你们的神从你们各支派中选择何处为立他名的居所，你们就当往那里去求问，'),
('CUV', '申命记', 5, 12, 6, '将你们的燔祭、平安祭、十分取一之物，和手中的举祭，并还愿祭、甘心祭，以及牛群羊群中头生的，都奉到那里。'),
('CUV', '申命记', 5, 12, 7, '在那里，耶和华─你们神的面前，你们和你们的家属都可以吃，并且因你手所办的一切事蒙耶和华─你的神赐福，就都欢乐。'),
('CUV', '申命记', 5, 12, 8, '我们今日在这里所行的是各人行自己眼中看为正的事，你们将来不可这样行；'),
('CUV', '申命记', 5, 12, 9, '因为你们还没有到耶和华─你神所赐你的安息地，所给你的产业。'),
('CUV', '申命记', 5, 12, 10, '但你们过了约但河，得以住在耶和华─你们神使你们承受为业之地，又使你们太平，不被四围的一切仇敌扰乱，安然居住。'),
('CUV', '申命记', 5, 12, 11, '那时要将我所吩咐你们的燔祭、平安祭、十分取一之物，和手中的举祭，并向耶和华许愿献的一切美祭，都奉到耶和华─你们神所选择要立为他名的居所。'),
('CUV', '申命记', 5, 12, 12, '你们和儿女、仆婢，并住在你们城里无分无业的利未人，都要在耶和华─你们的神面前欢乐。'),
('CUV', '申命记', 5, 12, 13, '你要谨慎，不可在你所看中的各处献燔祭。'),
('CUV', '申命记', 5, 12, 14, '惟独耶和华从你那一支派中所选择的地方，你就要在那里献燔祭，行我一切所吩咐你的。'),
('CUV', '申命记', 5, 12, 15, '然而，在你各城里都可以照耶和华─你神所赐你的福分，随心所欲宰牲吃肉；无论洁净人不洁净人都可以吃，就如吃羚羊与鹿一般。'),
('CUV', '申命记', 5, 12, 16, '只是不可吃血，要倒在地上，如同倒水一样。'),
('CUV', '申命记', 5, 12, 17, '你的五谷、新酒，和油的十分之一，或是牛群羊群中头生的，或是你许愿献的，甘心献的，或是手中的举祭，都不可在你城里吃。'),
('CUV', '申命记', 5, 12, 18, '但要在耶和华─你的神面前吃，在耶和华─你神所要选择的地方，你和儿女、仆婢，并住在你城里的利未人，都可以吃；也要因你手所办的，在耶和华─你神面前欢乐。'),
('CUV', '申命记', 5, 12, 19, '你要谨慎，在你所住的地方永不可丢弃利未人。'),
('CUV', '申命记', 5, 12, 20, '耶和华─你的神照他所应许扩张你境界的时候，你心里想要吃肉，说：我要吃肉，就可以随心所欲地吃肉。'),
('CUV', '申命记', 5, 12, 21, '耶和华─你神所选择要立他名的地方若离你太远，就可以照我所吩咐的，将耶和华赐给你的牛羊取些宰了，可以随心所欲在你城里吃。'),
('CUV', '申命记', 5, 12, 22, '你吃那肉，要像吃羚羊与鹿一般；无论洁净人不洁净人都可以吃。'),
('CUV', '申命记', 5, 12, 23, '只是你要心意坚定，不可吃血，因为血是生命；不可将血（原文作生命）与肉同吃。'),
('CUV', '申命记', 5, 12, 24, '不可吃血，要倒在地上，如同倒水一样。'),
('CUV', '申命记', 5, 12, 25, '不可吃血。这样，你行耶和华眼中看为正的事，你和你的子孙就可以得福。'),
('CUV', '申命记', 5, 12, 26, '只是你分别为圣的物和你的还愿祭要奉到耶和华所选择的地方去。'),
('CUV', '申命记', 5, 12, 27, '你的燔祭，连肉带血，都要献在耶和华─你神的坛上。平安祭的血要倒在耶和华─你神的坛上；平安祭的肉，你自己可以吃。'),
('CUV', '申命记', 5, 12, 28, '你要谨守听从我所吩咐的一切话，行耶和华─你神眼中看为善，看为正的事。这样，你和你的子孙就可以永远享福。'),
('CUV', '申命记', 5, 12, 29, '耶和华─你神将你要去赶出的国民从你面前剪除，你得了他们的地居住，'),
('CUV', '申命记', 5, 12, 30, '那时就要谨慎，不可在他们除灭之后随从他们的恶俗，陷入网罗，也不可访问他们的神说：这些国民怎样事奉他们的神，我也要照样行。'),
('CUV', '申命记', 5, 12, 31, '你不可向耶和华─你的神这样行，因为他们向他们的神行了耶和华所憎嫌所恨恶的一切事，甚至将自己的儿女用火焚烧，献与他们的神。'),
('CUV', '申命记', 5, 12, 32, '凡我所吩咐的，你们都要谨守遵行，不可加添，也不可删减。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 13, 1, '你们中间若有先知或是做梦的起来，向你显个神迹奇事，'),
('CUV', '申命记', 5, 13, 2, '对你说：我们去随从你素来所不认识的别神，事奉他罢。他所显的神迹奇事虽有应验，'),
('CUV', '申命记', 5, 13, 3, '你也不可听那先知或是那做梦之人的话；因为这是耶和华─你们的神试验你们，要知道你们是尽心尽性爱耶和华─你们的神不是。'),
('CUV', '申命记', 5, 13, 4, '你们要顺从耶和华─你们的神，敬畏他，谨守他的诫命，听从他的话，事奉他，专靠他。'),
('CUV', '申命记', 5, 13, 5, '那先知或是那做梦的既用言语叛逆那领你们出埃及地、救赎你脱离为奴之家的耶和华─你们的神，要勾引你离开耶和华─你神所吩咐你行的道，你便要将他治死。这样，就把那恶从你们中间除掉。'),
('CUV', '申命记', 5, 13, 6, '你的同胞弟兄，或是你的儿女，或是你怀中的妻，或是如同你性命的朋友，若暗中引诱你，说：我们不如去事奉你和你列祖素来所不认识的别神─'),
('CUV', '申命记', 5, 13, 7, '是你四围列国的神。无论是离你近，离你远，从地这边到地那边的神，'),
('CUV', '申命记', 5, 13, 8, '你不可依从他，也不可听从他，眼不可顾惜他。你不可怜恤他，也不可遮庇他，'),
('CUV', '申命记', 5, 13, 9, '总要杀他；你先下手，然后众民也下手，将他治死。'),
('CUV', '申命记', 5, 13, 10, '要用石头打死他，因为他想要勾引你离开那领你出埃及地为奴之家的耶和华─你的神。'),
('CUV', '申命记', 5, 13, 11, '以色列众人都要听见害怕，就不敢在你们中间再行这样的恶了。'),
('CUV', '申命记', 5, 13, 12, '在耶和华─你神所赐你居住的各城中，你若听人说，有些匪类从你们中间的一座城出来勾引本城的居民，说：我们不如去事奉你们素来所不认识的别神；'),
('CUV', '申命记', 5, 13, 13, 'a'),
('CUV', '申命记', 5, 13, 14, '你就要探听，查究，细细地访问，果然是真，准有这可憎恶的事行在你们中间，'),
('CUV', '申命记', 5, 13, 15, '你必要用刀杀那城里的居民，把城里所有的，连牲畜，都用刀杀尽。'),
('CUV', '申命记', 5, 13, 16, '你从那城里所夺的财物都要堆积在街市上，用火将城和其内所夺的财物都在耶和华─你神面前烧尽；那城就永为荒堆，不可再建造。'),
('CUV', '申命记', 5, 13, 17, '那当毁灭的物连一点都不可粘你的手。你要听从耶和华─你神的话，遵守我今日所吩咐你的一切诫命，行耶和华─你神眼中看为正的事，耶和华就必转意，不发烈怒，恩待你，怜恤你，照他向你列祖所起的誓使你人数增多。'),
('CUV', '申命记', 5, 13, 18, 'a')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 14, 1, '你们是耶和华─你们神的儿女。不可为死人用刀划身，也不可将额上剃光。'),
('CUV', '申命记', 5, 14, 2, '因为你归耶和华─你神为圣洁的民，耶和华从地上的万民中拣选你特作自己的子民。'),
('CUV', '申命记', 5, 14, 3, '凡可憎的物都不可吃。'),
('CUV', '申命记', 5, 14, 4, '可吃的牲畜就是牛、绵羊、山羊、'),
('CUV', '申命记', 5, 14, 5, '鹿、羚羊、麃子、野山羊、麋鹿、黄羊、青羊。'),
('CUV', '申命记', 5, 14, 6, '凡分蹄成为两瓣又倒嚼的走兽，你们都可以吃。'),
('CUV', '申命记', 5, 14, 7, '但那些倒嚼或是分蹄之中不可吃的乃是骆驼、兔子、沙番─因为是倒嚼不分蹄，就与你们不洁净；'),
('CUV', '申命记', 5, 14, 8, '猪─因为是分蹄却不倒嚼，就与你们不洁净。这些兽的肉，你们不可吃，死的也不可摸。'),
('CUV', '申命记', 5, 14, 9, '水中可吃的乃是这些：凡有翅有鳞的都可以吃；'),
('CUV', '申命记', 5, 14, 10, '凡无翅无鳞的都不可吃，是与你们不洁净。'),
('CUV', '申命记', 5, 14, 11, '凡洁净的鸟，你们都可以吃。'),
('CUV', '申命记', 5, 14, 12, '不可吃的乃是雕、狗头雕、红头雕、'),
('CUV', '申命记', 5, 14, 13, '鹯、小鹰、鹞鹰与其类，'),
('CUV', '申命记', 5, 14, 14, '乌鸦与其类，'),
('CUV', '申命记', 5, 14, 15, '鸵鸟、夜鹰、鱼鹰、鹰与其类，'),
('CUV', '申命记', 5, 14, 16, '鸮鸟、猫头鹰、角鸱、'),
('CUV', '申命记', 5, 14, 17, '鹈鹕、秃雕、鸬鹚、'),
('CUV', '申命记', 5, 14, 18, '鹳、鹭鸶与其类，戴鵀与蝙蝠。'),
('CUV', '申命记', 5, 14, 19, '凡有翅膀爬行的物是与你们不洁净，都不可吃。'),
('CUV', '申命记', 5, 14, 20, '凡洁净的鸟，你们都可以吃。'),
('CUV', '申命记', 5, 14, 21, '凡自死的，你们都不可吃，可以给你城里寄居的吃，或卖与外人吃，因为你是归耶和华─你神为圣洁的民。不可用山羊羔母的奶煮山羊羔。'),
('CUV', '申命记', 5, 14, 22, '你要把你撒种所产的，就是你田地每年所出的，十分取一分；'),
('CUV', '申命记', 5, 14, 23, '又要把你的五谷、新酒、和油的十分之一，并牛群羊群中头生的，吃在耶和华─你神面前，就是他所选择要立为他名的居所。这样，你可以学习时常敬畏耶和华─你的神。'),
('CUV', '申命记', 5, 14, 24, '当耶和华─你神赐福与你的时候，耶和华─你神所选择要立为他名的地方若离你太远，那路也太长，使你不能把这物带到那里去，'),
('CUV', '申命记', 5, 14, 25, '你就可以换成银子，将银子包起来，拿在手中，往耶和华─你神所要选择的地方去。'),
('CUV', '申命记', 5, 14, 26, '你用这银子，随心所欲，或买牛羊，或买清酒浓酒，凡你心所想的都可以买；你和你的家属在耶和华─你神的面前吃喝快乐。'),
('CUV', '申命记', 5, 14, 27, '住在你城里的利未人，你不可丢弃他，因为他在你们中间无分无业。'),
('CUV', '申命记', 5, 14, 28, '每逢三年的末一年，你要将本年的土产十分之一都取出来，积存在你的城中。'),
('CUV', '申命记', 5, 14, 29, '在你城里无分无业的利未人，和你城里寄居的，并孤儿寡妇，都可以来，吃得饱足。这样，耶和华─你的神必在你手里所办的一切事上赐福与你。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 15, 1, '每逢七年末一年，你要施行豁免。'),
('CUV', '申命记', 5, 15, 2, '豁免的定例乃是这样：凡债主要把所借给邻舍的豁免了；不可向邻舍和弟兄追讨，因为耶和华的豁免年已经宣告了。'),
('CUV', '申命记', 5, 15, 3, '若借给外邦人，你可以向他追讨；但借给你弟兄，无论是甚么，你要松手豁免了。'),
('CUV', '申命记', 5, 15, 4, '你若留意听从耶和华─你神的话，谨守遵行我今日所吩咐你这一切的命令，就必在你们中间没有穷人了（在耶和华─你神所赐你为业的地上，耶和华必大大赐福与你。）'),
('CUV', '申命记', 5, 15, 5, 'a'),
('CUV', '申命记', 5, 15, 6, '因为耶和华─你的神必照他所应许你的赐福与你。你必借给许多国民，却不至向他们借贷；你必管辖许多国民，他们却不能管辖你。'),
('CUV', '申命记', 5, 15, 7, '在耶和华─你神所赐你的地上，无论那一座城里，你弟兄中若有一个穷人，你不可忍著心、揝著手不帮补你穷乏的弟兄。'),
('CUV', '申命记', 5, 15, 8, '总要向他松开手，照他所缺乏的借给他，补他的不足。'),
('CUV', '申命记', 5, 15, 9, '你要谨慎，不可心里起恶念，说：第七年的豁免年快到了，你便恶眼看你穷乏的弟兄，甚么都不给他，以致他因你求告耶和华，罪便归于你了。'),
('CUV', '申命记', 5, 15, 10, '你总要给他，给他的时候心里不可愁烦；因耶和华─你的神必在你这一切所行的，并你手里所办的事上，赐福与你。'),
('CUV', '申命记', 5, 15, 11, '原来那地上的穷人永不断绝；所以我吩咐你说：总要向你地上困苦穷乏的弟兄松开手。'),
('CUV', '申命记', 5, 15, 12, '你弟兄中，若有一个希伯来男人或希伯来女人被卖给你，服事你六年，到第七年就要任他自由出去。'),
('CUV', '申命记', 5, 15, 13, '你任他自由的时候，不可使他空手而去，'),
('CUV', '申命记', 5, 15, 14, '要从你羊群、禾场、酒醡之中多多的给他；耶和华─你的神怎样赐福与你，你也要照样给他。'),
('CUV', '申命记', 5, 15, 15, '要记念你在埃及地作过奴仆，耶和华─你的神将你救赎；因此，我今日吩咐你这件事。'),
('CUV', '申命记', 5, 15, 16, '他若对你说：我不愿意离开你，是因他爱你和你的家，且因在你那里很好，'),
('CUV', '申命记', 5, 15, 17, '你就要拿锥子将他的耳朵在门上刺透，他便永为你的奴仆了。你待婢女也要这样。'),
('CUV', '申命记', 5, 15, 18, '你任他自由的时候，不可以为难事，因他服事你六年，较比雇工的工价多加一倍了。耶和华─你的神就必在你所做的一切事上赐福与你。'),
('CUV', '申命记', 5, 15, 19, '你牛群羊群中头生的，凡是公的，都要分别为圣，归耶和华─你的神。牛群中头生的，不可用他耕地；羊群中头生的，不可剪毛。'),
('CUV', '申命记', 5, 15, 20, '这头生的，你和你的家属，每年要在耶和华所选择的地方，在耶和华─你神面前吃。'),
('CUV', '申命记', 5, 15, 21, '这头生的若有甚么残疾，就如瘸腿的、瞎眼的，无论有甚么恶残疾，都不可献给耶和华─你的神；'),
('CUV', '申命记', 5, 15, 22, '可以在你城里吃；洁净人与不洁净人都可以吃，就如吃羚羊与鹿一般。'),
('CUV', '申命记', 5, 15, 23, '只是不可吃他的血；要倒在地上，如同倒水一样。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 16, 1, '你要注意亚笔月，向耶和华─你的神守逾越节，因为耶和华─你的神在亚笔月夜间领你出埃及。'),
('CUV', '申命记', 5, 16, 2, '你当在耶和华所选择要立为他名的居所，从牛群羊群中，将逾越节的祭牲献给耶和华─你的神。'),
('CUV', '申命记', 5, 16, 3, '你吃这祭牲，不可吃有酵的饼；七日之内要吃无酵饼，就是困苦饼─你本是急忙出了埃及地─要叫你一生一世记念你从埃及地出来的日子。'),
('CUV', '申命记', 5, 16, 4, '在你四境之内，七日不可见面酵，头一日晚上所献的肉，一点不可留到早晨。'),
('CUV', '申命记', 5, 16, 5, '在耶和华─你神所赐的各城中，你不可献逾越节的祭；'),
('CUV', '申命记', 5, 16, 6, '只当在耶和华─你神所选择要立为他名的居所，晚上日落的时候，乃是你出埃及的时候，献逾越节的祭。'),
('CUV', '申命记', 5, 16, 7, '当在耶和华─你神所选择的地方把肉烤了吃（烤：或作煮），次日早晨就回到你的帐棚去。'),
('CUV', '申命记', 5, 16, 8, '你要吃无酵饼六日，第七日要向耶和华─你的神守严肃会，不可做工。'),
('CUV', '申命记', 5, 16, 9, '你要计算七七日：从你开镰收割禾稼时算起，共计七七日。'),
('CUV', '申命记', 5, 16, 10, '你要照耶和华─你神所赐你的福，手里拿著甘心祭，献在耶和华─你的神面前，守七七节。'),
('CUV', '申命记', 5, 16, 11, '你和你儿女、仆婢，并住在你城里的利未人，以及在你们中间寄居的与孤儿寡妇，都要在耶和华─你神所选择立为他名的居所，在耶和华─你的神面前欢乐。'),
('CUV', '申命记', 5, 16, 12, '你也要记念你在埃及作过奴仆。你要谨守遵行这些律例。'),
('CUV', '申命记', 5, 16, 13, '你把禾场的谷、酒醡的酒收藏以后，就要守住棚节七日。'),
('CUV', '申命记', 5, 16, 14, '守节的时候，你和你儿女、仆婢，并住在你城里的利未人，以及寄居的与孤儿寡妇，都要欢乐。'),
('CUV', '申命记', 5, 16, 15, '在耶和华所选择的地方，你当向耶和华─你的神守节七日；因为耶和华─你神在你一切的土产上和你手里所办的事上要赐福与你，你就非常的欢乐。'),
('CUV', '申命记', 5, 16, 16, '你一切的男丁要在除酵节、七七节、住棚节，一年三次，在耶和华─你神所选择的地方朝见他，却不可空手朝见。'),
('CUV', '申命记', 5, 16, 17, '各人要按自己的力量，照耶和华─你神所赐的福分，奉献礼物。'),
('CUV', '申命记', 5, 16, 18, '你要在耶和华─你神所赐的各城里，按著各支派设立审判官和官长。他们必按公义的审判判断百姓。'),
('CUV', '申命记', 5, 16, 19, '不可屈枉正直；不可看人的外貌。也不可受贿赂；因为贿赂能叫智慧人的眼变瞎了，又能颠倒义人的话。'),
('CUV', '申命记', 5, 16, 20, '你要追求至公至义，好叫你存活，承受耶和华─你神所赐你的地。'),
('CUV', '申命记', 5, 16, 21, '你为耶和华─你的神筑坛，不可在坛旁栽甚么树木作为木偶。'),
('CUV', '申命记', 5, 16, 22, '也不可为自己设立柱像；这是耶和华─你神所恨恶的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 17, 1, '凡有残疾，或有甚么恶病的牛羊，你都不可献给耶和华─你的神，因为这是耶和华─你神所憎恶的。'),
('CUV', '申命记', 5, 17, 2, '在你们中间，在耶和华─你神所赐你的诸城中，无论那座城里，若有人，或男或女，行耶和华─你神眼中看为恶的事，违背了他的约，'),
('CUV', '申命记', 5, 17, 3, '去事奉敬拜别神，或拜日头，或拜月亮，或拜天象，是主不曾吩咐的；'),
('CUV', '申命记', 5, 17, 4, '有人告诉你，你也听见了，就要细细的探听，果然是真，准有这可憎恶的事行在以色列中，'),
('CUV', '申命记', 5, 17, 5, '你就要将行这恶事的男人或女人拉到城门外，用石头将他打死。'),
('CUV', '申命记', 5, 17, 6, '要凭两三个人的口作见证将那当死的人治死；不可凭一个人的口作见证将他治死。'),
('CUV', '申命记', 5, 17, 7, '见证人要先下手，然后众民也下手将他治死。这样，就把那恶从你们中间除掉。'),
('CUV', '申命记', 5, 17, 8, '你城中若起了争讼的事，或因流血，或因争竞，或因殴打，是你难断的案件，你就当起来，往耶和华─你神所选择的地方'),
('CUV', '申命记', 5, 17, 9, '去见祭司利未人，并当时的审判官，求问他们，他们必将判语指示你。'),
('CUV', '申命记', 5, 17, 10, '他们在耶和华所选择的地方指示你的判语，你必照著他们所指教你的一切话谨守遵行。'),
('CUV', '申命记', 5, 17, 11, '要按他们所指教你的律法，照他们所断定的去行；他们所指示你的判语，你不可偏离左右。'),
('CUV', '申命记', 5, 17, 12, '若有人擅敢不听从那侍立在耶和华─你神面前的祭司，或不听从审判官，那人就必治死；这样，便将那恶从以色列中除掉。'),
('CUV', '申命记', 5, 17, 13, '众百姓都要听见害怕，不再擅敢行事。'),
('CUV', '申命记', 5, 17, 14, '到了耶和华─你神所赐你的地，得了那地居住的时候，若说：我要立王治理我，像四围的国一样。'),
('CUV', '申命记', 5, 17, 15, '你总要立耶和华─你神所拣选的人为王。必从你弟兄中立一人；不可立你弟兄以外的人为王。'),
('CUV', '申命记', 5, 17, 16, '只是王不可为自己加添马匹，也不可使百姓回埃及去，为要加添他的马匹，因耶和华曾吩咐你们说：不可再回那条路去。'),
('CUV', '申命记', 5, 17, 17, '他也不可为自己多立妃嫔，恐怕他的心偏邪；也不可为自己多积金银。'),
('CUV', '申命记', 5, 17, 18, '他登了国位，就要将祭司利未人面前的这律法书，为自己抄录一本，'),
('CUV', '申命记', 5, 17, 19, '存在他那里，要平生诵读，好学习敬畏耶和华─他的神，谨守遵行这律法书上的一切言语和这些律例，'),
('CUV', '申命记', 5, 17, 20, '免得他向弟兄心高气傲，偏左偏右，离了这诫命。这样，他和他的子孙便可在以色列中，在国位上年长日久。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 18, 1, '祭司利未人和利未全支派必在以色列中无分无业；他们所吃用的就是献给耶和华的火祭和一切所捐的。'),
('CUV', '申命记', 5, 18, 2, '他们在弟兄中必没有产业；耶和华是他们的产业，正如耶和华所应许他们的。'),
('CUV', '申命记', 5, 18, 3, '祭司从百姓所当得的分乃是这样：凡献牛或羊为祭的，要把前腿和两腮并脾胃给祭司。'),
('CUV', '申命记', 5, 18, 4, '初收的五谷、新酒和油，并初剪的羊毛，也要给他；'),
('CUV', '申命记', 5, 18, 5, '因为耶和华─你的神从你各支派中将他拣选出来，使他和他子孙永远奉耶和华的名侍立，事奉。'),
('CUV', '申命记', 5, 18, 6, '利未人无论寄居在以色列中的那一座城，若从那里出来，一心愿意到耶和华所选择的地方，'),
('CUV', '申命记', 5, 18, 7, '就要奉耶和华─他神的名事奉，像他众弟兄利未人侍立在耶和华面前事奉一样。'),
('CUV', '申命记', 5, 18, 8, '除了他卖祖父产业所得的以外，还要得一分祭物与他们同吃。'),
('CUV', '申命记', 5, 18, 9, '你到了耶和华─你神所赐之地，那些国民所行可憎恶的事，你不可学著行。'),
('CUV', '申命记', 5, 18, 10, '你们中间不可有人使儿女经火，也不可有占卜的、观兆的、用法术的、行邪术的、'),
('CUV', '申命记', 5, 18, 11, '用迷术的、交鬼的、行巫术的、过阴的。'),
('CUV', '申命记', 5, 18, 12, '凡行这些事的都为耶和华所憎恶；因那些国民行这可憎恶的事，所以耶和华─你的神将他们从你面前赶出。'),
('CUV', '申命记', 5, 18, 13, '你要在耶和华─你的神面前作完全人。'),
('CUV', '申命记', 5, 18, 14, '因你所要赶出的那些国民都听信观兆的和占卜的，至于你，耶和华─你的神从来不许你这样行。'),
('CUV', '申命记', 5, 18, 15, '耶和华─你的神要从你们弟兄中间给你兴起一位先知，像我，你们要听从他。'),
('CUV', '申命记', 5, 18, 16, '正如你在何烈山大会的日子求耶和华─你神一切的话，说：求你不再叫我听见耶和华─我神的声音，也不再叫我看见这大火，免得我死亡。'),
('CUV', '申命记', 5, 18, 17, '耶和华就对我说：他们所说的是。'),
('CUV', '申命记', 5, 18, 18, '我必在他们弟兄中间给他们兴起一位先知，像你。我要将当说的话传给他；他要将我一切所吩咐的都传给他们。'),
('CUV', '申命记', 5, 18, 19, '谁不听他奉我名所说的话，我必讨谁的罪。'),
('CUV', '申命记', 5, 18, 20, '若有先知擅敢托我的名说我所未曾吩咐他说的话，或是奉别神的名说话，那先知就必治死。'),
('CUV', '申命记', 5, 18, 21, '你心里若说：耶和华所未曾吩咐的话，我们怎能知道呢？'),
('CUV', '申命记', 5, 18, 22, '先知托耶和华的名说话，所说的若不成就，也无效验，这就是耶和华所未曾吩咐的，是那先知擅自说的，你不要怕他。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 19, 1, '耶和华─你神将列国之民剪除的时候，耶和华─你神也将他们的地赐给你，你接著住他们的城邑并他们的房屋，'),
('CUV', '申命记', 5, 19, 2, '就要在耶和华─你神所赐你为业的地上分定三座城。'),
('CUV', '申命记', 5, 19, 3, '要将耶和华─你神使你承受为业的地分为三段；又要预备道路，使误杀人的，都可以逃到那里去。'),
('CUV', '申命记', 5, 19, 4, '误杀人的逃到那里可以存活，定例乃是这样：凡素无仇恨，无心杀了人的，'),
('CUV', '申命记', 5, 19, 5, '就如人与邻舍同入树林砍伐树木，手拿斧子一砍，本想砍下树木，不料，斧头脱了把，飞落在邻舍身上，以致于死，这人逃到那些城的一座城，就可以存活，'),
('CUV', '申命记', 5, 19, 6, '免得报血仇的，心中火热追赶他，因路远就追上，将他杀死；其实他不该死，因为他与被杀的素无仇恨。'),
('CUV', '申命记', 5, 19, 7, '所以我吩咐你说，要分定三座城。'),
('CUV', '申命记', 5, 19, 8, '耶和华─你神若照他向你列祖所起的誓扩张你的境界，将所应许赐你列祖的地全然给你，'),
('CUV', '申命记', 5, 19, 9, '你若谨守遵行我今日所吩咐的这一切诫命，爱耶和华─你的神，常常遵行他的道，就要在这三座城之外，再添三座城，'),
('CUV', '申命记', 5, 19, 10, '免得无辜之人的血流在耶和华─你神所赐你为业的地上，流血的罪就归于你。'),
('CUV', '申命记', 5, 19, 11, '若有人恨他的邻舍，埋伏著起来击杀他，以致于死，便逃到这些城的一座城，'),
('CUV', '申命记', 5, 19, 12, '本城的长老就要打发人去，从那里带出他来，交在报血仇的手中，将他治死。'),
('CUV', '申命记', 5, 19, 13, '你眼不可顾惜他，却要从以色列中除掉流无辜血的罪，使你可以得福。'),
('CUV', '申命记', 5, 19, 14, '在耶和华─你神所赐你承受为业之地，不可挪移你邻舍的地界，那是先人所定的。'),
('CUV', '申命记', 5, 19, 15, '人无论犯甚么罪，作甚么恶，不可凭一个人的口作见证，总要凭两三个人的口作见证才可定案。'),
('CUV', '申命记', 5, 19, 16, '若有凶恶的见证人起来，见证某人作恶，'),
('CUV', '申命记', 5, 19, 17, '这两个争讼的人就要站在耶和华面前，和当时的祭司，并审判官面前，'),
('CUV', '申命记', 5, 19, 18, '审判官要细细的查究，若见证人果然是作假见证的，以假见证陷害弟兄，'),
('CUV', '申命记', 5, 19, 19, '你们就要待他如同他想要待的弟兄。这样，就把那恶从你们中间除掉。'),
('CUV', '申命记', 5, 19, 20, '别人听见都要害怕，就不敢在你们中间再行这样的恶了。'),
('CUV', '申命记', 5, 19, 21, '你眼不可顾惜，要以命偿命，以眼还眼，以牙还牙，以手还手，以脚还脚。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 20, 1, '你出去与仇敌争战的时候，看见马匹、车辆，并有比你多的人民，不要怕他们，因为领你出埃及地的耶和华─你神与你同在。'),
('CUV', '申命记', 5, 20, 2, '你们将要上阵的时候，祭司要到百姓面前宣告'),
('CUV', '申命记', 5, 20, 3, '说：以色列人哪，你们当听，你们今日将要与仇敌争战，不要胆怯，不要惧怕战兢，也不要因他们惊恐；'),
('CUV', '申命记', 5, 20, 4, '因为耶和华─你们的神与你们同去，要为你们与仇敌争战，拯救你们。'),
('CUV', '申命记', 5, 20, 5, '官长也要对百姓宣告说：谁建造房屋，尚未奉献，他可以回家去，恐怕他阵亡，别人去奉献。'),
('CUV', '申命记', 5, 20, 6, '谁种葡萄园，尚未用所结的果子，他可以回家去，恐怕他阵亡，别人去用。'),
('CUV', '申命记', 5, 20, 7, '谁聘定了妻，尚未迎娶，他可以回家去，恐怕他阵亡，别人去娶。'),
('CUV', '申命记', 5, 20, 8, '官长又要对百姓宣告说：谁惧怕胆怯，他可以回家去，恐怕他弟兄的心消化，和他一样。'),
('CUV', '申命记', 5, 20, 9, '官长对百姓宣告完了，就当派军长率领他们。'),
('CUV', '申命记', 5, 20, 10, '你临近一座城、要攻打的时候，先要对城里的民宣告和睦的话。'),
('CUV', '申命记', 5, 20, 11, '他们若以和睦的话回答你，给你开了城，城里所有的人都要给你效劳，服事你；'),
('CUV', '申命记', 5, 20, 12, '若不肯与你和好，反要与你打仗，你就要围困那城。'),
('CUV', '申命记', 5, 20, 13, '耶和华─你的神把城交付你手，你就要用刀杀尽这城的男丁。'),
('CUV', '申命记', 5, 20, 14, '惟有妇女、孩子、牲畜，和城内一切的财物，你可以取为自己的掠物。耶和华─你神把你仇敌的财物赐给你，你可以吃用。'),
('CUV', '申命记', 5, 20, 15, '离你甚远的各城，不是这些国民的城，你都要这样待他。'),
('CUV', '申命记', 5, 20, 16, '但这些国民的城，耶和华─你神既赐你为业，其中凡有气息的，一个不可存留；'),
('CUV', '申命记', 5, 20, 17, '只要照耶和华─你神所吩咐的将这赫人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人都灭绝净尽，'),
('CUV', '申命记', 5, 20, 18, '免得他们教导你们学习一切可憎恶的事，就是他们向自己神所行的，以致你们得罪耶和华─你们的神。'),
('CUV', '申命记', 5, 20, 19, '你若许久围困、攻打所要取的一座城，就不可举斧子砍坏树木；因为你可以吃那树上的果子，不可砍伐。田间的树木岂是人，叫你蹧蹋么？'),
('CUV', '申命记', 5, 20, 20, '惟独你所知道不是结果毁坏、砍伐，用以修筑营垒，攻击那与你打仗的城，直到攻塌了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 21, 1, '在耶和华─你神所赐你为业的地上，若遇见被杀的人倒在田野，不知道是谁杀的，'),
('CUV', '申命记', 5, 21, 2, '长老和审判官就要出去，从被杀的人那里量起，直量到四围的城邑，'),
('CUV', '申命记', 5, 21, 3, '看哪城离被杀的人最近，那城的长老就要从牛群中取一只未曾耕地、未曾负轭的母牛犊，'),
('CUV', '申命记', 5, 21, 4, '把母牛犊牵到流水、未曾耕种的山谷去，在谷中打折母牛犊的颈项。'),
('CUV', '申命记', 5, 21, 5, '祭司利未的子孙要近前来；因为耶和华─你的神拣选了他们事奉他，奉耶和华的名祝福，所有争讼殴打的事都要凭他们判断。'),
('CUV', '申命记', 5, 21, 6, '那城的众长老，就是离被杀的人最近的，要在那山谷中，在所打折颈项的母牛犊以上洗手，'),
('CUV', '申命记', 5, 21, 7, '祷告（原文作回答）说：我们的手未曾流这人的血；我们的眼也未曾看见这事。'),
('CUV', '申命记', 5, 21, 8, '耶和华阿，求你赦免你所救赎的以色列民，不要使流无辜血的罪归在你的百姓以色列中间。这样，流血的罪必得赦免。'),
('CUV', '申命记', 5, 21, 9, '你行耶和华眼中看为正的事，就可以从你们中间除掉流无辜血的罪。'),
('CUV', '申命记', 5, 21, 10, '你出去与仇敌争战的时候，耶和华─你的神将他们交在你手中，你就掳了他们去。'),
('CUV', '申命记', 5, 21, 11, '若在被掳的人中见有美貌的女子，恋慕他，要娶他为妻，'),
('CUV', '申命记', 5, 21, 12, '就可以领他到你家里去；他便要剃头发，修指甲，'),
('CUV', '申命记', 5, 21, 13, '脱去被掳时所穿的衣服，住在你家里哀哭父母一个整月，然后可以与他同房。你作他的丈夫，他作你的妻子。'),
('CUV', '申命记', 5, 21, 14, '后来你若不喜悦他，就要由他随意出去，决不可为钱卖他，也不可当婢女待他，因为你玷污了他。'),
('CUV', '申命记', 5, 21, 15, '人若有二妻，一为所爱，一为所恶，所爱的、所恶的都给他生了儿子，但长子是所恶之妻生的。'),
('CUV', '申命记', 5, 21, 16, '到了把产业分给儿子承受的时候，不可将所爱之妻生的儿子立为长子，在所恶之妻生的儿子以上，'),
('CUV', '申命记', 5, 21, 17, '却要认所恶之妻生的儿子为长子，将产业多加一分给他；因这儿子是他力量强壮的时候生的，长子的名分本当归他。'),
('CUV', '申命记', 5, 21, 18, '人若有顽梗悖逆的儿子，不听从父母的话，他们虽惩治他，他仍不听从，'),
('CUV', '申命记', 5, 21, 19, '父母就要抓住他，将他带到本地的城门、本城的长老那里，'),
('CUV', '申命记', 5, 21, 20, '对长老说：我们这儿子顽梗悖逆，不听从我们的话，是贪食好酒的人。'),
('CUV', '申命记', 5, 21, 21, '本城的众人就要用石头将他打死。这样，就把那恶从你们中间除掉，以色列众人都要听见害怕。'),
('CUV', '申命记', 5, 21, 22, '人若犯该死的罪，被治死了，你将他挂在木头上，'),
('CUV', '申命记', 5, 21, 23, '他的尸首不可留在木头上过夜，必要当日将他葬埋，免得玷污了耶和华─你神所赐你为业之地。因为被挂的人是在神面前受咒诅的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 22, 1, '你若看见弟兄的牛或羊失迷了路，不可佯为不见，总要把他牵回来交给你的弟兄。'),
('CUV', '申命记', 5, 22, 2, '你弟兄若离你远，或是你不认识他，就要牵到你家去，留在你那里，等你弟兄来寻找就还给他。'),
('CUV', '申命记', 5, 22, 3, '你的弟兄无论失落甚么，或是驴，或是衣服，你若遇见，都要这样行，不可佯为不见。'),
('CUV', '申命记', 5, 22, 4, '你若看见弟兄的牛或驴跌倒在路上，不可佯为不见，总要帮助他拉起来。'),
('CUV', '申命记', 5, 22, 5, '妇女不可穿戴男子所穿戴的，男子也不可穿妇女的衣服，因为这样行都是耶和华─你神所憎恶的。'),
('CUV', '申命记', 5, 22, 6, '你若路上遇见鸟窝，或在树上或在地上，里头有雏或有蛋，母鸟伏在雏上或在蛋上，你不可连母带雏一并取去。'),
('CUV', '申命记', 5, 22, 7, '总要放母，只可取雏，这样你就可以享福，日子得以长久。'),
('CUV', '申命记', 5, 22, 8, '你若建造房屋，要在房上的四围安栏杆，免得有人从房上掉下来，流血的罪就归于你家。'),
('CUV', '申命记', 5, 22, 9, '不可把两样种子种在你的葡萄园里，免得你撒种所结的和葡萄园的果子都要充公。'),
('CUV', '申命记', 5, 22, 10, '不可并用牛、驴耕地。'),
('CUV', '申命记', 5, 22, 11, '不可穿羊毛、细麻两样搀杂料做的衣服。'),
('CUV', '申命记', 5, 22, 12, '你要在所披的外衣上四围做䍁子。'),
('CUV', '申命记', 5, 22, 13, '人若娶妻，与他同房之后恨恶他，'),
('CUV', '申命记', 5, 22, 14, '信口说他，将丑名加在他身上，说：我娶了这女子，与他同房，见他没有贞洁的凭据；'),
('CUV', '申命记', 5, 22, 15, '女子的父母就要把女子贞洁的凭据拿出来，带到本城门长老那里。'),
('CUV', '申命记', 5, 22, 16, '女子的父亲要对长老说：我将我的女儿给这人为妻，他恨恶他，'),
('CUV', '申命记', 5, 22, 17, '信口说他，说：我见你的女儿没有贞洁的凭据；其实这就是我女儿贞洁的凭据。父母就把那布铺在本城的长老面前。'),
('CUV', '申命记', 5, 22, 18, '本城的长老要拿住那人，惩治他，'),
('CUV', '申命记', 5, 22, 19, '并要罚他一百舍客勒银子，给女子的父亲，因为他将丑名加在以色列的一个处女身上。女子仍作他的妻，终身不可休他。'),
('CUV', '申命记', 5, 22, 20, '但这事若是真的，女子没有贞洁的凭据，'),
('CUV', '申命记', 5, 22, 21, '就要将女子带到他父家的门口，本城的人要用石头将他打死；因为他在父家行了淫乱，在以色列中做了丑事。这样，就把那恶从你们中间除掉。'),
('CUV', '申命记', 5, 22, 22, '若遇见人与有丈夫的妇人行淫，就要将奸夫淫妇一并治死。这样，就把那恶从以色列中除掉。'),
('CUV', '申命记', 5, 22, 23, '若有处女已经许配丈夫，有人在城里遇见他，与他行淫，'),
('CUV', '申命记', 5, 22, 24, '你们就要把这二人带到本城门，用石头打死─女子是因为虽在城里却没有喊叫；男子是因为玷污别人的妻。这样，就把那恶从你们中间除掉。'),
('CUV', '申命记', 5, 22, 25, '若有男子在田野遇见已经许配人的女子，强与他行淫，只要将那男子治死。'),
('CUV', '申命记', 5, 22, 26, '但不可办女子；他本没有该死的罪，这事就类乎人起来攻击邻舍，将他杀了一样。'),
('CUV', '申命记', 5, 22, 27, '因为男子是在田野遇见那已经许配人的女子，女子喊叫，并无人救他。'),
('CUV', '申命记', 5, 22, 28, '若有男子遇见没有许配人的处女，抓住他，与他行淫，被人看见，'),
('CUV', '申命记', 5, 22, 29, '这男子就要拿五十舍客勒银子给女子的父亲；因他玷污了这女子，就要娶他为妻，终身不可休他。'),
('CUV', '申命记', 5, 22, 30, '人不可娶继母为妻；不可掀开他父亲的衣襟。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 23, 1, '凡外肾受伤的，或被阉割的，不可入耶和华的会。'),
('CUV', '申命记', 5, 23, 2, '私生子不可入耶和华的会；他的子孙，直到十代，也不可入耶和华的会。'),
('CUV', '申命记', 5, 23, 3, '亚扪人或是摩押人不可入耶和华的会；他们的子孙，虽过十代，也永不可入耶和华的会。'),
('CUV', '申命记', 5, 23, 4, '因为你们出埃及的时候，他们没有拿食物和水在路上迎接你们，又因他们雇了米所波大米的毘夺人比珥的儿子巴兰来咒诅你们。'),
('CUV', '申命记', 5, 23, 5, '然而耶和华─你的神不肯听从巴兰，咒诅的言语变为祝福的话，因为耶和华─你的神爱你。'),
('CUV', '申命记', 5, 23, 6, '你一生一世永不可求他们的平安和他们的利益。'),
('CUV', '申命记', 5, 23, 7, '不可憎恶以东人，因为他是你的弟兄。不可憎恶埃及人，因为你在他的地上作过寄居的。'),
('CUV', '申命记', 5, 23, 8, '他们第三代子孙入耶和华的会。'),
('CUV', '申命记', 5, 23, 9, '你出兵攻打仇敌，就要远避诸恶。'),
('CUV', '申命记', 5, 23, 10, '你们中间，若有人夜间偶然梦遗，不洁净，就要出到营外，不可入营；'),
('CUV', '申命记', 5, 23, 11, '到傍晚的时候，他要用水洗澡，及至日落了才可以入营。'),
('CUV', '申命记', 5, 23, 12, '你在营外也该定出一个地方作为便所。'),
('CUV', '申命记', 5, 23, 13, '在你器械之中当预备一把锹，你出营外便溺以后，用以铲土，转身掩盖。'),
('CUV', '申命记', 5, 23, 14, '因为耶和华─你的神常在你营中行走，要救护你，将仇敌交给你，所以你的营理当圣洁，免得他见你那里有污秽，就离开你。'),
('CUV', '申命记', 5, 23, 15, '若有奴仆脱了主人的手，逃到你那里，你不可将他交付他的主人。'),
('CUV', '申命记', 5, 23, 16, '他必在你那里与你同住，在你的城邑中，要由他选择一个所喜悦的地方居住；你不可欺负他。'),
('CUV', '申命记', 5, 23, 17, '以色列的女子中不可有妓女；以色列的男子中不可有娈童。'),
('CUV', '申命记', 5, 23, 18, '娼妓所得的钱，或娈童（原文作狗）所得的价，你不可带入耶和华─你神的殿还愿，因为这两样都是耶和华─你神所憎恶的。'),
('CUV', '申命记', 5, 23, 19, '你借给你弟兄的，或是钱财或是粮食，无论甚么可生利的物，都不可取利。'),
('CUV', '申命记', 5, 23, 20, '借给外邦人可以取利，只是借给你弟兄不可取利。这样，耶和华─你神必在你所去得为业的地上和你手里所办的一切事上赐福与你。'),
('CUV', '申命记', 5, 23, 21, '你向耶和华─你的神许愿，偿还不可迟延；因为耶和华─你的神必定向你追讨，你不偿还就有罪。'),
('CUV', '申命记', 5, 23, 22, '你若不许愿，倒无罪。'),
('CUV', '申命记', 5, 23, 23, '你嘴里所出的，就是你口中应许甘心所献的，要照你向耶和华─你神所许的愿谨守遵行。'),
('CUV', '申命记', 5, 23, 24, '你进了邻舍的葡萄园，可以随意吃饱了葡萄，只是不可装在器皿中。'),
('CUV', '申命记', 5, 23, 25, '你进了邻舍站著的禾稼，可以用手摘穗子，只是不可用镰刀割取禾稼。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 24, 1, '人若娶妻以后，见他有甚么不合理的事，不喜悦他，就可以写休书交在他手中，打发他离开夫家。'),
('CUV', '申命记', 5, 24, 2, '妇人离开夫家以后，可以去嫁别人。'),
('CUV', '申命记', 5, 24, 3, '后夫若恨恶他，写休书交在他手中，打发他离开夫家，或是娶他为妻的后夫死了，'),
('CUV', '申命记', 5, 24, 4, '打发他去的前夫不可在妇人玷污之后再娶他为妻，因为这是耶和华所憎恶的；不可使耶和华─你神所赐为业之地被玷污了。'),
('CUV', '申命记', 5, 24, 5, '新娶妻之人不可从军出征，也不可托他办理甚么公事，可以在家清闲一年，使他所娶的妻快活。'),
('CUV', '申命记', 5, 24, 6, '不可拿人的全盘磨石或是上磨石作当头，因为这是拿人的命作当头。'),
('CUV', '申命记', 5, 24, 7, '若遇见人拐带以色列中的一个弟兄，当奴才待他，或是卖了他，那拐带人的就必治死。这样，便将那恶从你们中间除掉。'),
('CUV', '申命记', 5, 24, 8, '在大痲疯的灾病上，你们要谨慎，照祭司利未人一切所指教你们的留意遵行。我怎样吩咐他们，你们要怎样遵行。'),
('CUV', '申命记', 5, 24, 9, '当记念出埃及后，在路上，耶和华─你神向米利暗所行的事。'),
('CUV', '申命记', 5, 24, 10, '你借给邻舍，不拘是甚么，不可进他家拿他的当头。'),
('CUV', '申命记', 5, 24, 11, '要站在外面，等那向你借贷的人把当头拿出来交给你。'),
('CUV', '申命记', 5, 24, 12, '他若是穷人，你不可留他的当头过夜。'),
('CUV', '申命记', 5, 24, 13, '日落的时候，总要把当头还他，使他用那件衣服盖著睡觉，他就为你祝福；这在耶和华─你神面前就是你的义了。'),
('CUV', '申命记', 5, 24, 14, '困苦穷乏的雇工，无论是你的弟兄或是在你城里寄居的，你不可欺负他。'),
('CUV', '申命记', 5, 24, 15, '要当日给他工价，不可等到日落─因为他穷苦，把心放在工价上─恐怕他因你求告耶和华，罪便归你了。'),
('CUV', '申命记', 5, 24, 16, '不可因子杀父，也不可因父杀子；凡被杀的都为本身的罪。'),
('CUV', '申命记', 5, 24, 17, '你不可向寄居的和孤儿屈枉正直，也不可拿寡妇的衣裳作当头。'),
('CUV', '申命记', 5, 24, 18, '要记念你在埃及作过奴仆。耶和华─你的神从那里将你救赎，所以我吩咐你这样行。'),
('CUV', '申命记', 5, 24, 19, '你在田间收割庄稼，若忘下一捆，不可回去再取，要留给寄居的与孤儿寡妇。这样，耶和华─你神必在你手里所办的一切事上赐福与你。'),
('CUV', '申命记', 5, 24, 20, '你打橄榄树，枝上剩下的，不可再打；要留给寄居的与孤儿寡妇。'),
('CUV', '申命记', 5, 24, 21, '你摘葡萄园的葡萄，所剩下的，不可再摘；要留给寄居的与孤儿寡妇。'),
('CUV', '申命记', 5, 24, 22, '你也要记念你在埃及地作过奴仆，所以我吩咐你这样行。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 25, 1, '人若有争讼，来听审判，审判官就要定义人有理，定恶人有罪。'),
('CUV', '申命记', 5, 25, 2, '恶人若该受责打，审判官就要叫他当面伏在地上，按著他的罪照数责打。'),
('CUV', '申命记', 5, 25, 3, '只可打他四十下，不可过数；若过数，便是轻贱你的弟兄了。'),
('CUV', '申命记', 5, 25, 4, '牛在场上踹谷的时候，不可笼住他的嘴。'),
('CUV', '申命记', 5, 25, 5, '弟兄同居，若死了一个，没有儿子，死人的妻不可出嫁外人，他丈夫的兄弟当尽弟兄的本分，娶他为妻，与他同房。'),
('CUV', '申命记', 5, 25, 6, '妇人生的长子必归死兄的名下，免得他的名在以色列中涂抹了。'),
('CUV', '申命记', 5, 25, 7, '那人若不愿意娶他哥哥的妻，他哥哥的妻就要到城门长老那里，说：我丈夫的兄弟不肯在以色列中兴起他哥哥的名字，不给我尽弟兄的本分。'),
('CUV', '申命记', 5, 25, 8, '本城的长老就要召那人来问他，他若执意说：我不愿意娶他，'),
('CUV', '申命记', 5, 25, 9, '他哥哥的妻就要当著长老到那人的跟前，脱了他的鞋，吐唾沫在他脸上，说：凡不为哥哥建立家室的都要这样待他。'),
('CUV', '申命记', 5, 25, 10, '在以色列中，他的名必称为脱鞋之家。'),
('CUV', '申命记', 5, 25, 11, '若有二人争斗，这人的妻近前来，要救他丈夫脱离那打他丈夫之人的手，抓住那人的下体，'),
('CUV', '申命记', 5, 25, 12, '就要砍断妇人的手，眼不可顾惜他。'),
('CUV', '申命记', 5, 25, 13, '你囊中不可有一大一小两样的法码。'),
('CUV', '申命记', 5, 25, 14, '你家里不可有一大一小两样的升斗。'),
('CUV', '申命记', 5, 25, 15, '当用对准公平的法码，公平的升斗。这样，在耶和华─你神所赐你的地上，你的日子就可以长久。'),
('CUV', '申命记', 5, 25, 16, '因为行非义之事的人都是耶和华─你神所憎恶的。'),
('CUV', '申命记', 5, 25, 17, '你要记念你们出埃及的时候，亚玛力人在路上怎样待你。'),
('CUV', '申命记', 5, 25, 18, '他们在路上遇见你，趁你疲乏困倦击杀你尽后边软弱的人，并不敬畏神。'),
('CUV', '申命记', 5, 25, 19, '所以耶和华─你神使你不被四围一切的仇敌扰乱，在耶和华─你神赐你为业的地上得享平安。那时，你要将亚玛力的名号从天下涂抹了，不可忘记。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 26, 1, '你进去得了耶和华─你神所赐你为业之地居住，'),
('CUV', '申命记', 5, 26, 2, '就要从耶和华─你神赐你的地上将所收的各种初熟的土产取些来，盛在筐子里，往耶和华─你神所选择要立为他名的居所去，'),
('CUV', '申命记', 5, 26, 3, '见当时作祭司的，对他说：我今日向耶和华─你神明认，我已来到耶和华向我们列祖起誓应许赐给我们的地。'),
('CUV', '申命记', 5, 26, 4, '祭司就从你手里取过筐子来，放在耶和华─你神的坛前。'),
('CUV', '申命记', 5, 26, 5, '你要在耶和华─你神面前说：我祖原是一个将亡的亚兰人，下到埃及寄居。他人口稀少，在那里却成了又大又强、人数很多的国民。'),
('CUV', '申命记', 5, 26, 6, '埃及人恶待我们，苦害我们，将苦工加在我们身上。'),
('CUV', '申命记', 5, 26, 7, '于是我们哀求耶和华─我们列祖的神，耶和华听见我们的声音，看见我们所受的困苦、劳碌、欺压，'),
('CUV', '申命记', 5, 26, 8, '他就用大能的手和伸出来的膀臂，并大可畏的事与神迹奇事，领我们出了埃及，'),
('CUV', '申命记', 5, 26, 9, '将我们领进这地方，把这流奶与蜜之地赐给我们。'),
('CUV', '申命记', 5, 26, 10, '耶和华阿，现在我把你所赐给我地上初熟的土产奉了来。随后你要把筐子放在耶和华─你神面前，向耶和华─你的神下拜。'),
('CUV', '申命记', 5, 26, 11, '你和利未人，并在你们中间寄居的，要因耶和华─你神所赐你和你家的一切福分欢乐。'),
('CUV', '申命记', 5, 26, 12, '每逢三年，就是十分取一之年，你取完了一切土产的十分之一，要分给利未人和寄居的，与孤儿寡妇，使他们在你城中可以吃得饱足。'),
('CUV', '申命记', 5, 26, 13, '你又要在耶和华─你神面前说：我已将圣物从我家里拿出来，给了利未人和寄居的，与孤儿寡妇，是照你所吩咐我的一切命令。你的命令我都没有违背，也没有忘记。'),
('CUV', '申命记', 5, 26, 14, '我守丧的时候，没有吃这圣物；不洁净的时候，也没有拿出来，又没有为死人送去。我听从了耶和华─我神的话，都照你所吩咐的行了。'),
('CUV', '申命记', 5, 26, 15, '求你从天上、你的圣所垂看，赐福给你的百姓以色列与你所赐给我们的地，就是你向我们列祖起誓赐我们流奶与蜜之地。'),
('CUV', '申命记', 5, 26, 16, '耶和华─你的神今日吩咐你行这些律例典章，所以你要尽心尽性谨守遵行。'),
('CUV', '申命记', 5, 26, 17, '你今日认耶和华为你的神，应许遵行他的道，谨守他的律例、诫命、典章，听从他的话。'),
('CUV', '申命记', 5, 26, 18, '耶和华今日照他所应许你的，也认你为他的子民，使你谨守他的一切诫命，'),
('CUV', '申命记', 5, 26, 19, '又使你得称赞、美名、尊荣，超乎他所造的万民之上，并照他所应许的使你归耶和华─你神为圣洁的民。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 27, 1, '摩西和以色列的众长老吩咐百姓说：你们要遵守我今日所吩咐的一切诫命。'),
('CUV', '申命记', 5, 27, 2, '你们过约但河，到了耶和华─你神所赐给你的地，当天要立起几块大石头，墁上石灰，'),
('CUV', '申命记', 5, 27, 3, '把这律法的一切话写在石头上。你过了河，可以进入耶和华─你神所赐你流奶与蜜之地，正如耶和华─你列祖之神所应许你的。'),
('CUV', '申命记', 5, 27, 4, '你们过了约但河，就要在以巴路山上照我今日所吩咐的，将这些石头立起来，墁上石灰。'),
('CUV', '申命记', 5, 27, 5, '在那里要为耶和华─你的神筑一座石坛；在石头上不可动铁器。'),
('CUV', '申命记', 5, 27, 6, '要用没有凿过的石头筑耶和华─你神的坛，在坛上要将燔祭献给耶和华─你的神。'),
('CUV', '申命记', 5, 27, 7, '又要献平安祭，且在那里吃，在耶和华─你的神面前欢乐。'),
('CUV', '申命记', 5, 27, 8, '你要将这律法的一切话明明的写在石头上。'),
('CUV', '申命记', 5, 27, 9, '摩西和祭司利未人晓谕以色列众人说：以色列阿，要默默静听。你今日成为耶和华─你神的百姓了。'),
('CUV', '申命记', 5, 27, 10, '所以要听从耶和华─你神的话，遵行他的诫命律例，就是我今日所吩咐你的。'),
('CUV', '申命记', 5, 27, 11, '当日，摩西嘱咐百姓说：'),
('CUV', '申命记', 5, 27, 12, '你们过了约但河，西缅、利未、犹大、以萨迦、约瑟、便雅悯六个支派的人都要站在基利心山上为百姓祝福。'),
('CUV', '申命记', 5, 27, 13, '流便、迦得、亚设、西布伦、但、拿弗他利六个支派的人都要站在以巴路山上宣布咒诅。'),
('CUV', '申命记', 5, 27, 14, '利未人要向以色列众人高声说：'),
('CUV', '申命记', 5, 27, 15, '有人制造耶和华所憎恶的偶像，或雕刻，或铸造，就是工匠手所做的，在暗中设立，那人必受咒诅！百姓都要答应说：阿们！'),
('CUV', '申命记', 5, 27, 16, '轻慢父母的，必受咒诅！百姓都要说：阿们！'),
('CUV', '申命记', 5, 27, 17, '挪移邻舍地界的，必受咒诅！百姓都要说：阿们！'),
('CUV', '申命记', 5, 27, 18, '使瞎子走差路的，必受咒诅！百姓都要说：阿们！'),
('CUV', '申命记', 5, 27, 19, '向寄居的和孤儿寡妇屈枉正直的，必受咒诅！百姓都要说：阿们！'),
('CUV', '申命记', 5, 27, 20, '与继母行淫的，必受咒诅！因为掀开他父亲的衣襟。百姓都要说：阿们！'),
('CUV', '申命记', 5, 27, 21, '与兽淫合的，必受咒诅！百姓都要说：阿们！'),
('CUV', '申命记', 5, 27, 22, '与异母同父，或异父同母的姊妹行淫的，必受咒诅！百姓都要说：阿们！'),
('CUV', '申命记', 5, 27, 23, '与岳母行淫的，必受咒诅！百姓都要说：阿们！'),
('CUV', '申命记', 5, 27, 24, '暗中杀人的，必受咒诅！百姓都要说：阿们！'),
('CUV', '申命记', 5, 27, 25, '受贿赂害死无辜之人的，必受咒诅！百姓都要说：阿们！'),
('CUV', '申命记', 5, 27, 26, '不坚守遵行这律法言语的，必受咒诅！百姓都要说：阿们！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 28, 1, '你若留意听从耶和华─你神的话，谨守遵行他的一切诫命，就是我今日所吩咐你的，他必使你超乎天下万民之上。'),
('CUV', '申命记', 5, 28, 2, '你若听从耶和华─你神的话，这以下的福必追随你，临到你身上：'),
('CUV', '申命记', 5, 28, 3, '你在城里必蒙福，在田间也必蒙福。'),
('CUV', '申命记', 5, 28, 4, '你身所生的，地所产的，牲畜所下的，以及牛犊、羊羔，都必蒙福。'),
('CUV', '申命记', 5, 28, 5, '你的筐子和你的抟面盆都必蒙福。'),
('CUV', '申命记', 5, 28, 6, '你出也蒙福，入也蒙福。'),
('CUV', '申命记', 5, 28, 7, '仇敌起来攻击你，耶和华必使他们在你面前被你杀败；他们从一条路来攻击你，必从七条路逃跑。'),
('CUV', '申命记', 5, 28, 8, '在你仓房里，并你手所办的一切事上，耶和华所命的福必临到你。耶和华─你神也要在所给你的地上赐福与你。'),
('CUV', '申命记', 5, 28, 9, '你若谨守耶和华─你神的诫命，遵行他的道，他必照著向你所起的誓立你作为自己的圣民。'),
('CUV', '申命记', 5, 28, 10, '天下万民见你归在耶和华的名下，就要惧怕你。'),
('CUV', '申命记', 5, 28, 11, '你在耶和华向你列祖起誓应许赐你的地上，他必使你身所生的，牲畜所下的，地所产的，都绰绰有余。'),
('CUV', '申命记', 5, 28, 12, '耶和华必为你开天上的府库，按时降雨在你的地上。在你手里所办的一切事上赐福与你。你必借给许多国民，却不至向他们借贷。'),
('CUV', '申命记', 5, 28, 13, '你若听从耶和华─你神的诫命，就是我今日所吩咐你的，谨守遵行，不偏左右，也不随从事奉别神，耶和华就必使你作首不作尾，但居上不居下。'),
('CUV', '申命记', 5, 28, 14, 'a'),
('CUV', '申命记', 5, 28, 15, '你若不听从耶和华─你神的话，不谨守遵行他的一切诫命律例，就是我今日所吩咐你的，这以下的咒诅都必追随你，临到你身上：'),
('CUV', '申命记', 5, 28, 16, '你在城里必受咒诅，在田间也必受咒诅。'),
('CUV', '申命记', 5, 28, 17, '你的筐子和你的抟面盆都必受咒诅。'),
('CUV', '申命记', 5, 28, 18, '你身所生的，地所产的，以及牛犊、羊羔，都必受咒诅。'),
('CUV', '申命记', 5, 28, 19, '你出也受咒诅，入也受咒诅。'),
('CUV', '申命记', 5, 28, 20, '耶和华因你行恶离弃他，必在你手里所办的一切事上，使咒诅、扰乱、责罚临到你，直到你被毁灭，速速的灭亡。'),
('CUV', '申命记', 5, 28, 21, '耶和华必使瘟疫贴在你身上，直到他将你从所进去得为业的地上灭绝。'),
('CUV', '申命记', 5, 28, 22, '耶和华要用痨病、热病、火症、疟疾、刀剑、旱风（或作：干旱）、霉烂攻击你。这都要追赶你，直到你灭亡。'),
('CUV', '申命记', 5, 28, 23, '你头上的天要变为铜，脚下的地要变为铁。'),
('CUV', '申命记', 5, 28, 24, '耶和华要使那降在你地上的雨变为尘沙，从天临在你身上，直到你灭亡'),
('CUV', '申命记', 5, 28, 25, '耶和华必使你败在仇敌面前，你从一条路去攻击他们，必从七条路逃跑。你必在天下万国中抛来抛去。'),
('CUV', '申命记', 5, 28, 26, '你的尸首必给空中的飞鸟和地上的走兽作食物，并无人哄赶。'),
('CUV', '申命记', 5, 28, 27, '耶和华必用埃及人的疮并痔疮、牛皮癣与疥攻击你，使你不能医治。'),
('CUV', '申命记', 5, 28, 28, '耶和华必用癫狂、眼瞎、心惊攻击你。'),
('CUV', '申命记', 5, 28, 29, '你必在午间摸索，好像瞎子在暗中摸索一样。你所行的必不亨通，时常遭遇欺压、抢夺，无人搭救。'),
('CUV', '申命记', 5, 28, 30, '你聘定了妻，别人必与他同房；你建造房屋，不得住在其内；你栽种葡萄园，也不得用其中的果子。'),
('CUV', '申命记', 5, 28, 31, '你的牛在你眼前宰了，你必不得吃他的肉；你的驴在你眼前被抢夺，不得归还；你的羊归了仇敌，无人搭救。'),
('CUV', '申命记', 5, 28, 32, '你的儿女必归与别国的民；你的眼目终日切望，甚至失明，你手中无力拯救。'),
('CUV', '申命记', 5, 28, 33, '你的土产和你劳碌得来的，必被你所不认识的国民吃尽。你时常被欺负，受压制，'),
('CUV', '申命记', 5, 28, 34, '甚至你因眼中所看见的，必致疯狂。'),
('CUV', '申命记', 5, 28, 35, '耶和华必攻击你，使你膝上腿上，从脚掌到头顶，长毒疮无法医治。'),
('CUV', '申命记', 5, 28, 36, '耶和华必将你和你所立的王领到你和你列祖素不认识的国去；在那里你必事奉木头石头的神。'),
('CUV', '申命记', 5, 28, 37, '你在耶和华领你到的各国中，要令人惊骇、笑谈、讥诮。'),
('CUV', '申命记', 5, 28, 38, '你带到田间的种子虽多，收进来的却少，因为被蝗虫吃了。'),
('CUV', '申命记', 5, 28, 39, '你栽种、修理葡萄园，却不得收葡萄，也不得喝葡萄酒，因为被虫子吃了。'),
('CUV', '申命记', 5, 28, 40, '你全境有橄榄树，却不得其油抹身，因为树上的橄榄不熟自落了。'),
('CUV', '申命记', 5, 28, 41, '你生儿养女，却不算是你的，因为必被掳去。'),
('CUV', '申命记', 5, 28, 42, '你所有的树木和你地里的出产必被蝗虫所吃。'),
('CUV', '申命记', 5, 28, 43, '在你中间寄居的，必渐渐上升，比你高而又高；你必渐渐下降，低而又低。'),
('CUV', '申命记', 5, 28, 44, '他必借给你，你却不能借给他；他必作首，你必作尾。'),
('CUV', '申命记', 5, 28, 45, '这一切咒诅必追随你，赶上你，直到你灭亡；因为你不听从耶和华─你神的话，不遵守他所吩咐的诫命律例。'),
('CUV', '申命记', 5, 28, 46, '这些咒诅必在你和你后裔的身上成为异迹奇事，直到永远！'),
('CUV', '申命记', 5, 28, 47, '因为你富有的时候，不欢心乐意的事奉耶和华─你的神，'),
('CUV', '申命记', 5, 28, 48, '所以你必在饥饿、干渴、赤露、缺乏之中事奉耶和华所打发来攻击你的仇敌。他必把铁轭加在你的颈项上，直到将你灭绝。'),
('CUV', '申命记', 5, 28, 49, '耶和华要从远方、地极带一国的民，如鹰飞来攻击你。这民的言语，你不懂得。'),
('CUV', '申命记', 5, 28, 50, '这民的面貌凶恶，不顾恤年老的，也不恩待年少的。'),
('CUV', '申命记', 5, 28, 51, '他们必吃你牲畜所下的和你地土所产的，直到你灭亡。你的五谷、新酒，和油，以及牛犊、羊羔，都不给你留下，直到将你灭绝。'),
('CUV', '申命记', 5, 28, 52, '他们必将你困在你各}城里，直到你所倚靠、高大坚固的城墙都被攻塌。他们必将你困在耶和华─你神所赐你遍地的各城里。'),
('CUV', '申命记', 5, 28, 53, '你在仇敌围困窘迫之中，必吃你本身所生的，就是耶和华─你神所赐给你的儿女之肉。'),
('CUV', '申命记', 5, 28, 54, '你们中间，柔弱娇嫩的人必恶眼看他弟兄和他怀中的妻，并他余剩的儿女；'),
('CUV', '申命记', 5, 28, 55, '甚至在你受仇敌围困窘迫的城中，他要吃儿女的肉，不肯分一点给他的亲人，因为他一无所剩。'),
('CUV', '申命记', 5, 28, 56, '你们中间，柔弱娇嫩的妇人，是因娇嫩柔弱不肯把脚踏地的，必恶眼看他怀中的丈夫和他的儿女。'),
('CUV', '申命记', 5, 28, 57, '他两腿中间出来的婴孩与他所要生的儿女，他因缺乏一切就要在你受仇敌围困窘迫的城中将他们暗暗地吃了。'),
('CUV', '申命记', 5, 28, 58, '这书上所写律法的一切话是叫你敬畏耶和华─你神可荣可畏的名。你若不谨守遵行，耶和华就必将奇灾，就是至大至长的灾，至重至久的病，加在你和你后裔的身上，'),
('CUV', '申命记', 5, 28, 59, 'a'),
('CUV', '申命记', 5, 28, 60, '也必使你所惧怕、埃及人的病都临到你，贴在你身上，'),
('CUV', '申命记', 5, 28, 61, '又必将没有写在这律法书上的各样疾病、灾殃降在你身上，直到你灭亡。'),
('CUV', '申命记', 5, 28, 62, '你们先前虽然像天上的星那样多，却因不听从耶和华─你神的话，所剩的人数就稀少了。'),
('CUV', '申命记', 5, 28, 63, '先前耶和华怎样喜悦善待你们，使你们众多，也要照样喜悦毁灭你们，使你们灭亡；并且你们从所要进去得的地上必被拔除。'),
('CUV', '申命记', 5, 28, 64, '耶和华必使你们分散在万民中，从地这边到地那边，你必在那里事奉你和你列祖素不认识、木头石头的神。'),
('CUV', '申命记', 5, 28, 65, '在那些国中，你必不得安逸，也不得落脚之地；耶和华却使你在那里心中跳动，眼目失明，精神消耗。'),
('CUV', '申命记', 5, 28, 66, '你的性命必悬悬无定；你昼夜恐惧，自料性命难保。'),
('CUV', '申命记', 5, 28, 67, '你因心里所恐惧的，眼中所看见的，早晨必说，巴不得到晚上才好；晚上必说，巴不得到早晨才好。'),
('CUV', '申命记', 5, 28, 68, '耶和华必使你坐船回埃及去，走我曾告诉你不得再见的路；在那里你必卖己身与仇敌作奴婢，却无人买。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 29, 1, '这是耶和华在摩押地吩咐摩西与以色列人立约的话，是在他和他们于何烈山所立的约之外。'),
('CUV', '申命记', 5, 29, 2, '摩西召了以色列众人来，对他们说：耶和华在埃及地，在你们眼前向法老和他众臣仆，并他全地所行的一切事，你们都看见了，'),
('CUV', '申命记', 5, 29, 3, '就是你亲眼看见的大试验和神迹，并那些大奇事。'),
('CUV', '申命记', 5, 29, 4, '但耶和华到今日没有使你们心能明白，眼能看见，耳能听见。'),
('CUV', '申命记', 5, 29, 5, '我领你们在旷野四十年，你们身上的衣服并没有穿破，脚上的鞋也没有穿坏。'),
('CUV', '申命记', 5, 29, 6, '你们没有吃饼，也没有喝清酒浓酒。这要使你们知道，耶和华是你们的神。'),
('CUV', '申命记', 5, 29, 7, '你们来到这地方，希实本王西宏、巴珊王噩都出来与我们交战，我们就击杀了他们，'),
('CUV', '申命记', 5, 29, 8, '取了他们的地给流便支派、迦得支派，和玛拿西半支派为业。'),
('CUV', '申命记', 5, 29, 9, '所以你们要谨守遵行这约的话，好叫你们在一切所行的事上亨通。'),
('CUV', '申命记', 5, 29, 10, '今日，你们的首领、族长（原文作支派）、长老、官长、以色列的男丁，你们的妻子儿女，和营中寄居的，以及为你们劈柴挑水的人，都站在耶和华─你们的神面前，'),
('CUV', '申命记', 5, 29, 11, 'a'),
('CUV', '申命记', 5, 29, 12, '为要你顺从耶和华─你神今日与你所立的约，向你所起的誓。'),
('CUV', '申命记', 5, 29, 13, '这样，他要照他向你所应许的话，又向你列祖亚伯拉罕、以撒、雅各所起的誓，今日立你作他的子民，他作你的神。这样，他要照他向你所应许的话，又向你列祖亚伯拉罕、以撒、雅各所起的誓，今日立你作他的子民，他作你的神。'),
('CUV', '申命记', 5, 29, 14, '我不但与你们立这约，起这誓，'),
('CUV', '申命记', 5, 29, 15, '凡与我们一同站在耶和华─我们神面前的，并今日不在我们这里的人，我也与他们立这约，起这誓。'),
('CUV', '申命记', 5, 29, 16, '我们曾住过埃及地，也从列国经过；这是你们知道的。'),
('CUV', '申命记', 5, 29, 17, '你们也看见他们中间可憎之物，并他们木、石、金、银的偶像。'),
('CUV', '申命记', 5, 29, 18, '惟恐你们中间，或男或女，或族长或支派长，今日心里偏离耶和华─我们的神，去事奉那些国的神；又怕你们中间有恶根生出苦菜和茵𫈟来，'),
('CUV', '申命记', 5, 29, 19, '听见这咒诅的话，心里仍是自夸说：我虽然行事心里顽梗，连累众人，却还是平安。'),
('CUV', '申命记', 5, 29, 20, '耶和华必不饶恕他；耶和华的怒气与愤恨要向他发作，如烟冒出，将这书上所写的一切咒诅都加在他身上。耶和华又要从天下涂抹他的名，'),
('CUV', '申命记', 5, 29, 21, '也必照著写在律法书上、约中的一切咒诅将他从以色列众支派中分别出来，使他受祸。'),
('CUV', '申命记', 5, 29, 22, '你们的后代，就是以后兴起来的子孙，和远方来的外人，看见这地的灾殃，并耶和华所降与这地的疾病，'),
('CUV', '申命记', 5, 29, 23, '又看见遍地有硫磺，有盐卤，有火迹，没有耕种，没有出产，连草都不生长─好像耶和华在忿怒中所倾覆的所多玛、蛾摩拉、押玛、洗扁一样─'),
('CUV', '申命记', 5, 29, 24, '所看见的人，连万国人，都必问说：耶和华为何向此地这样行呢？这样大发烈怒是甚么意思呢？'),
('CUV', '申命记', 5, 29, 25, '人必回答说：是因这地的人离弃了耶和华─他们列祖的神，领他们出埃及地的时候与他们所立的约，'),
('CUV', '申命记', 5, 29, 26, '去事奉敬拜素不认识的别神，是耶和华所未曾给他们安排的。'),
('CUV', '申命记', 5, 29, 27, '所以耶和华的怒气向这地发作，将这书上所写的一切咒诅都降在这地上。'),
('CUV', '申命记', 5, 29, 28, '耶和华在怒气、忿怒、大恼恨中将他们从本地拔出来，扔在别的地上，像今日一样。'),
('CUV', '申命记', 5, 29, 29, '隐秘的事是属耶和华─我们神的；惟有明显的事是永远属我们和我们子孙的，好叫我们遵行这律法上的一切话。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 30, 1, '我所陈明在你面前的这一切咒诅都临到你身上；你在耶和华─你神追赶你到的万国中必心里追念祝福的话；'),
('CUV', '申命记', 5, 30, 2, '你和你的子孙若尽心尽性归向耶和华─你的神，照著我今日一切所吩咐的听从他的话；'),
('CUV', '申命记', 5, 30, 3, '那时，耶和华─你的神必怜恤你，救回你这被掳的子民；耶和华─你的神要回转过来，从分散你到的万民中将你招聚回来。'),
('CUV', '申命记', 5, 30, 4, '你被赶散的人，就是在天涯的，耶和华─你的神也必从那里将你招聚回来。'),
('CUV', '申命记', 5, 30, 5, '耶和华─你的神必领你进入你列祖所得的地，使你可以得著；又必善待你，使你的人数比你列祖众多。'),
('CUV', '申命记', 5, 30, 6, '耶和华─你神必将你心里和你后裔心里的污秽除掉，好叫你尽心尽性爱耶和华─你的神，使你可以存活。'),
('CUV', '申命记', 5, 30, 7, '耶和华─你的神必将这一切咒诅加在你仇敌和恨恶你、逼迫你的人身上。'),
('CUV', '申命记', 5, 30, 8, '你必归回，听从耶和华的话，遵行他的一切诫命，就是我今日所吩咐你的。'),
('CUV', '申命记', 5, 30, 9, '你若听从耶和华─你神的话，谨守这律法书上所写的诫命律例，又尽心尽性归向耶和华─你的神，他必使你手里所办的一切事，并你身所生的，牲畜所下的，地土所产的，都绰绰有余；因为耶和华必再喜悦你，降福与你，像从前喜悦你列祖一样。'),
('CUV', '申命记', 5, 30, 10, 'a'),
('CUV', '申命记', 5, 30, 11, '我今日所吩咐你的诫命不是你难行的，也不是离你远的；'),
('CUV', '申命记', 5, 30, 12, '不是在天上，使你说：谁替我们上天取下来，使我们听见可以遵行呢？'),
('CUV', '申命记', 5, 30, 13, '也不是在海外，使你说：谁替我们过海取了来，使我们听见可以遵行呢？'),
('CUV', '申命记', 5, 30, 14, '这话却离你甚近，就在你口中，在你心里，使你可以遵行。'),
('CUV', '申命记', 5, 30, 15, '看哪，我今日将生与福，死与祸，陈明在你面前。'),
('CUV', '申命记', 5, 30, 16, '吩咐你爱耶和华─你的神，遵行他的道，谨守他的诫命、律例、典章，使你可以存活，人数增多，耶和华─你神就必在你所要进去得为业的地上赐福与你。'),
('CUV', '申命记', 5, 30, 17, '倘若你心里偏离，不肯听从，却被勾引去敬拜事奉别神，'),
('CUV', '申命记', 5, 30, 18, '我今日明明告诉你们，你们必要灭亡；在你过约但河、进去得为业的地上，你的日子必不长久。'),
('CUV', '申命记', 5, 30, 19, '我今日呼天唤地向你作见证；我将生死祸福陈明在你面前，所以你要拣选生命，使你和你的后裔都得存活；'),
('CUV', '申命记', 5, 30, 20, '且且爱耶和华─你的神，听从他的话，专靠他；因为他是你的生命，你的日子长久也在乎他。这样，你就可以在耶和华向你列祖亚伯拉罕、以撒、雅各起誓应许所赐的地上居住。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 31, 1, '摩西去告诉以色列众人'),
('CUV', '申命记', 5, 31, 2, '说：我现在一百二十岁了，不能照常出入；耶和华也曾对我说：你必不得过这约但河。'),
('CUV', '申命记', 5, 31, 3, '耶和华─你们的神必引导你们过去，将这些国民在你们面前灭绝，你们就得他们的地。约书亚必引导你们过去，正如耶和华所说的。'),
('CUV', '申命记', 5, 31, 4, '耶和华必待他们，如同从前待他所灭绝的亚摩利二王西宏与噩以及他们的国一样。'),
('CUV', '申命记', 5, 31, 5, '耶和华必将他们交给你们；你们要照我所吩咐的一切命令待他们。'),
('CUV', '申命记', 5, 31, 6, '你们当刚强壮胆，不要害怕，也不要畏惧他们，因为耶和华─你的神和你同去。他必不撇下你，也不丢弃你。'),
('CUV', '申命记', 5, 31, 7, '摩西召了约书亚来，在以色列众人眼前对他说：你当刚强壮胆！因为，你要和这百姓一同进入耶和华向他们列祖起誓应许所赐之地；你也要使他们承受那地为业。'),
('CUV', '申命记', 5, 31, 8, '耶和华必在你前面行；他必与你同在，必不撇下你，也不丢弃你。不要惧怕，也不要惊惶。'),
('CUV', '申命记', 5, 31, 9, '摩西将这律法写出来，交给抬耶和华约柜的祭司利未子孙和以色列的众长老。'),
('CUV', '申命记', 5, 31, 10, '摩西吩咐他们说：每逢七年的末一年，就在豁免年的定期住棚节的时候，'),
('CUV', '申命记', 5, 31, 11, '以色列众人来到耶和华─你神所选择的地方朝见他。那时，你要在以色列众人面前将这律法念给他们听。'),
('CUV', '申命记', 5, 31, 12, '要招聚他们男、女、孩子，并城里寄居的，使他们听，使他们学习，好敬畏耶和华─你们的神，谨守、遵行这律法的一切话，'),
('CUV', '申命记', 5, 31, 13, '也使他们未曾晓得这律法的儿女得以听见，学习敬畏耶和华─你们的神，在你们过约但河要得为业之地，存活的日子，常常这样行。'),
('CUV', '申命记', 5, 31, 14, '耶和华对摩西说：你的死期临近了；要召约书亚来，你们二人站在会幕里，我好嘱咐他。于是摩西和约书亚去站在会幕里。'),
('CUV', '申命记', 5, 31, 15, '耶和华在会幕里云柱中显现，云柱停在会幕门以上。'),
('CUV', '申命记', 5, 31, 16, '耶和华又对摩西说：你必和你列祖同睡。这百姓要起来，在他们所要去的地上，在那地的人中，随从外邦神行邪淫，离弃我，违背我与他们所立的约。'),
('CUV', '申命记', 5, 31, 17, '那时，我的怒气必向他们发作；我也必离弃他们，掩面不顾他们，以致他们被吞灭，并有许多的祸患灾难临到他们。那日他们必说：这些祸患临到我们，岂不是因我们的神不在我们中间么？'),
('CUV', '申命记', 5, 31, 18, '那时，因他们偏向别神所行的一切恶，我必定掩面不顾他们。'),
('CUV', '申命记', 5, 31, 19, '现在你要写一篇歌，教导以色列人，传给他们，使这歌见证他们的不是；'),
('CUV', '申命记', 5, 31, 20, '因为我将他们领进我向他们列祖起誓应许那流奶与蜜之地，他们在那里吃得饱足，身体肥胖，就必偏向别神，事奉他们，藐视我，背弃我的约。'),
('CUV', '申命记', 5, 31, 21, '那时，有许多祸患灾难临到他们，这歌必在他们面前作见证，他们后裔的口中必念诵不忘。我未领他们到我所起誓应许之地以先，他们所怀的意念我都知道了。'),
('CUV', '申命记', 5, 31, 22, '当日摩西就写了一篇歌，教导以色列人。'),
('CUV', '申命记', 5, 31, 23, '耶和华嘱咐嫩的儿子约书亚说：你当刚强壮胆，因为你必领以色列人进我所起誓应许他们的地；我必与你同在。'),
('CUV', '申命记', 5, 31, 24, '摩西将这律法的话写在书上，及至写完了，'),
('CUV', '申命记', 5, 31, 25, '就吩咐抬耶和华约柜的利未人说：'),
('CUV', '申命记', 5, 31, 26, '将这律法书放在耶和华─你们神的约柜旁，可以在那里见证以色列人的不是；'),
('CUV', '申命记', 5, 31, 27, '因为我知道你们是悖逆的，是硬著颈项的。我今日还活著与你们同在，你们尚且悖逆耶和华，何况我死后呢？'),
('CUV', '申命记', 5, 31, 28, '你们要将你们支派的众长老和官长都招聚了来，我好将这些话说与他们听，并呼天唤地见证他们的不是。'),
('CUV', '申命记', 5, 31, 29, '我知道我死后，你们必全然败坏，偏离我所吩咐你们的道，行耶和华眼中看为恶的事，以手所做的惹他发怒；日后必有祸患临到你们。'),
('CUV', '申命记', 5, 31, 30, '摩西将这一篇歌的话都说与以色列全会众听。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 32, 1, '诸天哪，侧耳，我要说话；愿地也听我口中的言语。'),
('CUV', '申命记', 5, 32, 2, '我的教训要淋漓如雨；我的言语要滴落如露，如细雨降在嫩草上，如甘霖降在菜蔬中。'),
('CUV', '申命记', 5, 32, 3, '我要宣告耶和华的名；你们要将大德归与我们的神。'),
('CUV', '申命记', 5, 32, 4, '他是磐石，他的作为完全；他所行的无不公平，是诚实无伪的神，又公义，又正直。'),
('CUV', '申命记', 5, 32, 5, '这乖僻弯曲的世代向他行事邪僻；有这弊病就不是他的儿女。'),
('CUV', '申命记', 5, 32, 6, '愚昧无知的民哪，你们这样报答耶和华么？他岂不是你的父、将你买来的么？他是制造你、建立你的。'),
('CUV', '申命记', 5, 32, 7, '你当追想上古之日，思念历代之年；问你的父亲，他必指示你；问你的长者，他必告诉你。'),
('CUV', '申命记', 5, 32, 8, '至高者将地业赐给列邦，将世人分开，就照以色列人的数目立定万民的疆界。'),
('CUV', '申命记', 5, 32, 9, '耶和华的分本是他的百姓；他的产业本是雅各。'),
('CUV', '申命记', 5, 32, 10, '耶和华遇见他在旷野─荒凉野兽吼叫之地，就环绕他，看顾他，保护他，如同保护眼中的瞳人。'),
('CUV', '申命记', 5, 32, 11, '又如鹰搅动巢窝，在雏鹰以上两翅搧展，接取雏鹰，背在两翼之上。'),
('CUV', '申命记', 5, 32, 12, '这样，耶和华独自引导他，并无外邦神与他同在。'),
('CUV', '申命记', 5, 32, 13, '耶和华使他乘驾地的高处，得吃田间的土产；又使他从磐石中咂蜜，从坚石中吸油；'),
('CUV', '申命记', 5, 32, 14, '也吃牛的奶油，羊的奶，羊羔的脂油，巴珊所出的公绵羊和山羊，与上好的麦子，也喝葡萄汁酿的酒。'),
('CUV', '申命记', 5, 32, 15, '但耶书仑渐渐肥胖，粗壮，光润，踢跳，奔跑，便离弃造他的神，轻看救他的磐石；'),
('CUV', '申命记', 5, 32, 16, '敬拜别神，触动神的愤恨，行可憎恶的事，惹了他的怒气。'),
('CUV', '申命记', 5, 32, 17, '所祭祀的鬼魔并非真神，乃是素不认识的神，是近来新兴的，是你列祖所不畏惧的。'),
('CUV', '申命记', 5, 32, 18, '你轻忽生你的磐石，忘记产你的神。'),
('CUV', '申命记', 5, 32, 19, '耶和华看见他的儿女惹动他，就厌恶他们，说：'),
('CUV', '申命记', 5, 32, 20, '我要向他们掩面，看他们的结局如何。他们本是极乖僻的族类，心中无诚实的儿女。'),
('CUV', '申命记', 5, 32, 21, '他们以那不算为神的触动我的愤恨，以虚无的神惹了我的怒气。我也要以那不成子民的触动他们的愤恨，以愚昧的国民惹了他们的怒气。'),
('CUV', '申命记', 5, 32, 22, '因为在我怒中有火烧起，直烧到极深的阴间，把地和地的出产尽都焚烧，山的根基也烧著了。'),
('CUV', '申命记', 5, 32, 23, '我要将祸患堆在他们身上，把我的箭向他们射尽。'),
('CUV', '申命记', 5, 32, 24, '他们必因饥饿消瘦，被炎热苦毒吞灭。我要打发野兽用牙齿咬他们，并土中腹行的，用毒气害他们。'),
('CUV', '申命记', 5, 32, 25, '外头有刀剑，内室有惊恐，使人丧亡，使少男、童女、吃奶的、白发的，尽都灭绝。'),
('CUV', '申命记', 5, 32, 26, '我说，我必将他们分散远方，使他们的名号从人间除灭。'),
('CUV', '申命记', 5, 32, 27, '惟恐仇敌惹动我，只怕敌人错看，说：是我们手的能力，并非耶和华所行的。'),
('CUV', '申命记', 5, 32, 28, '因为以色列民毫无计谋，心中没有聪明。'),
('CUV', '申命记', 5, 32, 29, '惟愿他们有智慧，能明白这事，肯思念他们的结局。'),
('CUV', '申命记', 5, 32, 30, '若不是他们的磐石卖了他们，若不是耶和华交出他们，一人焉能追赶他们千人？二人焉能使万人逃跑呢？'),
('CUV', '申命记', 5, 32, 31, '据我们的仇敌自己断定，他们的磐石不如我们的磐石。'),
('CUV', '申命记', 5, 32, 32, '他们的葡萄树是所多玛的葡萄树，蛾摩拉田园所生的；他们的葡萄是毒葡萄，全挂都是苦的。'),
('CUV', '申命记', 5, 32, 33, '他们的酒是大蛇的毒气，是虺蛇残害的恶毒。'),
('CUV', '申命记', 5, 32, 34, '这不都是积蓄在我这里，封锁在我府库中么？'),
('CUV', '申命记', 5, 32, 35, '他们失脚的时候，伸冤报应在我；因他们遭灾的日子近了；那要临在他们身上的必速速来到。'),
('CUV', '申命记', 5, 32, 36, '耶和华见他百姓毫无能力，无论困住的、自由的都没有剩下，就必为他们伸冤，为他的仆人后悔。'),
('CUV', '申命记', 5, 32, 37, '他必说：他们的神，他们所投靠的磐石，'),
('CUV', '申命记', 5, 32, 38, '就是向来吃他们祭牲的脂油，喝他们奠祭之酒的，在那里呢？他可以兴起帮助你们，护卫你们。'),
('CUV', '申命记', 5, 32, 39, '你们如今要知道：我，惟有我是神；在我以外并无别神。我使人死，我使人活；我损伤，我也医治，并无人能从我手中救出来。'),
('CUV', '申命记', 5, 32, 40, '我向天举手说：我凭我的永生起誓：'),
('CUV', '申命记', 5, 32, 41, '我若磨我闪亮的刀，手掌审判之权，就必报复我的敌人，报应恨我的人。'),
('CUV', '申命记', 5, 32, 42, '我要使我的箭饮血饮醉，就是被杀被掳之人的血。我的刀要吃肉，乃是仇敌中首领之头的肉。'),
('CUV', '申命记', 5, 32, 43, '你们外邦人当与主的百姓一同欢呼；因他要伸他仆人流血的冤，报应他的敌人，洁净他的地，救赎他的百姓。'),
('CUV', '申命记', 5, 32, 44, '摩西和嫩的儿子约书亚去将这歌的一切话说给百姓听。'),
('CUV', '申命记', 5, 32, 45, '摩西向以色列众人说完了这一切的话，'),
('CUV', '申命记', 5, 32, 46, '又说：我今日所警教你们的，你们都要放在心上；要吩咐你们的子孙谨守遵行这律法上的话。'),
('CUV', '申命记', 5, 32, 47, '因为这不是虚空、与你们无关的事，乃是你们的生命；在你们过约但河要得为业的地上必因这事日子得以长久。'),
('CUV', '申命记', 5, 32, 48, '当日，耶和华吩咐摩西说：'),
('CUV', '申命记', 5, 32, 49, '你上这亚巴琳山中的尼波山去，在摩押地与耶利哥相对，观看我所要赐给以色列人为业的迦南地。'),
('CUV', '申命记', 5, 32, 50, '你必死在你所登的山上，归你列祖（原文作本民）去，像你哥哥亚伦死在何珥山上，归他的列祖一样。'),
('CUV', '申命记', 5, 32, 51, '因为你们在寻的旷野，加低斯的米利巴水，在以色列人中没有尊我为圣，得罪了我。'),
('CUV', '申命记', 5, 32, 52, '我所赐给以色列人的地，你可以远远地观看，却不得进去。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 33, 1, '以下是神人摩西在未死之先为以色列人所祝的福：'),
('CUV', '申命记', 5, 33, 2, '他说：耶和华从西乃而来，从西珥向他们显现，从巴兰山发出光辉，从万万圣者中来临，从他右手为百姓传出烈火的律法。'),
('CUV', '申命记', 5, 33, 3, '他疼爱百姓；众圣徒都在他手中。他们坐在他的脚下，领受他的言语。'),
('CUV', '申命记', 5, 33, 4, '摩西将律法传给我们，作为雅各会众的产业。'),
('CUV', '申命记', 5, 33, 5, '百姓的众首领，以色列的各支派，一同聚会的时候，耶和华（原文作他）在耶书仑中为王。'),
('CUV', '申命记', 5, 33, 6, '愿流便存活，不至死亡；愿他人数不致稀少。'),
('CUV', '申命记', 5, 33, 7, '为犹大祝福说：求耶和华俯听犹大的声音，引导他归于本族；他曾用手为自己争战，你必帮助他攻击敌人。'),
('CUV', '申命记', 5, 33, 8, '论利未说：耶和华阿，你的土明和乌陵都在你的虔诚人那里。你在玛撒曾试验他，在米利巴水与他争论。'),
('CUV', '申命记', 5, 33, 9, '他论自己的父母说：我未曾看见；他也不承认弟兄，也不认识自己的儿女。这是因利未人遵行你的话，谨守你的约。'),
('CUV', '申命记', 5, 33, 10, '他们要将你的典章教训雅各，将你的律法教训以色列。他们要把香焚在你面前，把全牲的燔祭献在你的坛上。'),
('CUV', '申命记', 5, 33, 11, '求耶和华降福在他的财物上，悦纳他手里所办的事。那些起来攻击他和恨恶他的人，愿你刺透他们的腰，使他们不得再起来。'),
('CUV', '申命记', 5, 33, 12, '论便雅悯说：耶和华所亲爱的必同耶和华安然居住；耶和华终日遮蔽他，也住在他两肩之中。'),
('CUV', '申命记', 5, 33, 13, '论约瑟说：愿他的地蒙耶和华赐福，得天上的宝物、甘露，以及地里所藏的泉水；'),
('CUV', '申命记', 5, 33, 14, '得太阳所晒熟的美果，月亮所养成的宝物；'),
('CUV', '申命记', 5, 33, 15, '得上古之山的至宝，永世之岭的宝物；'),
('CUV', '申命记', 5, 33, 16, '得地和其中所充满的宝物，并住荆棘中上主的喜悦。愿这些福都归于约瑟的头上，归于那与弟兄迥别之人的顶上。'),
('CUV', '申命记', 5, 33, 17, '他为牛群中头生的，有威严；他的角是野牛的角，用以抵触万邦，直到地极。这角是以法莲的万万，玛拿西的千千。'),
('CUV', '申命记', 5, 33, 18, '论西布伦说：西布伦哪，你出外可以欢喜。以萨迦阿，在你帐棚里可以快乐。'),
('CUV', '申命记', 5, 33, 19, '他们要将列邦召到山上，在那里献公义的祭；因为他们要吸取海里的丰富，并沙中所藏的珍宝。'),
('CUV', '申命记', 5, 33, 20, '论迦得说：使迦得扩张的应当称颂！迦得住如母狮；他撕裂膀臂，连头顶也撕裂。'),
('CUV', '申命记', 5, 33, 21, '他为自己选择头一段地，因在那里有设立律法者的分存留。他与百姓的首领同来；他施行耶和华的公义和耶和华与以色列所立的典章。'),
('CUV', '申命记', 5, 33, 22, '论但说：但为小狮子，从巴珊跳出来。'),
('CUV', '申命记', 5, 33, 23, '论拿弗他利说：拿弗他利阿，你足沾恩惠，满得耶和华的福，可以得西方和南方为业。'),
('CUV', '申命记', 5, 33, 24, '论亚设说：愿亚设享受多子的福乐，得他弟兄的喜悦，可以把脚蘸在油中。'),
('CUV', '申命记', 5, 33, 25, '你的门闩（门闩或作：鞋）是铜的，铁的。你的日子如何，你的力量也必如何。'),
('CUV', '申命记', 5, 33, 26, '耶书仑哪，没有能比神的。他为帮助你，乘在天空，显其威荣，驾行穹苍。'),
('CUV', '申命记', 5, 33, 27, '永生的神是你的居所；他永久的膀臂在你以下。他在你前面撵出仇敌，说：毁灭罢。'),
('CUV', '申命记', 5, 33, 28, '以色列安然居住；雅各的本源独居五谷新酒之地。他的天也滴甘露。'),
('CUV', '申命记', 5, 33, 29, '以色列阿，你是有福的！谁像你这蒙耶和华所拯救的百姓呢？他是你的盾牌，帮助你，是你威荣的刀剑。你的仇敌必投降你；你必踏在他们的高处。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '申命记', 5, 34, 1, '摩西从摩押平原登尼波山，上了那与耶利哥相对的毘斯迦山顶。耶和华把基列全地直到但，'),
('CUV', '申命记', 5, 34, 2, '拿弗他利全地，以法莲、玛拿西的地，犹大全地直到西海，'),
('CUV', '申命记', 5, 34, 3, '南地和棕树城耶利哥的平原，直到琐珥，都指给他看。'),
('CUV', '申命记', 5, 34, 4, '耶和华对他说：这就是我向亚伯拉罕、以撒、雅各起誓应许之地，说：我必将这地赐给你的后裔。现在我使你眼睛看见了，你却不得过到那里去。'),
('CUV', '申命记', 5, 34, 5, '于是，耶和华的仆人摩西死在摩押地，正如耶和华所说的。'),
('CUV', '申命记', 5, 34, 6, '耶和华将他埋葬在摩押地、伯毘珥对面的谷中，只是到今日没有人知道他的坟墓。'),
('CUV', '申命记', 5, 34, 7, '摩西死的时候年一百二十岁；眼目没有昏花，精神没有衰败。'),
('CUV', '申命记', 5, 34, 8, '以色列人在摩押平原为摩西哀哭了三十日，为摩西居丧哀哭的日子就满了。'),
('CUV', '申命记', 5, 34, 9, '嫩的儿子约书亚；因为摩西曾按手在他头上，就被智慧的灵充满，以色列人便听从他，照著耶和华吩咐摩西的行了。'),
('CUV', '申命记', 5, 34, 10, '以后以色列中再没有兴起先知像摩西的。他是耶和华面对面所认识的。'),
('CUV', '申命记', 5, 34, 11, '耶和华打发他在埃及地向法老和他的一切臣仆，并他的全地，行各样神迹奇事，'),
('CUV', '申命记', 5, 34, 12, '又在以色列.众人眼前显大能的手，行一切大而可畏的事。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 1, 1, '耶和华的仆人摩西死了以后，耶和华晓谕摩西的帮手，嫩的儿子约书亚，说：'),
('CUV', '约书亚记', 6, 1, 2, '我的仆人摩西死了。现在你要起来，和众百姓过这约但河，往我所要赐给以色列人的地去。'),
('CUV', '约书亚记', 6, 1, 3, '凡你们脚掌所踏之地，我都照著我所应许摩西的话赐给你们了。'),
('CUV', '约书亚记', 6, 1, 4, '从旷野和这利巴嫩，直到伯拉大河，赫人的全地，又到大海日落之处，都要作你们的境界。'),
('CUV', '约书亚记', 6, 1, 5, '你平生的日子，必无一人能在你面前站立得住。我怎样与摩西同在，也必照样与你同在；我必不撇下你，也不丢弃你。'),
('CUV', '约书亚记', 6, 1, 6, '你当刚强壮胆！因为你必使这百姓承受那地为业，就是我向他们列祖起誓应许赐给他们的地。'),
('CUV', '约书亚记', 6, 1, 7, '只要刚强，大大壮胆，谨守遵行我仆人摩西所吩咐你的一切律法，不可偏离左右，使你无论往那里去，都可以顺利。'),
('CUV', '约书亚记', 6, 1, 8, '这律法书不可离开你的口，总要昼夜思想，好使你谨守遵行这书上所写的一切话。如此，你的道路就可以亨通，凡事顺利。'),
('CUV', '约书亚记', 6, 1, 9, '我岂没有吩咐你么？你当刚强壮胆！不要惧怕，也不要惊惶；因为你无论往那里去，耶和华─你的神必与你同在。'),
('CUV', '约书亚记', 6, 1, 10, '于是，约书亚吩咐百姓的官长说：'),
('CUV', '约书亚记', 6, 1, 11, '你们要走遍营中，吩咐百姓说：当预备食物；因为三日之内你们要过这约但河，进去得耶和华─你们神赐你们为业之地。'),
('CUV', '约书亚记', 6, 1, 12, '约书亚对流便人、迦得人，和玛拿西半支派的人说：'),
('CUV', '约书亚记', 6, 1, 13, '你们要追念耶和华的仆人摩西所吩咐你们的话说：耶和华─你们的神使你们得享平安，也必将这地赐给你们。'),
('CUV', '约书亚记', 6, 1, 14, '你们的妻子、孩子，和牲畜都可以留在约但河东、摩西所给你们的地；但你们中间一切大能的勇士都要带著兵器在你们的弟兄前面过去，帮助他们，'),
('CUV', '约书亚记', 6, 1, 15, '等到耶和华使你们的弟兄像你们一样得享平安，并且得著耶和华─你们神所赐他们为业之地，那时才可以回你们所得之地，承受为业，就是耶和华的仆人摩西在约但河东、向日出之地所给你们的。'),
('CUV', '约书亚记', 6, 1, 16, '他们回答约书亚说：你所吩咐我们行的，我们都必行；你所差遣我们去的，我们都必去。'),
('CUV', '约书亚记', 6, 1, 17, '我们从前在一切事上怎样听从摩西，现在也必照样听从你；惟愿耶和华─你的神与你同在，像与摩西同在一样。'),
('CUV', '约书亚记', 6, 1, 18, '无论甚么人违背你的命令，不听从你所吩咐他的一切话，就必治死他。你只要刚强壮胆！')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 2, 1, '当下，嫩的儿子约书亚从什亭暗暗打发两个人作探子，吩咐说：你们去窥探那地和耶利哥。于是二人去了，来到一个妓女名叫喇合的家里，就在那里躺卧。'),
('CUV', '约书亚记', 6, 2, 2, '有人告诉耶利哥王说：今夜有以色列人来到这里窥探此地。'),
('CUV', '约书亚记', 6, 2, 3, '耶利哥王打发人去见喇合说：那来到你这里、进了你家的人要交出来，因为他们来窥探全地。'),
('CUV', '约书亚记', 6, 2, 4, '女人将二人隐藏，就回答说：那人果然到我这里来；他们是那里来的我却不知道。'),
('CUV', '约书亚记', 6, 2, 5, '天黑、要关城门的时候，他们出去了，往那里去我却不知道。你们快快的去追赶，就必追上。'),
('CUV', '约书亚记', 6, 2, 6, '（先是女人领二人上了房顶，将他们藏在那里所摆的麻中。）'),
('CUV', '约书亚记', 6, 2, 7, '那些人就往约但河的渡口追赶他们去了。追赶他们的人一出去，城门就关了。'),
('CUV', '约书亚记', 6, 2, 8, '二人还没有躺卧，女人就上房顶，到他们那里，'),
('CUV', '约书亚记', 6, 2, 9, '对他们说：我知道耶和华已经把这地赐给你们，并且因你们的缘故我们都惊慌了。这地的一切居民在你们面前心都消化了；'),
('CUV', '约书亚记', 6, 2, 10, '因为我们听见你们出埃及的时候，耶和华怎样在你们前面使红海的水干了，并且你们怎样待约但河东的两个亚摩利王西宏和噩，将他们尽行毁灭。'),
('CUV', '约书亚记', 6, 2, 11, '我们一听见这些事，心就消化了。因你们的缘故，并无一人有胆气。耶和华─你们的神本是上天下地的神。'),
('CUV', '约书亚记', 6, 2, 12, '现在我既是恩待你们，求你们指著耶和华向我起誓，也要恩待我父家，并给我一个实在的证据，'),
('CUV', '约书亚记', 6, 2, 13, '要救活我的父母、弟兄、姊妹，和一切属他们的，拯救我们性命不死。'),
('CUV', '约书亚记', 6, 2, 14, '二人对他说：你若不泄漏我们这件事，我们情愿替你们死。耶和华将这地赐给我们的时候，我们必以慈爱诚实待你。'),
('CUV', '约书亚记', 6, 2, 15, '于是女人用绳子将二人从窗户里缒下去；因他的房子是在城墙边上，他也住在城墙上。'),
('CUV', '约书亚记', 6, 2, 16, '他对他们说：你们且往山上去，恐怕追赶的人碰见你们；要在那里隐藏三天，等追赶的人回来，然后才可以走你们的路。'),
('CUV', '约书亚记', 6, 2, 17, '二人对他说：你要这样行。不然，你叫我们所起的誓就与我们无干了。'),
('CUV', '约书亚记', 6, 2, 18, '我们来到这地的时候，你要把这条朱红线绳系在缒我们下去的窗户上，并要使你的父母、弟兄，和你父的全家都聚集在你家中。'),
('CUV', '约书亚记', 6, 2, 19, '凡出了你家门往街上去的，他的罪（原文是血）必归到自己的头上，与我们无干了。凡在你家里的，若有人下手害他，流他血的罪就归到我们的头上。'),
('CUV', '约书亚记', 6, 2, 20, '你若泄漏我们这件事，你叫我们所起的誓就与我们无干了。'),
('CUV', '约书亚记', 6, 2, 21, '女人说：照你们的话行罢！于是打发他们去了，又把朱红线绳系在窗户上。'),
('CUV', '约书亚记', 6, 2, 22, '二人到山上，在那里住了三天，等著追赶的人回去了。追赶的人一路找他们，却找不著。'),
('CUV', '约书亚记', 6, 2, 23, '二人就下山回来，过了河，到嫩的儿子约书亚那里，向他述说所遭遇的一切事；'),
('CUV', '约书亚记', 6, 2, 24, '又对约书亚说：耶和华果然将那全地交在我们手中；那地的一切居民在我们面前心都消化了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 3, 1, '约书亚清早起来，和以色列众人都离开什亭，来到约但河，就住在那里，等候过河。'),
('CUV', '约书亚记', 6, 3, 2, '过了三天，官长走遍营中，'),
('CUV', '约书亚记', 6, 3, 3, '吩咐百姓说：你们看见耶和华─你们神的约柜，又见祭司利未人抬著，就要离开所住的地方，跟著约柜去。'),
('CUV', '约书亚记', 6, 3, 4, '只是你们和约柜相离要量二千肘，不可与约柜相近，使你们知道所当走的路，因为这条路你们向来没有走过。'),
('CUV', '约书亚记', 6, 3, 5, '约书亚吩咐百姓说：你们要自洁，因为明天耶和华必在你们中间行奇事。'),
('CUV', '约书亚记', 6, 3, 6, '约书亚又吩咐祭司说：你们抬起约柜，在百姓前头过去。于是他们抬起约柜，在百姓前头走。'),
('CUV', '约书亚记', 6, 3, 7, '耶和华对约书亚说：从今日起，我必使你在以色列众人眼前尊大，使他们知道我怎样与摩西同在，也必照样与你同在。'),
('CUV', '约书亚记', 6, 3, 8, '你要吩咐抬约柜的祭司说：你们到了约但河的水边上，就要在约但河水里站住。'),
('CUV', '约书亚记', 6, 3, 9, '约书亚对以色列人说：你们近前来，听耶和华─你们神的话。'),
('CUV', '约书亚记', 6, 3, 10, '约书亚说：看哪，普天下主的约柜必在你们前头过去，到约但河里，因此你们就知道在你们中间有永生神；并且他必在你们面前赶出迦南人、赫人、希未人、比利洗人、革迦撒人、亚摩利人、耶布斯人。'),
('CUV', '约书亚记', 6, 3, 11, 'a'),
('CUV', '约书亚记', 6, 3, 12, '你们现在要从以色列支派中拣选十二个人，每支派一人，'),
('CUV', '约书亚记', 6, 3, 13, '等到抬普天下主耶和华约柜的祭司把脚站在约但河水里，约但河的水，就是从上往下流的水，必然断绝，立起成垒。'),
('CUV', '约书亚记', 6, 3, 14, '百姓离开帐棚要过约但河的时候，抬约柜的祭司乃在百姓的前头。'),
('CUV', '约书亚记', 6, 3, 15, '他们到了约但河，脚一入水（原来约但河水在收割的日子涨过两岸），'),
('CUV', '约书亚记', 6, 3, 16, '那从上往下流的水便在极远之地、撒拉但旁的亚当城那里停住，立起成垒；那往亚拉巴的海，就是盐海，下流的水全然断绝。于是百姓在耶利哥的对面过去了。'),
('CUV', '约书亚记', 6, 3, 17, '抬耶和华约柜的祭司在约但河中的干地上站定，以色列众人都从干地上过去，直到国民尽都过了约但河。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 4, 1, '国民尽都过了约但河，耶和华就对约书亚说：'),
('CUV', '约书亚记', 6, 4, 2, '你从民中要拣选十二个人，每支派一人，'),
('CUV', '约书亚记', 6, 4, 3, '吩咐他们说：你们从这里，从约但河中、祭司脚站定的地方，取十二块石头带过去，放在你们今夜要住宿的地方。'),
('CUV', '约书亚记', 6, 4, 4, '于是，约书亚将他从以色列人中所预备的那十二个人，每支派一人，都召了来。'),
('CUV', '约书亚记', 6, 4, 5, '对他们说：你们下约但河中，过到耶和华─你们神的约柜前头，按著以色列人十二支派的数目，每人取一块石头扛在肩上。'),
('CUV', '约书亚记', 6, 4, 6, '这些石头在你们中间可以作为证据。日后，你们的子孙问你们说：这些石头是甚么意思？'),
('CUV', '约书亚记', 6, 4, 7, '你们就对他们说：这是因为约但河的水在耶和华的约柜前断绝；约柜过约但河的时候，约但河的水就断绝了。这些石头要作以色列人永远的纪念。'),
('CUV', '约书亚记', 6, 4, 8, '以色列人就照约书亚所吩咐的，按著以色列人支派的数目，从约但河中取了十二块石头，都遵耶和华所吩咐约书亚的行了。他们把石头带过去，到他们所住宿的地方，就放在那里。'),
('CUV', '约书亚记', 6, 4, 9, '约书亚另把十二块石头立在约但河中，在抬约柜的祭司脚站立的地方；直到今日，那石头还在那里。'),
('CUV', '约书亚记', 6, 4, 10, '抬约柜的祭司站在约但河中，等到耶和华晓谕约书亚吩咐百姓的事办完了，是照摩西所吩咐约书亚的一切话。于是百姓急速过去了。'),
('CUV', '约书亚记', 6, 4, 11, '众百姓尽都过了河，耶和华的约柜和祭司就在百姓面前过去。'),
('CUV', '约书亚记', 6, 4, 12, '流便人、迦得人、玛拿西半支派的人都照摩西所吩咐他们的，带著兵器在以色列人前头过去。'),
('CUV', '约书亚记', 6, 4, 13, '约有四万人都准备打仗，在耶和华面前过去，到耶利哥的平原，等候上阵。'),
('CUV', '约书亚记', 6, 4, 14, '当那日，耶和华使约书亚在以色列众人眼前尊大。在他平生的日子，百姓敬畏他，像从前敬畏摩西一样。'),
('CUV', '约书亚记', 6, 4, 15, '耶和华晓谕约书亚说：'),
('CUV', '约书亚记', 6, 4, 16, '你吩咐抬法柜的祭司从约但河里上来。'),
('CUV', '约书亚记', 6, 4, 17, '约书亚就吩咐祭司说：你们从约但河里上来。'),
('CUV', '约书亚记', 6, 4, 18, '抬耶和华约柜的祭司从约但河里上来，脚掌刚落旱地，约但河的水就流到原处，仍旧涨过两岸。'),
('CUV', '约书亚记', 6, 4, 19, '正月初十日，百姓从约但河里上来，就在吉甲，在耶利哥的东边安营。'),
('CUV', '约书亚记', 6, 4, 20, '他们从约但河中取来的那十二块石头，约书亚就立在吉甲，'),
('CUV', '约书亚记', 6, 4, 21, '对以色列人说：日后你们的子孙问他们的父亲说：这些石头是甚么意思？'),
('CUV', '约书亚记', 6, 4, 22, '你们就告诉他们说：以色列人曾走干地过这约但河；'),
('CUV', '约书亚记', 6, 4, 23, '因为耶和华─你们的神在你们前面使约但河的水干了，等著你们过来，就如耶和华─你们的神从前在我们前面使红海干了，等著我们过来一样，'),
('CUV', '约书亚记', 6, 4, 24, '要使地上万民都知道，耶和华的手大有能力，也要使你们永远敬畏耶和华─你们的神。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 5, 1, '约但河西亚摩利人的诸王和靠海迦南人的诸王，听见耶和华在以色列人前面使约但河的水干了，等到我们过去，他们的心因以色列人的缘故就消化了，不再有胆气。'),
('CUV', '约书亚记', 6, 5, 2, '那时，耶和华吩咐约书亚说：你制造火石刀，第二次给以色列人行割礼。'),
('CUV', '约书亚记', 6, 5, 3, '约书亚就制造了火石刀，在除皮山那里给以色列人行割礼。'),
('CUV', '约书亚记', 6, 5, 4, '约书亚行割礼的缘故，是因为从埃及出来的众民，就是一切能打仗的男丁，出了埃及以后，都死在旷野的路上。'),
('CUV', '约书亚记', 6, 5, 5, '因为出来的众民都受过割礼；惟独出埃及以后、在旷野的路上所生的众民都没有受过割礼。'),
('CUV', '约书亚记', 6, 5, 6, '以色列人在旷野走了四十年，等到国民，就是出埃及的兵丁，都消灭了，因为他们没有听从耶和华的话。耶和华曾向他们起誓，必不容他们看见耶和华向他们列祖起誓、应许赐给我们的地，就是流奶与蜜之地。'),
('CUV', '约书亚记', 6, 5, 7, '他们的子孙，就是耶和华所兴起来接续他们的，都没有受过割礼；因为在路上没有给他们行割礼，约书亚这才给他们行了。'),
('CUV', '约书亚记', 6, 5, 8, '国民都受完了割礼，就住在营中自己的地方，等到痊愈了。'),
('CUV', '约书亚记', 6, 5, 9, '耶和华对约书亚说：我今日将埃及的羞辱从你们身上辊去了。因此，那地方名叫吉甲（吉甲就是辊的意思），直到今日。'),
('CUV', '约书亚记', 6, 5, 10, '以色列人在吉甲安营。正月十四日晚上，在耶利哥的平原守逾越节。'),
('CUV', '约书亚记', 6, 5, 11, '逾越节的次日，他们就吃了那地的出产；正当那日吃无酵饼和烘的谷。'),
('CUV', '约书亚记', 6, 5, 12, '他们吃了那地的出产，第二日吗哪就止住了，以色列人也不再有吗哪了。那一年，他们却吃迦南地的出产。'),
('CUV', '约书亚记', 6, 5, 13, '约书亚靠近耶利哥的时候，举目观看，不料，有一个人手里有拔出来的刀，对面站立。约书亚到他那里，问他说：你是帮助我们呢，是帮助我们敌人呢？'),
('CUV', '约书亚记', 6, 5, 14, '他回答说：不是的，我来是要作耶和华军队的元帅。约书亚就俯伏在地下拜，说：我主有甚么话吩咐仆人。'),
('CUV', '约书亚记', 6, 5, 15, '耶和华军队的元帅对约书亚说：把你脚上的鞋脱下来，因为你所站的地方是圣的。约书亚就照著行了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 6, 1, '耶利哥的城门因以色列人就关得严紧，无人出入。'),
('CUV', '约书亚记', 6, 6, 2, '耶和华晓谕约书亚说：看哪，我已经把耶利哥和耶利哥的王，并大能的勇士，都交在你手中。'),
('CUV', '约书亚记', 6, 6, 3, '你们的一切兵丁要围绕这城，一日围绕一次，六日都要这样行。'),
('CUV', '约书亚记', 6, 6, 4, '七个祭司要拿七个羊角走在约柜前。到第七日，你们要绕城七次，祭司也要吹角。'),
('CUV', '约书亚记', 6, 6, 5, '他们吹的角声拖长，你们听见角声，众百姓要大声呼喊，城墙就必塌陷，各人都要往前直上。'),
('CUV', '约书亚记', 6, 6, 6, '嫩的儿子约书亚召了祭司来，吩咐他们说：你们抬起约柜来，要有七个祭司拿七个羊角走在耶和华的约柜前；'),
('CUV', '约书亚记', 6, 6, 7, '又对百姓说：你们前去绕城，带兵器的要走在耶和华的约柜前。'),
('CUV', '约书亚记', 6, 6, 8, '约书亚对百姓说完了话，七个祭司拿七个羊角走在耶和华面前吹角；耶和华的约柜在他们后面跟随。'),
('CUV', '约书亚记', 6, 6, 9, '带兵器的走在吹角的祭司前面，后队随著约柜行。祭司一面走一面吹。'),
('CUV', '约书亚记', 6, 6, 10, '约书亚吩咐百姓说：你们不可呼喊，不可出声，连一句话也不可出你们的口，等到我吩咐你们呼喊的日子，那时才可以呼喊。'),
('CUV', '约书亚记', 6, 6, 11, '这样，他使耶和华的约柜绕城，把城绕了一次；众人回到营里，就在营里住宿。'),
('CUV', '约书亚记', 6, 6, 12, '约书亚清早起来，祭司又抬起耶和华的约柜。'),
('CUV', '约书亚记', 6, 6, 13, '七个祭司拿七个羊角在耶和华的约柜前，时常行走吹角；带兵器的在他们前面走，后队随著耶和华的约柜行。祭司一面走一面吹。'),
('CUV', '约书亚记', 6, 6, 14, '第二日，众人把城绕了一次，就回营里去。六日都是这样行。'),
('CUV', '约书亚记', 6, 6, 15, '第七日清早，黎明的时候，他们起来，照样绕城七次；惟独这日把城绕了七次。'),
('CUV', '约书亚记', 6, 6, 16, '到了第七次，祭司吹角的时候，约书亚吩咐百姓说：呼喊罢，因为耶和华已经把城交给你们了！'),
('CUV', '约书亚记', 6, 6, 17, '这城和其中所有的都要在耶和华面前毁灭；只有妓女喇合与他家中所有的可以存活，因为他隐藏了我们所打发的使者。'),
('CUV', '约书亚记', 6, 6, 18, '至于你们，务要谨慎，不可取那当灭的物，恐怕你们取了那当灭的物就连累以色列的全营，使全营受咒诅。'),
('CUV', '约书亚记', 6, 6, 19, '惟有金子、银子，和铜铁的器皿都要归耶和华为圣，必入耶和华的库中。'),
('CUV', '约书亚记', 6, 6, 20, '于是百姓呼喊，祭司也吹角。百姓听见角声，便大声呼喊，城墙就塌陷，百姓便上去进城，各人往前直上，将城夺取。'),
('CUV', '约书亚记', 6, 6, 21, '又将城中所有的，不拘男女老少，牛羊和驴，都用刀杀尽。'),
('CUV', '约书亚记', 6, 6, 22, '约书亚吩咐窥探地的两个人说：你们进那妓女的家，照著你们向他所起的誓，将那女人和他所有的都从那里带出来。'),
('CUV', '约书亚记', 6, 6, 23, '当探子的两个少年人就进去，将喇合与他的父母、弟兄，和他所有的，并他一切的亲眷，都带出来，安置在以色列的营外。'),
('CUV', '约书亚记', 6, 6, 24, '众人就用火将城和其中所有的焚烧了；惟有金子、银子，和铜铁的器皿都放在耶和华殿的库中。'),
('CUV', '约书亚记', 6, 6, 25, '约书亚却把妓女喇合与他父家，并他所有的，都救活了；因为他隐藏了约书亚所打发窥探耶利哥的使者，他就住在以色列中，直到今日。'),
('CUV', '约书亚记', 6, 6, 26, '当时，约书亚叫众人起誓说：有兴起重修这耶利哥城的人，当在耶和华面前受咒诅。他立根基的时候，必丧长子，安门的时候，必丧幼子。'),
('CUV', '约书亚记', 6, 6, 27, '耶和华与约书亚同在，约书亚的声名传扬遍地。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 7, 1, '以色列人在当灭的物上犯了罪；因为犹大支派中，谢拉的曾孙，撒底的孙子，迦米的儿子亚干取了当灭的物；耶和华的怒气就向以色列人发作。'),
('CUV', '约书亚记', 6, 7, 2, '当下，约书亚从耶利哥打发人往伯特利东边、靠近伯亚文的艾城去，吩咐他们说：你们上去窥探那地。他们就上去窥探艾城。'),
('CUV', '约书亚记', 6, 7, 3, '他们回到约书亚那里，对他说：众民不必都上去，只要二三千人上去就能攻取艾城；不必劳累众民都去，因为那里的人少。'),
('CUV', '约书亚记', 6, 7, 4, '于是民中约有三千人上那里去，竟在艾城人面前逃跑了。'),
('CUV', '约书亚记', 6, 7, 5, '艾城的人击杀了他们三十六人，从城门前追赶他们，直到示巴琳，在下坡杀败他们；众民的心就消化如水。'),
('CUV', '约书亚记', 6, 7, 6, '约书亚便撕裂衣服；他和以色列的长老把灰撒在头上，在耶和华的约柜前俯伏在地，直到晚上。'),
('CUV', '约书亚记', 6, 7, 7, '约书亚说：哀哉！主耶和华阿，你为甚么竟领这百姓过约但河，将我们交在亚摩利人的手中，使我们灭亡呢？我们不如住在约但河那边倒好。'),
('CUV', '约书亚记', 6, 7, 8, '主阿，以色列人既在仇敌面前转背逃跑，我还有甚么可说的呢？'),
('CUV', '约书亚记', 6, 7, 9, '迦南人和这地一切的居民听见了就必围困我们，将我们的名从地上除灭。那时你为你的大名要怎样行呢？'),
('CUV', '约书亚记', 6, 7, 10, '耶和华吩咐约书亚说：起来！你为何这样俯伏在地呢？'),
('CUV', '约书亚记', 6, 7, 11, '以色列人犯了罪，违背了我所吩咐他们的约，取了当灭的物；又偷窃，又行诡诈，又把那当灭的放在他们的家具里。'),
('CUV', '约书亚记', 6, 7, 12, '因此，以色列人在仇敌面前站立不住。他们在仇敌面前转背逃跑，是因成了被咒诅的；你们若不把当灭的物从你们中间除掉，我就不再与你们同在了。'),
('CUV', '约书亚记', 6, 7, 13, '你起来，叫百姓自洁，对他们说：你们要自洁，预备明天，因为耶和华─以色列的神这样说：以色列阿，你们中间有当灭的物，你们若不除掉，在仇敌面前必站立不住！'),
('CUV', '约书亚记', 6, 7, 14, '到了早晨，你们要按著支派近前来；耶和华所取的支派，要按著宗族近前来；耶和华所取的宗族，要按著家室近前来；耶和华所取的家室，要按著人丁，一个一个的近前来。'),
('CUV', '约书亚记', 6, 7, 15, '被取的人有当灭的物在他那里，他和他所有的必被火焚烧；因他违背了耶和华的约，又因他在以色列中行了愚妄的事。'),
('CUV', '约书亚记', 6, 7, 16, '于是，约书亚清早起来，使以色列人按著支派近前来，取出来的是犹大支派；'),
('CUV', '约书亚记', 6, 7, 17, '使犹大支派（原文是宗族）近前来，就取了谢拉的宗族；使谢拉的宗族，按著家室人丁，一个一个的近前来，取出来的是撒底；'),
('CUV', '约书亚记', 6, 7, 18, '使撒底的家室，按著人丁，一个一个的近前来，就取出犹大支派的人谢拉的曾孙，撒底的孙子，迦米的儿子亚干。'),
('CUV', '约书亚记', 6, 7, 19, '约书亚对亚干说：我儿，我劝你将荣耀归给耶和华─以色列的神，在他面前认罪，将你所做的事告诉我，不要向我隐瞒。'),
('CUV', '约书亚记', 6, 7, 20, '亚干回答约书亚说：我实在得罪了耶和华─以色列的神。我所做的事如此如此：'),
('CUV', '约书亚记', 6, 7, 21, '我在所夺的财物中看见一件美好的示拿衣服，二百舍客勒银子，一条金子重五十舍客勒，我就贪爱这些物件，便拿去了。现今藏在我帐棚内的地里，银子在衣服底下。'),
('CUV', '约书亚记', 6, 7, 22, '约书亚就打发人跑到亚干的帐棚里。那件衣服果然藏在他帐棚内，银子在底下。'),
('CUV', '约书亚记', 6, 7, 23, '他们就从帐棚里取出来，拿到约书亚和以色列众人那里，放在耶和华面前。'),
('CUV', '约书亚记', 6, 7, 24, '约书亚和以色列众人把谢拉的曾孙亚干和那银子、那件衣服、那条金子，并亚干的儿女、牛、驴、羊、帐棚，以及他所有的，都带到亚割谷去。'),
('CUV', '约书亚记', 6, 7, 25, '约书亚说：你为甚么连累我们呢？今日耶和华必叫你受连累。于是以色列众人用石头打死他，将石头扔在其上，又用火焚烧他所有的（他所有的原文作他们）。'),
('CUV', '约书亚记', 6, 7, 26, '众人在亚干身上堆成一大堆石头，直存到今日。于是耶和华转意，不发他的烈怒。因此那地方名叫亚割谷（亚割就是连累的意思），直到今日。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 8, 1, '耶和华对约书亚说：不要惧怕，也不要惊惶。你起来，率领一切兵丁上艾城去，我已经把艾城的王和他的民、他的城，并他的地，都交在你手里。'),
('CUV', '约书亚记', 6, 8, 2, '你怎样待耶利哥和耶利哥的王，也当照样待艾城和艾城的王。只是城内所夺的财物和牲畜，你们可以取为自己的掠物。你要在城后设下伏兵。'),
('CUV', '约书亚记', 6, 8, 3, '于是，约书亚和一切兵丁都起来，要上艾城去。约书亚选了三万大能的勇士，夜间打发他们前往，'),
('CUV', '约书亚记', 6, 8, 4, '吩咐他们说：你们要在城后埋伏，不可离城太远，都要各自准备。'),
('CUV', '约书亚记', 6, 8, 5, '我与我所带领的众民要向城前往。城里的人像初次出来攻击我们的时候，我们就在他们面前逃跑，'),
('CUV', '约书亚记', 6, 8, 6, '他们必出来追赶我们，直到我们引诱他们离开城；因为他们必说：这些人像初次在我们面前逃跑。所以我们要在他们面前逃跑，'),
('CUV', '约书亚记', 6, 8, 7, '你们就从埋伏的地方起来，夺取那城，因为耶和华─你们的神必把城交在你们手里。'),
('CUV', '约书亚记', 6, 8, 8, '你们夺了城以后，就放火烧城，要照耶和华的话行。这是我吩咐你们的。'),
('CUV', '约书亚记', 6, 8, 9, '约书亚打发他们前往，他们就上埋伏的地方去，住在伯特利和艾城的中间，就是在艾城的西边。这夜约书亚却在民中住宿。'),
('CUV', '约书亚记', 6, 8, 10, '约书亚清早起来，点齐百姓，他和以色列的长老在百姓前面上艾城去。'),
('CUV', '约书亚记', 6, 8, 11, '众民，就是他所带领的兵丁，都上去，向前直往，来到城前，在艾城北边安营。在约书亚和艾城中间有一山谷。'),
('CUV', '约书亚记', 6, 8, 12, '他挑了约有五千人，使他们埋伏在伯特利和艾城的中间，就是在艾城的西边，'),
('CUV', '约书亚记', 6, 8, 13, '于是安置了百姓，就是城北的全军和城西的伏兵。这夜约书亚进入山谷之中。'),
('CUV', '约书亚记', 6, 8, 14, '艾城的王看见这景况，就和全城的人，清早急忙起来，按所定的时候，出到亚拉巴前，要与以色列人交战；王却不知道在城后有伏兵。'),
('CUV', '约书亚记', 6, 8, 15, '约书亚和以色列众人在他们面前装败，往那通旷野的路逃跑。'),
('CUV', '约书亚记', 6, 8, 16, '城内的众民都被招聚，追赶他们；艾城人追赶的时候，就被引诱离开城。'),
('CUV', '约书亚记', 6, 8, 17, '艾城和伯特利城没有一人不出来追赶以色列人的，撇了敞开的城门，去追赶以色列人。'),
('CUV', '约书亚记', 6, 8, 18, '耶和华吩咐约书亚说：你向艾城伸出手里的短鎗，因为我要将城交在你手里。约书亚就向城伸出手里的短鎗。'),
('CUV', '约书亚记', 6, 8, 19, '他一伸手，伏兵就从埋伏的地方急忙起来，夺了城，跑进城去，放火焚烧。'),
('CUV', '约书亚记', 6, 8, 20, '艾城的人回头一看，不料，城中烟气冲天，他们就无力向左向右逃跑。那往旷野逃跑的百姓便转身攻击追赶他们的人。'),
('CUV', '约书亚记', 6, 8, 21, '约书亚和以色列众人见伏兵已经夺了城，城中烟气飞腾，就转身回去，击杀艾城的人。'),
('CUV', '约书亚记', 6, 8, 22, '伏兵也出城迎击艾城人，艾城人就困在以色列人中间，前后都是以色列人。于是以色列人击杀他们，没有留下一个，也没有一个逃脱的，'),
('CUV', '约书亚记', 6, 8, 23, '生擒了艾城的王，将他解到约书亚那里。'),
('CUV', '约书亚记', 6, 8, 24, '以色列人在田间和旷野杀尽所追赶一切艾城的居民。艾城人倒在刀下，直到灭尽；以色列众人就回到艾城，用刀杀了城中的人。'),
('CUV', '约书亚记', 6, 8, 25, '当日杀毙的人，连男带女共有一万二千，就是艾城所有的人。'),
('CUV', '约书亚记', 6, 8, 26, '约书亚没有收回手里所伸出来的短鎗，直到把艾城的一切居民尽行杀灭。'),
('CUV', '约书亚记', 6, 8, 27, '惟独城中的牲畜和财物，以色列人都取为自己的掠物，是照耶和华所吩咐约书亚的话。'),
('CUV', '约书亚记', 6, 8, 28, '约书亚将艾城焚烧，使城永为高堆、荒场，直到今日；'),
('CUV', '约书亚记', 6, 8, 29, '又将艾城王挂在树上，直到晚上。日落的时候，约书亚吩咐人把尸首从树上取下来，丢在城门口，在尸首上堆成一大堆石头，直存到今日。'),
('CUV', '约书亚记', 6, 8, 30, '那时，约书亚在以巴路山上为耶和华─以色列的神筑一座坛，'),
('CUV', '约书亚记', 6, 8, 31, '是用没有动过铁器的整石头筑的，照著耶和华仆人摩西所吩咐以色列人的话，正如摩西律法书上所写的。众人在这坛上给耶和华奉献燔祭和平安祭。'),
('CUV', '约书亚记', 6, 8, 32, '约书亚在那里，当著以色列人面前，将摩西所写的律法抄写在石头上。'),
('CUV', '约书亚记', 6, 8, 33, '以色列众人，无论是本地人、是寄居的，和长老、官长，并审判官，都站在约柜两旁，在抬耶和华约柜的祭司利未人面前，一半对著基利心山，一半对著以巴路山，为以色列民祝福，正如耶和华仆人摩西先前所吩咐的。'),
('CUV', '约书亚记', 6, 8, 34, '随后，约书亚将律法上祝福、咒诅的话，照著律法书上一切所写的，都宣读了一遍。'),
('CUV', '约书亚记', 6, 8, 35, '摩西所吩咐的一切话，约书亚在以色列全会众和妇女、孩子，并他们中间寄居的外人面前，没有一句不宣读的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 9, 1, '约但河西，住山地、高原，并对著利巴嫩山沿大海一带的诸王，就是赫人、亚摩利人、迦南人、比利洗人、希未人、耶布斯人的诸王，听见这事，'),
('CUV', '约书亚记', 6, 9, 2, '就都聚集，同心合意的要与约书亚和以色列人争战。'),
('CUV', '约书亚记', 6, 9, 3, '基遍的居民听见约书亚向耶利哥和艾城所行的事，'),
('CUV', '约书亚记', 6, 9, 4, '就设诡计，假充使者，拿旧口袋和破裂缝补的旧皮酒袋驮在驴上，'),
('CUV', '约书亚记', 6, 9, 5, '将补过的旧鞋穿在脚上，把旧衣服穿在身上；他们所带的饼都是干的，长了霉了。'),
('CUV', '约书亚记', 6, 9, 6, '他们到吉甲营中见约书亚，对他和以色列人说：我们是从远方来的，现在求你与我们立约。'),
('CUV', '约书亚记', 6, 9, 7, '以色列人对这些希未人说：只怕你们是住在我们中间的；若是这样，怎能和你们立约呢？'),
('CUV', '约书亚记', 6, 9, 8, '他们对约书亚说：我们是你的仆人。约书亚问他们说：你们是甚么人？是从那里来的？'),
('CUV', '约书亚记', 6, 9, 9, '他们回答说：仆人从极远之地而来，是因听见耶和华─你神的名声和他在埃及所行的一切事，'),
('CUV', '约书亚记', 6, 9, 10, '并他向约但河东的两个亚摩利王，就是希实本王西宏和在亚斯他录的巴珊王噩一切所行的事。'),
('CUV', '约书亚记', 6, 9, 11, '我们的长老和我们那地的一切居民对我们说：你们手里要带著路上用的食物去迎接以色列人，对他们说：我们是你们的仆人；现在求你们与我们立约。'),
('CUV', '约书亚记', 6, 9, 12, '我们出来要往你们这里来的日子，从家里带出来的这饼还是热的；看哪，现在都干了，长了霉了。'),
('CUV', '约书亚记', 6, 9, 13, '这皮酒袋，我们盛酒的时候还是新的；看哪，现在已经破裂。我们这衣服和鞋，因为道路甚远，也都穿旧了。'),
('CUV', '约书亚记', 6, 9, 14, '以色列人受了他们些食物，并没有求问耶和华。'),
('CUV', '约书亚记', 6, 9, 15, '于是约书亚与他们讲和，与他们立约，容他们活著；会众的首领也向他们起誓。'),
('CUV', '约书亚记', 6, 9, 16, '以色列人与他们立约之后，过了三天才听见他们是近邻，住在以色列人中间的。'),
('CUV', '约书亚记', 6, 9, 17, '以色列人起行，第三天到了他们的城邑，就是基遍、基非拉、比录、基列耶琳。'),
('CUV', '约书亚记', 6, 9, 18, '因为会众的首领已经指著耶和华─以色列的神向他们起誓，所以以色列人不击杀他们；全会众就向首领发怨言。'),
('CUV', '约书亚记', 6, 9, 19, '众首领对全会众说：我们已经指著耶和华─以色列的神向他们起誓，现在我们不能害他们。'),
('CUV', '约书亚记', 6, 9, 20, '我们要如此待他们，容他们活著，免得有忿怒因我们所起的誓临到我们身上。'),
('CUV', '约书亚记', 6, 9, 21, '首领又对会众说：要容他们活著。于是他们为全会众作了劈柴挑水的人，正如首领对他们所说的话。'),
('CUV', '约书亚记', 6, 9, 22, '约书亚召了他们来，对他们说：为甚么欺哄我们说我们离你们甚远呢？其实你们是住在我们中间。'),
('CUV', '约书亚记', 6, 9, 23, '现在你们是被咒诅的！你们中间的人必断不了作奴仆，为我神的殿作劈柴挑水的人。'),
('CUV', '约书亚记', 6, 9, 24, '他们回答约书亚说：因为有人实在告诉你的仆人，耶和华─你的神曾吩咐他的仆人摩西，把这全地赐给你们，并在你们面前灭绝这地的一切居民，所以我们为你们的缘故甚怕丧命，就行了这事。'),
('CUV', '约书亚记', 6, 9, 25, '现在我们在你手中，你以怎样待我们为善为正，就怎样做罢！'),
('CUV', '约书亚记', 6, 9, 26, '于是约书亚这样待他们，救他们脱离以色列人的手，以色列人就没有杀他们。'),
('CUV', '约书亚记', 6, 9, 27, '当日约书亚使他们在耶和华所要选择的地方，为会众和耶和华的坛作劈柴挑水的人，直到今日。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 10, 1, '耶路撒冷王亚多尼洗德听见约书亚夺了艾城，尽行毁灭，怎样待耶利哥和耶利哥的王，也照样待艾城和艾城的王，又听见基遍的居民与以色列人立了和约，住在他们中间，'),
('CUV', '约书亚记', 6, 10, 2, '就甚惧怕；因为基遍是一座大城，如都城一般，比艾城更大，并且城内的人都是勇士。'),
('CUV', '约书亚记', 6, 10, 3, '所以耶路撒冷王亚多尼洗德打发人去见希伯仑王何咸、耶末王毘兰、拉吉王雅非亚，和伊矶伦王底璧，说：'),
('CUV', '约书亚记', 6, 10, 4, '求你们上来帮助我，我们好攻打基遍，因为他们与约书亚和以色列人立了和约。'),
('CUV', '约书亚记', 6, 10, 5, '于是五个亚摩利王，就是耶路撒冷王、希伯仑王、耶末王、拉吉王、伊矶伦王，大家聚集，率领他们的众军上去，对著基遍安营，攻打基遍。'),
('CUV', '约书亚记', 6, 10, 6, '基遍人就打发人往吉甲的营中去见约书亚，说：你不要袖手不顾你的仆人，求你速速上来拯救我们，帮助我们，因为住山地亚摩利人的诸王都聚集攻击我们。'),
('CUV', '约书亚记', 6, 10, 7, '于是约书亚和他一切兵丁，并大能的勇士，都从吉甲上去。'),
('CUV', '约书亚记', 6, 10, 8, '耶和华对约书亚说：不要怕他们；因为我已将他们交在你手里，他们无一人能在你面前站立得住。'),
('CUV', '约书亚记', 6, 10, 9, '约书亚就终夜从吉甲上去，猛然临到他们那里。'),
('CUV', '约书亚记', 6, 10, 10, '耶和华使他们在以色列人面前溃乱。约书亚在基遍大大的杀败他们，追赶他们，在伯和仑的上坡路击杀他们，直到亚西加和玛基大。'),
('CUV', '约书亚记', 6, 10, 11, '他们在以色列人面前逃跑，正在伯和仑下坡的时候，耶和华从天上降大冰雹在他们身上，（冰雹原文作石头）直降到亚西加，打死他们。被冰雹打死的，比以色列人用刀杀死的还多。'),
('CUV', '约书亚记', 6, 10, 12, '当耶和华将亚摩利人交付以色列人的日子，约书亚就祷告耶和华，在以色列人眼前说：日头阿，你要停在基遍；月亮阿，你要止在亚雅仑谷。'),
('CUV', '约书亚记', 6, 10, 13, '于是日头停留，月亮止住，直等国民向敌人报仇。这事岂不是写在雅煞珥书上么？日头在天当中停住，不急速下落，约有一日之久。'),
('CUV', '约书亚记', 6, 10, 14, '在这日以前，这日以后，耶和华听人的祷告，没有像这日的，是因耶和华为以色列争战。'),
('CUV', '约书亚记', 6, 10, 15, '约书亚和以色列众人回到吉甲的营中。'),
('CUV', '约书亚记', 6, 10, 16, '那五王逃跑，藏在玛基大洞里。'),
('CUV', '约书亚记', 6, 10, 17, '有人告诉约书亚说：那五王已经找到了，都藏在玛基大洞里。'),
('CUV', '约书亚记', 6, 10, 18, '约书亚说：你们把几块大石头辊到洞口，派人看守，'),
('CUV', '约书亚记', 6, 10, 19, '你们却不可耽延，要追赶你们的仇敌，击杀他们尽后边的人，不容他们进自己的城邑，因为耶和华─你们的神已经把他们交在你们手里。'),
('CUV', '约书亚记', 6, 10, 20, '约书亚和以色列人大大杀败他们，直到将他们灭尽；其中剩下的人都进了坚固的城。'),
('CUV', '约书亚记', 6, 10, 21, '众百姓就安然回玛基大营中，到约书亚那里。没有一人敢向以色列人饶舌。'),
('CUV', '约书亚记', 6, 10, 22, '约书亚说：打开洞口，将那五王从洞里带出来，领到我面前。'),
('CUV', '约书亚记', 6, 10, 23, '众人就这样行，将那五王，就是耶路撒冷王、希伯仑王、耶末王、拉吉王、伊矶伦王，从洞里带出来，领到约书亚面前。'),
('CUV', '约书亚记', 6, 10, 24, '带出那五王到约书亚面前的时候，约书亚就召了以色列众人来，对那些和他同去的军长说：你们近前来，把脚踏在这些王的颈项上。他们就近前来，把脚踏在这些王的颈项上。'),
('CUV', '约书亚记', 6, 10, 25, '约书亚对他们说：你们不要惧怕，也不要惊惶。应当刚强壮胆，因为耶和华必这样待你们所要攻打的一切仇敌。'),
('CUV', '约书亚记', 6, 10, 26, '随后约书亚将这五王杀死，挂在五棵树上。他们就在树上直挂到晚上。'),
('CUV', '约书亚记', 6, 10, 27, '日头要落的时候，约书亚一吩咐，人就把尸首从树上取下来，丢在他们藏过的洞里，把几块大石头放在洞口，直存到今日。'),
('CUV', '约书亚记', 6, 10, 28, '当日，约书亚夺了玛基大，用刀击杀城中的人和王；将其中一切人口尽行杀灭，没有留下一个。他待玛基大王，像从前待耶利哥王一样。'),
('CUV', '约书亚记', 6, 10, 29, '约书亚和以色列众人从玛基大往立拿去，攻打立拿。'),
('CUV', '约书亚记', 6, 10, 30, '耶和华将立拿和立拿的王也交在以色列人手里。约书亚攻打这城，用刀击杀了城中的一切人口，没有留下一个。他待立拿王，像从前待耶利哥王一样。'),
('CUV', '约书亚记', 6, 10, 31, '约书亚和以色列众人从立拿往拉吉去，对著拉吉安营，攻打这城。'),
('CUV', '约书亚记', 6, 10, 32, '耶和华将拉吉交在以色列人的手里。第二天约书亚就夺了拉吉，用刀击杀了城中的一切人口，是照他向立拿一切所行的。'),
('CUV', '约书亚记', 6, 10, 33, '那时基色王荷兰上来帮助拉吉，约书亚就把他和他的民都击杀了，没有留下一个。'),
('CUV', '约书亚记', 6, 10, 34, '约书亚和以色列众人从拉吉往伊矶伦去，对著伊矶伦安营，攻打这城。'),
('CUV', '约书亚记', 6, 10, 35, '当日就夺了城，用刀击杀了城中的人。那日，约书亚将城中的一切人口尽行杀灭，是照他向拉吉一切所行的。'),
('CUV', '约书亚记', 6, 10, 36, '约书亚和以色列众人从伊矶伦上希伯仑去，攻打这城，'),
('CUV', '约书亚记', 6, 10, 37, '就夺了希伯仑和属希伯仑的诸城邑，用刀将城中的人与王，并那些城邑中的人口，都击杀了，没有留下一个，是照他向伊矶伦所行的，把城中的一切人口尽行杀灭。'),
('CUV', '约书亚记', 6, 10, 38, '约书亚和以色列众人回到底璧，攻打这城，'),
('CUV', '约书亚记', 6, 10, 39, '就夺了底璧和属底璧的城邑，又擒获底璧的王，用刀将这些城中的人口尽行杀灭，没有留下一个。他待底璧和底璧王，像从前待希伯仑和立拿与立拿王一样。'),
('CUV', '约书亚记', 6, 10, 40, '这样，约书亚击杀全地的人，就是山地、南地、高原、山坡的人，和那些地的诸王，没有留下一个。将凡有气息的尽行杀灭，正如耶和华─以色列的神所吩咐的。'),
('CUV', '约书亚记', 6, 10, 41, '约书亚从加低斯巴尼亚攻击到迦萨，又攻击歌珊全地，直到基遍。'),
('CUV', '约书亚记', 6, 10, 42, '约书亚一时杀败了这些王，并夺了他们的地，因为耶和华─以色列的神为以色列争战。'),
('CUV', '约书亚记', 6, 10, 43, '于是约书亚和以色列众人回到吉甲的营中。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 11, 1, '夏琐王耶宾听见这事，就打发人去见玛顿王约巴、伸仑王、押煞王，'),
('CUV', '约书亚记', 6, 11, 2, '与北方山地、基尼烈南边的亚拉巴高原，并西边多珥山冈的诸王；'),
('CUV', '约书亚记', 6, 11, 3, '又去见东方和西方的迦南人，与山地的亚摩利人、赫人、比利洗人、耶布斯人，并黑门山根米斯巴地的希未人。'),
('CUV', '约书亚记', 6, 11, 4, '这些王和他们的众军都出来，人数多如海边的沙，并有许多马匹车辆。'),
('CUV', '约书亚记', 6, 11, 5, '这诸王会合，来到米伦水边，一同安营，要与以色列人争战。'),
('CUV', '约书亚记', 6, 11, 6, '耶和华对约书亚说：你不要因他们惧怕。明日这时，我必将他们交付以色列人全然杀了。你要砍断他们马的蹄筋，用火焚烧他们的车辆。'),
('CUV', '约书亚记', 6, 11, 7, '于是约书亚率领一切兵丁，在米伦水边突然向前攻打他们。'),
('CUV', '约书亚记', 6, 11, 8, '耶和华将他们交在以色列人手里，以色列人就击杀他们，追赶他们到西顿大城，到米斯利弗玛音，直到东边米斯巴的平原，将他们击杀，没有留下一个。'),
('CUV', '约书亚记', 6, 11, 9, '约书亚就照耶和华所吩咐他的去行，砍断他们马的蹄筋，用火焚烧他们的车辆。'),
('CUV', '约书亚记', 6, 11, 10, '当时，约书亚转回夺了夏琐，用刀击杀夏琐王。（素来夏琐在这诸国中是为首的。）'),
('CUV', '约书亚记', 6, 11, 11, '以色列人用刀击杀城中的人口，将他们尽行杀灭；凡有气息的没有留下一个。约书亚又用火焚烧夏琐。'),
('CUV', '约书亚记', 6, 11, 12, '约书亚夺了这些王的一切城邑，擒获其中的诸王，用刀击杀他们，将他们尽行杀灭，正如耶和华仆人摩西所吩咐的。'),
('CUV', '约书亚记', 6, 11, 13, '至于造在山冈上的城，除了夏琐以外，以色列人都没有焚烧。约书亚只将夏琐焚烧了。'),
('CUV', '约书亚记', 6, 11, 14, '那些城邑所有的财物和牲畜，以色列人都取为自己的掠物；惟有一切人口都用刀击杀，直到杀尽；凡有气息的没有留下一个。'),
('CUV', '约书亚记', 6, 11, 15, '耶和华怎样吩咐他仆人摩西，摩西就照样吩咐约书亚，约书亚也照样行。凡耶和华所吩咐摩西的，约书亚没有一件懈怠不行的。'),
('CUV', '约书亚记', 6, 11, 16, '约书亚夺了那全地，就是山地、一带南地、歌珊全地、高原、亚拉巴、以色列的山地，和山下的高原。'),
('CUV', '约书亚记', 6, 11, 17, '从上西珥的哈拉山，直到黑门山下利巴嫩平原的巴力迦得，并且擒获那些地的诸王，将他们杀死。'),
('CUV', '约书亚记', 6, 11, 18, '约书亚和这诸王争战了许多年日。'),
('CUV', '约书亚记', 6, 11, 19, '除了基遍的希未人之外，没有一城与以色列人讲和的，都是以色列人争战夺来的。'),
('CUV', '约书亚记', 6, 11, 20, '因为耶和华的意思是要使他们心里刚硬，来与以色列人争战，好叫他们尽被杀灭，不蒙怜悯，正如耶和华所吩咐摩西的。'),
('CUV', '约书亚记', 6, 11, 21, '当时约书亚来到，将住山地、希伯仑、底璧、亚拿伯、犹大山地、以色列山地所有的亚衲族人剪除了。约书亚将他们和他们的城邑尽都毁灭。'),
('CUV', '约书亚记', 6, 11, 22, '在以色列人的地没有留下一个亚衲族人，只在迦萨、迦特，和亚实突有留下的。'),
('CUV', '约书亚记', 6, 11, 23, '这样，约书亚照著耶和华所吩咐摩西的一切话夺了那全地，就按著以色列支派的宗族将地分给他们为业。于是国中太平，没有争战了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 12, 1, '以色列人在约但河外向日出之地击杀二王，得他们的地，就是从亚嫩谷直到黑门山，并东边的全亚拉巴之地。'),
('CUV', '约书亚记', 6, 12, 2, '这二王，有住希实本、亚摩利人的王西宏。他所管之地是从亚嫩谷边的亚罗珥和谷中的城，并基列一半，直到亚扪人的境界，雅博河'),
('CUV', '约书亚记', 6, 12, 3, '与约但河东边的亚拉巴，直到基尼烈海，又到亚拉巴的海，就是盐海，通伯耶西末的路，以及南方，直到毘斯迦的山根。'),
('CUV', '约书亚记', 6, 12, 4, '又有巴珊王噩。他是利乏音人所剩下的，住在亚斯他录和以得来。'),
('CUV', '约书亚记', 6, 12, 5, '他所管之地是黑门山、撒迦、巴珊全地，直到基述人和玛迦人的境界，并基列一半，直到希实本王西宏的境界。'),
('CUV', '约书亚记', 6, 12, 6, '这二王是耶和华仆人摩西和以色列人所击杀的；耶和华仆人摩西将他们的地赐给流便人、迦得人，和玛拿西半支派的人为业。'),
('CUV', '约书亚记', 6, 12, 7, '约书亚和以色列人在约但河西击杀了诸王。他们的地是从利巴嫩平原的巴力迦得，直到上西珥的哈拉山。约书亚就将那地按著以色列支派的宗族分给他们为业，'),
('CUV', '约书亚记', 6, 12, 8, '就是赫人、亚摩利人，迦南人、比利洗人、希未人、耶布斯人的山地、高原亚拉巴、山坡、旷野，和南地。'),
('CUV', '约书亚记', 6, 12, 9, '他们的王：一个是耶利哥王，一个是靠近伯特利的艾城王，'),
('CUV', '约书亚记', 6, 12, 10, '一个是耶路撒冷王，一个是希伯仑王，'),
('CUV', '约书亚记', 6, 12, 11, '一个是耶末王，一个是拉吉王，'),
('CUV', '约书亚记', 6, 12, 12, '一个是伊矶伦王，一个是基色王，'),
('CUV', '约书亚记', 6, 12, 13, '一个是底璧王，一个是基德王，'),
('CUV', '约书亚记', 6, 12, 14, '一个是何珥玛王，一个是亚拉得王，'),
('CUV', '约书亚记', 6, 12, 15, '一个是立拿王，一个是亚杜兰王，'),
('CUV', '约书亚记', 6, 12, 16, '一个是玛基大王，一个是伯特利王，'),
('CUV', '约书亚记', 6, 12, 17, '一个是他普亚王，一个是希弗王，'),
('CUV', '约书亚记', 6, 12, 18, '一个是亚弗王，一个是拉沙仑王，'),
('CUV', '约书亚记', 6, 12, 19, '一个是玛顿王，一个是夏琐王，'),
('CUV', '约书亚记', 6, 12, 20, '一个是伸仑米仑王，一个是押煞王，'),
('CUV', '约书亚记', 6, 12, 21, '一个是他纳王，一个是米吉多王，'),
('CUV', '约书亚记', 6, 12, 22, '一个是基低斯王，一个是靠近迦密的约念王，'),
('CUV', '约书亚记', 6, 12, 23, '一个是多珥山冈的多珥王，一个是吉甲的戈印王，'),
('CUV', '约书亚记', 6, 12, 24, '一个是得撒王；共计三十一个王。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 13, 1, '约书亚年纪老迈，耶和华对他说：你年纪老迈了，还有许多未得之地，'),
('CUV', '约书亚记', 6, 13, 2, '就是非利士人的全境和基述人的全地。'),
('CUV', '约书亚记', 6, 13, 3, '从埃及前的西曷河往北，直到以革伦的境界，就算属迦南人之地。有非利士人五个首领所管的迦萨人、亚实突人、亚实基伦人、迦特人、以革伦人之地，并有南方亚卫人之地。'),
('CUV', '约书亚记', 6, 13, 4, '又有迦南人的全地，并属西顿人的米亚拉到亚弗，直到亚摩利人的境界。'),
('CUV', '约书亚记', 6, 13, 5, '还有迦巴勒人之地，并向日出的全利巴嫩，就是从黑门山根的巴力迦得，直到哈马口。'),
('CUV', '约书亚记', 6, 13, 6, '山地的一切居民，从利巴嫩直到米斯利弗玛音，就是所有的西顿人，我必在以色列人面前赶出他们去。你只管照我所吩咐的，将这地拈阄分给以色列人为业。'),
('CUV', '约书亚记', 6, 13, 7, '现在你要把这地分给九个支派和玛拿西半个支派为业。'),
('CUV', '约书亚记', 6, 13, 8, '玛拿西那半支派和流便、迦得二支派已经受了产业，就是耶和华的仆人摩西在约但河东所赐给他们的：'),
('CUV', '约书亚记', 6, 13, 9, '是从亚嫩谷边的亚罗珥和谷中的城，并米底巴的全平原，直到底本，'),
('CUV', '约书亚记', 6, 13, 10, '和在希实本作王亚摩利王西宏的诸城，直到亚扪人的境界；'),
('CUV', '约书亚记', 6, 13, 11, '又有基列地、基述人、玛迦人的地界，并黑门全山、巴珊全地，直到撒迦；'),
('CUV', '约书亚记', 6, 13, 12, '又有巴珊王噩的全国─他在亚斯他录和以得来作王（利乏音人所存留的只剩下他）。这些地的人都是摩西所击杀、所赶逐的。'),
('CUV', '约书亚记', 6, 13, 13, '以色列人却没有赶逐基述人、玛迦人；这些人仍住在以色列中，直到今日。'),
('CUV', '约书亚记', 6, 13, 14, '只是利未支派，摩西（原文作他）没有把产业分给他们。他们的产业乃是献与耶和华─以色列神的火祭，正如耶和华所应许他们的。'),
('CUV', '约书亚记', 6, 13, 15, '摩西按著流便支派的宗族分给他们产业。'),
('CUV', '约书亚记', 6, 13, 16, '他们的境界是亚嫩谷边的亚罗珥和谷中的城，靠近米底巴的全平原；'),
('CUV', '约书亚记', 6, 13, 17, '希实本并属希实本平原的各城，底本、巴末巴力、伯巴力勉、'),
('CUV', '约书亚记', 6, 13, 18, '雅杂、基底莫、米法押、'),
('CUV', '约书亚记', 6, 13, 19, '基列亭、西比玛、谷中山的细列哈沙辖、'),
('CUV', '约书亚记', 6, 13, 20, '伯毘珥、毘斯迦山坡、伯耶西末；'),
('CUV', '约书亚记', 6, 13, 21, '平原的各城，并亚摩利王西宏的全国。这西宏曾在希实本作王，摩西把他和米甸的族长以未、利金、苏珥、户珥、利巴击杀了；这都是住那地属西宏为首领的。'),
('CUV', '约书亚记', 6, 13, 22, '那时以色列人在所杀的人中，也用刀杀了比珥的儿子术士巴兰。'),
('CUV', '约书亚记', 6, 13, 23, '流便人的境界就是约但河与靠近约但河的地。以上是流便人按著宗族所得为业的诸城，并属城的村庄。'),
('CUV', '约书亚记', 6, 13, 24, '摩西按著迦得支派的宗族分给他们产业。'),
('CUV', '约书亚记', 6, 13, 25, '他们的境界是雅谢和基列的各城，并亚扪人的一半地，直到拉巴前的亚罗珥；'),
('CUV', '约书亚记', 6, 13, 26, '从希实本到拉抹米斯巴和比多宁，又从玛哈念到底璧的境界，'),
('CUV', '约书亚记', 6, 13, 27, '并谷中的伯亚兰、伯宁拉、疏割、撒分，就是希实本王西宏国中的余地，以及约但河与靠近约但河的地，直到基尼烈海的极边，都在约但河东。'),
('CUV', '约书亚记', 6, 13, 28, '以上是迦得人按著宗族所得为业的诸城，并属城的村庄。'),
('CUV', '约书亚记', 6, 13, 29, '摩西把产业分给玛拿西半支派，是按著玛拿西半支派的宗族所分的。'),
('CUV', '约书亚记', 6, 13, 30, '他们的境界是从玛哈念起，包括巴珊全地，就是巴珊王噩的全国，并在巴珊、睚珥的一切城邑，共六十个。'),
('CUV', '约书亚记', 6, 13, 31, '基列的一半，并亚斯他录、以得来，就是属巴珊王噩国的二城，是按著宗族给玛拿西的儿子玛吉的一半子孙。'),
('CUV', '约书亚记', 6, 13, 32, '以上是摩西在约但河东对著耶利哥的摩押平原所分给他们的产业。'),
('CUV', '约书亚记', 6, 13, 33, '只是利未支派，摩西没有把产业分给他们。耶和华─以色列的神是他们的产业，正如耶和华所应许他们的。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 14, 1, '以色列人在迦南地所得的产业，就是祭司以利亚撒和嫩的儿子约书亚，并以色列各支派的族长所分给他们的，都记在下面，'),
('CUV', '约书亚记', 6, 14, 2, '是照耶和华藉摩西所吩咐的，把产业拈阄分给九个半支派。'),
('CUV', '约书亚记', 6, 14, 3, '原来，摩西在约但河东已经把产业分给那两个半支派，只是在他们中间没有把产业分给利未人。'),
('CUV', '约书亚记', 6, 14, 4, '因为约瑟的子孙是两个支派，就是玛拿西和以法莲，所以没有把地分给利未人，但给他们城邑居住，并城邑的郊野，可以牧养他们的牲畜，安置他们的财物。'),
('CUV', '约书亚记', 6, 14, 5, '耶和华怎样吩咐摩西，以色列人就照样行，把地分了。'),
('CUV', '约书亚记', 6, 14, 6, '那时，犹大人来到吉甲见约书亚，有基尼洗族耶孚尼的儿子迦勒对约书亚说：耶和华在加低斯巴尼亚指著我与你对神人摩西所说的话，你都知道了。'),
('CUV', '约书亚记', 6, 14, 7, '耶和华的仆人摩西从加低斯巴尼亚打发我窥探这地，那时我正四十岁；我按著心意回报他。'),
('CUV', '约书亚记', 6, 14, 8, '然而，同我上去的众弟兄使百姓的心消化；但我专心跟从耶和华─我的神。'),
('CUV', '约书亚记', 6, 14, 9, '当日摩西起誓说：你脚所踏之地定要归你和你的子孙永远为业，因为你专心跟从耶和华─我的神。'),
('CUV', '约书亚记', 6, 14, 10, '自从耶和华对摩西说这话的时候，耶和华照他所应许的使我存活这四十五年；其间以色列人在旷野行走。看哪，现今我八十五岁了，'),
('CUV', '约书亚记', 6, 14, 11, '我还是强壮，像摩西打发我去的那天一样；无论是争战，是出入，我的力量那时如何，现在还是如何。'),
('CUV', '约书亚记', 6, 14, 12, '求你将耶和华那日应许我的这山地给我；那里有亚衲族人，并宽大坚固的城，你也曾听见了。或者耶和华照他所应许的与我同在，我就把他们赶出去。'),
('CUV', '约书亚记', 6, 14, 13, '于是约书亚为耶孚尼的儿子迦勒祝福，将希伯仑给他为业。'),
('CUV', '约书亚记', 6, 14, 14, '所以希伯仑作了基尼洗族耶孚尼的儿子迦勒的产业，直到今日，因为他专心跟从耶和华─以色列的神。'),
('CUV', '约书亚记', 6, 14, 15, '希伯仑从前名叫基列亚巴；亚巴是亚衲族中最尊大的人。于是国中太平，没有争战了。')
on conflict (version, book, chapter, verse) do nothing;

insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CUV', '约书亚记', 6, 15, 1, '犹大支派按著宗族拈阄所得之地是在尽南边，到以东的交界，向南直到寻的旷野。'),
('CUV', '约书亚记', 6, 15, 2, '他们的南界是从盐海的尽边，就是从朝南的海汊起，'),
('CUV', '约书亚记', 6, 15, 3, '通到亚克拉滨坡的南边，接连到寻，上到加低斯巴尼亚的南边，又过希斯仑，上到亚达珥，绕到甲加，'),
('CUV', '约书亚记', 6, 15, 4, '接连到押们，通到埃及小河，直通到海为止。这就是他们的南界。'),
('CUV', '约书亚记', 6, 15, 5, '东界是从盐海南边到约但河口。北界是从约但河口的海汊起，'),
('CUV', '约书亚记', 6, 15, 6, '上到伯曷拉，过伯亚拉巴的北边，上到流便之子波罕的磐石；'),
('CUV', '约书亚记', 6, 15, 7, '从亚割谷往北，上到底璧，直向河南亚都冥坡对面的吉甲；又接连到隐示麦泉，直通到隐罗结，'),
('CUV', '约书亚记', 6, 15, 8, '上到欣嫩子谷，贴近耶布斯的南界（耶布斯就是耶路撒冷）；又上到欣嫩谷西边的山顶，就是在利乏音谷极北的边界；'),
('CUV', '约书亚记', 6, 15, 9, '又从山顶延到尼弗多亚的水源，通到以弗仑山的城邑，又延到巴拉（巴拉就是基列耶琳）；'),
('CUV', '约书亚记', 6, 15, 10, '又从巴拉往西绕到西珥山，接连到耶琳山的北边（耶琳就是基撒仑）；又下到伯示麦过亭纳，'),
('CUV', '约书亚记', 6, 15, 11, '通到以革伦北边，延到施基仑，接连到巴拉山；又通到雅比聂，直通到海为止。'),
('CUV', '约书亚记', 6, 15, 12, '西界就是大海和靠近大海之地。这是犹大人按著宗族所得之地四围的交界。'),
('CUV', '约书亚记', 6, 15, 13, '约书亚照耶和华所吩咐的，将犹大人中的一段地，就是基列亚巴，分给耶孚尼的儿子迦勒。亚巴是亚衲族的始祖（基列亚巴就是希伯仑）。'),
('CUV', '约书亚记', 6, 15, 14, '迦勒就从那里赶出亚衲族的三个族长，就是示筛、亚希幔、挞买；'),
('CUV', '约书亚记', 6, 15, 15, '又从那里上去，攻击底璧的居民。（这底璧从前名叫基列西弗。）'),
('CUV', '约书亚记', 6, 15, 16, '迦勒说：谁能攻打基列西弗将城夺取，我就把我女儿押撒给他为妻。'),
('CUV', '约书亚记', 6, 15, 17, '迦勒兄弟基纳斯的儿子俄陀聂夺取了那城，迦勒就把女儿押撒给他为妻。'),
('CUV', '约书亚记', 6, 15, 18, '押撒过门的时候，劝丈夫向他父亲求一块田，押撒一下驴，迦勒问他说：你要甚么？'),
('CUV', '约书亚记', 6, 15, 19, '他说：求你赐福给我，你既将我安置在南地，求你也给我水泉。他父亲就把上泉下泉赐给他。'),
('CUV', '约书亚记', 6, 15, 20, '以下是犹大支派按著宗族所得的产业。'),
('CUV', '约书亚记', 6, 15, 21, '犹大支派尽南边的城邑，与以东交界相近的，就是甲薛、以得、雅姑珥、'),
('CUV', '约书亚记', 6, 15, 22, '基拿、底摩拿、亚大达、'),
('CUV', '约书亚记', 6, 15, 23, '基低斯、夏琐、以提楠、'),
('CUV', '约书亚记', 6, 15, 24, '西弗、提炼、比亚绿、'),
('CUV', '约书亚记', 6, 15, 25, '夏琐哈大他、加略希斯仑（加略希斯仑就是夏琐）、'),
('CUV', '约书亚记', 6, 15, 26, '亚曼、示玛、摩拉大、'),
('CUV', '约书亚记', 6, 15, 27, '哈萨迦大、黑实门、伯帕列、'),
('CUV', '约书亚记', 6, 15, 28, '哈萨书亚、别是巴、比斯约他、'),
('CUV', '约书亚记', 6, 15, 29, '巴拉、以因、以森、'),
('CUV', '约书亚记', 6, 15, 30, '伊勒多腊、基失、何珥玛、'),
('CUV', '约书亚记', 6, 15, 31, '洗革拉、麦玛拿、三撒拿、'),
('CUV', '约书亚记', 6, 15, 32, '利巴勿、实忻、亚因、临门，共二十九座城，还有属城的村庄。'),
('CUV', '约书亚记', 6, 15, 33, '在高原有以实陶、琐拉、亚实拿、'),
('CUV', '约书亚记', 6, 15, 34, '撒挪亚、隐干宁、他普亚、以楠、'),
('CUV', '约书亚记', 6, 15, 35, '耶末、亚杜兰、梭哥、亚西加、'),
('CUV', '约书亚记', 6, 15, 36, '沙拉音、亚底他音、基底拉、基底罗他音，共十四座城，还有属城的村庄。'),
('CUV', '约书亚记', 6, 15, 37, '又有洗楠、哈大沙、麦大迦得、'),
('CUV', '约书亚记', 6, 15, 38, '底连、米斯巴、约帖、'),
('CUV', '约书亚记', 6, 15, 39, '拉吉、波斯加、伊矶伦、'),
('CUV', '约书亚记', 6, 15, 40, '迦本、拉幔、基提利、'),
('CUV', '约书亚记', 6, 15, 41, '基低罗、伯大衮、拿玛、玛基大，共十六座城，还有属城的村庄。'),
('CUV', '约书亚记', 6, 15, 42, '又有立拿、以帖、亚珊、'),
('CUV', '约书亚记', 6, 15, 43, '益弗他、亚实拿、尼悉、'),
('CUV', '约书亚记', 6, 15, 44, '基伊拉、亚革悉、玛利沙，共九座城，还有属城的村庄。'),
('CUV', '约书亚记', 6, 15, 45, '又有以革伦和属以革伦的镇市村庄；'),
('CUV', '约书亚记', 6, 15, 46, '从以革伦直到海，一切靠近亚实突之地，并属其地的村庄。'),
('CUV', '约书亚记', 6, 15, 47, '亚实突和属亚实突的镇市村庄；迦萨和属迦萨的镇市村庄；直到埃及小河，并大海和靠近大海之地。'),
('CUV', '约书亚记', 6, 15, 48, '在山地有沙密、雅提珥、梭哥、'),
('CUV', '约书亚记', 6, 15, 49, '大拿、基列萨拿（基列萨拿就是底璧）、'),
('CUV', '约书亚记', 6, 15, 50, '亚拿伯、以实提莫、亚念、'),
('CUV', '约书亚记', 6, 15, 51, '歌珊、何伦、基罗，共十一座城，还有属城的村庄。'),
('CUV', '约书亚记', 6, 15, 52, '又有亚拉、度玛、以珊、'),
('CUV', '约书亚记', 6, 15, 53, '雅农、伯他普亚、亚非加、'),
('CUV', '约书亚记', 6, 15, 54, '宏他、基列亚巴（基列亚巴就是希伯仑）、洗珥，共九座城，还有属城的村庄。'),
('CUV', '约书亚记', 6, 15, 55, '又有玛云、迦密、西弗、淤他、'),
('CUV', '约书亚记', 6, 15, 56, '耶斯列、约甸、撒挪亚、'),
('CUV', '约书亚记', 6, 15, 57, '该隐、基比亚、亭纳，共十座城，还有属城的村庄。'),
('CUV', '约书亚记', 6, 15, 58, '又有哈忽、伯夙、基突、'),
('CUV', '约书亚记', 6, 15, 59, '玛腊、伯亚诺、伊勒提君，共六座城，还有属城的村庄。'),
('CUV', '约书亚记', 6, 15, 60, '又有基列巴力（基列巴力就是基列耶琳）、拉巴，共两座城，还有属城的村庄。'),
('CUV', '约书亚记', 6, 15, 61, '在旷野有伯亚拉巴、密丁、西迦迦、'),
('CUV', '约书亚记', 6, 15, 62, '匿珊、盐城、隐基底，共六座城，还有属城的村庄。'),
('CUV', '约书亚记', 6, 15, 63, '至于住耶路撒冷的耶布斯人，犹大人不能把他们赶出去，耶布斯人却在耶路撒冷与犹大人同住，直到今日。')
on conflict (version, book, chapter, verse) do nothing;
